import sys, os

def read_u16(b, o): return int.from_bytes(b[o:o+2], 'little')
def read_u32(b, o): return int.from_bytes(b[o:o+4], 'little')
def read_i32(b, o): return int.from_bytes(b[o:o+4], 'little', signed=True)

def extract(pixel, mask):
    if mask == 0:
        return 0
    s = 0
    while not (mask >> s) & 1:
        s += 1
    n = bin(mask).count('1')
    v = (pixel & mask) >> s
    m = (1 << n) - 1
    return (v * 255 + m // 2) // m

def process(path):
    out = []
    name = os.path.basename(path)
    data = open(path, 'rb').read()
    out.append(f"== {name}")
    off = read_u32(data, 10)
    hsize = read_u32(data, 14)
    width = read_i32(data, 18)
    height_raw = read_i32(data, 22)
    bpp = read_u16(data, 28)
    comp = read_u32(data, 30)
    colours_used = read_u32(data, 46)
    if comp not in (0, 3):
        out.append(f"error: unsupported compression {comp}")
        return out
    top_down = height_raw < 0
    height = abs(height_raw)
    w = width

    palette = []
    if bpp in (1, 4, 8):
        n = colours_used if colours_used else (1 << bpp)
        poff = 14 + hsize
        for i in range(n):
            b = data[poff + 4*i]
            g = data[poff + 4*i + 1]
            r = data[poff + 4*i + 2]
            palette.append((r, g, b))

    masks = None
    if comp == 3:
        if hsize == 40:
            mo = 14 + 40
            masks = (read_u32(data, mo), read_u32(data, mo+4), read_u32(data, mo+8))
        else:
            masks = (read_u32(data, 14+40), read_u32(data, 14+44), read_u32(data, 14+48))

    row_size = ((bpp * w + 31) // 32) * 4
    ink = [[False]*w for _ in range(height)]

    for row in range(height):
        y = row if top_down else height - 1 - row
        base = off + row * row_size
        if bpp == 1:
            for x in range(w):
                byte = data[base + x // 8]
                idx = (byte >> (7 - x % 8)) & 1
                r, g, b = palette[idx]
                if (299*r + 587*g + 114*b) // 1000 < 128:
                    ink[y][x] = True
        elif bpp == 4:
            for x in range(w):
                byte = data[base + x // 2]
                idx = (byte >> 4) & 0xF if x % 2 == 0 else byte & 0xF
                r, g, b = palette[idx]
                if (299*r + 587*g + 114*b) // 1000 < 128:
                    ink[y][x] = True
        elif bpp == 8:
            for x in range(w):
                idx = data[base + x]
                r, g, b = palette[idx]
                if (299*r + 587*g + 114*b) // 1000 < 128:
                    ink[y][x] = True
        elif bpp == 24:
            for x in range(w):
                o = base + 3*x
                b, g, r = data[o], data[o+1], data[o+2]
                if (299*r + 587*g + 114*b) // 1000 < 128:
                    ink[y][x] = True
        elif bpp == 32:
            rm, gm, bm = masks if comp == 3 else (0xFF0000, 0xFF00, 0xFF)
            for x in range(w):
                o = base + 4*x
                pixel = int.from_bytes(data[o:o+4], 'little')
                r = extract(pixel, rm)
                g = extract(pixel, gm)
                b = extract(pixel, bm)
                if (299*r + 587*g + 114*b) // 1000 < 128:
                    ink[y][x] = True

    total_ink = sum(sum(1 for v in row if v) for row in ink)
    out.append(f"size {w}x{height} bpp {bpp} header {hsize} "
               f"{'top-down' if top_down else 'bottom-up'} ink {total_ink}")

    comp_id = [[-1]*w for _ in range(height)]
    comps = []  # (firstx, firsty, minx, miny, maxx, maxy, count)
    for y in range(height):
        for x in range(w):
            if ink[y][x] and comp_id[y][x] == -1:
                cid = len(comps)
                stack = [(x, y)]
                comp_id[y][x] = cid
                minx = maxx = x
                miny = maxy = y
                count = 0
                while stack:
                    cx, cy = stack.pop()
                    count += 1
                    if cx < minx: minx = cx
                    if cx > maxx: maxx = cx
                    if cy < miny: miny = cy
                    if cy > maxy: maxy = cy
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            nx, ny = cx+dx, cy+dy
                            if 0 <= nx < w and 0 <= ny < height and ink[ny][nx] and comp_id[ny][nx] == -1:
                                comp_id[ny][nx] = cid
                                stack.append((nx, ny))
                comps.append((x, y, minx, miny, maxx, maxy, count))

    out.append(f"components {len(comps)}")
    for fx, fy, minx, miny, maxx, maxy, count in comps:
        out.append(f"{fx},{fy} bbox {minx},{miny}-{maxx},{maxy} pixels {count}")
    return out

def main():
    d = sys.argv[1]
    files = sorted(f for f in os.listdir(d) if f.endswith('.bmp'))
    lines = []
    for f in files:
        lines.extend(process(os.path.join(d, f)))
    sys.stdout.write("\n".join(lines) + ("\n" if lines else ""))

main()

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static int u16(byte[] b, int o) { return (b[o] & 0xFF) | ((b[o+1] & 0xFF) << 8); }
    static int u32(byte[] b, int o) { return (b[o] & 0xFF) | ((b[o+1] & 0xFF) << 8) | ((b[o+2] & 0xFF) << 16) | ((b[o+3] & 0xFF) << 24); }

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles();
        Arrays.sort(files, (f1, f2) -> {
            byte[] a1 = f1.getName().getBytes(StandardCharsets.UTF_8);
            byte[] a2 = f2.getName().getBytes(StandardCharsets.UTF_8);
            int n = Math.min(a1.length, a2.length);
            for (int i = 0; i < n; i++) {
                int c = (a1[i] & 0xFF) - (a2[i] & 0xFF);
                if (c != 0) return c;
            }
            return a1.length - a2.length;
        });
        for (File f : files) {
            if (!f.getName().endsWith(".bmp")) continue;
            process(f);
        }
    }

    static void process(File f) throws IOException {
        byte[] b = Files.readAllBytes(f.toPath());
        System.out.println("== " + f.getName());
        int compression = u32(b, 30);
        if (compression != 0 && compression != 3) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }
        int hs = u32(b, 14);
        int width = u32(b, 18);
        int heightRaw = u32(b, 22);
        boolean bottomUp = heightRaw > 0;
        int height = Math.abs(heightRaw);
        int bpp = u16(b, 28);
        int coloursUsed = u32(b, 46);
        int bfOffBits = u32(b, 10);
        int w = width, h = height;

        int[] palR = null, palG = null, palB = null;
        if (bpp <= 8) {
            int n = coloursUsed != 0 ? coloursUsed : (1 << bpp);
            int off = 14 + hs;
            palR = new int[n]; palG = new int[n]; palB = new int[n];
            for (int i = 0; i < n; i++) {
                palB[i] = b[off + 4*i] & 0xFF;
                palG[i] = b[off + 4*i + 1] & 0xFF;
                palR[i] = b[off + 4*i + 2] & 0xFF;
            }
        }

        int redMask = 0, greenMask = 0, blueMask = 0;
        if (bpp == 32 && compression == 3) {
            if (hs == 40) {
                redMask = u32(b, 54); greenMask = u32(b, 58); blueMask = u32(b, 62);
            } else {
                redMask = u32(b, 14 + 40); greenMask = u32(b, 14 + 44); blueMask = u32(b, 14 + 48);
            }
        }

        boolean[][] ink = new boolean[h][w];
        int rowSize = ((bpp * w + 31) / 32) * 4;
        int inkCount = 0;

        for (int r = 0; r < h; r++) {
            int y = bottomUp ? h - 1 - r : r;
            int rowOff = bfOffBits + r * rowSize;
            for (int x = 0; x < w; x++) {
                int R = 0, G = 0, B = 0;
                if (bpp == 1) {
                    int idx = (b[rowOff + x/8] >> (7 - (x & 7))) & 1;
                    R = palR[idx]; G = palG[idx]; B = palB[idx];
                } else if (bpp == 4) {
                    int idx = (b[rowOff + x/2] >> ((x & 1) == 0 ? 4 : 0)) & 0xF;
                    R = palR[idx]; G = palG[idx]; B = palB[idx];
                } else if (bpp == 8) {
                    int idx = b[rowOff + x] & 0xFF;
                    R = palR[idx]; G = palG[idx]; B = palB[idx];
                } else if (bpp == 24) {
                    B = b[rowOff + 3*x] & 0xFF;
                    G = b[rowOff + 3*x + 1] & 0xFF;
                    R = b[rowOff + 3*x + 2] & 0xFF;
                } else { // 32
                    if (compression == 0) {
                        B = b[rowOff + 4*x] & 0xFF;
                        G = b[rowOff + 4*x + 1] & 0xFF;
                        R = b[rowOff + 4*x + 2] & 0xFF;
                    } else {
                        int pixel = u32(b, rowOff + 4*x);
                        R = extract(pixel, redMask);
                        G = extract(pixel, greenMask);
                        B = extract(pixel, blueMask);
                    }
                }
                if ((299 * R + 587 * G + 114 * B) / 1000 < 128) {
                    ink[y][x] = true;
                    inkCount++;
                }
            }
        }

        System.out.println("size " + w + "x" + h + " bpp " + bpp + " header " + hs + " " + (bottomUp ? "bottom-up" : "top-down") + " ink " + inkCount);

        boolean[][] visited = new boolean[h][w];
        List<String> lines = new ArrayList<>();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (ink[y][x] && !visited[y][x]) {
                    int count = 0;
                    int minx = x, maxx = x, miny = y, maxy = y;
                    ArrayDeque<int[]> queue = new ArrayDeque<>();
                    visited[y][x] = true;
                    queue.add(new int[]{x, y});
                    while (!queue.isEmpty()) {
                        int[] p = queue.poll();
                        count++;
                        if (p[0] < minx) minx = p[0];
                        if (p[0] > maxx) maxx = p[0];
                        if (p[1] < miny) miny = p[1];
                        if (p[1] > maxy) maxy = p[1];
                        for (int dy = -1; dy <= 1; dy++) {
                            for (int dx = -1; dx <= 1; dx++) {
                                if (dx == 0 && dy == 0) continue;
                                int nx = p[0] + dx, ny = p[1] + dy;
                                if (nx >= 0 && nx < w && ny >= 0 && ny < h && ink[ny][nx] && !visited[ny][nx]) {
                                    visited[ny][nx] = true;
                                    queue.add(new int[]{nx, ny});
                                }
                            }
                        }
                    }
                    lines.add(x + "," + y + " bbox " + minx + "," + miny + "-" + maxx + "," + maxy + " pixels " + count);
                }
            }
        }
        System.out.println("components " + lines.size());
        for (String line : lines) System.out.println(line);
    }

    static int extract(int pixel, int mask) {
        if (mask == 0) return 0;
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        int m = (1 << n) - 1;
        int v = (pixel & mask) >>> s;
        return (v * 255 + m / 2) / m;
    }
}

import * as fs from 'fs';
import * as path from 'path';

interface Decoded {
  w: number; h: number; bpp: number; header: number; order: string;
  ink: Uint8Array;
}
type DecodeResult = Decoded | { error: number };

function popcount(x: number): number {
  let c = 0;
  while (x) { x &= x - 1; c++; }
  return c;
}

function extract(pixel: number, mask: number): number {
  const s = 0;
  let m = mask;
  let s2 = 0;
  while ((m & 1) === 0) { m >>>= 1; s2++; }
  const n = popcount(mask);
  const max = (1 << n) - 1;
  const v = (pixel & mask) >>> s2;
  return Math.floor((v * 255 + Math.floor(max / 2)) / max);
}

function decodeBMP(buf: Buffer): DecodeResult {
  const dibOff = 14;
  const dibSize = buf.readUInt32LE(dibOff);
  const compression = buf.readUInt32LE(dibOff + 16);
  if (compression !== 0 && compression !== 3) return { error: compression };
  const w = buf.readInt32LE(dibOff + 4);
  const hRaw = buf.readInt32LE(dibOff + 8);
  const bpp = buf.readUInt16LE(dibOff + 14);
  const bottomUp = hRaw > 0;
  const h = Math.abs(hRaw);
  const off = buf.readUInt32LE(10);
  const rowSize = Math.floor((bpp * w + 31) / 32) * 4;

  let palette: Uint8Array | null = null;
  if (bpp <= 8) {
    const coloursUsed = buf.readUInt32LE(dibOff + 32);
    const n = coloursUsed || (1 << bpp);
    palette = buf.subarray(dibOff + dibSize, dibOff + dibSize + n * 4);
  }

  let rMask = 0, gMask = 0, bMask = 0;
  if (bpp === 32 && compression === 3) {
    // masks follow the first 40 bytes of the DIB header in both cases
    rMask = buf.readUInt32LE(dibOff + 40);
    gMask = buf.readUInt32LE(dibOff + 44);
    bMask = buf.readUInt32LE(dibOff + 48);
  }

  const ink = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    const row = bottomUp ? h - 1 - y : y;
    const base = off + row * rowSize;
    for (let x = 0; x < w; x++) {
      let R = 0, G = 0, B = 0;
      if (bpp === 8) {
        const i = buf[base + x];
        B = palette![i * 4]; G = palette![i * 4 + 1]; R = palette![i * 4 + 2];
      } else if (bpp === 4) {
        const b = buf[base + (x >> 1)];
        const i = (x & 1) ? (b & 15) : (b >> 4);
        B = palette![i * 4]; G = palette![i * 4 + 1]; R = palette![i * 4 + 2];
      } else if (bpp === 1) {
        const b = buf[base + (x >> 3)];
        const i = (b >> (7 - (x & 7))) & 1;
        B = palette![i * 4]; G = palette![i * 4 + 1]; R = palette![i * 4 + 2];
      } else if (bpp === 24) {
        B = buf[base + x * 3]; G = buf[base + x * 3 + 1]; R = buf[base + x * 3 + 2];
      } else { // 32
        const p = buf.readUInt32LE(base + x * 4);
        if (compression === 3) {
          R = extract(p, rMask); G = extract(p, gMask); B = extract(p, bMask);
        } else {
          B = p & 255; G = (p >>> 8) & 255; R = (p >>> 16) & 255;
        }
      }
      if (Math.floor((299 * R + 587 * G + 114 * B) / 1000) < 128) ink[y * w + x] = 1;
    }
  }
  return { w, h, bpp, header: dibSize, order: bottomUp ? 'bottom-up' : 'top-down', ink };
}

function main(): void {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.bmp')).sort();
  for (const f of files) {
    console.log(`== ${f}`);
    const buf = fs.readFileSync(path.join(dir, f));
    const d = decodeBMP(buf);
    if ('error' in d) {
      console.log(`error: unsupported compression ${d.error}`);
      continue;
    }
    const { w, h, bpp, header, order, ink } = d;
    let inkCount = 0;
    for (let i = 0; i < ink.length; i++) inkCount += ink[i];
    console.log(`size ${w}x${h} bpp ${bpp} header ${header} ${order} ink ${inkCount}`);

    const visited = new Uint8Array(w * h);
    const lines: string[] = [];
    for (let start = 0; start < w * h; start++) {
      if (!ink[start] || visited[start]) continue;
      visited[start] = 1;
      let minx = w, miny = h, maxx = 0, maxy = 0, cnt = 0;
      const stack: number[] = [start];
      while (stack.length) {
        const cur = stack.pop()!;
        const cx = cur % w, cy = (cur / w) | 0;
        cnt++;
        if (cx < minx) minx = cx;
        if (cx > maxx) maxx = cx;
        if (cy < miny) miny = cy;
        if (cy > maxy) maxy = cy;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const nx = cx + dx, ny = cy + dy;
            if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
            const ni = ny * w + nx;
            if (ink[ni] && !visited[ni]) {
              visited[ni] = 1;
              stack.push(ni);
            }
          }
        }
      }
      const sx = start % w, sy = (start / w) | 0;
      lines.push(`${sx},${sy} bbox ${minx},${miny}-${maxx},${maxy} pixels ${cnt}`);
    }
    console.log(`components ${lines.length}`);
    for (const line of lines) console.log(line);
  }
}

main();

use std::collections::VecDeque;
use std::env;
use std::fs;

fn u16le(b: &[u8], o: usize) -> u16 {
    u16::from_le_bytes([b[o], b[o + 1]])
}
fn u32le(b: &[u8], o: usize) -> u32 {
    u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}
fn i32le(b: &[u8], o: usize) -> i32 {
    i32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}

fn is_ink(r: u32, g: u32, b: u32) -> bool {
    (299 * r + 587 * g + 114 * b) / 1000 < 128
}

fn process(name: &str, data: &[u8], out: &mut String) {
    out.push_str(&format!("== {}\n", name));
    let comp = u32le(data, 14 + 16);
    if comp != 0 && comp != 3 {
        out.push_str(&format!("error: unsupported compression {}\n", comp));
        return;
    }
    let dib_size = u32le(data, 14) as usize;
    let width = i32le(data, 14 + 4) as usize;
    let height_raw = i32le(data, 14 + 8);
    let bottom_up = height_raw > 0;
    let height = height_raw.unsigned_abs() as usize;
    let bpp = u16le(data, 14 + 14) as usize;
    let off_bits = u32le(data, 10) as usize;
    let colours_used = u32le(data, 14 + 32) as usize;

    // masks for 32bpp BI_BITFIELDS
    let (rmask, gmask, bmask) = if bpp == 32 && comp == 3 {
        if dib_size == 40 {
            (
                u32le(data, 14 + 40),
                u32le(data, 14 + 44),
                u32le(data, 14 + 48),
            )
        } else {
            (
                u32le(data, 14 + 40),
                u32le(data, 14 + 44),
                u32le(data, 14 + 48),
            )
        }
    } else {
        (0, 0, 0)
    };

    let stride = (width * bpp + 31) / 32 * 4;
    let palette_start = 14 + dib_size;
    let pal_count = if colours_used == 0 {
        1usize << bpp
    } else {
        colours_used
    };
    // precompute palette ink for indexed modes
    let mut pal_ink = vec![false; pal_count];
    if bpp <= 8 {
        for i in 0..pal_count {
            let o = palette_start + 4 * i;
            let b = data[o] as u32;
            let g = data[o + 1] as u32;
            let r = data[o + 2] as u32;
            pal_ink[i] = is_ink(r, g, b);
        }
    }

    let mut ink = vec![false; width * height];
    for row in 0..height {
        let y = if bottom_up { height - 1 - row } else { row };
        let ro = off_bits + row * stride;
        for x in 0..width {
            let v = match bpp {
                1 => {
                    let idx = ((data[ro + x / 8] >> (7 - x % 8)) & 1) as usize;
                    pal_ink[idx]
                }
                4 => {
                    let byte = data[ro + x / 2];
                    let idx = if x % 2 == 0 {
                        (byte >> 4) as usize
                    } else {
                        (byte & 0xF) as usize
                    };
                    pal_ink[idx]
                }
                8 => pal_ink[data[ro + x] as usize],
                24 => {
                    let o = ro + 3 * x;
                    let b = data[o] as u32;
                    let g = data[o + 1] as u32;
                    let r = data[o + 2] as u32;
                    is_ink(r, g, b)
                }
                32 => {
                    if comp == 0 {
                        let o = ro + 4 * x;
                        let b = data[o] as u32;
                        let g = data[o + 1] as u32;
                        let r = data[o + 2] as u32;
                        is_ink(r, g, b)
                    } else {
                        let pixel = u32le(data, ro + 4 * x);
                        let mut vals = [0u32; 3];
                        for (mi, mask) in [rmask, gmask, bmask].iter().enumerate() {
                            let s = mask.trailing_zeros();
                            let n = mask.count_ones();
                            let m = (1u32 << n) - 1;
                            let v = (pixel & mask) >> s;
                            vals[mi] = (v * 255 + m / 2) / m;
                        }
                        is_ink(vals[0], vals[1], vals[2])
                    }
                }
                _ => false,
            };
            ink[y * width + x] = v;
        }
    }

    let total_ink = ink.iter().filter(|&&v| v).count();
    out.push_str(&format!(
        "size {}x{} bpp {} header {} {} ink {}\n",
        width,
        height,
        bpp,
        dib_size,
        if bottom_up { "bottom-up" } else { "top-down" },
        total_ink
    ));

    let mut visited = vec![false; width * height];
    let mut comps: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();
    // (first x, first y, minx, miny, maxx, maxy, count)
    for y in 0..height {
        for x in 0..width {
            if !ink[y * width + x] || visited[y * width + x] {
                continue;
            }
            let fx = x;
            let fy = y;
            let mut minx = x;
            let mut maxx = x;
            let mut miny = y;
            let mut maxy = y;
            let mut count = 0usize;
            let mut q = VecDeque::new();
            visited[y * width + x] = true;
            q.push_back((x, y));
            while let Some((cx, cy)) = q.pop_front() {
                count += 1;
                if cx < minx {
                    minx = cx;
                }
                if cx > maxx {
                    maxx = cx;
                }
                if cy < miny {
                    miny = cy;
                }
                if cy > maxy {
                    maxy = cy;
                }
                for dy in -1i64..=1 {
                    for dx in -1i64..=1 {
                        if dx == 0 && dy == 0 {
                            continue;
                        }
                        let nx = cx as i64 + dx;
                        let ny = cy as i64 + dy;
                        if nx < 0 || ny < 0 || nx >= width as i64 || ny >= height as i64 {
                            continue;
                        }
                        let nx = nx as usize;
                        let ny = ny as usize;
                        if ink[ny * width + nx] && !visited[ny * width + nx] {
                            visited[ny * width + nx] = true;
                            q.push_back((nx, ny));
                        }
                    }
                }
            }
            comps.push((fx, fy, minx, miny, maxx, maxy, count));
        }
    }

    out.push_str(&format!("components {}\n", comps.len()));
    for c in &comps {
        out.push_str(&format!(
            "{},{} bbox {},{}-{},{} pixels {}\n",
            c.0, c.1, c.2, c.3, c.4, c.5, c.6
        ));
    }
}

