use std::collections::VecDeque;
use std::env;
use std::fs;
use std::io::Read;

fn u16le(b: &[u8], o: usize) -> u16 {
    u16::from_le_bytes([b[o], b[o + 1]])
}
fn u32le(b: &[u8], o: usize) -> u32 {
    u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}
fn i32le(b: &[u8], o: usize) -> i32 {
    i32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}

fn is_ink(r: u32, g: u32, b: u32) -> bool {
    (299 * r + 587 * g + 114 * b) / 1000 < 128
}

fn process(name: &str, data: &[u8], out: &mut String) {
    out.push_str(&format!("== {}\n", name));
    let comp = u32le(data, 14 + 16);
    if comp != 0 && comp != 3 {
        out.push_str(&format!("error: unsupported compression {}\n", comp));
        return;
    }
    let dib_size = u32le(data, 14) as usize;
    let width = i32le(data, 14 + 4) as usize;
    let height_raw = i32le(data, 14 + 8);
    let bottom_up = height_raw > 0;
    let height = height_raw.unsigned_abs() as usize;
    let bpp = u16le(data, 14 + 14) as usize;
    let off_bits = u32le(data, 10) as usize;
    let colours_used = u32le(data, 14 + 32) as usize;

    let (rmask, gmask, bmask) = if bpp == 32 && comp == 3 {
        if dib_size == 40 {
            (
                u32le(data, 14 + 40),
                u32le(data, 14 + 44),
                u32le(data, 14 + 48),
            )
        } else {
            (
                u32le(data, 14 + 40),
                u32le(data, 14 + 44),
                u32le(data, 14 + 48),
            )
        }
    } else {
        (0, 0, 0)
    };

    let stride = (width * bpp + 31) / 32 * 4;
    let palette_start = 14 + dib_size;
    let pal_count = if colours_used == 0 {
        1usize << bpp
    } else {
        colours_used
    };
    let mut pal_ink = vec![false; pal_count];
    if bpp <= 8 {
        for i in 0..pal_count {
            let o = palette_start + 4 * i;
            let b = data[o] as u32;
            let g = data[o + 1] as u32;
            let r = data[o + 2] as u32;
            pal_ink[i] = is_ink(r, g, b);
        }
    }

    let mut ink = vec![false; width * height];
    for row in 0..height {
        let y = if bottom_up { height - 1 - row } else { row };
        let ro = off_bits + row * stride;
        for x in 0..width {
            let v = match bpp {
                1 => {
                    let idx = ((data[ro + x / 8] >> (7 - x % 8)) & 1) as usize;
                    pal_ink[idx]
                }
                4 => {
                    let byte = data[ro + x / 2];
                    let idx = if x % 2 == 0 {
                        (byte >> 4) as usize
                    } else {
                        (byte & 0xF) as usize
                    };
                    pal_ink[idx]
                }
                8 => pal_ink[data[ro + x] as usize],
                24 => {
                    let o = ro + 3 * x;
                    let b = data[o] as u32;
                    let g = data[o + 1] as u32;
                    let r = data[o + 2] as u32;
                    is_ink(r, g, b)
                }
                32 => {
                    if comp == 0 {
                        let o = ro + 4 * x;
                        let b = data[o] as u32;
                        let g = data[o + 1] as u32;
                        let r = data[o + 2] as u32;
                        is_ink(r, g, b)
                    } else {
                        let pixel = u32le(data, ro + 4 * x);
                        let mut vals = [0u32; 3];
                        for (mi, mask) in [rmask, gmask, bmask].iter().enumerate() {
                            let s = mask.trailing_zeros();
                            let n = mask.count_ones();
                            let m = (1u32 << n) - 1;
                            let v = (pixel & mask) >> s;
                            vals[mi] = (v * 255 + m / 2) / m;
                        }
                        is_ink(vals[0], vals[1], vals[2])
                    }
                }
                _ => false,
            };
            ink[y * width + x] = v;
        }
    }

    let total_ink = ink.iter().filter(|&&v| v).count();
    out.push_str(&format!(
        "size {}x{} bpp {} header {} {} ink {}\n",
        width,
        height,
        bpp,
        dib_size,
        if bottom_up { "bottom-up" } else { "top-down" },
        total_ink
    ));

    let mut visited = vec![false; width * height];
    let mut comps: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();
    for y in 0..height {
        for x in 0..width {
            if !ink[y * width + x] || visited[y * width + x] {
                continue;
            }
            let fx = x;
            let fy = y;
            let mut minx = x;
            let mut maxx = x;
            let mut miny = y;
            let mut maxy = y;
            let mut count = 0usize;
            let mut q = VecDeque::new();
            visited[y * width + x] = true;
            q.push_back((x, y));
            while let Some((cx, cy)) = q.pop_front() {
                count += 1;
                if cx < minx {
                    minx = cx;
                }
                if cx > maxx {
                    maxx = cx;
                }
                if cy < miny {
                    miny = cy;
                }
                if cy > maxy {
                    maxy = cy;
                }
                for dy in -1i64..=1 {
                    for dx in -1i64..=1 {
                        if dx == 0 && dy == 0 {
                            continue;
                        }
                        let nx = cx as i64 + dx;
                        let ny = cy as i64 + dy;
                        if nx < 0 || ny < 0 || nx >= width as i64 || ny >= height as i64 {
                            continue;
                        }
                        let nx = nx as usize;
                        let ny = ny as usize;
                        if ink[ny * width + nx] && !visited[ny * width + nx] {
                            visited[ny * width + nx] = true;
                            q.push_back((nx, ny));
                        }
                    }
                }
            }
            comps.push((fx, fy, minx, miny, maxx, maxy, count));
        }
    }

    out.push_str(&format!("components {}\n", comps.len()));
    for c in &comps {
        out.push_str(&format!(
            "{},{} bbox {},{}-{},{} pixels {}\n",
            c.0, c.1, c.2, c.3, c.4, c.5, c.6
        ));
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let mut entries: Vec<String> = Vec::new();
    for e in fs::read_dir(dir).unwrap() {
        let e = e.unwrap();
        let name = e.file_name().to_string_lossy().into_owned();
        if name.ends_with(".bmp") {
            entries.push(name);
        }
    }
    entries.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));

    let mut out = String::new();
    for name in &entries {
        let path = format!("{}/{}", dir, name);
        let mut data = Vec::new();
        fs::File::open(&path).unwrap().read_to_end(&mut data).unwrap();
        process(name, &data, &mut out);
    }
    print!("{}", out);
}

import Foundation

func le16(_ b: [UInt8], _ o: Int) -> Int { Int(b[o]) | Int(b[o+1]) << 8 }
func le32(_ b: [UInt8], _ o: Int) -> Int { Int(b[o]) | Int(b[o+1]) << 8 | Int(b[o+2]) << 16 | Int(b[o+3]) << 24 }

func processFile(_ path: String, _ name: String) -> String {
    var out = "== \(name)\n"
    guard let data = FileManager.default.contents(atPath: path) else { return out }
    let b = [UInt8](data)
    guard b.count >= 14, b[0] == UInt8(ascii: "B"), b[1] == UInt8(ascii: "M") else { return out }
    let offBits = le32(b, 10)
    let headerSize = le32(b, 14)
    guard headerSize == 40 || headerSize == 108 || headerSize == 124 else { return out }
    let width = le32(b, 18)
    var height = le32(b, 22)
    let bottomUp = height > 0
    height = abs(height)
    let bpp = le16(b, 28)
    let compression = le32(b, 30)
    guard compression == 0 || compression == 3 else {
        out += "error: unsupported compression \(compression)\n"
        return out
    }
    let colorsUsed = le32(b, 46)
    let w = width, h = height
    let rowBytes = ((bpp * w + 31) / 32) * 4
    let palOff = 14 + Int(headerSize)
    let palCount = colorsUsed == 0 ? (1 << bpp) : colorsUsed

    var rMask = 0, gMask = 0, bMask = 0
    if compression == 3 && bpp == 32 {
        rMask = le32(b, 14 + 40)
        gMask = le32(b, 14 + 44)
        bMask = le32(b, 14 + 48)
    }

    func paletteColor(_ idx: Int) -> (Int, Int, Int) {
        let o = palOff + 4 * idx
        return (Int(b[o+2]), Int(b[o+1]), Int(b[o]))
    }
    func scale(_ v: Int, _ mask: Int) -> Int {
        let n = mask.nonzeroBitCount
        let s = mask.trailingZeroBitCount
        let raw = (v & mask) >> s
        let m = (1 << n) - 1
        return (raw * 255 + m / 2) / m
    }

    var ink = [Bool](repeating: false, count: w * h)
    var inkCount = 0
    for y in 0..<h {
        let rowIndex = bottomUp ? (h - 1 - y) : y
        let rowStart = Int(offBits) + rowIndex * rowBytes
        for x in 0..<w {
            var r = 0, g = 0, bl = 0
            switch bpp {
            case 1, 4, 8:
                var idx: Int
                if bpp == 8 {
                    idx = Int(b[rowStart + x])
                } else if bpp == 4 {
                    let byte = Int(b[rowStart + x / 2])
                    idx = (x % 2 == 0) ? (byte >> 4) & 0xF : byte & 0xF
                } else {
                    let byte = Int(b[rowStart + x / 8])
                    idx = (byte >> (7 - x % 8)) & 1
                }
                if idx < palCount { (r, g, bl) = paletteColor(idx) }
            case 24:
                let o = rowStart + 3 * x
                bl = Int(b[o]); g = Int(b[o+1]); r = Int(b[o+2])
            case 32:
                if compression == 0 {
                    let o = rowStart + 4 * x
                    bl = Int(b[o]); g = Int(b[o+1]); r = Int(b[o+2])
                } else {
                    let o = rowStart + 4 * x
                    let pixel = le32(b, o)
                    r = scale(pixel, rMask)
                    g = scale(pixel, gMask)
                    bl = scale(pixel, bMask)
                }
            default:
                break
            }
            if (299 * r + 587 * g + 114 * bl) / 1000 < 128 {
                ink[y * w + x] = true
                inkCount += 1
            }
        }
    }

    out += "size \(w)x\(h) bpp \(bpp) header \(headerSize) \(bottomUp ? "bottom-up" : "top-down") ink \(inkCount)\n"

    var visited = [Bool](repeating: false, count: w * h)
    var comps: [(Int, Int, Int, Int, Int, Int, Int)] = []
    for y in 0..<h {
        for x in 0..<w {
            if ink[y * w + x] && !visited[y * w + x] {
                var stack = [(x, y)]
                visited[y * w + x] = true
                var count = 0
                var minx = x, maxx = x, miny = y, maxy = y
                while let (cx, cy) = stack.popLast() {
                    count += 1
                    minx = min(minx, cx); maxx = max(maxx, cx)
                    miny = min(miny, cy); maxy = max(maxy, cy)
                    for dy in -1...1 {
                        for dx in -1...1 {
                            let nx = cx + dx, ny = cy + dy
                            if nx >= 0 && nx < w && ny >= 0 && ny < h,
                               ink[ny * w + nx] && !visited[ny * w + nx] {
                                visited[ny * w + nx] = true
                                stack.append((nx, ny))
                            }
                        }
                    }
                }
                comps.append((x, y, minx, miny, maxx, maxy, count))
            }
        }
    }

    out += "components \(comps.count)\n"
    for c in comps {
        out += "\(c.0),\(c.1) bbox \(c.2),\(c.3)-\(c.4),\(c.5) pixels \(c.6)\n"
    }
    return out
}

