#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>

static unsigned get32(const unsigned char *b, size_t o) {
    return b[o] | (b[o+1] << 8) | (b[o+2] << 16) | ((unsigned)b[o+3] << 24);
}
static int geti32(const unsigned char *b, size_t o) { return (int)get32(b, o); }
static unsigned get16(const unsigned char *b, size_t o) { return b[o] | (b[o+1] << 8); }

static int scale(unsigned p, unsigned mask) {
    if (!mask) return 0;
    int s = 0;
    while (!(mask & 1)) { mask >>= 1; s++; }
    int n = 0;
    unsigned t = mask;
    while (t) { n += t & 1; t >>= 1; }
    unsigned m = (1u << n) - 1;
    unsigned v = (p & (mask << s)) >> s;
    return (int)((v * 255 + m / 2) / m);
}

typedef struct { int x, y, minx, miny, maxx, maxy, cnt; } Comp;

static void process(const char *name) {
    FILE *f = fopen(name, "rb");
    printf("== %s\n", name);
    if (!f) return;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *d = malloc(sz ? sz : 1);
    if (fread(d, 1, sz, f) != (size_t)sz) { /* ignore */ }
    fclose(f);

    unsigned off = get32(d, 10);
    unsigned hs = get32(d, 14);
    int w = geti32(d, 18);
    int h = geti32(d, 22);
    unsigned bpp = get16(d, 28);
    unsigned comp = get32(d, 30);

    if (comp != 0 && comp != 3) {
        printf("error: unsupported compression %u\n", comp);
        free(d);
        return;
    }

    int topdown = h < 0;
    int H = h < 0 ? -h : h;
    int W = w;
    size_t stride = ((size_t)W * bpp + 31) / 32 * 4;

    unsigned char *pal = NULL;
    unsigned ncol = 0;
    if (bpp <= 8) {
        ncol = get32(d, 46);
        if (!ncol) ncol = 1u << bpp;
        pal = d + 14 + hs;
    }

    unsigned maskR = 0, maskG = 0, maskB = 0;
    if (bpp == 32 && comp == 3) {
        maskR = get32(d, 54);
        maskG = get32(d, 58);
        maskB = get32(d, 62);
    }

    unsigned char *ink = calloc((size_t)W * H, 1);
    long inkcount = 0;
    for (int y = 0; y < H; y++) {
        int row = topdown ? y : H - 1 - y;
        const unsigned char *r = d + off + (size_t)row * stride;
        for (int x = 0; x < W; x++) {
            int R, G, B;
            if (bpp == 24) {
                R = r[x*3+2]; G = r[x*3+1]; B = r[x*3];
            } else if (bpp == 32) {
                if (comp == 3) {
                    unsigned p = get32(r, (size_t)x * 4);
                    R = scale(p, maskR);
                    G = scale(p, maskG);
                    B = scale(p, maskB);
                } else {
                    R = r[x*4+2]; G = r[x*4+1]; B = r[x*4];
                }
            } else {
                unsigned idx;
                if (bpp == 8) idx = r[x];
                else if (bpp == 4) idx = (x & 1) ? (r[x >> 1] & 15) : (r[x >> 1] >> 4);
                else idx = (r[x >> 3] >> (7 - (x & 7))) & 1;
                if (idx >= ncol) idx = 0;
                R = pal[idx*4+2]; G = pal[idx*4+1]; B = pal[idx*4];
            }
            if ((299 * R + 587 * G + 114 * B) / 1000 < 128) {
                ink[(size_t)y * W + x] = 1;
                inkcount++;
            }
        }
    }

    printf("size %dx%d bpp %u header %u %s ink %ld\n",
           W, H, bpp, hs, topdown ? "top-down" : "bottom-up", inkcount);

    int *stack = malloc(sizeof(int) * (size_t)W * H);
    unsigned char *vis = calloc((size_t)W * H, 1);
    Comp *comps = NULL;
    int ncomp = 0, cap = 0;

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (ink[(size_t)y * W + x] && !vis[(size_t)y * W + x]) {
                if (ncomp == cap) {
                    cap = cap ? cap * 2 : 16;
                    comps = realloc(comps, cap * sizeof(Comp));
                }
                Comp *c = &comps[ncomp++];
                c->x = x; c->y = y;
                c->minx = x; c->maxx = x; c->miny = y; c->maxy = y;
                c->cnt = 0;
                int sp = 0;
                stack[sp++] = y * W + x;
                vis[(size_t)y * W + x] = 1;
                while (sp) {
                    int p = stack[--sp];
                    int py = p / W, px = p % W;
                    c->cnt++;
                    if (px < c->minx) c->minx = px;
                    if (px > c->maxx) c->maxx = px;
                    if (py < c->miny) c->miny = py;
                    if (py > c->maxy) c->maxy = py;
                    for (int dy = -1; dy <= 1; dy++) {
                        for (int dx = -1; dx <= 1; dx++) {
                            if (!dx && !dy) continue;
                            int nx = px + dx, ny = py + dy;
                            if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
                            int q = ny * W + nx;
                            if (ink[q] && !vis[q]) {
                                vis[q] = 1;
                                stack[sp++] = q;
                            }
                        }
                    }
                }
            }
        }
    }

    printf("components %d\n", ncomp);
    for (int i = 0; i < ncomp; i++) {
        Comp *c = &comps[i];
        printf("%d,%d bbox %d,%d-%d,%d pixels %d\n",
               c->x, c->y, c->minx, c->miny, c->maxx, c->maxy, c->cnt);
    }

    free(comps); free(vis); free(stack); free(ink); free(d);
}

static int cmpstr(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    if (chdir(argv[1]) != 0) return 0;
    DIR *dp = opendir(".");
    if (!dp) return 0;
    char **names = NULL;
    int n = 0, cap = 0;
    struct dirent *de;
    while ((de = readdir(dp))) {
        size_t l = strlen(de->d_name);
        if (l > 4 && !strcmp(de->d_name + l - 4, ".bmp")) {
            if (n == cap) {
                cap = cap ? cap * 2 : 16;
                names = realloc(names, cap * sizeof(*names));
            }
            names[n++] = strdup(de->d_name);
        }
    }
    closedir(dp);
    qsort(names, n, sizeof(*names), cmpstr);
    for (int i = 0; i < n; i++) {
        process(names[i]);
        free(names[i]);
    }
    free(names);
    return 0;
}

import socket, struct, sys, os, random

QTYPES = {1: 'A', 2: 'NS', 5: 'CNAME', 6: 'SOA', 12: 'PTR', 15: 'MX', 16: 'TXT', 28: 'AAAA'}
RCODES = {0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'}

def encode_name(name):
    out = b''
    for label in name.split('.'):
        if label:
            out += bytes([len(label)]) + label.encode()
    return out + b'\x00'

def parse_name(msg, off):
    labels = []
    pos = off
    end = None
    while True:
        b = msg[pos]
        if b & 0xC0 == 0xC0:
            ptr = ((b & 0x3F) << 8) | msg[pos + 1]
            if end is None:
                end = pos + 2
            pos = ptr
        elif b == 0:
            if end is None:
                end = pos + 1
            break
        else:
            labels.append(msg[pos + 1:pos + 1 + b].decode('latin-1').lower())
            pos += 1 + b
    name = '.'.join(labels)
    return (name if name else '.'), end

def fmt_aaaa(ip):
    groups = [struct.unpack('>H', ip[i:i+2])[0] for i in range(0, 16, 2)]
    best_s = best_l = -1
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            if j - i > best_l:
                best_s, best_l = i, j - i
            i = j
        else:
            i += 1
    if best_l >= 2:
        left = ['%x' % g for g in groups[:best_s]]
        right = ['%x' % g for g in groups[best_s+best_l:]]
        return ':'.join(left) + '::' + ':'.join(right)
    return ':'.join('%x' % g for g in groups)

def fmt_txt(rdata):
    parts = []
    i = 0
    while i < len(rdata):
        ln = rdata[i]
        s = rdata[i+1:i+1+ln]
        i += 1 + ln
        out = '"'
        for c in s:
            if c == 0x22:
                out += '\\"'
            elif c == 0x5C:
                out += '\\\\'
            elif 0x20 <= c <= 0x7E:
                out += chr(c)
            else:
                out += '\\' + '%03d' % c
        out += '"'
        parts.append(out)
    return ' '.join(parts)

def fmt_rdata(rtype, rdata, msg, rdo):
    if rtype == 1 and len(rdata) == 4:
        return socket.inet_ntoa(rdata)
    if rtype == 28 and len(rdata) == 16:
        return fmt_aaaa(rdata)
    if rtype == 5 or rtype == 2 or rtype == 12:
        name, _ = parse_name(msg, rdo)
        return name
    if rtype == 15:
        pref = struct.unpack('>H', rdata[:2])[0]
        name, _ = parse_name(msg, rdo + 2)
        return '%d %s' % (pref, name)
    if rtype == 16:
        return fmt_txt(rdata)
    if len(rdata) == 0:
        return '\\# 0'
    return '\\# %d %s' % (len(rdata), rdata.hex())

def build_query(qid, name, qtype):
    header = struct.pack('>HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    return header + encode_name(name) + struct.pack('>HH', qtype, 1)

def parse_response(msg, qid):
    ident, flags, qd, an, ns, ar = struct.unpack('>HHHHHH', msg[:12])
    if ident != qid or not (flags & 0x8000):
        return None
    rcode = flags & 0x000F
    off = 12
    for _ in range(qd):
        _, off = parse_name(msg, off)
        off += 4
    records = []
    for _ in range(an):
        owner, off = parse_name(msg, off)
        rtype, rclass, ttl, rdlen = struct.unpack('>HHIH', msg[off:off+10])
        off += 10
        rdata = msg[off:off+rdlen]
        rdo = off
        off += rdlen
        tname = QTYPES.get(rtype, 'TYPE%d' % rtype)
        data = fmt_rdata(rtype, rdata, msg, rdo)
        records.append('  %s %d %s %s' % (owner, ttl, tname, data))
    return rcode, records

def main():
    qdir, port = sys.argv[1], int(sys.argv[2])
    addr = ('127.0.0.1', port)
    udp = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    udp.settimeout(5)
    tcp = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    tcp.settimeout(5)
    tcp.connect(addr)

    def recv_udp(qid):
        while True:
            data, _ = udp.recvfrom(65535)
            if len(data) >= 12:
                ident = struct.unpack('>H', data[:2])[0]
                if ident == qid:
                    return data

    def recv_tcp_exact(n):
        buf = b''
        while len(buf) < n:
            chunk = tcp.recv(n - len(buf))
            if not chunk:
                break
            buf += chunk
        return buf

    def do_tcp(query):
        tcp.sendall(struct.pack('>H', len(query)) + query)
        hdr = recv_tcp_exact(2)
        ln = struct.unpack('>H', hdr)[0]
        return recv_tcp_exact(ln)

    out = []
    with open(os.path.join(qdir, 'queries.txt')) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            name, qtype_s = line.rsplit(' ', 1)
            qtype = {'A': 1, 'CNAME': 5, 'MX': 15, 'TXT': 16, 'AAAA': 28}[qtype_s]
            qid = random.randrange(65536)
            query = build_query(qid, name, qtype)
            udp.sendto(query, addr)
            data = recv_udp(qid)
            flags = struct.unpack('>H', data[2:4])[0]
            if flags & 0x0200:
                data = do_tcp(query)
            rcode, records = parse_response(data, qid)
            disp = name.lower()
            if disp.endswith('.'):
                disp = disp[:-1]
            if not disp:
                disp = '.'
            rc = RCODES.get(rcode, 'RCODE%d' % rcode)
            out.append('%s %s %s' % (disp, qtype_s, rc))
            out.extend(records)
    print('\n'.join(out))

main()

import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static byte[] buildQuery(int id, String name, int qtype) {
        ByteArrayOutputStream b = new ByteArrayOutputStream();
        DataOutputStream d = new DataOutputStream(b);
        try {
            d.writeShort(id);
            d.writeShort(0x0100);
            d.writeShort(1); d.writeShort(0); d.writeShort(0); d.writeShort(0);
            for (String label : name.split("\\.", -1)) {
                if (label.isEmpty()) continue;
                d.writeByte(label.length());
                d.write(label.getBytes(StandardCharsets.US_ASCII));
            }
            d.writeByte(0);
            d.writeShort(qtype);
            d.writeShort(1);
        } catch (IOException e) { throw new RuntimeException(e); }
        return b.toByteArray();
    }

    static int[] skipName(byte[] m, int off) {
        while (true) {
            int len = m[off] & 0xFF;
            if ((len & 0xC0) == 0xC0) return new int[]{off + 2};
            off++;
            if (len == 0) return new int[]{off};
            off += len;
        }
    }

    static String readName(byte[] m, int off, int[] end) {
        StringBuilder sb = new StringBuilder();
        int[] ptr = {off};
        boolean jumped = false;
        int[] finalPos = end;
        Set<Integer> seen = new HashSet<>();
        while (true) {
            int len = m[ptr[0]] & 0xFF;
            if ((len & 0xC0) == 0xC0) {
                int target = ((len & 0x3F) << 8) | (m[ptr[0] + 1] & 0xFF);
                if (!jumped) { finalPos[0] = ptr[0] + 2; jumped = true; }
                if (!seen.add(target)) break; // loop guard
                ptr[0] = target;
                continue;
            }
            ptr[0]++;
            if (len == 0) {
                if (!jumped) finalPos[0] = ptr[0];
                break;
            }
            if (sb.length() > 0) sb.append('.');
            for (int i = 0; i < len; i++) sb.append((char)(m[ptr[0] + i] & 0xFF));
            ptr[0] += len;
        }
        return sb.toString();
    }

    static String lowerName(String n) {
        if (n.isEmpty()) return ".";
        return n.toLowerCase(Locale.ROOT);
    }

    static String formatAAAA(byte[] a) {
        int[] g = new int[8];
        for (int i = 0; i < 8; i++) g[i] = ((a[2*i] & 0xFF) << 8) | (a[2*i+1] & 0xFF);
        int bestStart = -1, bestLen = 0, curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (g[i] == 0) {
                if (curLen == 0) curStart = i;
                curLen++;
                if (curLen > bestLen) { bestLen = curLen; bestStart = curStart; }
            } else curLen = 0;
        }
        if (bestLen < 2) bestStart = -1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 8; i++) {
            if (bestStart >= 0 && i == bestStart) {
                sb.append("::");
                i += bestLen - 1;
                continue;
            }
            if (bestStart >= 0 && i > bestStart && i < bestStart + bestLen) continue;
            if (sb.length() > 0 && !sb.toString().endsWith(":")) sb.append(':');
            sb.append(Integer.toHexString(g[i]));
        }
        return sb.toString();
    }

    static String formatTXT(byte[] rdata) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < rdata.length) {
            int len = rdata[i++] & 0xFF;
            if (sb.length() > 0) sb.append(' ');
            sb.append('"');
            for (int j = 0; j < len; j++) {
                int c = rdata[i + j] & 0xFF;
                if (c == '"') sb.append("\\\"");
                else if (c == '\\') sb.append("\\\\");
                else if (c >= 0x20 && c <= 0x7E) sb.append((char) c);
                else sb.append('\\').append(String.format("%03d", c));
            }
            sb.append('"');
            i += len;
        }
        return sb.toString();
    }

    static String formatRData(byte[] msg, int rdataOff, int rdlen, int type, int[] consumed) {
        switch (type) {
            case 1:
                return (rdataOff[0+0] == 0 ? "" : "");
            default:
                return null;
        }
    }

    static String typeOrGeneric(int type) {
        switch (type) {
            case 1: return "A";
            case 5: return "CNAME";
            case 15: return "MX";
            case 16: return "TXT";
            case 28: return "AAAA";
            default: return "TYPE" + type;
        }
    }

    static String rdataToString(byte[] msg, int off, int rdlen, int type) {
        switch (type) {
            case 1: {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < 4; i++) {
                    if (i > 0) sb.append('.');
                    sb.append(msg[off + i] & 0xFF);
                }
                return sb.toString();
            }
            case 28: {
                byte[] a = Arrays.copyOfRange(msg, off, off + 16);
                return formatAAAA(a);
            }
            case 5: {
                int[] end = new int[1];
                return lowerName(readName(msg, off, end));
            }
            case 15: {
                int pref = ((msg[off] & 0xFF) << 8) | (msg[off + 1] & 0xFF);
                int[] end = new int[1];
                String ex = lowerName(readName(msg, off + 2, end));
                return pref + " " + ex;
            }
            case 16: {
                return formatTXT(Arrays.copyOfRange(msg, off, off + rdlen));
            }
            default: {
                StringBuilder sb = new StringBuilder("\\# ").append(rdlen);
                if (rdlen > 0) {
                    sb.append(' ');
                    for (int i = 0; i < rdlen; i++) sb.append(String.format("%02x", msg[off + i] & 0xFF));
                }
                return sb.toString();
            }
        }
    }

    static String rcodeName(int rcode) {
        switch (rcode) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + rcode;
        }
    }

    static byte[] tcpQuery(byte[] query, InetSocketAddress addr) throws IOException {
        try (Socket s = new Socket(addr.getAddress(), addr.getPort())) {
            OutputStream out = s.getOutputStream();
            InputStream in = s.getInputStream();
            out.write((query.length >> 8) & 0xFF);
            out.write(query.length & 0xFF);
            out.write(query);
            out.flush();
            int hi = in.read(), lo = in.read();
            int len = ((hi & 0xFF) << 8) | (lo & 0xFF);
            byte[] resp = new byte[len];
            int got = 0;
            while (got < len) {
                int r = in.read(resp, got, len - got);
                if (r < 0) throw new EOFException();
                got += r;
            }
            return resp;
        }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);
        InetAddress server = InetAddress.getByName("127.0.0.1");
        DatagramSocket sock = new DatagramSocket();
        sock.setSoTimeout(10000);
        InetSocketAddress addr = new InetSocketAddress(server, port);

        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        StringBuilder output = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.trim().split(" ");
            String name = parts[0];
            String typeStr = parts[1];
            int qtype;
            switch (typeStr) {
                case "A": qtype = 1; break;
                case "CNAME": qtype = 5; break;
                case "MX": qtype = 15; break;
                case "TXT": qtype = 16; break;
                case "AAAA": qtype = 28; break;
                default: throw new RuntimeException("bad type");
            }

            int id = new Random().nextInt(0x10000);
            byte[] query = buildQuery(id, name, qtype);

            byte[] resp = null;
            // UDP
            sock.send(new DatagramPacket(query, query.length, addr));
            byte[] buf = new byte[65536];
            while (resp == null) {
                DatagramPacket p = new DatagramPacket(buf, buf.length);
                sock.receive(p);
                byte[] d = Arrays.copyOf(p.getData(), p.getLength());
                if (d.length < 12) continue;
                int rid = ((d[0] & 0xFF) << 8) | (d[1] & 0xFF);
                if (rid != id) continue;
                if ((d[2] & 0x80) == 0) continue; // QR must be 1
                if ((d[2] & 0x02) != 0) { // TC
                    resp = tcpQuery(query, addr);
                } else {
                    resp = d;
                }
            }

            int flagsHi = resp[2] & 0xFF;
            int rcode = resp[3] & 0x0F;
            int qdcount = ((resp[4] & 0xFF) << 8) | (resp[5] & 0xFF);
            int ancount = ((resp[6] & 0xFF) << 8) | (resp[7] & 0xFF);

            String qNameLower = name.toLowerCase(Locale.ROOT);
            if (qNameLower.endsWith(".")) qNameLower = qNameLower.substring(0, qNameLower.length() - 1);
            if (qNameLower.isEmpty()) qNameLower = ".";

            output.append(qNameLower).append(' ').append(typeStr).append(' ').append(rcodeName(rcode)).append('\n');

            int off = 12;
            int[] end = new int[1];
            for (int i = 0; i < qdcount; i++) {
                off = skipName(resp, off)[0];
                off += 4;
            }
            for (int i = 0; i < ancount; i++) {
                String owner = lowerName(readName(resp, off, end));
                off = end[0];
                int type = ((resp[off] & 0xFF) << 8) | (resp[off + 1] & 0xFF);
                off += 4; // type + class
                long ttl = ((long)(resp[off] & 0xFF) << 24) | ((resp[off+1] & 0xFF) << 16)
                         | ((resp[off+2] & 0xFF) << 8) | (resp[off+3] & 0xFF);
                off += 4;
                int rdlen = ((resp[off] & 0xFF) << 8) | (resp[off + 1] & 0xFF);
                off += 2;
                String data = rdataToString(resp, off, rdlen, type);
                off += rdlen;
                output.append("  ").append(owner).append(' ').append(ttl).append(' ')
                      .append(typeOrGeneric(type)).append(' ').append(data).append('\n');
            }
        }

        System.out.print(output);
        sock.close();
        System.exit(0);
    }
}

import java.io.*;
