                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < 4; i++) {
                    if (i > 0) sb.append('.');
                    sb.append(msg[off + i] & 0xFF);
                }
                return sb.toString();
            }
            case 28: {
                byte[] a = Arrays.copyOfRange(msg, off, off + 16);
                return formatAAAA(a);
            }
            case 5: {
                int[] end = new int[1];
                return lowerName(readName(msg, off, end));
            }
            case 15: {
                int pref = ((msg[off] & 0xFF) << 8) | (msg[off + 1] & 0xFF);
                int[] end = new int[1];
                String ex = lowerName(readName(msg, off + 2, end));
                return pref + " " + ex;
            }
            case 16: {
                return formatTXT(Arrays.copyOfRange(msg, off, off + rdlen));
            }
            default: {
                StringBuilder sb = new StringBuilder("\\# ").append(rdlen);
                if (rdlen > 0) {
                    sb.append(' ');
                    for (int i = 0; i < rdlen; i++) sb.append(String.format("%02x", msg[off + i] & 0xFF));
                }
                return sb.toString();
            }
        }
    }

    static String rcodeName(int rcode) {
        switch (rcode) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + rcode;
        }
    }

    static byte[] tcpQuery(byte[] query, InetSocketAddress addr) throws IOException {
        try (Socket s = new Socket(addr.getAddress(), addr.getPort())) {
            OutputStream out = s.getOutputStream();
            InputStream in = s.getInputStream();
            out.write((query.length >> 8) & 0xFF);
            out.write(query.length & 0xFF);
            out.write(query);
            out.flush();
            int hi = in.read(), lo = in.read();
            int len = ((hi & 0xFF) << 8) | (lo & 0xFF);
            byte[] resp = new byte[len];
            int got = 0;
            while (got < len) {
                int r = in.read(resp, got, len - got);
                if (r < 0) throw new EOFException();
                got += r;
            }
            return resp;
        }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);
        InetAddress server = InetAddress.getByName("127.0.0.1");
        DatagramSocket sock = new DatagramSocket();
        sock.setSoTimeout(10000);
        InetSocketAddress addr = new InetSocketAddress(server, port);

        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        StringBuilder output = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.trim().split(" ");
            String name = parts[0];
            String typeStr = parts[1];
            int qtype;
            switch (typeStr) {
                case "A": qtype = 1; break;
                case "CNAME": qtype = 5; break;
                case "MX": qtype = 15; break;
                case "TXT": qtype = 16; break;
                case "AAAA": qtype = 28; break;
                default: throw new RuntimeException("bad type");
            }

            int id = new Random().nextInt(0x10000);
            byte[] query = buildQuery(id, name, qtype);

            byte[] resp = null;
            sock.send(new DatagramPacket(query, query.length, addr));
            byte[] buf = new byte[65536];
            while (resp == null) {
                DatagramPacket p = new DatagramPacket(buf, buf.length);
                sock.receive(p);
                byte[] d = Arrays.copyOf(p.getData(), p.getLength());
                if (d.length < 12) continue;
                int rid = ((d[0] & 0xFF) << 8) | (d[1] & 0xFF);
                if (rid != id) continue;
                if ((d[2] & 0x80) == 0) continue; // QR must be 1
                if ((d[2] & 0x02) != 0) { // TC
                    resp = tcpQuery(query, addr);
                } else {
                    resp = d;
                }
            }

            int rcode = resp[3] & 0x0F;
            int qdcount = ((resp[4] & 0xFF) << 8) | (resp[5] & 0xFF);
            int ancount = ((resp[6] & 0xFF) << 8) | (resp[7] & 0xFF);

            String qNameLower = name.toLowerCase(Locale.ROOT);
            if (qNameLower.endsWith(".")) qNameLower = qNameLower.substring(0, qNameLower.length() - 1);
            if (qNameLower.isEmpty()) qNameLower = ".";

            output.append(qNameLower).append(' ').append(typeStr).append(' ').append(rcodeName(rcode)).append('\n');

            int off = 12;
            for (int i = 0; i < qdcount; i++) {
                off = skipName(resp, off);
                off += 4;
            }
            for (int i = 0; i < ancount; i++) {
                String owner = lowerName(readName(resp, off, new int[1]));
                off = skipName(resp, off);
                int type = ((resp[off] & 0xFF) << 8) | (resp[off + 1] & 0xFF);
                off += 4; // type + class
                long ttl = ((long)(resp[off] & 0xFF) << 24) | ((resp[off+1] & 0xFF) << 16)
                         | ((resp[off+2] & 0xFF) << 8) | (resp[off+3] & 0xFF);
                off += 4;
                int rdlen = ((resp[off] & 0xFF) << 8) | (resp[off + 1] & 0xFF);
                off += 2;
                String data = rdataToString(resp, off, rdlen, type);
                off += rdlen;
                output.append("  ").append(owner).append(' ').append(ttl).append(' ')
                      .append(typeOrGeneric(type)).append(' ').append(data).append('\n');
            }
        }

        System.out.print(output);
        sock.close();
        System.exit(0);
    }
}

import * as dgram from 'dgram';
import * as net from 'net';
import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const port = parseInt(process.argv[3], 10);

const TYPES: Record<number, string> = { 1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA' };
const RCODES = ['NOERROR', 'FORMERR', 'SERVFAIL', 'NXDOMAIN', 'NOTIMP', 'REFUSED'];
const QTYPES: Record<string, number> = { A: 1, CNAME: 5, MX: 15, TXT: 16, AAAA: 28 };

function encodeName(name: string): Buffer {
  const labels = name.replace(/\.$/, '').split('.').filter(l => l.length > 0);
  const parts: number[] = [];
  for (const l of labels) {
    parts.push(l.length);
    for (const b of Buffer.from(l, 'latin1')) parts.push(b);
  }
  parts.push(0);
  return Buffer.from(parts);
}

function buildQuery(id: number, name: string, qtype: number): Buffer {
  const head = Buffer.alloc(12);
  head.writeUInt16BE(id, 0);
  head.writeUInt16BE(0x0100, 2);
  head.writeUInt16BE(1, 4); // QDCOUNT
  const q = Buffer.alloc(4);
  q.writeUInt16BE(qtype, 0);
  q.writeUInt16BE(1, 2); // IN
  return Buffer.concat([head, encodeName(name), q]);
}

function readName(msg: Buffer, off: number): [string, number] {
  const labels: string[] = [];
  let jumped = false;
  let end = off;
  let guard = 0;
  while (true) {
    if (off >= msg.length) break;
    const len = msg[off];
    if (len === 0) {
      if (!jumped) end = off + 1;
      break;
    }
    if ((len & 0xc0) === 0xc0) {
      const ptr = ((len & 0x3f) << 8) | msg[off + 1];
      if (!jumped) end = off + 2;
      off = ptr;
      jumped = true;
      if (++guard > 200) break;
      continue;
    }
    labels.push(msg.toString('latin1', off + 1, off + 1 + len).toLowerCase());
    off += 1 + len;
  }
  return [labels.length ? labels.join('.') : '.', end];
}

function fmtAAAA(b: Buffer): string {
  const groups: string[] = [];
  for (let i = 0; i < 8; i++) groups.push(b.readUInt16BE(i * 2).toString(16));
  let best = -1, bestLen = 0, i = 0;
  while (i < 8) {
    if (groups[i] === '0') {
      let j = i;
      while (j < 8 && groups[j] === '0') j++;
      if (j - i > bestLen) { bestLen = j - i; best = i; }
      i = j;
    } else i++;
  }
  if (bestLen >= 2) {
    return groups.slice(0, best).join(':') + '::' + groups.slice(best + bestLen).join(':');
  }
  return groups.join(':');
}

function escapeTxt(b: Buffer): string {
  let s = '';
  for (const byte of b) {
    if (byte === 0x22) s += '\\"';
    else if (byte === 0x5c) s += '\\\\';
    else if (byte >= 0x20 && byte <= 0x7e) s += String.fromCharCode(byte);
    else s += '\\' + byte.toString(10).padStart(3, '0');
  }
  return s;
}

function fmtRDATA(type: number, msg: Buffer, off: number, len: number): string {
  if (type === 1 && len === 4) {
    return `${msg[off]}.${msg[off + 1]}.${msg[off + 2]}.${msg[off + 3]}`;
  }
  if (type === 28 && len === 16) return fmtAAAA(msg.subarray(off, off + 16));
  if (type === 5) { const [n] = readName(msg, off); return n; }
  if (type === 15) {
    const pref = msg.readUInt16BE(off);
    const [n] = readName(msg, off + 2);
    return `${pref} ${n}`;
  }
  if (type === 16) {
    let o = off;
    const parts: string[] = [];
    while (o < off + len) {
      const l = msg[o];
      parts.push('"' + escapeTxt(msg.subarray(o + 1, o + 1 + l)) + '"');
      o += 1 + l;
    }
    return parts.join(' ');
  }
  let hex = '';
  for (let i = 0; i < len; i++) hex += msg[off + i].toString(16).padStart(2, '0');
  return `\\# ${len}${len ? ' ' + hex : ''}`;
}

interface Rec { name: string; ttl: number; type: number; data: string; }
interface Resp { id: number; qr: number; tc: number; rcode: number; answers: Rec[]; }

function parseResponse(msg: Buffer): Resp {
  const id = msg.readUInt16BE(0);
  const flags = msg.readUInt16BE(2);
  const qd = msg.readUInt16BE(4);
  const an = msg.readUInt16BE(6);
  const rcode = flags & 0xf;
  let off = 12;
  for (let i = 0; i < qd; i++) {
    const [, n] = readName(msg, off);
    off = n + 4;
  }
  const answers: Rec[] = [];
  for (let i = 0; i < an; i++) {
    const [name, n1] = readName(msg, off);
    off = n1;
    const type = msg.readUInt16BE(off);
    const ttl = msg.readUInt32BE(off + 4);
    const rdlen = msg.readUInt16BE(off + 8);
    const rstart = off + 10;
    answers.push({ name, ttl, type, data: fmtRDATA(type, msg, rstart, rdlen) });
    off = rstart + rdlen;
  }
  return { id, qr: (flags >> 15) & 1, tc: (flags >> 9) & 1, rcode, answers };
}

function udpQuery(q: Buffer): Promise<Buffer> {
  return new Promise(resolve => {
    const sock = dgram.createSocket('udp4');
    sock.on('message', m => {
      if (m.length < 12) return;
      const id = m.readUInt16BE(0);
      const flags = m.readUInt16BE(2);
      if (id === q.readUInt16BE(0) && (flags & 0x8000)) {
        sock.close();
        resolve(m);
      }
    });
    sock.send(q, port, '127.0.0.1');
  });
}

function tcpQuery(q: Buffer): Promise<Buffer> {
  return new Promise(resolve => {
    const sock = net.connect(port, '127.0.0.1', () => {
      const len = Buffer.alloc(2);
      len.writeUInt16BE(q.length, 0);
      sock.write(Buffer.concat([len, q]));
    });
    let buf = Buffer.alloc(0);
    let done = false;
    sock.on('data', d => {
      buf = Buffer.concat([buf, d]);
      if (!done && buf.length >= 2) {
        const need = 2 + buf.readUInt16BE(0);
        if (buf.length >= need) {
          done = true;
          sock.end();
          resolve(buf.subarray(2, need));
        }
      }
    });
  });
}

async function main() {
  const lines = fs.readFileSync(path.join(dir, 'queries.txt'), 'utf8').split('\n');
  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;
    const sp = t.indexOf(' ');
    const name = sp === -1 ? t : t.slice(0, sp);
    const typeStr = sp === -1 ? 'A' : t.slice(sp + 1).trim();
    const qtype = QTYPES[typeStr] ?? 1;
    const id = (Math.random() * 65536) | 0;
    const q = buildQuery(id, name, qtype);
    let parsed = parseResponse(await udpQuery(q));
    if (parsed.tc) parsed = parseResponse(await tcpQuery(q));
    let lname = name.toLowerCase();
    if (lname.endsWith('.')) lname = lname.slice(0, -1);
    if (lname === '') lname = '.';
    const rcodeStr = RCODES[parsed.rcode] ?? `RCODE${parsed.rcode}`;
    console.log(`${lname} ${typeStr} ${rcodeStr}`);
    for (const r of parsed.answers) {
      const tname = TYPES[r.type] ?? `TYPE${r.type}`;
      console.log(`  ${r.name} ${r.ttl} ${tname} ${r.data}`);
    }
  }
}

main().catch(() => process.exit(1));

import Foundation

signal(SIGPIPE, SIG_IGN)

func die(_ m: String) -> Never {
    FileHandle.standardError.write((m + "\n").data(using: .utf8)!)
    exit(1)
}

let args = CommandLine.arguments
guard args.count == 3, let port = UInt16(args[2]) else { die("usage: main <dir> <port>") }
let dir = args[1]

let fileText: String
do { fileText = try String(contentsOfFile: dir + "/queries.txt", encoding: .utf8) }
catch { die("cannot read queries.txt: \(error)") }

let qtypeMap = ["A": 1, "CNAME": 5, "MX": 15, "TXT": 16, "AAAA": 28]

func encodeName(_ name: String) -> [UInt8] {
    var n = name
    if n.hasSuffix(".") { n.removeLast() }
    var out: [UInt8] = []
    if !n.isEmpty {
        for label in n.split(separator: ".", omittingEmptySubsequences: false) {
            let b = Array(label.utf8)
            out.append(UInt8(b.count))
            out += b
        }
    }
    out.append(0)
    return out
}

func readName(_ msg: [UInt8], _ start: Int) -> (String, Int) {
    var labels: [String] = []
    var off = start
    var next = -1
    var hops = 0
    while true {
        guard off >= 0 && off < msg.count else { break }
        let b = msg[off]
        if b & 0xC0 == 0xC0 {
            if off + 1 >= msg.count { break }
            if next < 0 { next = off + 2 }
            off = (Int(b & 0x3F) << 8) | Int(msg[off + 1])
            hops += 1
            if hops > 128 { break }
            continue
        }
        if b == 0 {
            if next < 0 { next = off + 1 }
            break
        }
        let len = Int(b)
        if off + 1 + len > msg.count { break }
        labels.append(String(bytes: msg[(off + 1)..<(off + 1 + len)], encoding: .isoLatin1) ?? "")
        off += 1 + len
    }
    if next < 0 { next = msg.count }
    let name = labels.isEmpty ? "." : labels.map { $0.lowercased() }.joined(separator: ".")
    return (name, next)
}

func formatAAAA(_ rdata: ArraySlice<UInt8>) -> String {
    var groups: [Int] = []
    let s = rdata.startIndex
    for i in 0..<8 {
        groups.append(Int(rdata[s + i * 2]) << 8 | Int(rdata[s + i * 2 + 1]))
    }
    var bestStart = -1, bestLen = 0
    var i = 0
    while i < 8 {
        if groups[i] == 0 {
            var j = i
            while j < 8 && groups[j] == 0 { j += 1 }
            let len = j - i
            if len >= 2 && len > bestLen { bestLen = len; bestStart = i }
            i = j
        } else { i += 1 }
    }
    if bestStart < 0 {
        return groups.map { String($0, radix: 16) }.joined(separator: ":")
    }
    let left = groups[0..<bestStart].map { String($0, radix: 16) }.joined(separator: ":")
    let right = groups[(bestStart + bestLen)..<8].map { String($0, radix: 16) }.joined(separator: ":")
    return left + "::" + right
}

func escapeTXT(_ bytes: [UInt8]) -> String {
    var s = "\""
    for b in bytes {
        switch b {
        case 0x22: s += "\\\""
        case 0x5C: s += "\\\\"
        case 0x20...0x7E: s.append(Character(UnicodeScalar(b)))
        default: s += String(format: "\\%03u", b)
        }
    }
    return s + "\""
}

func formatRData(_ msg: [UInt8], _ type: Int, _ rdata: ArraySlice<UInt8>) -> String {
    let base = rdata.startIndex
    switch type {
    case 1:
        return rdata.map { String($0) }.joined(separator: ".")
    case 28:
        return formatAAAA(rdata)
    case 5:
        let (n, _) = readName(msg, base)
        return n
    case 15:
        guard rdata.count >= 3 else { return "" }
        let pref = Int(msg[base]) << 8 | Int(msg[base + 1])
        let (n, _) = readName(msg, base + 2)
        return "\(pref) \(n)"
    case 16:
        var parts: [String] = []
        var i = base
        while i < rdata.endIndex {
            let len = Int(msg[i])
            i += 1
            guard i + len <= rdata.endIndex else { break }
            parts.append(escapeTXT(Array(msg[i..<i + len])))
            i += len
        }
        return parts.joined(separator: " ")
    default:
        if rdata.isEmpty { return "\\# 0" }
        let hex = rdata.map { String(format: "%02x", $0) }.joined()
        return "\\# \(rdata.count) \(hex)"
    }
}

func makeAddr(_ port: UInt16) -> sockaddr_in {
    var a = sockaddr_in()
    a.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
    a.sin_family = sa_family_t(AF_INET)
    a.sin_port = port.bigEndian
    a.sin_addr.s_addr = inet_addr("127.0.0.1")
    return a
}

func udpExchange(_ msg: [UInt8], _ port: UInt16) -> [UInt8] {
    let fd = socket(AF_INET, SOCK_DGRAM, 0)
    guard fd >= 0 else { die("socket") }
    defer { close(fd) }
    var addr = makeAddr(port)
    let sent = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            sendto(fd, msg, msg.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard sent == msg.count else { die("sendto") }
    let queryID = UInt16(msg[0]) << 8 | UInt16(msg[1])
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(fd, &buf, buf.count, 0)
        guard n >= 2 else { continue }
        let id = UInt16(buf[0]) << 8 | UInt16(buf[1])
        let flags = UInt16(buf[2]) << 8 | UInt16(buf[3])
        if id == queryID && (flags & 0x8000) != 0 {
            return Array(buf[0..<n])
        }
    }
}

func tcpExchange(_ msg: [UInt8], _ port: UInt16) -> [UInt8] {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    guard fd >= 0 else { die("socket") }
    defer { close(fd) }
    var addr = makeAddr(port)
    let c = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard c == 0 else { die("connect") }
    let out: [UInt8] = [UInt8((msg.count >> 8) & 0xFF), UInt8(msg.count & 0xFF)] + msg
    var allSent = false
    out.withUnsafeBufferPointer { bp in
        var p = bp.baseAddress!
        let end = p + out.count
        while p < end {
            let n = send(fd, p, end - p, 0)
            if n <= 0 { return }
            p += n
        }
        allSent = true
    }
    guard allSent else { die("tcp send") }
    var resp: [UInt8] = []
    var buf = [UInt8](repeating: 0, count: 65536)
    while resp.count < 2 {
        let n = recv(fd, &buf, buf.count, 0)
        guard n > 0 else { die("tcp recv") }
        resp += buf[0..<n]
    }
    let len = Int(resp[0]) << 8 | Int(resp[1])
    while resp.count < 2 + len {
        let n = recv(fd, &buf, buf.count, 0)
        guard n > 0 else { die("tcp recv2") }
        resp += buf[0..<n]
    }
    return Array(resp[2..<2 + len])
}

func process(_ resp: [UInt8], _ outName: String, _ typeStr: String) {
    guard resp.count >= 12 else { return }
    let flags = UInt16(resp[2]) << 8 | UInt16(resp[3])
    let qd = Int(resp[4]) << 8 | Int(resp[5])
    let an = Int(resp[6]) << 8 | Int(resp[7])
    let rcode = Int(flags & 0x000F)
    let rcodeStr: String
    switch rcode {
    case 0: rcodeStr = "NOERROR"
    case 1: rcodeStr = "FORMERR"
    case 2: rcodeStr = "SERVFAIL"
    case 3: rcodeStr = "NXDOMAIN"
    case 4: rcodeStr = "NOTIMP"
    case 5: rcodeStr = "REFUSED"
    default: rcodeStr = "RCODE\(rcode)"
    }
    print("\(outName) \(typeStr) \(rcodeStr)")
    var off = 12
    for _ in 0..<qd {
        guard off < resp.count else { return }
        let (_, o) = readName(resp, off)
        off = o + 4
        if off > resp.count { return }
    }
    for _ in 0..<an {
        guard off < resp.count else { break }
        let (owner, o) = readName(resp, off)
        off = o
        guard off + 10 <= resp.count else { break }
        let type = Int(resp[off]) << 8 | Int(resp[off + 1])
        let ttl = UInt32(resp[off + 4]) << 24 | UInt32(resp[off + 5]) << 16
            | UInt32(resp[off + 6]) << 8 | UInt32(resp[off + 7])
        let rdlen = Int(resp[off + 8]) << 8 | Int(resp[off + 9])
        off += 10
        guard off + rdlen <= resp.count else { break }
        let rdata = resp[off..<off + rdlen]
        off += rdlen
        let typeName: String
        switch type {
        case 1: typeName = "A"
        case 28: typeName = "AAAA"
        case 5: typeName = "CNAME"
        case 15: typeName = "MX"
        case 16: typeName = "TXT"
        default: typeName = "TYPE\(type)"
        }
        print("  \(owner) \(ttl) \(typeName) \(formatRData(resp, type, rdata))")
    }
}

for rawLine in fileText.components(separatedBy: "\n") {
    let line = rawLine.trimmingCharacters(in: .whitespaces)
    if line.isEmpty { continue }
    let parts = line.components(separatedBy: " ").filter { !$0.isEmpty }
    guard parts.count >= 2, let qtype = qtypeMap[parts[1].uppercased()] else { continue }
    let qname = parts[0]
    let typeStr = parts[1].uppercased()
    var outName = qname.lowercased()
    if outName.hasSuffix(".") { outName.removeLast() }
    if outName.isEmpty { outName = "." }

    var msg: [UInt8] = [0, 0, 0x01, 0x00, 0, 1, 0, 0, 0, 0, 0, 0]
    let id = UInt16.random(in: 0...UInt16.max)
    msg[0] = UInt8(id >> 8)
    msg[1] = UInt8(id & 0xFF)
    msg += encodeName(qname)
    msg += [UInt8(qtype >> 8), UInt8(qtype & 0xFF), 0, 1]

    var resp = udpExchange(msg, port)
    let rflags = UInt16(resp[2]) << 8 | UInt16(resp[3])
    if rflags & 0x0200 != 0 {
        resp = tcpExchange(msg, port)
    }
    process(resp, outName, typeStr)
}

exit(0)

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::process::exit;
use std::time::{SystemTime, UNIX_EPOCH};

fn g16(m: &[u8], o: usize) -> u16 {
    u16::from_be_bytes([m[o], m[o + 1]])
}
fn g32(m: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([m[o], m[o + 1], m[o + 2], m[o + 3]])
}

fn read_name(msg: &[u8], pos: &mut usize) -> String {
    let mut labels: Vec<String> = Vec::new();
    let mut cur = *pos;
    let mut jumped = false;
    let mut end = *pos;
    let mut guard = 0;
    loop {
        guard += 1;
        if guard > 200 || cur >= msg.len() {
            break;
        }
        let len = msg[cur];
        if len & 0xC0 == 0xC0 {
            if !jumped {
                end = cur + 2;
                jumped = true;
            }
            if cur + 1 >= msg.len() {
                break;
            }
            cur = (((len & 0x3F) as usize) << 8) | msg[cur + 1] as usize;
        } else if len == 0 {
            if !jumped {
                end = cur + 1;
            }
            break;
        } else {
            let s = cur + 1;
            let e = s + len as usize;
            if e > msg.len() {
                break;
            }
            labels.push(String::from_utf8_lossy(&msg[s..e]).to_lowercase());
            cur = e;
        }
    }
    *pos = end;
    if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    }
}

fn fmt_aaaa(b: &[u8]) -> String {
    let mut g = [0u16; 8];
    for i in 0..8 {
        g[i] = ((b[2 * i] as u16) << 8) | b[2 * i + 1] as u16;
    }
    let mut best = (0usize, 0usize);
    let mut i = 0;
    while i < 8 {
        if g[i] == 0 {
            let s = i;
            while i < 8 && g[i] == 0 {
                i += 1;
            }
            let l = i - s;
            if l >= 2 && l > best.1 {
                best = (s, l);
            }
        } else {
            i += 1;
        }
    }
    if best.1 == 0 {
        let parts: Vec<String> = g.iter().map(|x| format!("{:x}", x)).collect();
        return parts.join(":");
    }
    let before: Vec<String> = g[..best.0].iter().map(|x| format!("{:x}", x)).collect();
    let after: Vec<String> = g[best.0 + best.1..].iter().map(|x| format!("{:x}", x)).collect();
    format!("{}::{}", before.join(":"), after.join(":"))
}

fn esc_txt(s: &[u8]) -> String {
    let mut r = String::from("\"");
    for &c in s {
        match c {
            0x22 => r.push_str("\\\""),
            0x5c => r.push_str("\\\\"),
            0x20..=0x7e => r.push(c as char),
            _ => r.push_str(&format!("\\{:03}", c)),
        }
    }
    r.push('"');
    r
}

fn type_name(t: u16) -> String {
    match t {
        1 => "A".into(),
        5 => "CNAME".into(),
        15 => "MX".into(),
        16 => "TXT".into(),
        28 => "AAAA".into(),
        _ => format!("TYPE{}", t),
    }
}

fn rcode_name(r: u8) -> String {
    match r {
        0 => "NOERROR".into(),
        1 => "FORMERR".into(),
        2 => "SERVFAIL".into(),
        3 => "NXDOMAIN".into(),
        4 => "NOTIMP".into(),
        5 => "REFUSED".into(),
        _ => format!("RCODE{}", r),
    }
}

fn fmt_rdata(msg: &[u8], rtype: u16, rdata: &[u8]) -> String {
    match rtype {
        1 => {
            if rdata.len() >= 4 {
                format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3])
            } else {
                String::new()
            }
        }
        28 => {
            if rdata.len() >= 16 {
                fmt_aaaa(&rdata[..16])
            } else {
                String::new()
            }
        }
        5 => {
            let mut o = 0usize;
            read_name(msg, &mut o);
            let mut o2 = 0usize;
            let _ = o2;
            // re-read at rdata offset
            let mut p = 0usize;
            let _ = &mut p;
            // we need offset within message; handled by caller variant below
            unreachable!()
        }
        15 => {
            if rdata.len() >= 2 {
                let pref = ((rdata[0] as u16) << 8) | rdata[1] as u16;
                format!("{} {}", pref, mx_name(msg, rdata))
            } else {
                String::new()
            }
        }
        16 => {
            let mut parts = Vec::new();
            let mut i = 0usize;
            while i < rdata.len() {
                let l = rdata[i] as usize;
                if i + 1 + l > rdata.len() {
                    break;
                }
                parts.push(esc_txt(&rdata[i + 1..i + 1 + l]));
                i += 1 + l;
            }
            parts.join(" ")
        }
        _ => {
            let hex: Vec<String> = rdata.iter().map(|b| format!("{:02x}", b)).collect();
            if rdata.is_empty() {
                format!("\\# {}", rdata.len())
            } else {
                format!("\\# {} {}", rdata.len(), hex.join(" "))
            }
        }
    }
}

fn mx_name(msg: &[u8], rdata: &[u8]) -> String {
    // name starts at rdata[2], but compression refers to message offsets,
    // so we need the offset of rdata within msg; caller passes via global trick:
    unsafe { String::new() }
}

