    msg: Vec<u8>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        exit(2);
    }
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap_or_else(|_| exit(2));
    let data = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap_or_else(|_| exit(2));

    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .subsec_nanos() as u64
        ^ (SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs()
            << 20);

    let udp = UdpSocket::bind("0.0.0.0:0").unwrap();
    udp.connect(("127.0.0.1", port)).unwrap();

    for line in data.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let mut it = line.split_whitespace();
        let qname_in = it.next().unwrap_or("");
        let qtype_str = it.next().unwrap_or("A").to_uppercase();
        let qtype: u16 = match qtype_str.as_str() {
            "A" => 1,
            "CNAME" => 5,
            "MX" => 15,
            "TXT" => 16,
            "AAAA" => 28,
            _ => exit(2),
        };

        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let id = ((seed >> 33) & 0xFFFF) as u16;

        let base = qname_in.trim_end_matches('.');
        let labels: Vec<&str> = if base.is_empty() {
            Vec::new()
        } else {
            base.split('.').collect()
        };

        let mut q: Vec<u8> = Vec::new();
        q.extend_from_slice(&id.to_be_bytes());
        q.extend_from_slice(&[0x01, 0x00]);
        q.extend_from_slice(&[0, 1, 0, 0, 0, 0, 0, 0]);
        for l in &labels {
            q.push(l.len() as u8);
            q.extend_from_slice(l.as_bytes());
        }
        q.push(0);
        q.extend_from_slice(&qtype.to_be_bytes());
        q.extend_from_slice(&[0, 1]);

        let mut resp: Vec<u8>;
        loop {
            udp.send(&q).unwrap();
            let mut buf = [0u8; 65536];
            let mut got = false;
            resp = Vec::new();
            loop {
                let n = udp.recv(&mut buf).unwrap();
                if n >= 12 && buf[2] & 0x80 != 0 && buf[0] == (id >> 8) as u8 && buf[1] == (id & 0xFF) as u8 {
                    resp = buf[..n].to_vec();
                    got = true;
                    break;
                }
            }
            if !got {
                continue;
            }
            if resp[2] & 0x02 == 0 {
                break;
            }
            // TC: retry over TCP
            let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
            let mut framed = Vec::new();
            framed.extend_from_slice(&(q.len() as u16).to_be_bytes());
            framed.extend_from_slice(&q);
            stream.write_all(&framed).unwrap();
            let mut lenb = [0u8; 2];
            stream.read_exact(&mut lenb).unwrap();
            let len = u16::from_be_bytes(lenb) as usize;
            let mut tcpresp = vec![0u8; len];
            stream.read_exact(&mut tcpresp).unwrap();
            resp = tcpresp;
            break;
        }

        let rcode = resp[3] & 0x0F;
        let qdcount = g16(&resp, 4);
        let ancount = g16(&resp, 6);

        let out_name = if base.is_empty() {
            ".".to_string()
        } else {
            base.to_lowercase()
        };
        println!("{} {} {}", out_name, qtype_str, rcode_name(rcode));

        let mut off = 12usize;
        for _ in 0..qdcount {
            read_name(&resp, &mut off);
            off += 4;
        }
        for _ in 0..ancount {
            let owner = read_name(&resp, &mut off);
            if off + 10 > resp.len() {
                break;
            }
            let rtype = g16(&resp, off);
            let _class = g16(&resp, off + 2);
            let ttl = g32(&resp, off + 4);
            let rdlen = g16(&resp, off + 8) as usize;
            off += 10;
            if off + rdlen > resp.len() {
                break;
            }
            let rdata = &resp[off..off + rdlen];
            let rdata_off = off;
            off += rdlen;

            let data_str = match rtype {
                1 => {
                    if rdata.len() >= 4 {
                        format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3])
                    } else {
                        String::new()
                    }
                }
                28 => {
                    if rdata.len() >= 16 {
                        fmt_aaaa(&rdata[..16])
                    } else {
                        String::new()
                    }
                }
                5 => {
                    let mut p = rdata_off;
                    read_name(&resp, &mut p)
                }
                15 => {
                    if rdata.len() >= 2 {
                        let pref = ((rdata[0] as u16) << 8) | rdata[1] as u16;
                        let mut p = rdata_off + 2;
                        let name = read_name(&resp, &mut p);
                        format!("{} {}", pref, name)
                    } else {
                        String::new()
                    }
                }
                16 => {
                    let mut parts = Vec::new();
                    let mut i = 0usize;
                    while i < rdata.len() {
                        let l = rdata[i] as usize;
                        if i + 1 + l > rdata.len() {
                            break;
                        }
                        parts.push(esc_txt(&rdata[i + 1..i + 1 + l]));
                        i += 1 + l;
                    }
                    parts.join(" ")
                }
                _ => {
                    let hex: Vec<String> = rdata.iter().map(|b| format!("{:02x}", b)).collect();
                    if rdata.is_empty() {
                        format!("\\# {}", rdata.len())
                    } else {
                        format!("\\# {} {}", rdata.len(), hex.join(" "))
                    }
                }
            };
            println!("  {} {} {} {}", owner, ttl, type_name(rtype), data_str);
        }
    }
}

