import sys, json, os

def esc(t):
    return t.replace("~", "~0").replace("/", "~1")

def unesc(t):
    return t.replace("~1", "/").replace("~0", "~")

def ptr(tokens):
    return "#" + "".join("/" + esc(t) for t in tokens)

def is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def is_int_val(v):
    if isinstance(v, int):
        return True
    return v.is_integer()

def deq(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if is_num(a) and is_num(b):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(deq(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return set(a.keys()) == set(b.keys()) and all(deq(a[k], b[k]) for k in a)
    return False

def type_ok(inst, name):
    if name == "null":
        return inst is None
    if name == "boolean":
        return isinstance(inst, bool)
    if name == "object":
        return isinstance(inst, dict)
    if name == "array":
        return isinstance(inst, list)
    if name == "string":
        return isinstance(inst, str)
    if name == "number":
        return is_num(inst)
    if name == "integer":
        return is_num(inst) and is_int_val(inst)
    return False

def resolve(ref, root):
    if ref == "#":
        return root, []
    prefix = "#/$defs/"
    name = unesc(ref[len(prefix):])
    return root["$defs"][name], ["$defs", name]

def validate(inst, iloc, schema, sloc, root):
    if schema is True:
        return set()
    if schema is False:
        return {(ptr(iloc), ptr(sloc))}
    errors = set()

    def add(tok):
        errors.add((ptr(iloc), ptr(sloc + [tok])))

    def sub(child, tok, iloc2=None):
        return validate(child, iloc2 if iloc2 is not None else iloc,
                        schema[tok], sloc + [tok], root)

    # type
    if "type" in schema:
        t = schema["type"]
        names = [t] if isinstance(t, str) else t
        if not any(type_ok(inst, n) for n in names):
            add("type")
    # enum / const
    if "enum" in schema:
        if not any(deq(inst, e) for e in schema["enum"]):
            add("enum")
    if "const" in schema:
        if not deq(inst, schema["const"]):
            add("const")
    # numbers
    if is_num(inst):
        if "minimum" in schema and not (inst >= schema["minimum"]):
            add("minimum")
        if "maximum" in schema and not (inst <= schema["maximum"]):
            add("maximum")
        if "exclusiveMinimum" in schema and not (inst > schema["exclusiveMinimum"]):
            add("exclusiveMinimum")
        if "exclusiveMaximum" in schema and not (inst < schema["exclusiveMaximum"]):
            add("exclusiveMaximum")
    # strings
    if isinstance(inst, str):
        if "minLength" in schema and not (len(inst) >= schema["minLength"]):
            add("minLength")
        if "maxLength" in schema and not (len(inst) <= schema["maxLength"]):
            add("maxLength")
    # arrays
    if isinstance(inst, list):
        if "minItems" in schema and not (len(inst) >= schema["minItems"]):
            add("minItems")
        if "maxItems" in schema and not (len(inst) <= schema["maxItems"]):
            add("maxItems")
        if schema.get("uniqueItems") is True:
            n = len(inst)
            found = False
            for i in range(n):
                for j in range(i + 1, n):
                    if deq(inst[i], inst[j]):
                        found = True
                        break
                if found:
                    break
            if found:
                add("uniqueItems")
        start = 0
        if "prefixItems" in schema:
            pre = schema["prefixItems"]
            for i in range(min(len(inst), len(pre))):
                errors |= validate(inst[i], iloc + [str(i)], pre[i],
                                   sloc + ["prefixItems", str(i)], root)
            start = len(pre)
        if "items" in schema:
            for i in range(start, len(inst)):
                errors |= validate(inst[i], iloc + [str(i)], schema["items"],
                                   sloc + ["items"], root)
    # objects
    if isinstance(inst, dict):
        if "minProperties" in schema and not (len(inst) >= schema["minProperties"]):
            add("minProperties")
        if "maxProperties" in schema and not (len(inst) <= schema["maxProperties"]):
            add("maxProperties")
        if "required" in schema:
            for j, name in enumerate(schema["required"]):
                if name not in inst:
                    errors.add((ptr(iloc), ptr(sloc + ["required", str(j)])))
        if "properties" in schema:
            for name, subs in schema["properties"].items():
                if name in inst:
                    errors |= validate(inst[name], iloc + [name], subs,
                                       sloc + ["properties", name], root)
        if "additionalProperties" in schema:
            props = schema.get("properties", {})
            for name in inst:
                if name not in props:
                    errors |= validate(inst[name], iloc + [name],
                                       schema["additionalProperties"],
                                       sloc + ["additionalProperties"], root)
    # applicators
    if "allOf" in schema:
        for i, subs in enumerate(schema["allOf"]):
            errors |= validate(inst, iloc, subs, sloc + ["allOf", str(i)], root)
    if "anyOf" in schema:
        if not any(not validate(inst, iloc, s, sloc + ["anyOf", str(i)], root)
                   for i, s in enumerate(schema["anyOf"])):
            add("anyOf")
    if "oneOf" in schema:
        count = sum(1 for s in schema["oneOf"]
                    if not validate(inst, iloc, s, sloc + ["oneOf", str(i)], root)
                    for i in [schema["oneOf"].index(s)])
        # recompute properly
        count = 0
        for i, s in enumerate(schema["oneOf"]):
            if not validate(inst, iloc, s, sloc + ["oneOf", str(i)], root):
                count += 1
        if count != 1:
            add("oneOf")
    if "not" in schema:
        if not validate(inst, iloc, schema["not"], sloc + ["not"], root):
            add("not")
    if "if" in schema:
        ok = not validate(inst, iloc, schema["if"], sloc + ["if"], root)
        if ok and "then" in schema:
            errors |= validate(inst, iloc, schema["then"], sloc + ["then"], root)
        if not ok and "else" in schema:
            errors |= validate(inst, iloc, schema["else"], sloc + ["else"], root)
    if "$ref" in schema:
        target, tloc = resolve(schema["$ref"], root)
        errors |= validate(inst, iloc, target, tloc, root)
    return errors

