import * as fs from 'fs';
import * as path from 'path';

const SCALE = 10n ** 20n;

function parseNum(s: string): bigint {
  const m = /^(-?)(\d+)(?:\.(\d+))?$/.exec(s);
  if (!m) throw new Error('bad number: ' + s);
  const sign = m[1] === '-' ? -1n : 1n;
  let frac = m[3] ?? '';
  frac = (frac + '0'.repeat(20)).slice(0, 20);
  return sign * BigInt(m[2] + frac);
}

// round-half-even to d decimal places; v is scaled by 1e20
function roundScaled(v: bigint, d: number): bigint {
  const unit = 10n ** BigInt(20 - d);
  const neg = v < 0n;
  const a = neg ? -v : v;
  let q = a / unit;
  const r = a % unit;
  const r2 = r * 2n;
  if (r2 > unit || (r2 === unit && (q & 1n) === 1n)) q += 1n;
  return neg ? -q : q;
}

function group(s: string): string {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (i > 0 && (s.length - i) % 3 === 0) out += ',';
    out += s[i];
  }
  return out;
}

function fmt(v: bigint, d: number): string {
  v = roundScaled(v, d);
  const neg = v < 0n;
  const a = neg ? -v : v;
  const ip = a / SCALE;
  const fp = d > 0 ? (a / 10n ** BigInt(20 - d)) % 10n ** BigInt(d) : 0n;
  let s = group(ip.toString());
  if (d > 0) s += '.' + fp.toString().padStart(d, '0');
  return (neg && a !== 0n ? '-' : '') + s;
}

function main(): void {
  const dir = process.argv[2];
  const text = fs.readFileSync(path.join(dir, 'ledger.txt'), 'utf8');
  const lines = text.split('\n');

  const decimals = new Map<string, number>();
  const accounts = new Map<string, { code: string; balance: bigint; limit: bigint }>();
  const rejects: string[] = [];

  lines.forEach((raw, idx) => {
    const lineNo = idx + 1;
    const t = raw.trim();
    if (t === '' || t.startsWith('#')) return;
    const f = t.split(/\s+/);
    const cmd = f[0];
    const reject = (reason: string) => rejects.push(`line ${lineNo}: REJECT ${reason}`);

    if (cmd === 'currency') {
      decimals.set(f[1], parseInt(f[2], 10));
      return;
    }

    if (cmd === 'open') {
      const name = f[1];
      const code = f[2];
      if (accounts.has(name)) {
        reject(`account exists ${name}`);
        return;
      }
      const d = decimals.get(code) ?? 0;
      const limit = f[3] !== undefined ? roundScaled(parseNum(f[3]), d) : 0n;
      accounts.set(name, { code, balance: 0n, limit });
      return;
    }

    if (cmd === 'deposit' || cmd === 'withdraw') {
      const name = f[1];
      if (!accounts.has(name)) {
        reject(`unknown account ${name}`);
        return;
      }
      const acc = accounts.get(name)!;
      const d = decimals.get(acc.code) ?? 0;
      const amt = roundScaled(parseNum(f[2]), d);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (cmd === 'deposit') {
        acc.balance += amt;
      } else {
        if (acc.balance - amt < -acc.limit) {
          reject(`insufficient funds ${name}`);
          return;
        }
        acc.balance -= amt;
      }
      return;
    }

    if (cmd === 'transfer') {
      const from = f[1], to = f[2];
      for (const n of [from, to]) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const a1 = accounts.get(from)!, a2 = accounts.get(to)!;
      if (a1.code !== a2.code) {
        reject('currency mismatch');
        return;
      }
      const d = decimals.get(a1.code) ?? 0;
      const amt = roundScaled(parseNum(f[3]), d);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (a1.balance - amt < -a1.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      a1.balance -= amt;
      a2.balance += amt;
      return;
    }

    if (cmd === 'convert') {
      const from = f[1], to = f[2];
      for (const n of [from, to]) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const a1 = accounts.get(from)!, a2 = accounts.get(to)!;
      const d1 = decimals.get(a1.code) ?? 0;
      const d2 = decimals.get(a2.code) ?? 0;
      const amt = roundScaled(parseNum(f[3]), d1);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (a1.balance - amt < -a1.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      const rate = parseNum(f[4]);
      const received = roundScaled((amt * rate) / SCALE, d2);
      a1.balance -= amt;
      a2.balance += received;
      return;
    }

    if (cmd === 'interest') {
      const name = f[1];
      if (!accounts.has(name)) {
        reject(`unknown account ${name}`);
        return;
      }
      const acc = accounts.get(name)!;
      const d = decimals.get(acc.code) ?? 0;
      const rate = parseNum(f[2]);
      acc.balance += roundScaled((acc.balance * rate) / SCALE, d);
      return;
    }

    if (cmd === 'split') {
      const from = f[1];
      const targets: { name: string; w: bigint }[] = [];
      for (let i = 3; i < f.length; i++) {
        const ci = f[i].lastIndexOf(':');
        targets.push({ name: f[i].slice(0, ci), w: BigInt(f[i].slice(ci + 1)) });
      }
      const checkOrder = [from, ...targets.map((x) => x.name)];
      for (const n of checkOrder) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const aFrom = accounts.get(from)!;
      const d = decimals.get(aFrom.code) ?? 0;
      for (const tg of targets) {
        if (accounts.get(tg.name)!.code !== aFrom.code) {
          reject('currency mismatch');
          return;
        }
      }
      const amt = roundScaled(parseNum(f[2]), d);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (aFrom.balance - amt < -aFrom.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      const unit = 10n ** BigInt(20 - d);
      const A = amt / unit; // exact: amt is a multiple of unit
      const W = targets.reduce((s, x) => s + x.w, 0n);
      const floors = targets.map((x) => (A * x.w) / W);
      const rems = targets.map((x) => (A * x.w) % W);
      let leftover = A - floors.reduce((s, x) => s + x, 0n);
      const order = targets.map((_, i) => i).sort((a, b) => {
        if (rems[a] !== rems[b]) return rems[a] > rems[b] ? -1 : 1;
        return a - b;
      });
      const extra = targets.map(() => 0n);
      for (let i = 0; i < order.length && leftover > 0n; i++, leftover -= 1n) {
        extra[order[i]] += 1n;
      }
      aFrom.balance -= amt;
      targets.forEach((tg, i) => {
        accounts.get(tg.name)!.balance += (floors[i] + extra[i]) * unit;
      });
      return;
    }
  });

  const out: string[] = [];
  out.push(...rejects);
  out.push('');

  const names = [...accounts.keys()].sort();
  for (const n of names) {
    const acc = accounts.get(n)!;
    out.push(`${n} ${acc.code} ${fmt(acc.balance, decimals.get(acc.code) ?? 0)}`);
  }
  out.push('');

  const totals = new Map<string, { sum: bigint; count: number }>();
  for (const n of names) {
    const acc = accounts.get(n)!;
    const e = totals.get(acc.code) ?? { sum: 0n, count: 0 };
    e.sum += acc.balance;
    e.count += 1;
    totals.set(acc.code, e);
  }
  for (const code of [...totals.keys()].sort()) {
    const e = totals.get(code)!;
    out.push(`total ${code} ${fmt(e.sum, decimals.get(code) ?? 0)} (${e.count} accounts)`);
  }

  process.stdout.write(out.join('\n') + '\n');
}

main();

