const SCALE = 10n ** 12n; // numbers parsed with 12 decimal places (rates need up to 12)

function parseNum(s: string): bigint {
  const m = /^(-?)(\d+)(?:\.(\d))?$/.exec(s);
  if (!m) throw new Error('bad number: ' + s);
  const frac = ((m[3] ?? '') + '000000000000').slice(0, 12);
  return BigInt((m[1] === '-' ? '-' : '') + m[2] + frac);
}

// round a/b to nearest integer, half-even; b > 0
function halfEvenDiv(a: bigint, b: bigint): bigint {
  const neg = a < 0n;
  const n = neg ? -a : a;
  let q = n / b;
  const r = n % b;
  const r2 = r * 2n;
  if (r2 > b || (r2 === b && (q & 1n) === 1n)) q += 1n;
  return neg ? -q : q;
}

// v is scaled by 1e12; round to d decimal places, return minor units (integer)
function toMinor(v: bigint, d: number): bigint {
  return halfEvenDiv(v, 10n ** BigInt(12 - d));
}

function group(s: string): string {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (i > 0 && (s.length - i) % 3 === 0) out += ',';
    out += s[i];
  }
  return out;
}

