    }

    if (cmd === 'transfer') {
      const from = f[1], to = f[2];
      for (const n of [from, to]) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const a1 = accounts.get(from)!, a2 = accounts.get(to)!;
      if (a1.code !== a2.code) {
        reject('currency mismatch');
        return;
      }
      const d = decimals.get(a1.code) ?? 0;
      const amt = toMinor(parseNum(f[3]), d);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (a1.balance - amt < -a1.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      a1.balance -= amt;
      a2.balance += amt;
      return;
    }

    if (cmd === 'convert') {
      const from = f[1], to = f[2];
      for (const n of [from, to]) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const a1 = accounts.get(from)!, a2 = accounts.get(to)!;
      const d1 = decimals.get(a1.code) ?? 0;
      const d2 = decimals.get(a2.code) ?? 0;
      const amt = toMinor(parseNum(f[3]), d1);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (a1.balance - amt < -a1.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      const rate = parseNum(f[4]);
      // value in to-minor units = amt * rate * 10^(d2-d1), with rate scaled by 1e12
      const received = halfEvenDiv(amt * rate * 10n ** BigInt(d2), 10n ** BigInt(12 + d1));
      a1.balance -= amt;
      a2.balance += received;
      return;
    }

    if (cmd === 'interest') {
      const name = f[1];
      if (!accounts.has(name)) {
        reject(`unknown account ${name}`);
        return;
      }
      const acc = accounts.get(name)!;
      const rate = parseNum(f[2]);
      acc.balance += halfEvenDiv(acc.balance * rate, SCALE);
      return;
    }

    if (cmd === 'split') {
      const from = f[1];
      const targets: { name: string; w: bigint }[] = [];
      for (let i = 3; i < f.length; i++) {
        const ci = f[i].lastIndexOf(':');
        targets.push({ name: f[i].slice(0, ci), w: BigInt(f[i].slice(ci + 1)) });
      }
      for (const n of [from, ...targets.map((x) => x.name)]) {
        if (!accounts.has(n)) {
          reject(`unknown account ${n}`);
          return;
        }
      }
      const aFrom = accounts.get(from)!;
      const d = decimals.get(aFrom.code) ?? 0;
      for (const tg of targets) {
        if (accounts.get(tg.name)!.code !== aFrom.code) {
          reject('currency mismatch');
          return;
        }
      }
      const amt = toMinor(parseNum(f[2]), d);
      if (amt <= 0n) {
        reject('non-positive amount');
        return;
      }
      if (aFrom.balance - amt < -aFrom.limit) {
        reject(`insufficient funds ${from}`);
        return;
      }
      const A = amt;
      const W = targets.reduce((s, x) => s + x.w, 0n);
      const floors = targets.map((x) => (A * x.w) / W);
      const rems = targets.map((x) => (A * x.w) % W);
      let leftover = A - floors.reduce((s, x) => s + x, 0n);
      const order = targets.map((_, i) => i).sort((a, b) => {
        if (rems[a] !== rems[b]) return rems[a] > rems[b] ? -1 : 1;
        return a - b;
      });
      const extra = targets.map(() => 0n);
      for (let i = 0; i < order.length && leftover > 0n; i++, leftover -= 1n) {
        extra[order[i]] += 1n;
      }
      aFrom.balance -= amt;
      targets.forEach((tg, i) => {
        accounts.get(tg.name)!.balance += floors[i] + extra[i];
      });
      return;
    }
  });

  const out: string[] = [];
  out.push(...rejects);
  out.push('');

  const names = [...accounts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const n of names) {
    const acc = accounts.get(n)!;
    out.push(`${n} ${acc.code} ${fmt(acc.balance, decimals.get(acc.code) ?? 0)}`);
  }
  out.push('');

  const totals = new Map<string, { sum: bigint; count: number }>();
  for (const n of names) {
    const acc = accounts.get(n)!;
    const e = totals.get(acc.code) ?? { sum: 0n, count: 0 };
    e.sum += acc.balance;
    e.count += 1;
    totals.set(acc.code, e);
  }
  for (const code of [...totals.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const e = totals.get(code)!;
    out.push(`total ${code} ${fmt(e.sum, decimals.get(code) ?? 0)} (${e.count} accounts)`);
  }

  process.stdout.write(out.join('\n') + '\n');
}

main();

use std::env;
use std::fs;
use std::collections::{HashMap, BTreeMap};
use std::cmp::Ordering;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, PartialEq, Eq)]
struct Big {
    neg: bool,
    d: Vec<u32>, // little-endian, base 1e9, normalized (no trailing zeros)
}

fn big_zero() -> Big { Big { neg: false, d: vec![] } }
fn big_from_u64(mut x: u64) -> Big {
    let mut d = vec![];
    while x > 0 { d.push((x % BASE) as u32); x /= BASE; }
    Big { neg: false, d }
}
fn is_zero(a: &Big) -> bool { a.d.is_empty() }

fn norm(d: &mut Vec<u32>) { while d.last() == Some(&0) { d.pop(); } }

fn cmp_mag(a: &[u32], b: &[u32]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in (0..a.len()).rev() {
        if a[i] != b[i] { return a[i].cmp(&b[i]); }
    }
    Ordering::Equal
}

fn add_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u64;
    for i in 0..a.len().max(b.len()) {
        let x = *a.get(i).unwrap_or(&0) as u64 + *b.get(i).unwrap_or(&0) as u64 + carry;
        r.push((x % BASE) as u32);
        carry = x / BASE;
    }
    if carry > 0 { r.push(carry as u32); }
    r
}

fn sub_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for i in 0..a.len() {
        let x = a[i] as i64 - *b.get(i).unwrap_or(&0) as i64 - borrow;
        if x < 0 { r.push((x + BASE as i64) as u32); borrow = 1; }
        else { r.push(x as u32); borrow = 0; }
    }
    norm(&mut r);
    r
}

fn mul_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    if a.is_empty() || b.is_empty() { return vec![]; }
    let mut r = vec![0u32; a.len() + b.len()];
    for i in 0..a.len() {
        let mut carry = 0u64;
        for j in 0..b.len() {
            let cur = r[i + j] as u64 + a[i] as u64 * b[j] as u64 + carry;
            r[i + j] = (cur % BASE) as u32;
            carry = cur / BASE;
        }
        let mut k = i + b.len();
        while carry > 0 {
            let cur = r[k] as u64 + carry;
            r[k] = (cur % BASE) as u32;
            carry = cur / BASE;
            k += 1;
        }
    }
    norm(&mut r);
    r
}

fn mul_small(a: &[u32], m: u32) -> Vec<u32> {
    if a.is_empty() || m == 0 { return vec![]; }
    let mut r = Vec::with_capacity(a.len() + 1);
    let mut carry = 0u64;
    for &x in a {
        let cur = x as u64 * m as u64 + carry;
        r.push((cur % BASE) as u32);
        carry = cur / BASE;
    }
    while carry > 0 { r.push((carry % BASE) as u32); carry /= BASE; }
    r
}

fn divmod_mag(a: &[u32], b: &[u32]) -> (Vec<u32>, Vec<u32>) {
    if cmp_mag(a, b) == Ordering::Less { return (vec![], a.to_vec()); }
    if b.len() == 1 {
        let dv = b[0] as u64;
        let mut q = vec![0u32; a.len()];
        let mut r = 0u64;
        for i in (0..a.len()).rev() {
            let cur = r * BASE + a[i] as u64;
            q[i] = (cur / dv) as u32;
            r = cur % dv;
        }
        norm(&mut q);
        return (q, vec![r as u32]);
    }
    // normalize divisor so top digit >= BASE/2
    let top = *b.last().unwrap() as u64;
    let s = (BASE / (top + 1)) as u32;
    let an = mul_small(a, s);
    let bn = mul_small(b, s);
    let mut q = vec![0u32; an.len()];
    let mut rem: Vec<u32> = vec![];
    let dbn = *bn.last().unwrap() as u128;
    for i in (0..an.len()).rev() {
        rem.insert(0, an[i]);
        while rem.last() == Some(&0) { rem.pop(); }
        let qh: u128 = if cmp_mag(&rem, &bn) == Ordering::Less {
            0
        } else {
            let m = rem.len();
            let t: u128 = (rem[m - 1] as u128) * BASE as u128 + rem[m - 2] as u128;
            let mut qh = t / dbn;
            if qh > BASE as u128 - 1 { qh = BASE as u128 - 1; }
            qh
        };
        let mut qh = qh;
        loop {
            let prod = mul_small(&bn, qh as u32);
            if cmp_mag(&prod, &rem) == Ordering::Greater { qh -= 1; } else { break; }
        }
        q[i] = qh as u32;
        let prod = mul_small(&bn, qh as u32);
        rem = sub_mag(&rem, &prod);
    }
    norm(&mut q);
    let (r, _) = divmod_mag(&rem, &[s]);
    (q, r)
}

impl Big {
    fn neg_of(&self) -> Big {
        if self.d.is_empty() { self.clone() } else { Big { neg: !self.neg, d: self.d.clone() } }
    }
}

fn add(a: &Big, b: &Big) -> Big {
    if a.neg == b.neg {
        let d = add_mag(&a.d, &b.d);
        Big { neg: a.neg && !d.is_empty(), d }
    } else {
        match cmp_mag(&a.d, &b.d) {
            Ordering::Equal => big_zero(),
            Ordering::Greater => { let d = sub_mag(&a.d, &b.d); Big { neg: a.neg, d } }
            Ordering::Less => { let d = sub_mag(&b.d, &a.d); Big { neg: b.neg, d } }
        }
    }
}

fn sub(a: &Big, b: &Big) -> Big { add(a, &b.neg_of()) }

fn mul(a: &Big, b: &Big) -> Big {
    let d = mul_mag(&a.d, &b.d);
    Big { neg: a.neg != b.neg && !d.is_empty(), d }
}

fn divmod_trunc(a: &Big, b: &Big) -> (Big, Big) {
    let (q, r) = divmod_mag(&a.d, &b.d);
    (Big { neg: a.neg != b.neg && !q.is_empty(), d: q },
     Big { neg: a.neg && !r.is_empty(), d: r })
}

fn floor_divmod(a: &Big, b: &Big) -> (Big, Big) {
    let (q, r) = divmod_trunc(a, b);
    if !is_zero(&r) && (a.neg != b.neg) {
        (sub(&q, &big_from_u64(1)), sub(b, &r))
    } else {
        (q, r)
    }
}

fn cmp(a: &Big, b: &Big) -> Ordering {
    match (a.neg, b.neg) {
        (false, false) => cmp_mag(&a.d, &b.d),
        (true, true) => cmp_mag(&b.d, &a.d),
        (true, false) => if is_zero(a) && is_zero(b) { Ordering::Equal } else { Ordering::Less },
        (false, true) => if is_zero(a) && is_zero(b) { Ordering::Equal } else { Ordering::Greater },
    }
}

fn mul_pow10(v: &Big, k: u32) -> Big {
    let mut d = v.d.clone();
    let mut k = k;
    while k > 0 {
        let m = k.min(9);
        d = mul_small(&d, 10u64.pow(m) as u32);
        k -= m;
    }
    Big { neg: v.neg && !d.is_empty(), d }
}

fn pow10(k: u32) -> Big { mul_pow10(&big_from_u64(1), k) }

// Round value v (scale s) to d decimal places, round-half-even.
fn round_to(v: &Big, s: u32, d: u32) -> Big {
    if s <= d { return mul_pow10(v, d - s); }
    let p = pow10(s - d);
    let (q, r) = divmod_trunc(v, &p);
    let r2 = add(&r, &r);
    let up = match cmp_mag(&r2.d, &p.d) {
        Ordering::Greater => true,
        Ordering::Equal => !q.d.is_empty() && (q.d[0] & 1 == 1),
        Ordering::Less => false,
    };
    let mut qd = q.d;
    if up { qd = add_mag(&qd, &[1]); }
    Big { neg: v.neg && !qd.is_empty(), d: qd }
}

fn digits_to_big(ds: &str) -> Big {
    let ds = ds.trim_start_matches('0');
    let mut d = vec![];
    let b = ds.as_bytes();
    let mut i = b.len();
    while i > 0 {
        let start = i.saturating_sub(9);
        d.push(ds[start..i].parse::<u32>().unwrap());
        i = start;
    }
    Big { neg: false, d }
}

fn parse_dec(s: &str) -> (Big, u32) {
    let mut t = s;
    let mut neg = false;
    if let Some(r) = t.strip_prefix('-') { neg = true; t = r; }
    let (i, f) = match t.find('.') {
        Some(i) => (&t[..i], &t[i + 1..]),
        None => (t, ""),
    };
    let mut ds = i.to_string();
    ds.push_str(f);
    let mut b = digits_to_big(&ds);
    if neg && !b.d.is_empty() { b.neg = true; }
    (b, f.len() as u32)
}

fn big_to_decstr(d: &[u32]) -> String {
    if d.is_empty() { return "0".to_string(); }
    let mut s = d[d.len() - 1].to_string();
    for i in (0..d.len() - 1).rev() { s.push_str(&format!("{:09}", d[i])); }
    s
}

fn group(ip: &str) -> String {
    let n = ip.len();
    let mut r = String::new();
    for (i, c) in ip.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { r.push(','); }
        r.push(c);
    }
    r
}

fn fmt(v: &Big, dec: u32) -> String {
    let mut ds = big_to_decstr(&v.d);
    let neg = v.neg && !v.d.is_empty();
    let ip;
    let fp;
    if dec > 0 {
        while ds.len() < dec as usize + 1 { ds.insert(0, '0'); }
        let split = ds.len() - dec as usize;
        ip = group(&ds[..split]);
        fp = ds[split..].to_string();
    } else {
        ip = group(&ds);
        fp = String::new();
    }
    let mut s = String::new();
    if neg { s.push('-'); }
    s.push_str(&ip);
    if dec > 0 { s.push('.'); s.push_str(&fp); }
    s
}

struct Account {
    code: String,
    bal: Big,
    limit: Big,
}

fn funds_check(accts: &HashMap<String, Account>, name: &str, amt: &Big) -> bool {
    let a = &accts[name];
    let avail = add(&a.bal, &a.limit);
    cmp(&sub(&avail, amt), &big_zero()) != Ordering::Less
}

fn process(f: &[&str], curs: &HashMap<String, u32>, accts: &mut HashMap<String, Account>) -> Result<(), String> {
    match f[0] {
        "currency" => {
            curs.insert(f[1].to_string(), f[2].parse::<u32>().unwrap());
            Ok(())
        }
        "open" => {
            let name = f[1];
            if accts.contains_key(name) { return Err(format!("account exists {}", name)); }
            let dec = *curs.get(f[2]).unwrap_or(&0);
            let limit = if f.len() > 3 {
                let (v, s) = parse_dec(f[3]);
                round_to(&v, s, dec)
            } else { big_zero() };
            accts.insert(name.to_string(), Account { code: f[2].to_string(), bal: big_zero(), limit });
            Ok(())
        }
        "deposit" | "withdraw" => {
            let name = f[1];
            if !accts.contains_key(name) { return Err(format!("unknown account {}", name)); }
            let dec = *curs.get(&accts[name].code).unwrap();
            let (v, s) = parse_dec(f[2]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if f[0] == "withdraw" {
                if !funds_check(accts, name, &amt) { return Err(format!("insufficient funds {}", name)); }
                let a = accts.get_mut(name).unwrap();
                a.bal = sub(&a.bal, &amt);
            } else {
                let a = accts.get_mut(name).unwrap();
                a.bal = add(&a.bal, &amt);
            }
            Ok(())
        }
        "transfer" => {
            for n in [f[1], f[2]] {
                if !accts.contains_key(n) { return Err(format!("unknown account {}", n)); }
            }
            if accts[f[1]].code != accts[f[2]].code { return Err("currency mismatch".into()); }
            let dec = *curs.get(&accts[f[1]].code).unwrap();
            let (v, s) = parse_dec(f[3]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, f[1], &amt) { return Err(format!("insufficient funds {}", f[1])); }
            let fb;
            { let a = accts.get_mut(f[1]).unwrap(); fb = sub(&a.bal, &amt); }
            let tb;
            { let a = accts.get_mut(f[2]).unwrap(); tb = add(&a.bal, &amt); }
            accts.get_mut(f[1]).unwrap().bal = fb;
            accts.get_mut(f[2]).unwrap().bal = tb;
            Ok(())
        }
        "convert" => {
            for n in [f[1], f[2]] {
                if !accts.contains_key(n) { return Err(format!("unknown account {}", n)); }
            }
            let dfrom = *curs.get(&accts[f[1]].code).unwrap();
            let dto = *curs.get(&accts[f[2]].code).unwrap();
            let (v, s) = parse_dec(f[3]);
            let amt = round_to(&v, s, dfrom);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, f[1], &amt) { return Err(format!("insufficient funds {}", f[1])); }
            let (rv, rs) = parse_dec(f[4]);
            let prod = mul(&amt, &rv);
            let toamt = round_to(&prod, dfrom + rs, dto);
            let fb;
            { let a = accts.get_mut(f[1]).unwrap(); fb = sub(&a.bal, &amt); }
            let tb;
            { let a = accts.get_mut(f[2]).unwrap(); tb = add(&a.bal, &toamt); }
            accts.get_mut(f[1]).unwrap().bal = fb;
            accts.get_mut(f[2]).unwrap().bal = tb;
            Ok(())
        }
        "interest" => {
            let name = f[1];
            if !accts.contains_key(name) { return Err(format!("unknown account {}", name)); }
            let dec = *curs.get(&accts[name].code).unwrap();
            let (rv, rs) = parse_dec(f[2]);
            let a = accts.get_mut(name).unwrap();
            let prod = mul(&a.bal, &rv);
            let delta = round_to(&prod, dec + rs, dec);
            a.bal = add(&a.bal, &delta);
            Ok(())
        }
        "split" => {
            let from = f[1];
            let mut tnames: Vec<&str> = vec![];
            let mut weights: Vec<Big> = vec![];
            for tok in &f[3..] {
                let p: Vec<&str> = tok.split(':').collect();
                tnames.push(p[0]);
                weights.push(parse_dec(p[1]).0);
            }
            if !accts.contains_key(from) { return Err(format!("unknown account {}", from)); }
            for n in &tnames {
                if !accts.contains_key(n) { return Err(format!("unknown account {}", n)); }
            }
            let code = accts[from].code.clone();
            for n in &tnames {
                if accts[*n].code != code { return Err("currency mismatch".into()); }
            }
            let dec = *curs.get(&code).unwrap();
            let (v, s) = parse_dec(f[2]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, from, &amt) { return Err(format!("insufficient funds {}", from)); }
            let wsum = weights.iter().fold(big_zero(), |a, w| add(&a, w));
            let mut qs = vec![];
            let mut rs = vec![];
            for w in &weights {
                let (q, r) = floor_divmod(&mul(&amt, w), &wsum);
                qs.push(q);
                rs.push(r);
            }
            let sumq = qs.iter().fold(big_zero(), |a, x| add(&a, x));
            let leftover = sub(&amt, &sumq);
            let mut order: Vec<usize> = (0..tnames.len()).collect();
            order.sort_by(|&a, &b| cmp(&rs[b], &rs[a]));
            let fb;
            { let a = accts.get_mut(from).unwrap(); fb = sub(&a.bal, &amt); }
            accts.get_mut(from).unwrap().bal = fb;
            let mut newbals = vec![];
            for i in 0..tnames.len() {
                let a = accts.get_mut(tnames[i]).unwrap();
                newbals.push(add(&a.bal, &qs[i]));
            }
            for i in 0..tnames.len() {
                accts.get_mut(tnames[i]).unwrap().bal = newbals[i].clone();
            }
            let lo = if leftover.d.is_empty() { 0usize } else { leftover.d[0] as usize };
            for i in 0..lo {
                let a = accts.get_mut(tnames[order[i]]).unwrap();
                a.bal = add(&a.bal, &big_from_u64(1));
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let path = format!("{}/ledger.txt", args[1]);
    let content = fs::read_to_string(&path).unwrap();
    let mut rejects: Vec<String> = vec![];
    let mut curs: HashMap<String, u32> = HashMap::new();
    let mut accts: HashMap<String, Account> = HashMap::new();
    for (idx, line) in content.lines().enumerate() {
        let n = idx + 1;
        let t = line.trim_start();
        if t.is_empty() || t.starts_with('#') { continue; }
        let f: Vec<&str> = t.split_whitespace().collect();
        if let Err(r) = process(&f, &curs, &mut accts) {
            rejects.push(format!("line {}: REJECT {}", n, r));
        }
    }
    for r in &rejects { println!("{}", r); }
    println!();
    let mut names: Vec<String> = accts.keys().cloned().collect();
    names.sort();
    for name in &names {
        let a = &accts[name];
        println!("{} {} {}", name, a.code, fmt(&a.bal, curs[&a.code]));
    }
    println!();
    let mut totals: BTreeMap<String, (Big, usize)> = BTreeMap::new();
    for a in accts.values() {
        let e = totals.entry(a.code.clone()).or_insert((big_zero(), 0));
        e.0 = add(&e.0, &a.bal);
        e.1 += 1;
    }
    for (code, (sum, cnt)) in &totals {
        println!("total {} {} ({} accounts)", code, fmt(sum, curs[code]), cnt);
    }
}

use std::env;
use std::fs;
use std::collections::{HashMap, BTreeMap};
use std::cmp::Ordering;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, PartialEq, Eq)]
struct Big {
    neg: bool,
    d: Vec<u32>, // little-endian, base 1e9, normalized (no trailing zeros)
}

fn big_zero() -> Big { Big { neg: false, d: vec![] } }
fn big_from_u64(mut x: u64) -> Big {
    let mut d = vec![];
    while x > 0 { d.push((x % BASE) as u32); x /= BASE; }
    Big { neg: false, d }
}
fn is_zero(a: &Big) -> bool { a.d.is_empty() }

fn norm(d: &mut Vec<u32>) { while d.last() == Some(&0) { d.pop(); } }

fn cmp_mag(a: &[u32], b: &[u32]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in (0..a.len()).rev() {
        if a[i] != b[i] { return a[i].cmp(&b[i]); }
    }
    Ordering::Equal
}

fn add_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u64;
    for i in 0..a.len().max(b.len()) {
        let x = *a.get(i).unwrap_or(&0) as u64 + *b.get(i).unwrap_or(&0) as u64 + carry;
        r.push((x % BASE) as u32);
        carry = x / BASE;
    }
    if carry > 0 { r.push(carry as u32); }
    r
}

fn sub_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for i in 0..a.len() {
        let x = a[i] as i64 - *b.get(i).unwrap_or(&0) as i64 - borrow;
        if x < 0 { r.push((x + BASE as i64) as u32); borrow = 1; }
        else { r.push(x as u32); borrow = 0; }
    }
    norm(&mut r);
    r
}

fn mul_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    if a.is_empty() || b.is_empty() { return vec![]; }
    let mut r = vec![0u32; a.len() + b.len()];
    for i in 0..a.len() {
        let mut carry = 0u64;
        for j in 0..b.len() {
            let cur = r[i + j] as u64 + a[i] as u64 * b[j] as u64 + carry;
            r[i + j] = (cur % BASE) as u32;
            carry = cur / BASE;
        }
        let mut k = i + b.len();
        while carry > 0 {
            let cur = r[k] as u64 + carry;
            r[k] = (cur % BASE) as u32;
            carry = cur / BASE;
            k += 1;
        }
    }
    norm(&mut r);
    r
}

fn mul_small(a: &[u32], m: u32) -> Vec<u32> {
    if a.is_empty() || m == 0 { return vec![]; }
    let mut r = Vec::with_capacity(a.len() + 1);
    let mut carry = 0u64;
    for &x in a {
        let cur = x as u64 * m as u64 + carry;
        r.push((cur % BASE) as u32);
        carry = cur / BASE;
    }
    while carry > 0 { r.push((carry % BASE) as u32); carry /= BASE; }
    r
}

fn divmod_mag(a: &[u32], b: &[u32]) -> (Vec<u32>, Vec<u32>) {
    if cmp_mag(a, b) == Ordering::Less { return (vec![], a.to_vec()); }
    if b.len() == 1 {
        let dv = b[0] as u64;
        let mut q = vec![0u32; a.len()];
        let mut r = 0u64;
        for i in (0..a.len()).rev() {
            let cur = r * BASE + a[i] as u64;
            q[i] = (cur / dv) as u32;
            r = cur % dv;
        }
        norm(&mut q);
        return (q, vec![r as u32]);
    }
    let top = *b.last().unwrap() as u64;
    let s = (BASE / (top + 1)) as u32;
    let an = mul_small(a, s);
    let bn = mul_small(b, s);
    let mut q = vec![0u32; an.len()];
    let mut rem: Vec<u32> = vec![];
    let dbn = *bn.last().unwrap() as u128;
    for i in (0..an.len()).rev() {
        rem.insert(0, an[i]);
        while rem.last() == Some(&0) { rem.pop(); }
        let qh: u128 = if cmp_mag(&rem, &bn) == Ordering::Less {
            0
        } else {
            let m = rem.len();
            let t: u128 = (rem[m - 1] as u128) * BASE as u128 + rem[m - 2] as u128;
            let mut qh = t / dbn;
            if qh > BASE as u128 - 1 { qh = BASE as u128 - 1; }
            qh
        };
        let mut qh = qh;
        loop {
            let prod = mul_small(&bn, qh as u32);
            if cmp_mag(&prod, &rem) == Ordering::Greater { qh -= 1; } else { break; }
        }
        q[i] = qh as u32;
        let prod = mul_small(&bn, qh as u32);
        rem = sub_mag(&rem, &prod);
    }
    norm(&mut q);
    let (r, _) = divmod_mag(&rem, &[s]);
    (q, r)
}

impl Big {
    fn neg_of(&self) -> Big {
        if self.d.is_empty() { self.clone() } else { Big { neg: !self.neg, d: self.d.clone() } }
    }
}

fn add(a: &Big, b: &Big) -> Big {
    if a.neg == b.neg {
        let d = add_mag(&a.d, &b.d);
        Big { neg: a.neg && !d.is_empty(), d }
    } else {
        match cmp_mag(&a.d, &b.d) {
            Ordering::Equal => big_zero(),
            Ordering::Greater => { let d = sub_mag(&a.d, &b.d); Big { neg: a.neg, d } }
            Ordering::Less => { let d = sub_mag(&b.d, &a.d); Big { neg: b.neg, d } }
        }
    }
}

fn sub(a: &Big, b: &Big) -> Big { add(a, &b.neg_of()) }

fn mul(a: &Big, b: &Big) -> Big {
    let d = mul_mag(&a.d, &b.d);
    Big { neg: a.neg != b.neg && !d.is_empty(), d }
}

fn divmod_trunc(a: &Big, b: &Big) -> (Big, Big) {
    let (q, r) = divmod_mag(&a.d, &b.d);
    (Big { neg: a.neg != b.neg && !q.is_empty(), d: q },
     Big { neg: a.neg && !r.is_empty(), d: r })
}

fn floor_divmod(a: &Big, b: &Big) -> (Big, Big) {
    let (q, r) = divmod_trunc(a, b);
    if !is_zero(&r) && (a.neg != b.neg) {
        (sub(&q, &big_from_u64(1)), sub(b, &r))
    } else {
        (q, r)
    }
}

fn cmp(a: &Big, b: &Big) -> Ordering {
    match (a.neg, b.neg) {
        (false, false) => cmp_mag(&a.d, &b.d),
        (true, true) => cmp_mag(&b.d, &a.d),
        (true, false) => if is_zero(a) && is_zero(b) { Ordering::Equal } else { Ordering::Less },
        (false, true) => if is_zero(a) && is_zero(b) { Ordering::Equal } else { Ordering::Greater },
    }
}

fn mul_pow10(v: &Big, k: u32) -> Big {
    let mut d = v.d.clone();
    let mut k = k;
    while k > 0 {
        let m = k.min(9);
        d = mul_small(&d, 10u64.pow(m) as u32);
        k -= m;
    }
    Big { neg: v.neg && !d.is_empty(), d }
}

fn pow10(k: u32) -> Big { mul_pow10(&big_from_u64(1), k) }

// Round value v (scale s) to d decimal places, round-half-even.
fn round_to(v: &Big, s: u32, d: u32) -> Big {
    if s <= d { return mul_pow10(v, d - s); }
    let p = pow10(s - d);
    let (q, r) = divmod_trunc(v, &p);
    let r2 = add(&r, &r);
    let up = match cmp_mag(&r2.d, &p.d) {
        Ordering::Greater => true,
        Ordering::Equal => !q.d.is_empty() && (q.d[0] & 1 == 1),
        Ordering::Less => false,
    };
    let mut qd = q.d;
    if up { qd = add_mag(&qd, &[1]); }
    Big { neg: v.neg && !qd.is_empty(), d: qd }
}

fn digits_to_big(ds: &str) -> Big {
    let ds = ds.trim_start_matches('0');
    let mut d = vec![];
    let b = ds.as_bytes();
    let mut i = b.len();
    while i > 0 {
        let start = i.saturating_sub(9);
        d.push(ds[start..i].parse::<u32>().unwrap());
        i = start;
    }
    Big { neg: false, d }
}

fn parse_dec(s: &str) -> (Big, u32) {
    let mut t = s;
    let mut neg = false;
    if let Some(r) = t.strip_prefix('-') { neg = true; t = r; }
    let (i, f) = match t.find('.') {
        Some(i) => (&t[..i], &t[i + 1..]),
        None => (t, ""),
    };
    let mut ds = i.to_string();
    ds.push_str(f);
    let mut b = digits_to_big(&ds);
    if neg && !b.d.is_empty() { b.neg = true; }
    (b, f.len() as u32)
}

fn big_to_decstr(d: &[u32]) -> String {
    if d.is_empty() { return "0".to_string(); }
    let mut s = d[d.len() - 1].to_string();
    for i in (0..d.len() - 1).rev() { s.push_str(&format!("{:09}", d[i])); }
    s
}

fn group(ip: &str) -> String {
    let n = ip.len();
    let mut r = String::new();
    for (i, c) in ip.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { r.push(','); }
        r.push(c);
    }
    r
}

fn fmt(v: &Big, dec: u32) -> String {
    let mut ds = big_to_decstr(&v.d);
    let neg = v.neg && !v.d.is_empty();
    let ip;
    let fp;
    if dec > 0 {
        while ds.len() < dec as usize + 1 { ds.insert(0, '0'); }
        let split = ds.len() - dec as usize;
        ip = group(&ds[..split]);
        fp = ds[split..].to_string();
    } else {
        ip = group(&ds);
        fp = String::new();
    }
    let mut s = String::new();
    if neg { s.push('-'); }
    s.push_str(&ip);
    if dec > 0 { s.push('.'); s.push_str(&fp); }
    s
}

fn big_to_usize(v: &Big) -> usize {
    let mut r: usize = 0;
    for &x in v.d.iter().rev() {
        r = r * (BASE as usize) + x as usize;
    }
    r
}

struct Account {
    code: String,
    bal: Big,
    limit: Big,
}

fn funds_check(accts: &HashMap<String, Account>, name: &str, amt: &Big) -> bool {
    let a = &accts[name];
    let avail = add(&a.bal, &a.limit);
    cmp(&sub(&avail, amt), &big_zero()) != Ordering::Less
}

fn process(f: &[&str], curs: &HashMap<String, u32>, accts: &mut HashMap<String, Account>) -> Result<(), String> {
    match f[0] {
        "currency" => {
            curs.insert(f[1].to_string(), f[2].parse::<u32>().unwrap());
            Ok(())
        }
        "open" => {
            let name = f[1];
            if accts.contains_key(name) { return Err(format!("account exists {}", name)); }
            let dec = *curs.get(f[2]).unwrap_or(&0);
            let limit = if f.len() > 3 {
                let (v, s) = parse_dec(f[3]);
                round_to(&v, s, dec)
            } else { big_zero() };
            accts.insert(name.to_string(), Account { code: f[2].to_string(), bal: big_zero(), limit });
            Ok(())
        }
        "deposit" | "withdraw" => {
            let name = f[1];
            if !accts.contains_key(name) { return Err(format!("unknown account {}", name)); }
            let dec = *curs.get(&accts[name].code).unwrap();
            let (v, s) = parse_dec(f[2]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if f[0] == "withdraw" {
                if !funds_check(accts, name, &amt) { return Err(format!("insufficient funds {}", name)); }
                let a = accts.get_mut(name).unwrap();
                a.bal = sub(&a.bal, &amt);
            } else {
                let a = accts.get_mut(name).unwrap();
                a.bal = add(&a.bal, &amt);
            }
            Ok(())
        }
        "transfer" => {
            for n in [f[1], f[2]] {
                if !accts.contains_key(n) { return Err(format!("unknown account {}", n)); }
            }
            if accts[f[1]].code != accts[f[2]].code { return Err("currency mismatch".into()); }
            let dec = *curs.get(&accts[f[1]].code).unwrap();
            let (v, s) = parse_dec(f[3]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, f[1], &amt) { return Err(format!("insufficient funds {}", f[1])); }
            let fb;
            { let a = accts.get_mut(f[1]).unwrap(); fb = sub(&a.bal, &amt); }
            let tb;
            { let a = accts.get_mut(f[2]).unwrap(); tb = add(&a.bal, &amt); }
            accts.get_mut(f[1]).unwrap().bal = fb;
            accts.get_mut(f[2]).unwrap().bal = tb;
            Ok(())
        }
        "convert" => {
            for n in [f[1], f[2]] {
                if !accts.contains_key(n) { return Err(format!("unknown account {}", n)); }
            }
            let dfrom = *curs.get(&accts[f[1]].code).unwrap();
            let dto = *curs.get(&accts[f[2]].code).unwrap();
            let (v, s) = parse_dec(f[3]);
            let amt = round_to(&v, s, dfrom);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, f[1], &amt) { return Err(format!("insufficient funds {}", f[1])); }
            let (rv, rs) = parse_dec(f[4]);
            let prod = mul(&amt, &rv);
            let toamt = round_to(&prod, dfrom + rs, dto);
            let fb;
            { let a = accts.get_mut(f[1]).unwrap(); fb = sub(&a.bal, &amt); }
            let tb;
            { let a = accts.get_mut(f[2]).unwrap(); tb = add(&a.bal, &toamt); }
            accts.get_mut(f[1]).unwrap().bal = fb;
            accts.get_mut(f[2]).unwrap().bal = tb;
            Ok(())
        }
        "interest" => {
            let name = f[1];
            if !accts.contains_key(name) { return Err(format!("unknown account {}", name)); }
            let dec = *curs.get(&accts[name].code).unwrap();
            let (rv, rs) = parse_dec(f[2]);
            let a = accts.get_mut(name).unwrap();
            let prod = mul(&a.bal, &rv);
            let delta = round_to(&prod, dec + rs, dec);
            a.bal = add(&a.bal, &delta);
            Ok(())
        }
        "split" => {
            let from = f[1];
            let mut tnames: Vec<&str> = vec![];
            let mut weights: Vec<Big> = vec![];
            for tok in &f[3..] {
                let p: Vec<&str> = tok.split(':').collect();
                tnames.push(p[0]);
                weights.push(parse_dec(p[1]).0);
            }
            if !accts.contains_key(from) { return Err(format!("unknown account {}", from)); }
            for n in &tnames {
                if !accts.contains_key(*n) { return Err(format!("unknown account {}", n)); }
            }
            let code = accts[from].code.clone();
            for n in &tnames {
                if accts[*n].code != code { return Err("currency mismatch".into()); }
            }
            let dec = *curs.get(&code).unwrap();
            let (v, s) = parse_dec(f[2]);
            let amt = round_to(&v, s, dec);
            if cmp(&amt, &big_zero()) != Ordering::Greater { return Err("non-positive amount".into()); }
            if !funds_check(accts, from, &amt) { return Err(format!("insufficient funds {}", from)); }
            let wsum = weights.iter().fold(big_zero(), |a, w| add(&a, w));
            let mut qs = vec![];
            let mut rs = vec![];
            for w in &weights {
                let (q, r) = floor_divmod(&mul(&amt, w), &wsum);
                qs.push(q);
                rs.push(r);
            }
            let sumq = qs.iter().fold(big_zero(), |a, x| add(&a, x));
            let leftover = sub(&amt, &sumq);
            let mut order: Vec<usize> = (0..tnames.len()).collect();
            order.sort_by(|&a, &b| cmp(&rs[b], &rs[a]));
            let fb;
            { let a = accts.get_mut(from).unwrap(); fb = sub(&a.bal, &amt); }
            accts.get_mut(from).unwrap().bal = fb;
            let mut newbals = vec![];
            for i in 0..tnames.len() {
                let a = accts.get_mut(tnames[i]).unwrap();
                newbals.push(add(&a.bal, &qs[i]));
            }
            for i in 0..tnames.len() {
                accts.get_mut(tnames[i]).unwrap().bal = newbals[i].clone();
            }
            let lo = big_to_usize(&leftover);
            for i in 0..lo {
                let a = accts.get_mut(tnames[order[i]]).unwrap();
                a.bal = add(&a.bal, &big_from_u64(1));
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let path = format!("{}/ledger.txt", args[1]);
    let content = fs::read_to_string(&path).unwrap();
    let mut rejects: Vec<String> = vec![];
    let mut curs: HashMap<String, u32> = HashMap::new();
    let mut accts: HashMap<String, Account> = HashMap::new();
    for (idx, line) in content.lines().enumerate() {
        let n = idx + 1;
        let t = line.trim_start();
        if t.is_empty() || t.starts_with('#') { continue; }
        let f: Vec<&str> = t.split_whitespace().collect();
        if let Err(r) = process(&f, &curs, &mut accts) {
            rejects.push(format!("line {}: REJECT {}", n, r));
        }
    }
    for r in &rejects { println!("{}", r); }
    println!();
    let mut names: Vec<String> = accts.keys().cloned().collect();
    names.sort();
    for name in &names {
        let a = &accts[name];
        println!("{} {} {}", name, a.code, fmt(&a.bal, curs[&a.code]));
    }
    println!();
    let mut totals: BTreeMap<String, (Big, usize)> = BTreeMap::new();
    for a in accts.values() {
        let e = totals.entry(a.code.clone()).or_insert((big_zero(), 0));
        e.0 = add(&e.0, &a.bal);
        e.1 += 1;
    }
    for (code, (sum, cnt)) in &totals {
        println!("total {} {} ({} accounts)", code, fmt(sum, curs[code]), cnt);
    }
}

import java.nio.file.*;
import java.util.*;

public class Main {
    record Err(String inst, String sch) {}

    static Object ROOT;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        Object schema = parse(Files.readString(Path.of(dir, "schema.json")));
        ROOT = schema;
        List<Object> insts = (List<Object>) parse(Files.readString(Path.of(dir, "instances.json")));
        StringBuilder sb = new StringBuilder();
        int nv = 0, ni = 0;
        for (int n = 0; n < insts.size(); n++) {
            Set<Err> errs = new HashSet<>();
            validate(insts.get(n), schema, "#", "#", errs);
            if (errs.isEmpty()) {
                sb.append(n).append(": valid\n");
                nv++;
            } else {
                ni++;
                List<Err> l = new ArrayList<>(errs);
                l.sort((a, b) -> {
                    int c = cmp(a.inst(), b.inst());
                    return c != 0 ? c : cmp(a.sch(), b.sch());
                });
                sb.append(n).append(": invalid (").append(l.size()).append(")\n");
                for (Err e : l) sb.append("  ").append(e.inst()).append(' ').append(e.sch()).append('\n');
            }
        }
        sb.append("valid=").append(nv).append(" invalid=").append(ni).append('\n');
        System.out.print(sb);
    }

    static int cmp(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int ca = a.codePointAt(i), cb = b.codePointAt(j);
            if (ca != cb) return Integer.compare(ca, cb);
            i += Character.charCount(ca);
            j += Character.charCount(cb);
        }
        return Integer.compare(a.length() - i, b.length() - j);
    }

    static String esc(String t) { return t.replace("~", "~0").replace("/", "~1"); }
    static String unesc(String t) { return t.replace("~1", "/").replace("~0", "~"); }

    static Object resolve(Object root, String ref) {
        if (ref.equals("#")) return root;
        Object cur = root;
        for (String tok : ref.substring(2).split("/")) cur = ((Map<?, ?>) cur).get(unesc(tok));
        return cur;
    }

    static boolean accepts(Object inst, Object schema, String ip, String sp) {
        Set<Err> tmp = new HashSet<>();
        validate(inst, schema, ip, sp, tmp);
        return tmp.isEmpty();
    }

    @SuppressWarnings("unchecked")
    static void validate(Object inst, Object schema, String ip, String sp, Set<Err> errs) {
        if (schema instanceof Boolean b) {
            if (!b) errs.add(new Err(ip, sp));
            return;
        }
        Map<String, Object> m = (Map<String, Object>) schema;

        if (m.containsKey("type")) {
            Object t = m.get("type");
            List<Object> names = t instanceof String ? List.of(t) : (List<Object>) t;
            boolean ok = false;
            for (Object nm : names) if (typeOk(inst, (String) nm)) { ok = true; break; }
            if (!ok) errs.add(new Err(ip, sp + "/type"));
        }
        if (m.containsKey("enum")) {
            boolean ok = false;
            for (Object e : (List<Object>) m.get("enum")) if (deq(inst, e)) { ok = true; break; }
            if (!ok) errs.add(new Err(ip, sp + "/enum"));
        }
        if (m.containsKey("const") && !deq(inst, m.get("const"))) errs.add(new Err(ip, sp + "/const"));

        if (inst instanceof Double d) {
            if (m.containsKey("minimum") && !(d >= (Double) m.get("minimum"))) errs.add(new Err(ip, sp + "/minimum"));
            if (m.containsKey("maximum") && !(d <= (Double) m.get("maximum"))) errs.add(new Err(ip, sp + "/maximum"));
            if (m.containsKey("exclusiveMinimum") && !(d > (Double) m.get("exclusiveMinimum"))) errs.add(new Err(ip, sp + "/exclusiveMinimum"));
            if (m.containsKey("exclusiveMaximum") && !(d < (Double) m.get("exclusiveMaximum"))) errs.add(new Err(ip, sp + "/exclusiveMaximum"));
        }
        if (inst instanceof String s) {
            int len = s.codePointCount(0, s.length());
            if (m.containsKey("minLength") && !(len >= (Double) m.get("minLength"))) errs.add(new Err(ip, sp + "/minLength"));
            if (m.containsKey("maxLength") && !(len <= (Double) m.get("maxLength"))) errs.add(new Err(ip, sp + "/maxLength"));
        }
        if (inst instanceof List<?> arr) {
            int n = arr.size();
            if (m.containsKey("minItems") && !(n >= (Double) m.get("minItems"))) errs.add(new Err(ip, sp + "/minItems"));
            if (m.containsKey("maxItems") && !(n <= (Double) m.get("maxItems"))) errs.add(new Err(ip, sp + "/maxItems"));
            if (Boolean.TRUE.equals(m.get("uniqueItems"))) {
                boolean dup = false;
                for (int i = 0; i < n && !dup; i++)
                    for (int j = i + 1; j < n; j++)
                        if (deq(arr.get(i), arr.get(j))) { dup = true; break; }
                if (dup) errs.add(new Err(ip, sp + "/uniqueItems"));
            }
            Object pi = m.get("prefixItems");
            int pl = pi instanceof List ? ((List<Object>) pi).size() : 0;
            if (pi instanceof List) {
                List<Object> pl2 = (List<Object>) pi;
                for (int i = 0; i < pl2.size() && i < n; i++)
                    validate(arr.get(i), pl2.get(i), ip + "/" + i, sp + "/prefixItems/" + i, errs);
            }
            if (m.containsKey("items"))
                for (int i = pl; i < n; i++)
                    validate(arr.get(i), m.get("items"), ip + "/" + i, sp + "/items", errs);
        }
        if (inst instanceof Map<?, ?> om) {
            Map<String, Object> o = (Map<String, Object>) om;
            if (m.containsKey("properties")) {
                Map<String, Object> props = (Map<String, Object>) m.get("properties");
                for (var e : o.entrySet())
                    if (props.containsKey(e.getKey()))
                        validate(e.getValue(), props.get(e.getKey()), ip + "/" + esc(e.getKey()), sp + "/properties/" + esc(e.getKey()), errs);
            }
            if (m.containsKey("required")) {
                List<Object> req = (List<Object>) m.get("required");
                for (int j = 0; j < req.size(); j++)
                    if (!o.containsKey((String) req.get(j))) errs.add(new Err(ip, sp + "/required/" + j));
            }
            if (m.containsKey("additionalProperties")) {
                Set<String> pk = m.containsKey("properties") ? ((Map<String, Object>) m.get("properties")).keySet() : Set.of();
                Object ap = m.get("additionalProperties");
                for (var e : o.entrySet())
                    if (!pk.contains(e.getKey()))
                        validate(e.getValue(), ap, ip + "/" + esc(e.getKey()), sp + "/additionalProperties", errs);
            }
            int cnt = o.size();
            if (m.containsKey("minProperties") && !(cnt >= (Double) m.get("minProperties"))) errs.add(new Err(ip, sp + "/minProperties"));
            if (m.containsKey("maxProperties") && !(cnt <= (Double) m.get("maxProperties"))) errs.add(new Err(ip, sp + "/maxProperties"));
        }

        if (m.containsKey("allOf")) {
            List<Object> l = (List<Object>) m.get("allOf");
            for (int i = 0; i < l.size(); i++) validate(inst, l.get(i), ip, sp + "/allOf/" + i, errs);
        }
        if (m.containsKey("anyOf")) {
            boolean ok = false;
            for (Object s2 : (List<Object>) m.get("anyOf")) if (accepts(inst, s2, ip, sp)) { ok = true; break; }
            if (!ok) errs.add(new Err(ip, sp + "/anyOf"));
        }
        if (m.containsKey("oneOf")) {
            int c = 0;
            for (Object s2 : (List<Object>) m.get("oneOf")) if (accepts(inst, s2, ip, sp)) c++;
            if (c != 1) errs.add(new Err(ip, sp + "/oneOf"));
        }
        if (m.containsKey("not") && accepts(inst, m.get("not"), ip, sp)) errs.add(new Err(ip, sp + "/not"));
        if (m.containsKey("if")) {
            boolean acc = accepts(inst, m.get("if"), ip, sp);
            if (acc && m.containsKey("then")) validate(inst, m.get("then"), ip, sp + "/then", errs);
            if (!acc && m.containsKey("else")) validate(inst, m.get("else"), ip, sp + "/else", errs);
        }
        if (m.containsKey("$ref")) {
            String ref = (String) m.get("$ref");
            validate(inst, resolve(ROOT, ref), ip, ref.equals("#") ? "#" : ref, errs);
        }
    }

    static boolean typeOk(Object inst, String t) {
        switch (t) {
            case "null": return inst == null;
            case "boolean": return inst instanceof Boolean;
            case "string": return inst instanceof String;
            case "array": return inst instanceof List;
            case "object": return inst instanceof Map;
            case "number": return inst instanceof Double;
            case "integer": return inst instanceof Double && isInt((Double) inst);
        }
        return false;
    }

    static boolean isInt(double d) { return d == Math.rint(d); }

    static boolean deq(Object a, Object b) {
        if (a instanceof Double x && b instanceof Double y) return x.doubleValue() == y.doubleValue();
        if (a instanceof List<?> x && b instanceof List<?> y) {
            if (x.size() != y.size()) return false;
            for (int i = 0; i < x.size(); i++) if (!deq(x.get(i), y.get(i))) return false;
            return true;
        }
        if (a instanceof Map<?, ?> x && b instanceof Map<?, ?> y) {
            if (x.size() != y.size()) return false;
            for (var e : x.entrySet()) {
                if (!y.containsKey(e.getKey())) return false;
                if (!deq(e.getValue(), y.get(e.getKey()))) return false;
            }
            return true;
        }
        if (a == null || b == null) return a == b;
        return a.equals(b);
    }

    static Object parse(String s) {
        Parser p = new Parser(s);
        p.ws();
        return p.value();
    }

    static class Parser {
        final String s;
        int i;
        Parser(String s) { this.s = s; }

        void ws() {
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') i++;
                else break;
            }
        }

        char peek() { return s.charAt(i); }

        Object value() {
            ws();
            char c = s.charAt(i);
            switch (c) {
                case '{': return object();
                case '[': return array();
                case '"': return string();
                case 't': i += 4; return Boolean.TRUE;
                case 'f': i += 5; return Boolean.FALSE;
                case 'n': i += 4; return null;
                default: return number();
            }
        }

        Map<String, Object> object() {
            i++; ws();
            Map<String, Object> m = new LinkedHashMap<>();
            if (peek() == '}') { i++; return m; }
            while (true) {
                ws();
                String k = string();
                ws();
                i++; // ':'
                Object v = value();
                m.put(k, v);
                ws();
                char c = s.charAt(i); i++;
                if (c == '}') return m;
            }
        }

        List<Object> array() {
            i++; ws();
            List<Object> l = new ArrayList<>();
            if (peek() == ']') { i++; return l; }
            while (true) {
                l.add(value());
                ws();
                char c = s.charAt(i); i++;
                if (c == ']') return l;
            }
        }

        String string() {
            i++;
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = s.charAt(i);
                if (c == '"') { i++; return sb.toString(); }
                if (c == '\\') {
                    i++;
                    char e = s.charAt(i);
                    switch (e) {
                        case '"': sb.append('"'); i++; break;
                        case '\\': sb.append('\\'); i++; break;
                        case '/': sb.append('/'); i++; break;
                        case 'b': sb.append('\b'); i++; break;
                        case 'f': sb.append('\f'); i++; break;
                        case 'n': sb.append('\n'); i++; break;
                        case 'r': sb.append('\r'); i++; break;
                        case 't': sb.append('\t'); i++; break;
                        case 'u':
                            i++;
                            sb.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
                            i += 4;
                            break;
                    }
                } else {
                    sb.append(c);
                    i++;
                }
            }
        }

        Double number() {
            int st = i;
            if (s.charAt(i) == '-') i++;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            if (i < s.length() && s.charAt(i) == '.') {
                i++;
                while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            }
            if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
                i++;
                if (s.charAt(i) == '+' || s.charAt(i) == '-') i++;
                while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            }
            return Double.parseDouble(s.substring(st, i));
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const schemaDoc = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf8'));
const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf8'));

function esc(t: string): string {
  return t.replace(/~/g, '~0').replace(/\//g, '~1');
}

function deepEq(a: any, b: any): boolean {
  if (a === b) return true;
  if (typeof a === 'number' && typeof b === 'number') return false;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return false;
  if (typeof a === 'string' || typeof a === 'boolean') return false;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!deepEq(a[i], b[i])) return false;
    return true;
  }
  if (Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!(k in b) || !deepEq(a[k], b[k])) return false;
  }
  return true;
}

function resolveRef(ref: string): [any, string] {
  if (ref === '#') return [schemaDoc, '#'];
  const m = ref.match(/^#\/\$defs\/(.+)$/)!;
  const token = m[1];
  const name = token.replace(/~1/g, '/').replace(/~0/g, '~');
  return [schemaDoc.$defs[name], '#/' + token];
}

function accepts(s: any, inst: any): boolean {
  const errs = new Map<string, [string, string]>();
  validate(s, '#', inst, '#', errs);
  return errs.size === 0;
}

function validate(s: any, loc: string, inst: any, iloc: string,
                  errs: Map<string, [string, string]>): void {
  const add = (sl: string) => { errs.set(iloc + '\u0000' + sl, [iloc, sl]); };
  if (typeof s === 'boolean') {
    if (!s) add(loc);
    return;
  }
  const has = (k: string): boolean => Object.prototype.hasOwnProperty.call(s, k);

  if (has('type')) {
    const ts = Array.isArray(s.type) ? s.type : [s.type];
    const ok = ts.some((t: string) => {
      switch (t) {
        case 'null': return inst === null;
        case 'boolean': return typeof inst === 'boolean';
        case 'integer': return typeof inst === 'number' && Number.isInteger(inst);
        case 'number': return typeof inst === 'number';
        case 'string': return typeof inst === 'string';
        case 'array': return Array.isArray(inst);
        case 'object': return inst !== null && typeof inst === 'object' && !Array.isArray(inst);
        default: return false;
      }
    });
    if (!ok) add(loc + '/type');
  }
  if (has('enum') && !s.enum.some((e: any) => deepEq(inst, e))) add(loc + '/enum');
  if (has('const') && !deepEq(inst, s.const)) add(loc + '/const');

  if (typeof inst === 'number') {
    if (has('minimum') && !(inst >= s.minimum)) add(loc + '/minimum');
    if (has('maximum') && !(inst <= s.maximum)) add(loc + '/maximum');
    if (has('exclusiveMinimum') && !(inst > s.exclusiveMinimum)) add(loc + '/exclusiveMinimum');
    if (has('exclusiveMaximum') && !(inst < s.exclusiveMaximum)) add(loc + '/exclusiveMaximum');
  }

  if (typeof inst === 'string') {
    const L = [...inst].length;
    if (has('minLength') && !(L >= s.minLength)) add(loc + '/minLength');
    if (has('maxLength') && !(L <= s.maxLength)) add(loc + '/maxLength');
  }

  if (Array.isArray(inst)) {
    if (has('minItems') && !(inst.length >= s.minItems)) add(loc + '/minItems');
    if (has('maxItems') && !(inst.length <= s.maxItems)) add(loc + '/maxItems');
    if (s.uniqueItems === true) {
      outer: for (let i = 0; i < inst.length; i++) {
        for (let j = i + 1; j < inst.length; j++) {
          if (deepEq(inst[i], inst[j])) { add(loc + '/uniqueItems'); break outer; }
        }
      }
    }
    if (has('prefixItems')) {
      s.prefixItems.forEach((sub: any, i: number) => {
        if (i < inst.length) validate(sub, loc + '/prefixItems/' + i, inst[i], iloc + '/' + i, errs);
      });
    }
    if (has('items')) {
      const start = has('prefixItems') ? s.prefixItems.length : 0;
      for (let i = start; i < inst.length; i++) {
        validate(s.items, loc + '/items', inst[i], iloc + '/' + i, errs);
      }
    }
  }

  if (inst !== null && typeof inst === 'object' && !Array.isArray(inst)) {
    const keys = Object.keys(inst);
    if (has('minProperties') && !(keys.length >= s.minProperties)) add(loc + '/minProperties');
    if (has('maxProperties') && !(keys.length <= s.maxProperties)) add(loc + '/maxProperties');
    if (has('required')) {
      s.required.forEach((n: string, j: number) => {
        if (!(n in inst)) add(loc + '/required/' + j);
      });
    }
    if (has('properties')) {
      for (const k of Object.keys(s.properties)) {
        if (k in inst) validate(s.properties[k], loc + '/properties/' + esc(k), inst[k], iloc + '/' + esc(k), errs);
      }
    }
    if (has('additionalProperties')) {
      for (const k of keys) {
        if (!(has('properties') && Object.prototype.hasOwnProperty.call(s.properties, k))) {
          validate(s.additionalProperties, loc + '/additionalProperties', inst[k], iloc + '/' + esc(k), errs);
        }
      }
    }
  }

  if (has('allOf')) {
    s.allOf.forEach((sub: any, i: number) => validate(sub, loc + '/allOf/' + i, inst, iloc, errs));
  }
  if (has('anyOf')) {
    if (!s.anyOf.some((sub: any) => accepts(sub, inst))) add(loc + '/anyOf');
  }
  if (has('oneOf')) {
    const c = s.oneOf.filter((sub: any) => accepts(sub, inst)).length;
    if (c !== 1) add(loc + '/oneOf');
  }
  if (has('not')) {
    if (accepts(s.not, inst)) add(loc + '/not');
  }
  if (has('if')) {
    const ok = accepts(s.if, inst);
    if (ok && has('then')) validate(s.then, loc + '/then', inst, iloc, errs);
    if (!ok && has('else')) validate(s.else, loc + '/else', inst, iloc, errs);
  }
  if (has('$ref')) {
    const [sub, rloc] = resolveRef(s.$ref);
    validate(sub, rloc, inst, iloc, errs);
  }
}

function cmpPtr(a: string, b: string): number {
  const A = Array.from(a), B = Array.from(b);
  const n = Math.min(A.length, B.length);
  for (let i = 0; i < n; i++) {
    const x = A[i]!.codePointAt(0)!, y = B[i]!.codePointAt(0)!;
    if (x !== y) return x - y;
  }
  return A.length - B.length;
}

let valid = 0, invalid = 0;
const out: string[] = [];
instances.forEach((inst: any, n: number) => {
  const errs = new Map<string, [string, string]>();
  validate(schemaDoc, '#', inst, '#', errs);
  if (errs.size === 0) {
    valid++;
    out.push(`${n}: valid`);
  } else {
    invalid++;
    const list = Array.from(errs.values()).sort((p, q) =>
      cmpPtr(p[0], q[0]) || cmpPtr(p[1], q[1]));
    out.push(`${n}: invalid (${list.length})`);
    for (const [il, sl] of list) out.push(`  ${il} ${sl}`);
  }
});
out.push(`valid=${valid} invalid=${invalid}`);
process.stdout.write(out.join('\n') + '\n');

