  }
}

function cmpPtr(a: string, b: string): number {
  const A = Array.from(a), B = Array.from(b);
  const n = Math.min(A.length, B.length);
  for (let i = 0; i < n; i++) {
    const x = A[i]!.codePointAt(0)!, y = B[i]!.codePointAt(0)!;
    if (x !== y) return x - y;
  }
  return A.length - B.length;
}

let valid = 0, invalid = 0;
const out: string[] = [];
instances.forEach((inst: any, n: number) => {
  const errs = new Map<string, [string, string]>();
  validate(schemaDoc, '#', inst, '#', errs);
  if (errs.size === 0) {
    valid++;
    out.push(`${n}: valid`);
  } else {
    invalid++;
    const list = Array.from(errs.values()).sort((p, q) =>
      cmpPtr(p[0], q[0]) || cmpPtr(p[1], q[1]));
    out.push(`${n}: invalid (${list.length})`);
    for (const [il, sl] of list) out.push(`  ${il} ${sl}`);
  }
});
out.push(`valid=${valid} invalid=${invalid}`);
process.stdout.write(out.join('\n') + '\n');

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef unsigned __int128 u128;

#define LIM 48
typedef struct { int neg, n; uint32_t d[LIM]; } Big; /* magnitude base 1e9, little-endian */

static void trim(Big*b){ while(b->n&&b->d[b->n-1]==0)b->n--; if(!b->n)b->neg=0; }
static void bzero_(Big*b){ b->n=0; b->neg=0; }

static int big_cmp(Big a,Big b){
    if(a.n!=b.n) return a.n<b.n?-1:1;
    for(int i=a.n-1;i>=0;i--) if(a.d[i]!=b.d[i]) return a.d[i]<b.d[i]?-1:1;
    return 0;
}
static Big big_add_mag(Big a,Big b){
    Big r; r.neg=0; r.n=0;
    int n=a.n>b.n?a.n:b.n; uint32_t carry=0;
    for(int i=0;i<n||carry;i++){
        uint32_t v=carry;
        if(i<a.n)v+=a.d[i];
        if(i<b.n)v+=b.d[i];
        if(v>=1000000000u){v-=1000000000u;carry=1;}else carry=0;
        r.d[r.n++]=v;
    }
    return r;
}
static Big big_sub_mag(Big a,Big b){ /* a>=b */
    Big r=a; int32_t carry=0;
    for(int i=0;i<a.n;i++){
        int64_t cur=(int64_t)a.d[i]-carry-(i<b.n?b.d[i]:0);
        if(cur<0){cur+=1000000000;carry=1;}else carry=0;
        r.d[i]=(uint32_t)cur;
    }
    trim(&r); return r;
}
static void big_mul_small(Big*a,uint64_t m){
    u128 carry=0;
    for(int i=0;i<a->n;i++){ u128 cur=(u128)a->d[i]*m+carry; a->d[i]=(uint32_t)(cur%1000000000); carry=cur/1000000000; }
    while(carry){ if(a->n>=LIM)break; a->d[a->n++]=(uint32_t)(carry%1000000000); carry/=1000000000; }
}
static void big_mul_pow10(Big*a,int k){
    static const uint64_t p10[9]={1,10,100,1000,10000,100000,1000000,10000000,100000000};
    while(k>=9){ big_mul_small(a,1000000000ULL); k-=9; }
    if(k>0) big_mul_small(a,p10[k]);
}
static Big big_mul(Big a,Big b){
    Big r; r.neg=0; r.n=a.n+b.n; memset(r.d,0,r.n*sizeof(uint32_t));
    for(int i=0;i<a.n;i++){
        u128 carry=0; int j;
        for(j=0;j<b.n;j++){
            u128 cur=(u128)r.d[i+j]+(u128)a.d[i]*b.d[j]+carry;
            r.d[i+j]=(uint32_t)(cur%1000000000);
            carry=cur/1000000000;
        }
        while(carry){ u128 cur=(u128)r.d[i+j]+carry; r.d[i+j]=(uint32_t)(cur%1000000000); carry=cur/1000000000; j++; }
    }
    trim(&r); return r;
}
static void big_set_u64(Big*b,uint64_t v){ b->n=0;b->neg=0; while(v){ b->d[b->n++]=(uint32_t)(v%1000000000); v/=1000000000; } }
static void big_divmod(Big A,Big B,Big*q,Big*r){ /* binary long division, B>0 */
    memset(q->d,0,sizeof q->d); q->n=0; q->neg=0;
    r->n=0; r->neg=0;
    for(int i=A.n*32-1;i>=0;i--){
        uint32_t bit=(A.d[i>>5]>>(i&31))&1;
        uint32_t carry=bit;
        for(int j=0;j<r->n;j++){ uint32_t nc=r->d[j]>>31; r->d[j]=(r->d[j]<<1)|carry; carry=nc; }
        if(carry) r->d[r->n++]=carry;
        if(big_cmp(*r,B)>=0){ *r=big_sub_mag(*r,B); q->d[i>>5]|=1u<<(i&31); if((i>>5)+1>q->n)q->n=(i>>5)+1; }
    }
    trim(q); trim(r);
}
static int big_to_str(Big a,char*out){
    if(a.n==0){ strcpy(out,"0"); return 1; }
    char*p=out;
    p+=sprintf(p,"%u",a.d[a.n-1]);
    for(int i=a.n-2;i>=0;i--) p+=sprintf(p,"%09u",a.d[i]);
    return (int)(p-out);
}
static void big_from_digits(Big*b,const char*s,int len){
    b->n=0; b->neg=0;
    int i=0;
    while(i<len){
        int k=len-i; if(k>9)k=9;
        uint64_t m=1; for(int j=0;j<k;j++)m*=10;
        big_mul_small(b,m);
        uint64_t v=0; for(int j=0;j<k;j++)v=v*10+(s[i+j]-'0');
        uint32_t carry=(uint32_t)v; int idx=0;
        while(carry){
            if(idx>=b->n)b->d[b->n++]=0;
            uint32_t cur=b->d[idx]+carry;
            if(cur>=1000000000u){ b->d[idx]=cur-1000000000u; carry=1; idx++; }
            else { b->d[idx]=cur; carry=0; }
        }
        i+=k;
    }
    trim(b);
}
/* round magnitude (value = mag*10^-scale) to d decimals, half-even; returns magnitude */
static Big round_mag(Big mag,int scale,int d){
    if(scale<=d){ big_mul_pow10(&mag,d-scale); return mag; }
    int k=scale-d;
    char buf[LIM*9+2];
    big_to_str(mag,buf);
    int D=(int)strlen(buf);
    char frac[LIM*9+2]; int intlen;
    if(D>k){ intlen=D-k; memcpy(frac,buf+intlen,k); frac[k]=0; }
    else { intlen=0; int z=k-D; memset(frac,'0',z); memcpy(frac+z,buf,D); frac[k]=0; }
    int up=0,c=0;
    for(int i=0;i<k;i++){ char h=(i==0)?'5':'0'; if(frac[i]!=h){ c=(frac[i]>h)?1:-1; break; } }
    if(c>0) up=1;
    else if(c==0){ char last=intlen>0?buf[intlen-1]:'0'; if((last-'0')&1) up=1; }
    Big res;
    if(intlen>0) big_from_digits(&res,buf,intlen); else bzero_(&res);
    if(up){
        int idx=0; uint32_t carry=1;
        while(carry){
            if(idx>=res.n)res.d[res.n++]=0;
            uint32_t cur=res.d[idx]+carry;
            if(cur>=1000000000u){ res.d[idx]=0; carry=1; idx++; }
            else { res.d[idx]=cur; carry=0; }
        }
    }
    trim(&res); return res;
}
static Big s_neg(Big a){ if(a.n)a.neg=!a.neg; return a; }
static Big s_add(Big a,Big b){
    Big r;
    if(a.n==0)return b;
    if(b.n==0)return a;
    if(a.neg==b.neg){ r=big_add_mag(a,b); r.neg=a.neg; }
    else{
        int c=big_cmp(a,b);
        if(c==0) bzero_(&r);
        else if(c>0){ r=big_sub_mag(a,b); r.neg=a.neg; }
        else { r=big_sub_mag(b,a); r.neg=b.neg; }
    }
    return r;
}
static Big s_sub(Big a,Big b){ return s_add(a,s_neg(b)); }
static int s_cmp(Big a,Big b){
    int az=a.n==0,bz=b.n==0;
    if(az&&bz)return 0;
    if(az)return b.neg?-1:1;
    if(bz)return a.neg?-1:1;
    if(a.neg!=b.neg)return a.neg?-1:1;
    int c=big_cmp(a,b); return a.neg?-c:c;
}
static int parse_num(const char*t,Big*out){
    int neg=0; const char*p=t;
    if(*p=='-'){neg=1;p++;} else if(*p=='+')p++;
    char digits[1200]; int nd=0,scale=0,seenDot=0;
    for(;*p;p++){
        if(*p=='.'){ if(seenDot)return -1; seenDot=1; continue; }
        if(*p<'0'||*p>'9') return -1;
        digits[nd++]=*p; if(seenDot)scale++;
    }
    if(nd==0)return -1;
    big_from_digits(out,digits,nd);
    out->neg=neg;
    return scale;
}

#define MAXACC 2000
#define MAXCUR 100
struct Cur { char code[16]; int dec; };
struct Acc { char name[128]; int cur; Big bal; Big lim; };
static struct Cur curs[MAXCUR]; static int ncurs;
static struct Acc accs[MAXACC]; static int nacc;
static int find_cur(const char*c){ for(int i=0;i<ncurs;i++)if(!strcmp(curs[i].code,c))return i; return -1; }
static int find_acc(const char*n){ for(int i=0;i<nacc;i++)if(!strcmp(accs[i].name,n))return i; return -1; }
static int cmpacc(const void*a,const void*b){ return strcmp(accs[*(const int*)a].name,accs[*(const int*)b].name); }
static int cmpcur(const void*a,const void*b){ return strcmp(curs[*(const int*)a].code,curs[*(const int*)b].code); }

static Big parse_round(const char*tok,int dec){
    Big v,r; bzero_(&r);
    int sc=parse_num(tok,&v);
    if(sc<0)return r;
    r=round_mag(v,sc,dec);
    if(r.n)r.neg=v.neg;
    return r;
}
static int funds_ok(Big bal,Big lim,Big delta){ /* delta is signed amount to subtract */
    Big nb=s_sub(bal,delta);
    Big nl=lim; if(nl.n)nl.neg=1;
    return s_cmp(nb,nl)>=0;
}
static void money(Big v,int dec,char*out){
    char buf[LIM*9+2];
    Big mag=v; mag.neg=0; trim(&mag);
    big_to_str(mag,buf);
    char intp[LIM*9+2],frac[16];
    int D=(int)strlen(buf);
    if(dec>0){
        if(D>dec){ memcpy(intp,buf,D-dec); intp[D-dec]=0; memcpy(frac,buf+D-dec,dec); frac[dec]=0; }
        else { strcpy(intp,"0"); int z=dec-D; memset(frac,'0',z); memcpy(frac+z,buf,D); frac[dec]=0; }
    } else { strcpy(intp,buf); frac[0]=0; }
    char g[LIM*9+8]; int len=(int)strlen(intp),idx=0;
    for(int i=0;i<len;i++){
        g[idx++]=intp[i];
        int rem=len-1-i;
        if(rem>0&&rem%3==0)g[idx++]=',';
    }
    g[idx]=0;
    out[0]=0;
    if(v.neg&&mag.n)strcat(out,"-");
    strcat(out,g);
    if(dec>0){ strcat(out,"."); strcat(out,frac); }
}

int main(int argc,char**argv){
    if(argc<2)return 0;
    char path[4096];
    snprintf(path,sizeof path,"%s/ledger.txt",argv[1]);
    FILE*f=fopen(path,"r");
    if(!f)return 0;
    static char line[65536];
    static char rej[20000][192]; int nrej=0;
#define REJ(...) snprintf(rej[nrej++],192,__VA_ARGS__)
    int lineno=0;
    while(fgets(line,sizeof line,f)){
        lineno++;
        char*toks[1024]; int nt=0;
        for(char*t=strtok(line," \t\r\n");t&&nt<1024;t=strtok(NULL," \t\r\n"))toks[nt++]=t;
        if(nt==0)continue;
        if(toks[0][0]=='#')continue;
        const char*cmd=toks[0];
        if(!strcmp(cmd,"currency")&&nt>=3){
            strncpy(curs[ncurs].code,toks[1],15); curs[ncurs].code[15]=0;
            curs[ncurs].dec=atoi(toks[2]);
            ncurs++;
        }
        else if(!strcmp(cmd,"open")&&nt>=3){
            char*name=toks[1];
            if(find_acc(name)>=0){ REJ("line %d: REJECT account exists %s",lineno,name); }
            else{
                int ci=find_cur(toks[2]); if(ci<0)ci=0;
                struct Acc*a=&accs[nacc++];
                strcpy(a->name,name); a->cur=ci; bzero_(&a->bal); bzero_(&a->lim);
                if(nt>=4){ Big lim=parse_round(toks[3],curs[ci].dec); lim.neg=0; a->lim=lim; }
            }
        }
        else if((!strcmp(cmd,"deposit")||!strcmp(cmd,"withdraw"))&&nt>=3){
            int wd=(cmd[0]=='w');
            int ai=find_acc(toks[1]);
            if(ai<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else{
                Big amt=parse_round(toks[2],curs[accs[ai].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else{
                    Big delta=wd?s_neg(amt):amt;
                    if(!funds_ok(accs[ai].bal,accs[ai].lim,delta)) REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]);
                    else accs[ai].bal=s_sub(accs[ai].bal,delta);
                }
            }
        }
        else if(!strcmp(cmd,"transfer")&&nt>=4){
            int fi=find_acc(toks[1]),ti=find_acc(toks[2]);
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[2]); }
            else if(accs[fi].cur!=accs[ti].cur){ REJ("line %d: REJECT currency mismatch",lineno); }
            else{
                Big amt=parse_round(toks[3],curs[accs[fi].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                else{ accs[fi].bal=s_sub(accs[fi].bal,amt); accs[ti].bal=s_add(accs[ti].bal,amt); }
            }
        }
        else if(!strcmp(cmd,"convert")&&nt>=5){
            int fi=find_acc(toks[1]),ti=find_acc(toks[2]);
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[2]); }
            else{
                Big amt=parse_round(toks[3],curs[accs[fi].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                else{
                    Big rm; int rs=parse_num(toks[4],&rm);
                    if(rs<0){ bzero_(&rm); rs=0; }
                    int fd=curs[accs[fi].cur].dec;
                    Big am=amt; am.neg=0;
                    Big prod=big_mul(am,rm);
                    Big to=round_mag(prod,rs+fd,curs[accs[ti].cur].dec);
                    if(to.n)to.neg=rm.neg;
                    accs[fi].bal=s_sub(accs[fi].bal,amt);
                    accs[ti].bal=s_add(accs[ti].bal,to);
                }
            }
        }
        else if(!strcmp(cmd,"interest")&&nt>=3){
            int ai=find_acc(toks[1]);
            if(ai<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else{
                Big rm; int rs=parse_num(toks[2],&rm);
                if(rs<0){ bzero_(&rm); rs=0; }
                int dec=curs[accs[ai].cur].dec;
                Big bal=accs[ai].bal;
                Big bm=bal; bm.neg=0;
                Big prod=big_mul(bm,rm);
                Big add=round_mag(prod,rs+dec,dec);
                if(add.n)add.neg=bal.neg^rm.neg;
                accs[ai].bal=s_add(bal,add);
            }
        }
        else if(!strcmp(cmd,"split")&&nt>=4){
            int fi=find_acc(toks[1]);
            int bad=0;
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); bad=1; }
            int tidx[1024]; int ntgt=nt-3;
            if(!bad){
                for(int i=0;i<ntgt;i++){
                    char*colon=strchr(toks[3+i],':');
                    int ln=colon?(int)(colon-toks[3+i]):(int)strlen(toks[3+i]);
                    char nm[128]; memcpy(nm,toks[3+i],ln); nm[ln]=0;
                    int ti=find_acc(nm);
                    tidx[i]=ti;
                    if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,nm); bad=1; break; }
                }
            }
            if(!bad){
                int mm=0;
                for(int i=0;i<ntgt;i++)if(accs[tidx[i]].cur!=accs[fi].cur)mm=1;
                if(mm){ REJ("line %d: REJECT currency mismatch",lineno); }
                else{
                    Big amt=parse_round(toks[2],curs[accs[fi].cur].dec);
                    if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                    else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                    else{
                        Big A=amt; A.neg=0;
                        uint64_t W=0,w[1024];
                        for(int i=0;i<ntgt;i++){
                            char*colon=strchr(toks[3+i],':');
                            w[i]=strtoull(colon+1,NULL,10);
                            W+=w[i];
                        }
                        Big Wb; big_set_u64(&Wb,W);
                        Big q[1024],r[1024];
                        for(int i=0;i<ntgt;i++){
                            Big wb; big_set_u64(&wb,w[i]);
                            Big prod=big_mul(A,wb);
                            big_divmod(prod,Wb,&q[i],&r[i]);
                        }
                        Big sumq; bzero_(&sumq);
                        for(int i=0;i<ntgt;i++)sumq=big_add_mag(sumq,q[i]);
                        Big left=big_sub_mag(A,sumq);
                        int lo=left.n?(int)left.d[0]:0;
                        if(lo>ntgt)lo=ntgt;
                        int chosen[1024]; memset(chosen,0,sizeof chosen);
                        for(int e=0;e<lo;e++){
                            int best=-1;
                            for(int i=0;i<ntgt;i++)
                                if(!chosen[i]&&(best<0||big_cmp(r[i],r[best])>0))best=i;
                            chosen[best]=1;
                        }
                        accs[fi].bal=s_sub(accs[fi].bal,amt);
                        Big one; big_set_u64(&one,1);
                        for(int i=0;i<ntgt;i++){
                            Big pay=q[i];
                            if(chosen[i])pay=big_add_mag(pay,one);
                            accs[tidx[i]].bal=s_add(accs[tidx[i]].bal,pay);
                        }
                    }
                }
            }
        }
    }
    fclose(f);
    for(int i=0;i<nrej;i++)puts(rej[i]);
    if(nrej)putchar('\n');
    int ord[MAXACC];
    for(int i=0;i<nacc;i++)ord[i]=i;
    qsort(ord,nacc,sizeof(int),cmpacc);
    for(int i=0;i<nacc;i++){
        char buf[1024];
        money(accs[ord[i]].bal,curs[accs[ord[i]].cur].dec,buf);
        printf("%s %s %s\n",accs[ord[i]].name,curs[accs[ord[i]].cur].code,buf);
    }
    putchar('\n');
    int cl[MAXCUR],ncl=0;
    Big sums[MAXCUR]; int cnts[MAXCUR];
    for(int c=0;c<ncurs;c++){
        int cnt=0; Big s; bzero_(&s);
        for(int i=0;i<nacc;i++)if(accs[i].cur==c){ cnt++; s=s_add(s,accs[i].bal); }
        if(cnt){ cl[ncl]=c; sums[ncl]=s; cnts[ncl]=cnt; ncl++; }
    }
    qsort(cl,ncl,sizeof(int),cmpcur);
    for(int i=0;i<ncl;i++){
        char buf[1024];
        money(sums[i],curs[cl[i]].dec,buf);
        printf("total %s %s (%d accounts)\n",curs[cl[i]].code,buf,cnts[i]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef unsigned __int128 u128;

#define LIM 48
typedef struct { int neg, n; uint32_t d[LIM]; } Big; /* magnitude base 1e9, little-endian */

static void trim(Big*b){ while(b->n&&b->d[b->n-1]==0)b->n--; if(!b->n)b->neg=0; }
static void bzero_(Big*b){ b->n=0; b->neg=0; }

static int big_cmp(Big a,Big b){
    if(a.n!=b.n) return a.n<b.n?-1:1;
    for(int i=a.n-1;i>=0;i--) if(a.d[i]!=b.d[i]) return a.d[i]<b.d[i]?-1:1;
    return 0;
}
static Big big_add_mag(Big a,Big b){
    Big r; r.neg=0; r.n=0;
    int n=a.n>b.n?a.n:b.n; uint32_t carry=0;
    for(int i=0;i<n||carry;i++){
        uint32_t v=carry;
        if(i<a.n)v+=a.d[i];
        if(i<b.n)v+=b.d[i];
        if(v>=1000000000u){v-=1000000000u;carry=1;}else carry=0;
        r.d[r.n++]=v;
    }
    return r;
}
static Big big_sub_mag(Big a,Big b){ /* a>=b */
    Big r=a; int32_t carry=0;
    for(int i=0;i<a.n;i++){
        int64_t cur=(int64_t)a.d[i]-carry-(i<b.n?b.d[i]:0);
        if(cur<0){cur+=1000000000;carry=1;}else carry=0;
        r.d[i]=(uint32_t)cur;
    }
    trim(&r); return r;
}
static void big_mul_small(Big*a,uint64_t m){
    u128 carry=0;
    for(int i=0;i<a->n;i++){ u128 cur=(u128)a->d[i]*m+carry; a->d[i]=(uint32_t)(cur%1000000000); carry=cur/1000000000; }
    while(carry){ if(a->n>=LIM)break; a->d[a->n++]=(uint32_t)(carry%1000000000); carry/=1000000000; }
}
static void big_mul_pow10(Big*a,int k){
    static const uint64_t p10[9]={1,10,100,1000,10000,100000,1000000,10000000,100000000};
    while(k>=9){ big_mul_small(a,1000000000ULL); k-=9; }
    if(k>0) big_mul_small(a,p10[k]);
}
static Big big_mul(Big a,Big b){
    Big r; r.neg=0; r.n=a.n+b.n; memset(r.d,0,r.n*sizeof(uint32_t));
    for(int i=0;i<a.n;i++){
        u128 carry=0; int j;
        for(j=0;j<b.n;j++){
            u128 cur=(u128)r.d[i+j]+(u128)a.d[i]*b.d[j]+carry;
            r.d[i+j]=(uint32_t)(cur%1000000000);
            carry=cur/1000000000;
        }
        while(carry){ u128 cur=(u128)r.d[i+j]+carry; r.d[i+j]=(uint32_t)(cur%1000000000); carry=cur/1000000000; j++; }
    }
    trim(&r); return r;
}
static void big_set_u64(Big*b,uint64_t v){ b->n=0;b->neg=0; while(v){ b->d[b->n++]=(uint32_t)(v%1000000000); v/=1000000000; } }
static void big_divmod(Big A,Big B,Big*q,Big*r){ /* binary long division, B>0 */
    memset(q->d,0,sizeof q->d); q->n=0; q->neg=0;
    r->n=0; r->neg=0;
    for(int i=A.n*32-1;i>=0;i--){
        uint32_t bit=(A.d[i>>5]>>(i&31))&1;
        uint32_t carry=bit;
        for(int j=0;j<r->n;j++){ uint32_t nc=r->d[j]>>31; r->d[j]=(r->d[j]<<1)|carry; carry=nc; }
        if(carry) r->d[r->n++]=carry;
        if(big_cmp(*r,B)>=0){ *r=big_sub_mag(*r,B); q->d[i>>5]|=1u<<(i&31); if((i>>5)+1>q->n)q->n=(i>>5)+1; }
    }
    trim(q); trim(r);
}
static int big_to_str(Big a,char*out){
    if(a.n==0){ strcpy(out,"0"); return 1; }
    char*p=out;
    p+=sprintf(p,"%u",a.d[a.n-1]);
    for(int i=a.n-2;i>=0;i--) p+=sprintf(p,"%09u",a.d[i]);
    return (int)(p-out);
}
static void big_from_digits(Big*b,const char*s,int len){
    b->n=0; b->neg=0;
    int i=0;
    while(i<len){
        int k=len-i; if(k>9)k=9;
        uint64_t m=1; for(int j=0;j<k;j++)m*=10;
        big_mul_small(b,m);
        uint64_t v=0; for(int j=0;j<k;j++)v=v*10+(s[i+j]-'0');
        uint32_t carry=(uint32_t)v; int idx=0;
        while(carry){
            if(idx>=b->n)b->d[b->n++]=0;
            uint32_t cur=b->d[idx]+carry;
            if(cur>=1000000000u){ b->d[idx]=cur-1000000000u; carry=1; idx++; }
            else { b->d[idx]=cur; carry=0; }
        }
        i+=k;
    }
    trim(b);
}
/* round magnitude (value = mag*10^-scale) to d decimals, half-even; returns magnitude */
static Big round_mag(Big mag,int scale,int d){
    if(scale<=d){ big_mul_pow10(&mag,d-scale); return mag; }
    int k=scale-d;
    char buf[LIM*9+2];
    big_to_str(mag,buf);
    int D=(int)strlen(buf);
    char frac[LIM*9+2]; int intlen;
    if(D>k){ intlen=D-k; memcpy(frac,buf+intlen,k); frac[k]=0; }
    else { intlen=0; int z=k-D; memset(frac,'0',z); memcpy(frac+z,buf,D); frac[k]=0; }
    int up=0,c=0;
    for(int i=0;i<k;i++){ char h=(i==0)?'5':'0'; if(frac[i]!=h){ c=(frac[i]>h)?1:-1; break; } }
    if(c>0) up=1;
    else if(c==0){ char last=intlen>0?buf[intlen-1]:'0'; if((last-'0')&1) up=1; }
    Big res;
    if(intlen>0) big_from_digits(&res,buf,intlen); else bzero_(&res);
    if(up){
        int idx=0; uint32_t carry=1;
        while(carry){
            if(idx>=res.n)res.d[res.n++]=0;
            uint32_t cur=res.d[idx]+carry;
            if(cur>=1000000000u){ res.d[idx]=0; carry=1; idx++; }
            else { res.d[idx]=cur; carry=0; }
        }
    }
    trim(&res); return res;
}
static Big s_neg(Big a){ if(a.n)a.neg=!a.neg; return a; }
static Big s_add(Big a,Big b){
    Big r;
    if(a.n==0)return b;
    if(b.n==0)return a;
    if(a.neg==b.neg){ r=big_add_mag(a,b); r.neg=a.neg; }
    else{
        int c=big_cmp(a,b);
        if(c==0) bzero_(&r);
        else if(c>0){ r=big_sub_mag(a,b); r.neg=a.neg; }
        else { r=big_sub_mag(b,a); r.neg=b.neg; }
    }
    return r;
}
static Big s_sub(Big a,Big b){ return s_add(a,s_neg(b)); }
static int s_cmp(Big a,Big b){
    int az=a.n==0,bz=b.n==0;
    if(az&&bz)return 0;
    if(az)return b.neg?-1:1;
    if(bz)return a.neg?-1:1;
    if(a.neg!=b.neg)return a.neg?-1:1;
    int c=big_cmp(a,b); return a.neg?-c:c;
}
static int parse_num(const char*t,Big*out){
    int neg=0; const char*p=t;
    if(*p=='-'){neg=1;p++;} else if(*p=='+')p++;
    char digits[1200]; int nd=0,scale=0,seenDot=0;
    for(;*p;p++){
        if(*p=='.'){ if(seenDot)return -1; seenDot=1; continue; }
        if(*p<'0'||*p>'9') return -1;
        digits[nd++]=*p; if(seenDot)scale++;
    }
    if(nd==0)return -1;
    big_from_digits(out,digits,nd);
    out->neg=neg;
    return scale;
}

#define MAXACC 2000
#define MAXCUR 100
struct Cur { char code[16]; int dec; };
struct Acc { char name[128]; int cur; Big bal; Big lim; };
static struct Cur curs[MAXCUR]; static int ncurs;
static struct Acc accs[MAXACC]; static int nacc;
static int find_cur(const char*c){ for(int i=0;i<ncurs;i++)if(!strcmp(curs[i].code,c))return i; return -1; }
static int find_acc(const char*n){ for(int i=0;i<nacc;i++)if(!strcmp(accs[i].name,n))return i; return -1; }
static int cmpacc(const void*a,const void*b){ return strcmp(accs[*(const int*)a].name,accs[*(const int*)b].name); }
static int cmpcur(const void*a,const void*b){ return strcmp(curs[*(const int*)a].code,curs[*(const int*)b].code); }

static Big parse_round(const char*tok,int dec){
    Big v,r; bzero_(&r);
    int sc=parse_num(tok,&v);
    if(sc<0)return r;
    r=round_mag(v,sc,dec);
    if(r.n)r.neg=v.neg;
    return r;
}
static int funds_ok(Big bal,Big lim,Big amt){ /* new balance = bal - amt must be >= -lim */
    Big nb=s_sub(bal,amt);
    Big nl=lim; if(nl.n)nl.neg=1;
    return s_cmp(nb,nl)>=0;
}
static void money(Big v,int dec,char*out){
    char buf[LIM*9+2];
    Big mag=v; mag.neg=0; trim(&mag);
    big_to_str(mag,buf);
    char intp[LIM*9+2],frac[16];
    int D=(int)strlen(buf);
    if(dec>0){
        if(D>dec){ memcpy(intp,buf,D-dec); intp[D-dec]=0; memcpy(frac,buf+D-dec,dec); frac[dec]=0; }
        else { strcpy(intp,"0"); int z=dec-D; memset(frac,'0',z); memcpy(frac+z,buf,D); frac[dec]=0; }
    } else { strcpy(intp,buf); frac[0]=0; }
    char g[LIM*9+8]; int len=(int)strlen(intp),idx=0;
    for(int i=0;i<len;i++){
        g[idx++]=intp[i];
        int rem=len-1-i;
        if(rem>0&&rem%3==0)g[idx++]=',';
    }
    g[idx]=0;
    out[0]=0;
    if(v.neg&&mag.n)strcat(out,"-");
    strcat(out,g);
    if(dec>0){ strcat(out,"."); strcat(out,frac); }
}

int main(int argc,char**argv){
    if(argc<2)return 0;
    char path[4096];
    snprintf(path,sizeof path,"%s/ledger.txt",argv[1]);
    FILE*f=fopen(path,"r");
    if(!f)return 0;
    static char line[65536];
    static char rej[20000][192]; int nrej=0;
#define REJ(...) snprintf(rej[nrej++],192,__VA_ARGS__)
    int lineno=0;
    while(fgets(line,sizeof line,f)){
        lineno++;
        char*toks[1024]; int nt=0;
        for(char*t=strtok(line," \t\r\n");t&&nt<1024;t=strtok(NULL," \t\r\n"))toks[nt++]=t;
        if(nt==0)continue;
        if(toks[0][0]=='#')continue;
        const char*cmd=toks[0];
        if(!strcmp(cmd,"currency")&&nt>=3){
            strncpy(curs[ncurs].code,toks[1],15); curs[ncurs].code[15]=0;
            curs[ncurs].dec=atoi(toks[2]);
            ncurs++;
        }
        else if(!strcmp(cmd,"open")&&nt>=3){
            char*name=toks[1];
            if(find_acc(name)>=0){ REJ("line %d: REJECT account exists %s",lineno,name); }
            else{
                int ci=find_cur(toks[2]); if(ci<0)ci=0;
                struct Acc*a=&accs[nacc++];
                strcpy(a->name,name); a->cur=ci; bzero_(&a->bal); bzero_(&a->lim);
                if(nt>=4){ Big lim=parse_round(toks[3],curs[ci].dec); lim.neg=0; a->lim=lim; }
            }
        }
        else if(!strcmp(cmd,"deposit")&&nt>=3){
            int ai=find_acc(toks[1]);
            if(ai<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else{
                Big amt=parse_round(toks[2],curs[accs[ai].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else accs[ai].bal=s_add(accs[ai].bal,amt);
            }
        }
        else if(!strcmp(cmd,"withdraw")&&nt>=3){
            int ai=find_acc(toks[1]);
            if(ai<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else{
                Big amt=parse_round(toks[2],curs[accs[ai].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else if(!funds_ok(accs[ai].bal,accs[ai].lim,amt)) REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]);
                else accs[ai].bal=s_sub(accs[ai].bal,amt);
            }
        }
        else if(!strcmp(cmd,"transfer")&&nt>=4){
            int fi=find_acc(toks[1]),ti=find_acc(toks[2]);
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[2]); }
            else if(accs[fi].cur!=accs[ti].cur){ REJ("line %d: REJECT currency mismatch",lineno); }
            else{
                Big amt=parse_round(toks[3],curs[accs[fi].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                else{ accs[fi].bal=s_sub(accs[fi].bal,amt); accs[ti].bal=s_add(accs[ti].bal,amt); }
            }
        }
        else if(!strcmp(cmd,"convert")&&nt>=5){
            int fi=find_acc(toks[1]),ti=find_acc(toks[2]);
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[2]); }
            else{
                Big amt=parse_round(toks[3],curs[accs[fi].cur].dec);
                if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                else{
                    Big rm; int rs=parse_num(toks[4],&rm);
                    if(rs<0){ bzero_(&rm); rs=0; }
                    int fd=curs[accs[fi].cur].dec;
                    Big am=amt; am.neg=0;
                    Big prod=big_mul(am,rm);
                    Big to=round_mag(prod,rs+fd,curs[accs[ti].cur].dec);
                    if(to.n)to.neg=rm.neg;
                    accs[fi].bal=s_sub(accs[fi].bal,amt);
                    accs[ti].bal=s_add(accs[ti].bal,to);
                }
            }
        }
        else if(!strcmp(cmd,"interest")&&nt>=3){
            int ai=find_acc(toks[1]);
            if(ai<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); }
            else{
                Big rm; int rs=parse_num(toks[2],&rm);
                if(rs<0){ bzero_(&rm); rs=0; }
                int dec=curs[accs[ai].cur].dec;
                Big bal=accs[ai].bal;
                Big bm=bal; bm.neg=0;
                Big prod=big_mul(bm,rm);
                Big add=round_mag(prod,rs+dec,dec);
                if(add.n)add.neg=bal.neg^rm.neg;
                accs[ai].bal=s_add(bal,add);
            }
        }
        else if(!strcmp(cmd,"split")&&nt>=4){
            int fi=find_acc(toks[1]);
            int bad=0;
            if(fi<0){ REJ("line %d: REJECT unknown account %s",lineno,toks[1]); bad=1; }
            int tidx[1024]; int ntgt=nt-3;
            if(!bad){
                for(int i=0;i<ntgt;i++){
                    char*colon=strchr(toks[3+i],':');
                    int ln=colon?(int)(colon-toks[3+i]):(int)strlen(toks[3+i]);
                    char nm[128]; memcpy(nm,toks[3+i],ln); nm[ln]=0;
                    int ti=find_acc(nm);
                    tidx[i]=ti;
                    if(ti<0){ REJ("line %d: REJECT unknown account %s",lineno,nm); bad=1; break; }
                }
            }
            if(!bad){
                int mm=0;
                for(int i=0;i<ntgt;i++)if(accs[tidx[i]].cur!=accs[fi].cur)mm=1;
                if(mm){ REJ("line %d: REJECT currency mismatch",lineno); }
                else{
                    Big amt=parse_round(toks[2],curs[accs[fi].cur].dec);
                    if(amt.n==0||amt.neg){ REJ("line %d: REJECT non-positive amount",lineno); }
                    else if(!funds_ok(accs[fi].bal,accs[fi].lim,amt)){ REJ("line %d: REJECT insufficient funds %s",lineno,toks[1]); }
                    else{
                        Big A=amt; A.neg=0;
                        uint64_t W=0,w[1024];
                        for(int i=0;i<ntgt;i++){
                            char*colon=strchr(toks[3+i],':');
                            w[i]=strtoull(colon+1,NULL,10);
                            W+=w[i];
                        }
                        Big Wb; big_set_u64(&Wb,W);
                        Big q[1024],r[1024];
                        for(int i=0;i<ntgt;i++){
                            Big wb; big_set_u64(&wb,w[i]);
                            Big prod=big_mul(A,wb);
                            big_divmod(prod,Wb,&q[i],&r[i]);
                        }
                        Big sumq; bzero_(&sumq);
                        for(int i=0;i<ntgt;i++)sumq=big_add_mag(sumq,q[i]);
                        Big left=big_sub_mag(A,sumq);
                        int lo=left.n?(int)left.d[0]:0;
                        if(lo>ntgt)lo=ntgt;
                        int chosen[1024]; memset(chosen,0,sizeof chosen);
                        for(int e=0;e<lo;e++){
                            int best=-1;
                            for(int i=0;i<ntgt;i++)
                                if(!chosen[i]&&(best<0||big_cmp(r[i],r[best])>0))best=i;
                            chosen[best]=1;
                        }
                        accs[fi].bal=s_sub(accs[fi].bal,amt);
                        Big one; big_set_u64(&one,1);
                        for(int i=0;i<ntgt;i++){
                            Big pay=q[i];
                            if(chosen[i])pay=big_add_mag(pay,one);
                            accs[tidx[i]].bal=s_add(accs[tidx[i]].bal,pay);
                        }
                    }
                }
            }
        }
    }
    fclose(f);
    for(int i=0;i<nrej;i++)puts(rej[i]);
    putchar('\n');
    int ord[MAXACC];
    for(int i=0;i<nacc;i++)ord[i]=i;
    qsort(ord,nacc,sizeof(int),cmpacc);
    for(int i=0;i<nacc;i++){
        char buf[1024];
        money(accs[ord[i]].bal,curs[accs[ord[i]].cur].dec,buf);
        printf("%s %s %s\n",accs[ord[i]].name,curs[accs[ord[i]].cur].code,buf);
    }
    putchar('\n');
    int cl[MAXCUR],ncl=0;
    Big sums[MAXCUR]; int cnts[MAXCUR];
    for(int c=0;c<ncurs;c++){
        int cnt=0; Big s; bzero_(&s);
        for(int i=0;i<nacc;i++)if(accs[i].cur==c){ cnt++; s=s_add(s,accs[i].bal); }
        if(cnt){ cl[ncl]=c; sums[ncl]=s; cnts[ncl]=cnt; ncl++; }
    }
    qsort(cl,ncl,sizeof(int),cmpcur);
    for(int i=0;i<ncl;i++){
        char buf[1024];
        money(sums[i],curs[cl[i]].dec,buf);
        printf("total %s %s (%d accounts)\n",curs[cl[i]].code,buf,cnts[i]);
    }
    return 0;
}

