static char *read_name(const uint8_t *msg, size_t len, size_t *off) {
    char buf[2048]; size_t bl = 0;
    size_t pos = *off, next = pos + 1;
    int jumped = 0, count = 0;
    while (pos < len) {
        uint8_t b = msg[pos];
        if ((b & 0xC0) == 0xC0) {
            if (pos + 1 >= len) break;
            size_t ptr = ((size_t)(b & 0x3F) << 8) | msg[pos + 1];
            if (!jumped) next = pos + 2;
            jumped = 1;
            if (++count > 128) break;
            pos = ptr;
            continue;
        }
        if (b == 0) { if (!jumped) next = pos + 1; break; }
        if (pos + 1 + b > len) break;
        if (bl && bl < sizeof buf - 1) buf[bl++] = '.';
        for (int i = 0; i < b && bl < sizeof buf - 1; i++)
            buf[bl++] = (char)tolower((unsigned char)msg[pos + 1 + i]);
        pos += 1 + b;
    }
    buf[bl] = 0;
    *off = next;
    return strdup(bl ? buf : ".");
}

static void fmt_aaaa(const uint8_t *a, char *out) {
    uint16_t g[8];
    char tok[8][6];
    for (int i = 0; i < 8; i++) {
        g[i] = (uint16_t)((a[2*i] << 8) | a[2*i+1]);
        sprintf(tok[i], "%x", g[i]);
    }
    int best = -1, bl = 0;
    for (int i = 0; i < 8;) {
        if (g[i] == 0) {
            int j = i; while (j < 8 && g[j] == 0) j++;
            if (j - i > bl) { bl = j - i; best = i; }
            i = j;
        } else i++;
    }
    if (bl < 2) best = -1;
    char *p = out;
    if (best < 0) {
        for (int i = 0; i < 8; i++) {
            if (i) *p++ = ':';
            strcpy(p, tok[i]); p += strlen(p);
        }
    } else {
        for (int i = 0; i < best; i++) {
            if (i) *p++ = ':';
            strcpy(p, tok[i]); p += strlen(p);
        }
        *p++ = ':'; *p++ = ':';
        for (int i = best + bl; i < 8; i++) {
            if (i > best + bl) *p++ = ':';
            strcpy(p, tok[i]); p += strlen(p);
        }
    }
    *p = 0;
}

static int write_all(int fd, const void *b, size_t n) {
    const uint8_t *p = b;
    while (n) {
        ssize_t w = write(fd, p, n);
        if (w <= 0) return -1;
        p += w; n -= (size_t)w;
    }
    return 0;
}

static int read_all(int fd, void *b, size_t n) {
    uint8_t *p = b;
    while (n) {
        ssize_t r = read(fd, p, n);
        if (r <= 0) return -1;
        p += r; n -= (size_t)r;
    }
    return 0;
}

static const char *rcode_str(int r) {
    switch (r) {
        case 0: return "NOERROR";
        case 1: return "FORMERR";
        case 2: return "SERVFAIL";
        case 3: return "NXDOMAIN";
        case 4: return "NOTIMP";
        case 5: return "REFUSED";
        default: { static char s[16]; sprintf(s, "RCODE%d", r); return s; }
    }
}

static const char *type_name(int t) {
    switch (t) {
        case 1: return "A";
        case 5: return "CNAME";
        case 15: return "MX";
        case 16: return "TXT";
        case 28: return "AAAA";
        default: { static char s[16]; sprintf(s, "TYPE%d", t); return s; }
    }
}

int main(int argc, char **argv) {
    if (argc < 3) return 1;
    const char *dir = argv[1];
    int port = atoi(argv[2]);
    char path[4096];
    snprintf(path, sizeof path, "%s/queries.txt", dir);
    FILE *f = fopen(path, "r");
    if (!f) return 1;
    srand((unsigned)(time(NULL) ^ (getpid() << 16)));

    char line[2048];
    while (fgets(line, sizeof line, f)) {
        line[strcspn(line, "\r\n")] = 0;
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (!*p) continue;
        char name[1024], typestr[32];
        typestr[0] = 0;
        char *sp = strchr(p, ' ');
        if (sp) { *sp = 0; snprintf(typestr, sizeof typestr, "%s", sp + 1); }
        snprintf(name, sizeof name, "%s", p);

        int qtype = 0;
        if (!strcmp(typestr, "A")) qtype = 1;
        else if (!strcmp(typestr, "CNAME")) qtype = 5;
        else if (!strcmp(typestr, "MX")) qtype = 15;
        else if (!strcmp(typestr, "TXT")) qtype = 16;
        else if (!strcmp(typestr, "AAAA")) qtype = 28;
        else qtype = atoi(typestr);

        uint8_t q[4096]; size_t ql = 0;
        uint16_t id = (uint16_t)(rand() & 0xFFFF);
        q[ql++] = id >> 8; q[ql++] = id & 0xFF;
        q[ql++] = 0x01; q[ql++] = 0x00;
        q[ql++] = 0; q[ql++] = 1;
        q[ql++] = 0; q[ql++] = 0;
        q[ql++] = 0; q[ql++] = 0;
        char tmp[1024];
        snprintf(tmp, sizeof tmp, "%s", name);
        size_t tl = strlen(tmp);
        if (tl && tmp[tl-1] == '.') tmp[tl-1] = 0;
        if (tmp[0]) {
            char *lab = strtok(tmp, ".");
            while (lab) {
                size_t ll = strlen(lab);
                if (ll > 63) ll = 63;
                q[ql++] = (uint8_t)ll;
                memcpy(q + ql, lab, ll); ql += ll;
                lab = strtok(NULL, ".");
            }
        }
        q[ql++] = 0;
        q[ql++] = (uint8_t)(qtype >> 8); q[ql++] = (uint8_t)(qtype & 0xFF);
        q[ql++] = 0; q[ql++] = 1;

        struct sockaddr_in sa;
        memset(&sa, 0, sizeof sa);
        sa.sin_family = AF_INET;
        sa.sin_port = htons((uint16_t)port);
        sa.sin_addr.s_addr = htonl(0x7F000001);

        uint8_t *resp = NULL;
        size_t rlen = 0;
        uint8_t buf[65536];
        int tc = 0;

        int s = socket(AF_INET, SOCK_DGRAM, 0);
        if (s >= 0) {
            sendto(s, q, ql, 0, (struct sockaddr *)&sa, sizeof sa);
            for (;;) {
                ssize_t r = recvfrom(s, buf, sizeof buf, 0, NULL, NULL);
                if (r < 12) continue;
                uint16_t rid = (uint16_t)((buf[0] << 8) | buf[1]);
                if (rid != id) continue;
                if (!(buf[2] & 0x80)) continue;
                tc = (buf[2] >> 6) & 1;
                if (!tc) {
                    resp = malloc((size_t)r);
                    memcpy(resp, buf, (size_t)r);
                    rlen = (size_t)r;
                }
                break;
            }
            close(s);
        }

        if (tc) {
            int t = socket(AF_INET, SOCK_STREAM, 0);
            if (t >= 0 && connect(t, (struct sockaddr *)&sa, sizeof sa) == 0) {
                uint8_t lb[2] = { (uint8_t)(ql >> 8), (uint8_t)(ql & 0xFF) };
                if (write_all(t, lb, 2) == 0 && write_all(t, q, ql) == 0) {
                    uint8_t rb[2];
                    if (read_all(t, rb, 2) == 0) {
                        size_t need = ((size_t)rb[0] << 8) | rb[1];
                        resp = malloc(need ? need : 1);
                        if (read_all(t, resp, need) == 0) rlen = need;
                        else { free(resp); resp = NULL; }
                    }
                }
            }
            close(t);
        }

        if (!resp) continue;

        uint16_t flags = (uint16_t)((resp[2] << 8) | resp[3]);
        int rcode = flags & 0xF;
        int qd = (resp[4] << 8) | resp[5];
        int an = (resp[6] << 8) | resp[7];

        /* output name: lowercase, no trailing dot, root = "." */
        char outname[1100];
        snprintf(outname, sizeof outname, "%s", name);
        for (char *c = outname; *c; c++) *c = (char)tolower((unsigned char)*c);
        size_t ol = strlen(outname);
        if (ol && outname[ol-1] == '.') outname[ol-1] = 0;
        if (!outname[0]) strcpy(outname, ".");

        printf("%s %s %s\n", outname, typestr, rcode_str(rcode));

        size_t off = 12;
        for (int i = 0; i < qd && off < rlen; i++) {
            char *n = read_name(resp, rlen, &off);
            free(n);
            off += 4;
        }

        for (int i = 0; i < an && off + 10 <= rlen; i++) {
            char *owner = read_name(resp, rlen, &off);
            int type = (resp[off] << 8) | resp[off+1];
            /* class = resp[off+2..3] */
            uint32_t ttl = ((uint32_t)resp[off+4] << 24) | ((uint32_t)resp[off+5] << 16) |
                           ((uint32_t)resp[off+6] << 8) | resp[off+7];
            int rdlen = (resp[off+8] << 8) | resp[off+9];
            off += 10;
            if (off + (size_t)rdlen > rlen) { free(owner); break; }
            size_t doff = off;
            off += (size_t)rdlen;

            char data[65536];
            data[0] = 0;
            int known = 0;
            if (type == 1 && rdlen == 4) {
                sprintf(data, "%u.%u.%u.%u", resp[doff], resp[doff+1], resp[doff+2], resp[doff+3]);
                known = 1;
            } else if (type == 28 && rdlen == 16) {
                fmt_aaaa(resp + doff, data);
                known = 1;
            } else if (type == 5) {
                size_t o = doff;
                char *t2 = read_name(resp, rlen, &o);
                snprintf(data, sizeof data, "%s", t2);
                free(t2);
                known = 1;
            } else if (type == 15 && rdlen >= 3) {
                int pref = (resp[doff] << 8) | resp[doff+1];
                size_t o = doff + 2;
                char *t2 = read_name(resp, rlen, &o);
                snprintf(data, sizeof data, "%d %s", pref, t2);
                free(t2);
                known = 1;
            } else if (type == 16) {
                size_t o = doff, end = doff + (size_t)rdlen;
                size_t dl = 0;
                int first = 1;
                while (o < end) {
                    uint8_t l = resp[o++];
                    if (o + l > end) break;
                    if (!first) data[dl++] = ' ';
                    first = 0;
                    data[dl++] = '"';
                    for (int k = 0; k < l; k++) {
                        uint8_t c = resp[o + k];
                        if (c == '"') { data[dl++] = '\\'; data[dl++] = '"'; }
                        else if (c == '\\') { data[dl++] = '\\'; data[dl++] = '\\'; }
                        else if (c >= 0x20 && c <= 0x7E) data[dl++] = (char)c;
                        else { sprintf(data + dl, "\\%03u", c); dl += 4; }
                    }
                    data[dl++] = '"';
                    o += l;
                }
                data[dl] = 0;
                known = 1;
            }
            if (!known) {
                size_t dl = (size_t)sprintf(data, "\\# %d", rdlen);
                if (rdlen) {
                    data[dl++] = ' ';
                    for (int k = 0; k < rdlen; k++)
                        dl += (size_t)sprintf(data + dl, "%02x", resp[doff + k]);
                }
                data[dl] = 0;
            }
            printf("  %s %u %s %s\n", owner, (unsigned)ttl, type_name(type), data);
            free(owner);
        }
        free(resp);
    }
    fclose(f);
    return 0;
}

