import sys
import os
from decimal import Decimal, getcontext, ROUND_HALF_EVEN


def q(d, minor):
    return d.quantize(Decimal(1).scaleb(-minor), rounding=ROUND_HALF_EVEN)


def fmt(d, minor):
    d = q(d, minor)
    if d == 0:
        d = abs(d)
    sign = '-' if d < 0 else ''
    d = abs(d)
    s = format(d, 'f')
    if minor > 0:
        ip, fp = s.split('.')
    else:
        ip, fp = s, None
    groups = []
    while len(ip) > 3:
        groups.insert(0, ip[-3:])
        ip = ip[:-3]
    groups.insert(0, ip)
    out = sign + ','.join(groups)
    if minor > 0:
        out += '.' + fp
    return out


def main():
    getcontext().prec = 500
    directory = sys.argv[1]
    with open(os.path.join(directory, 'ledger.txt')) as f:
        lines = f.read().split('\n')

    currencies = {}
    accounts = {}  # name -> [code, balance, limit]
    rejects = []

    def first_unknown(names):
        for n in names:
            if n not in accounts:
                return n
        return None

    for lineno, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        parts = line.split()
        cmd = parts[0]
        reason = None

        if cmd == 'currency':
            currencies[parts[1]] = int(parts[2])

        elif cmd == 'open':
            name, code = parts[1], parts[2]
            if name in accounts:
                reason = 'account exists ' + name
            else:
                minor = currencies[code]
                if len(parts) > 3:
                    limit = q(Decimal(parts[3]), minor)
                else:
                    limit = Decimal(0).scaleb(-minor)
                accounts[name] = [code, Decimal(0).scaleb(-minor), limit]

        elif cmd in ('deposit', 'withdraw', 'interest'):
            name = parts[1]
            u = first_unknown([name])
            if u is not None:
                reason = 'unknown account ' + u
            else:
                minor = currencies[accounts[name][0]]
                if cmd == 'interest':
                    rate = Decimal(parts[2])
                    accounts[name][1] += q(accounts[name][1] * rate, minor)
                else:
                    amt = q(Decimal(parts[2]), minor)
                    if amt <= 0:
                        reason = 'non-positive amount'
                    elif cmd == 'withdraw':
                        bal, limit = accounts[name][1], accounts[name][2]
                        if bal - amt < -limit:
                            reason = 'insufficient funds ' + name
                        else:
                            accounts[name][1] = bal - amt
                    else:
                        accounts[name][1] = accounts[name][1] + amt

        elif cmd in ('transfer', 'convert'):
            src, dst = parts[1], parts[2]
            u = first_unknown([src, dst])
            if u is not None:
                reason = 'unknown account ' + u
            elif cmd == 'transfer' and accounts[src][0] != accounts[dst][0]:
                reason = 'currency mismatch'
            else:
                minor = currencies[accounts[src][0]]
                if cmd == 'transfer':
                    amt = q(Decimal(parts[3]), minor)
                else:
                    amt = q(Decimal(parts[3]), minor)
                if amt <= 0:
                    reason = 'non-positive amount'
                elif accounts[src][1] - amt < -accounts[src][2]:
                    reason = 'insufficient funds ' + src
                else:
                    accounts[src][1] -= amt
                    if cmd == 'convert':
                        rate = Decimal(parts[4])
                        dminor = currencies[accounts[dst][0]]
                        accounts[dst][1] += q(amt * rate, dminor)
                    else:
                        accounts[dst][1] += amt

        elif cmd == 'split':
            src = parts[1]
            targets = parts[3:]
            tnames = [t.split(':')[0] for t in targets]
            u = first_unknown([src] + tnames)
            if u is not None:
                reason = 'unknown account ' + u
            elif any(accounts[t][0] != accounts[src][0] for t in tnames):
                reason = 'currency mismatch'
            else:
                minor = currencies[accounts[src][0]]
                amt = q(Decimal(parts[2]), minor)
                if amt <= 0:
                    reason = 'non-positive amount'
                elif accounts[src][1] - amt < -accounts[src][2]:
                    reason = 'insufficient funds ' + src
                else:
