import sys, os, json, hmac, hashlib, base64, re

B64RE = re.compile(r'^[A-Za-z0-9_-]+$')

def b64decode(seg):
    if not B64RE.match(seg):
        raise ValueError
    if len(seg) % 4 != 1:
        raise ValueError
    return base64.urlsafe_b64decode(seg + '=' * (-len(seg) % 4))

def main():
    d = sys.argv[1]
    with open(os.path.join(d, 'config.json'), encoding='utf-8') as f:
        cfg = json.load(f)
    now = cfg['now']; leeway = cfg['leeway']
    issuer = cfg['issuer']; audience = cfg['audience']
    keys = {k['kid']: k for k in cfg['keys']}
    alg_hash = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}

    results = []
    valid = invalid = 0
    with open(os.path.join(d, 'tokens.txt'), encoding='utf-8') as f:
        n = 0
        for raw in f:
            tok = raw.strip(' \t\r\n')
            if not tok:
                continue
            n += 1
            res = check(tok, keys, alg_hash, now, leeway, issuer, audience)
            if isinstance(res, str):
                invalid += 1
                results.append(f'{n}: {res}')
            else:
                valid += 1
                sub, scopes = res
                results.append(f'{n}: VALID sub={sub} scope={scopes}')
    print('\n'.join(results))
    print()
    print(f'valid={valid} invalid={invalid}')

def check(tok, keys, alg_hash, now, leeway, issuer, audience):
    parts = tok.split('.')
    if len(parts) != 3:
        return 'MALFORMED'
    try:
        hb = b64decode(parts[0]); pb = b64decode(parts[1]); sb = b64decode(parts[2])
        header = json.loads(hb.decode('utf-8'))
        payload = json.loads(pb.decode('utf-8'))
    except Exception:
        return 'MALFORMED'
    if not isinstance(header, dict) or not isinstance(payload, dict):
        return 'MALFORMED'
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in alg_hash:
        return 'UNSUPPORTED_ALG'
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys:
        return 'UNKNOWN_KEY'
    key = keys[kid]
    if key['alg'] != alg:
        return 'ALG_MISMATCH'
    secret = base64.urlsafe_b64decode(key['k'] + '=' * (-len(key['k']) % 4))
    expected = hmac.new(secret, f'{parts[0]}.{parts[1]}'.encode('ascii'), alg_hash[alg]).digest()
    if len(sb) != len(expected) or not hmac.compare_digest(sb, expected):
        return 'BAD_SIGNATURE'
    exp = payload.get('exp')
    if exp is not None and now >= exp + leeway:
        return 'EXPIRED'
    nbf = payload.get('nbf')
    if nbf is not None and now + leeway < nbf:
        return 'NOT_YET_VALID'
    if payload.get('iss') != issuer:
        return 'BAD_ISSUER'
    aud = payload.get('aud')
    ok = False
    if isinstance(aud, str):
        ok = aud == audience
    elif isinstance(aud, list):
        ok = any(a == audience for a in aud)
    if not ok:
        return 'BAD_AUDIENCE'
    sub = payload['sub']
    scope = payload.get('scope', '')
    pieces = sorted({p for p in scope.split(' ') if p})
    return sub, ','.join(pieces)

