import Foundation
import CryptoKit

func b64urlDecode(_ s: String) -> Data? {
    let chars = Array(s.unicodeScalars)
    for c in chars {
        if !((c >= "A" && c <= "Z") || (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-" || c == "_") {
            return nil
        }
    }
    var out: [UInt8] = []
    var vals: [Int] = []
    for c in chars {
        var v: Int
        switch c {
        case "A"..."Z": v = Int(c.value - 65)
        case "a"..."z": v = Int(c.value - 97 + 26)
        case "0"..."9": v = Int(c.value - 48 + 52)
        case "-": v = 62
        case "_": v = 63
        default: return nil
        }
        vals.append(v)
        if vals.count == 4 {
            out.append(UInt8((vals[0] << 2) | (vals[1] >> 4)))
            out.append(UInt8(((vals[1] & 0xF) << 4) | (vals[2] >> 2)))
            out.append(UInt8(((vals[2] & 0x3) << 6) | vals[3]))
            vals = []
        }
    }
    switch vals.count {
    case 0: break
    case 2:
        out.append(UInt8((vals[0] << 2) | (vals[1] >> 4)))
    case 3:
        out.append(UInt8((vals[0] << 2) | (vals[1] >> 4)))
        out.append(UInt8(((vals[1] & 0xF) << 4) | (vals[2] >> 2)))
    default:
        return nil
    }
    return Data(out)
}

func asDouble(_ v: Any) -> Double? {
    if let n = v as? NSNumber {
        if CFGetTypeID(n) == CFBooleanGetTypeID() { return nil }
        return n.doubleValue
    }
    return nil
}

func asString(_ v: Any) -> String? { v as? String }

func main() {
    let args = CommandLine.arguments
    guard args.count == 2 else { exit(1) }
    let dir = args[1]
    let fm = FileManager.default

    guard let cfgData = fm.contents(atPath: dir + "/config.json"),
          let cfg = try? JSONSerialization.jsonObject(with: cfgData) as? [String: Any] else { exit(1) }
    guard let now = asDouble(cfg["now"] ?? NSNumber(value: 0)),
          let leeway = asDouble(cfg["leeway"] ?? NSNumber(value: 0)),
          let issuer = cfg["issuer"] as? String,
          let audience = cfg["audience"] as? String,
          let keysArr = cfg["keys"] as? [[String: Any]] else { exit(1) }

    var keys: [String: (alg: String, secret: Data)] = [:]
    for k in keysArr {
        guard let kid = k["kid"] as? String,
              let kty = k["kty"] as? String, kty == "oct",
              let alg = k["alg"] as? String,
              let kb64 = k["k"] as? String,
              let secret = b64urlDecode(kb64) else { continue }
        keys[kid] = (alg, secret)
    }

    guard let textData = fm.contents(atPath: dir + "/tokens.txt"),
          let text = String(data: textData, encoding: .utf8) else { exit(1) }

    var results: [String] = []
    var valid = 0, invalid = 0
    var n = 0

    for rawLine in text.components(separatedBy: "\n") {
        let line = rawLine.trimmingCharacters(in: CharacterSet(charactersIn: " \t\r"))
        if line.isEmpty { continue }
        n += 1
        let result = verify(token: line, keys: keys, now: now, leeway: leeway, issuer: issuer, audience: audience)
        if result.hasPrefix("VALID") { valid += 1 } else { invalid += 1 }
        results.append("\(n): \(result)")
    }

    print(results.joined(separator: "\n"))
    print()
    print("valid=\(valid) invalid=\(invalid)")
}

func verify(token: String, keys: [String: (alg: String, secret: Data)], now: Double, leeway: Double, issuer: String, audience: String) -> String {
    let segs = token.components(separatedBy: ".")
    guard segs.count == 3 else { return "MALFORMED" }
    for s in segs {
        guard !s.isEmpty, let d = b64urlDecode(s) else { return "MALFORMED" }
        _ = d
    }
    guard let headerData = b64urlDecode(segs[0]),
          let payloadData = b64urlDecode(segs[1]) else { return "MALFORMED" }
    guard let header = try? JSONSerialization.jsonObject(with: headerData) as? [String: Any],
          let payload = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else { return "MALFORMED" }

    guard let alg = header["alg"] as? String, ["HS256", "HS384", "HS512"].contains(alg) else { return "UNSUPPORTED_ALG" }

    guard let kid = header["kid"] as? String, let key = keys[kid] else { return "UNKNOWN_KEY" }
    guard key.alg == alg else { return "ALG_MISMATCH" }

    let signingInput = Data((segs[0] + "." + segs[1]).utf8)
    let expected: Data
    switch alg {
    case "HS256": expected = Data(HMAC<SHA256>.authenticationCode(for: signingInput, using: SymmetricKey(data: key.secret)))
    case "HS384": expected = Data(HMAC<SHA384>.authenticationCode(for: signingInput, using: SymmetricKey(data: key.secret)))
    default: expected = Data(HMAC<SHA512>.authenticationCode(for: signingInput, using: SymmetricKey(data: key.secret)))
    }
    guard let sig = b64urlDecode(segs[2]), sig == expected else { return "BAD_SIGNATURE" }

    if let exp = payload["exp"].flatMap(asDouble), now >= exp + leeway { return "EXPIRED" }
    if let nbf = payload["nbf"].flatMap(asDouble), now + leeway < nbf { return "NOT_YET_VALID" }
    guard let iss = payload["iss"] as? String, iss == issuer else { return "BAD_ISSUER" }

    if let aud = payload["aud"] {
        if let s = aud as? String {
            if s != audience { return "BAD_AUDIENCE" }
        } else if let arr = aud as? [Any] {
            if !arr.contains(where: { ($0 as? String) == audience }) { return "BAD_AUDIENCE" }
        } else {
            return "BAD_AUDIENCE"
        }
    } else {
        return "BAD_AUDIENCE"
    }

    let sub = payload["sub"] as? String ?? ""
    var scopes: Set<String> = []
    if let scope = payload["scope"] as? String {
        for piece in scope.components(separatedBy: " ") where !piece.isEmpty {
            scopes.insert(piece)
        }
    }
    let sorted = scopes.sorted { $0 < $1 }
    return "VALID sub=\(sub) scope=\(sorted.joined(separator: ","))"
}

main()

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

interface KeyDef { kid: string; kty: string; alg: string; k: string; }
interface Config {
  now: number; leeway: number; issuer: string; audience: string; keys: KeyDef[];
}

const dir = process.argv[2];
const config: Config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf8'));
const text = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf8');

const B64URL_RE = /^[A-Za-z0-9_-]+$/;
const HASHES: Record<string, string> = { HS256: 'sha256', HS384: 'sha384', HS512: 'sha512' };

function decodeSeg(seg: string): Buffer | null {
  if (!B64URL_RE.test(seg)) return null;
  if (seg.length % 4 === 1) return null;
  return Buffer.from(seg, 'base64url');
}

function isObj(x: unknown): x is Record<string, unknown> {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

function cpCompare(a: string, b: string): number {
  const ai = Array.from(a).map(c => c.codePointAt(0)!);
  const bi = Array.from(b).map(c => c.codePointAt(0)!);
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    if (ai[i] !== bi[i]) return ai[i] - bi[i];
  }
  return ai.length - bi.length;
}

const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);

let valid = 0, invalid = 0;
const out: string[] = [];

lines.forEach((line, idx) => {
  const n = idx + 1;
  const result = check(line);
  if (result.startsWith('VALID')) valid++; else invalid++;
  out.push(`${n}: ${result}`);
});

function check(token: string): string {
  const segs = token.split('.');
  if (segs.length !== 3) return 'MALFORMED';
  const [h, p, s] = segs;
  if (h.length === 0 || p.length === 0 || s.length === 0) return 'MALFORMED';
  const hb = decodeSeg(h), pb = decodeSeg(p), sb = decodeSeg(s);
  if (!hb || !pb || !sb) return 'MALFORMED';
  let header: unknown, payload: unknown;
  try {
    header = JSON.parse(hb.toString('utf8'));
    payload = JSON.parse(pb.toString('utf8'));
  } catch {
    return 'MALFORMED';
  }
  if (!isObj(header) || !isObj(payload)) return 'MALFORMED';

  const alg = header['alg'];
  if (typeof alg !== 'string' || !(alg in HASHES)) return 'UNSUPPORTED_ALG';

  const kid = header['kid'];
  if (typeof kid !== 'string') return 'UNKNOWN_KEY';
  const key = config.keys.find(k => k.kid === kid);
  if (!key) return 'UNKNOWN_KEY';

  if (key.alg !== alg) return 'ALG_MISMATCH';

  const secret = Buffer.from(key.k, 'base64url');
  const expected = crypto.createHmac(HASHES[alg], secret)
    .update(h + '.' + p, 'ascii').digest();
  if (sb.length !== expected.length || !crypto.timingSafeEqual(sb, expected)) {
    return 'BAD_SIGNATURE';
  }

  const exp = payload['exp'];
  if (exp !== undefined && typeof exp === 'number' &&
      config.now >= exp + config.leeway) return 'EXPIRED';

  const nbf = payload['nbf'];
  if (nbf !== undefined && typeof nbf === 'number' &&
      config.now + config.leeway < nbf) return 'NOT_YET_VALID';

  const iss = payload['iss'];
  if (typeof iss !== 'string' || iss !== config.issuer) return 'BAD_ISSUER';

  const aud = payload['aud'];
  const audOk =
    (typeof aud === 'string' && aud === config.audience) ||
    (Array.isArray(aud) && aud.some(a => a === config.audience));
  if (!audOk) return 'BAD_AUDIENCE';

  const sub = payload['sub'] as string;
  const scopeRaw = typeof payload['scope'] === 'string' ? payload['scope'] : '';
  const scopes = Array.from(new Set(scopeRaw.split(' ').filter(x => x.length > 0)))
    .sort(cpCompare).join(',');
  return `VALID sub=${sub} scope=${scopes}`;
}

