    static class Json {
        private final String s;
        private int i;
        Json(String s) { this.s = s; }

        static Object parse(String text) {
            Json p = new Json(text);
            p.ws();
            Object v = p.value();
            p.ws();
            if (p.i != p.s.length()) throw new RuntimeException("trailing");
            return v;
        }

        private void ws() {
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') i++;
                else break;
            }
        }

        private Object value() {
            if (i >= s.length()) throw new RuntimeException("eof");
            char c = s.charAt(i);
            switch (c) {
                case '{': return object();
                case '[': return array();
                case '"': return string();
                case 't': expect("true"); return Boolean.TRUE;
                case 'f': expect("false"); return Boolean.FALSE;
                case 'n': expect("null"); return null;
                default: return number();
            }
        }

        private void expect(String w) {
            if (!s.startsWith(w, i)) throw new RuntimeException("literal");
            i += w.length();
        }

        private Map<String, Object> object() {
            i++; // {
            Map<String, Object> m = new LinkedHashMap<>();
            ws();
            if (i < s.length() && s.charAt(i) == '}') { i++; return m; }
            while (true) {
                ws();
                if (i >= s.length() || s.charAt(i) != '"') throw new RuntimeException("key");
                String k = string();
                ws();
                if (i >= s.length() || s.charAt(i) != ':') throw new RuntimeException("colon");
                i++;
                ws();
                m.put(k, value());
                ws();
                if (i < s.length() && s.charAt(i) == ',') { i++; continue; }
                if (i < s.length() && s.charAt(i) == '}') { i++; return m; }
                throw new RuntimeException("obj");
            }
        }

        private List<Object> array() {
            i++; // [
            List<Object> l = new ArrayList<>();
            ws();
            if (i < s.length() && s.charAt(i) == ']') { i++; return l; }
            while (true) {
                ws();
                l.add(value());
                ws();
                if (i < s.length() && s.charAt(i) == ',') { i++; continue; }
                if (i < s.length() && s.charAt(i) == ']') { i++; return l; }
                throw new RuntimeException("arr");
            }
        }

        private String string() {
            i++; // "
            StringBuilder sb = new StringBuilder();
            while (true) {
                if (i >= s.length()) throw new RuntimeException("str");
                char c = s.charAt(i++);
                if (c == '"') return sb.toString();
                if (c == '\\') {
                    if (i >= s.length()) throw new RuntimeException("esc");
                    char e = s.charAt(i++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (i + 4 > s.length()) throw new RuntimeException("u");
                            sb.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
                            i += 4;
                            break;
                        default: throw new RuntimeException("esc");
                    }
                } else {
                    sb.append(c);
                }
            }
        }

        private Double number() {
            int start = i;
            while (i < s.length()) {
                char c = s.charAt(i);
                if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E') i++;
                else break;
            }
            if (i == start) throw new RuntimeException("num");
            try {
                return Double.parseDouble(s.substring(start, i));
            } catch (NumberFormatException e) {
                throw new RuntimeException("num");
            }
        }
    }

    // ---------- base64url helpers ----------
    static boolean isB64Url(String seg) {
        if (seg.isEmpty()) return false;
        for (char c : seg.toCharArray()) {
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'))
                return false;
        }
        return seg.length() % 4 == 1;
    }

    static byte[] b64(String seg) {
        return Base64.getUrlDecoder().decode(seg);
    }

    // ---------- main ----------
    public static void main(String[] args) throws Exception {
        PrintStream out = new PrintStream(new FileOutputStream(FileDescriptor.out), true, StandardCharsets.UTF_8);
        Path dir = Paths.get(args[0]);
        String configText = Files.readString(dir.resolve("config.json"), StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) Json.parse(configText);

        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");

        Map<String, Map<String, Object>> keys = new HashMap<>();
        for (Object o : (List<Object>) config.get("keys")) {
            Map<String, Object> k = (Map<String, Object>) o;
            keys.put((String) k.get("kid"), k);
        }

        String tokensText = Files.readString(dir.resolve("tokens.txt"), StandardCharsets.UTF_8);
        List<String> tokens = new ArrayList<>();
        for (String line : tokensText.split("\n", -1)) {
            String t = line.trim();
            if (!t.isEmpty()) tokens.add(t);
        }

        int valid = 0, invalid = 0;
        int n = 0;
        for (String token : tokens) {
            n++;
            String result = verify(token, keys, now, leeway, issuer, audience);
            if (result == null) {
                valid++;
                Map<String, Object> payload = payloadOf(token);
                String sub = (String) payload.get("sub");
                String scope = payload.get("scope") instanceof String ? (String) payload.get("scope") : "";
                Set<String> scopes = new TreeSet<>((a, b) -> {
                    int i = 0, j = 0;
                    while (i < a.length() && j < b.length()) {
                        int ca = a.codePointAt(i), cb = b.codePointAt(j);
                        if (ca != cb) return ca - cb;
                        i += Character.charCount(ca);
                        j += Character.charCount(cb);
                    }
                    return (a.length() - i) - (b.length() - j);
                });
                for (String p : scope.split(" ")) if (!p.isEmpty()) scopes.add(p);
                out.println(n + ": VALID sub=" + sub + " scope=" + String.join(",", scopes));
            } else {
                invalid++;
                out.println(n + ": " + result);
            }
        }
        out.println();
        out.println("valid=" + valid + " invalid=" + invalid);
    }

    static Map<String, Object> payloadOf(String token) throws Exception {
        String[] seg = token.split("\\.", -1);
        return (Map<String, Object>) Json.parse(new String(b64(seg[1]), StandardCharsets.UTF_8));
    }

    static String verify(String token, Map<String, Map<String, Object>> keys,
                         double now, double leeway, String issuer, String audience) {
        try {
            // 1. MALFORMED
            String[] seg = token.split("\\.", -1);
            if (seg.length != 3) return "MALFORMED";
            for (String s : seg) if (!isB64Url(s)) return "MALFORMED";
            Object headerO, payloadO;
            try {
                headerO = Json.parse(new String(b64(seg[0]), StandardCharsets.UTF_8));
                payloadO = Json.parse(new String(b64(seg[1]), StandardCharsets.UTF_8));
            } catch (RuntimeException e) {
                return "MALFORMED";
            }
            if (!(headerO instanceof Map) || !(payloadO instanceof Map)) return "MALFORMED";
            Map<String, Object> header = (Map<String, Object>) headerO;
            Map<String, Object> payload = (Map<String, Object>) payloadO;

            // 2. UNSUPPORTED_ALG
            Object algO = header.get("alg");
            if (!(algO instanceof String)) return "UNSUPPORTED_ALG";
            String alg = (String) algO;
            if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) return "UNSUPPORTED_ALG";

            // 3. UNKNOWN_KEY
            Object kidO = header.get("kid");
            if (!(kidO instanceof String)) return "UNKNOWN_KEY";
            Map<String, Object> key = keys.get(kidO);
            if (key == null) return "UNKNOWN_KEY";

            // 4. ALG_MISMATCH
            if (!alg.equals(key.get("alg"))) return "ALG_MISMATCH";

            // 5. BAD_SIGNATURE
            byte[] secret = b64((String) key.get("k"));
            String macName;
            switch (alg) {
                case "HS256": macName = "HmacSHA256"; break;
                case "HS384": macName = "HmacSHA384"; break;
                default: macName = "HmacSHA512"; break;
            }
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance(macName);
            mac.init(new javax.crypto.spec.SecretKeySpec(secret, macName));
            byte[] signingInput = (seg[0] + "." + seg[1]).getBytes(StandardCharsets.US_ASCII);
            byte[] expected = mac.doFinal(signingInput);
            byte[] actual;
            try {
                actual = b64(seg[2]);
            } catch (RuntimeException e) {
                return "MALFORMED";
            }
            if (!MessageDigest.isEqual(expected, actual)) return "BAD_SIGNATURE";

            // 6. EXPIRED
            if (payload.get("exp") instanceof Number) {
                double exp = ((Number) payload.get("exp")).doubleValue();
                if (now >= exp + leeway) return "EXPIRED";
            }

            // 7. NOT_YET_VALID
            if (payload.get("nbf") instanceof Number) {
                double nbf = ((Number) payload.get("nbf")).doubleValue();
                if (now + leeway < nbf) return "NOT_YET_VALID";
            }

            // 8. BAD_ISSUER
            if (!issuer.equals(payload.get("iss"))) return "BAD_ISSUER";

            // 9. BAD_AUDIENCE
            Object aud = payload.get("aud");
            boolean audOk = false;
            if (aud instanceof String) {
                audOk = aud.equals(audience);
            } else if (aud instanceof List) {
                for (Object a : (List<?>) aud) if (audience.equals(a)) { audOk = true; break; }
            }
            if (!audOk) return "BAD_AUDIENCE";

            return null;
        } catch (Exception e) {
            return "MALFORMED";
        }
    }
}

