            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'))
                return false;
        }
        // invalid if length is 1 more than a multiple of 4
        return seg.length() % 4 != 1;
    }

    static byte[] b64(String seg) {
