    static Map<String, Object> payloadOf(String token) throws Exception {
        String[] seg = token.split("\\.", -1);
        return (Map<String, Object>) Json.parse(new String(b64(seg[1]), StandardCharsets.UTF_8));
    }

    static String verify(String token, Map<String, Map<String, Object>> keys,
                         double now, double leeway, String issuer, String audience) {
        try {
            // 1. MALFORMED
            String[] seg = token.split("\\.", -1);
            if (seg.length != 3) return "MALFORMED";
            for (String s : seg) if (!isB64Url(s)) return "MALFORMED";
            Object headerO, payloadO;
            try {
                headerO = Json.parse(new String(b64(seg[0]), StandardCharsets.UTF_8));
                payloadO = Json.parse(new String(b64(seg[1]), StandardCharsets.UTF_8));
            } catch (RuntimeException e) {
                return "MALFORMED";
            }
            if (!(headerO instanceof Map) || !(payloadO instanceof Map)) return "MALFORMED";
            Map<String, Object> header = (Map<String, Object>) headerO;
            Map<String, Object> payload = (Map<String, Object>) payloadO;

            // 2. UNSUPPORTED_ALG
            Object algO = header.get("alg");
            if (!(algO instanceof String)) return "UNSUPPORTED_ALG";
            String alg = (String) algO;
            if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) return "UNSUPPORTED_ALG";

            // 3. UNKNOWN_KEY
            Object kidO = header.get("kid");
            if (!(kidO instanceof String)) return "UNKNOWN_KEY";
            Map<String, Object> key = keys.get(kidO);
            if (key == null) return "UNKNOWN_KEY";

            // 4. ALG_MISMATCH
            if (!alg.equals(key.get("alg"))) return "ALG_MISMATCH";

            // 5. BAD_SIGNATURE
            byte[] secret = b64((String) key.get("k"));
            String macName;
            switch (alg) {
                case "HS256": macName = "HmacSHA256"; break;
                case "HS384": macName = "HmacSHA384"; break;
                default: macName = "HmacSHA512"; break;
            }
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance(macName);
            mac.init(new javax.crypto.spec.SecretKeySpec(secret, macName));
            byte[] signingInput = (seg[0] + "." + seg[1]).getBytes(StandardCharsets.US_ASCII);
            byte[] expected = mac.doFinal(signingInput);
            byte[] actual;
            try {
                actual = b64(seg[2]);
            } catch (RuntimeException e) {
                return "MALFORMED";
            }
            if (!MessageDigest.isEqual(expected, actual)) return "BAD_SIGNATURE";

            // 6. EXPIRED
            if (payload.get("exp") instanceof Number) {
                double exp = ((Number) payload.get("exp")).doubleValue();
                if (now >= exp + leeway) return "EXPIRED";
            }

            // 7. NOT_YET_VALID
            if (payload.get("nbf") instanceof Number) {
                double nbf = ((Number) payload.get("nbf")).doubleValue();
                if (now + leeway < nbf) return "NOT_YET_VALID";
            }

            // 8. BAD_ISSUER
            if (!issuer.equals(payload.get("iss"))) return "BAD_ISSUER";

            // 9. BAD_AUDIENCE
