#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct Value Value;
typedef struct { char *name; Value *val; } Member;

struct Value {
    int type; /* 0 null,1 bool,2 num,3 str,4 arr,5 obj */
    int b;
    double num;
    char *str; size_t slen;
    Value **items; size_t n;
    Member *mem; size_t m;
};

static Value *root;

static void die(const char *m){ fprintf(stderr, "%s\n", m); exit(1); }

static Value *newval(int t){ Value *v = calloc(1, sizeof(Value)); v->type = t; return v; }

/* ---------- dynamic char buffer ---------- */
typedef struct { char *d; size_t n, cap; } Buf;
static void bpush(Buf *b, char c){
    if(b->n + 1 >= b->cap){ b->cap = b->cap ? b->cap * 2 : 16; b->d = realloc(b->d, b->cap); }
    b->d[b->n++] = c;
}
static void utf8_enc(Buf *b, unsigned cp){
    if(cp < 0x80) bpush(b, (char)cp);
    else if(cp < 0x800){ bpush(b, (char)(0xC0|(cp>>6))); bpush(b, (char)(0x80|(cp&0x3F))); }
    else if(cp < 0x10000){ bpush(b,(char)(0xE0|(cp>>12))); bpush(b,(char)(0x80|((cp>>6)&0x3F))); bpush(b,(char)(0x80|(cp&0x3F))); }
    else { bpush(b,(char)(0xF0|(cp>>18))); bpush(b,(char)(0x80|((cp>>12)&0x3F))); bpush(b,(char)(0x80|((cp>>6)&0x3F))); bpush(b,(char)(0x80|(cp&0x3F))); }
}

/* ---------- parser ---------- */
static char *src; static size_t pos, slen;

static void skipws(void){
    while(pos < slen){ char c = src[pos];
        if(c==' '||c=='\t'||c=='\n'||c=='\r') pos++; else break; }
}
static unsigned hex4(void){
    unsigned v = 0;
    for(int i = 0; i < 4; i++){
        char c = src[pos++];
        v *= 16;
        if(c <= '9') v += (unsigned)(c - '0');
        else if(c <= 'F') v += (unsigned)(c - 'A' + 10);
        else v += (unsigned)(c - 'a' + 10);
    }
    return v;
}
static char *parse_string_raw(size_t *outlen){
    pos++; /* opening quote */
    Buf b = {0};
    while(pos < slen && src[pos] != '"'){
        unsigned char c = (unsigned char)src[pos];
        if(c == '\\'){
            pos++;
            char e = src[pos++];
            switch(e){
                case '"': bpush(&b,'"'); break;
                case '\\': bpush(&b,'\\'); break;
                case '/': bpush(&b,'/'); break;
                case 'b': bpush(&b,'\b'); break;
                case 'f': bpush(&b,'\f'); break;
                case 'n': bpush(&b,'\n'); break;
                case 'r': bpush(&b,'\r'); break;
                case 't': bpush(&b,'\t'); break;
                case 'u': {
                    unsigned cp = hex4();
                    if(cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < slen &&
                       src[pos] == '\\' && src[pos+1] == 'u'){
                        size_t save = pos; pos += 2;
                        unsigned lo = hex4();
                        if(lo >= 0xDC00 && lo <= 0xDFFF)
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        else pos = save;
                    }
                    utf8_enc(&b, cp);
                    break;
                }
                default: die("bad escape");
            }
        } else { bpush(&b, (char)c); pos++; }
    }
    if(pos >= slen) die("unterminated string");
    pos++; /* closing quote */
    bpush(&b, '\0');
    if(outlen) *outlen = b.n - 1;
    return b.d;
}
static Value *parse_value(void){
    skipws();
    if(pos >= slen) die("eof");
    char c = src[pos];
    if(c == '{'){
        pos++; Value *v = newval(5);
        skipws();
        if(src[pos] == '}'){ pos++; return v; }
        for(;;){
            skipws();
            if(src[pos] != '"') die("bad key");
            char *k = parse_string_raw(NULL);
            skipws();
            if(src[pos] != ':') die("expected :");
            pos++;
            Value *val = parse_value();
            v->mem = realloc(v->mem, (v->m + 1) * sizeof(Member));
            v->mem[v->m].name = k; v->mem[v->m].val = val; v->m++;
            skipws();
            if(src[pos] == ','){ pos++; continue; }
            if(src[pos] == '}'){ pos++; break; }
            die("bad object");
        }
        return v;
    }
    if(c == '['){
        pos++; Value *v = newval(4);
        skipws();
        if(src[pos] == ']'){ pos++; return v; }
        for(;;){
            Value *val = parse_value();
            v->items = realloc(v->items, (v->n + 1) * sizeof(Value *));
            v->items[v->n++] = val;
            skipws();
            if(src[pos] == ','){ pos++; continue; }
            if(src[pos] == ']'){ pos++; break; }
            die("bad array");
        }
        return v;
    }
    if(c == '"'){
        size_t l; char *s = parse_string_raw(&l);
        Value *v = newval(3); v->str = s; v->slen = l; return v;
    }
    if(!strncmp(src + pos, "true", 4)){ pos += 4; Value *v = newval(1); v->b = 1; return v; }
    if(!strncmp(src + pos, "false", 5)){ pos += 5; Value *v = newval(1); v->b = 0; return v; }
    if(!strncmp(src + pos, "null", 4)){ pos += 4; return newval(0); }
    /* number */
    size_t st = pos;
    if(src[pos] == '-') pos++;
    while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++;
    if(pos < slen && src[pos] == '.'){ pos++; while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++; }
    if(pos < slen && (src[pos] == 'e' || src[pos] == 'E')){
        pos++;
        if(pos < slen && (src[pos] == '+' || src[pos] == '-')) pos++;
        while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++;
    }
    size_t l = pos - st;
    char *tmp = malloc(l + 1);
    memcpy(tmp, src + st, l); tmp[l] = 0;
    Value *v = newval(2);
    v->num = strtod(tmp, NULL);
    free(tmp);
    return v;
}

/* ---------- helpers ---------- */
static Value *get(Value *o, const char *name){
    if(!o || o->type != 5) return NULL;
    for(size_t i = 0; i < o->m; i++)
        if(!strcmp(o->mem[i].name, name)) return o->mem[i].val;
    return NULL;
}
static size_t cpcount(const char *s){
    size_t c = 0;
    while(*s){ if((((unsigned char)*s) & 0xC0) != 0x80) c++; s++; }
    return c;
}
static int deq(Value *a, Value *b){
    if(a->type != b->type) return 0;
    switch(a->type){
        case 0: return 1;
        case 1: return a->b == b->b;
        case 2: return a->num == b->num;
        case 3: return a->slen == b->slen && memcmp(a->str, b->str, a->slen) == 0;
        case 4:
            if(a->n != b->n) return 0;
            for(size_t i = 0; i < a->n; i++) if(!deq(a->items[i], b->items[i])) return 0;
            return 1;
        case 5:
            if(a->m != b->m) return 0;
            for(size_t i = 0; i < a->m; i++){
                Value *bv = get(b, a->mem[i].name);
                if(!bv || !deq(a->mem[i].val, bv)) return 0;
            }
            return 1;
    }
    return 0;
}
static int matchtype(const char *t, Value *v){
    if(!strcmp(t, "null")) return v->type == 0;
    if(!strcmp(t, "boolean")) return v->type == 1;
    if(!strcmp(t, "object")) return v->type == 5;
    if(!strcmp(t, "array")) return v->type == 4;
    if(!strcmp(t, "string")) return v->type == 3;
    if(!strcmp(t, "number")) return v->type == 2;
    if(!strcmp(t, "integer")) return v->type == 2 && v->num == floor(v->num);
    return 0;
}

/* ---------- pointer paths ---------- */
static char *esc_tok(const char *t){
    size_t l = strlen(t);
    char *r = malloc(2 * l + 1);
    size_t j = 0;
    for(size_t i = 0; i < l; i++){
        if(t[i] == '~'){ r[j++] = '~'; r[j++] = '0'; }
        else if(t[i] == '/'){ r[j++] = '~'; r[j++] = '1'; }
        else r[j++] = t[i];
    }
    r[j] = 0;
    return r;
}
static char *child(const char *p, const char *rawtok){
    char *e = esc_tok(rawtok);
    char *r = malloc(strlen(p) + strlen(e) + 2);
    sprintf(r, "%s/%s", p, e);
    free(e);
    return r;
}
static char *childi(const char *p, size_t i){
    char b[32];
    sprintf(b, "%zu", i);
    return child(p, b);
}
static char *unescape_tok(const char *t){
    size_t l = strlen(t);
    char *r = malloc(l + 1);
    size_t j = 0;
    for(size_t i = 0; i < l; i++){
        if(t[i] == '~' && i + 1 < l){
            if(t[i+1] == '0'){ r[j++] = '~'; i++; }
            else if(t[i+1] == '1'){ r[j++] = '/'; i++; }
            else r[j++] = t[i];
        } else r[j++] = t[i];
    }
    r[j] = 0;
    return r;
}

/* ---------- errors ---------- */
typedef struct { char *inst, *sch; } Err;
typedef struct { Err *e; size_t n, cap; } ErrList;
static ErrList *cur;

static void adderr(const char *ip, const char *sp){
    for(size_t i = 0; i < cur->n; i++)
        if(!strcmp(cur->e[i].inst, ip) && !strcmp(cur->e[i].sch, sp)) return;
    if(cur->n + 1 > cur->cap){
        cur->cap = cur->cap ? cur->cap * 2 : 16;
        cur->e = realloc(cur->e, cur->cap * sizeof(Err));
    }
    cur->e[cur->n].inst = strdup(ip);
    cur->e[cur->n].sch = strdup(sp);
    cur->n++;
}
static int accepts(Value *s, const char *sp, Value *v, const char *ip){
    ErrList tmp = {0};
    ErrList *old = cur;
    cur = &tmp;
    validate(s, sp, v, ip);
    cur = old;
    int ok = (tmp.n == 0);
    free(tmp.e);
    return ok;
}

/* ---------- validation ---------- */
static void validate(Value *s, const char *sp, Value *v, const char *ip){
    if(s->type == 1){
        if(!s->b) adderr(ip, sp);
        return;
    }
    if(s->type != 5) return;

    Value *m;
    if((m = get(s, "type"))){
        int ok = 0;
        if(m->type == 3) ok = matchtype(m->str, v);
        else if(m->type == 4){
            for(size_t i = 0; i < m->n; i++)
                if(m->items[i]->type == 3 && matchtype(m->items[i]->str, v)){ ok = 1; break; }
        }
        if(!ok) adderr(ip, child(sp, "type"));
    }
    if((m = get(s, "enum")) && m->type == 4){
        int ok = 0;
        for(size_t i = 0; i < m->n; i++) if(deq(v, m->items[i])){ ok = 1; break; }
        if(!ok) adderr(ip, child(sp, "enum"));
    }
    if((m = get(s, "const")) && !deq(v, m))
        adderr(ip, child(sp, "const"));

    if(v->type == 2){
        if((m = get(s, "minimum")) && !(v->num >= m->num)) adderr(ip, child(sp, "minimum"));
        if((m = get(s, "maximum")) && !(v->num <= m->num)) adderr(ip, child(sp, "maximum"));
        if((m = get(s, "exclusiveMinimum")) && !(v->num > m->num)) adderr(ip, child(sp, "exclusiveMinimum"));
        if((m = get(s, "exclusiveMaximum")) && !(v->num < m->num)) adderr(ip, child(sp, "exclusiveMaximum"));
    }
    if(v->type == 3){
        size_t cp = cpcount(v->str);
        if((m = get(s, "minLength")) && !((double)cp >= m->num)) adderr(ip, child(sp, "minLength"));
        if((m = get(s, "maxLength")) && !((double)cp <= m->num)) adderr(ip, child(sp, "maxLength"));
    }
    if(v->type == 4){
        if((m = get(s, "minItems")) && !((double)v->n >= m->num)) adderr(ip, child(sp, "minItems"));
        if((m = get(s, "maxItems")) && !((double)v->n <= m->num)) adderr(ip, child(sp, "maxItems"));
        if((m = get(s, "uniqueItems")) && m->type == 1 && m->b){
            for(size_t i = 0; i < v->n && !0; i++){
                int dup = 0;
                for(size_t j = i + 1; j < v->n; j++)
                    if(deq(v->items[i], v->items[j])){ dup = 1; break; }
                if(dup){ adderr(ip, child(sp, "uniqueItems")); break; }
            }
        }
        Value *pi = get(s, "prefixItems");
        if(pi && pi->type == 4){
            size_t k = pi->n < v->n ? pi->n : v->n;
            char *spp = child(sp, "prefixItems");
            for(size_t i = 0; i < k; i++)
                validate(pi->items[i], childi(spp, i), v->items[i], childi(ip, i));
        }
        Value *it = get(s, "items");
        if(it){
            size_t start = (pi && pi->type == 4) ? pi->n : 0;
            char *spi = child(sp, "items");
            for(size_t i = start; i < v->n; i++)
                validate(it, spi, v->items[i], childi(ip, i));
        }
    }
    if(v->type == 5){
        if((m = get(s, "minProperties")) && !((double)v->m >= m->num)) adderr(ip, child(sp, "minProperties"));
        if((m = get(s, "maxProperties")) && !((double)v->m <= m->num)) adderr(ip, child(sp, "maxProperties"));
        Value *req = get(s, "required");
        if(req && req->type == 4){
            char *spr = child(sp, "required");
            for(size_t j = 0; j < req->n; j++){
                char *name = req->items[j]->str;
                if(!get(v, name)) adderr(ip, childi(spr, j));
            }
        }
        Value *props = get(s, "properties");
        if(props && props->type == 5){
            char *spp = child(sp, "properties");
            for(size_t i = 0; i < v->m; i++){
                Value *sub = get(props, v->mem[i].name);
                if(sub) validate(sub, child(spp, v->mem[i].name),
                                 v->mem[i].val, child(ip, v->mem[i].name));
            }
        }
        Value *ap = get(s, "additionalProperties");
        if(ap){
            char *spa = child(sp, "additionalProperties");
            for(size_t i = 0; i < v->m; i++){
                if(!props || !get(props, v->mem[i].name))
                    validate(ap, spa, v->mem[i].val, child(ip, v->mem[i].name));
            }
        }
    }

    if((m = get(s, "allOf")) && m->type == 4){
        char *spa = child(sp, "allOf");
        for(size_t i = 0; i < m->n; i++)
            validate(m->items[i], childi(spa, i), v, ip);
    }
    if((m = get(s, "anyOf")) && m->type == 4){
        int ok = 0;
        for(size_t i = 0; i < m->n; i++)
            if(accepts(m->items[i], childi(child(sp, "anyOf"), i), v, ip)){ ok = 1; break; }
        if(!ok) adderr(ip, child(sp, "anyOf"));
    }
    if((m = get(s, "oneOf")) && m->type == 4){
        int cnt = 0;
        for(size_t i = 0; i < m->n; i++)
            if(accepts(m->items[i], childi(child(sp, "oneOf"), i), v, ip)) cnt++;
        if(cnt != 1) adderr(ip, child(sp, "oneOf"));
    }
    if((m = get(s, "not")) && accepts(m, child(sp, "not"), v, ip))
        adderr(ip, child(sp, "not"));
    if((m = get(s, "if"))){
        int a = accepts(m, child(sp, "if"), v, ip);
        if(a){
            Value *t = get(s, "then");
            if(t) validate(t, child(sp, "then"), v, ip);
        } else {
            Value *e = get(s, "else");
            if(e) validate(e, child(sp, "else"), v, ip);
        }
    }
    if((m = get(s, "$ref")) && m->type == 3){
        const char *r = m->str;
        if(!strcmp(r, "#")){
            validate(root, "#", v, ip);
        } else if(!strncmp(r, "#/$defs/", 8)){
            char *name = unescape_tok(r + 8);
            Value *defs = get(root, "$defs");
            Value *sub = defs ? get(defs, name) : NULL;
            if(sub) validate(sub, child("#/$defs", name), v, ip);
        }
    }
}

/* ---------- misc ---------- */
static char *readfile(const char *path){
    FILE *f = fopen(path, "rb");
    if(!f){ perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if(fread(b, 1, (size_t)n, f) != (size_t)n) die("read error");
    b[n] = 0;
    fclose(f);
    return b;
}
static char *joinpath(const char *dir, const char *name){
    char *r = malloc(strlen(dir) + strlen(name) + 2);
    sprintf(r, "%s/%s", dir, name);
    return r;
}
static int errcmp(const void *a, const void *b){
    const Err *x = a, *y = b;
    int c = strcmp(x->inst, y->inst);
    if(c) return c;
    return strcmp(x->sch, y->sch);
}

int main(int argc, char **argv){
    if(argc < 2) return 1;
    src = readfile(joinpath(argv[1], "schema.json"));
    slen = strlen(src); pos = 0;
    root = parse_value();

    src = readfile(joinpath(argv[1], "instances.json"));
    slen = strlen(src); pos = 0;
    Value *insts = parse_value();
    if(insts->type != 4) die("instances not array");

    ErrList main = {0};
    size_t nvalid = 0, ninvalid = 0;
    for(size_t i = 0; i < insts->n; i++){
        main.n = 0;
        cur = &main;
        validate(root, "#", insts->items[i], "#");
        qsort(main.e, main.n, sizeof(Err), errcmp);
        if(main.n == 0){
            printf("%zu: valid\n", i);
            nvalid++;
        } else {
            printf("%zu: invalid (%zu)\n", i, main.n);
            for(size_t j = 0; j < main.n; j++)
                printf("  %s %s\n", main.e[j].inst, main.e[j].sch);
            ninvalid++;
        }
    }
    printf("valid=%zu invalid=%zu\n", nvalid, ninvalid);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct Value Value;
typedef struct { char *name; Value *val; } Member;

struct Value {
    int type; /* 0 null,1 bool,2 num,3 str,4 arr,5 obj */
    int b;
    double num;
    char *str; size_t slen;
    Value **items; size_t n;
    Member *mem; size_t m;
};

static Value *root;

static void die(const char *m){ fprintf(stderr, "%s\n", m); exit(1); }

static Value *newval(int t){ Value *v = calloc(1, sizeof(Value)); v->type = t; return v; }

/* ---------- dynamic char buffer ---------- */
typedef struct { char *d; size_t n, cap; } Buf;
static void bpush(Buf *b, char c){
    if(b->n + 1 >= b->cap){ b->cap = b->cap ? b->cap * 2 : 16; b->d = realloc(b->d, b->cap); }
    b->d[b->n++] = c;
}
static void utf8_enc(Buf *b, unsigned cp){
    if(cp < 0x80) bpush(b, (char)cp);
    else if(cp < 0x800){ bpush(b, (char)(0xC0|(cp>>6))); bpush(b, (char)(0x80|(cp&0x3F))); }
    else if(cp < 0x10000){ bpush(b,(char)(0xE0|(cp>>12))); bpush(b,(char)(0x80|((cp>>6)&0x3F))); bpush(b,(char)(0x80|(cp&0x3F))); }
    else { bpush(b,(char)(0xF0|(cp>>18))); bpush(b,(char)(0x80|((cp>>12)&0x3F))); bpush(b,(char)(0x80|((cp>>6)&0x3F))); bpush(b,(char)(0x80|(cp&0x3F))); }
}

/* ---------- parser ---------- */
static char *src; static size_t pos, slen;

static void skipws(void){
    while(pos < slen){ char c = src[pos];
        if(c==' '||c=='\t'||c=='\n'||c=='\r') pos++; else break; }
}
static unsigned hex4(void){
    unsigned v = 0;
    for(int i = 0; i < 4; i++){
        char c = src[pos++];
        v *= 16;
        if(c <= '9') v += (unsigned)(c - '0');
        else if(c <= 'F') v += (unsigned)(c - 'A' + 10);
        else v += (unsigned)(c - 'a' + 10);
    }
    return v;
}
static char *parse_string_raw(size_t *outlen){
    pos++; /* opening quote */
    Buf b = {0};
    while(pos < slen && src[pos] != '"'){
        unsigned char c = (unsigned char)src[pos];
        if(c == '\\'){
            pos++;
            char e = src[pos++];
            switch(e){
                case '"': bpush(&b,'"'); break;
                case '\\': bpush(&b,'\\'); break;
                case '/': bpush(&b,'/'); break;
                case 'b': bpush(&b,'\b'); break;
                case 'f': bpush(&b,'\f'); break;
                case 'n': bpush(&b,'\n'); break;
                case 'r': bpush(&b,'\r'); break;
                case 't': bpush(&b,'\t'); break;
                case 'u': {
                    unsigned cp = hex4();
                    if(cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < slen &&
                       src[pos] == '\\' && src[pos+1] == 'u'){
                        size_t save = pos; pos += 2;
                        unsigned lo = hex4();
                        if(lo >= 0xDC00 && lo <= 0xDFFF)
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        else pos = save;
                    }
                    utf8_enc(&b, cp);
                    break;
                }
                default: die("bad escape");
            }
        } else { bpush(&b, (char)c); pos++; }
    }
    if(pos >= slen) die("unterminated string");
    pos++; /* closing quote */
    bpush(&b, '\0');
    if(outlen) *outlen = b.n - 1;
    return b.d;
}
static Value *parse_value(void){
    skipws();
    if(pos >= slen) die("eof");
    char c = src[pos];
    if(c == '{'){
        pos++; Value *v = newval(5);
        skipws();
        if(src[pos] == '}'){ pos++; return v; }
        for(;;){
            skipws();
            if(src[pos] != '"') die("bad key");
            char *k = parse_string_raw(NULL);
            skipws();
            if(src[pos] != ':') die("expected :");
            pos++;
            Value *val = parse_value();
            v->mem = realloc(v->mem, (v->m + 1) * sizeof(Member));
            v->mem[v->m].name = k; v->mem[v->m].val = val; v->m++;
            skipws();
            if(src[pos] == ','){ pos++; continue; }
            if(src[pos] == '}'){ pos++; break; }
            die("bad object");
        }
        return v;
    }
    if(c == '['){
        pos++; Value *v = newval(4);
        skipws();
        if(src[pos] == ']'){ pos++; return v; }
        for(;;){
            Value *val = parse_value();
            v->items = realloc(v->items, (v->n + 1) * sizeof(Value *));
            v->items[v->n++] = val;
            skipws();
            if(src[pos] == ','){ pos++; continue; }
            if(src[pos] == ']'){ pos++; break; }
            die("bad array");
        }
        return v;
    }
    if(c == '"'){
        size_t l; char *s = parse_string_raw(&l);
        Value *v = newval(3); v->str = s; v->slen = l; return v;
    }
    if(!strncmp(src + pos, "true", 4)){ pos += 4; Value *v = newval(1); v->b = 1; return v; }
    if(!strncmp(src + pos, "false", 5)){ pos += 5; Value *v = newval(1); v->b = 0; return v; }
    if(!strncmp(src + pos, "null", 4)){ pos += 4; return newval(0); }
    /* number */
    size_t st = pos;
    if(src[pos] == '-') pos++;
    while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++;
    if(pos < slen && src[pos] == '.'){ pos++; while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++; }
    if(pos < slen && (src[pos] == 'e' || src[pos] == 'E')){
        pos++;
        if(pos < slen && (src[pos] == '+' || src[pos] == '-')) pos++;
        while(pos < slen && src[pos] >= '0' && src[pos] <= '9') pos++;
    }
    size_t l = pos - st;
    char *tmp = malloc(l + 1);
    memcpy(tmp, src + st, l); tmp[l] = 0;
    Value *v = newval(2);
    v->num = strtod(tmp, NULL);
    free(tmp);
    return v;
}

/* ---------- helpers ---------- */
static Value *get(Value *o, const char *name){
    if(!o || o->type != 5) return NULL;
    for(size_t i = 0; i < o->m; i++)
        if(!strcmp(o->mem[i].name, name)) return o->mem[i].val;
    return NULL;
}
static size_t cpcount(const char *s){
    size_t c = 0;
    while(*s){ if((((unsigned char)*s) & 0xC0) != 0x80) c++; s++; }
    return c;
}
static int deq(Value *a, Value *b){
    if(a->type != b->type) return 0;
    switch(a->type){
        case 0: return 1;
        case 1: return a->b == b->b;
        case 2: return a->num == b->num;
        case 3: return a->slen == b->slen && memcmp(a->str, b->str, a->slen) == 0;
        case 4:
            if(a->n != b->n) return 0;
            for(size_t i = 0; i < a->n; i++) if(!deq(a->items[i], b->items[i])) return 0;
            return 1;
        case 5:
            if(a->m != b->m) return 0;
            for(size_t i = 0; i < a->m; i++){
                Value *bv = get(b, a->mem[i].name);
                if(!bv || !deq(a->mem[i].val, bv)) return 0;
            }
            return 1;
    }
    return 0;
}
static int matchtype(const char *t, Value *v){
    if(!strcmp(t, "null")) return v->type == 0;
    if(!strcmp(t, "boolean")) return v->type == 1;
    if(!strcmp(t, "object")) return v->type == 5;
    if(!strcmp(t, "array")) return v->type == 4;
    if(!strcmp(t, "string")) return v->type == 3;
    if(!strcmp(t, "number")) return v->type == 2;
    if(!strcmp(t, "integer")) return v->type == 2 && v->num == floor(v->num);
    return 0;
}

/* ---------- pointer paths ---------- */
static char *esc_tok(const char *t){
    size_t l = strlen(t);
    char *r = malloc(2 * l + 1);
    size_t j = 0;
    for(size_t i = 0; i < l; i++){
        if(t[i] == '~'){ r[j++] = '~'; r[j++] = '0'; }
        else if(t[i] == '/'){ r[j++] = '~'; r[j++] = '1'; }
        else r[j++] = t[i];
    }
    r[j] = 0;
    return r;
}
static char *child(const char *p, const char *rawtok){
    char *e = esc_tok(rawtok);
    char *r = malloc(strlen(p) + strlen(e) + 2);
    sprintf(r, "%s/%s", p, e);
    free(e);
    return r;
}
static char *childi(const char *p, size_t i){
    char b[32];
    sprintf(b, "%zu", i);
    return child(p, b);
}
static char *unescape_tok(const char *t){
    size_t l = strlen(t);
    char *r = malloc(l + 1);
    size_t j = 0;
    for(size_t i = 0; i < l; i++){
        if(t[i] == '~' && i + 1 < l){
            if(t[i+1] == '0'){ r[j++] = '~'; i++; }
            else if(t[i+1] == '1'){ r[j++] = '/'; i++; }
            else r[j++] = t[i];
        } else r[j++] = t[i];
    }
    r[j] = 0;
    return r;
}

/* ---------- errors ---------- */
typedef struct { char *inst, *sch; } Err;
typedef struct { Err *e; size_t n, cap; } ErrList;
static ErrList *cur;

static void validate(Value *s, const char *sp, Value *v, const char *ip);

static void adderr(const char *ip, const char *sp){
    for(size_t i = 0; i < cur->n; i++)
        if(!strcmp(cur->e[i].inst, ip) && !strcmp(cur->e[i].sch, sp)) return;
    if(cur->n + 1 > cur->cap){
        cur->cap = cur->cap ? cur->cap * 2 : 16;
        cur->e = realloc(cur->e, cur->cap * sizeof(Err));
    }
    cur->e[cur->n].inst = strdup(ip);
    cur->e[cur->n].sch = strdup(sp);
    cur->n++;
}
static int accepts(Value *s, const char *sp, Value *v, const char *ip){
    ErrList tmp = {0};
    ErrList *old = cur;
    cur = &tmp;
    validate(s, sp, v, ip);
    cur = old;
    int ok = (tmp.n == 0);
    free(tmp.e);
    return ok;
}

/* ---------- validation ---------- */
static void validate(Value *s, const char *sp, Value *v, const char *ip){
    if(s->type == 1){
        if(!s->b) adderr(ip, sp);
        return;
    }
    if(s->type != 5) return;

    Value *m;
    if((m = get(s, "type"))){
        int ok = 0;
        if(m->type == 3) ok = matchtype(m->str, v);
        else if(m->type == 4){
            for(size_t i = 0; i < m->n; i++)
                if(m->items[i]->type == 3 && matchtype(m->items[i]->str, v)){ ok = 1; break; }
        }
        if(!ok) adderr(ip, child(sp, "type"));
    }
    if((m = get(s, "enum")) && m->type == 4){
        int ok = 0;
        for(size_t i = 0; i < m->n; i++) if(deq(v, m->items[i])){ ok = 1; break; }
        if(!ok) adderr(ip, child(sp, "enum"));
    }
    if((m = get(s, "const")) && !deq(v, m))
        adderr(ip, child(sp, "const"));

    if(v->type == 2){
        if((m = get(s, "minimum")) && !(v->num >= m->num)) adderr(ip, child(sp, "minimum"));
        if((m = get(s, "maximum")) && !(v->num <= m->num)) adderr(ip, child(sp, "maximum"));
        if((m = get(s, "exclusiveMinimum")) && !(v->num > m->num)) adderr(ip, child(sp, "exclusiveMinimum"));
        if((m = get(s, "exclusiveMaximum")) && !(v->num < m->num)) adderr(ip, child(sp, "exclusiveMaximum"));
    }
    if(v->type == 3){
        size_t cp = cpcount(v->str);
        if((m = get(s, "minLength")) && !((double)cp >= m->num)) adderr(ip, child(sp, "minLength"));
        if((m = get(s, "maxLength")) && !((double)cp <= m->num)) adderr(ip, child(sp, "maxLength"));
    }
    if(v->type == 4){
        if((m = get(s, "minItems")) && !((double)v->n >= m->num)) adderr(ip, child(sp, "minItems"));
        if((m = get(s, "maxItems")) && !((double)v->n <= m->num)) adderr(ip, child(sp, "maxItems"));
        if((m = get(s, "uniqueItems")) && m->type == 1 && m->b){
            for(size_t i = 0; i < v->n; i++){
                int dup = 0;
                for(size_t j = i + 1; j < v->n; j++)
                    if(deq(v->items[i], v->items[j])){ dup = 1; break; }
                if(dup){ adderr(ip, child(sp, "uniqueItems")); break; }
            }
        }
        Value *pi = get(s, "prefixItems");
        if(pi && pi->type == 4){
            size_t k = pi->n < v->n ? pi->n : v->n;
            char *spp = child(sp, "prefixItems");
            for(size_t i = 0; i < k; i++)
                validate(pi->items[i], childi(spp, i), v->items[i], childi(ip, i));
        }
        Value *it = get(s, "items");
        if(it){
            size_t start = (pi && pi->type == 4) ? pi->n : 0;
            char *spi = child(sp, "items");
            for(size_t i = start; i < v->n; i++)
                validate(it, spi, v->items[i], childi(ip, i));
        }
    }
    if(v->type == 5){
        if((m = get(s, "minProperties")) && !((double)v->m >= m->num)) adderr(ip, child(sp, "minProperties"));
        if((m = get(s, "maxProperties")) && !((double)v->m <= m->num)) adderr(ip, child(sp, "maxProperties"));
        Value *req = get(s, "required");
        if(req && req->type == 4){
            char *spr = child(sp, "required");
            for(size_t j = 0; j < req->n; j++){
                char *name = req->items[j]->str;
                if(!get(v, name)) adderr(ip, childi(spr, j));
            }
        }
        Value *props = get(s, "properties");
        if(props && props->type == 5){
            char *spp = child(sp, "properties");
            for(size_t i = 0; i < v->m; i++){
                Value *sub = get(props, v->mem[i].name);
                if(sub) validate(sub, child(spp, v->mem[i].name),
                                 v->mem[i].val, child(ip, v->mem[i].name));
            }
        }
        Value *ap = get(s, "additionalProperties");
        if(ap){
            char *spa = child(sp, "additionalProperties");
            for(size_t i = 0; i < v->m; i++){
                if(!props || !get(props, v->mem[i].name))
                    validate(ap, spa, v->mem[i].val, child(ip, v->mem[i].name));
            }
        }
    }

    if((m = get(s, "allOf")) && m->type == 4){
        char *spa = child(sp, "allOf");
        for(size_t i = 0; i < m->n; i++)
            validate(m->items[i], childi(spa, i), v, ip);
    }
    if((m = get(s, "anyOf")) && m->type == 4){
        int ok = 0;
        for(size_t i = 0; i < m->n; i++)
            if(accepts(m->items[i], childi(child(sp, "anyOf"), i), v, ip)){ ok = 1; break; }
        if(!ok) adderr(ip, child(sp, "anyOf"));
    }
    if((m = get(s, "oneOf")) && m->type == 4){
        int cnt = 0;
        for(size_t i = 0; i < m->n; i++)
            if(accepts(m->items[i], childi(child(sp, "oneOf"), i), v, ip)) cnt++;
        if(cnt != 1) adderr(ip, child(sp, "oneOf"));
    }
    if((m = get(s, "not")) && accepts(m, child(sp, "not"), v, ip))
        adderr(ip, child(sp, "not"));
    if((m = get(s, "if"))){
        int a = accepts(m, child(sp, "if"), v, ip);
        if(a){
            Value *t = get(s, "then");
            if(t) validate(t, child(sp, "then"), v, ip);
        } else {
            Value *e = get(s, "else");
            if(e) validate(e, child(sp, "else"), v, ip);
        }
    }
    if((m = get(s, "$ref")) && m->type == 3){
        const char *r = m->str;
        if(!strcmp(r, "#")){
            validate(root, "#", v, ip);
        } else if(!strncmp(r, "#/$defs/", 8)){
            char *name = unescape_tok(r + 8);
            Value *defs = get(root, "$defs");
            Value *sub = defs ? get(defs, name) : NULL;
            if(sub) validate(sub, child("#/$defs", name), v, ip);
        }
    }
}

/* ---------- misc ---------- */
static char *readfile(const char *path){
    FILE *f = fopen(path, "rb");
    if(!f){ perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if(fread(b, 1, (size_t)n, f) != (size_t)n) die("read error");
    b[n] = 0;
    fclose(f);
    return b;
}
static char *joinpath(const char *dir, const char *name){
    char *r = malloc(strlen(dir) + strlen(name) + 2);
    sprintf(r, "%s/%s", dir, name);
    return r;
}
static int errcmp(const void *a, const void *b){
    const Err *x = a, *y = b;
    int c = strcmp(x->inst, y->inst);
    if(c) return c;
    return strcmp(x->sch, y->sch);
}

int main(int argc, char **argv){
    if(argc < 2) return 1;
    src = readfile(joinpath(argv[1], "schema.json"));
    slen = strlen(src); pos = 0;
    root = parse_value();

    src = readfile(joinpath(argv[1], "instances.json"));
    slen = strlen(src); pos = 0;
    Value *insts = parse_value();
    if(insts->type != 4) die("instances not array");

    ErrList errs = {0};
    size_t nvalid = 0, ninvalid = 0;
    for(size_t i = 0; i < insts->n; i++){
        errs.n = 0;
        cur = &errs;
        validate(root, "#", insts->items[i], "#");
        qsort(errs.e, errs.n, sizeof(Err), errcmp);
        if(errs.n == 0){
            printf("%zu: valid\n", i);
            nvalid++;
        } else {
            printf("%zu: invalid (%zu)\n", i, errs.n);
            for(size_t j = 0; j < errs.n; j++)
                printf("  %s %s\n", errs.e[j].inst, errs.e[j].sch);
            ninvalid++;
        }
    }
    printf("valid=%zu invalid=%zu\n", nvalid, ninvalid);
    return 0;
}

import sys, json

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def valid_id(x):
    return isinstance(x, str) or is_int(x)

def parse(line):
    try:
        return json.loads(line, parse_constant=lambda c: (_ for _ in ()).throw(ValueError()))
    except Exception:
        return None

TOOLS = [
 {"name":"kv_set","title":"Set a value","description":"Store a string value under a key, replacing any previous value.",
  "inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1},"value":{"type":"string"}},"required":["key","value"],"additionalProperties":False}},
 {"name":"kv_get","title":"Get a value","description":"Return the value stored under a key.",
  "inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1}},"required":["key"],"additionalProperties":False}},
 {"name":"kv_list","title":"List keys","description":"List the stored keys that start with a prefix, sorted by Unicode code point.",
  "inputSchema":{"type":"object","properties":{"prefix":{"type":"string"}},"additionalProperties":False},
  "outputSchema":{"type":"object","properties":{"keys":{"type":"array","items":{"type":"string"}},"count":{"type":"integer"}},"required":["keys","count"]}},
 {"name":"sum","title":"Sum integers","description":"Add up a non-empty list of integers.",
  "inputSchema":{"type":"object","properties":{"numbers":{"type":"array","items":{"type":"integer"},"minItems":1}},"required":["numbers"],"additionalProperties":False},
  "outputSchema":{"type":"object","properties":{"sum":{"type":"integer"},"count":{"type":"integer"}},"required":["sum","count"]},
  "annotations":{"readOnlyHint":True,"idempotentHint":True}},
 {"name":"text_stats","title":"Text statistics","description":"Count the words, Unicode code points and UTF-8 bytes of a text.",
  "inputSchema":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"],"additionalProperties":False},
  "outputSchema":{"type":"object","properties":{"words":{"type":"integer"},"codepoints":{"type":"integer"},"utf8_bytes":{"type":"integer"}},"required":["words","codepoints","utf8_bytes"]},
  "annotations":{"readOnlyHint":True}},
]

def out(obj):
    sys.stdout.write(json.dumps(obj, ensure_ascii=False) + "\n")

def fail(id, code, msg):
    out({"jsonrpc":"2.0","id":id,"error":{"code":code,"message":msg}})

def main():
    initialized = False
    kv = {}
    for line in sys.stdin:
        line = line.rstrip("\n").rstrip("\r")
        if line.strip(" \t\r") == "":
            continue
        msg = parse(line)
        if msg is None:
            out({"jsonrpc":"2.0","id":None,"error":{"code":-32700,"message":"Parse error"}})
            continue
        if not isinstance(msg, dict):
            out({"jsonrpc":"2.0","id":None,"error":{"code":-32600,"message":"Invalid Request"}})
            continue
        if "method" not in msg and ("result" in msg or "error" in msg):
            continue
        if msg.get("jsonrpc") != "2.0" or not isinstance(msg.get("method"), str) or ("id" in msg and not valid_id(msg["id"])):
            rid = msg["id"] if valid_id(msg.get("id")) else None
            fail(rid, -32600, "Invalid Request")
            continue
        if "id" not in msg:
            continue  # notification
        rid = msg["id"]
        method = msg["method"]
        if method not in ("initialize","ping","tools/list","tools/call"):
            fail(rid, -32601, "Method not found")
            continue
        params = msg.get("params")
        if "params" in msg and not isinstance(params, dict):
            fail(rid, -32602, "Invalid params")
            continue
        if not initialized and method not in ("initialize","ping"):
            fail(rid, -32002, "Server not initialized")
            continue
        if method == "ping":
            out({"jsonrpc":"2.0","id":rid,"result":{}})
            continue
        if method == "initialize":
            if initialized:
                fail(rid, -32600, "Already initialized")
                continue
            pv = params.get("protocolVersion") if isinstance(params, dict) else None
            if not isinstance(params, dict) or not isinstance(pv, str):
                fail(rid, -32602, "Invalid params")
                continue
            initialized = True
            version = pv if pv in ("2025-06-18","2025-03-26","2024-11-05") else "2025-06-18"
            out({"jsonrpc":"2.0","id":rid,"result":{"protocolVersion":version,
                "capabilities":{"tools":{"listChanged":False}},
                "serverInfo":{"name":"cb2-kv","title":"CB2 key-value server","version":"1.4.2"}}})
            continue
        if method == "tools/list":
            out({"jsonrpc":"2.0","id":rid,"result":{"tools":TOOLS}})
            continue
        # tools/call
        name = params.get("name")
        if not isinstance(name, str):
            fail(rid, -32602, "Invalid params")
            continue
        tool = next((t for t in TOOLS if t["name"] == name), None)
        if tool is None:
            fail(rid, -32602, "Unknown tool: " + name)
            continue
        args = params.get("arguments", {})
        def tool_fail(text):
            out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":text}],"isError":True}})
        if not isinstance(args, dict):
            tool_fail("arguments must be an object")
            continue
        props = tool["inputSchema"]["properties"]
        unknown = sorted(set(args) - set(props))
        if unknown:
            tool_fail("unknown argument: " + unknown[0])
            continue
        ok = True
        for pname, pschema in props.items():
            if pname not in args:
                if pname in tool["inputSchema"].get("required", []):
                    tool_fail("missing required argument: " + pname)
                    ok = False
                    break
                continue
            v = args[pname]
            t = pschema["type"]
            if t == "string":
                if not isinstance(v, str):
                    tool_fail("argument " + pname + " must be a string"); ok = False; break
                if pschema.get("minLength") == 1 and len(v) == 0:
                    tool_fail("argument " + pname + " must not be empty"); ok = False; break
            elif t == "array":
                if not isinstance(v, list) or not all(is_int(x) for x in v):
                    tool_fail("argument " + pname + " must be an array of integers"); ok = False; break
                if pschema.get("minItems") == 1 and len(v) == 0:
                    tool_fail("argument " + pname + " must not be empty"); ok = False; break
        if not ok:
            continue
        if name == "kv_set":
            existed = args["key"] in kv
            kv[args["key"]] = args["value"]
            out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":("updated " if existed else "created ") + args["key"]}],"isError":False}})
        elif name == "kv_get":
            k = args["key"]
            if k not in kv:
                tool_fail("key not found: " + k)
            else:
                out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":kv[k]}],"isError":False}})
        elif name == "kv_list":
            prefix = args.get("prefix", "")
            keys = sorted((k for k in kv if k.startswith(prefix)))
            S = {"keys": keys, "count": len(keys)}
            out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":json.dumps(S, ensure_ascii=False)}],"structuredContent":S,"isError":False}})
        elif name == "sum":
            S = {"sum": sum(args["numbers"]), "count": len(args["numbers"])}
            out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":json.dumps(S)}],"structuredContent":S,"isError":False}})
        elif name == "text_stats":
            text = args["text"]
            words = 0
            in_word = False
            for ch in text:
                if ch in " \t\n\r":
                    in_word = False
                else:
                    if not in_word:
                        words += 1
                    in_word = True
            S = {"words": words, "codepoints": len(text), "utf8_bytes": len(text.encode("utf-8"))}
            out({"jsonrpc":"2.0","id":rid,"result":{"content":[{"type":"text","text":json.dumps(S)}],"structuredContent":S,"isError":False}})

main()
sys.exit(0)

use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone, Debug)]
enum Value { Null, Bool(bool), Num(f64), Str(String), Arr(Vec<Value>), Obj(Vec<(String, Value)>) }

struct P<'a> { b: &'a [u8], i: usize }

impl<'a> P<'a> {
    fn ws(&mut self) { while self.i < self.b.len() && matches!(self.b[self.i], b' '|b'\t'|b'\n'|b'\r') { self.i += 1; } }
    fn value(&mut self) -> Result<Value, String> {
        self.ws();
        match self.b.get(self.i) {
            None => Err("eof".into()),
            Some(b'n') => { self.i += 1; Ok(Value::Null) }
            Some(b't') => { self.i += 4; Ok(Value::Bool(true)) }
            Some(b'f') => { self.i += 5; Ok(Value::Bool(false)) }
            Some(b'"') => self.string(),
            Some(b'[') => self.array(),
            Some(b'{') => self.object(),
            Some(_) => self.number(),
        }
    }
    fn string(&mut self) -> Result<Value, String> {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.b[self.i]; self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.b[self.i]; self.i += 1;
                    match e {
                        b'"' => out.push(b'"'), b'\\' => out.push(b'\\'), b'/' => out.push(b'/'),
                        b'b' => out.push(8), b'f' => out.push(12), b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'), b't' => out.push(b'\t'),
                        b'u' => {
                            let mut c = self.hex4();
                            if (0xD800..0xDC00).contains(&c) && self.b[self.i] == b'\\' && self.b[self.i+1] == b'u' {
                                self.i += 2;
                                let lo = self.hex4();
                                c = 0x10000 + ((c - 0xD800) << 10) + (lo - 0xDC00);
                            }
                            let ch = char::from_u32(c).unwrap_or('\u{FFFD}');
                            let mut buf = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return Err("bad escape".into()),
                    }
                }
                _ => out.push(c),
            }
        }
        Ok(Value::Str(String::from_utf8(out).unwrap()))
    }
    fn hex4(&mut self) -> u32 {
        let s = std::str::from_utf8(&self.b[self.i..self.i+4]).unwrap();
        self.i += 4;
        u32::from_str_radix(s, 16).unwrap()
    }
    fn array(&mut self) -> Result<Value, String> {
        self.i += 1; let mut v = Vec::new(); self.ws();
        if self.b[self.i] == b']' { self.i += 1; return Ok(Value::Arr(v)); }
        loop {
            v.push(self.value()?);
            self.ws();
            match self.b[self.i] { b',' => { self.i += 1; } b']' => { self.i += 1; break; } _ => return Err("arr".into()) }
        }
        Ok(Value::Arr(v))
    }
    fn object(&mut self) -> Result<Value, String> {
        self.i += 1; let mut v = Vec::new(); self.ws();
        if self.b[self.i] == b'}' { self.i += 1; return Ok(Value::Obj(v)); }
        loop {
            self.ws();
            let k = match self.string()? { Value::Str(s) => s, _ => return Err("key".into()) };
            self.ws();
            if self.b[self.i] != b':' { return Err("colon".into()); }
            self.i += 1;
            v.push((k, self.value()?));
            self.ws();
            match self.b[self.i] { b',' => { self.i += 1; } b'}' => { self.i += 1; break; } _ => return Err("obj".into()) }
        }
        Ok(Value::Obj(v))
    }
    fn number(&mut self) -> Result<Value, String> {
        let start = self.i;
        if self.b[self.i] == b'-' { self.i += 1; }
        while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        if self.i < self.b.len() && self.b[self.i] == b'.' {
            self.i += 1;
            while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        }
        if self.i < self.b.len() && (self.b[self.i] == b'e' || self.b[self.i] == b'E') {
            self.i += 1;
            if self.i < self.b.len() && (self.b[self.i] == b'+' || self.b[self.i] == b'-') { self.i += 1; }
            while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        }
        let s = std::str::from_utf8(&self.b[start..self.i]).unwrap();
        Ok(Value::Num(s.parse::<f64>().unwrap()))
    }
}

fn parse(s: &str) -> Result<Value, String> {
    let mut p = P { b: s.as_bytes(), i: 0 };
    let v = p.value()?;
    p.ws();
    if p.i != p.b.len() { return Err("trailing".into()); }
    Ok(v)
}

fn deq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Arr(x), Value::Arr(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| deq(p, q)),
        (Value::Obj(x), Value::Obj(y)) => x.len() == y.len()
            && x.iter().all(|(k, v)| y.iter().find(|(k2, _)| k2 == k).map_or(false, |(_, v2)| deq(v, v2))),
        _ => false,
    }
}

fn ptr(t: &[String]) -> String {
    let mut s = String::from("#");
    for tok in t {
        s.push('/');
        for c in tok.chars() {
            match c { '~' => s.push_str("~0"), '/' => s.push_str("~1"), _ => s.push(c) }
        }
    }
    s
}

fn child(t: &[String], tok: &str) -> Vec<String> { let mut v = t.to_vec(); v.push(tok.to_string()); v }

fn decode_token(s: &str) -> String {
    let mut r = String::new();
    let mut it = s.chars();
    while let Some(c) = it.next() {
        if c == '~' {
            match it.next() { Some('0') => r.push('~'), Some('1') => r.push('/'), o => { r.push('~'); if let Some(c2) = o { r.push(c2); } } }
        } else { r.push(c); }
    }
    r
}

fn type_match(v: &Value, n: &str) -> bool {
    match n {
        "null" => matches!(v, Value::Null),
        "boolean" => matches!(v, Value::Bool(_)),
        "string" => matches!(v, Value::Str(_)),
        "array" => matches!(v, Value::Arr(_)),
        "object" => matches!(v, Value::Obj(_)),
        "number" => matches!(v, Value::Num(_)),
        "integer" => matches!(v, Value::Num(x) if x.fract() == 0.0),
        _ => false,
    }
}

fn accepts(root: &Value, inst: &Value, sch: &Value) -> bool {
    let mut e = Vec::new();
    validate(root, inst, &[], sch, &[], &mut e);
    e.is_empty()
}

fn validate(root: &Value, inst: &Value, iloc: &[String], sch: &Value, sloc: &[String], errs: &mut Vec<(String, String)>) {
    match sch {
        Value::Bool(true) => {}
        Value::Bool(false) => errs.push((ptr(iloc), ptr(sloc))),
        Value::Obj(m) => {
            let get = |k: &str| m.iter().find(|(kk, _)| kk == k).map(|(_, v)| v);

            if let Some(tv) = get("type") {
                let names: Vec<&str> = match tv {
                    Value::Str(s) => vec![s.as_str()],
                    Value::Arr(a) => a.iter().filter_map(|v| if let Value::Str(s) = v { Some(s.as_str()) } else { None }).collect(),
                    _ => vec![],
                };
                if !names.is_empty() && !names.iter().any(|n| type_match(inst, n)) {
                    errs.push((ptr(iloc), ptr(&child(sloc, "type"))));
                }
            }
            if let Some(Value::Arr(es)) = get("enum") {
                if !es.iter().any(|e| deq(e, inst)) { errs.push((ptr(iloc), ptr(&child(sloc, "enum")))); }
            }
            if let Some(cv) = get("const") {
                if !deq(cv, inst) { errs.push((ptr(iloc), ptr(&child(sloc, "const")))); }
            }
            if let Value::Num(x) = inst {
                let checks: [(&str, fn(f64, f64) -> bool); 4] = [
                    ("minimum", |x, k| x >= k), ("maximum", |x, k| x <= k),
                    ("exclusiveMinimum", |x, k| x > k), ("exclusiveMaximum", |x, k| x < k),
                ];
                for (kw, ok) in checks {
                    if let Some(Value::Num(k)) = get(kw) {
                        if !ok(*x, *k) { errs.push((ptr(iloc), ptr(&child(sloc, kw)))); }
                    }
                }
            }
            if let Value::Str(s) = inst {
                if let Some(Value::Num(n)) = get("minLength") {
                    if !((s.chars().count() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minLength")))); }
                }
                if let Some(Value::Num(n)) = get("maxLength") {
                    if !((s.chars().count() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxLength")))); }
                }
            }
            if let Value::Arr(a) = inst {
                if let Some(Value::Num(n)) = get("minItems") {
                    if !((a.len() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minItems")))); }
                }
                if let Some(Value::Num(n)) = get("maxItems") {
                    if !((a.len() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxItems")))); }
                }
                if let Some(Value::Bool(true)) = get("uniqueItems") {
                    'outer: for i in 0..a.len() {
                        for j in i + 1..a.len() {
                            if deq(&a[i], &a[j]) {
                                errs.push((ptr(iloc), ptr(&child(sloc, "uniqueItems"))));
                                break 'outer;
                            }
                        }
                    }
                }
                if let Some(Value::Arr(pi)) = get("prefixItems") {
                    for i in 0..a.len().min(pi.len()) {
                        validate(root, &a[i], &child(iloc, &i.to_string()), &pi[i],
                                 &child(&child(sloc, "prefixItems"), &i.to_string()), errs);
                    }
                }
                if let Some(it) = get("items") {
                    let start = match get("prefixItems") { Some(Value::Arr(pi)) => pi.len(), _ => 0 };
                    for i in start..a.len() {
                        validate(root, &a[i], &child(iloc, &i.to_string()), it, &child(sloc, "items"), errs);
                    }
                }
            }
            if let Value::Obj(o) = inst {
                if let Some(Value::Num(n)) = get("minProperties") {
                    if !((o.len() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minProperties")))); }
                }
                if let Some(Value::Num(n)) = get("maxProperties") {
                    if !((o.len() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxProperties")))); }
                }
                if let Some(Value::Arr(rs)) = get("required") {
                    for (j, r) in rs.iter().enumerate() {
                        if let Value::Str(name) = r {
                            if !o.iter().any(|(k, _)| k == name) {
                                errs.push((ptr(iloc), ptr(&child(&child(sloc, "required"), &j.to_string()))));
                            }
                        }
                    }
                }
                if let Some(Value::Obj(ps)) = get("properties") {
                    for (k, v) in o {
                        if let Some(sub) = ps.iter().find(|(pk, _)| pk == k).map(|(_, sv)| sv) {
                            validate(root, v, &child(iloc, k), sub, &child(&child(sloc, "properties"), k), errs);
                        }
                    }
                }
                if let Some(ap) = get("additionalProperties") {
                    let props = get("properties");
                    for (k, v) in o {
                        let in_props = match props { Some(Value::Obj(ps)) => ps.iter().any(|(pk, _)| pk == k), _ => false };
                        if !in_props {
                            validate(root, v, &child(iloc, k), ap, &child(sloc, "additionalProperties"), errs);
                        }
                    }
                }
            }
            if let Some(Value::Arr(ss)) = get("allOf") {
                for (i, s) in ss.iter().enumerate() {
                    validate(root, inst, iloc, s, &child(&child(sloc, "allOf"), &i.to_string()), errs);
                }
            }
            if let Some(Value::Arr(ss)) = get("anyOf") {
                if !ss.iter().any(|s| accepts(root, inst, s)) {
                    errs.push((ptr(iloc), ptr(&child(sloc, "anyOf"))));
                }
            }
            if let Some(Value::Arr(ss)) = get("oneOf") {
                let cnt = ss.iter().filter(|s| accepts(root, inst, s)).count();
                if cnt != 1 { errs.push((ptr(iloc), ptr(&child(sloc, "oneOf")))); }
            }
            if let Some(ns) = get("not") {
                if accepts(root, inst, ns) { errs.push((ptr(iloc), ptr(&child(sloc, "not")))); }
            }
            if let Some(iff) = get("if") {
                if accepts(root, inst, iff) {
                    if let Some(t) = get("then") { validate(root, inst, iloc, t, &child(sloc, "then"), errs); }
                } else if let Some(e) = get("else") {
                    validate(root, inst, iloc, e, &child(sloc, "else"), errs);
                }
            }
            if let Some(Value::Str(r)) = get("$ref") {
                if r == "#" {
                    validate(root, inst, iloc, root, &[], errs);
                } else if let Some(raw) = r.strip_prefix("#/$defs/") {
                    let name = decode_token(raw);
                    if let Value::Obj(rm) = root {
                        if let Some(Value::Obj(defs)) = rm.iter().find(|(k, _)| k == "$defs").map(|(_, v)| v) {
                            if let Some(t) = defs.iter().find(|(k, _)| *k == name).map(|(_, v)| v) {
                                validate(root, inst, iloc, t, &child(&["$defs".to_string()], &name), errs);
                            }
                        }
                    }
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = Path::new(&args[1]);
    let schema_s = fs::read_to_string(dir.join("schema.json")).unwrap();
    let inst_s = fs::read_to_string(dir.join("instances.json")).unwrap();
    let schema = parse(&schema_s).unwrap();
    let insts = match parse(&inst_s).unwrap() { Value::Arr(a) => a, _ => vec![] };
    let mut out = String::new();
    let mut nv = 0usize; let mut ni = 0usize;
    for (i, inst) in insts.iter().enumerate() {
        let mut errs = Vec::new();
        validate(&schema, inst, &[], &schema, &[], &mut errs);
        errs.sort();
        errs.dedup();
        if errs.is_empty() {
            nv += 1;
            out.push_str(&format!("{}: valid\n", i));
        } else {
            ni += 1;
            out.push_str(&format!("{}: invalid ({})\n", i, errs.len()));
            for (a, b) in &errs {
                out.push_str(&format!("  {} {}\n", a, b));
            }
        }
    }
    out.push_str(&format!("valid={} invalid={}\n", nv, ni));
    print!("{}", out);
}

use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone, Debug)]
enum Value { Null, Bool(bool), Num(f64), Str(String), Arr(Vec<Value>), Obj(Vec<(String, Value)>) }

struct P<'a> { b: &'a [u8], i: usize }

impl<'a> P<'a> {
    fn ws(&mut self) { while self.i < self.b.len() && matches!(self.b[self.i], b' '|b'\t'|b'\n'|b'\r') { self.i += 1; } }
    fn value(&mut self) -> Result<Value, String> {
        self.ws();
        match self.b.get(self.i) {
            None => Err("eof".into()),
            Some(b'n') => { self.i += 4; Ok(Value::Null) }
            Some(b't') => { self.i += 4; Ok(Value::Bool(true)) }
            Some(b'f') => { self.i += 5; Ok(Value::Bool(false)) }
            Some(b'"') => self.string(),
            Some(b'[') => self.array(),
            Some(b'{') => self.object(),
            Some(_) => self.number(),
        }
    }
    fn string(&mut self) -> Result<Value, String> {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.b[self.i]; self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.b[self.i]; self.i += 1;
                    match e {
                        b'"' => out.push(b'"'), b'\\' => out.push(b'\\'), b'/' => out.push(b'/'),
                        b'b' => out.push(8), b'f' => out.push(12), b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'), b't' => out.push(b'\t'),
                        b'u' => {
                            let mut c = self.hex4();
                            if (0xD800..0xDC00).contains(&c) && self.b[self.i] == b'\\' && self.b[self.i+1] == b'u' {
                                self.i += 2;
                                let lo = self.hex4();
                                c = 0x10000 + ((c - 0xD800) << 10) + (lo - 0xDC00);
                            }
                            let ch = char::from_u32(c).unwrap_or('\u{FFFD}');
                            let mut buf = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return Err("bad escape".into()),
                    }
                }
                _ => out.push(c),
            }
        }
        Ok(Value::Str(String::from_utf8(out).unwrap()))
    }
    fn hex4(&mut self) -> u32 {
        let s = std::str::from_utf8(&self.b[self.i..self.i+4]).unwrap();
        self.i += 4;
        u32::from_str_radix(s, 16).unwrap()
    }
    fn array(&mut self) -> Result<Value, String> {
        self.i += 1; let mut v = Vec::new(); self.ws();
        if self.b[self.i] == b']' { self.i += 1; return Ok(Value::Arr(v)); }
        loop {
            v.push(self.value()?);
            self.ws();
            match self.b[self.i] { b',' => { self.i += 1; } b']' => { self.i += 1; break; } _ => return Err("arr".into()) }
        }
        Ok(Value::Arr(v))
    }
    fn object(&mut self) -> Result<Value, String> {
        self.i += 1; let mut v = Vec::new(); self.ws();
        if self.b[self.i] == b'}' { self.i += 1; return Ok(Value::Obj(v)); }
        loop {
            self.ws();
            let k = match self.string()? { Value::Str(s) => s, _ => return Err("key".into()) };
            self.ws();
            if self.b[self.i] != b':' { return Err("colon".into()); }
            self.i += 1;
            v.push((k, self.value()?));
            self.ws();
            match self.b[self.i] { b',' => { self.i += 1; } b'}' => { self.i += 1; break; } _ => return Err("obj".into()) }
        }
        Ok(Value::Obj(v))
    }
    fn number(&mut self) -> Result<Value, String> {
        let start = self.i;
        if self.b[self.i] == b'-' { self.i += 1; }
        while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        if self.i < self.b.len() && self.b[self.i] == b'.' {
            self.i += 1;
            while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        }
        if self.i < self.b.len() && (self.b[self.i] == b'e' || self.b[self.i] == b'E') {
            self.i += 1;
            if self.i < self.b.len() && (self.b[self.i] == b'+' || self.b[self.i] == b'-') { self.i += 1; }
            while self.i < self.b.len() && self.b[self.i].is_ascii_digit() { self.i += 1; }
        }
        let s = std::str::from_utf8(&self.b[start..self.i]).unwrap();
        Ok(Value::Num(s.parse::<f64>().unwrap()))
    }
}

fn parse(s: &str) -> Result<Value, String> {
    let mut p = P { b: s.as_bytes(), i: 0 };
    let v = p.value()?;
    p.ws();
    if p.i != p.b.len() { return Err("trailing".into()); }
    Ok(v)
}

fn deq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Arr(x), Value::Arr(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| deq(p, q)),
        (Value::Obj(x), Value::Obj(y)) => x.len() == y.len()
            && x.iter().all(|(k, v)| y.iter().find(|(k2, _)| k2 == k).map_or(false, |(_, v2)| deq(v, v2))),
        _ => false,
    }
}

fn ptr(t: &[String]) -> String {
    let mut s = String::from("#");
    for tok in t {
        s.push('/');
        for c in tok.chars() {
            match c { '~' => s.push_str("~0"), '/' => s.push_str("~1"), _ => s.push(c) }
        }
    }
    s
}

fn child(t: &[String], tok: &str) -> Vec<String> { let mut v = t.to_vec(); v.push(tok.to_string()); v }

fn decode_token(s: &str) -> String {
    let mut r = String::new();
    let mut it = s.chars();
    while let Some(c) = it.next() {
        if c == '~' {
            match it.next() { Some('0') => r.push('~'), Some('1') => r.push('/'), o => { r.push('~'); if let Some(c2) = o { r.push(c2); } } }
        } else { r.push(c); }
    }
    r
}

fn type_match(v: &Value, n: &str) -> bool {
    match n {
        "null" => matches!(v, Value::Null),
        "boolean" => matches!(v, Value::Bool(_)),
        "string" => matches!(v, Value::Str(_)),
        "array" => matches!(v, Value::Arr(_)),
        "object" => matches!(v, Value::Obj(_)),
        "number" => matches!(v, Value::Num(_)),
