    }
}

fn accepts(root: &Value, inst: &Value, sch: &Value) -> bool {
    let mut e = Vec::new();
    validate(root, inst, &[], sch, &[], &mut e);
    e.is_empty()
}

fn validate(root: &Value, inst: &Value, iloc: &[String], sch: &Value, sloc: &[String], errs: &mut Vec<(String, String)>) {
    match sch {
        Value::Bool(true) => {}
        Value::Bool(false) => errs.push((ptr(iloc), ptr(sloc))),
        Value::Obj(m) => {
            let get = |k: &str| m.iter().find(|(kk, _)| kk == k).map(|(_, v)| v);

            if let Some(tv) = get("type") {
                let names: Vec<&str> = match tv {
                    Value::Str(s) => vec![s.as_str()],
                    Value::Arr(a) => a.iter().filter_map(|v| if let Value::Str(s) = v { Some(s.as_str()) } else { None }).collect(),
                    _ => vec![],
                };
                if !names.is_empty() && !names.iter().any(|n| type_match(inst, n)) {
                    errs.push((ptr(iloc), ptr(&child(sloc, "type"))));
                }
            }
            if let Some(Value::Arr(es)) = get("enum") {
                if !es.iter().any(|e| deq(e, inst)) { errs.push((ptr(iloc), ptr(&child(sloc, "enum")))); }
            }
            if let Some(cv) = get("const") {
                if !deq(cv, inst) { errs.push((ptr(iloc), ptr(&child(sloc, "const")))); }
            }
            if let Value::Num(x) = inst {
                let checks: [(&str, fn(f64, f64) -> bool); 4] = [
                    ("minimum", |x, k| x >= k), ("maximum", |x, k| x <= k),
                    ("exclusiveMinimum", |x, k| x > k), ("exclusiveMaximum", |x, k| x < k),
                ];
                for (kw, ok) in checks {
                    if let Some(Value::Num(k)) = get(kw) {
                        if !ok(*x, *k) { errs.push((ptr(iloc), ptr(&child(sloc, kw)))); }
                    }
                }
            }
            if let Value::Str(s) = inst {
                if let Some(Value::Num(n)) = get("minLength") {
                    if !((s.chars().count() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minLength")))); }
                }
                if let Some(Value::Num(n)) = get("maxLength") {
                    if !((s.chars().count() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxLength")))); }
                }
            }
            if let Value::Arr(a) = inst {
                if let Some(Value::Num(n)) = get("minItems") {
                    if !((a.len() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minItems")))); }
                }
                if let Some(Value::Num(n)) = get("maxItems") {
                    if !((a.len() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxItems")))); }
                }
                if let Some(Value::Bool(true)) = get("uniqueItems") {
                    'outer: for i in 0..a.len() {
                        for j in i + 1..a.len() {
                            if deq(&a[i], &a[j]) {
                                errs.push((ptr(iloc), ptr(&child(sloc, "uniqueItems"))));
                                break 'outer;
                            }
                        }
                    }
                }
                if let Some(Value::Arr(pi)) = get("prefixItems") {
                    for i in 0..a.len().min(pi.len()) {
                        validate(root, &a[i], &child(iloc, &i.to_string()), &pi[i],
                                 &child(&child(sloc, "prefixItems"), &i.to_string()), errs);
                    }
                }
                if let Some(it) = get("items") {
                    let start = match get("prefixItems") { Some(Value::Arr(pi)) => pi.len(), _ => 0 };
                    for i in start..a.len() {
                        validate(root, &a[i], &child(iloc, &i.to_string()), it, &child(sloc, "items"), errs);
                    }
                }
            }
            if let Value::Obj(o) = inst {
                if let Some(Value::Num(n)) = get("minProperties") {
                    if !((o.len() as f64) >= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "minProperties")))); }
                }
                if let Some(Value::Num(n)) = get("maxProperties") {
                    if !((o.len() as f64) <= *n) { errs.push((ptr(iloc), ptr(&child(sloc, "maxProperties")))); }
                }
                if let Some(Value::Arr(rs)) = get("required") {
                    for (j, r) in rs.iter().enumerate() {
                        if let Value::Str(name) = r {
                            if !o.iter().any(|(k, _)| k == name) {
                                errs.push((ptr(iloc), ptr(&child(&child(sloc, "required"), &j.to_string()))));
                            }
                        }
                    }
                }
                if let Some(Value::Obj(ps)) = get("properties") {
                    for (k, v) in o {
                        if let Some(sub) = ps.iter().find(|(pk, _)| pk == k).map(|(_, sv)| sv) {
                            validate(root, v, &child(iloc, k), sub, &child(&child(sloc, "properties"), k), errs);
                        }
                    }
                }
                if let Some(ap) = get("additionalProperties") {
                    let props = get("properties");
                    for (k, v) in o {
                        let in_props = match props { Some(Value::Obj(ps)) => ps.iter().any(|(pk, _)| pk == k), _ => false };
                        if !in_props {
                            validate(root, v, &child(iloc, k), ap, &child(sloc, "additionalProperties"), errs);
                        }
                    }
                }
            }
            if let Some(Value::Arr(ss)) = get("allOf") {
                for (i, s) in ss.iter().enumerate() {
                    validate(root, inst, iloc, s, &child(&child(sloc, "allOf"), &i.to_string()), errs);
                }
            }
            if let Some(Value::Arr(ss)) = get("anyOf") {
                if !ss.iter().any(|s| accepts(root, inst, s)) {
                    errs.push((ptr(iloc), ptr(&child(sloc, "anyOf"))));
                }
            }
            if let Some(Value::Arr(ss)) = get("oneOf") {
                let cnt = ss.iter().filter(|s| accepts(root, inst, s)).count();
                if cnt != 1 { errs.push((ptr(iloc), ptr(&child(sloc, "oneOf")))); }
            }
            if let Some(ns) = get("not") {
                if accepts(root, inst, ns) { errs.push((ptr(iloc), ptr(&child(sloc, "not")))); }
            }
            if let Some(iff) = get("if") {
                if accepts(root, inst, iff) {
                    if let Some(t) = get("then") { validate(root, inst, iloc, t, &child(sloc, "then"), errs); }
                } else if let Some(e) = get("else") {
                    validate(root, inst, iloc, e, &child(sloc, "else"), errs);
                }
            }
            if let Some(Value::Str(r)) = get("$ref") {
                if r == "#" {
                    validate(root, inst, iloc, root, &[], errs);
                } else if let Some(raw) = r.strip_prefix("#/$defs/") {
                    let name = decode_token(raw);
                    if let Value::Obj(rm) = root {
                        if let Some(Value::Obj(defs)) = rm.iter().find(|(k, _)| k == "$defs").map(|(_, v)| v) {
                            if let Some(t) = defs.iter().find(|(k, _)| *k == name).map(|(_, v)| v) {
                                validate(root, inst, iloc, t, &child(&["$defs".to_string()], &name), errs);
                            }
                        }
                    }
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = Path::new(&args[1]);
    let schema_s = fs::read_to_string(dir.join("schema.json")).unwrap();
    let inst_s = fs::read_to_string(dir.join("instances.json")).unwrap();
    let schema = parse(&schema_s).unwrap();
    let insts = match parse(&inst_s).unwrap() { Value::Arr(a) => a, _ => vec![] };
    let mut out = String::new();
    let mut nv = 0usize; let mut ni = 0usize;
    for (i, inst) in insts.iter().enumerate() {
        let mut errs = Vec::new();
        validate(&schema, inst, &[], &schema, &[], &mut errs);
        errs.sort();
        errs.dedup();
        if errs.is_empty() {
            nv += 1;
            out.push_str(&format!("{}: valid\n", i));
        } else {
            ni += 1;
            out.push_str(&format!("{}: invalid ({})\n", i, errs.len()));
            for (a, b) in &errs {
                out.push_str(&format!("  {} {}\n", a, b));
            }
        }
    }
    out.push_str(&format!("valid={} invalid={}\n", nv, ni));
    print!("{}", out);
}

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Acct {
        String name, code; int scale; BigDecimal limit, bal;
        Acct(String n, String c, int s, BigDecimal l) { name = n; code = c; scale = s; limit = l; bal = BigDecimal.ZERO.setScale(s); }
    }
    static Map<String, Acct> accounts = new HashMap<>();
    static Map<String, Integer> currencies = new HashMap<>();
    static List<String> rejects = new ArrayList<>();

    static BigDecimal round(BigDecimal v, int s) { return v.setScale(s, RoundingMode.HALF_EVEN); }

    static String fmt(BigDecimal v, int scale) {
        BigInteger uns = v.abs().unscaledValue();
        String d = uns.toString();
        if (scale > 0) while (d.length() <= scale) d = "0" + d;
        String ip = scale > 0 ? d.substring(0, d.length() - scale) : d;
        StringBuilder g = new StringBuilder();
        for (int i = 0; i < ip.length(); i++) {
            g.append(ip.charAt(i));
            int rem = ip.length() - 1 - i;
            if (rem > 0 && rem % 3 == 0) g.append(',');
        }
        StringBuilder o = new StringBuilder();
        if (v.signum() < 0) o.append('-');
        o.append(g);
        if (scale > 0) o.append('.').append(d.substring(d.length() - scale));
        return o.toString();
    }

    static String process(String cmd, String[] t) {
        switch (cmd) {
            case "currency":
                currencies.put(t[1], Integer.parseInt(t[2]));
                return null;
            case "open": {
                if (accounts.containsKey(t[1])) return "account exists " + t[1];
                int sc = currencies.get(t[2]);
                BigDecimal lim = t.length > 3 ? round(new BigDecimal(t[3]), sc) : BigDecimal.ZERO;
                accounts.put(t[1], new Acct(t[1], t[2], sc, lim));
                return null;
            }
        }
        List<String> names = new ArrayList<>();
        switch (cmd) {
            case "deposit": case "withdraw": case "interest":
                names.add(t[1]); break;
            case "transfer": case "convert":
                names.add(t[1]); names.add(t[2]); break;
            case "split":
                names.add(t[1]);
                for (int i = 3; i < t.length; i++) names.add(t[i].split(":")[0]);
                break;
        }
        for (String n : names) if (!accounts.containsKey(n)) return "unknown account " + n;

        switch (cmd) {
            case "deposit": {
                Acct a = accounts.get(t[1]);
                BigDecimal amt = round(new BigDecimal(t[2]), a.scale);
                if (amt.signum() <= 0) return "non-positive amount";
                a.bal = a.bal.add(amt);
                return null;
            }
            case "withdraw": {
                Acct a = accounts.get(t[1]);
                BigDecimal amt = round(new BigDecimal(t[2]), a.scale);
                if (amt.signum() <= 0) return "non-positive amount";
                if (a.bal.subtract(amt).compareTo(a.limit.negate()) < 0) return "insufficient funds " + a.name;
                a.bal = a.bal.subtract(amt);
                return null;
            }
            case "transfer": {
                Acct f = accounts.get(t[1]), to = accounts.get(t[2]);
                if (!f.code.equals(to.code)) return "currency mismatch";
                BigDecimal amt = round(new BigDecimal(t[3]), f.scale);
                if (amt.signum() <= 0) return "non-positive amount";
                if (f.bal.subtract(amt).compareTo(f.limit.negate()) < 0) return "insufficient funds " + f.name;
                f.bal = f.bal.subtract(amt);
                to.bal = to.bal.add(amt);
                return null;
            }
            case "convert": {
                Acct f = accounts.get(t[1]), to = accounts.get(t[2]);
                BigDecimal amt = round(new BigDecimal(t[3]), f.scale);
                if (amt.signum() <= 0) return "non-positive amount";
                if (f.bal.subtract(amt).compareTo(f.limit.negate()) < 0) return "insufficient funds " + f.name;
                BigDecimal toAmt = round(amt.multiply(new BigDecimal(t[4])), to.scale);
                f.bal = f.bal.subtract(amt);
                to.bal = to.bal.add(toAmt);
                return null;
            }
            case "interest": {
                Acct a = accounts.get(t[1]);
                a.bal = a.bal.add(round(a.bal.multiply(new BigDecimal(t[2])), a.scale));
                return null;
            }
            case "split": {
                Acct f = accounts.get(t[1]);
                for (int i = 3; i < t.length; i++)
                    if (!accounts.get(t[i].split(":")[0]).code.equals(f.code)) return "currency mismatch";
                BigDecimal amt = round(new BigDecimal(t[2]), f.scale);
                if (amt.signum() <= 0) return "non-positive amount";
                if (f.bal.subtract(amt).compareTo(f.limit.negate()) < 0) return "insufficient funds " + f.name;
                BigInteger A = amt.unscaledValue();
                int m = t.length - 3;
                BigInteger[] w = new BigInteger[m];
                BigInteger[] fl = new BigInteger[m];
                BigInteger[] rem = new BigInteger[m];
                BigInteger W = BigInteger.ZERO;
                for (int i = 0; i < m; i++) { w[i] = new BigInteger(t[i + 3].split(":")[1]); W = W.add(w[i]); }
                BigInteger sumF = BigInteger.ZERO;
                for (int i = 0; i < m; i++) {
                    fl[i] = A.multiply(w[i]).divide(W);
                    rem[i] = A.multiply(w[i]).mod(W);
                    sumF = sumF.add(fl[i]);
                }
                int leftover = A.subtract(sumF).intValueExact();
                Integer[] idx = new Integer[m];
                for (int i = 0; i < m; i++) idx[i] = i;
                Arrays.sort(idx, (x, y) -> rem[y].compareTo(rem[x]));
                for (int k = 0; k < m; k++) {
                    BigInteger units = fl[k].add(k < leftover ? BigInteger.ONE : BigInteger.ZERO);
                    Acct to = accounts.get(t[idx[k] + 3].split(":")[0]);
                    to.bal = to.bal.add(new BigDecimal(units, f.scale));
                }
                f.bal = f.bal.subtract(amt);
                return null;
            }
        }
        return null;
    }

    public static void main(String[] args) throws Exception {
        List<String> lines = Files.readAllLines(Paths.get(args[0], "ledger.txt"));
        int ln = 0;
        for (String line : lines) {
            ln++;
            String tr = line.trim();
            if (tr.isEmpty() || tr.startsWith("#")) continue;
            String[] t = tr.split("\\s+");
            String reason = process(t[0], t);
            if (reason != null) rejects.add("line " + ln + ": REJECT " + reason);
        }
        StringBuilder out = new StringBuilder();
        for (String r : rejects) out.append(r).append('\n');
        out.append('\n');
        List<String> names = new ArrayList<>(accounts.keySet());
        Collections.sort(names);
        Map<String, BigDecimal[]> totals = new TreeMap<>();
        for (String n : names) {
            Acct a = accounts.get(n);
            out.append(a.name).append(' ').append(a.code).append(' ').append(fmt(a.bal, a.scale)).append('\n');
            BigDecimal[] tt = totals.get(a.code);
            if (tt == null) totals.put(a.code, new BigDecimal[]{a.bal, BigDecimal.ONE});
            else { tt[0] = tt[0].add(a.bal); tt[1] = tt[1].add(BigDecimal.ONE); }
        }
        out.append('\n');
        for (Map.Entry<String, BigDecimal[]> e : totals.entrySet()) {
            int sc = currencies.get(e.getKey());
            out.append("total ").append(e.getKey()).append(' ').append(fmt(e.getValue()[0], sc))
               .append(" (").append(e.getValue()[1].intValueExact()).append(" accounts)\n");
        }
        System.out.print(out);
    }
}

import Foundation

struct BigInt {
    var neg = false
    var d: [UInt32] = []   // little-endian, base 1e9, normalized

    static let BASE: UInt64 = 1_000_000_000

    var isZero: Bool { d.isEmpty }

    init() {}
    init(_ i: Int) {
        if i == 0 { return }
        neg = i < 0
        var x: UInt64 = neg ? UInt64(Int64(i).magnitude) : UInt64(i)
        while x > 0 { d.append(UInt32(x % 1_000_000_000)); x /= 1_000_000_000 }
    }
    init(digits: String) {
        let arr = Array(digits)
        var i = arr.count
        while i > 0 {
            let lo = max(0, i - 9)
            d.append(UInt32(String(arr[lo..<i]))!)
            i = lo
        }
        BigInt.norm(&d)
    }
    static func norm(_ dd: inout [UInt32]) { while let l = dd.last, l == 0 { dd.removeLast() } }

    func pad9(_ x: UInt32) -> String {
        var s = String(x)
        while s.count < 9 { s = "0" + s }
        return s
    }
    func magString() -> String {
        if d.isEmpty { return "0" }
        var parts: [String] = []
        for (i, limb) in d.enumerated() {
            parts.append(i == d.count - 1 ? String(limb) : pad9(limb))
        }
        return parts.reversed().joined()
    }

    static func cmpMag(_ a: [UInt32], _ b: [UInt32]) -> Int {
        if a.count != b.count { return a.count < b.count ? -1 : 1 }
        for i in stride(from: a.count - 1, through: 0, by: -1) {
            if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 }
        }
        return 0
    }
    static func addMag(_ a: [UInt32], _ b: [UInt32]) -> [UInt32] {
        var res: [UInt32] = []
        var carry: UInt64 = 0
        for i in 0..<max(a.count, b.count) {
            let x = UInt64(i < a.count ? a[i] : 0) + UInt64(i < b.count ? b[i] : 0) + carry
            res.append(UInt32(x % 1_000_000_000)); carry = x / 1_000_000_000
        }
        if carry > 0 { res.append(UInt32(carry)) }
        return res
    }
    static func subMag(_ a: [UInt32], _ b: [UInt32]) -> [UInt32] {
        var res: [UInt32] = []
        var borrow: Int64 = 0
        for i in 0..<a.count {
            var x = Int64(a[i]) - borrow - Int64(i < b.count ? b[i] : 0)
            if x < 0 { x += 1_000_000_000; borrow = 1 } else { borrow = 0 }
            res.append(UInt32(x))
        }
        norm(&res)
        return res
    }
    static func mulMag(_ a: [UInt32], _ b: [UInt32]) -> [UInt32] {
        if a.isEmpty || b.isEmpty { return [] }
        var res = [UInt32](repeating: 0, count: a.count + b.count)
        for i in 0..<a.count {
            var carry: UInt64 = 0
            let ai = UInt64(a[i])
            for j in 0..<b.count {
                let cur = UInt64(res[i + j]) + ai * UInt64(b[j]) + carry
                res[i + j] = UInt32(cur % 1_000_000_000); carry = cur / 1_000_000_000
            }
            var k = i + b.count
            while carry > 0 {
                let cur = UInt64(res[k]) + carry
                res[k] = UInt32(cur % 1_000_000_000); carry = cur / 1_000_000_000
                k += 1
            }
        }
        norm(&res)
        return res
    }
    static func divmodMag(_ a: [UInt32], _ b: [UInt32]) -> ([UInt32], [UInt32]) {
        precondition(!b.isEmpty)
        if cmpMag(a, b) < 0 { return ([], a) }
        if b.count == 1 {
            let dv = UInt64(b[0]); var rem: UInt64 = 0
            var q = [UInt32](repeating: 0, count: a.count)
            for i in stride(from: a.count - 1, through: 0, by: -1) {
                let cur = rem * 1_000_000_000 + UInt64(a[i])
                q[i] = UInt32(cur / dv); rem = cur % dv
            }
            norm(&q)
            return (q, rem == 0 ? [] : [UInt32(rem)])
        }
        let n = b.count
        let m = a.count - n
        let s = UInt64(1_000_000_000) / (UInt64(b[n - 1]) + 1)
        var u = mulMag(a, [UInt32(s)])
        let v = mulMag(b, [UInt32(s)])
        if u.count == a.count { u.append(0) }
        var q = [UInt32](repeating: 0, count: m + 1)
        let vn1 = UInt64(v[n - 1]), vn2 = UInt64(v[n - 2])
        for j in stride(from: m, through: 0, by: -1) {
            let hat = UInt64(u[j + n]) * 1_000_000_000 + UInt64(u[j + n - 1])
            var qhat = hat / vn1
            var rhat = hat % vn1
            while qhat >= 1_000_000_000 || qhat * vn2 > rhat * 1_000_000_000 + UInt64(u[j + n - 2]) {
                qhat -= 1
                rhat += vn1
                if rhat >= 1_000_000_000 { break }
            }
            var carry: UInt64 = 0
            var borrow: Int64 = 0
            for i in 0..<n {
                let p = qhat * UInt64(v[i]) + carry
                carry = p / 1_000_000_000
                var t = Int64(u[j + i]) - Int64(p % 1_000_000_000) - borrow
                if t < 0 { t += 1_000_000_000; borrow = 1 } else { borrow = 0 }
                u[j + i] = UInt32(t)
            }
            let top = Int64(u[j + n]) - Int64(carry) - borrow
            if top >= 0 {
                u[j + n] = UInt32(top)
            } else {
                var c: UInt64 = 0
                for i in 0..<n {
                    let cur = UInt64(u[j + i]) + UInt64(v[i]) + c
                    u[j + i] = UInt32(cur % 1_000_000_000); c = cur / 1_000_000_000
                }
                u[j + n] = UInt32((UInt64(u[j + n]) + c) % 1_000_000_000)
                qhat -= 1
            }
            q[j] = UInt32(qhat)
        }
        norm(&q)
        var rem: UInt64 = 0
        var rr = [UInt32](repeating: 0, count: n)
        for i in stride(from: n - 1, through: 0, by: -1) {
            let cur = rem * 1_000_000_000 + UInt64(u[i])
            rr[i] = UInt32(cur / s); rem = cur % s
        }
        norm(&rr)
        return (q, rr)
    }

    static func add(_ a: BigInt, _ b: BigInt) -> BigInt {
        if a.neg == b.neg {
            var r = BigInt(); r.neg = a.neg; r.d = addMag(a.d, b.d); return r
        }
        let c = cmpMag(a.d, b.d)
        if c == 0 { return BigInt() }
        var r = BigInt()
        if c > 0 { r.neg = a.neg; r.d = subMag(a.d, b.d) }
        else { r.neg = b.neg; r.d = subMag(b.d, a.d) }
        return r
    }
    static func neg(_ a: BigInt) -> BigInt {
        var r = a
        if !a.isZero { r.neg = !a.neg }
        return r
    }
    static func sub(_ a: BigInt, _ b: BigInt) -> BigInt { add(a, neg(b)) }
    static func mul(_ a: BigInt, _ b: BigInt) -> BigInt {
        var r = BigInt(); r.d = mulMag(a.d, b.d)
        r.neg = (a.neg != b.neg) && !r.isZero
        return r
    }
    static func cmp(_ a: BigInt, _ b: BigInt) -> Int {
        if a.neg != b.neg { return a.neg ? -1 : 1 }
        let c = cmpMag(a.d, b.d)
        return a.neg ? -c : c
    }
    // floor division, b > 0; returns (quotient, remainder) with 0 <= remainder < b
    static func divmodFloor(_ a: BigInt, _ b: BigInt) -> (BigInt, BigInt) {
        let (q0, r0) = divmodMag(a.d, b.d)
        if !a.neg {
            var q = BigInt(); q.d = q0
            var r = BigInt(); r.d = r0
            return (q, r)
        }
        if r0.isEmpty {
            var q = BigInt(); q.d = q0; q.neg = !q0.isEmpty
            return (q, BigInt())
        }
        var q = BigInt(); q.d = addMag(q0, [1]); q.neg = true
        var r = BigInt(); r.d = subMag(b.d, r0)
        return (q, r)
    }
    // round half-even of num/den, den > 0
    static func roundHalfEven(_ num: BigInt, _ den: BigInt) -> BigInt {
        var (q, r) = divmodFloor(num, den)
        if !r.isZero {
            let two = add(r, r)
            let c = cmp(two, den)
            if c > 0 || (c == 0 && (q.d.first ?? 0) % 2 == 1) {
                q = add(q, BigInt(1))
            }
        }
        return q
    }
    static func pow10(_ n: Int) -> BigInt {
        if n == 0 { return BigInt(1) }
        var s = "1"
        for _ in 0..<n { s += "0" }
        return BigInt(digits: s)
    }
}

func parseNum(_ s: String) -> (BigInt, Int)? {
    var str = Substring(s)
    var neg = false
    if str.hasPrefix("-") { neg = true; str = str.dropFirst() }
    let parts = str.split(separator: ".", omittingEmptySubsequences: false)
    if parts.count > 2 { return nil }
    let intPart = parts[0]
    let fracPart = parts.count == 2 ? parts[1] : ""
    if intPart.isEmpty { return nil }
    for ch in intPart + fracPart {
        if ch < "0" || ch > "9" { return nil }
    }
    var mag = BigInt(digits: String(intPart) + String(fracPart))
    if neg && !mag.isZero { mag.neg = true }
    return (mag, fracPart.count)
}

func roundAmount(_ m: BigInt, _ sc: Int, _ c: Int) -> BigInt {
    if sc <= c { return BigInt.mul(m, BigInt.pow10(c - sc)) }
    return BigInt.roundHalfEven(m, BigInt.pow10(sc - c))
}

func group(_ s: String) -> String {
    var res = ""
    let a = Array(s)
    for (i, ch) in a.enumerated() {
        if i > 0 && (a.count - i) % 3 == 0 { res += "," }
        res.append(ch)
    }
    return res
}

func format(_ v: BigInt, _ c: Int) -> String {
    var mag = v.magString()
    let isNeg = v.neg && mag != "0"
    if c > 0 {
        while mag.count <= c { mag = "0" + mag }
        let ip = String(mag.prefix(mag.count - c))
        let frac = String(mag.suffix(c))
        return (isNeg ? "-" : "") + group(ip) + "." + frac
    }
    return (isNeg ? "-" : "") + group(mag)
}

func main() {
    let args = CommandLine.arguments
    guard args.count > 1,
          let content = try? String(contentsOfFile: args[1] + "/ledger.txt", encoding: .utf8)
    else { return }

    var currencies: [String: Int] = [:]
    var accounts: [String: (code: String, limit: BigInt, bal: BigInt)] = [:]
    var rejects: [String] = []

    func process(_ toks: [String]) -> String? {
        switch toks[0] {
        case "currency":
            currencies[toks[1]] = Int(toks[2])
            return nil
        case "open":
            let name = toks[1], code = toks[2]
            if accounts[name] != nil { return "account exists \(name)" }
            let c = currencies[code] ?? 0
            var lim = BigInt(0)
            if toks.count > 3, let (m, sc) = parseNum(toks[3]) {
                lim = roundAmount(m, sc, c)
            }
            accounts[name] = (code, lim, BigInt(0))
            return nil
        case "deposit", "withdraw":
            let name = toks[1]
            guard accounts[name] != nil else { return "unknown account \(name)" }
            guard let (m, sc) = parseNum(toks[2]) else { return nil }
            let c = currencies[accounts[name]!.code]!
            let amt = roundAmount(m, sc, c)
            if BigInt.cmp(amt, BigInt(0)) <= 0 { return "non-positive amount" }
            var a = accounts[name]!
            if toks[0] == "deposit" {
                a.bal = BigInt.add(a.bal, amt)
            } else {
                if BigInt.cmp(BigInt.add(a.bal, a.limit), amt) < 0 {
                    return "insufficient funds \(name)"
                }
                a.bal = BigInt.sub(a.bal, amt)
            }
            accounts[name] = a
            return nil
        case "transfer":
            let from = toks[1], to = toks[2]
            for n in [from, to] {
                if accounts[n] == nil { return "unknown account \(n)" }
            }
            if accounts[from]!.code != accounts[to]!.code { return "currency mismatch" }
            guard let (m, sc) = parseNum(toks[3]) else { return nil }
            let c = currencies[accounts[from]!.code]!
            let amt = roundAmount(m, sc, c)
            if BigInt.cmp(amt, BigInt(0)) <= 0 { return "non-positive amount" }
            var f = accounts[from]!
            if BigInt.cmp(BigInt.add(f.bal, f.limit), amt) < 0 {
                return "insufficient funds \(from)"
            }
            f.bal = BigInt.sub(f.bal, amt)
            accounts[from] = f
            var t = accounts[to]!
            t.bal = BigInt.add(t.bal, amt)
            accounts[to] = t
            return nil
        case "convert":
            let from = toks[1], to = toks[2]
            for n in [from, to] {
                if accounts[n] == nil { return "unknown account \(n)" }
            }
            let fc = currencies[accounts[from]!.code]!
            let tc = currencies[accounts[to]!.code]!
            guard let (m, sc) = parseNum(toks[3]) else { return nil }
            let amt = roundAmount(m, sc, fc)
            if BigInt.cmp(amt, BigInt(0)) <= 0 { return "non-positive amount" }
            guard let (rm, rsc) = parseNum(toks[4]) else { return nil }
            let numer = BigInt.mul(BigInt.mul(amt, rm), BigInt.pow10(tc))
            let denom = BigInt.pow10(fc + rsc)
            let toAmt = BigInt.roundHalfEven(numer, denom)
            var f = accounts[from]!
            if BigInt.cmp(BigInt.add(f.bal, f.limit), amt) < 0 {
                return "insufficient funds \(from)"
            }
            f.bal = BigInt.sub(f.bal, amt)
            accounts[from] = f
            var t = accounts[to]!
            t.bal = BigInt.add(t.bal, toAmt)
            accounts[to] = t
            return nil
        case "interest":
            let name = toks[1]
            guard accounts[name] != nil else { return "unknown account \(name)" }
            guard let (rm, rsc) = parseNum(toks[2]) else { return nil }
            var a = accounts[name]!
            let delta = BigInt.roundHalfEven(BigInt.mul(a.bal, rm), BigInt.pow10(rsc))
            a.bal = BigInt.add(a.bal, delta)
            accounts[name] = a
            return nil
        case "split":
            let from = toks[1]
            guard accounts[from] != nil else { return "unknown account \(from)" }
            var targets: [String] = []
            var weights: [BigInt] = []
            for t in toks[3...] {
                let ps = t.split(separator: ":", omittingEmptySubsequences: false)
                let n = String(ps[0])
                if accounts[n] == nil { return "unknown account \(n)" }
                targets.append(n)
                weights.append(BigInt(digits: String(ps[1])))
            }
            for n in targets {
                if accounts[n]!.code != accounts[from]!.code { return "currency mismatch" }
            }
            guard let (m, sc) = parseNum(toks[2]) else { return nil }
            let c = currencies[accounts[from]!.code]!
            let A = roundAmount(m, sc, c)
            if BigInt.cmp(A, BigInt(0)) <= 0 { return "non-positive amount" }
            var f = accounts[from]!
            if BigInt.cmp(BigInt.add(f.bal, f.limit), A) < 0 {
                return "insufficient funds \(from)"
            }
            var W = BigInt(0)
            for w in weights { W = BigInt.add(W, w) }
            var shares: [BigInt] = []
            var rems: [BigInt] = []
            for w in weights {
                let (q, r) = BigInt.divmodFloor(BigInt.mul(A, w), W)
                shares.append(q); rems.append(r)
            }
            var total = BigInt(0)
            for s in shares { total = BigInt.add(total, s) }
            let leftover = Int(BigInt.sub(A, total).magString())!
            let order = Array(0..<targets.count).sorted { x, y in
                let cc = BigInt.cmp(rems[x], rems[y])
                return cc != 0 ? cc > 0 : x < y
            }
            f.bal = BigInt.sub(f.bal, A)
            accounts[from] = f
            for i in 0..<targets.count {
                var a = accounts[targets[i]]!
                a.bal = BigInt.add(a.bal, shares[i])
                accounts[targets[i]] = a
            }
            for i in 0..<leftover {
                let n = targets[order[i]]
                var a = accounts[n]!
                a.bal = BigInt.add(a.bal, BigInt(1))
                accounts[n] = a
            }
            return nil
        default:
            return nil
        }
    }

    let lines = content.components(separatedBy: "\n")
    for (idx, raw) in lines.enumerated() {
        let lineNo = idx + 1
        let trimmed = raw.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }
        let toks = trimmed.split(separator: " ").map(String.init)
        if let r = process(toks) {
            rejects.append("line \(lineNo): REJECT \(r)")
        }
    }

    var out: [String] = []
    out.append(contentsOf: rejects)
    out.append("")
    var totals: [String: (BigInt, Int)] = [:]
    for name in accounts.keys.sorted() {
        let a = accounts[name]!
        print(name, a.code, format(a.bal, currencies[a.code]!))
        var t = totals[a.code, default: (BigInt(0), 0)]
        t.0 = BigInt.add(t.0, a.bal)
        t.1 += 1
        totals[a.code] = t
    }
    print()
    for code in totals.keys.sorted() {
        let t = totals[code]!
        print("total \(code) \(format(t.0, currencies[code]!)) (\(t.1) accounts)")
    }
}

