    title: "Sum integers",
    description: "Add up a non-empty list of integers.",
    inputSchema: {
      type: "object",
      properties: {
        numbers: { type: "array", items: { type: "integer" }, minItems: 1 },
      },
      required: ["numbers"],
      additionalProperties: false,
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" },
      },
      required: ["sum", "count"],
    },
    annotations: { readOnlyHint: true, idempotentHint: true },
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string" },
      },
      required: ["text"],
      additionalProperties: false,
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" },
      },
      required: ["words", "codepoints", "utf8_bytes"],
    },
    annotations: { readOnlyHint: true },
  },
];

function toolByName(name: string) {
  return TOOLS.find((t) => t.name === name);
}

function isValidId(v: unknown): boolean {
  if (typeof v === "string") return true;
  if (typeof v === "number") return Number.isInteger(v);
  return false;
}

function isInteger(v: unknown): boolean {
  return typeof v === "number" && Number.isInteger(v);
}

// Sort by Unicode code point (not UTF-16 code unit).
function codePoints(s: string): number[] {
  return Array.from(s, (c) => c.codePointAt(0)!);
}

function compareCodePoints(a: string, b: string): number {
  const ca = codePoints(a);
  const cb = codePoints(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i++) {
    if (ca[i] !== cb[i]) return ca[i] - cb[i];
  }
  return ca.length - cb.length;
}

function startsWithCodePoint(s: string, prefix: string): boolean {
  if (prefix === "") return true;
  const cs = codePoints(s);
  const cp = codePoints(prefix);
  if (cp.length > cs.length) return false;
  for (let i = 0; i < cp.length; i++) {
    if (cs[i] !== cp[i]) return false;
  }
  return true;
}

function utf8Bytes(s: string): number {
  return Buffer.byteLength(s, "utf8");
}

const kv = new Map<string, string>();
let initialized = false;

function fail(msg: string) {
  return { content: [{ type: "text", text: msg }], isError: true };
}

function successText(text: string) {
  return { content: [{ type: "text", text }], isError: false };
}

function successStructured(s: object) {
  return {
    content: [{ type: "text", text: JSON.stringify(s) }],
    structuredContent: s,
    isError: false,
  };
}

// Validate arguments; returns error message string or null.
function validateArgs(tool: any, args: Record<string, unknown>): string | null {
  const props = tool.inputSchema.properties as Record<string, any>;
  const required: string[] = tool.inputSchema.required ?? [];

  // unknown arguments: smallest by code point
  const unknown = Object.keys(args)
    .filter((k) => !(k in props))
    .sort(compareCodePoints);
  if (unknown.length > 0) return `unknown argument: ${unknown[0]}`;

  for (const name of Object.keys(props)) {
    const spec = props[name];
    const present = name in args;
    if (!present) {
      if (required.includes(name)) return `missing required argument: ${name}`;
      continue;
    }
    const v = args[name];
    if (spec.type === "string") {
      if (typeof v !== "string") return `argument ${name} must be a string`;
      if (spec.minLength === 1 && v.length === 0) return `argument ${name} must not be empty`;
    } else if (spec.type === "array") {
      if (!Array.isArray(v)) return `argument ${name} must be an array of integers`;
      if (!v.every(isInteger)) return `argument ${name} must be an array of integers`;
      if (spec.minItems === 1 && v.length === 0) return `argument ${name} must not be empty`;
    }
  }
  return null;
}

function runTool(name: string, args: Record<string, unknown>): object {
  switch (name) {
    case "kv_set": {
      const key = args.key as string;
      const value = args.value as string;
      const existed = kv.has(key);
      kv.set(key, value);
      return successText(`${existed ? "updated" : "created"} ${key}`);
    }
    case "kv_get": {
      const key = args.key as string;
      if (!kv.has(key)) return fail(`key not found: ${key}`);
      return successText(kv.get(key)!);
    }
    case "kv_list": {
      const prefix = typeof args.prefix === "string" ? args.prefix : "";
      const keys = Array.from(kv.keys())
        .filter((k) => startsWithCodePoint(k, prefix))
        .sort(compareCodePoints);
      return successStructured({ keys, count: keys.length });
    }
    case "sum": {
      const numbers = args.numbers as number[];
      const sum = numbers.reduce((a, b) => a + b, 0);
      return successStructured({ sum, count: numbers.length });
    }
    case "text_stats": {
      const text = args.text as string;
      let words = 0;
      let inWord = false;
      for (const ch of text) {
        const sep = ch === " " || ch === "\t" || ch === "\n" || ch === "\r";
        if (!sep) {
          if (!inWord) words++;
          inWord = true;
        } else {
          inWord = false;
        }
      }
      const codepoints = Array.from(text).length;
      const bytes = utf8Bytes(text);
      return successStructured({ words, codepoints, utf8_bytes: bytes });
    }
  }
  // unreachable
  return fail("unknown tool");
}

function handleRequest(msg: any): object {
  const method = msg.method;

  if (!["initialize", "ping", "tools/list", "tools/call"].includes(method)) {
    return { jsonrpc: "2.0", id: msg.id, error: { code: -32601, message: "Method not found" } };
  }

  if ("params" in msg && msg.params !== undefined && (typeof msg.params !== "object" || msg.params === null || Array.isArray(msg.params))) {
    return { jsonrpc: "2.0", id: msg.id, error: { code: -32602, message: "Invalid params" } };
  }

  if (!initialized && method !== "initialize" && method !== "ping") {
    return { jsonrpc: "2.0", id: msg.id, error: { code: -32002, message: "Server not initialized" } };
  }

  const params = msg.params ?? {};

  switch (method) {
    case "initialize": {
      if (initialized) {
        return { jsonrpc: "2.0", id: msg.id, error: { code: -32600, message: "Already initialized" } };
      }
      const pv = params.protocolVersion;
      if (typeof pv !== "string") {
        return { jsonrpc: "2.0", id: msg.id, error: { code: -32602, message: "Invalid params" } };
      }
      initialized = true;
      const version = PROTOCOL_VERSIONS.includes(pv) ? pv : "2025-06-18";
      return {
        jsonrpc: "2.0",
        id: msg.id,
        result: {
          protocolVersion: version,
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" },
        },
      };
    }
    case "ping":
      return { jsonrpc: "2.0", id: msg.id, result: {} };
    case "tools/list":
      return { jsonrpc: "2.0", id: msg.id, result: { tools: TOOLS } };
    case "tools/call": {
      const toolName = params.name;
      if (typeof toolName !== "string") {
        return { jsonrpc: "2.0", id: msg.id, error: { code: -32602, message: "Invalid params" } };
      }
      const tool = toolByName(toolName);
      if (!tool) {
        return { jsonrpc: "2.0", id: msg.id, error: { code: -32602, message: `Unknown tool: ${toolName}` } };
      }
      let args: Record<string, unknown> = {};
      if ("arguments" in params && params.arguments !== undefined) {
        args = params.arguments;
      }
      if (typeof args !== "object" || args === null || Array.isArray(args)) {
        return { jsonrpc: "2.0", id: msg.id, result: fail("arguments must be an object") };
      }
      const err = validateArgs(tool, args);
      if (err !== null) {
        return { jsonrpc: "2.0", id: msg.id, result: fail(err) };
      }
      return { jsonrpc: "2.0", id: msg.id, result: runTool(toolName, args) };
    }
  }
  // unreachable
  return { jsonrpc: "2.0", id: msg.id, error: { code: -32601, message: "Method not found" } };
}

function processLine(line: string): string | null {
  let msg: unknown;
  try {
    msg = JSON.parse(line);
  } catch {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
  }

  if (typeof msg !== "object" || msg === null || Array.isArray(msg)) {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } });
  }

  const obj = msg as Record<string, unknown>;

  // Response from client: ignore.
  if (!("method" in obj) && ("result" in obj || "error" in obj)) {
    return null;
  }

  // Invalid request checks.
  if (obj.jsonrpc !== "2.0" || typeof obj.method !== "string" || ("id" in obj && !isValidId(obj.id))) {
    const id = isValidId(obj.id) ? obj.id : null;
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32600, message: "Invalid Request" } });
  }

  // Notification: ignore completely.
  if (!("id" in obj)) {
    return null;
  }

  return JSON.stringify(handleRequest(obj));
}

const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

rl.on("line", (line: string) => {
  if (/^[\s\r]*$/.test(line)) return;
  const out = processLine(line);
  if (out !== null) {
    process.stdout.write(out + "\n");
  }
});

rl.on("close", () => {
  process.exit(0);
});

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // ---------- minimal JSON parser ----------
    static class ParseException extends RuntimeException {}

    static Object parse(String s) {
        P p = new P(s);
        p.ws();
        Object v = p.value();
        p.ws();
        if (p.i < p.s.length()) throw new ParseException();
        return v;
    }

    static class P {
        String s; int i = 0;
        P(String s) { this.s = s; }
        void ws() { while (i < s.length()) { char c = s.charAt(i); if (c==' '||c=='\t'||c=='\n'||c=='\r') i++; else break; } }
        char peek() { if (i >= s.length()) throw new ParseException(); return s.charAt(i); }
        char next() { if (i >= s.length()) throw new ParseException(); return s.charAt(i++); }
        void expect(char c) { if (next() != c) throw new ParseException(); }

        Object value() {
            char c = peek();
            switch (c) {
                case '{': return object();
                case '[': return array();
                case '"': return string();
                case 't': expect('t');expect('r');expect('u');expect('e'); return Boolean.TRUE;
                case 'f': expect('f');expect('a');expect('l');expect('s');expect('e'); return Boolean.FALSE;
                case 'n': expect('n');expect('u');expect('l');expect('l'); return null;
                default: return number();
            }
        }

        Map<String,Object> object() {
            expect('{');
            Map<String,Object> m = new LinkedHashMap<>();
            ws();
            if (peek() == '}') { next(); return m; }
            while (true) {
                ws();
                String k = string();
                ws();
                expect(':');
                ws();
                m.put(k, value());
                ws();
                char c = next();
                if (c == '}') return m;
                if (c != ',') throw new ParseException();
            }
        }

        List<Object> array() {
            expect('[');
            List<Object> l = new ArrayList<>();
            ws();
            if (peek() == ']') { next(); return l; }
            while (true) {
                ws();
                l.add(value());
                ws();
                char c = next();
                if (c == ']') return l;
                if (c != ',') throw new ParseException();
            }
        }

        String string() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = next();
                if (c == '"') return sb.toString();
                if (c == '\\') {
                    char e = next();
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            int cp = 0;
                            for (int k = 0; k < 4; k++) {
                                char h = next();
                                int d = Character.digit(h, 16);
                                if (d < 0) throw new ParseException();
                                cp = cp * 16 + d;
                            }
                            sb.append((char) cp);
                            break;
                        default: throw new ParseException();
                    }
                } else if (c < 0x20) {
                    throw new ParseException();
                } else {
                    sb.append(c);
                }
            }
        }

        Object number() {
            int start = i;
            if (peek() == '-') i++;
            if (i >= s.length()) throw new ParseException();
            if (peek() == '0') { i++; }
            else if (peek() >= '1' && peek() <= '9') { while (i < s.length() && Character.isDigit(s.charAt(i))) i++; }
            else throw new ParseException();
            boolean frac = false;
            if (i < s.length() && s.charAt(i) == '.') {
                frac = true; i++;
                if (i >= s.length() || !Character.isDigit(s.charAt(i))) throw new ParseException();
                while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            }
            if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
                frac = true; i++;
                if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
                if (i >= s.length() || !Character.isDigit(s.charAt(i))) throw new ParseException();
                while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            }
            String tok = s.substring(start, i);
            if (frac) return Double.parseDouble(tok);
            try { return Long.parseLong(tok); }
            catch (NumberFormatException ex) { return Double.parseDouble(tok); }
        }
    }

    // ---------- serializer ----------
    static void esc(String s, StringBuilder sb) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
    }

    static void ser(Object o, StringBuilder sb) {
        if (o == null) { sb.append("null"); return; }
        if (o instanceof String) { esc((String) o, sb); return; }
        if (o instanceof Boolean) { sb.append(o); return; }
        if (o instanceof Long || o instanceof Integer) { sb.append(o); return; }
        if (o instanceof Map) {
            sb.append('{');
            boolean first = true;
            for (Map.Entry<?,?> e : ((Map<?,?>) o).entrySet()) {
                if (!first) sb.append(',');
                first = false;
                esc((String) e.getKey(), sb);
                sb.append(':');
                ser(e.getValue(), sb);
            }
            sb.append('}');
            return;
        }
        if (o instanceof List) {
            sb.append('[');
            boolean first = true;
            for (Object x : (List<?>) o) {
                if (!first) sb.append(',');
                first = false;
                ser(x, sb);
            }
            sb.append(']');
            return;
        }
        throw new RuntimeException("cannot serialize");
    }

    static String ser(Object o) { StringBuilder sb = new StringBuilder(); ser(o, sb); return sb.toString(); }

    // ---------- helpers ----------
    static boolean isInt(Object o) { return o instanceof Long; }
    static boolean isValidId(Object o) { return o instanceof String || o instanceof Long; }

    static Map<String,Object> resp(Object id, Object result) {
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("jsonrpc", "2.0");
        m.put("id", id);
        m.put("result", result);
        return m;
    }

    static Map<String,Object> errResp(Object id, int code, String msg) {
        Map<String,Object> e = new LinkedHashMap<>();
        e.put("code", (long) code);
        e.put("message", msg);
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("jsonrpc", "2.0");
        m.put("id", id);
        m.put("error", e);
        return m;
    }

    static Map<String,Object> toolFail(String msg) {
        Map<String,Object> content = new LinkedHashMap<>();
        content.put("type", "text");
        content.put("text", msg);
        List<Object> cl = new ArrayList<>();
        cl.add(content);
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("content", cl);
        r.put("isError", Boolean.TRUE);
        return r;
    }

    static Map<String,Object> toolOkText(String text) {
        Map<String,Object> content = new LinkedHashMap<>();
        content.put("type", "text");
        content.put("text", text);
        List<Object> cl = new ArrayList<>();
        cl.add(content);
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("content", cl);
        r.put("isError", Boolean.FALSE);
        return r;
    }

    static Map<String,Object> toolOkStructured(Map<String,Object> s) {
        Map<String,Object> content = new LinkedHashMap<>();
        content.put("type", "text");
        content.put("text", ser(s));
        List<Object> cl = new ArrayList<>();
        cl.add(content);
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("content", cl);
        r.put("structuredContent", s);
        r.put("isError", Boolean.FALSE);
        return r;
    }

    static int cmpByCodePoint(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int ca = a.codePointAt(i), cb = b.codePointAt(j);
            if (ca != cb) return ca - cb;
            i += Character.charCount(ca);
            j += Character.charCount(cb);
        }
        return (a.length() - i) - (b.length() - j);
    }

    // ---------- tool schemas ----------
    static Map<String,Object> prop(String type) {
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("type", type);
        return m;
    }

    static Map<String,Object> schema(Map<String,Object> properties, List<String> required) {
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("type", "object");
        m.put("properties", properties);
        if (required != null) m.put("required", required);
        m.put("additionalProperties", Boolean.FALSE);
        return m;
    }

    static Map<String,Object> tool(String name, String title, String desc,
                                   Map<String,Object> inputSchema, Map<String,Object> outputSchema,
                                   Map<String,Object> annotations) {
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("name", name);
        m.put("title", title);
        m.put("description", desc);
        m.put("inputSchema", inputSchema);
        if (outputSchema != null) m.put("outputSchema", outputSchema);
        if (annotations != null) m.put("annotations", annotations);
        return m;
    }

    static List<Object> buildTools() {
        List<Object> tools = new ArrayList<>();

        // kv_set
        Map<String,Object> kvSetProps = new LinkedHashMap<>();
        Map<String,Object> keyP = prop("string"); keyP.put("minLength", 1L);
        kvSetProps.put("key", keyP);
        kvSetProps.put("value", prop("string"));
        tools.add(tool("kv_set", "Set a value",
                "Store a string value under a key, replacing any previous value.",
                schema(kvSetProps, Arrays.asList("key", "value")), null, null));

        // kv_get
        Map<String,Object> kvGetProps = new LinkedHashMap<>();
        Map<String,Object> keyP2 = prop("string"); keyP2.put("minLength", 1L);
        kvGetProps.put("key", keyP2);
        tools.add(tool("kv_get", "Get a value",
                "Return the value stored under a key.",
                schema(kvGetProps, Arrays.asList("key")), null, null));

        // kv_list
        Map<String,Object> kvListProps = new LinkedHashMap<>();
        kvListProps.put("prefix", prop("string"));
        Map<String,Object> outProps = new LinkedHashMap<>();
        Map<String,Object> keysArr = new LinkedHashMap<>();
        keysArr.put("type", "array");
        keysArr.put("items", prop("string"));
        outProps.put("keys", keysArr);
        outProps.put("count", prop("integer"));
        Map<String,Object> kvListOut = new LinkedHashMap<>();
        kvListOut.put("type", "object");
        kvListOut.put("properties", outProps);
        kvListOut.put("required", Arrays.asList("keys", "count"));
        tools.add(tool("kv_list", "List keys",
                "List the stored keys that start with a prefix, sorted by Unicode code point.",
                schema(kvListProps, null), kvListOut, null));

        // sum
        Map<String,Object> sumProps = new LinkedHashMap<>();
        Map<String,Object> numbers = new LinkedHashMap<>();
        numbers.put("type", "array");
        numbers.put("items", prop("integer"));
        numbers.put("minItems", 1L);
        sumProps.put("numbers", numbers);
        Map<String,Object> sumOutProps = new LinkedHashMap<>();
        sumOutProps.put("sum", prop("integer"));
        sumOutProps.put("count", prop("integer"));
        Map<String,Object> sumOut = new LinkedHashMap<>();
        sumOut.put("type", "object");
        sumOut.put("properties", sumOutProps);
        sumOut.put("required", Arrays.asList("sum", "count"));
        Map<String,Object> sumAnn = new LinkedHashMap<>();
        sumAnn.put("readOnlyHint", Boolean.TRUE);
        sumAnn.put("idempotentHint", Boolean.TRUE);
        tools.add(tool("sum", "Sum integers",
                "Add up a non-empty list of integers.",
                schema(sumProps, Arrays.asList("numbers")), sumOut, sumAnn));

        // text_stats
        Map<String,Object> tsProps = new LinkedHashMap<>();
        tsProps.put("text", prop("string"));
        Map<String,Object> tsOutProps = new LinkedHashMap<>();
        tsOutProps.put("words", prop("integer"));
        tsOutProps.put("codepoints", prop("integer"));
        tsOutProps.put("utf8_bytes", prop("integer"));
        Map<String,Object> tsOut = new LinkedHashMap<>();
        tsOut.put("type", "object");
        tsOut.put("properties", tsOutProps);
        tsOut.put("required", Arrays.asList("words", "codepoints", "utf8_bytes"));
        Map<String,Object> tsAnn = new LinkedHashMap<>();
        tsAnn.put("readOnlyHint", Boolean.TRUE);
        tools.add(tool("text_stats", "Text statistics",
                "Count the words, Unicode code points and UTF-8 bytes of a text.",
                schema(tsProps, Arrays.asList("text")), tsOut, tsAnn));

        return tools;
    }

    static final Set<String> TOOL_NAMES = new HashSet<>(Arrays.asList("kv_set","kv_get","kv_list","sum","text_stats"));

    // per-tool: allowed arg names and property order
    static Map<String,List<String>> argOrder = new HashMap<>();
    static Map<String,Map<String,String[]>> argSpec = new HashMap<>(); // name -> [type, minLength/minItems flag]

    static void initSpecs() {
        argOrder.put("kv_set", Arrays.asList("key","value"));
        argOrder.put("kv_get", Arrays.asList("key"));
        argOrder.put("kv_list", Arrays.asList("prefix"));
        argOrder.put("sum", Arrays.asList("numbers"));
        argOrder.put("text_stats", Arrays.asList("text"));

        argSpec.put("kv_set", new HashMap<>());
        argSpec.get("kv_set").put("key", new String[]{"string","min1"});
        argSpec.get("kv_set").put("value", new String[]{"string",null});

        argSpec.put("kv_get", new HashMap<>());
        argSpec.get("kv_get").put("key", new String[]{"string","min1"});

        argSpec.put("kv_list", new HashMap<>());
        argSpec.get("kv_list").put("prefix", new String[]{"string",null});

        argSpec.put("sum", new HashMap<>());
        argSpec.get("sum").put("numbers", new String[]{"intarray","min1"});

        argSpec.put("text_stats", new HashMap<>());
        argSpec.get("text_stats").put("text", new String[]{"string",null});
    }

    static Map<String,String> kv = new HashMap<>();
    static boolean initialized = false;

    static Object handleRequest(String method, Map<String,Object> params) {
        switch (method) {
            case "initialize": {
                if (initialized) return errResp(null, -32600, "Already initialized"); // id filled by caller
                if (params == null || !(params.get("protocolVersion") instanceof String))
                    return errResp(null, -32602, "Invalid params");
                String pv = (String) params.get("protocolVersion");
                String version = pv;
                if (!(pv.equals("2025-06-18") || pv.equals("2025-03-26") || pv.equals("2024-11-05")))
                    version = "2025-06-18";
                initialized = true;
                Map<String,Object> caps = new LinkedHashMap<>();
                Map<String,Object> toolsCap = new LinkedHashMap<>();
                toolsCap.put("listChanged", Boolean.FALSE);
                caps.put("tools", toolsCap);
                Map<String,Object> serverInfo = new LinkedHashMap<>();
                serverInfo.put("name", "cb2-kv");
                serverInfo.put("title", "CB2 key-value server");
                serverInfo.put("version", "1.4.2");
                Map<String,Object> r = new LinkedHashMap<>();
                r.put("protocolVersion", version);
                r.put("capabilities", caps);
                r.put("serverInfo", serverInfo);
                return r;
            }
            case "ping": return new LinkedHashMap<>();
            case "tools/list": {
                Map<String,Object> r = new LinkedHashMap<>();
                r.put("tools", buildTools());
                return r;
            }
            case "tools/call": return handleToolsCall(params);
        }
        return null;
    }

    static Object handleToolsCall(Map<String,Object> params) {
        Object nameO = params.get("name");
        if (!(nameO instanceof String)) return errResp(null, -32602, "Invalid params");
        String name = (String) nameO;
        if (!TOOL_NAMES.contains(name)) return errResp(null, -32602, "Unknown tool: " + name);

        Object argsO = params.get("arguments");
        Map<String,Object> args;
        if (argsO == null && !params.containsKey("arguments")) {
            args = new LinkedHashMap<>();
        } else if (argsO instanceof Map) {
            args = (Map<String,Object>) argsO;
        } else {
            return toolFail("arguments must be an object");
        }

        List<String> order = argOrder.get(name);
        Set<String> allowed = new HashSet<>(order);
        String bestUnknown = null;
        for (String k : args.keySet()) {
            if (!allowed.contains(k)) {
                if (bestUnknown == null || cmpByCodePoint(k, bestUnknown) < 0) bestUnknown = k;
            }
        }
        if (bestUnknown != null) return toolFail("unknown argument: " + bestUnknown);

        Set<String> required;
        switch (name) {
            case "kv_set": required = new HashSet<>(Arrays.asList("key","value")); break;
            case "kv_get": required = new HashSet<>(Arrays.asList("key")); break;
            case "sum": required = new HashSet<>(Arrays.asList("numbers")); break;
            case "text_stats": required = new HashSet<>(Arrays.asList("text")); break;
            default: required = new HashSet<>();
        }

        for (String prop : order) {
            String[] spec = argSpec.get(name).get(prop);
            boolean present = args.containsKey(prop);
            if (!present) {
                if (required.contains(prop)) return toolFail("missing required argument: " + prop);
                continue;
            }
            Object v = args.get(prop);
            if (spec[0].equals("string")) {
                if (!(v instanceof String)) return toolFail("argument " + prop + " must be a string");
                if (spec[1] != null && ((String) v).isEmpty()) return toolFail("argument " + prop + " must not be empty");
            } else {
                if (!(v instanceof List)) return toolFail("argument " + prop + " must be an array of integers");
                for (Object el : (List<?>) v) {
                    if (!isInt(el)) return toolFail("argument " + prop + " must be an array of integers");
                }
                if (spec[1] != null && ((List<?>) v).isEmpty()) return toolFail("argument " + prop + " must not be empty");
            }
        }

        switch (name) {
            case "kv_set": {
                String key = (String) args.get("key");
                String value = (String) args.get("value");
                boolean existed = kv.containsKey(key);
                kv.put(key, value);
                return toolOkText((existed ? "updated " : "created ") + key);
            }
            case "kv_get": {
                String key = (String) args.get("key");
                if (!kv.containsKey(key)) return toolFail("key not found: " + key);
                return toolOkText(kv.get(key));
            }
            case "kv_list": {
                String prefix = args.containsKey("prefix") ? (String) args.get("prefix") : "";
                List<String> keys = new ArrayList<>();
                for (String k : kv.keySet()) if (k.startsWith(prefix)) keys.add(k);
                keys.sort(Main::cmpByCodePoint);
                Map<String,Object> s = new LinkedHashMap<>();
                s.put("keys", keys);
                s.put("count", (long) keys.size());
                return toolOkStructured(s);
            }
            case "sum": {
                List<Object> nums = (List<Object>) args.get("numbers");
                long sum = 0;
                for (Object o : nums) sum += (Long) o;
                Map<String,Object> s = new LinkedHashMap<>();
                s.put("sum", sum);
                s.put("count", (long) nums.size());
                return toolOkStructured(s);
            }
            case "text_stats": {
                String text = (String) args.get("text");
                long words = 0;
                boolean inWord = false;
                for (int i = 0; i < text.length(); ) {
                    int cp = text.codePointAt(i);
                    boolean sep = (cp == ' ' || cp == '\t' || cp == '\n' || cp == '\r');
                    if (!sep && !inWord) words++;
                    inWord = !sep;
                    i += Character.charCount(cp);
                }
                long cps = text.codePointCount(0, text.length());
                long bytes = text.getBytes(StandardCharsets.UTF_8).length;
                Map<String,Object> s = new LinkedHashMap<>();
                s.put("words", words);
                s.put("codepoints", cps);
                s.put("utf8_bytes", bytes);
                return toolOkStructured(s);
            }
        }
        return null; // unreachable
    }

    static Object process(Map<String,Object> obj) {
        boolean hasMethod = obj.containsKey("method");
        boolean hasResult = obj.containsKey("result");
        boolean hasError = obj.containsKey("error");

        if (!hasMethod && (hasResult || hasError)) return null; // client response, ignore

        // validate request shape
        boolean invalid = false;
        if (!"2.0".equals(obj.get("jsonrpc"))) invalid = true;
        if (!(obj.get("method") instanceof String)) invalid = true;
        Object id = obj.get("id");
        boolean hasId = obj.containsKey("id");
        if (hasId && !isValidId(id)) invalid = true;

        if (invalid) {
            Object echoId = (hasId && isValidId(id)) ? id : null;
            return errResp(echoId, -32600, "Invalid Request");
        }

        if (!hasId) return null; // notification

        String method = (String) obj.get("method");
        Object paramsO = obj.get("params");
        Map<String,Object> params = null;
        boolean hasParams = obj.containsKey("params");
        if (hasParams && paramsO instanceof Map) params = (Map<String,Object>) paramsO;

        Set<String> methods = new HashSet<>(Arrays.asList("initialize","ping","tools/list","tools/call"));
        if (!methods.contains(method)) return errResp(id, -32601, "Method not found");
        if (hasParams && !(paramsO instanceof Map)) return errResp(id, -32602, "Invalid params");
        if (!initialized && !(method.equals("initialize") || method.equals("ping")))
            return errResp(id, -32002, "Server not initialized");

        Object r = handleRequest(method, params);
        if (r instanceof Map && ((Map<?,?>) r).containsKey("error")) {
            Map<String,Object> e = (Map<String,Object>) ((Map<String,Object>) r).get("error");
            return errResp(id, (int) (long) (Long) e.get("code"), (String) e.get("message"));
        }
        return resp(id, r);
    }

    public static void main(String[] args) throws IOException {
        initSpecs();
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        StringBuilder out = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            String t = line.replaceAll("^[ \t\r]+|[ \t\r]+$", "");
            if (t.isEmpty()) continue;
            Object msg;
            try {
                msg = parse(line);
            } catch (Exception ex) {
                out.append(ser(errResp(null, -32700, "Parse error"))).append('\n');
                continue;
            }
            if (!(msg instanceof Map)) {
                out.append(ser(errResp(null, -32600, "Invalid Request"))).append('\n');
                continue;
            }
            Object resp = process((Map<String,Object>) msg);
            if (resp != null) out.append(ser(resp)).append('\n');
        }
        System.out.print(out);
        System.exit(0);
    }
}

import Foundation

var initialized = false
