func esc(_ s: String) -> String {
    var r = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if c.value < 0x20 { r += String(format: "\\u%04x", c.value) }
            else { r.unicodeScalars.append(c) }
        }
    }
    return r + "\""
}

func ser(_ o: Any) -> String {
    if let n = o as? NSNumber {
        if CFGetTypeID(n) == CFBooleanGetTypeID() { return n.boolValue ? "true" : "false" }
        let t = String(cString: n.objCType)
        if ["q", "i", "l", "s", "I", "L", "Q", "S"].contains(t) { return String(n.int64Value) }
        let d = n.doubleValue
        if d == d.rounded() && abs(d) < 1e15 { return String(format: "%.1f", d) }
        return "\(d)"
    }
    if let s = o as? NSString { return esc(s as String) }
    if let a = o as? [Any] { return "[" + a.map { ser($0) }.joined(separator: ",") + "]" }
    if let d = o as? [String: Any] {
        return "{" + d.map { esc($0.key) + ":" + ser($0.value) }.joined(separator: ",") + "}"
    }
    return "null"
}

func isIntNum(_ o: Any) -> Bool {
    guard let n = o as? NSNumber else { return false }
    if CFGetTypeID(n) == CFBooleanGetTypeID() { return false }
    let t = String(cString: n.objCType)
    return ["q", "i", "l", "s"].contains(t)
}

func isValidID(_ o: Any) -> Bool {
    if o is NSString { return true }
    return isIntNum(o)
}

func lexLess(_ a: String, _ b: String) -> Bool {
    Array(a.unicodeScalars).lexicographicallyPrecedes(Array(b.unicodeScalars))
}

func errResp(_ id: Any?, _ code: Int, _ msg: String) -> String {
    ser(["jsonrpc": "2.0", "id": id ?? NSNull(), "error": ["code": NSNumber(value: code), "message": msg]])
}

let toolsJSON = #"""
