 {"name":"kv_set","title":"Set a value","description":"Store a string value under a key, replacing any previous value.",
  "inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1},"value":{"type":"string"}},"required":["key","value"],"additionalProperties":false}},
 {"name":"kv_get","title":"Get a value","description":"Return the value stored under a key.",
  "inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1}},"required":["key"],"additionalProperties":false}},
 {"name":"kv_list","title":"List keys","description":"List the stored keys that start with a prefix, sorted by Unicode code point.",
  "inputSchema":{"type":"object","properties":{"prefix":{"type":"string"}},"additionalProperties":false},
  "outputSchema":{"type":"object","properties":{"keys":{"type":"array","items":{"type":"string"}},"count":{"type":"integer"}},"required":["keys","count"]}},
 {"name":"sum","title":"Sum integers","description":"Add up a non-empty list of integers.",
  "inputSchema":{"type":"object","properties":{"numbers":{"type":"array","items":{"type":"integer"},"minItems":1}},"required":["numbers"],"additionalProperties":false},
  "outputSchema":{"type":"object","properties":{"sum":{"type":"integer"},"count":{"type":"integer"}},"required":["sum","count"]},
  "annotations":{"readOnlyHint":true,"idempotentHint":true}},
 {"name":"text_stats","title":"Text statistics","description":"Count the words, Unicode code points and UTF-8 bytes of a text.",
  "inputSchema":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"],"additionalProperties":false},
  "outputSchema":{"type":"object","properties":{"words":{"type":"integer"},"codepoints":{"type":"integer"},"utf8_bytes":{"type":"integer"}},"required":["words","codepoints","utf8_bytes"]},
  "annotations":{"readOnlyHint":true}}
]
"""#

let toolsData = toolsJSON.data(using: .utf8)!
let toolsArr = (try! JSONSerialization.jsonObject(with: toolsData, options: [.fragmentsAllowed])) as! [Any]

struct ToolSpec {
    let name: String
    let props: [(String, Kind)]
    let required: Set<String>
    let allowed: Set<String>
    enum Kind { case string(minLen1: Bool), intArray(minItems1: Bool) }
}

let specs: [ToolSpec] = [
    ToolSpec(name: "kv_set", props: [("key", .string(minLen1: true)), ("value", .string(minLen1: false))], required: ["key", "value"], allowed: ["key", "value"]),
    ToolSpec(name: "kv_get", props: [("key", .string(minLen1: true))], required: ["key"], allowed: ["key"]),
    ToolSpec(name: "kv_list", props: [("prefix", .string(minLen1: false))], required: [], allowed: ["prefix"]),
    ToolSpec(name: "sum", props: [("numbers", .intArray(minItems1: true))], required: ["numbers"], allowed: ["numbers"]),
    ToolSpec(name: "text_stats", props: [("text", .string(minLen1: false))], required: ["text"], allowed: ["text"]),
]

func textResult(_ text: String, isError: Bool) -> [String: Any] {
    return ["content": [["type": "text", "text": text]], "isError": isError]
}

func handle(_ obj: Any) -> String? {
    guard let dict = obj as? [String: Any] else {
        return errResp(nil, -32600, "Invalid Request")
    }
    if dict["method"] == nil && (dict["result"] != nil || dict["error"] != nil) {
        return nil
    }
    let jsonrpcOK = (dict["jsonrpc"] as? String) == "2.0"
    let methodOK = dict["method"] is String
    let idPresent = dict["id"] != nil
    let idValid = idPresent ? isValidID(dict["id"]!) : false
    if !jsonrpcOK || !methodOK || (idPresent && !idValid) {
        return errResp(idValid ? dict["id"]! : nil, -32600, "Invalid Request")
    }
    if !idPresent { return nil }

    let id = dict["id"]!
    let method = dict["method"] as! String

    let known = ["initialize", "ping", "tools/list", "tools/call"]
    if !known.contains(method) { return errResp(id, -32601, "Method not found") }

    var params: [String: Any] = [:]
    if let p = dict["params"] {
        guard let pd = p as? [String: Any] else { return errResp(id, -32602, "Invalid params") }
        params = pd
    }

    if !initialized && method != "initialize" && method != "ping" {
        return errResp(id, -32002, "Server not initialized")
    }

    switch method {
    case "initialize":
        if initialized { return errResp(id, -32600, "Already initialized") }
        guard let pv = params["protocolVersion"] as? String else {
            return errResp(id, -32602, "Invalid params")
        }
        initialized = true
        let version = ["2025-06-18", "2025-03-26", "2024-11-05"].contains(pv) ? pv : "2025-06-18"
        return ser(["jsonrpc": "2.0", "id": id, "result": [
            "protocolVersion": version,
            "capabilities": ["tools": ["listChanged": false]],
            "serverInfo": ["name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"]
        ]])
    case "ping":
        return ser(["jsonrpc": "2.0", "id": id, "result": [String: Any]()])
    case "tools/list":
        return ser(["jsonrpc": "2.0", "id": id, "result": ["tools": toolsArr]])
    case "tools/call":
        guard let name = params["name"] as? String else {
            return errResp(id, -32602, "Invalid params")
        }
        guard let spec = specs.first(where: { $0.name == name }) else {
            return errResp(id, -32602, "Unknown tool: \(name)")
        }
        var args: [String: Any] = [:]
        if let a = params["arguments"] {
            guard let ad = a as? [String: Any] else {
                return ser(["jsonrpc": "2.0", "id": id, "result": textResult("arguments must be an object", isError: true)])
            }
            args = ad
        }
        let unknown = args.keys.filter { !spec.allowed.contains($0) }
        if let u = unknown.min(by: { lexLess($0, $1) }) {
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult("unknown argument: \(u)", isError: true)])
        }
        for (pname, kind) in spec.props {
            guard let v = args[pname] else {
                if spec.required.contains(pname) {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("missing required argument: \(pname)", isError: true)])
                }
                continue
            }
            switch kind {
            case .string(let minLen1):
                guard let s = v as? String else {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must be a string", isError: true)])
                }
                if minLen1 && s.isEmpty {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must not be empty", isError: true)])
                }
            case .intArray(let minItems1):
                guard let arr = v as? [Any], arr.allSatisfy(isIntNum) else {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must be an array of integers", isError: true)])
                }
                if minItems1 && arr.isEmpty {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must not be empty", isError: true)])
                }
            }
        }
        switch name {
        case "kv_set":
            let key = args["key"] as! String
            let value = args["value"] as! String
            let existed = kv[key] != nil
            kv[key] = value
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult("\(existed ? "updated" : "created") \(key)", isError: false)])
        case "kv_get":
            let key = args["key"] as! String
            guard let v = kv[key] else {
                return ser(["jsonrpc": "2.0", "id": id, "result": textResult("key not found: \(key)", isError: true)])
            }
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult(v, isError: false)])
        case "kv_list":
            let prefix = (args["prefix"] as? String) ?? ""
            let keys = kv.keys.filter { $0.hasPrefix(prefix) }.sorted { lexLess($0, $1) }
            let s: [String: Any] = ["keys": keys, "count": NSNumber(value: keys.count)]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        case "sum":
            let nums = (args["numbers"] as! [Any]).map { ($0 as! NSNumber).int64Value }
            let total = nums.reduce(0, +)
            let s: [String: Any] = ["sum": NSNumber(value: total), "count": NSNumber(value: nums.count)]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        case "text_stats":
            let text = args["text"] as! String
            let words = text.split(omittingEmptySubsequences: true, whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" || $0 == "\r" }).count
            let s: [String: Any] = [
                "words": NSNumber(value: words),
                "codepoints": NSNumber(value: text.count),
                "utf8_bytes": NSNumber(value: text.utf8.count)
            ]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        default:
            return nil
        }
    default:
        return nil
    }
}

let inputData = FileHandle.standardInput.readDataToEndOfFile()
let input = String(data: inputData, encoding: .utf8) ?? ""
var outLines: [String] = []
for rawLine in input.split(separator: "\n", omittingEmptySubsequences: false) {
    var line = String(rawLine)
    if line.hasSuffix("\r") { line.removeLast() }
    if line.trimmingCharacters(in: CharacterSet(charactersIn: " \t\r")).isEmpty { continue }
    var parsed: Any?
    do {
        parsed = try JSONSerialization.jsonObject(with: line.data(using: .utf8)!, options: [.fragmentsAllowed])
    } catch {
        parsed = nil
    }
    if parsed == nil {
        outLines.append(errResp(nil, -32700, "Parse error"))
        continue
    }
    if let resp = handle(parsed!) {
        outLines.append(resp)
    }
}
let data = outLines.joined(separator: "\n")
if !outLines.isEmpty {
    FileHandle.standardOutput.write((data + "\n").data(using: .utf8)!)
}
exit(0)

