let toolsData = toolsJSON.data(using: .utf8)!
let toolsArr = (try! JSONSerialization.jsonObject(with: toolsData, options: [.fragmentsAllowed])) as! [Any]

struct ToolSpec {
    let name: String
    let props: [(String, Kind)]
    let required: Set<String>
    let allowed: Set<String>
    enum Kind { case string(minLen1: Bool), intArray(minItems1: Bool) }
}

let specs: [ToolSpec] = [
    ToolSpec(name: "kv_set", props: [("key", .string(minLen1: true)), ("value", .string(minLen1: false))], required: ["key", "value"], allowed: ["key", "value"]),
    ToolSpec(name: "kv_get", props: [("key", .string(minLen1: true))], required: ["key"], allowed: ["key"]),
    ToolSpec(name: "kv_list", props: [("prefix", .string(minLen1: false))], required: [], allowed: ["prefix"]),
    ToolSpec(name: "sum", props: [("numbers", .intArray(minItems1: true))], required: ["numbers"], allowed: ["numbers"]),
    ToolSpec(name: "text_stats", props: [("text", .string(minLen1: false))], required: ["text"], allowed: ["text"]),
]

func textResult(_ text: String, isError: Bool) -> [String: Any] {
    return ["content": [["type": "text", "text": text]], "isError": isError]
}

func handle(_ obj: Any) -> String? {
    guard let dict = obj as? [String: Any] else {
        return errResp(nil, -32600, "Invalid Request")
    }
    if dict["method"] == nil && (dict["result"] != nil || dict["error"] != nil) {
        return nil
    }
    let jsonrpcOK = (dict["jsonrpc"] as? String) == "2.0"
    let methodOK = dict["method"] is String
    let idPresent = dict["id"] != nil
    let idValid = idPresent ? isValidID(dict["id"]!) : false
    if !jsonrpcOK || !methodOK || (idPresent && !idValid) {
        return errResp(idValid ? dict["id"]! : nil, -32600, "Invalid Request")
    }
    if !idPresent { return nil }

    let id = dict["id"]!
    let method = dict["method"] as! String

    let known = ["initialize", "ping", "tools/list", "tools/call"]
    if !known.contains(method) { return errResp(id, -32601, "Method not found") }

    var params: [String: Any] = [:]
    if let p = dict["params"] {
        guard let pd = p as? [String: Any] else { return errResp(id, -32602, "Invalid params") }
        params = pd
    }

    if !initialized && method != "initialize" && method != "ping" {
        return errResp(id, -32002, "Server not initialized")
    }

    switch method {
    case "initialize":
        if initialized { return errResp(id, -32600, "Already initialized") }
        guard let pv = params["protocolVersion"] as? String else {
            return errResp(id, -32602, "Invalid params")
        }
        initialized = true
        let version = ["2025-06-18", "2025-03-26", "2024-11-05"].contains(pv) ? pv : "2025-06-18"
        return ser(["jsonrpc": "2.0", "id": id, "result": [
            "protocolVersion": version,
            "capabilities": ["tools": ["listChanged": false]],
            "serverInfo": ["name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"]
        ]])
    case "ping":
        return ser(["jsonrpc": "2.0", "id": id, "result": [String: Any]()])
    case "tools/list":
        return ser(["jsonrpc": "2.0", "id": id, "result": ["tools": toolsArr]])
    case "tools/call":
        guard let name = params["name"] as? String else {
            return errResp(id, -32602, "Invalid params")
        }
        guard let spec = specs.first(where: { $0.name == name }) else {
            return errResp(id, -32602, "Unknown tool: \(name)")
        }
        var args: [String: Any] = [:]
        if let a = params["arguments"] {
            guard let ad = a as? [String: Any] else {
                return ser(["jsonrpc": "2.0", "id": id, "result": textResult("arguments must be an object", isError: true)])
            }
            args = ad
        }
        let unknown = args.keys.filter { !spec.allowed.contains($0) }
        if let u = unknown.min(by: { lexLess($0, $1) }) {
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult("unknown argument: \(u)", isError: true)])
        }
        for (pname, kind) in spec.props {
            guard let v = args[pname] else {
                if spec.required.contains(pname) {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("missing required argument: \(pname)", isError: true)])
                }
                continue
            }
            switch kind {
            case .string(let minLen1):
                guard let s = v as? String else {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must be a string", isError: true)])
                }
                if minLen1 && s.isEmpty {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must not be empty", isError: true)])
                }
            case .intArray(let minItems1):
                guard let arr = v as? [Any], arr.allSatisfy(isIntNum) else {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must be an array of integers", isError: true)])
                }
                if minItems1 && arr.isEmpty {
                    return ser(["jsonrpc": "2.0", "id": id, "result": textResult("argument \(pname) must not be empty", isError: true)])
                }
            }
        }
        switch name {
        case "kv_set":
            let key = args["key"] as! String
            let value = args["value"] as! String
            let existed = kv[key] != nil
            kv[key] = value
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult("\(existed ? "updated" : "created") \(key)", isError: false)])
        case "kv_get":
            let key = args["key"] as! String
            guard let v = kv[key] else {
                return ser(["jsonrpc": "2.0", "id": id, "result": textResult("key not found: \(key)", isError: true)])
            }
            return ser(["jsonrpc": "2.0", "id": id, "result": textResult(v, isError: false)])
        case "kv_list":
            let prefix = (args["prefix"] as? String) ?? ""
            let keys = kv.keys.filter { $0.hasPrefix(prefix) }.sorted { lexLess($0, $1) }
            let s: [String: Any] = ["keys": keys, "count": NSNumber(value: keys.count)]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        case "sum":
            let nums = (args["numbers"] as! [Any]).map { ($0 as! NSNumber).int64Value }
            let total = nums.reduce(0, +)
            let s: [String: Any] = ["sum": NSNumber(value: total), "count": NSNumber(value: nums.count)]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        case "text_stats":
            let text = args["text"] as! String
            let words = text.split(omittingEmptySubsequences: true, whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" || $0 == "\r" }).count
            let s: [String: Any] = [
                "words": NSNumber(value: words),
                "codepoints": NSNumber(value: text.unicodeScalars.count),
                "utf8_bytes": NSNumber(value: text.utf8.count)
            ]
            return ser(["jsonrpc": "2.0", "id": id, "result": [
                "content": [["type": "text", "text": ser(s)]],
                "structuredContent": s,
                "isError": false
            ]])
        default:
            return nil
        }
    default:
        return nil
    }
}

let inputData = FileHandle.standardInput.readDataToEndOfFile()
let input = String(data: inputData, encoding: .utf8) ?? ""
var outLines: [String] = []
for rawLine in input.split(separator: "\n", omittingEmptySubsequences: false) {
    var line = String(rawLine)
    if line.hasSuffix("\r") { line.removeLast() }
    if line.trimmingCharacters(in: CharacterSet(charactersIn: " \t\r")).isEmpty { continue }
    var parsed: Any?
    do {
        parsed = try JSONSerialization.jsonObject(with: line.data(using: .utf8)!, options: [.fragmentsAllowed])
    } catch {
        parsed = nil
    }
    if parsed == nil {
        outLines.append(errResp(nil, -32700, "Parse error"))
        continue
    }
    if let resp = handle(parsed!) {
        outLines.append(resp)
    }
}
let data = outLines.joined(separator: "\n")
if !outLines.isEmpty {
    FileHandle.standardOutput.write((data + "\n").data(using: .utf8)!)
}
exit(0)

use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

#[derive(Clone, Debug)]
enum Value {
    Null,
    Bool(bool),
    Num(f64, bool), // bool: is integer (no '.' or exponent)
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

impl Value {
    fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Obj(m) => m.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn is_int(&self) -> bool {
        matches!(self, Value::Num(_, true))
    }
}

struct P<'a> {
    c: &'a [char],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.c.len()
            && matches!(self.c[self.i], ' ' | '\t' | '\n' | '\r')
        {
            self.i += 1;
        }
    }
    fn peek(&self) -> Option<char> {
        self.c.get(self.i).copied()
    }
    fn string(&mut self) -> Result<String, ()> {
        // assumes current char is '"'
        self.i += 1;
        let mut s = String::new();
        loop {
            let ch = self.peek().ok_or(())?;
            self.i += 1;
            match ch {
                '"' => return Ok(s),
                '\\' => {
                    let e = self.peek().ok_or(())?;
                    self.i += 1;
                    match e {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'b' => s.push('\u{0008}'),
                        'f' => s.push('\u{000C}'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        'u' => {
                            let hi = self.hex4()?;
                            let cp = if (0xD800..=0xDBFF).contains(&hi) {
                                if self.peek() != Some('\\') {
                                    return Err(());
                                }
                                self.i += 1;
                                if self.peek() != Some('u') {
                                    return Err(());
                                }
                                self.i += 1;
                                let lo = self.hex4()?;
                                if !(0xDC00..=0xDFFF).contains(&lo) {
                                    return Err(());
                                }
                                0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                            } else {
                                hi
                            };
                            s.push(char::from_u32(cp).ok_or(())?);
                        }
                        _ => return Err(()),
                    }
                }
                c if (c as u32) < 0x20 => return Err(()),
                c => s.push(c),
            }
        }
    }
    fn hex4(&mut self) -> Result<u32, ()> {
        let mut v = 0u32;
        for _ in 0..4 {
            let ch = self.peek().ok_or(())?;
            self.i += 1;
            let d = ch.to_digit(16).ok_or(())?;
            v = v * 16 + d;
        }
        Ok(v)
    }
    fn number(&mut self) -> Result<Value, ()> {
        let start = self.i;
        let mut is_int = true;
        if self.peek() == Some('-') {
            self.i += 1;
        }
        match self.peek() {
            Some('0') => {
                self.i += 1;
                if let Some(d) = self.peek() {
                    if d.is_ascii_digit() {
                        return Err(());
                    }
                }
            }
            Some(d) if d.is_ascii_digit() => {
                while matches!(self.peek(), Some(d) if d.is_ascii_digit()) {
                    self.i += 1;
                }
            }
            _ => return Err(()),
        }
        if self.peek() == Some('.') {
            is_int = false;
            self.i += 1;
            if !matches!(self.peek(), Some(d) if d.is_ascii_digit()) {
                return Err(());
            }
            while matches!(self.peek(), Some(d) if d.is_ascii_digit()) {
                self.i += 1;
            }
        }
        if matches!(self.peek(), Some('e') | Some('E')) {
            is_int = false;
            self.i += 1;
            if matches!(self.peek(), Some('+') | Some('-')) {
                self.i += 1;
            }
            if !matches!(self.peek(), Some(d) if d.is_ascii_digit()) {
                return Err(());
            }
            while matches!(self.peek(), Some(d) if d.is_ascii_digit()) {
                self.i += 1;
            }
        }
        let txt: String = self.c[start..self.i].iter().collect();
        let f: f64 = txt.parse().map_err(|_| ())?;
        Ok(Value::Num(f, is_int))
    }
    fn value(&mut self) -> Result<Value, ()> {
        match self.peek().ok_or(())? {
            '{' => {
                self.i += 1;
                let mut m = Vec::new();
                self.ws();
                if self.peek() == Some('}') {
                    self.i += 1;
                    return Ok(Value::Obj(m));
                }
                loop {
                    self.ws();
                    if self.peek() != Some('"') {
                        return Err(());
                    }
                    let k = self.string()?;
                    self.ws();
                    if self.peek() != Some(':') {
                        return Err(());
                    }
                    self.i += 1;
                    self.ws();
                    let v = self.value()?;
                    m.push((k, v));
                    self.ws();
                    match self.peek() {
                        Some(',') => self.i += 1,
                        Some('}') => {
                            self.i += 1;
                            return Ok(Value::Obj(m));
                        }
                        _ => return Err(()),
                    }
                }
            }
            '[' => {
                self.i += 1;
                let mut a = Vec::new();
                self.ws();
                if self.peek() == Some(']') {
                    self.i += 1;
                    return Ok(Value::Arr(a));
                }
                loop {
                    self.ws();
                    let v = self.value()?;
                    a.push(v);
                    self.ws();
                    match self.peek() {
                        Some(',') => self.i += 1,
                        Some(']') => {
                            self.i += 1;
                            return Ok(Value::Arr(a));
                        }
                        _ => return Err(()),
                    }
                }
            }
            '"' => self.string().map(Value::Str),
            't' => {
                if self.c[self.i..].starts_with(&['t', 'r', 'u', 'e']) {
                    self.i += 4;
                    Ok(Value::Bool(true))
                } else {
                    Err(())
                }
            }
            'f' => {
                if self.c[self.i..].starts_with(&['f', 'a', 'l', 's', 'e']) {
                    self.i += 5;
                    Ok(Value::Bool(false))
                } else {
                    Err(())
                }
            }
            'n' => {
                if self.c[self.i..].starts_with(&['n', 'u', 'l', 'l']) {
                    self.i += 4;
                    Ok(Value::Null)
                } else {
                    Err(())
                }
            }
            c if c == '-' || c.is_ascii_digit() => self.number(),
            _ => Err(()),
        }
    }
}

fn parse_line(line: &str) -> Result<Value, ()> {
    let c: Vec<char> = line.chars().collect();
    let mut p = P { c: &c, i: 0 };
    p.ws();
    let v = p.value()?;
    p.ws();
    if p.i != c.len() {
        return Err(());
    }
    Ok(v)
}

fn esc(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn to_json(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => if *b { "true" } else { "false" }.into(),
        Value::Num(f, is_int) => {
            if *is_int {
                format!("{}", *f as i64)
            } else {
                format!("{}", f)
            }
        }
        Value::Str(s) => esc(s),
        Value::Arr(a) => {
            let parts: Vec<String> = a.iter().map(to_json).collect();
            format!("[{}]", parts.join(","))
        }
        Value::Obj(m) => {
            let parts: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{}:{}", esc(k), to_json(v)))
                .collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn id_ser(v: &Value) -> String {
    match v {
        Value::Str(s) => esc(s),
        Value::Num(f, _) => format!("{}", *f as i64),
        _ => "null".into(),
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Str,
    IntArr,
}

struct Prop {
    name: &'static str,
    kind: Kind,
    required: bool,
    min1: bool,
}

const TOOLS_JSON: &str = r#"[{"name":"kv_set","title":"Set a value","description":"Store a string value under a key, replacing any previous value.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1},"value":{"type":"string"}},"required":["key","value"],"additionalProperties":false}},{"name":"kv_get","title":"Get a value","description":"Return the value stored under a key.","inputSchema":{"type":"object","properties":{"key":{"type":"string","minLength":1}},"required":["key"],"additionalProperties":false}},{"name":"kv_list","title":"List keys","description":"List the stored keys that start with a prefix, sorted by Unicode code point.","inputSchema":{"type":"object","properties":{"prefix":{"type":"string"}},"additionalProperties":false},"outputSchema":{"type":"object","properties":{"keys":{"type":"array","items":{"type":"string"}},"count":{"type":"integer"}},"required":["keys","count"]}},{"name":"sum","title":"Sum integers","description":"Add up a non-empty list of integers.","inputSchema":{"type":"object","properties":{"numbers":{"type":"array","items":{"type":"integer"},"minItems":1}},"required":["numbers"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"sum":{"type":"integer"},"count":{"type":"integer"}},"required":["sum","count"]},"annotations":{"readOnlyHint":true,"idempotentHint":true}},{"name":"text_stats","title":"Text statistics","description":"Count the words, Unicode code points and UTF-8 bytes of a text.","inputSchema":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"words":{"type":"integer"},"codepoints":{"type":"integer"},"utf8_bytes":{"type":"integer"}},"required":["words","codepoints","utf8_bytes"]},"annotations":{"readOnlyHint":true}}]"#;

fn result_resp(id: &str, body: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"result\":{}}}", id, body)
}

fn error_resp(id: &str, code: i32, msg: &str) -> String {
    format!(
        "{{\"jsonrpc\":\"2.0\",\"id\":{},\"error\":{{\"code\":{},\"message\":{}}}}}",
        id,
        code,
        esc(msg)
    )
}

fn text_result(text: &str) -> String {
    format!(
        "{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"isError\":false}}",
        esc(text)
    )
}

fn failure_result(msg: &str) -> String {
    format!(
        "{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"isError\":true}}",
        esc(msg)
    )
}

fn structured_result(s: &Value) -> String {
    let sj = to_json(s);
    format!(
        "{{\"content\":[{{\"type\":\"text\",\"text\":{}}}],\"structuredContent\":{},\"isError\":false}}",
        esc(&sj),
        sj
    )
}

fn validate_args(props: &[Prop], args: &Value) -> Result<(), String> {
    let pairs = match args {
        Value::Obj(m) => m,
        _ => return Err("arguments must be an object".into()),
    };
    let mut unknown: Vec<&str> = Vec::new();
    for (k, _) in pairs {
        if !props.iter().any(|p| p.name == k.as_str()) {
            unknown.push(k.as_str());
        }
    }
    if let Some(u) = unknown.iter().min() {
        return Err(format!("unknown argument: {}", u));
    }
    for p in props {
        match args.get(p.name) {
            None => {
                if p.required {
                    return Err(format!("missing required argument: {}", p.name));
                }
            }
            Some(Value::Str(s)) => {
                if p.kind != Kind::Str {
                    return Err(format!(
                        "argument {} must be an array of integers",
                        p.name
                    ));
                }
                if p.min1 && s.is_empty() {
                    return Err(format!("argument {} must not be empty", p.name));
                }
            }
            Some(Value::Arr(a)) => {
                if p.kind != Kind::IntArr {
                    return Err(format!("argument {} must be a string", p.name));
                }
                if a.iter().any(|e| !e.is_int()) {
                    return Err(format!(
                        "argument {} must be an array of integers",
                        p.name
                    ));
                }
                if p.min1 && a.is_empty() {
                    return Err(format!("argument {} must not be empty", p.name));
                }
            }
            Some(_) => {
                return Err(if p.kind == Kind::Str {
                    format!("argument {} must be a string", p.name)
                } else {
                    format!("argument {} must be an array of integers", p.name)
                })
            }
        }
    }
    Ok(())
}

enum ToolOut {
    Text(String),
    Structured(Value),
}

fn run_tool(
    name: &str,
    args: &Value,
    store: &mut BTreeMap<String, String>,
) -> Result<ToolOut, String> {
    match name {
        "kv_set" => {
            let key = match args.get("key") {
                Some(Value::Str(s)) => s.clone(),
                _ => unreachable!(),
            };
            let value = match args.get("value") {
                Some(Value::Str(s)) => s.clone(),
                _ => unreachable!(),
            };
            let existed = store.contains_key(&key);
            store.insert(key.clone(), value);
            Ok(ToolOut::Text(format!(
                "{} {}",
                if existed { "updated" } else { "created" },
                key
            )))
        }
        "kv_get" => {
            let key = match args.get("key") {
                Some(Value::Str(s)) => s.clone(),
                _ => unreachable!(),
            };
            match store.get(&key) {
                Some(v) => Ok(ToolOut::Text(v.clone())),
                None => Err(format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = match args.get("prefix") {
                Some(Value::Str(s)) => s.clone(),
                _ => String::new(),
            };
            let mut keys: Vec<String> = store
                .keys()
                .filter(|k| k.starts_with(&prefix))
                .cloned()
                .collect();
            keys.sort();
            let n = keys.len();
            Ok(ToolOut::Structured(Value::Obj(vec![
                (
                    "keys".into(),
                    Value::Arr(keys.into_iter().map(Value::Str).collect()),
                ),
                ("count".into(), Value::Num(n as f64, true)),
            ])))
        }
        "sum" => {
            let nums = match args.get("numbers") {
                Some(Value::Arr(a)) => a.clone(),
                _ => unreachable!(),
            };
            let mut sum: i64 = 0;
            for e in &nums {
                if let Value::Num(f, true) = e {
                    sum += *f as i64;
                }
            }
            let count = nums.len();
            Ok(ToolOut::Structured(Value::Obj(vec![
                ("sum".into(), Value::Num(sum as f64, true)),
                ("count".into(), Value::Num(count as f64, true)),
            ])))
        }
        "text_stats" => {
            let text = match args.get("text") {
                Some(Value::Str(s)) => s.clone(),
                _ => unreachable!(),
            };
            let words = text
                .split(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r')
                .filter(|s| !s.is_empty())
                .count();
            let codepoints = text.chars().count();
            let utf8_bytes = text.len();
            Ok(ToolOut::Structured(Value::Obj(vec![
                ("words".into(), Value::Num(words as f64, true)),
                ("codepoints".into(), Value::Num(codepoints as f64, true)),
                ("utf8_bytes".into(), Value::Num(utf8_bytes as f64, true)),
            ])))
        }
        _ => unreachable!(),
    }
}

fn process(
    line: &str,
    initialized: &mut bool,
    store: &mut BTreeMap<String, String>,
) -> Option<String> {
    let msg = match parse_line(line) {
        Ok(v) => v,
        Err(_) => {
            return Some(error_resp("null", -32700, "Parse error"));
        }
    };
    let obj = match &msg {
        Value::Obj(o) => o,
        _ => return Some(error_resp("null", -32600, "Invalid Request")),
    };

    // id classification
    let id_val = obj.iter().find(|(k, _)| k == "id").map(|(_, v)| v);
    enum IdK {
        Absent,
        Valid(Value),
        Invalid,
    }
    let idk = match id_val {
        None => IdK::Absent,
        Some(v) if matches!(v, Value::Str(_)) || v.is_int() => IdK::Valid(v.clone()),
        Some(_) => IdK::Invalid,
    };
    let id_ser = match &idk {
        IdK::Valid(v) => id_ser(v),
        _ => "null".into(),
    };

    let has_method = obj.iter().any(|(k, _)| k == "method");
    let has_result_or_error = obj.iter().any(|(k, _)| k == "result" || k == "error");
    if !has_method && has_result_or_error {
        return None; // response from client
    }

    let jsonrpc_ok = matches!(obj.iter().find(|(k, _)| k == "jsonrpc"), Some((_, Value::Str(s))) if s == "2.0");
    let method_ok = matches!(
        obj.iter().find(|(k, _)| k == "method"),
        Some((_, Value::Str(_)))
    );

    if !jsonrpc_ok || !method_ok || matches!(idk, IdK::Invalid) {
        return Some(error_resp(&id_ser, -32600, "Invalid Request"));
    }

    if matches!(idk, IdK::Absent) {
        return None; // notification: ignore completely
    }

    let method = match obj.iter().find(|(k, _)| k == "method") {
        Some((_, Value::Str(s))) => s.clone(),
        _ => unreachable!(),
    };

    // a. method known?
    if !matches!(method.as_str(), "initialize" | "ping" | "tools/list" | "tools/call") {
        return Some(error_resp(&id_ser, -32601, "Method not found"));
    }

    // b. params must be object if present
    let params = obj.iter().find(|(k, _)| k == "params").map(|(_, v)| v);
    if let Some(p) = params {
        if !matches!(p, Value::Obj(_)) {
            return Some(error_resp(&id_ser, -32602, "Invalid params"));
        }
    }

    // c. initialization gate
    if !*initialized && method != "initialize" && method != "ping" {
        return Some(error_resp(&id_ser, -32002, "Server not initialized"));
    }

    // d. dispatch
    match method.as_str() {
        "ping" => Some(result_resp(&id_ser, "{}")),
        "initialize" => {
            if *initialized {
                return Some(error_resp(&id_ser, -32600, "Already initialized"));
            }
            let pv = params.and_then(|p| p.get("protocolVersion"));
            let pv = match pv {
                Some(Value::Str(s)) => s.clone(),
                _ => return Some(error_resp(&id_ser, -32602, "Invalid params")),
            };
            *initialized = true;
            let version = if pv == "2025-06-18" || pv == "2025-03-26" || pv == "2024-11-05" {
                pv
            } else {
                "2025-06-18".to_string()
            };
            let body = format!(
                "{{\"protocolVersion\":{},\"capabilities\":{{\"tools\":{{\"listChanged\":false}}}},\"serverInfo\":{{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}}",
                esc(&version)
            );
            Some(result_resp(&id_ser, &body))
        }
        "tools/list" => {
            let body = format!("{{\"tools\":{}}}", TOOLS_JSON);
            Some(result_resp(&id_ser, &body))
        }
        "tools/call" => {
            let params = match params {
                Some(p) => p,
                None => return Some(error_resp(&id_ser, -32602, "Invalid params")),
            };
            let name = match params.get("name") {
                Some(Value::Str(s)) => s.clone(),
                _ => return Some(error_resp(&id_ser, -32602, "Invalid params")),
            };
            let (props, has_output): (&[Prop], bool) = match name.as_str() {
                "kv_set" => (
                    &[
                        Prop { name: "key", kind: Kind::Str, required: true, min1: true },
                        Prop { name: "value", kind: Kind::Str, required: true, min1: false },
                    ],
                    false,
                ),
                "kv_get" => (
                    &[Prop { name: "key", kind: Kind::Str, required: true, min1: true }],
                    false,
                ),
                "kv_list" => (
                    &[Prop { name: "prefix", kind: Kind::Str, required: false, min1: false }],
                    true,
                ),
                "sum" => (
                    &[Prop { name: "numbers", kind: Kind::IntArr, required: true, min1: true }],
                    true,
                ),
                "text_stats" => (
                    &[Prop { name: "text", kind: Kind::Str, required: true, min1: false }],
                    true,
                ),
                _ => {
                    return Some(error_resp(
                        &id_ser,
                        -32602,
                        &format!("Unknown tool: {}", name),
                    ))
                }
            };
            let args = match params.get("arguments") {
                Some(a) => a.clone(),
                None => Value::Obj(vec![]),
            };
            if let Err(e) = validate_args(props, &args) {
                return Some(result_resp(&id_ser, &failure_result(&e)));
            }
            match run_tool(&name, &args, store) {
                Err(e) => Some(result_resp(&id_ser, &failure_result(&e))),
                Ok(ToolOut::Text(t)) => Some(result_resp(&id_ser, &text_result(&t))),
                Ok(ToolOut::Structured(s)) => {
                    if has_output {
                        Some(result_resp(&id_ser, &structured_result(&s)))
                    } else {
                        unreachable!()
                    }
                }
            }
        }
        _ => unreachable!(),
    }
}

fn main() {
    let stdin = io::stdin();
    let mut out = io::BufWriter::new(io::stdout());
    let mut initialized = false;
    let mut store: BTreeMap<String, String> = BTreeMap::new();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        if let Some(resp) = process(&line, &mut initialized, &mut store) {
            writeln!(out, "{}", resp).unwrap();
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

/* ---------- dynamic buffer ---------- */
typedef struct { char *d; size_t n, cap; } Buf;
static void buf_put(Buf *b, const void *p, size_t n) {
    if (b->n + n + 1 > b->cap) { b->cap = (b->n + n) * 2 + 16; b->d = realloc(b->d, b->cap); }
    memcpy(b->d + b->n, p, n); b->n += n;
}
static void buf_putc(Buf *b, char c) { buf_put(b, &c, 1); }

/* ---------- JSON ---------- */
typedef enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ } JType;
typedef struct JV JV;
struct JV {
    JType t;
    double num;
    int boolean;
    char *str; size_t slen;
    JV **items; char **keys; JV **vals; size_t n;
};
static JV *mk(JType t) { JV *v = calloc(1, sizeof *v); v->t = t; return v; }

static const char *cur;
static void perr(const char *m) { fprintf(stderr, "parse error: %s\n", m); exit(1); }
static void skipws(void) { while (*cur == ' ' || *cur == '\t' || *cur == '\n' || *cur == '\r') cur++; }

static unsigned hex4(void) {
    unsigned v = 0;
    for (int i = 0; i < 4; i++) {
        int c = (unsigned char)*cur++; int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if ((c | 32) >= 'a' && (c | 32) <= 'f') d = (c | 32) - 'a' + 10;
        else perr("hex");
        v = v * 16 + d;
    }
    return v;
}
static void utf8_emit(Buf *b, unsigned cp) {
    char t[4]; int n;
    if (cp < 0x80) { t[0] = cp; n = 1; }
    else if (cp < 0x800) { t[0] = 0xC0 | (cp >> 6); t[1] = 0x80 | (cp & 0x3F); n = 2; }
    else if (cp < 0x10000) { t[0] = 0xE0 | (cp >> 12); t[1] = 0x80 | ((cp >> 6) & 0x3F); t[2] = 0x80 | (cp & 0x3F); n = 3; }
    else { t[0] = 0xF0 | (cp >> 18); t[1] = 0x80 | ((cp >> 12) & 0x3F); t[2] = 0x80 | ((cp >> 6) & 0x3F); t[3] = 0x80 | (cp & 0x3F); n = 4; }
    buf_put(b, t, n);
}
static char *pstr(size_t *outlen) {
    if (*cur != '"') perr("str");
    cur++;
    Buf b = {0};
    while (*cur && *cur != '"') {
        if (*cur == '\\') {
            cur++;
            switch (*cur++) {
                case '"': buf_putc(&b, '"'); break;
                case '\\': buf_putc(&b, '\\'); break;
                case '/': buf_putc(&b, '/'); break;
                case 'b': buf_putc(&b, '\b'); break;
                case 'f': buf_putc(&b, '\f'); break;
                case 'n': buf_putc(&b, '\n'); break;
                case 'r': buf_putc(&b, '\r'); break;
                case 't': buf_putc(&b, '\t'); break;
                case 'u': {
                    unsigned cp = hex4();
                    if (cp >= 0xD800 && cp <= 0xDBFF && cur[0] == '\\' && cur[1] == 'u') {
                        cur += 2; unsigned lo = hex4();
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    utf8_emit(&b, cp);
                } break;
                default: perr("esc");
            }
        } else buf_putc(&b, *cur++);
    }
    if (*cur != '"') perr("str end");
    cur++;
    buf_putc(&b, 0);
    *outlen = b.n - 1;
    return b.d;
}
static JV *pval(void) {
    skipws();
    char c = *cur;
    if (c == '{') {
        cur++; JV *o = mk(JOBJ); skipws();
        if (*cur == '}') { cur++; return o; }
        for (;;) {
            skipws();
            if (*cur != '"') perr("key");
            size_t kl; char *k = pstr(&kl);
            skipws(); if (*cur != ':') perr(":"); cur++;
            JV *v = pval();
            o->keys = realloc(o->keys, (o->n + 1) * sizeof(char *));
            o->vals = realloc(o->vals, (o->n + 1) * sizeof(JV *));
            o->keys[o->n] = k; o->vals[o->n] = v; o->n++;
            skipws();
            if (*cur == ',') { cur++; continue; }
            if (*cur == '}') { cur++; break; }
            perr("obj");
        }
        return o;
    }
    if (c == '[') {
        cur++; JV *a = mk(JARR); skipws();
        if (*cur == ']') { cur++; return a; }
        for (;;) {
            JV *v = pval();
            a->items = realloc(a->items, (a->n + 1) * sizeof(JV *));
            a->items[a->n++] = v;
            skipws();
            if (*cur == ',') { cur++; continue; }
            if (*cur == ']') { cur++; break; }
            perr("arr");
        }
        return a;
    }
    if (c == '"') { size_t l; char *s = pstr(&l); JV *v = mk(JSTR); v->str = s; v->slen = l; return v; }
    if (!strncmp(cur, "true", 4)) { cur += 4; JV *v = mk(JBOOL); v->boolean = 1; return v; }
    if (!strncmp(cur, "false", 5)) { cur += 5; JV *v = mk(JBOOL); v->boolean = 0; return v; }
    if (!strncmp(cur, "null", 4)) { cur += 4; return mk(JNULL); }
    char *end; double d = strtod(cur, &end);
    if (end == cur) perr("num");
    cur = end; JV *v = mk(JNUM); v->num = d; return v;
}
static JV *jget(JV *o, const char *k) {
    if (!o || o->t != JOBJ) return NULL;
    for (size_t i = 0; i < o->n; i++)
        if (!strcmp(o->keys[i], k)) return o->vals[i];
    return NULL;
}

/* ---------- base64url ---------- */
static int b64val(int c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}
static int b64ok(const char *s, size_t n) {
    if (n % 4 == 1) return 0;
    for (size_t i = 0; i < n; i++) if (b64val((unsigned char)s[i]) < 0) return 0;
    return 1;
}
static uint8_t *b64dec(const char *s, size_t n, size_t *on) {
    uint8_t *out = malloc(n * 3 / 4 + 4);
    size_t o = 0; uint32_t acc = 0; int bits = 0;
    for (size_t i = 0; i < n; i++) {
        acc = (acc << 6) | (uint32_t)b64val((unsigned char)s[i]); bits += 6;
        if (bits >= 8) { bits -= 8; out[o++] = (acc >> bits) & 0xFF; }
    }
    *on = o; return out;
}

/* ---------- SHA-2 ---------- */
static uint32_t ror32(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }
static uint64_t ror64(uint64_t x, int n) { return (x >> n) | (x << (64 - n)); }

