    for (size_t off = 0; off < nl; off += 128) {
        uint64_t w[80];
        for (int i = 0; i < 16; i++) { w[i] = 0; for (int j = 0; j < 8; j++) w[i] = (w[i] << 8) | buf[off+8*i+j]; }
        for (int i = 16; i < 80; i++) {
            uint64_t s0 = ror64(w[i-15],1) ^ ror64(w[i-15],8) ^ (w[i-15] >> 7);
            uint64_t s1 = ror64(w[i-2],19) ^ ror64(w[i-2],61) ^ (w[i-2] >> 6);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }
        uint64_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
        for (int i = 0; i < 80; i++) {
            uint64_t S1 = ror64(e,14)^ror64(e,18)^ror64(e,41);
            uint64_t t1 = hh + S1 + ((e&f)^(~e&g)) + K[i] + w[i];
            uint64_t S0 = ror64(a,28)^ror64(a,34)^ror64(a,39);
            uint64_t t2 = S0 + ((a&b)^(a&c)^(b&c));
            hh=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
        }
        h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d; h[4]+=e; h[5]+=f; h[6]+=g; h[7]+=hh;
    }
    int n = is384 ? 6 : 8;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < 8; j++) out[8*i+j] = (uint8_t)(h[i] >> (56 - 8*j));
    free(buf);
}

static void hmac_sha(int alg, const uint8_t *key, size_t klen, const uint8_t *msg, size_t mlen, uint8_t *out) {
    int block = (alg == 2) ? 128 : 64;
    int hlen = (alg == 0) ? 32 : (alg == 1) ? 48 : 64;
    uint8_t k[128]; memset(k, 0, block);
    if (klen > (size_t)block) { if (alg == 0) sha256(key, klen, k); else sha512(key, klen, k, alg == 1); }
    else memcpy(k, key, klen);
    uint8_t ih[64];
    uint8_t *ip = malloc((size_t)block + mlen);
    uint8_t *op = malloc((size_t)block + 64);
    for (int i = 0; i < block; i++) { ip[i] = k[i] ^ 0x36; op[i] = k[i] ^ 0x5c; }
    memcpy(ip + block, msg, mlen);
    if (alg == 0) {
        sha256(ip, (size_t)block + mlen, ih);
        memcpy(op + block, ih, 32);
        sha256(op, (size_t)block + 32, out);
    } else {
        sha512(ip, (size_t)block + mlen, ih, 0);
        memcpy(op + block, ih, 64);
        sha512(op, (size_t)block + 64, out, alg == 1);
    }
    free(ip); free(op);
}

/* ---------- helpers ---------- */
static char *readfile(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if (n > 0 && fread(b, 1, (size_t)n, f) != (size_t)n) { fprintf(stderr, "read error\n"); exit(1); }
    b[n] = 0; fclose(f); *len = (size_t)n;
    return b;
}
static int cmpstr(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }
static char *proc_scope(const char *s) {
    char *tmp = strdup(s);
    char *parts[4096]; int n = 0;
    for (char *t = strtok(tmp, " "); t && n < 4096; t = strtok(NULL, " ")) parts[n++] = t;
    qsort(parts, (size_t)n, sizeof(char *), cmpstr);
    Buf b = {0};
    for (int i = 0; i < n; i++) {
        if (i && !strcmp(parts[i], parts[i-1])) continue;
        if (b.n) buf_putc(&b, ',');
        buf_put(&b, parts[i], strlen(parts[i]));
    }
    buf_putc(&b, 0);
    free(tmp);
    if (!b.d) { b.d = malloc(1); b.d[0] = 0; }
    return b.d;
}

typedef struct { char *kid, *alg; uint8_t *sec; size_t seclen; } Key;

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    char path[4096];
    snprintf(path, sizeof path, "%s/config.json", argv[1]);
    size_t cl; char *cfg = readfile(path, &cl);
    cur = cfg; JV *conf = pval();
    double now = jget(conf, "now")->num;
    double leeway = jget(conf, "leeway")->num;
    const char *issuer = jget(conf, "issuer")->str;
    const char *aud = jget(conf, "audience")->str;
    JV *keys = jget(conf, "keys");
    size_t nk = keys->n;
    Key *ks = malloc(sizeof(Key) * (nk ? nk : 1));
    for (size_t i = 0; i < nk; i++) {
        JV *k = keys->items[i];
        ks[i].kid = jget(k, "kid")->str;
        ks[i].alg = jget(k, "alg")->str;
        const char *kb64 = jget(k, "k")->str;
        ks[i].sec = b64dec(kb64, strlen(kb64), &ks[i].seclen);
    }

    snprintf(path, sizeof path, "%s/tokens.txt", argv[1]);
    size_t tl; char *toks = readfile(path, &tl);

    size_t V = 0, I = 0;
    int lineno = 0;
    char *s = toks;
    while (*s) {
        char *nl = strchr(s, '\n'); char *next;
        if (nl) { *nl = 0; next = nl + 1; } else next = s + strlen(s);
        char *a = s;
        while (*a == ' ' || *a == '\t') a++;
        char *e = a + strlen(a);
        while (e > a && (e[-1] == ' ' || e[-1] == '\t')) e--;
        *e = 0;
        s = next;
        if (!*a) continue;
        lineno++;

        const char *res = NULL;
        char *sub = NULL, *scope = NULL;
        do {
            char *d1 = strchr(a, '.');
            if (!d1) { res = "MALFORMED"; break; }
            char *d2 = strchr(d1 + 1, '.');
            if (!d2) { res = "MALFORMED"; break; }
            if (strchr(d2 + 1, '.')) { res = "MALFORMED"; break; }
            *d1 = 0; *d2 = 0;
            char *H = a, *P = d1 + 1, *S = d2 + 1;
            size_t hl = (size_t)(d1 - H), pl = (size_t)(d2 - P), sl = strlen(S);
            if (!hl || !pl || !sl) { res = "MALFORMED"; break; }
            if (!b64ok(H, hl) || !b64ok(P, pl) || !b64ok(S, sl)) { res = "MALFORMED"; break; }
            size_t Hn, Pn;
            uint8_t *Hd = b64dec(H, hl, &Hn), *Pd = b64dec(P, pl, &Pn);
            Hd = realloc(Hd, Hn + 1); Hd[Hn] = 0;
            Pd = realloc(Pd, Pn + 1); Pd[Pn] = 0;
            cur = (char *)Hd; JV *hj = pval();
            if (!hj || hj->t != JOBJ) { res = "MALFORMED"; break; }
            cur = (char *)Pd; JV *pj = pval();
            if (!pj || pj->t != JOBJ) { res = "MALFORMED"; break; }

            JV *alg = jget(hj, "alg");
            if (!alg || alg->t != JSTR ||
                (strcmp(alg->str, "HS256") && strcmp(alg->str, "HS384") && strcmp(alg->str, "HS512"))) {
                res = "UNSUPPORTED_ALG"; break;
            }
            JV *kid = jget(hj, "kid");
            Key *key = NULL;
            if (kid && kid->t == JSTR)
                for (size_t i = 0; i < nk; i++)
                    if (!strcmp(ks[i].kid, kid->str)) { key = &ks[i]; break; }
            if (!key) { res = "UNKNOWN_KEY"; break; }
            if (strcmp(key->alg, alg->str)) { res = "ALG_MISMATCH"; break; }

            size_t Sn;
            uint8_t *Sd = b64dec(S, sl, &Sn);
            int ai = !strcmp(alg->str, "HS256") ? 0 : !strcmp(alg->str, "HS384") ? 1 : 2;
            int hlen = ai == 0 ? 32 : ai == 1 ? 48 : 64;
            uint8_t mac[64];
            size_t mlen = hl + 1 + pl;
            uint8_t *msg = malloc(mlen);
            memcpy(msg, H, hl); msg[hl] = '.'; memcpy(msg + hl + 1, P, pl);
            hmac_sha(ai, key->sec, key->seclen, msg, mlen, mac);
            if (Sn != (size_t)hlen || memcmp(Sd, mac, (size_t)hlen)) { res = "BAD_SIGNATURE"; break; }

            JV *ex = jget(pj, "exp");
            if (ex && ex->t == JNUM && now >= ex->num + leeway) { res = "EXPIRED"; break; }
            JV *nbf = jget(pj, "nbf");
            if (nbf && nbf->t == JNUM && now + leeway < nbf->num) { res = "NOT_YET_VALID"; break; }
            JV *iss = jget(pj, "iss");
            if (!iss || iss->t != JSTR || strcmp(iss->str, issuer)) { res = "BAD_ISSUER"; break; }
            JV *audj = jget(pj, "aud");
            int audok = 0;
            if (audj) {
                if (audj->t == JSTR) audok = !strcmp(audj->str, aud);
                else if (audj->t == JARR)
                    for (size_t i = 0; i < audj->n; i++)
                        if (audj->items[i]->t == JSTR && !strcmp(audj->items[i]->str, aud)) { audok = 1; break; }
            }
            if (!audok) { res = "BAD_AUDIENCE"; break; }

            sub = jget(pj, "sub")->str;
            JV *scv = jget(pj, "scope");
            scope = proc_scope(scv && scv->t == JSTR ? scv->str : "");
        } while (0);

        if (res) { printf("%d: %s\n", lineno, res); I++; }
        else { printf("%d: VALID sub=%s scope=%s\n", lineno, sub, scope); V++; }
    }
    printf("\nvalid=%zu invalid=%zu\n", V, I);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <setjmp.h>
#include <math.h>

/* ---------- dynamic buffer ---------- */
typedef struct { char *d; size_t n, cap; } Buf;
static void buf_put(Buf *b, const void *p, size_t n) {
    if (b->n + n + 1 > b->cap) { b->cap = (b->n + n) * 2 + 16; b->d = realloc(b->d, b->cap); }
    memcpy(b->d + b->n, p, n); b->n += n;
}
static void buf_putc(Buf *b, char c) { buf_put(b, &c, 1); }

/* ---------- JSON ---------- */
typedef enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ } JType;
typedef struct JV JV;
struct JV {
    JType t;
    double num;
    int boolean;
    char *str; size_t slen;
    JV **items; char **keys; JV **vals; size_t n;
};
static JV *mk(JType t) { JV *v = calloc(1, sizeof *v); v->t = t; return v; }

static const char *cur;
static jmp_buf jerr;
static void perr(const char *m) { (void)m; longjmp(jerr, 1); }
static void skipws(void) { while (*cur == ' ' || *cur == '\t' || *cur == '\n' || *cur == '\r') cur++; }

static unsigned hex4(void) {
    unsigned v = 0;
    for (int i = 0; i < 4; i++) {
        int c = (unsigned char)*cur++; int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if ((c | 32) >= 'a' && (c | 32) <= 'f') d = (c | 32) - 'a' + 10;
        else perr("hex");
        v = v * 16 + d;
    }
    return v;
}
static void utf8_emit(Buf *b, unsigned cp) {
    char t[4]; int n;
    if (cp < 0x80) { t[0] = (char)cp; n = 1; }
    else if (cp < 0x800) { t[0] = (char)(0xC0 | (cp >> 6)); t[1] = (char)(0x80 | (cp & 0x3F)); n = 2; }
    else if (cp < 0x10000) { t[0] = (char)(0xE0 | (cp >> 12)); t[1] = (char)(0x80 | ((cp >> 6) & 0x3F)); t[2] = (char)(0x80 | (cp & 0x3F)); n = 3; }
    else { t[0] = (char)(0xF0 | (cp >> 18)); t[1] = (char)(0x80 | ((cp >> 12) & 0x3F)); t[2] = (char)(0x80 | ((cp >> 6) & 0x3F)); t[3] = (char)(0x80 | (cp & 0x3F)); n = 4; }
    buf_put(b, t, n);
}
static char *pstr(size_t *outlen) {
    if (*cur != '"') perr("str");
    cur++;
    Buf b = {0};
    while (*cur && *cur != '"') {
        if (*cur == '\\') {
            cur++;
            switch (*cur++) {
                case '"': buf_putc(&b, '"'); break;
                case '\\': buf_putc(&b, '\\'); break;
                case '/': buf_putc(&b, '/'); break;
                case 'b': buf_putc(&b, '\b'); break;
                case 'f': buf_putc(&b, '\f'); break;
                case 'n': buf_putc(&b, '\n'); break;
                case 'r': buf_putc(&b, '\r'); break;
                case 't': buf_putc(&b, '\t'); break;
                case 'u': {
                    unsigned cp = hex4();
                    if (cp >= 0xD800 && cp <= 0xDBFF && cur[0] == '\\' && cur[1] == 'u') {
                        cur += 2; unsigned lo = hex4();
                        if (lo >= 0xDC00 && lo <= 0xDFFF)
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    utf8_emit(&b, cp);
                } break;
                default: perr("esc");
            }
        } else buf_putc(&b, *cur++);
    }
    if (*cur != '"') perr("str end");
    cur++;
    buf_putc(&b, 0);
    *outlen = b.n - 1;
    return b.d;
}
static JV *pval(void) {
    skipws();
    char c = *cur;
    if (c == '{') {
        cur++; JV *o = mk(JOBJ); skipws();
        if (*cur == '}') { cur++; return o; }
        for (;;) {
            skipws();
            if (*cur != '"') perr("key");
            size_t kl; char *k = pstr(&kl);
            skipws(); if (*cur != ':') perr(":"); cur++;
            JV *v = pval();
            o->keys = realloc(o->keys, (o->n + 1) * sizeof(char *));
            o->vals = realloc(o->vals, (o->n + 1) * sizeof(JV *));
            o->keys[o->n] = k; o->vals[o->n] = v; o->n++;
            skipws();
            if (*cur == ',') { cur++; continue; }
            if (*cur == '}') { cur++; break; }
            perr("obj");
        }
        return o;
    }
    if (c == '[') {
        cur++; JV *a = mk(JARR); skipws();
        if (*cur == ']') { cur++; return a; }
        for (;;) {
            JV *v = pval();
            a->items = realloc(a->items, (a->n + 1) * sizeof(JV *));
            a->items[a->n++] = v;
            skipws();
            if (*cur == ',') { cur++; continue; }
            if (*cur == ']') { cur++; break; }
            perr("arr");
        }
        return a;
    }
    if (c == '"') { size_t l; char *s = pstr(&l); JV *v = mk(JSTR); v->str = s; v->slen = l; return v; }
    if (!strncmp(cur, "true", 4)) { cur += 4; JV *v = mk(JBOOL); v->boolean = 1; return v; }
    if (!strncmp(cur, "false", 5)) { cur += 5; JV *v = mk(JBOOL); v->boolean = 0; return v; }
    if (!strncmp(cur, "null", 4)) { cur += 4; return mk(JNULL); }
    char *end; double d = strtod(cur, &end);
    if (end == cur) perr("num");
    cur = end; JV *v = mk(JNUM); v->num = d; return v;
}
/* Parse a complete JSON document; returns NULL on any error. */
static JV *parse_json(const char *s) {
    if (setjmp(jerr)) return NULL;
    cur = s;
    JV *v = pval();
    skipws();
    if (*cur != '\0') return NULL;
    return v;
}
static JV *jget(JV *o, const char *k) {
    if (!o || o->t != JOBJ) return NULL;
    for (size_t i = 0; i < o->n; i++)
        if (!strcmp(o->keys[i], k)) return o->vals[i];
    return NULL;
}

/* ---------- base64url ---------- */
static int b64val(int c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}
static int b64ok(const char *s, size_t n) {
    if (n % 4 == 1) return 0;
    for (size_t i = 0; i < n; i++) if (b64val((unsigned char)s[i]) < 0) return 0;
    return 1;
}
static uint8_t *b64dec(const char *s, size_t n, size_t *on) {
    uint8_t *out = malloc(n * 3 / 4 + 4);
    size_t o = 0; uint32_t acc = 0; int bits = 0;
    for (size_t i = 0; i < n; i++) {
        acc = (acc << 6) | (uint32_t)b64val((unsigned char)s[i]); bits += 6;
        if (bits >= 8) { bits -= 8; out[o++] = (uint8_t)(acc >> bits) & 0xFF; }
    }
    *on = o; return out;
}

/* ---------- SHA-2 ---------- */
static uint32_t ror32(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }
static uint64_t ror64(uint64_t x, int n) { return (x >> n) | (x << (64 - n)); }

static void sha256(const uint8_t *m, size_t len, uint8_t *out) {
    static const uint32_t K[64] = {
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2 };
    uint32_t h[8] = { 0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19 };
    size_t nl = ((len + 8) / 64 + 1) * 64;
    uint8_t *buf = calloc(nl, 1);
    memcpy(buf, m, len); buf[len] = 0x80;
    uint64_t bl = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) buf[nl - 1 - i] = (uint8_t)(bl >> (8 * i));
    for (size_t off = 0; off < nl; off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; i++)
            w[i] = ((uint32_t)buf[off+4*i] << 24) | ((uint32_t)buf[off+4*i+1] << 16) | ((uint32_t)buf[off+4*i+2] << 8) | buf[off+4*i+3];
        for (int i = 16; i < 64; i++) {
            uint32_t s0 = ror32(w[i-15],7) ^ ror32(w[i-15],18) ^ (w[i-15] >> 3);
            uint32_t s1 = ror32(w[i-2],17) ^ ror32(w[i-2],19) ^ (w[i-2] >> 10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }
        uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
        for (int i = 0; i < 64; i++) {
            uint32_t S1 = ror32(e,6)^ror32(e,11)^ror32(e,25);
            uint32_t t1 = hh + S1 + ((e&f)^(~e&g)) + K[i] + w[i];
            uint32_t S0 = ror32(a,2)^ror32(a,13)^ror32(a,22);
            uint32_t t2 = S0 + ((a&b)^(a&c)^(b&c));
            hh=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
        }
        h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d; h[4]+=e; h[5]+=f; h[6]+=g; h[7]+=hh;
    }
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 4; j++) out[4*i+j] = (uint8_t)(h[i] >> (24 - 8*j));
    free(buf);
}

static void sha512(const uint8_t *m, size_t len, uint8_t *out, int is384) {
