static void hmac_sha(int alg, const uint8_t *key, size_t klen, const uint8_t *msg, size_t mlen, uint8_t *out) {
    int block = (alg == 2) ? 128 : 64;
    int hlen = (alg == 0) ? 32 : (alg == 1) ? 48 : 64;
    uint8_t k[128]; memset(k, 0, block);
    if (klen > (size_t)block) { if (alg == 0) sha256(key, klen, k); else sha512(key, klen, k, alg == 1); }
    else memcpy(k, key, klen);
    uint8_t ih[64];
    uint8_t *ip = malloc((size_t)block + mlen);
    uint8_t *op = malloc((size_t)block + 64);
    for (int i = 0; i < block; i++) { ip[i] = k[i] ^ 0x36; op[i] = k[i] ^ 0x5c; }
    memcpy(ip + block, msg, mlen);
    if (alg == 0) {
        sha256(ip, (size_t)block + mlen, ih);
        memcpy(op + block, ih, 32);
        sha256(op, (size_t)block + 32, out);
    } else {
        sha512(ip, (size_t)block + mlen, ih, 0);
        memcpy(op + block, ih, 64);
        sha512(op, (size_t)block + 64, out, alg == 1);
    }
    free(ip); free(op);
    (void)hlen;
}

/* ---------- helpers ---------- */
static char *readfile(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if (n > 0 && fread(b, 1, (size_t)n, f) != (size_t)n) { fprintf(stderr, "read error\n"); exit(1); }
    b[n] = 0; fclose(f); *len = (size_t)n;
    return b;
}
static int cmpstr(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }
static char *proc_scope(const char *s) {
    char *tmp = strdup(s);
    char *parts[4096]; int n = 0;
    for (char *t = strtok(tmp, " "); t && n < 4096; t = strtok(NULL, " ")) parts[n++] = t;
    qsort(parts, (size_t)n, sizeof(char *), cmpstr);
    Buf b = {0};
    for (int i = 0; i < n; i++) {
        if (i && !strcmp(parts[i], parts[i-1])) continue;
        if (b.n) buf_putc(&b, ',');
        buf_put(&b, parts[i], strlen(parts[i]));
    }
    buf_putc(&b, 0);
    free(tmp);
    if (!b.d) { b.d = malloc(1); b.d[0] = 0; }
    return b.d;
}

typedef struct { char *kid, *alg; uint8_t *sec; size_t seclen; } Key;

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    char path[4096];
    snprintf(path, sizeof path, "%s/config.json", argv[1]);
    size_t cl; char *cfg = readfile(path, &cl);
    JV *conf = parse_json(cfg);
    if (!conf) return 1;
    double now = jget(conf, "now")->num;
    double leeway = jget(conf, "leeway")->num;
    const char *issuer = jget(conf, "issuer")->str;
    const char *aud = jget(conf, "audience")->str;
    JV *keys = jget(conf, "keys");
    size_t nk = keys->n;
    Key *ks = malloc(sizeof(Key) * (nk ? nk : 1));
    for (size_t i = 0; i < nk; i++) {
        JV *k = keys->items[i];
        ks[i].kid = jget(k, "kid")->str;
        ks[i].alg = jget(k, "alg")->str;
        const char *kb64 = jget(k, "k")->str;
        ks[i].sec = b64dec(kb64, strlen(kb64), &ks[i].seclen);
    }

    snprintf(path, sizeof path, "%s/tokens.txt", argv[1]);
    size_t tl; char *toks = readfile(path, &tl);

    size_t V = 0, I = 0;
    int lineno = 0;
    char *s = toks;
    while (*s) {
        char *nl = strchr(s, '\n'); char *next;
        if (nl) { *nl = 0; next = nl + 1; } else next = s + strlen(s);
        char *a = s;
        while (*a == ' ' || *a == '\t') a++;
        char *e = a + strlen(a);
        while (e > a && (e[-1] == ' ' || e[-1] == '\t')) e--;
        *e = 0;
        s = next;
        if (!*a) continue;
        lineno++;

        const char *res = NULL;
        char *sub = NULL, *scope = NULL;
        do {
            char *d1 = strchr(a, '.');
            if (!d1) { res = "MALFORMED"; break; }
            char *d2 = strchr(d1 + 1, '.');
            if (!d2) { res = "MALFORMED"; break; }
            if (strchr(d2 + 1, '.')) { res = "MALFORMED"; break; }
            *d1 = 0; *d2 = 0;
            char *H = a, *P = d1 + 1, *S = d2 + 1;
            size_t hl = (size_t)(d1 - H), pl = (size_t)(d2 - P), sl = strlen(S);
            if (!hl || !pl || !sl) { res = "MALFORMED"; break; }
            if (!b64ok(H, hl) || !b64ok(P, pl) || !b64ok(S, sl)) { res = "MALFORMED"; break; }
            size_t Hn, Pn;
            uint8_t *Hd = b64dec(H, hl, &Hn), *Pd = b64dec(P, pl, &Pn);
            Hd = realloc(Hd, Hn + 1); Hd[Hn] = 0;
            Pd = realloc(Pd, Pn + 1); Pd[Pn] = 0;
            JV *hj = parse_json((char *)Hd);
            if (!hj || hj->t != JOBJ) { res = "MALFORMED"; break; }
            JV *pj = parse_json((char *)Pd);
            if (!pj || pj->t != JOBJ) { res = "MALFORMED"; break; }

            JV *alg = jget(hj, "alg");
            if (!alg || alg->t != JSTR ||
                (strcmp(alg->str, "HS256") && strcmp(alg->str, "HS384") && strcmp(alg->str, "HS512"))) {
                res = "UNSUPPORTED_ALG"; break;
            }
            JV *kid = jget(hj, "kid");
            Key *key = NULL;
            if (kid && kid->t == JSTR)
                for (size_t i = 0; i < nk; i++)
                    if (!strcmp(ks[i].kid, kid->str)) { key = &ks[i]; break; }
            if (!key) { res = "UNKNOWN_KEY"; break; }
            if (strcmp(key->alg, alg->str)) { res = "ALG_MISMATCH"; break; }

            size_t Sn;
            uint8_t *Sd = b64dec(S, sl, &Sn);
            int ai = !strcmp(alg->str, "HS256") ? 0 : !strcmp(alg->str, "HS384") ? 1 : 2;
            int hlen = ai == 0 ? 32 : ai == 1 ? 48 : 64;
            uint8_t mac[64];
            size_t mlen = hl + 1 + pl;
            uint8_t *msg = malloc(mlen);
            memcpy(msg, H, hl); msg[hl] = '.'; memcpy(msg + hl + 1, P, pl);
            hmac_sha(ai, key->sec, key->seclen, msg, mlen, mac);
            if (Sn != (size_t)hlen || memcmp(Sd, mac, (size_t)hlen)) { res = "BAD_SIGNATURE"; break; }

            JV *ex = jget(pj, "exp");
            if (ex && ex->t == JNUM && now >= ex->num + leeway) { res = "EXPIRED"; break; }
            JV *nbf = jget(pj, "nbf");
            if (nbf && nbf->t == JNUM && now + leeway < nbf->num) { res = "NOT_YET_VALID"; break; }
            JV *iss = jget(pj, "iss");
            if (!iss || iss->t != JSTR || strcmp(iss->str, issuer)) { res = "BAD_ISSUER"; break; }
            JV *audj = jget(pj, "aud");
            int audok = 0;
            if (audj) {
                if (audj->t == JSTR) audok = !strcmp(audj->str, aud);
                else if (audj->t == JARR)
                    for (size_t i = 0; i < audj->n; i++)
                        if (audj->items[i]->t == JSTR && !strcmp(audj->items[i]->str, aud)) { audok = 1; break; }
            }
            if (!audok) { res = "BAD_AUDIENCE"; break; }

            sub = jget(pj, "sub")->str;
            JV *scv = jget(pj, "scope");
            scope = proc_scope(scv && scv->t == JSTR ? scv->str : "");
        } while (0);

        if (res) { printf("%d: %s\n", lineno, res); I++; }
        else { printf("%d: VALID sub=%s scope=%s\n", lineno, sub, scope); V++; }
    }
    printf("\nvalid=%zu invalid=%zu\n", V, I);
    return 0;
}

import Foundation

indirect enum JSON {
    case null
    case bool(Bool)
    case num(Double)
    case str(String)
    case arr([JSON])
    case obj([String: JSON])
}

// MARK: - Parser

final class Parser {
    var b: [UInt8]
    var i = 0
    init(_ s: String) { b = Array(s.utf8) }

    func ws() {
        while i < b.count {
            switch b[i] {
            case 0x20, 0x09, 0x0A, 0x0D: i += 1
            default: return
            }
        }
    }

    func parse() -> JSON {
        ws()
        return value()
    }

    func value() -> JSON {
        ws()
        let c = b[i]
        switch c {
        case UInt8(ascii: "{"): return obj()
        case UInt8(ascii: "["): return arr()
        case UInt8(ascii: "\""): return .str(string())
        case UInt8(ascii: "t"): i += 4; return .bool(true)
        case UInt8(ascii: "f"): i += 5; return .bool(false)
        case UInt8(ascii: "n"): i += 4; return .null
        default: return number()
        }
    }

    func obj() -> JSON {
        i += 1
        var d = [String: JSON]()
        ws()
        if b[i] == UInt8(ascii: "}") { i += 1; return .obj(d) }
        while true {
            ws()
            let k = string()
            ws()
            i += 1 // ':'
            d[k] = value()
            ws()
            if b[i] == UInt8(ascii: ",") { i += 1 } else { i += 1; break }
        }
        return .obj(d)
    }

    func arr() -> JSON {
        i += 1
        var a = [JSON]()
        ws()
        if b[i] == UInt8(ascii: "]") { i += 1; return .arr(a) }
        while true {
            a.append(value())
            ws()
            if b[i] == UInt8(ascii: ",") { i += 1 } else { i += 1; break }
        }
        return .arr(a)
    }

    func string() -> String {
        i += 1 // skip "
        var out = [UInt8]()
        while true {
            let c = b[i]
            if c == UInt8(ascii: "\"") { i += 1; break }
            if c == UInt8(ascii: "\\") {
                i += 1
                let e = b[i]
                switch e {
                case UInt8(ascii: "\""): out.append(0x22); i += 1
                case UInt8(ascii: "\\"): out.append(0x5C); i += 1
                case UInt8(ascii: "/"): out.append(0x2F); i += 1
                case UInt8(ascii: "b"): out.append(0x08); i += 1
                case UInt8(ascii: "f"): out.append(0x0C); i += 1
                case UInt8(ascii: "n"): out.append(0x0A); i += 1
                case UInt8(ascii: "r"): out.append(0x0D); i += 1
                case UInt8(ascii: "t"): out.append(0x09); i += 1
                case UInt8(ascii: "u"):
                    i += 1
                    var v = hex4()
                    if v >= 0xD800 && v <= 0xDBFF {
                        i += 2 // \u
                        let lo = hex4()
                        v = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00)
                    }
                    out.append(contentsOf: Array(String(Unicode.Scalar(v)!).utf8))
                default: fatalError("bad escape")
                }
            } else if c < 0x80 {
                out.append(c); i += 1
            } else {
                out.append(c); i += 1
                while i < b.count && (b[i] & 0xC0) == 0x80 {
                    out.append(b[i]); i += 1
                }
            }
        }
        return String(decoding: out, as: UTF8.self)
    }

    func hex4() -> Int {
        var v = 0
        for _ in 0..<4 {
            let c = b[i]; i += 1
            let d: Int
            switch c {
            case 0x30...0x39: d = Int(c - 0x30)
            case 0x61...0x66: d = Int(c - 0x61) + 10
            case 0x41...0x46: d = Int(c - 0x41) + 10
            default: fatalError("bad hex")
            }
            v = v * 16 + d
        }
        return v
    }

    func number() -> JSON {
        let st = i
        while i < b.count {
            let c = b[i]
            if (c >= 0x30 && c <= 0x39) || c == 0x2D || c == 0x2B || c == 0x2E || c == 0x45 || c == 0x65 {
                i += 1
            } else { break }
        }
        let tok = String(decoding: b[st..<i], as: UTF8.self)
        return .num(Double(tok)!)
    }
}

// MARK: - Helpers

func esc(_ s: String) -> String {
    s.replacingOccurrences(of: "~", with: "~0").replacingOccurrences(of: "/", with: "~1")
}

func unescapeToken(_ s: Substring) -> String {
    var r = ""
    var i = s.startIndex
    while i < s.endIndex {
        if s[i] == "~" {
            let nx = s.index(after: i)
            if nx < s.endIndex {
                if s[nx] == "0" { r.append("~"); i = s.index(after: nx); continue }
                if s[nx] == "1" { r.append("/"); i = s.index(after: nx); continue }
            }
        }
        r.append(s[i])
        i = s.index(after: i)
    }
    return r
}

func deepEqual(_ a: JSON, _ b: JSON) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.num(let x), .num(let y)): return x == y
    case (.str(let x), .str(let y)): return x == y
    case (.arr(let x), .arr(let y)):
        return x.count == y.count && zip(x, y).allSatisfy { deepEqual($0, $1) }
    case (.obj(let x), .obj(let y)):
        guard x.count == y.count else { return false }
        for (k, v) in x {
            guard case .some(let w) = y[k], deepEqual(v, w) else { return false }
        }
        return true
    default: return false
    }
}

func isInteger(_ d: Double) -> Bool {
    d.isFinite && d == d.rounded(.towardZero)
}

func typeMatches(_ inst: JSON, _ t: String) -> Bool {
    switch t {
    case "null":
        if case .null = inst { return true }
    case "boolean":
        if case .bool = inst { return true }
    case "object":
        if case .obj = inst { return true }
    case "array":
        if case .arr = inst { return true }
    case "string":
        if case .str = inst { return true }
    case "number":
        if case .num = inst { return true }
    case "integer":
        if case .num(let d) = inst { return isInteger(d) }
    default: break
    }
    return false
}

struct Err: Hashable {
    let inst: String
    let sch: String
}

var root: JSON = .null

func resolveRef(_ ref: String) -> (JSON, String)? {
    if ref == "#" { return (root, "#") }
    guard ref.hasPrefix("#/") else { return nil }
    let tokens = ref.dropFirst(2).split(separator: "/", omittingEmptySubsequences: false).map { unescapeToken($0) }
    var cur = root
    for t in tokens {
        guard case .obj(let o) = cur, let v = o[t] else { return nil }
        cur = v
    }
    return (cur, ref)
}

func accepts(_ inst: JSON, _ sch: JSON, _ sp: String) -> Bool {
    var e = Set<Err>()
    validate(inst, "#", sch, sp, &e)
    return e.isEmpty
}

func validate(_ inst: JSON, _ ip: String, _ sch: JSON, _ sp: String, _ errs: inout Set<Err>) {
    switch sch {
    case .bool(let b):
        if !b { errs.insert(Err(inst: ip, sch: sp)) }
    case .obj(let o):
        // type
        if let tv = o["type"] {
            var ok = false
            switch tv {
            case .str(let t):
                ok = typeMatches(inst, t)
            case .arr(let ts):
                for t in ts {
                    if case .str(let s) = t, typeMatches(inst, s) { ok = true; break }
                }
            default:
                ok = true
            }
            if !ok { errs.insert(Err(inst: ip, sch: sp + "/type")) }
        }
        // enum
        if case .arr(let list)? = o["enum"] {
            if !list.contains(where: { deepEqual(inst, $0) }) {
                errs.insert(Err(inst: ip, sch: sp + "/enum"))
            }
        }
        // const
        if let cv = o["const"], !deepEqual(inst, cv) {
            errs.insert(Err(inst: ip, sch: sp + "/const"))
        }
        // numbers
        if case .num(let d) = inst {
            if case .num(let v)? = o["minimum"], !(d >= v) {
                errs.insert(Err(inst: ip, sch: sp + "/minimum"))
            }
            if case .num(let v)? = o["maximum"], !(d <= v) {
                errs.insert(Err(inst: ip, sch: sp + "/maximum"))
            }
            if case .num(let v)? = o["exclusiveMinimum"], !(d > v) {
                errs.insert(Err(inst: ip, sch: sp + "/exclusiveMinimum"))
            }
            if case .num(let v)? = o["exclusiveMaximum"], !(d < v) {
                errs.insert(Err(inst: ip, sch: sp + "/exclusiveMaximum"))
            }
        }
        // strings
        if case .str(let s) = inst {
            let n = s.unicodeScalars.count
            if case .num(let v)? = o["minLength"], !(Double(n) >= v) {
                errs.insert(Err(inst: ip, sch: sp + "/minLength"))
            }
            if case .num(let v)? = o["maxLength"], !(Double(n) <= v) {
                errs.insert(Err(inst: ip, sch: sp + "/maxLength"))
            }
        }
        // arrays
        if case .arr(let items) = inst {
            if case .num(let v)? = o["minItems"], !(Double(items.count) >= v) {
                errs.insert(Err(inst: ip, sch: sp + "/minItems"))
            }
            if case .num(let v)? = o["maxItems"], !(Double(items.count) <= v) {
                errs.insert(Err(inst: ip, sch: sp + "/maxItems"))
            }
            if case .bool(true)? = o["uniqueItems"] {
                outer: for a in 0..<items.count {
                    for b in (a + 1)..<items.count {
                        if deepEqual(items[a], items[b]) {
                            errs.insert(Err(inst: ip, sch: sp + "/uniqueItems"))
                            break outer
                        }
                    }
                }
            }
            var start = 0
            if case .arr(let pi)? = o["prefixItems"] {
                for k in 0..<min(pi.count, items.count) {
                    validate(items[k], ip + "/\(k)", pi[k], sp + "/prefixItems/\(k)", &errs)
                }
                start = pi.count
            }
            if let it = o["items"] {
                for k in start..<items.count {
                    validate(items[k], ip + "/\(k)", it, sp + "/items", &errs)
                }
            }
        }
        // objects
        if case .obj(let m) = inst {
            if case .num(let v)? = o["minProperties"], !(Double(m.count) >= v) {
                errs.insert(Err(inst: ip, sch: sp + "/minProperties"))
            }
            if case .num(let v)? = o["maxProperties"], !(Double(m.count) <= v) {
                errs.insert(Err(inst: ip, sch: sp + "/maxProperties"))
            }
            if case .arr(let req)? = o["required"] {
                for (j, r) in req.enumerated() {
                    if case .str(let name) = r, m[name] == nil {
                        errs.insert(Err(inst: ip, sch: sp + "/required/\(j)"))
                    }
                }
            }
            var propKeys = Set<String>()
            if case .obj(let props)? = o["properties"] {
                propKeys = Set(props.keys)
                for (name, sub) in props {
                    if let v = m[name] {
                        validate(v, ip + "/" + esc(name), sub, sp + "/properties/" + esc(name), &errs)
                    }
                }
            }
            if let ap = o["additionalProperties"] {
                for (name, v) in m {
                    if !propKeys.contains(name) {
                        validate(v, ip + "/" + esc(name), ap, sp + "/additionalProperties", &errs)
                    }
                }
            }
        }
        // allOf
        if case .arr(let subs)? = o["allOf"] {
            for (k, sub) in subs.enumerated() {
                validate(inst, ip, sub, sp + "/allOf/\(k)", &errs)
            }
        }
        // anyOf
        if case .arr(let subs)? = o["anyOf"] {
            var any = false
            for (k, sub) in subs.enumerated() {
                if accepts(inst, sub, sp + "/anyOf/\(k)") { any = true; break }
            }
            if !any { errs.insert(Err(inst: ip, sch: sp + "/anyOf")) }
        }
        // oneOf
        if case .arr(let subs)? = o["oneOf"] {
            var c = 0
            for (k, sub) in subs.enumerated() {
                if accepts(inst, sub, sp + "/oneOf/\(k)") { c += 1 }
            }
            if c != 1 { errs.insert(Err(inst: ip, sch: sp + "/oneOf")) }
        }
        // not
        if let ns = o["not"] {
            if accepts(inst, ns, sp + "/not") {
                errs.insert(Err(inst: ip, sch: sp + "/not"))
            }
        }
        // if/then/else
        if let ifS = o["if"] {
            let cond = accepts(inst, ifS, sp + "/if")
            if cond, let thenS = o["then"] {
                validate(inst, ip, thenS, sp + "/then", &errs)
            }
            if !cond, let elseS = o["else"] {
                validate(inst, ip, elseS, sp + "/else", &errs)
            }
        }
        // $ref
        if case .str(let r)? = o["$ref"] {
            if let (sub, loc) = resolveRef(r) {
                validate(inst, ip, sub, loc, &errs)
            }
        }
    default:
        break
    }
}

// MARK: - Main

func main() {
    let args = CommandLine.arguments
    guard args.count > 1 else { exit(1) }
    let dir = args[1]
    guard let schemaStr = try? String(contentsOfFile: dir + "/schema.json", encoding: .utf8),
          let instStr = try? String(contentsOfFile: dir + "/instances.json", encoding: .utf8) else {
        exit(1)
    }
    root = Parser(schemaStr).parse()
    guard case .arr(let insts) = Parser(instStr).parse() else { exit(1) }

    var out = ""
    var nv = 0, ni = 0
    for (n, inst) in insts.enumerated() {
        var errs = Set<Err>()
        validate(inst, "#", root, "#", &errs)
        if errs.isEmpty {
            nv += 1
            out += "\(n): valid\n"
        } else {
            ni += 1
            out += "\(n): invalid (\(errs.count))\n"
            let sorted = errs.sorted { a, b in
                if a.inst != b.inst {
                    return a.inst.utf8.lexicographicallyPrecedes(b.inst.utf8)
                }
                return a.sch.utf8.lexicographicallyPrecedes(b.sch.utf8)
            }
            for e in sorted {
                out += "  \(e.inst) \(e.sch)\n"
            }
        }
    }
    out += "valid=\(nv) invalid=\(ni)\n"
    print(out, terminator: "")
}

main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef enum { J_NULL, J_BOOL, J_NUM, J_STR, J_ARR, J_OBJ } JType;
typedef struct JVal JVal;
struct JVal {
    JType t;
    int b;
    int is_int;
    long long i;
    double d;
    char *s; size_t slen;
    JVal **items;
    char **keys; size_t *keyl;
    size_t n, cap;
};

static void *xmalloc(size_t n){ void*p=malloc(n?n:1); if(!p)exit(1); return p; }
static void *xrealloc(void*p,size_t n){ p=realloc(p,n?n:1); if(!p)exit(1); return p; }
static char *xstrdup(const char*s){ size_t l=strlen(s); char*r=xmalloc(l+1); memcpy(r,s,l+1); return r; }

typedef struct { char *d; size_t n, cap; } Buf;
static void buf_put(Buf*b,const char*s,size_t l){
    if(b->n+l+1>b->cap){ b->cap=(b->n+l+1)*2; b->d=xrealloc(b->d,b->cap); }
    memcpy(b->d+b->n,s,l); b->n+=l; b->d[b->n]=0;
}
static void bputs(Buf*b,const char*s){ buf_put(b,s,strlen(s)); }
static void bputc(Buf*b,char c){ buf_put(b,&c,1); }
static void bputi(Buf*b,long long v){ char t[32]; snprintf(t,sizeof t,"%lld",v); bputs(b,t); }
static void bputjstr(Buf*b,const char*s,size_t l){
    bputc(b,'"');
    for(size_t i=0;i<l;i++){
        unsigned char c=(unsigned char)s[i];
        switch(c){
        case '"': bputs(b,"\\\""); break;
        case '\\': bputs(b,"\\\\"); break;
        case '\n': bputs(b,"\\n"); break;
        case '\r': bputs(b,"\\r"); break;
        case '\t': bputs(b,"\\t"); break;
        case '\b': bputs(b,"\\b"); break;
        case '\f': bputs(b,"\\f"); break;
        default:
            if(c<0x20){ char t[8]; snprintf(t,sizeof t,"\\u%04x",c); bputs(b,t); }
            else bputc(b,(char)c);
        }
    }
    bputc(b,'"');
}

/* ---------- parser ---------- */
static const char *P; static int PERR;

static void skipws(void){ while(*P==' '||*P=='\t'||*P=='\r'||*P=='\n') P++; }
static JVal *newval(JType t){ JVal*v=xmalloc(sizeof *v); memset(v,0,sizeof *v); v->t=t; return v; }

static void arr_add(JVal*a,JVal*v){
    if(a->n==a->cap){ a->cap=a->cap?a->cap*2:8; a->items=xrealloc(a->items,a->cap*sizeof(JVal*)); }
    a->items[a->n++]=v;
}
static void obj_add(JVal*o,char*k,size_t kl,JVal*v){
    if(o->n==o->cap){
        o->cap=o->cap?o->cap*2:8;
        o->items=xrealloc(o->items,o->cap*sizeof(JVal*));
        o->keys=xrealloc(o->keys,o->cap*sizeof(char*));
        o->keyl=xrealloc(o->keyl,o->cap*sizeof(size_t));
    }
    o->keys[o->n]=k; o->keyl[o->n]=kl; o->items[o->n]=v; o->n++;
}
static JVal *obj_getn(JVal*o,const char*k,size_t kl){
    if(!o||o->t!=J_OBJ) return NULL;
    for(size_t i=0;i<o->n;i++)
        if(o->keyl[i]==kl && !memcmp(o->keys[i],k,kl)) return o->items[i];
    return NULL;
}

static unsigned hex4(void){
    unsigned v=0;
    for(int i=0;i<4;i++){
        char c=P[i]; unsigned d;
        if(c>='0'&&c<='9')d=c-'0';
        else if(c>='a'&&c<='f')d=c-'a'+10;
        else if(c>='A'&&c<='F')d=c-'A'+10;
        else { PERR=1; return 0; }
        v=v*16+d;
    }
    P+=4; return v;
}

static JVal *parse_string(void){
    if(*P!='"'){ PERR=1; return NULL; }
    P++;
    Buf b={0};
    while(1){
        unsigned char c=(unsigned char)*P;
        if(!c){ PERR=1; break; }
        if(c=='"'){ P++; break; }
        if(c=='\\'){
            P++;
            char e=*P++;
            if(e=='"')bputc(&b,'"');
            else if(e=='\\')bputc(&b,'\\');
            else if(e=='/')bputc(&b,'/');
            else if(e=='b')bputc(&b,'\b');
            else if(e=='f')bputc(&b,'\f');
            else if(e=='n')bputc(&b,'\n');
            else if(e=='r')bputc(&b,'\r');
            else if(e=='t')bputc(&b,'\t');
            else if(e=='u'){
                unsigned cp=hex4(); if(PERR)break;
                if(cp>=0xD800&&cp<=0xDBFF&&P[0]=='\\'&&P[1]=='u'){
                    const char*save=P; P+=2;
                    unsigned lo=hex4();
                    if(!PERR&&lo>=0xDC00&&lo<=0xDFFF)
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    else if(!PERR){ P=save; }
                }
                if(cp<0x80)bputc(&b,(char)cp);
                else if(cp<0x800){bputc(&b,(char)(0xC0|(cp>>6)));bputc(&b,(char)(0x80|(cp&63)));}
                else if(cp<0x10000){bputc(&b,(char)(0xE0|(cp>>12)));bputc(&b,(char)(0x80|((cp>>6)&63)));bputc(&b,(char)(0x80|(cp&63)));}
                else {bputc(&b,(char)(0xF0|(cp>>18)));bputc(&b,(char)(0x80|((cp>>12)&63)));bputc(&b,(char)(0x80|((cp>>6)&63)));bputc(&b,(char)(0x80|(cp&63)));}
            }
            else { PERR=1; break; }
        }
        else if(c<0x20){ PERR=1; break; }
        else { bputc(&b,(char)c); P++; }
    }
    if(PERR){ free(b.d); return NULL; }
    if(!b.d) b.d=xstrdup("");
    JVal*v=newval(J_STR); v->s=b.d; v->slen=b.n; return v;
}

static JVal *parse_number(void){
    const char*st=P;
    if(*P=='-')P++;
    if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; }
    if(*P=='0'){ P++; if(*P>='0'&&*P<='9'){ PERR=1; return NULL; } }
    else while(*P>='0'&&*P<='9')P++;
    int isint=1;
    if(*P=='.'){ isint=0; P++; if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; } while(*P>='0'&&*P<='9')P++; }
    if(*P=='e'||*P=='E'){ isint=0; P++; if(*P=='+'||*P=='-')P++; if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; } while(*P>='0'&&*P<='9')P++; }
    size_t l=P-st; char*t=xmalloc(l+1); memcpy(t,st,l); t[l]=0;
    JVal*v=newval(J_NUM); v->is_int=isint; v->d=strtod(t,NULL); if(isint)v->i=strtoll(t,NULL,10);
    free(t); return v;
}

static JVal *parse_value(void){
    skipws();
    if(*P=='{'){
        P++; JVal*o=newval(J_OBJ);
        skipws(); if(*P=='}'){ P++; return o; }
        while(1){
            skipws();
            JVal*k=parse_string(); if(PERR)return NULL;
            skipws(); if(*P!=':'){ PERR=1; return NULL; } P++;
            JVal*v=parse_value(); if(PERR)return NULL;
            obj_add(o,k->s,k->slen,v); free(k);
            skipws();
            if(*P==','){ P++; continue; }
            if(*P=='}'){ P++; return o; }
            PERR=1; return NULL;
        }
    }
    if(*P=='['){
        P++; JVal*a=newval(J_ARR);
        skipws(); if(*P==']'){ P++; return a; }
        while(1){
            JVal*v=parse_value(); if(PERR)return NULL;
            arr_add(a,v); skipws();
            if(*P==','){ P++; continue; }
            if(*P==']'){ P++; return a; }
            PERR=1; return NULL;
        }
    }
    if(*P=='"') return parse_string();
    if(!strncmp(P,"true",4)){ P+=4; JVal*v=newval(J_BOOL); v->b=1; return v; }
    if(!strncmp(P,"false",5)){ P+=5; JVal*v=newval(J_BOOL); return v; }
    if(!strncmp(P,"null",4)){ P+=4; return newval(J_NULL); }
    if(*P=='-'||(*P>='0'&&*P<='9')) return parse_number();
    PERR=1; return NULL;
}

static JVal *parse_json(const char*s){
    P=s; PERR=0;
    JVal*v=parse_value();
    if(PERR)return NULL;
    skipws();
    if(*P)return NULL;
    return v;
}

/* ---------- output helpers ---------- */
static void print_jstr(const char*s,size_t l){ Buf b={0}; bputjstr(&b,s,l); fwrite(b.d,1,b.n,stdout); free(b.d); }
static void print_id(JVal*id){
    if(id->t==J_STR) print_jstr(id->s,id->slen);
    else printf("%lld",id->i);
}
static void print_err(JVal*id,int code,const char*msg){
    printf("{\"jsonrpc\":\"2.0\",\"id\":");
    if(id)print_id(id); else fputs("null",stdout);
    printf(",\"error\":{\"code\":%d,\"message\":",code);
    print_jstr(msg,strlen(msg));
    fputs("}}\n",stdout);
}
static void print_result_raw(JVal*id,const char*result){
    printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
    printf(",\"result\":%s}\n",result);
}
static void print_tool(JVal*id,const char*text,size_t tl,int isErr,const char*structured,size_t sl){
    printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
    printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":");
    print_jstr(text,tl);
    if(structured){ fputs("}],\"structuredContent\":",stdout); fwrite(structured,1,sl,stdout); }
    fputs(isErr?"}],\"isError\":true}}\n":"}],\"isError\":false}}\n",stdout);
}

static const char *TOOLS_JSON =
"{\"tools\":[{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}},{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}},{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}},{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}},{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}]}";

/* ---------- kv store ---------- */
typedef struct { char*k; size_t kl; char*v; size_t vl; } KV;
static KV *store; static size_t nst,capst;
static long store_find(const char*k,size_t kl){
    for(size_t i=0;i<nst;i++)
        if(store[i].kl==kl&&!memcmp(store[i].k,k,kl)) return (long)i;
    return -1;
}

static int keycmp(const char*a,size_t al,const char*b,size_t bl){
    size_t m=al<bl?al:bl; int c=memcmp(a,b,m);
    if(c)return c<0?-1:1;
    return al<bl?-1:al>bl?1:0;
}

/* ---------- tools ---------- */
typedef struct { const char*name; int type; int required; int nonempty; } Prop;
typedef struct { const char*name; Prop props[3]; int nprops; int structured; } Tool;
static Tool tools[]={
    {"kv_set",{{"key",0,1,1},{"value",0,1,0}},2,0},
    {"kv_get",{{"key",0,1,1}},1,0},
    {"kv_list",{{"prefix",0,0,0}},1,1},
    {"sum",{{"numbers",1,1,1}},1,1},
    {"text_stats",{{"text",0,1,0}},1,1},
};
#define NTOOLS 5

static int validate(Tool*t,JVal*args,JVal**vals,Buf*msg){
    memset(msg,0,sizeof*msg);
    for(int i=0;i<3;i++)vals[i]=NULL;
    if(args && args->t!=J_OBJ){ bputs(msg,"arguments must be an object"); return 1; }
    const char*unk=NULL; size_t unkl=0;
    if(args){
        for(size_t i=0;i<args->n;i++){
            char*k=args->keys[i]; size_t kl=args->keyl[i];
            int found=0;
            for(int j=0;j<t->nprops;j++)
                if(strlen(t->props[j].name)==kl&&!memcmp(t->props[j].name,k,kl)){found=1;break;}
            if(!found && (!unk||keycmp(k,kl,unk,unkl)<0)){ unk=k; unkl=kl; }
        }
    }
    if(unk){ bputs(msg,"unknown argument: "); buf_put(msg,unk,unkl); return 1; }
    for(int j=0;j<t->nprops;j++){
        Prop*p=&t->props[j]; size_t pl=strlen(p->name);
        JVal*v=args?obj_getn(args,p->name,pl):NULL;
        if(!v){
            if(p->required){ bputs(msg,"missing required argument: "); bputs(msg,p->name); return 1; }
            continue;
        }
        vals[j]=v;
        if(p->type==0){
            if(v->t!=J_STR){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be a string"); return 1; }
            if(p->nonempty&&v->slen==0){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must not be empty"); return 1; }
        } else {
            if(v->t!=J_ARR){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be an array of integers"); return 1; }
            for(size_t i=0;i<v->n;i++){
                JVal*e=v->items[i];
                if(e->t!=J_NUM||!e->is_int){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be an array of integers"); return 1; }
            }
            if(p->nonempty&&v->n==0){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must not be empty"); return 1; }
        }
    }
    return 0;
}

/* ---------- input ---------- */
static char *readline(size_t*olen){
    int c=getchar();
    if(c==EOF)return NULL;
    size_t cap=128,n=0; char*b=xmalloc(cap);
    while(c!=EOF&&c!='\n'){
        if(n+2>cap){ cap*=2; b=xrealloc(b,cap); }
        b[n++]=(char)c; c=getchar();
    }
    b[n]=0; *olen=n; return b;
}

int main(void){
    char*line; size_t len;
    int initialized=0;
    while((line=readline(&len))!=NULL){
        int blank=1;
        for(size_t i=0;i<len;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'&&c!='\n'){ blank=0; break; }
        }
        if(blank){ free(line); continue; }

        JVal*m=parse_json(line);
        if(!m){ print_err(NULL,-32700,"Parse error"); free(line); continue; }
        if(m->t!=J_OBJ){ print_err(NULL,-32600,"Invalid Request"); free(line); continue; }

        JVal*method=obj_getn(m,"method",6);
        JVal*res=obj_getn(m,"result",6);
        JVal*err=obj_getn(m,"error",5);
        if(!method&&(res||err)){ free(line); continue; }

        JVal*id=obj_getn(m,"id",2);
        int idv = id && (id->t==J_STR || (id->t==J_NUM&&id->is_int));
        JVal*jr=obj_getn(m,"jsonrpc",7);
        int jok = jr && jr->t==J_STR && jr->slen==3 && !memcmp(jr->s,"2.0",3);
        int mok = method && method->t==J_STR;
        if(!jok||!mok||!idv){ print_err(idv?id:NULL,-32600,"Invalid Request"); free(line); continue; }
        if(!id){ free(line); continue; } /* notification */

        const char*meth=method->s; size_t ml=method->slen;
        JVal*params=obj_getn(m,"params",6);
        if(params && params->t!=J_OBJ){ print_err(id,-32602,"Invalid params"); free(line); continue; }

        #define IS(s) (ml==strlen(s)&&!memcmp(meth,s,strlen(s)))
        if(!(IS("initialize")||IS("ping")||IS("tools/list")||IS("tools/call"))){
            print_err(id,-32601,"Method not found"); free(line); continue;
        }
        if(!initialized && !(IS("initialize")||IS("ping"))){
            print_err(id,-32002,"Server not initialized"); free(line); continue;
        }

        if(IS("ping")){ print_result_raw(id,"{}"); free(line); continue; }
        if(IS("tools/list")){ print_result_raw(id,TOOLS_JSON); free(line); continue; }

        if(IS("initialize")){
            if(initialized){ print_err(id,-32600,"Already initialized"); free(line); continue; }
            JVal*pv=params?obj_getn(params,"protocolVersion",15):NULL;
            if(!params||!pv||pv->t!=J_STR){ print_err(id,-32602,"Invalid params"); free(line); continue; }
            initialized=1;
            int known=(pv->slen==10&&!memcmp(pv->s,"2025-06-18",10))
                    ||(pv->slen==10&&!memcmp(pv->s,"2025-03-26",10))
                    ||(pv->slen==10&&!memcmp(pv->s,"2024-11-05",10));
            printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
            printf(",\"result\":{\"protocolVersion\":");
            if(known) print_jstr(pv->s,pv->slen); else print_jstr("2025-06-18",10);
            printf(",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n");
            free(line); continue;
        }

        /* tools/call */
        JVal*name=params?obj_getn(params,"name",4):NULL;
        if(!name||name->t!=J_STR){ print_err(id,-32602,"Invalid params"); free(line); continue; }
        Tool*tool=NULL;
        for(int i=0;i<NTOOLS;i++)
            if(strlen(tools[i].name)==name->slen&&!memcmp(tools[i].name,name->s,name->slen)){ tool=&tools[i]; break; }
        if(!tool){
            Buf mb={0}; bputs(&mb,"Unknown tool: "); buf_put(&mb,name->s,name->slen);
            print_err(id,-32602,mb.d?mb.d:"Unknown tool:");
            free(line); continue;
        }
        JVal*args=obj_getn(params,"arguments",9);
        JVal*vals[3]; Buf msg={0};
        if(validate(tool,args,vals,&msg)){
            print_tool(id,msg.d,msg.n,1,NULL,0);
            free(line); continue;
        }

        if(!strcmp(tool->name,"kv_set")){
            JVal*k=vals[0],*v=vals[1];
            long idx=store_find(k->s,k->slen);
            int created = idx<0;
            if(created){
                if(nst==capst){ capst=capst?capst*2:8; store=xrealloc(store,capst*sizeof(KV)); }
                store[nst].k=xmalloc(k->slen+1); memcpy(store[nst].k,k->s,k->slen); store[nst].kl=k->slen;
                store[nst].v=xmalloc(v->slen+1); memcpy(store[nst].v,v->s,v->slen); store[nst].vl=v->slen;
                nst++;
            } else {
                free(store[idx].v);
                store[idx].v=xmalloc(v->slen+1); memcpy(store[idx].v,v->s,v->slen); store[idx].vl=v->slen;
            }
            Buf t={0}; bputs(&t,created?"created ":"updated "); buf_put(&t,k->s,k->slen);
            print_tool(id,t.d,t.n,0,NULL,0);
        } else if(!strcmp(tool->name,"kv_get")){
            JVal*k=vals[0];
            long idx=store_find(k->s,k->slen);
            if(idx<0){
                Buf t={0}; bputs(&t,"key not found: "); buf_put(&t,k->s,k->slen);
                print_tool(id,t.d,t.n,1,NULL,0);
            } else {
                print_tool(id,store[idx].v,store[idx].vl,0,NULL,0);
            }
        } else if(!strcmp(tool->name,"kv_list")){
            JVal*pre=vals[0];
            const char*pf=pre?pre->s:""; size_t pl=pre?pre->slen:0;
            KV**ks=xmalloc((nst?nst:1)*sizeof(KV*)); size_t nk=0;
            for(size_t i=0;i<nst;i++)
                if(store[i].kl>=pl&&!memcmp(store[i].k,pf,pl)) ks[nk++]=&store[i];
            for(size_t i=1;i<nk;i++){
                KV*kk=ks[i]; size_t j=i;
                while(j>0&&keycmp(kk->k,kk->kl,ks[j-1]->k,ks[j-1]->kl)<0){ ks[j]=ks[j-1]; j--; }
                ks[j]=kk;
            }
            Buf S={0}; bputs(&S,"{\"keys\":[");
            for(size_t i=0;i<nk;i++){ if(i)bputc(&S,','); bputjstr(&S,ks[i]->k,ks[i]->kl); }
            bputs(&S,"],\"count\":"); bputi(&S,(long long)nk); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        } else if(!strcmp(tool->name,"sum")){
            JVal*ns=vals[0]; long long s=0;
            for(size_t i=0;i<ns->n;i++) s+=ns->items[i]->i;
            Buf S={0}; bputs(&S,"{\"sum\":"); bputi(&S,s);
            bputs(&S,",\"count\":"); bputi(&S,(long long)ns->n); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        } else { /* text_stats */
            JVal*tx=vals[0];
            size_t bytes=tx->slen, cps=0;
            for(size_t i=0;i<bytes;i++)
                if((((unsigned char)tx->s[i])&0xC0)!=0x80) cps++;
            size_t w=0; int inword=0;
            for(size_t i=0;i<bytes;i++){
                char c=tx->s[i];
                int sep=(c==' '||c=='\t'||c=='\n'||c=='\r');
                if(sep) inword=0;
                else if(!inword){ inword=1; w++; }
            }
            Buf S={0}; bputs(&S,"{\"words\":"); bputi(&S,(long long)w);
            bputs(&S,",\"codepoints\":"); bputi(&S,(long long)cps);
            bputs(&S,",\"utf8_bytes\":"); bputi(&S,(long long)bytes); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        }
        free(line);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef enum { J_NULL, J_BOOL, J_NUM, J_STR, J_ARR, J_OBJ } JType;
typedef struct JVal JVal;
struct JVal {
    JType t;
    int b;
    int is_int;
    long long i;
    double d;
    char *s; size_t slen;
    JVal **items;
    char **keys; size_t *keyl;
    size_t n, cap;
};

static void *xmalloc(size_t n){ void*p=malloc(n?n:1); if(!p)exit(1); return p; }
static void *xrealloc(void*p,size_t n){ p=realloc(p,n?n:1); if(!p)exit(1); return p; }
static char *xstrdup(const char*s){ size_t l=strlen(s); char*r=xmalloc(l+1); memcpy(r,s,l+1); return r; }

typedef struct { char *d; size_t n, cap; } Buf;
static void buf_put(Buf*b,const char*s,size_t l){
    if(b->n+l+1>b->cap){ b->cap=(b->n+l+1)*2; b->d=xrealloc(b->d,b->cap); }
    memcpy(b->d+b->n,s,l); b->n+=l; b->d[b->n]=0;
}
static void bputs(Buf*b,const char*s){ buf_put(b,s,strlen(s)); }
static void bputc(Buf*b,char c){ buf_put(b,&c,1); }
static void bputi(Buf*b,long long v){ char t[32]; snprintf(t,sizeof t,"%lld",v); bputs(b,t); }
static void bputjstr(Buf*b,const char*s,size_t l){
    bputc(b,'"');
    for(size_t i=0;i<l;i++){
        unsigned char c=(unsigned char)s[i];
        switch(c){
        case '"': bputs(b,"\\\""); break;
        case '\\': bputs(b,"\\\\"); break;
        case '\n': bputs(b,"\\n"); break;
        case '\r': bputs(b,"\\r"); break;
        case '\t': bputs(b,"\\t"); break;
        case '\b': bputs(b,"\\b"); break;
        case '\f': bputs(b,"\\f"); break;
        default:
            if(c<0x20){ char t[8]; snprintf(t,sizeof t,"\\u%04x",c); bputs(b,t); }
            else bputc(b,(char)c);
        }
    }
    bputc(b,'"');
}

/* ---------- parser ---------- */
static const char *P; static int PERR;

static void skipws(void){ while(*P==' '||*P=='\t'||*P=='\r'||*P=='\n') P++; }
static JVal *newval(JType t){ JVal*v=xmalloc(sizeof *v); memset(v,0,sizeof *v); v->t=t; return v; }

static void arr_add(JVal*a,JVal*v){
    if(a->n==a->cap){ a->cap=a->cap?a->cap*2:8; a->items=xrealloc(a->items,a->cap*sizeof(JVal*)); }
    a->items[a->n++]=v;
}
static void obj_add(JVal*o,char*k,size_t kl,JVal*v){
    if(o->n==o->cap){
        o->cap=o->cap?o->cap*2:8;
        o->items=xrealloc(o->items,o->cap*sizeof(JVal*));
        o->keys=xrealloc(o->keys,o->cap*sizeof(char*));
        o->keyl=xrealloc(o->keyl,o->cap*sizeof(size_t));
    }
    o->keys[o->n]=k; o->keyl[o->n]=kl; o->items[o->n]=v; o->n++;
}
static JVal *obj_getn(JVal*o,const char*k,size_t kl){
    if(!o||o->t!=J_OBJ) return NULL;
    for(size_t i=0;i<o->n;i++)
        if(o->keyl[i]==kl && !memcmp(o->keys[i],k,kl)) return o->items[i];
    return NULL;
}

static unsigned hex4(void){
    unsigned v=0;
    for(int i=0;i<4;i++){
        char c=P[i]; unsigned d;
        if(c>='0'&&c<='9')d=c-'0';
        else if(c>='a'&&c<='f')d=c-'a'+10;
        else if(c>='A'&&c<='F')d=c-'A'+10;
        else { PERR=1; return 0; }
        v=v*16+d;
    }
    P+=4; return v;
}

static JVal *parse_string(void){
    if(*P!='"'){ PERR=1; return NULL; }
    P++;
    Buf b={0};
    while(1){
        unsigned char c=(unsigned char)*P;
        if(!c){ PERR=1; break; }
        if(c=='"'){ P++; break; }
        if(c=='\\'){
            P++;
            char e=*P++;
            if(e=='"')bputc(&b,'"');
            else if(e=='\\')bputc(&b,'\\');
            else if(e=='/')bputc(&b,'/');
            else if(e=='b')bputc(&b,'\b');
            else if(e=='f')bputc(&b,'\f');
            else if(e=='n')bputc(&b,'\n');
            else if(e=='r')bputc(&b,'\r');
            else if(e=='t')bputc(&b,'\t');
            else if(e=='u'){
                unsigned cp=hex4(); if(PERR)break;
                if(cp>=0xD800&&cp<=0xDBFF&&P[0]=='\\'&&P[1]=='u'){
                    const char*save=P; P+=2;
                    unsigned lo=hex4();
                    if(!PERR&&lo>=0xDC00&&lo<=0xDFFF)
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    else if(!PERR){ P=save; }
                }
                if(cp<0x80)bputc(&b,(char)cp);
                else if(cp<0x800){bputc(&b,(char)(0xC0|(cp>>6)));bputc(&b,(char)(0x80|(cp&63)));}
                else if(cp<0x10000){bputc(&b,(char)(0xE0|(cp>>12)));bputc(&b,(char)(0x80|((cp>>6)&63)));bputc(&b,(char)(0x80|(cp&63)));}
                else {bputc(&b,(char)(0xF0|(cp>>18)));bputc(&b,(char)(0x80|((cp>>12)&63)));bputc(&b,(char)(0x80|((cp>>6)&63)));bputc(&b,(char)(0x80|(cp&63)));}
            }
            else { PERR=1; break; }
        }
        else if(c<0x20){ PERR=1; break; }
        else { bputc(&b,(char)c); P++; }
    }
    if(PERR){ free(b.d); return NULL; }
    if(!b.d) b.d=xstrdup("");
    JVal*v=newval(J_STR); v->s=b.d; v->slen=b.n; return v;
}

static JVal *parse_number(void){
    const char*st=P;
    if(*P=='-')P++;
    if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; }
    if(*P=='0'){ P++; if(*P>='0'&&*P<='9'){ PERR=1; return NULL; } }
    else while(*P>='0'&&*P<='9')P++;
    int isint=1;
    if(*P=='.'){ isint=0; P++; if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; } while(*P>='0'&&*P<='9')P++; }
    if(*P=='e'||*P=='E'){ isint=0; P++; if(*P=='+'||*P=='-')P++; if(!(*P>='0'&&*P<='9')){ PERR=1; return NULL; } while(*P>='0'&&*P<='9')P++; }
    size_t l=P-st; char*t=xmalloc(l+1); memcpy(t,st,l); t[l]=0;
    JVal*v=newval(J_NUM); v->is_int=isint; v->d=strtod(t,NULL); if(isint)v->i=strtoll(t,NULL,10);
    free(t); return v;
}

static JVal *parse_value(void){
    skipws();
    if(*P=='{'){
        P++; JVal*o=newval(J_OBJ);
        skipws(); if(*P=='}'){ P++; return o; }
        while(1){
            skipws();
            JVal*k=parse_string(); if(PERR)return NULL;
            skipws(); if(*P!=':'){ PERR=1; return NULL; } P++;
            JVal*v=parse_value(); if(PERR)return NULL;
            obj_add(o,k->s,k->slen,v); free(k);
            skipws();
            if(*P==','){ P++; continue; }
            if(*P=='}'){ P++; return o; }
            PERR=1; return NULL;
        }
    }
    if(*P=='['){
        P++; JVal*a=newval(J_ARR);
        skipws(); if(*P==']'){ P++; return a; }
        while(1){
            JVal*v=parse_value(); if(PERR)return NULL;
            arr_add(a,v); skipws();
            if(*P==','){ P++; continue; }
            if(*P==']'){ P++; return a; }
            PERR=1; return NULL;
        }
    }
    if(*P=='"') return parse_string();
    if(!strncmp(P,"true",4)){ P+=4; JVal*v=newval(J_BOOL); v->b=1; return v; }
    if(!strncmp(P,"false",5)){ P+=5; JVal*v=newval(J_BOOL); return v; }
    if(!strncmp(P,"null",4)){ P+=4; return newval(J_NULL); }
    if(*P=='-'||(*P>='0'&&*P<='9')) return parse_number();
    PERR=1; return NULL;
}

static JVal *parse_json(const char*s){
    P=s; PERR=0;
    JVal*v=parse_value();
    if(PERR)return NULL;
    skipws();
    if(*P)return NULL;
    return v;
}

/* ---------- output helpers ---------- */
static void print_jstr(const char*s,size_t l){ Buf b={0}; bputjstr(&b,s,l); fwrite(b.d,1,b.n,stdout); free(b.d); }
static void print_id(JVal*id){
    if(id->t==J_STR) print_jstr(id->s,id->slen);
    else printf("%lld",id->i);
}
static void print_err(JVal*id,int code,const char*msg){
    printf("{\"jsonrpc\":\"2.0\",\"id\":");
    if(id)print_id(id); else fputs("null",stdout);
    printf(",\"error\":{\"code\":%d,\"message\":",code);
    print_jstr(msg,strlen(msg));
    fputs("}}\n",stdout);
}
static void print_result_raw(JVal*id,const char*result){
    printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
    printf(",\"result\":%s}\n",result);
}
static void print_tool(JVal*id,const char*text,size_t tl,int isErr,const char*structured,size_t sl){
    printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
    printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":");
    print_jstr(text,tl);
    if(structured){ fputs("}],\"structuredContent\":",stdout); fwrite(structured,1,sl,stdout); }
    fputs(isErr?"}],\"isError\":true}}\n":"}],\"isError\":false}}\n",stdout);
}

static const char *TOOLS_JSON =
"{\"tools\":[{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}},{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}},{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}},{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}},{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}]}";

/* ---------- kv store ---------- */
typedef struct { char*k; size_t kl; char*v; size_t vl; } KV;
static KV *store; static size_t nst,capst;
static long store_find(const char*k,size_t kl){
    for(size_t i=0;i<nst;i++)
        if(store[i].kl==kl&&!memcmp(store[i].k,k,kl)) return (long)i;
    return -1;
}

static int keycmp(const char*a,size_t al,const char*b,size_t bl){
    size_t m=al<bl?al:bl; int c=memcmp(a,b,m);
    if(c)return c<0?-1:1;
    return al<bl?-1:al>bl?1:0;
}

/* ---------- tools ---------- */
typedef struct { const char*name; int type; int required; int nonempty; } Prop;
typedef struct { const char*name; Prop props[3]; int nprops; int structured; } Tool;
static Tool tools[]={
    {"kv_set",{{"key",0,1,1},{"value",0,1,0}},2,0},
    {"kv_get",{{"key",0,1,1}},1,0},
    {"kv_list",{{"prefix",0,0,0}},1,1},
    {"sum",{{"numbers",1,1,1}},1,1},
    {"text_stats",{{"text",0,1,0}},1,1},
};
#define NTOOLS 5

static int validate(Tool*t,JVal*args,JVal**vals,Buf*msg){
    memset(msg,0,sizeof*msg);
    for(int i=0;i<3;i++)vals[i]=NULL;
    if(args && args->t!=J_OBJ){ bputs(msg,"arguments must be an object"); return 1; }
    const char*unk=NULL; size_t unkl=0;
    if(args){
        for(size_t i=0;i<args->n;i++){
            char*k=args->keys[i]; size_t kl=args->keyl[i];
            int found=0;
            for(int j=0;j<t->nprops;j++)
                if(strlen(t->props[j].name)==kl&&!memcmp(t->props[j].name,k,kl)){found=1;break;}
            if(!found && (!unk||keycmp(k,kl,unk,unkl)<0)){ unk=k; unkl=kl; }
        }
    }
    if(unk){ bputs(msg,"unknown argument: "); buf_put(msg,unk,unkl); return 1; }
    for(int j=0;j<t->nprops;j++){
        Prop*p=&t->props[j]; size_t pl=strlen(p->name);
        JVal*v=args?obj_getn(args,p->name,pl):NULL;
        if(!v){
            if(p->required){ bputs(msg,"missing required argument: "); bputs(msg,p->name); return 1; }
            continue;
        }
        vals[j]=v;
        if(p->type==0){
            if(v->t!=J_STR){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be a string"); return 1; }
            if(p->nonempty&&v->slen==0){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must not be empty"); return 1; }
        } else {
            if(v->t!=J_ARR){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be an array of integers"); return 1; }
            for(size_t i=0;i<v->n;i++){
                JVal*e=v->items[i];
                if(e->t!=J_NUM||!e->is_int){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must be an array of integers"); return 1; }
            }
            if(p->nonempty&&v->n==0){ bputs(msg,"argument "); bputs(msg,p->name); bputs(msg," must not be empty"); return 1; }
        }
    }
    return 0;
}

/* ---------- input ---------- */
static char *readline(size_t*olen){
    int c=getchar();
    if(c==EOF)return NULL;
    size_t cap=128,n=0; char*b=xmalloc(cap);
    while(c!=EOF&&c!='\n'){
        if(n+2>cap){ cap*=2; b=xrealloc(b,cap); }
        b[n++]=(char)c; c=getchar();
    }
    b[n]=0; *olen=n; return b;
}

int main(void){
    char*line; size_t len;
    int initialized=0;
    while((line=readline(&len))!=NULL){
        int blank=1;
        for(size_t i=0;i<len;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'&&c!='\n'){ blank=0; break; }
        }
        if(blank){ free(line); continue; }

        JVal*m=parse_json(line);
        if(!m){ print_err(NULL,-32700,"Parse error"); free(line); continue; }
        if(m->t!=J_OBJ){ print_err(NULL,-32600,"Invalid Request"); free(line); continue; }

        JVal*method=obj_getn(m,"method",6);
        JVal*res=obj_getn(m,"result",6);
        JVal*err=obj_getn(m,"error",5);
        if(!method&&(res||err)){ free(line); continue; }

        JVal*id=obj_getn(m,"id",2);
        int idv = id && (id->t==J_STR || (id->t==J_NUM&&id->is_int));
        JVal*jr=obj_getn(m,"jsonrpc",7);
        int jok = jr && jr->t==J_STR && jr->slen==3 && !memcmp(jr->s,"2.0",3);
        int mok = method && method->t==J_STR;
        if(!jok||!mok){ print_err(idv?id:NULL,-32600,"Invalid Request"); free(line); continue; }
        if(!id){ free(line); continue; } /* notification: ignore completely */
        if(!idv){ print_err(NULL,-32600,"Invalid Request"); free(line); continue; }

        const char*meth=method->s; size_t ml=method->slen;
        #define IS(s) (ml==strlen(s)&&!memcmp(meth,s,strlen(s)))
        if(!(IS("initialize")||IS("ping")||IS("tools/list")||IS("tools/call"))){
            print_err(id,-32601,"Method not found"); free(line); continue;
        }
        JVal*params=obj_getn(m,"params",6);
        if(params && params->t!=J_OBJ){ print_err(id,-32602,"Invalid params"); free(line); continue; }
        if(!initialized && !(IS("initialize")||IS("ping"))){
            print_err(id,-32002,"Server not initialized"); free(line); continue;
        }

        if(IS("ping")){ print_result_raw(id,"{}"); free(line); continue; }
        if(IS("tools/list")){ print_result_raw(id,TOOLS_JSON); free(line); continue; }

        if(IS("initialize")){
            if(initialized){ print_err(id,-32600,"Already initialized"); free(line); continue; }
            JVal*pv=params?obj_getn(params,"protocolVersion",15):NULL;
            if(!params||!pv||pv->t!=J_STR){ print_err(id,-32602,"Invalid params"); free(line); continue; }
            initialized=1;
            int known=(pv->slen==10&&!memcmp(pv->s,"2025-06-18",10))
                    ||(pv->slen==10&&!memcmp(pv->s,"2025-03-26",10))
                    ||(pv->slen==10&&!memcmp(pv->s,"2024-11-05",10));
            printf("{\"jsonrpc\":\"2.0\",\"id\":"); print_id(id);
            printf(",\"result\":{\"protocolVersion\":");
            if(known) print_jstr(pv->s,pv->slen); else print_jstr("2025-06-18",10);
            printf(",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n");
            free(line); continue;
        }

        /* tools/call */
        JVal*name=params?obj_getn(params,"name",4):NULL;
        if(!name||name->t!=J_STR){ print_err(id,-32602,"Invalid params"); free(line); continue; }
        Tool*tool=NULL;
        for(int i=0;i<NTOOLS;i++)
            if(strlen(tools[i].name)==name->slen&&!memcmp(tools[i].name,name->s,name->slen)){ tool=&tools[i]; break; }
        if(!tool){
            Buf mb={0}; bputs(&mb,"Unknown tool: "); buf_put(&mb,name->s,name->slen);
            print_err(id,-32602,mb.d?mb.d:"Unknown tool:");
            free(line); continue;
        }
        JVal*args=obj_getn(params,"arguments",9);
        JVal*vals[3]; Buf msg={0};
        if(validate(tool,args,vals,&msg)){
            print_tool(id,msg.d,msg.n,1,NULL,0);
            free(line); continue;
        }

        if(!strcmp(tool->name,"kv_set")){
            JVal*k=vals[0],*v=vals[1];
            long idx=store_find(k->s,k->slen);
            int created = idx<0;
            if(created){
                if(nst==capst){ capst=capst?capst*2:8; store=xrealloc(store,capst*sizeof(KV)); }
                store[nst].k=xmalloc(k->slen+1); memcpy(store[nst].k,k->s,k->slen); store[nst].kl=k->slen;
                store[nst].v=xmalloc(v->slen+1); memcpy(store[nst].v,v->s,v->slen); store[nst].vl=v->slen;
                nst++;
            } else {
                free(store[idx].v);
                store[idx].v=xmalloc(v->slen+1); memcpy(store[idx].v,v->s,v->slen); store[idx].vl=v->slen;
            }
            Buf t={0}; bputs(&t,created?"created ":"updated "); buf_put(&t,k->s,k->slen);
            print_tool(id,t.d,t.n,0,NULL,0);
        } else if(!strcmp(tool->name,"kv_get")){
            JVal*k=vals[0];
            long idx=store_find(k->s,k->slen);
            if(idx<0){
                Buf t={0}; bputs(&t,"key not found: "); buf_put(&t,k->s,k->slen);
                print_tool(id,t.d,t.n,1,NULL,0);
            } else {
                print_tool(id,store[idx].v,store[idx].vl,0,NULL,0);
            }
        } else if(!strcmp(tool->name,"kv_list")){
            JVal*pre=vals[0];
            const char*pf=pre?pre->s:""; size_t pl=pre?pre->slen:0;
            KV**ks=xmalloc((nst?nst:1)*sizeof(KV*)); size_t nk=0;
            for(size_t i=0;i<nst;i++)
                if(store[i].kl>=pl&&!memcmp(store[i].k,pf,pl)) ks[nk++]=&store[i];
            for(size_t i=1;i<nk;i++){
                KV*kk=ks[i]; size_t j=i;
                while(j>0&&keycmp(kk->k,kk->kl,ks[j-1]->k,ks[j-1]->kl)<0){ ks[j]=ks[j-1]; j--; }
                ks[j]=kk;
            }
            Buf S={0}; bputs(&S,"{\"keys\":[");
            for(size_t i=0;i<nk;i++){ if(i)bputc(&S,','); bputjstr(&S,ks[i]->k,ks[i]->kl); }
            bputs(&S,"],\"count\":"); bputi(&S,(long long)nk); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        } else if(!strcmp(tool->name,"sum")){
            JVal*ns=vals[0]; long long s=0;
            for(size_t i=0;i<ns->n;i++) s+=ns->items[i]->i;
            Buf S={0}; bputs(&S,"{\"sum\":"); bputi(&S,s);
            bputs(&S,",\"count\":"); bputi(&S,(long long)ns->n); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        } else { /* text_stats */
            JVal*tx=vals[0];
            size_t bytes=tx->slen, cps=0;
            for(size_t i=0;i<bytes;i++)
                if((((unsigned char)tx->s[i])&0xC0)!=0x80) cps++;
            size_t w=0; int inword=0;
            for(size_t i=0;i<bytes;i++){
                char c=tx->s[i];
                int sep=(c==' '||c=='\t'||c=='\n'||c=='\r');
                if(sep) inword=0;
                else if(!inword){ inword=1; w++; }
            }
            Buf S={0}; bputs(&S,"{\"words\":"); bputi(&S,(long long)w);
            bputs(&S,",\"codepoints\":"); bputi(&S,(long long)cps);
            bputs(&S,",\"utf8_bytes\":"); bputi(&S,(long long)bytes); bputc(&S,'}');
            print_tool(id,S.d,S.n,0,S.d,S.n);
        }
        free(line);
    }
    return 0;
}

use std::env;
use std::fs;
use std::path::Path;

// ---------- JSON ----------

#[derive(Clone, Debug)]
enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn get(&self, k: &str) -> Option<&J> {
        match self {
            J::Obj(v) => v.iter().find(|(key, _)| key == k).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> Option<&str> {
        match self {
            J::Str(s) => Some(s),
            _ => None,
        }
    }
    fn as_f64(&self) -> Option<f64> {
        match self {
            J::Num(n) => Some(*n),
            _ => None,
        }
    }
}

struct P {
    s: Vec<u8>,
    i: usize,
}

impl P {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn ws(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.i += 1;
        }
    }
    fn expect(&mut self, w: &[u8]) -> Option<()> {
        if self.s.get(self.i..self.i + w.len())? == w {
            self.i += w.len();
            Some(())
        } else {
            None
        }
    }
    fn val(&mut self) -> Option<J> {
        self.ws();
        match self.peek()? {
            b'{' => self.obj(),
            b'[' => self.arr(),
            b'"' => self.string().map(J::Str),
            b't' => {
                self.expect(b"true")?;
                Some(J::Bool(true))
            }
            b'f' => {
                self.expect(b"false")?;
                Some(J::Bool(false))
            }
            b'n' => {
                self.expect(b"null")?;
                Some(J::Null)
            }
            _ => self.number(),
        }
    }
    fn obj(&mut self) -> Option<J> {
        self.i += 1;
        let mut v = Vec::new();
        self.ws();
        if self.peek()? == b'}' {
            self.i += 1;
            return Some(J::Obj(v));
        }
        loop {
            self.ws();
            if self.peek()? != b'"' {
                return None;
            }
            let k = self.string()?;
            self.ws();
            if self.peek()? != b':' {
                return None;
            }
            self.i += 1;
            let val = self.val()?;
            v.push((k, val));
            self.ws();
            match self.peek()? {
                b',' => {
                    self.i += 1;
                }
                b'}' => {
                    self.i += 1;
                    break;
                }
                _ => return None,
            }
        }
        Some(J::Obj(v))
    }
    fn arr(&mut self) -> Option<J> {
        self.i += 1;
        let mut v = Vec::new();
        self.ws();
        if self.peek()? == b']' {
            self.i += 1;
            return Some(J::Arr(v));
        }
        loop {
            let val = self.val()?;
            v.push(val);
            self.ws();
            match self.peek()? {
                b',' => {
                    self.i += 1;
                }
                b']' => {
                    self.i += 1;
                    break;
                }
                _ => return None,
            }
        }
        Some(J::Arr(v))
    }
    fn hex4(&mut self) -> Option<u32> {
        let mut n = 0u32;
        for _ in 0..4 {
            let c = self.peek()?;
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return None,
            };
            n = n * 16 + d;
            self.i += 1;
        }
        Some(n)
    }
    fn string(&mut self) -> Option<String> {
        if self.peek()? != b'"' {
            return None;
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            let c = self.peek()?;
            self.i += 1;
            if c == b'"' {
                break;
            }
            if c == b'\\' {
                let e = self.peek()?;
                self.i += 1;
                match e {
                    b'u' => {
                        let cp = self.hex4()?;
                        if (0xD800..0xDC00).contains(&cp) {
                            if self.peek()? == b'\\' {
                                self.i += 1;
                                if self.peek()? == b'u' {
                                    self.i += 1;
                                    let lo = self.hex4()?;
                                    if (0xDC00..0xE000).contains(&lo) {
                                        let c = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        out.push(char::from_u32(c).unwrap_or('\u{FFFD}'));
                                    } else {
                                        out.push('\u{FFFD}');
                                        out.push(char::from_u32(lo).unwrap_or('\u{FFFD}'));
                                    }
                                } else {
                                    out.push('\u{FFFD}');
                                }
                            } else {
                                out.push('\u{FFFD}');
                            }
                        } else if (0xDC00..0xE000).contains(&cp) {
                            out.push('\u{FFFD}');
                        } else {
                            out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                        }
                    }
                    b'n' => out.push('\n'),
                    b't' => out.push('\t'),
                    b'r' => out.push('\r'),
                    b'b' => out.push('\u{0008}'),
                    b'f' => out.push('\u{000C}'),
                    b'/' => out.push('/'),
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    _ => return None,
                }
            } else {
                let len = if c < 0x80 {
                    1
                } else if c >> 5 == 0b110 {
                    2
                } else if c >> 4 == 0b1110 {
                    3
                } else {
                    4
                };
                let start = self.i - 1;
                let end = start + len;
                if end > self.s.len() {
                    return None;
                }
                out.push_str(std::str::from_utf8(&self.s[start..end]).ok()?);
                self.i = end;
            }
        }
        Some(out)
    }
    fn number(&mut self) -> Option<J> {
        let start = self.i;
        while let Some(c) = self.peek() {
            if matches!(c, b'0'..=b'9' | b'-' | b'+' | b'.' | b'e' | b'E') {
                self.i += 1;
            } else {
                break;
            }
        }
        if start == self.i {
            return None;
        }
        let t = std::str::from_utf8(&self.s[start..self.i]).ok()?;
        t.parse::<f64>().ok().map(J::Num)
    }
}

fn parse_json(s: &str) -> Option<J> {
    let mut p = P {
        s: s.as_bytes().to_vec(),
        i: 0,
    };
    let v = p.val()?;
    p.ws();
    if p.i != p.s.len() {
        None
    } else {
        Some(v)
    }
}

// ---------- base64url ----------

fn b64url(seg: &str) -> Option<Vec<u8>> {
    let n = seg.len();
    if n % 4 == 1 {
        return None;
    }
    let mut out = Vec::with_capacity(n * 3 / 4);
    let mut acc: u32 = 0;
    let mut bits: u32 = 0;
    for c in seg.bytes() {
        let v = match c {
            b'A'..=b'Z' => (c - b'A') as u32,
            b'a'..=b'z' => (c - b'a' + 26) as u32,
            b'0'..=b'9' => (c - b'0' + 52) as u32,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        };
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xFF) as u8);
            acc &= (1 << bits) - 1;
        }
    }
    if bits > 0 && (acc & ((1 << bits) - 1)) != 0 {
        return None;
    }
    Some(out)
}

// ---------- SHA-256 ----------

fn sha256(msg: &[u8]) -> [u8; 32] {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let ml = (msg.len() as u64) * 8;
    let mut m = msg.to_vec();
    m.push(0x80);
    while m.len() % 64 != 56 {
        m.push(0);
    }
    m.extend_from_slice(&ml.to_be_bytes());
    for ch in m.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([ch[4 * i], ch[4 * i + 1], ch[4 * i + 2], ch[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let chh = (e & f) ^ ((!e) & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(chh)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    let mut out = [0u8; 32];
    for i in 0..8 {
        out[4 * i..4 * i + 4].copy_from_slice(&h[i].to_be_bytes());
    }
    out
}

