        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let chh = (e & f) ^ ((!e) & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(chh)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    let mut out = [0u8; 64];
    for i in 0..8 {
        out[8 * i..8 * i + 8].copy_from_slice(&h[i].to_be_bytes());
    }
    out
}

fn sha512(msg: &[u8]) -> Vec<u8> {
    sha512_core(msg, IV512).to_vec()
}

fn sha384(msg: &[u8]) -> Vec<u8> {
    sha512_core(msg, IV384)[..48].to_vec()
}

fn sha256v(msg: &[u8]) -> Vec<u8> {
    sha256(msg).to_vec()
}

// ---------- HMAC ----------

fn hmac(key: &[u8], msg: &[u8], block: usize, hash: &dyn Fn(&[u8]) -> Vec<u8>) -> Vec<u8> {
    let mut k = key.to_vec();
    if k.len() > block {
        k = hash(&k);
    }
    k.resize(block, 0);
    let ipad: Vec<u8> = k.iter().map(|x| x ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|x| x ^ 0x5c).collect();
    let mut inner = ipad;
    inner.extend_from_slice(msg);
    let ih = hash(&inner);
    let mut outer = opad;
    outer.extend_from_slice(&ih);
    hash(&outer)
}

// ---------- config / verification ----------

struct Key {
    kid: String,
    alg: String,
    k: Vec<u8>,
}

struct Cfg {
    now: f64,
    leeway: f64,
    issuer: String,
    audience: String,
    keys: Vec<Key>,
}

fn verify(tok: &str, cfg: &Cfg) -> Result<(String, String), &'static str> {
    let parts: Vec<&str> = tok.split('.').collect();
    if parts.len() != 3 {
        return Err("MALFORMED");
    }
    for p in &parts {
        if p.is_empty() {
            return Err("MALFORMED");
        }
    }
    let hb = b64url(parts[0]).ok_or("MALFORMED")?;
    let pb = b64url(parts[1]).ok_or("MALFORMED")?;
    let sb = b64url(parts[2]).ok_or("MALFORMED")?;
    let hs = std::str::from_utf8(&hb).map_err(|_| "MALFORMED")?;
    let ps = std::str::from_utf8(&pb).map_err(|_| "MALFORMED")?;
    let h = parse_json(hs).ok_or("MALFORMED")?;
    let p = parse_json(ps).ok_or("MALFORMED")?;
    if !matches!(h, J::Obj(_)) || !matches!(p, J::Obj(_)) {
        return Err("MALFORMED");
    }
    // 2
    let alg = match h.get("alg").and_then(|j| j.as_str()) {
        Some(s) => s.to_string(),
        None => return Err("UNSUPPORTED_ALG"),
    };
    if !matches!(alg.as_str(), "HS256" | "HS384" | "HS512") {
        return Err("UNSUPPORTED_ALG");
    }
    // 3
    let kid = match h.get("kid").and_then(|j| j.as_str()) {
        Some(s) => s.to_string(),
        None => return Err("UNKNOWN_KEY"),
    };
    let key = cfg.keys.iter().find(|k| k.kid == kid).ok_or("UNKNOWN_KEY")?;
    // 4
    if key.alg != alg {
        return Err("ALG_MISMATCH");
    }
    // 5
    let (block, hashf): (usize, &dyn Fn(&[u8]) -> Vec<u8>) = match alg.as_str() {
        "HS256" => (64, &sha256v),
        "HS384" => (128, &sha384),
        _ => (128, &sha512),
    };
    let signing_input = format!("{}.{}", parts[0], parts[1]);
    let sig = hmac(&key.k, signing_input.as_bytes(), block, hashf);
    if sig != sb {
        return Err("BAD_SIGNATURE");
    }
    // 6
    if let Some(e) = p.get("exp").and_then(|j| j.as_f64()) {
        if cfg.now >= e + cfg.leeway {
            return Err("EXPIRED");
        }
    }
    // 7
    if let Some(n) = p.get("nbf").and_then(|j| j.as_f64()) {
        if cfg.now + cfg.leeway < n {
            return Err("NOT_YET_VALID");
        }
    }
    // 8
    match p.get("iss").and_then(|j| j.as_str()) {
        Some(s) if s == cfg.issuer => {}
        _ => return Err("BAD_ISSUER"),
    }
    // 9
    let aud_ok = match p.get("aud") {
        Some(J::Str(s)) => s == &cfg.audience,
        Some(J::Arr(a)) => a
            .iter()
            .any(|x| matches!(x, J::Str(s) if s == &cfg.audience)),
        _ => false,
    };
    if !aud_ok {
        return Err("BAD_AUDIENCE");
    }
    let sub = match p.get("sub").and_then(|j| j.as_str()) {
        Some(s) => s.to_string(),
        None => return Err("BAD_ISSUER"),
    };
    let mut scopes: Vec<String> = match p.get("scope").and_then(|j| j.as_str()) {
        Some(s) => s
            .split(' ')
            .filter(|x| !x.is_empty())
            .map(|x| x.to_string())
            .collect(),
        None => Vec::new(),
    };
    scopes.sort();
    scopes.dedup();
    Ok((sub, scopes.join(",")))
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let cfg_text = fs::read_to_string(Path::new(dir).join("config.json")).unwrap();
    let cfg_json = parse_json(&cfg_text).expect("bad config");
    let now = cfg_json.get("now").and_then(|j| j.as_f64()).unwrap_or(0.0);
    let leeway = cfg_json
        .get("leeway")
        .and_then(|j| j.as_f64())
        .unwrap_or(0.0);
    let issuer = cfg_json
        .get("issuer")
        .and_then(|j| j.as_str())
        .unwrap_or("")
        .to_string();
    let audience = cfg_json
        .get("audience")
        .and_then(|j| j.as_str())
        .unwrap_or("")
        .to_string();
    let mut keys = Vec::new();
    if let Some(J::Arr(arr)) = cfg_json.get("keys") {
        for k in arr {
            let kid = k.get("kid").and_then(|j| j.as_str()).unwrap_or("").to_string();
            let alg = k.get("alg").and_then(|j| j.as_str()).unwrap_or("").to_string();
            let kb64 = k.get("k").and_then(|j| j.as_str()).unwrap_or("");
            let k = b64url(kb64).unwrap_or_default();
            keys.push(Key { kid, alg, k });
        }
    }
    let cfg = Cfg {
        now,
        leeway,
        issuer,
        audience,
        keys,
    };

    let toks_text = fs::read_to_string(Path::new(dir).join("tokens.txt")).unwrap();
    let mut out = String::new();
    let mut valid = 0usize;
    let mut invalid = 0usize;
    for line in toks_text.lines() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        let n = valid + invalid + 1;
        match verify(t, &cfg) {
            Ok((sub, scopes)) => {
                valid += 1;
                out.push_str(&format!("{}: VALID sub={} scope={}\n", n, sub, scopes));
            }
            Err(e) => {
                invalid += 1;
                out.push_str(&format!("{}: {}\n", n, e));
            }
        }
    }
    out.push_str(&format!("\nvalid={} invalid={}\n", valid, invalid));
    print!("{}", out);
}

import java.nio.file.*;
import java.util.*;

public class Main {
    static java.io.PrintStream out;

    public static void main(String[] args) throws Exception {
        out = new java.io.PrintStream(new java.io.BufferedOutputStream(
                new java.io.FileOutputStream(java.io.FileDescriptor.out)), false);
        String src = Files.readString(Path.of(args[0], "program.tern"));
        try {
            List<Stmt> prog = new Parser(Lexer.lex(src)).parseProgram();
            Env builtins = new Env(null);
            Builtins.install(builtins);
            Env global = new Env(builtins);
            for (Stmt s : prog) s.exec(global);
        } catch (TernError e) {
            out.println("error at line " + e.line + ": " + e.msg);
        }
        out.flush();
    }

    static void execBlock(List<Stmt> b, Env e) throws TernError {
        for (Stmt s : b) s.exec(e);
    }

    static boolean truthy(Object v) {
        if (v == null) return false;
        if (v instanceof Long l) return l != 0;
        if (v instanceof Boolean b) return b;
        if (v instanceof String s) return !s.isEmpty();
        if (v instanceof TernList L) return !L.a.isEmpty();
        return true;
    }

    static boolean eq(Object a, Object b) {
        if (a == null) return b == null;
        if (b == null) return false;
        if (a instanceof Long x) return (b instanceof Long y) && x.longValue() == y.longValue();
        if (a instanceof Boolean x) return (b instanceof Boolean y) && x.booleanValue() == y.booleanValue();
        if (a instanceof String x) return (b instanceof String y) && x.equals(y);
        if (a instanceof TernList x) {
            if (!(b instanceof TernList y)) return false;
            if (x == y) return true;
            int n = x.a.size();
            if (n != y.a.size()) return false;
            for (int i = 0; i < n; i++) if (!eq(x.a.get(i), y.a.get(i))) return false;
            return true;
        }
        return a == b;
    }

    static String tn(Object v) {
        if (v == null) return "nil";
        if (v instanceof Long) return "int";
        if (v instanceof Boolean) return "bool";
        if (v instanceof String) return "string";
        if (v instanceof TernList) return "list";
        return "function";
    }

    static void quote(StringBuilder sb, String s) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '"': sb.append("\\\""); break;
                case '\n': sb.append("\\n"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        sb.append('"');
    }

    static void disp(StringBuilder sb, Object v, IdentityHashMap<TernList, Object> act) {
        if (v == null) { sb.append("nil"); return; }
        if (v instanceof Long || v instanceof Boolean || v instanceof String) { sb.append(v); return; }
        if (v instanceof TernList L) {
            if (act.containsKey(L)) { sb.append("[...]"); return; }
            act.put(L, null);
            sb.append('[');
            for (int i = 0; i < L.a.size(); i++) {
                if (i > 0) sb.append(", ");
                Object e = L.a.get(i);
                if (e instanceof String s) quote(sb, s);
                else disp(sb, e, act);
            }
            sb.append(']');
            act.remove(L);
            return;
        }
        sb.append("<fn>");
    }
}

class TernError extends RuntimeException {
    final int line; final String msg;
    TernError(int l, String m) { super(m, null, null, false); line = l; msg = m; }
}

class RetSig extends RuntimeException { final Object v; RetSig(Object v) { super(null, null, false); this.v = v; } }
class BreakSig extends RuntimeException { BreakSig() { super(null, null, false); } }
class ContinueSig extends RuntimeException { ContinueSig() { super(null, null, false); } }

class Token {
    static final int ID = 0, INT = 1, STR = 2, OP = 3, KW = 4, EOF = 5;
    final int type; final String s; final long v; final int line;
    Token(int t, String s, long v, int l) { type = t; this.s = s; this.v = v; line = l; }
}

class Lexer {
    static final String[] KWDS = {"let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil"};
    static List<Token> lex(String src) {
        List<Token> t = new ArrayList<>();
        int i = 0, line = 1, n = src.length();
        while (i < n) {
            char c = src.charAt(i);
            if (c == '\n') { line++; i++; continue; }
            if (c == ' ' || c == '\t' || c == '\r') { i++; continue; }
            if (c == '#') { while (i < n && src.charAt(i) != '\n') i++; continue; }
            if (c >= '0' && c <= '9') {
                int j = i;
                while (j < n && src.charAt(j) >= '0' && src.charAt(j) <= '9') j++;
                t.add(new Token(Token.INT, null, Long.parseLong(src.substring(i, j)), line));
                i = j; continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int j = i;
                while (j < n && (Character.isLetterOrDigit(src.charAt(j)) || src.charAt(j) == '_')) j++;
                String w = src.substring(i, j);
                boolean kw = false;
                for (String k : KWDS) if (k.equals(w)) { kw = true; break; }
                t.add(new Token(kw ? Token.KW : Token.ID, w, 0, line));
                i = j; continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (src.charAt(i) != '"') {
                    char d = src.charAt(i);
                    if (d == '\\') {
                        char e2 = src.charAt(i + 1);
                        if (e2 == 'n') sb.append('\n');
                        else if (e2 == 't') sb.append('\t');
                        else if (e2 == '"') sb.append('"');
                        else sb.append('\\');
                        i += 2;
                    } else { sb.append(d); i++; }
                }
                i++;
                t.add(new Token(Token.STR, sb.toString(), 0, line));
                continue;
            }
            if (i + 1 < n) {
                String two = src.substring(i, i + 2);
                if (two.equals("==") || two.equals("!=") || two.equals("<=") || two.equals(">=")) {
                    t.add(new Token(Token.OP, two, 0, line)); i += 2; continue;
                }
            }
            t.add(new Token(Token.OP, String.valueOf(c), 0, line)); i++;
        }
        t.add(new Token(Token.EOF, null, 0, line));
        return t;
    }
}

class Env {
    final Env parent;
    final HashMap<String, Object> map = new HashMap<>();
    Env(Env p) { parent = p; }
    Object get(String n, int line) throws TernError {
        for (Env e = this; e != null; e = e.parent) if (e.map.containsKey(n)) return e.map.get(n);
        throw new TernError(line, "undefined variable " + n);
    }
    void set(String n, Object v, int line) throws TernError {
        for (Env e = this; e != null; e = e.parent) if (e.map.containsKey(n)) { e.map.put(n, v); return; }
        throw new TernError(line, "undefined variable " + n);
    }
    void declare(String n, Object v) { map.put(n, v); }
}

class TernList { final ArrayList<Object> a = new ArrayList<>(); }
class Func { final String[] params; final List<Stmt> body; final Env closure;
    Func(String[] p, List<Stmt> b, Env c) { params = p; body = b; closure = c; } }

abstract class Builtin {
    final String name; final int arity;
    Builtin(String n, int a) { name = n; arity = a; }
    abstract Object call(Object[] args, int line) throws TernError;
}

class Builtins {
    static void install(Env e) {
        e.declare("print", new Builtin("print", -1) {
            Object call(Object[] a, int line) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < a.length; i++) {
                    if (i > 0) sb.append(' ');
                    Main.disp(sb, a[i], new IdentityHashMap<>());
                }
                sb.append('\n');
                Main.out.print(sb);
                return null;
            }
        });
        e.declare("str", new Builtin("str", 1) {
            Object call(Object[] a, int line) {
                StringBuilder sb = new StringBuilder();
                Main.disp(sb, a[0], new IdentityHashMap<>());
                return sb.toString();
            }
        });
        e.declare("type", new Builtin("type", 1) {
            Object call(Object[] a, int line) { return Main.tn(a[0]); }
        });
        e.declare("len", new Builtin("len", 1) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof String s) return (long) s.length();
                if (a[0] instanceof TernList L) return (long) L.a.size();
                throw new TernError(line, "bad argument to len");
            }
        });
        e.declare("push", new Builtin("push", 2) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof TernList L) { L.a.add(a[1]); return null; }
                throw new TernError(line, "bad argument to push");
            }
        });
        e.declare("pop", new Builtin("pop", 1) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof TernList L) {
                    int n = L.a.size();
                    if (n == 0) throw new TernError(line, "bad argument to pop");
                    return L.a.remove(n - 1);
                }
                throw new TernError(line, "bad argument to pop");
            }
        });
        e.declare("range", new Builtin("range", 2) {
            Object call(Object[] a, int line) throws TernError {
                if (!(a[0] instanceof Long) || !(a[1] instanceof Long))
                    throw new TernError(line, "bad argument to range");
                long A = (Long) a[0], B = (Long) a[1];
                TernList L = new TernList();
                for (long i = A; i < B; i++) L.a.add(i);
                return L;
            }
        });
        e.declare("slice", new Builtin("slice", 3) {
            Object call(Object[] a, int line) throws TernError {
                if (!(a[1] instanceof Long) || !(a[2] instanceof Long))
                    throw new TernError(line, "bad argument to slice");
                int A = (int) (long) (Long) a[1], B = (int) (long) (Long) a[2];
                if (a[0] instanceof String s) {
                    if (A < 0 || B > s.length() || A > B) throw new TernError(line, "bad argument to slice");
                    return s.substring(A, B);
                }
                if (a[0] instanceof TernList L) {
                    if (A < 0 || B > L.a.size() || A > B) throw new TernError(line, "bad argument to slice");
                    TernList R = new TernList();
                    R.a.addAll(L.a.subList(A, B));
                    return R;
                }
                throw new TernError(line, "bad argument to slice");
            }
        });
    }
}

abstract class Expr { abstract Object eval(Env e) throws TernError; }

class Lit extends Expr { final Object v; Lit(Object v) { this.v = v; } Object eval(Env e) { return v; } }

class NameExpr extends Expr { final String n; final int line;
    NameExpr(String n, int l) { this.n = n; line = l; }
    Object eval(Env e) throws TernError { return e.get(n, line); } }

class ListLit extends Expr { final Expr[] es;
    ListLit(Expr[] es) { this.es = es; }
    Object eval(Env e) throws TernError {
        TernList L = new TernList();
        for (Expr x : es) L.a.add(x.eval(e));
        return L;
    } }

class FnLit extends Expr { final String[] params; final List<Stmt> body;
    FnLit(String[] p, List<Stmt> b) { params = p; body = b; }
    Object eval(Env e) { return new Func(params, body, e); } }

class Neg extends Expr { final Expr x; final int line;
    Neg(Expr x, int l) { this.x = x; line = l; }
    Object eval(Env e) throws TernError {
        Object v = x.eval(e);
        if (v instanceof Long) {
            try { return Math.negateExact((Long) v); }
            catch (ArithmeticException ex) { throw new TernError(line, "integer overflow"); }
        }
        throw new TernError(line, "cannot apply - to " + Main.tn(v));
    } }

class Not extends Expr { final Expr x;
    Not(Expr x) { this.x = x; }
    Object eval(Env e) throws TernError { return !Main.truthy(x.eval(e)); } }

class And extends Expr { final Expr l, r;
    And(Expr l, Expr r) { this.l = l; this.r = r; }
    Object eval(Env e) throws TernError { Object a = l.eval(e); return Main.truthy(a) ? r.eval(e) : a; } }

class Or extends Expr { final Expr l, r;
    Or(Expr l, Expr r) { this.l = l; this.r = r; }
    Object eval(Env e) throws TernError { Object a = l.eval(e); return Main.truthy(a) ? a : r.eval(e); } }

class Binary extends Expr {
    final String op; final Expr l, r; final int line;
    Binary(String op, Expr l, Expr r, int line) { this.op = op; this.l = l; this.r = r; this.line = line; }
    Object eval(Env e) throws TernError {
        Object a = l.eval(e), b = r.eval(e);
        switch (op) {
            case "+":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.addExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                if (a instanceof String && b instanceof String) return (String) a + (String) b;
                if (a instanceof TernList && b instanceof TernList) {
                    TernList R = new TernList();
                    R.a.addAll(((TernList) a).a);
                    R.a.addAll(((TernList) b).a);
                    return R;
                }
                break;
            case "-":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.subtractExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                break;
            case "*":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.multiplyExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                break;
            case "/":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    if (y == 0) throw new TernError(line, "division by zero");
                    if (x == Long.MIN_VALUE && y == -1) throw new TernError(line, "integer overflow");
                    return x / y;
                }
                break;
            case "%":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    if (y == 0) throw new TernError(line, "division by zero");
                    return x % y;
                }
                break;
            case "<": case "<=": case ">": case ">=":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    switch (op) {
                        case "<": return x < y;
                        case "<=": return x <= y;
                        case ">": return x > y;
                        default: return x >= y;
                    }
                }
                if (a instanceof String && b instanceof String) {
                    int c = ((String) a).compareTo((String) b);
                    switch (op) {
                        case "<": return c < 0;
                        case "<=": return c <= 0;
                        case ">": return c > 0;
                        default: return c >= 0;
                    }
                }
                break;
            case "==": return Main.eq(a, b);
            case "!=": return !Main.eq(a, b);
        }
        throw new TernError(line, "cannot apply " + op + " to " + Main.tn(a) + " and " + Main.tn(b));
    }
}

class Call extends Expr {
    final Expr callee; final Expr[] args; final int line;
    Call(Expr c, Expr[] a, int l) { callee = c; args = a; line = l; }
    Object eval(Env e) throws TernError {
        Object c = callee.eval(e);
        Object[] av = new Object[args.length];
        for (int i = 0; i < args.length; i++) av[i] = args[i].eval(e);
        if (c instanceof Func f) {
            if (f.params.length != av.length)
                throw new TernError(line, "expected " + f.params.length + " arguments, got " + av.length);
            Env ne = new Env(f.closure);
            for (int i = 0; i < av.length; i++) ne.declare(f.params[i], av[i]);
            try {
                for (Stmt s : f.body) s.exec(ne);
            } catch (RetSig r) { return r.v; }
            return null;
        }
        if (c instanceof Builtin b) {
            if (b.arity >= 0 && av.length != b.arity)
                throw new TernError(line, "expected " + b.arity + " arguments, got " + av.length);
            return b.call(av, line);
        }
        throw new TernError(line, "cannot call " + Main.tn(c));
    }
}

class Index extends Expr {
    final Expr obj, idx; final int line;
    Index(Expr o, Expr i, int l) { obj = o; idx = i; line = l; }
    Object eval(Env e) throws TernError {
        Object x = obj.eval(e), i = idx.eval(e);
        if (x instanceof TernList L) {
            if (!(i instanceof Long)) throw new TernError(line, "cannot index list with " + Main.tn(i));
            int I = (int) (long) (Long) i;
            if (I < 0 || I >= L.a.size())
                throw new TernError(line, "index " + I + " out of range for length " + L.a.size());
            return L.a.get(I);
        }
        if (x instanceof String s) {
            if (!(i instanceof Long)) throw new TernError(line, "cannot index string with " + Main.tn(i));
            int I = (int) (long) (Long) i;
            if (I < 0 || I >= s.length())
                throw new TernError(line, "index " + I + " out of range for length " + s.length());
            return String.valueOf(s.charAt(I));
        }
        throw new TernError(line, "cannot index " + Main.tn(x) + " with " + Main.tn(i));
    }
}

abstract class Stmt { abstract void exec(Env e) throws TernError; }

class Let extends Stmt { final String n; final Expr x;
    Let(String n, Expr x) { this.n = n; this.x = x; }
    void exec(Env e) throws TernError { e.declare(n, x.eval(e)); } }

class FnStmt extends Stmt { final String n; final String[] params; final List<Stmt> body;
    FnStmt(String n, String[] p, List<Stmt> b) { this.n = n; params = p; body = b; }
    void exec(Env e) { e.declare(n, new Func(params, body, e)); } }

class ExprStmt extends Stmt { final Expr x; ExprStmt(Expr x) { this.x = x; }
    void exec(Env e) throws TernError { x.eval(e); } }

class Assign extends Stmt { final String n; final Expr x; final int line;
    Assign(String n, Expr x, int l) { this.n = n; this.x = x; line = l; }
    void exec(Env e) throws TernError { e.set(n, x.eval(e), line); } }

class IndexAssign extends Stmt {
    final Expr obj, idx, val; final int line;
    IndexAssign(Expr o, Expr i, Expr v, int l) { obj = o; idx = i; val = v; line = l; }
    void exec(Env e) throws TernError {
        Object x = obj.eval(e), i = idx.eval(e), v = val.eval(e);
        if (!(x instanceof TernList)) throw new TernError(line, "cannot assign into " + Main.tn(x));
        TernList L = (TernList) x;
        if (!(i instanceof Long)) throw new TernError(line, "cannot index list with " + Main.tn(i));
        int I = (int) (long) (Long) i;
        if (I < 0 || I >= L.a.size())
            throw new TernError(line, "index " + I + " out of range for length " + L.a.size());
        L.a.set(I, v);
    }
}

class If extends Stmt {
    final Expr c; final List<Stmt> then; final Object els;
    If(Expr c, List<Stmt> t, Object e) { this.c = c; then = t; els = e; }
    void exec(Env e) throws TernError {
        if (Main.truthy(c.eval(e))) Main.execBlock(then, new Env(e));
        else if (els != null) {
            if (els instanceof If) ((If) els).exec(e);
            else Main.execBlock((List<Stmt>) els, new Env(e));
        }
    }
}

class While extends Stmt {
    final Expr c; final List<Stmt> body;
    While(Expr c, List<Stmt> b) { this.c = c; body = b; }
    void exec(Env e) throws TernError {
        while (Main.truthy(c.eval(e))) {
            Env be = new Env(e);
            try { Main.execBlock(body, be); }
            catch (BreakSig s) { break; }
            catch (ContinueSig s) {}
        }
    }
}

class For extends Stmt {
    final String var; final Expr xs; final List<Stmt> body; final int line;
    For(String v, Expr x, List<Stmt> b, int l) { var = v; xs = x; body = b; line = l; }
    void exec(Env e) throws TernError {
        Object o = xs.eval(e);
        if (!(o instanceof TernList)) throw new TernError(line, "cannot iterate " + Main.tn(o));
        TernList L = (TernList) o;
        int i = 0;
        while (i < L.a.size()) {
            Env be = new Env(e);
            be.declare(var, L.a.get(i));
            try { Main.execBlock(body, be); }
            catch (BreakSig s) { break; }
            catch (ContinueSig s) {}
            i++;
        }
    }
}

class Ret extends Stmt { final Expr x; Ret(Expr x) { this.x = x; }
    void exec(Env e) throws TernError { throw new RetSig(x == null ? null : x.eval(e)); } }
class BreakS extends Stmt { void exec(Env e) { throw new BreakSig(); } }
class ContinueS extends Stmt { void exec(Env e) { throw new ContinueSig(); } }

class Parser {
    List<Token> t; int p;
    Parser(List<Token> t) { this.t = t; }
    Token peek() { return t.get(p); }
    Token next() { return t.get(p++); }
    boolean isOp(String o) { Token k = peek(); return k.type == Token.OP && k.s.equals(o); }
    boolean matchOp(String o) { if (isOp(o)) { p++; return true; } return false; }
    boolean matchKw(String o) { Token k = peek(); if (k.type == Token.KW && k.s.equals(o)) { p++; return true; } return false; }
    Token expectOp(String o) { if (!matchOp(o)) throw new RuntimeException("syntax error"); return t.get(p - 1); }
    Token expectId() { Token k = peek(); if (k.type != Token.ID) throw new RuntimeException("syntax error"); p++; return k; }

    List<Stmt> parseProgram() {
        ArrayList<Stmt> s = new ArrayList<>();
        while (peek().type != Token.EOF) s.add(parseStmt());
        return s;
    }

    List<Stmt> block() {
        expectOp("{");
        ArrayList<Stmt> s = new ArrayList<>();
        while (!isOp("}")) s.add(parseStmt());
        expectOp("}");
        return s;
    }

    String[] params() {
        ArrayList<String> ps = new ArrayList<>();
        if (peek().type == Token.ID) {
            ps.add(next().s);
            while (matchOp(",")) ps.add(expectId().s);
        }
        return ps.toArray(new String[0]);
    }

    Stmt parseStmt() {
        Token k = peek();
        if (k.type == Token.KW) {
            switch (k.s) {
                case "let": {
                    next();
                    Token name = expectId();
                    expectOp("=");
                    Expr e = expr();
                    expectOp(";");
                    return new Let(name.s, e);
                }
                case "fn": {
                    next();
                    Token name = expectId();
                    expectOp("(");
                    String[] ps = params();
                    expectOp(")");
                    return new FnStmt(name.s, ps, block());
                }
                case "if": return parseIf();
                case "while": {
                    next();
                    Expr c = expr();
                    return new While(c, block());
                }
                case "for": {
                    int line = k.line;
                    next();
                    Token name = expectId();
                    expectKw("in");
                    Expr e = expr();
                    return new For(name.s, e, block(), line);
                }
                case "return": {
                    next();
                    Expr e = null;
                    if (!isOp(";")) e = expr();
                    expectOp(";");
                    return new Ret(e);
                }
                case "break": next(); expectOp(";"); return new BreakS();
                case "continue": next(); expectOp(";"); return new ContinueS();
            }
        }
        Expr e = expr();
        if (matchOp("=")) {
            if (e instanceof NameExpr ne) {
                Expr v = expr();
                expectOp(";");
                return new Assign(ne.n, v, ne.line);
            }
            if (e instanceof Index ix) {
                Expr v = expr();
                expectOp(";");
                return new IndexAssign(ix.obj, ix.idx, v, ix.line);
            }
            throw new RuntimeException("syntax error");
        }
        expectOp(";");
        return new ExprStmt(e);
    }

    Stmt parseIf() {
        next(); // if
        Expr c = expr();
        List<Stmt> b = block();
        Object els = null;
        if (matchKw("else")) {
            if (peek().type == Token.KW && peek().s.equals("if")) els = parseIf();
            else els = block();
        }
        return new If(c, b, els);
    }

    Expr expr() { return parseOr(); }

    Expr parseOr() {
        Expr l = parseAnd();
        while (matchKw("or")) l = new Or(l, parseAnd());
        return l;
    }

    Expr parseAnd() {
        Expr l = parseNot();
        while (matchKw("and")) l = new And(l, parseNot());
        return l;
    }

    Expr parseNot() {
        if (matchKw("not")) return new Not(parseNot());
        return parseCmp();
    }

    Expr parseCmp() {
        Expr l = parseAdd();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("==") || k.s.equals("!=") || k.s.equals("<")
                    || k.s.equals("<=") || k.s.equals(">") || k.s.equals(">="))) {
                next();
                l = new Binary(k.s, l, parseAdd(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseAdd() {
        Expr l = parseMul();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("+") || k.s.equals("-"))) {
                next();
                l = new Binary(k.s, l, parseMul(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseMul() {
        Expr l = parseUnary();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("*") || k.s.equals("/") || k.s.equals("%"))) {
                next();
                l = new Binary(k.s, l, parseUnary(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseUnary() {
        if (matchOp("-")) {
            Token k = t.get(p - 1);
            return new Neg(parseUnary(), k.line);
        }
        return parsePostfix();
    }

    Expr parsePostfix() {
        Expr e = parsePrimary();
        while (true) {
            if (matchOp("(")) {
                int line = t.get(p - 1).line;
                ArrayList<Expr> args = new ArrayList<>();
                if (!isOp(")")) {
                    args.add(expr());
                    while (matchOp(",")) args.add(expr());
                }
                expectOp(")");
                e = new Call(e, args.toArray(new Expr[0]), line);
            } else if (matchOp("[")) {
                int line = t.get(p - 1).line;
                Expr i = expr();
                expectOp("]");
                e = new Index(e, i, line);
            } else break;
        }
        return e;
    }

    Expr parsePrimary() {
        Token k = peek();
        if (k.type == Token.INT) { next(); return new Lit(k.v); }
        if (k.type == Token.STR) { next(); return new Lit(k.s); }
        if (k.type == Token.ID) { next(); return new NameExpr(k.s, k.line); }
        if (k.type == Token.KW) {
            switch (k.s) {
                case "true": next(); return new Lit(Boolean.TRUE);
                case "false": next(); return new Lit(Boolean.FALSE);
                case "nil": next(); return new Lit(null);
                case "fn": {
                    next();
                    expectOp("(");
                    String[] ps = params();
                    expectOp(")");
                    return new FnLit(ps, block());
                }
            }
        }
        if (matchOp("(")) { Expr e = expr(); expectOp(")"); return e; }
        if (matchOp("[")) {
            ArrayList<Expr> es = new ArrayList<>();
            if (!isOp("]")) {
                es.add(expr());
                while (matchOp(",")) es.add(expr());
            }
            expectOp("]");
            return new ListLit(es.toArray(new Expr[0]));
        }
        throw new RuntimeException("syntax error");
    }
}

import java.nio.file.*;
import java.util.*;

public class Main {
    static java.io.PrintStream out;

    public static void main(String[] args) throws Exception {
        out = new java.io.PrintStream(new java.io.BufferedOutputStream(
                new java.io.FileOutputStream(java.io.FileDescriptor.out)), false);
        String src = Files.readString(Path.of(args[0], "program.tern"));
        try {
            List<Stmt> prog = new Parser(Lexer.lex(src)).parseProgram();
            Env builtins = new Env(null);
            Builtins.install(builtins);
            Env global = new Env(builtins);
            for (Stmt s : prog) s.exec(global);
        } catch (TernError e) {
            out.println("error at line " + e.line + ": " + e.msg);
        }
        out.flush();
    }

    static void execBlock(List<Stmt> b, Env e) throws TernError {
        for (Stmt s : b) s.exec(e);
    }

    static boolean truthy(Object v) {
        if (v == null) return false;
        if (v instanceof Long l) return l != 0;
        if (v instanceof Boolean b) return b;
        if (v instanceof String s) return !s.isEmpty();
        if (v instanceof TernList L) return !L.a.isEmpty();
        return true;
    }

    static boolean eq(Object a, Object b) {
        if (a == null) return b == null;
        if (b == null) return false;
        if (a instanceof Long x) return (b instanceof Long y) && x.longValue() == y.longValue();
        if (a instanceof Boolean x) return (b instanceof Boolean y) && x.booleanValue() == y.booleanValue();
        if (a instanceof String x) return (b instanceof String y) && x.equals(y);
        if (a instanceof TernList x) {
            if (!(b instanceof TernList y)) return false;
            if (x == y) return true;
            int n = x.a.size();
            if (n != y.a.size()) return false;
            for (int i = 0; i < n; i++) if (!eq(x.a.get(i), y.a.get(i))) return false;
            return true;
        }
        return a == b;
    }

    static String tn(Object v) {
        if (v == null) return "nil";
        if (v instanceof Long) return "int";
        if (v instanceof Boolean) return "bool";
        if (v instanceof String) return "string";
        if (v instanceof TernList) return "list";
        return "function";
    }

    static void quote(StringBuilder sb, String s) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '"': sb.append("\\\""); break;
                case '\n': sb.append("\\n"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        sb.append('"');
    }

    static void disp(StringBuilder sb, Object v, IdentityHashMap<TernList, Object> act) {
        if (v == null) { sb.append("nil"); return; }
        if (v instanceof Long || v instanceof Boolean || v instanceof String) { sb.append(v); return; }
        if (v instanceof TernList L) {
            if (act.containsKey(L)) { sb.append("[...]"); return; }
            act.put(L, null);
            sb.append('[');
            for (int i = 0; i < L.a.size(); i++) {
                if (i > 0) sb.append(", ");
                Object e = L.a.get(i);
                if (e instanceof String s) quote(sb, s);
                else disp(sb, e, act);
            }
            sb.append(']');
            act.remove(L);
            return;
        }
        sb.append("<fn>");
    }
}

class TernError extends RuntimeException {
    final int line; final String msg;
    TernError(int l, String m) { super(m, (Throwable) null, false, false); line = l; msg = m; }
}

class RetSig extends RuntimeException { final Object v; RetSig(Object v) { super((String) null, (Throwable) null, false, false); this.v = v; } }
class BreakSig extends RuntimeException { BreakSig() { super((String) null, (Throwable) null, false, false); } }
class ContinueSig extends RuntimeException { ContinueSig() { super((String) null, (Throwable) null, false, false); } }

class Token {
    static final int ID = 0, INT = 1, STR = 2, OP = 3, KW = 4, EOF = 5;
    final int type; final String s; final long v; final int line;
    Token(int t, String s, long v, int l) { type = t; this.s = s; this.v = v; line = l; }
}

class Lexer {
    static final String[] KWDS = {"let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil"};
    static List<Token> lex(String src) {
        List<Token> t = new ArrayList<>();
        int i = 0, line = 1, n = src.length();
        while (i < n) {
            char c = src.charAt(i);
            if (c == '\n') { line++; i++; continue; }
            if (c == ' ' || c == '\t' || c == '\r') { i++; continue; }
            if (c == '#') { while (i < n && src.charAt(i) != '\n') i++; continue; }
            if (c >= '0' && c <= '9') {
                int j = i;
                while (j < n && src.charAt(j) >= '0' && src.charAt(j) <= '9') j++;
                t.add(new Token(Token.INT, null, Long.parseLong(src.substring(i, j)), line));
                i = j; continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int j = i;
                while (j < n && (Character.isLetterOrDigit(src.charAt(j)) || src.charAt(j) == '_')) j++;
                String w = src.substring(i, j);
                boolean kw = false;
                for (String k : KWDS) if (k.equals(w)) { kw = true; break; }
                t.add(new Token(kw ? Token.KW : Token.ID, w, 0, line));
                i = j; continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (src.charAt(i) != '"') {
                    char d = src.charAt(i);
                    if (d == '\\') {
                        char e2 = src.charAt(i + 1);
                        if (e2 == 'n') sb.append('\n');
                        else if (e2 == 't') sb.append('\t');
                        else if (e2 == '"') sb.append('"');
                        else sb.append('\\');
                        i += 2;
                    } else { sb.append(d); i++; }
                }
                i++;
                t.add(new Token(Token.STR, sb.toString(), 0, line));
                continue;
            }
            if (i + 1 < n) {
                String two = src.substring(i, i + 2);
                if (two.equals("==") || two.equals("!=") || two.equals("<=") || two.equals(">=")) {
                    t.add(new Token(Token.OP, two, 0, line)); i += 2; continue;
                }
            }
            t.add(new Token(Token.OP, String.valueOf(c), 0, line)); i++;
        }
        t.add(new Token(Token.EOF, null, 0, line));
        return t;
    }
}

class Env {
    final Env parent;
    final HashMap<String, Object> map = new HashMap<>();
    Env(Env p) { parent = p; }
    Object get(String n, int line) throws TernError {
        for (Env e = this; e != null; e = e.parent) if (e.map.containsKey(n)) return e.map.get(n);
        throw new TernError(line, "undefined variable " + n);
    }
    void set(String n, Object v, int line) throws TernError {
        for (Env e = this; e != null; e = e.parent) if (e.map.containsKey(n)) { e.map.put(n, v); return; }
        throw new TernError(line, "undefined variable " + n);
    }
    void declare(String n, Object v) { map.put(n, v); }
}

class TernList { final ArrayList<Object> a = new ArrayList<>(); }
class Func { final String[] params; final List<Stmt> body; final Env closure;
    Func(String[] p, List<Stmt> b, Env c) { params = p; body = b; closure = c; } }

abstract class Builtin {
    final String name; final int arity;
    Builtin(String n, int a) { name = n; arity = a; }
    abstract Object call(Object[] args, int line) throws TernError;
}

class Builtins {
    static void install(Env e) {
        e.declare("print", new Builtin("print", -1) {
            Object call(Object[] a, int line) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < a.length; i++) {
                    if (i > 0) sb.append(' ');
                    Main.disp(sb, a[i], new IdentityHashMap<>());
                }
                sb.append('\n');
                Main.out.print(sb);
                return null;
            }
        });
        e.declare("str", new Builtin("str", 1) {
            Object call(Object[] a, int line) {
                StringBuilder sb = new StringBuilder();
                Main.disp(sb, a[0], new IdentityHashMap<>());
                return sb.toString();
            }
        });
        e.declare("type", new Builtin("type", 1) {
            Object call(Object[] a, int line) { return Main.tn(a[0]); }
        });
        e.declare("len", new Builtin("len", 1) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof String s) return (long) s.length();
                if (a[0] instanceof TernList L) return (long) L.a.size();
                throw new TernError(line, "bad argument to len");
            }
        });
        e.declare("push", new Builtin("push", 2) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof TernList L) { L.a.add(a[1]); return null; }
                throw new TernError(line, "bad argument to push");
            }
        });
        e.declare("pop", new Builtin("pop", 1) {
            Object call(Object[] a, int line) throws TernError {
                if (a[0] instanceof TernList L) {
                    int n = L.a.size();
                    if (n == 0) throw new TernError(line, "bad argument to pop");
                    return L.a.remove(n - 1);
                }
                throw new TernError(line, "bad argument to pop");
            }
        });
        e.declare("range", new Builtin("range", 2) {
            Object call(Object[] a, int line) throws TernError {
                if (!(a[0] instanceof Long) || !(a[1] instanceof Long))
                    throw new TernError(line, "bad argument to range");
                long A = (Long) a[0], B = (Long) a[1];
                TernList L = new TernList();
                for (long i = A; i < B; i++) L.a.add(i);
                return L;
            }
        });
        e.declare("slice", new Builtin("slice", 3) {
            Object call(Object[] a, int line) throws TernError {
                if (!(a[1] instanceof Long) || !(a[2] instanceof Long))
                    throw new TernError(line, "bad argument to slice");
                int A = (int) (long) (Long) a[1], B = (int) (long) (Long) a[2];
                if (a[0] instanceof String s) {
                    if (A < 0 || B > s.length() || A > B) throw new TernError(line, "bad argument to slice");
                    return s.substring(A, B);
                }
                if (a[0] instanceof TernList L) {
                    if (A < 0 || B > L.a.size() || A > B) throw new TernError(line, "bad argument to slice");
                    TernList R = new TernList();
                    R.a.addAll(L.a.subList(A, B));
                    return R;
                }
                throw new TernError(line, "bad argument to slice");
            }
        });
    }
}

abstract class Expr { abstract Object eval(Env e) throws TernError; }

class Lit extends Expr { final Object v; Lit(Object v) { this.v = v; } Object eval(Env e) { return v; } }

class NameExpr extends Expr { final String n; final int line;
    NameExpr(String n, int l) { this.n = n; line = l; }
    Object eval(Env e) throws TernError { return e.get(n, line); } }

class ListLit extends Expr { final Expr[] es;
    ListLit(Expr[] es) { this.es = es; }
    Object eval(Env e) throws TernError {
        TernList L = new TernList();
        for (Expr x : es) L.a.add(x.eval(e));
        return L;
    } }

class FnLit extends Expr { final String[] params; final List<Stmt> body;
    FnLit(String[] p, List<Stmt> b) { params = p; body = b; }
    Object eval(Env e) { return new Func(params, body, e); } }

class Neg extends Expr { final Expr x; final int line;
    Neg(Expr x, int l) { this.x = x; line = l; }
    Object eval(Env e) throws TernError {
        Object v = x.eval(e);
        if (v instanceof Long) {
            try { return Math.negateExact((Long) v); }
            catch (ArithmeticException ex) { throw new TernError(line, "integer overflow"); }
        }
        throw new TernError(line, "cannot apply - to " + Main.tn(v));
    } }

class Not extends Expr { final Expr x;
    Not(Expr x) { this.x = x; }
    Object eval(Env e) throws TernError { return !Main.truthy(x.eval(e)); } }

class And extends Expr { final Expr l, r;
    And(Expr l, Expr r) { this.l = l; this.r = r; }
    Object eval(Env e) throws TernError { Object a = l.eval(e); return Main.truthy(a) ? r.eval(e) : a; } }

class Or extends Expr { final Expr l, r;
    Or(Expr l, Expr r) { this.l = l; this.r = r; }
    Object eval(Env e) throws TernError { Object a = l.eval(e); return Main.truthy(a) ? a : r.eval(e); } }

class Binary extends Expr {
    final String op; final Expr l, r; final int line;
    Binary(String op, Expr l, Expr r, int line) { this.op = op; this.l = l; this.r = r; this.line = line; }
    Object eval(Env e) throws TernError {
        Object a = l.eval(e), b = r.eval(e);
        switch (op) {
            case "+":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.addExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                if (a instanceof String && b instanceof String) return (String) a + (String) b;
                if (a instanceof TernList && b instanceof TernList) {
                    TernList R = new TernList();
                    R.a.addAll(((TernList) a).a);
                    R.a.addAll(((TernList) b).a);
                    return R;
                }
                break;
            case "-":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.subtractExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                break;
            case "*":
                if (a instanceof Long && b instanceof Long) {
                    try { return Math.multiplyExact((Long) a, (Long) b); }
                    catch (ArithmeticException x) { throw new TernError(line, "integer overflow"); }
                }
                break;
            case "/":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    if (y == 0) throw new TernError(line, "division by zero");
                    if (x == Long.MIN_VALUE && y == -1) throw new TernError(line, "integer overflow");
                    return x / y;
                }
                break;
            case "%":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    if (y == 0) throw new TernError(line, "division by zero");
                    return x % y;
                }
                break;
            case "<": case "<=": case ">": case ">=":
                if (a instanceof Long && b instanceof Long) {
                    long x = (Long) a, y = (Long) b;
                    switch (op) {
                        case "<": return x < y;
                        case "<=": return x <= y;
                        case ">": return x > y;
                        default: return x >= y;
                    }
                }
                if (a instanceof String && b instanceof String) {
                    int c = ((String) a).compareTo((String) b);
                    switch (op) {
                        case "<": return c < 0;
                        case "<=": return c <= 0;
                        case ">": return c > 0;
                        default: return c >= 0;
                    }
                }
                break;
            case "==": return Main.eq(a, b);
            case "!=": return !Main.eq(a, b);
        }
        throw new TernError(line, "cannot apply " + op + " to " + Main.tn(a) + " and " + Main.tn(b));
    }
}

class Call extends Expr {
    final Expr callee; final Expr[] args; final int line;
    Call(Expr c, Expr[] a, int l) { callee = c; args = a; line = l; }
    Object eval(Env e) throws TernError {
        Object c = callee.eval(e);
        Object[] av = new Object[args.length];
        for (int i = 0; i < args.length; i++) av[i] = args[i].eval(e);
        if (c instanceof Func f) {
            if (f.params.length != av.length)
                throw new TernError(line, "expected " + f.params.length + " arguments, got " + av.length);
            Env ne = new Env(f.closure);
            for (int i = 0; i < av.length; i++) ne.declare(f.params[i], av[i]);
            try {
                for (Stmt s : f.body) s.exec(ne);
            } catch (RetSig r) { return r.v; }
            return null;
        }
        if (c instanceof Builtin b) {
            if (b.arity >= 0 && av.length != b.arity)
                throw new TernError(line, "expected " + b.arity + " arguments, got " + av.length);
            return b.call(av, line);
        }
        throw new TernError(line, "cannot call " + Main.tn(c));
    }
}

class Index extends Expr {
    final Expr obj, idx; final int line;
    Index(Expr o, Expr i, int l) { obj = o; idx = i; line = l; }
    Object eval(Env e) throws TernError {
        Object x = obj.eval(e), i = idx.eval(e);
        if (x instanceof TernList L) {
            if (!(i instanceof Long)) throw new TernError(line, "cannot index list with " + Main.tn(i));
            int I = (int) (long) (Long) i;
            if (I < 0 || I >= L.a.size())
                throw new TernError(line, "index " + I + " out of range for length " + L.a.size());
            return L.a.get(I);
        }
        if (x instanceof String s) {
            if (!(i instanceof Long)) throw new TernError(line, "cannot index string with " + Main.tn(i));
            int I = (int) (long) (Long) i;
            if (I < 0 || I >= s.length())
                throw new TernError(line, "index " + I + " out of range for length " + s.length());
            return String.valueOf(s.charAt(I));
        }
        throw new TernError(line, "cannot index " + Main.tn(x) + " with " + Main.tn(i));
    }
}

abstract class Stmt { abstract void exec(Env e) throws TernError; }

class Let extends Stmt { final String n; final Expr x;
    Let(String n, Expr x) { this.n = n; this.x = x; }
    void exec(Env e) throws TernError { e.declare(n, x.eval(e)); } }

class FnStmt extends Stmt { final String n; final String[] params; final List<Stmt> body;
    FnStmt(String n, String[] p, List<Stmt> b) { this.n = n; params = p; body = b; }
    void exec(Env e) { e.declare(n, new Func(params, body, e)); } }

class ExprStmt extends Stmt { final Expr x; ExprStmt(Expr x) { this.x = x; }
    void exec(Env e) throws TernError { x.eval(e); } }

class Assign extends Stmt { final String n; final Expr x; final int line;
    Assign(String n, Expr x, int l) { this.n = n; this.x = x; line = l; }
    void exec(Env e) throws TernError { e.set(n, x.eval(e), line); } }

class IndexAssign extends Stmt {
    final Expr obj, idx, val; final int line;
    IndexAssign(Expr o, Expr i, Expr v, int l) { obj = o; idx = i; val = v; line = l; }
    void exec(Env e) throws TernError {
        Object x = obj.eval(e), i = idx.eval(e), v = val.eval(e);
        if (!(x instanceof TernList)) throw new TernError(line, "cannot assign into " + Main.tn(x));
        TernList L = (TernList) x;
        if (!(i instanceof Long)) throw new TernError(line, "cannot index list with " + Main.tn(i));
        int I = (int) (long) (Long) i;
        if (I < 0 || I >= L.a.size())
            throw new TernError(line, "index " + I + " out of range for length " + L.a.size());
        L.a.set(I, v);
    }
}

class If extends Stmt {
    final Expr c; final List<Stmt> then; final Object els;
    If(Expr c, List<Stmt> t, Object e) { this.c = c; then = t; els = e; }
    void exec(Env e) throws TernError {
        if (Main.truthy(c.eval(e))) Main.execBlock(then, new Env(e));
        else if (els != null) {
            if (els instanceof If) ((If) els).exec(e);
            else Main.execBlock((List<Stmt>) els, new Env(e));
        }
    }
}

class While extends Stmt {
    final Expr c; final List<Stmt> body;
    While(Expr c, List<Stmt> b) { this.c = c; body = b; }
    void exec(Env e) throws TernError {
        while (Main.truthy(c.eval(e))) {
            Env be = new Env(e);
            try { Main.execBlock(body, be); }
            catch (BreakSig s) { break; }
            catch (ContinueSig s) {}
        }
    }
}

class For extends Stmt {
    final String var; final Expr xs; final List<Stmt> body; final int line;
    For(String v, Expr x, List<Stmt> b, int l) { var = v; xs = x; body = b; line = l; }
    void exec(Env e) throws TernError {
        Object o = xs.eval(e);
        if (!(o instanceof TernList)) throw new TernError(line, "cannot iterate " + Main.tn(o));
        TernList L = (TernList) o;
        int i = 0;
        while (i < L.a.size()) {
            Env be = new Env(e);
            be.declare(var, L.a.get(i));
            try { Main.execBlock(body, be); }
            catch (BreakSig s) { break; }
            catch (ContinueSig s) {}
            i++;
        }
    }
}

class Ret extends Stmt { final Expr x; Ret(Expr x) { this.x = x; }
    void exec(Env e) throws TernError { throw new RetSig(x == null ? null : x.eval(e)); } }
class BreakS extends Stmt { void exec(Env e) { throw new BreakSig(); } }
class ContinueS extends Stmt { void exec(Env e) { throw new ContinueSig(); } }

class Parser {
    List<Token> t; int p;
    Parser(List<Token> t) { this.t = t; }
    Token peek() { return t.get(p); }
    Token next() { return t.get(p++); }
    boolean isOp(String o) { Token k = peek(); return k.type == Token.OP && k.s.equals(o); }
    boolean matchOp(String o) { if (isOp(o)) { p++; return true; } return false; }
    boolean matchKw(String o) { Token k = peek(); if (k.type == Token.KW && k.s.equals(o)) { p++; return true; } return false; }
    Token expectOp(String o) { if (!matchOp(o)) throw new RuntimeException("syntax error"); return t.get(p - 1); }
    Token expectKw(String o) { if (!matchKw(o)) throw new RuntimeException("syntax error"); return t.get(p - 1); }
    Token expectId() { Token k = peek(); if (k.type != Token.ID) throw new RuntimeException("syntax error"); p++; return k; }

    List<Stmt> parseProgram() {
        ArrayList<Stmt> s = new ArrayList<>();
        while (peek().type != Token.EOF) s.add(parseStmt());
        return s;
    }

    List<Stmt> block() {
        expectOp("{");
        ArrayList<Stmt> s = new ArrayList<>();
        while (!isOp("}")) s.add(parseStmt());
        expectOp("}");
        return s;
    }

    String[] params() {
        ArrayList<String> ps = new ArrayList<>();
        if (peek().type == Token.ID) {
            ps.add(next().s);
            while (matchOp(",")) ps.add(expectId().s);
        }
        return ps.toArray(new String[0]);
    }

    Stmt parseStmt() {
        Token k = peek();
        if (k.type == Token.KW) {
            switch (k.s) {
                case "let": {
                    next();
                    Token name = expectId();
                    expectOp("=");
                    Expr e = expr();
                    expectOp(";");
                    return new Let(name.s, e);
                }
                case "fn": {
                    next();
                    Token name = expectId();
                    expectOp("(");
                    String[] ps = params();
                    expectOp(")");
                    return new FnStmt(name.s, ps, block());
                }
                case "if": return parseIf();
                case "while": {
                    next();
                    Expr c = expr();
                    return new While(c, block());
                }
                case "for": {
                    int line = k.line;
                    next();
                    Token name = expectId();
                    expectKw("in");
                    Expr e = expr();
                    return new For(name.s, e, block(), line);
                }
                case "return": {
                    next();
                    Expr e = null;
                    if (!isOp(";")) e = expr();
                    expectOp(";");
                    return new Ret(e);
                }
                case "break": next(); expectOp(";"); return new BreakS();
                case "continue": next(); expectOp(";"); return new ContinueS();
            }
        }
        Expr e = expr();
        if (matchOp("=")) {
            if (e instanceof NameExpr ne) {
                Expr v = expr();
                expectOp(";");
                return new Assign(ne.n, v, ne.line);
            }
            if (e instanceof Index ix) {
                Expr v = expr();
                expectOp(";");
                return new IndexAssign(ix.obj, ix.idx, v, ix.line);
            }
            throw new RuntimeException("syntax error");
        }
        expectOp(";");
        return new ExprStmt(e);
    }

    Stmt parseIf() {
        next(); // if
        Expr c = expr();
        List<Stmt> b = block();
        Object els = null;
        if (matchKw("else")) {
            if (peek().type == Token.KW && peek().s.equals("if")) els = parseIf();
            else els = block();
        }
        return new If(c, b, els);
    }

    Expr expr() { return parseOr(); }

    Expr parseOr() {
        Expr l = parseAnd();
        while (matchKw("or")) l = new Or(l, parseAnd());
        return l;
    }

    Expr parseAnd() {
        Expr l = parseNot();
        while (matchKw("and")) l = new And(l, parseNot());
        return l;
    }

    Expr parseNot() {
        if (matchKw("not")) return new Not(parseNot());
        return parseCmp();
    }

    Expr parseCmp() {
        Expr l = parseAdd();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("==") || k.s.equals("!=") || k.s.equals("<")
                    || k.s.equals("<=") || k.s.equals(">") || k.s.equals(">="))) {
                next();
                l = new Binary(k.s, l, parseAdd(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseAdd() {
        Expr l = parseMul();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("+") || k.s.equals("-"))) {
                next();
                l = new Binary(k.s, l, parseMul(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseMul() {
        Expr l = parseUnary();
        while (true) {
            Token k = peek();
            if (k.type == Token.OP && (k.s.equals("*") || k.s.equals("/") || k.s.equals("%"))) {
                next();
                l = new Binary(k.s, l, parseUnary(), k.line);
            } else break;
        }
        return l;
    }

    Expr parseUnary() {
        if (matchOp("-")) {
            Token k = t.get(p - 1);
            return new Neg(parseUnary(), k.line);
        }
        return parsePostfix();
    }

    Expr parsePostfix() {
        Expr e = parsePrimary();
        while (true) {
            if (matchOp("(")) {
                int line = t.get(p - 1).line;
                ArrayList<Expr> args = new ArrayList<>();
                if (!isOp(")")) {
                    args.add(expr());
                    while (matchOp(",")) args.add(expr());
                }
                expectOp(")");
                e = new Call(e, args.toArray(new Expr[0]), line);
            } else if (matchOp("[")) {
                int line = t.get(p - 1).line;
                Expr i = expr();
                expectOp("]");
                e = new Index(e, i, line);
            } else break;
        }
        return e;
    }

    Expr parsePrimary() {
        Token k = peek();
        if (k.type == Token.INT) { next(); return new Lit(k.v); }
        if (k.type == Token.STR) { next(); return new Lit(k.s); }
        if (k.type == Token.ID) { next(); return new NameExpr(k.s, k.line); }
        if (k.type == Token.KW) {
            switch (k.s) {
                case "true": next(); return new Lit(Boolean.TRUE);
                case "false": next(); return new Lit(Boolean.FALSE);
                case "nil": next(); return new Lit(null);
                case "fn": {
                    next();
                    expectOp("(");
                    String[] ps = params();
                    expectOp(")");
                    return new FnLit(ps, block());
                }
            }
        }
        if (matchOp("(")) { Expr e = expr(); expectOp(")"); return e; }
        if (matchOp("[")) {
            ArrayList<Expr> es = new ArrayList<>();
            if (!isOp("]")) {
                es.add(expr());
                while (matchOp(",")) es.add(expr());
            }
            expectOp("]");
            return new ListLit(es.toArray(new Expr[0]));
        }
        throw new RuntimeException("syntax error");
    }
}

import sys, os, re, zlib, base64

W1252 = [0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
         0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
         0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
         0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178]

HEX = '0123456789abcdefABCDEF'
B64ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
ENCWORD = re.compile(r'=\?([^? \t]+)\?([BbQq])\?([^? \t]*)\?=')

def split_lines(data, br):
    if not data:
        return [], False
    parts = data.split(br)
    if parts[-1] == b'':
        return parts[:-1], True
    return parts, False

def split_head_body(data, br):
    idx = data.find(br + br)
    if idx != -1:
        return data[:idx], data[idx + 2 * len(br):]
    if data.startswith(br):
        return b'', data[len(br):]
    return data, b''

def parse_headers(head, br):
    headers = {}
    if not head:
        return headers
    items = []
    for line in head.split(br):
        if line[:1] in (b' ', b'\t') and items:
            items[-1][1].append(line)
        else:
            name, _, val = line.partition(b':')
            items.append([name.strip().decode('ascii', 'replace').lower(), [val]])
    for key, parts in items:
        headers[key] = b''.join(parts).decode('ascii', 'replace').strip(' \t')
    return headers

def parse_entity(data, br):
    head, body = split_head_body(data, br)
    return {'headers': parse_headers(head, br), 'body': body}

def parse_params(s):
    n = len(s)
    def ws(i):
        while i < n and s[i] in ' \t':
            i += 1
        return i
    i = ws(i)
    start = i
    while i < n and s[i] != ';':
        i += 1
    main = s[start:i].strip(' \t').replace(' ', '').replace('\t', '')
    params = []
    while i < n:
        i += 1  # skip ';'
        i = ws(i)
        j = i
        while j < n and s[j] not in '=;':
            j += 1
        if j >= n:
            break
        attr = s[i:j].strip(' \t').lower()
        if s[j] == ';':
            i = j
            continue
        i = j + 1
        i = ws(i)
        if i < n and s[i] == '"':
            i += 1
            val = []
            while i < n and s[i] != '"':
                if s[i] == '\\' and i + 1 < n:
                    val.append(s[i + 1]); i += 2
                else:
                    val.append(s[i]); i += 1
            i += 1
            while i < n and s[i] != ';':
                i += 1
        else:
            j = i
            while j < n and s[j] not in ' \t;':
                j += 1
            val = s[i:j]
            while i < n and s[i] != ';':
                i += 1
        params.append((attr, val))
    return main, params

def get_param(params, name):
    for k, v in params:
        if k == name:
            return v
    return None

def analyze(ent):
    h = ent['headers']
    ct = h.get('content-type')
    if ct is None:
        main, params = 'text/plain', []
    else:
        main, params = parse_params(ct)
    if '/' in main:
        t, st = main.split('/', 1)
    else:
        t, st = main, ''
    t = t.lower(); st = st.lower()
    cte = (h.get('content-transfer-encoding') or '7bit').strip().lower()
    cd = h.get('content-disposition')
    if cd is None:
        disp, cd_params = None, []
    else:
        cd_main, cd_params = parse_params(cd)
        disp = cd_main.lower()
    return t, st, params, cte, disp, cd_params

def b64_decode_data(data):
    buf = bytearray()
    for b in data:
        c = chr(b)
        if c == '=':
            break
        if c in B64ALPHA:
            buf.append(b)
    pad = (-len(buf)) % 4
    return base64.b64decode(bytes(buf) + b'=' * pad)

def qp_decode(data, br):
    lines, ewb = split_lines(data, br)
    buf = bytearray()
    for idx, line in enumerate(lines):
        line = line.rstrip(b' \t')
        if line.endswith(b'='):
            buf += line[:-1]
        else:
            buf += line
            if idx < len(lines) - 1 or ewb:
                buf += br
    out = bytearray()
    i = 0
    while i < len(buf):
        if buf[i] == 0x3D and i + 2 < len(buf) and \
           chr(buf[i+1]) in HEX and chr(buf[i+2]) in HEX:
            out.append(int(buf[i+1:i+3].decode('ascii'), 16))
            i += 3
        else:
            out.append(buf[i]); i += 1
    return bytes(out)

def transfer_decode(data, cte, br):
    if cte == 'base64':
        return b64_decode_data(data)
    if cte == 'quoted-printable':
        return qp_decode(data, br)
    return data

def decode_charset(data, cs):
    cs = (cs or '').lower()
    if cs == 'windows-1252':
        return ''.join(chr(W1252[b - 0x80]) if 0x80 <= b <= 0x9F else chr(b) for b in data)
    try:
        return data.decode(cs or 'ascii')
    except (LookupError, UnicodeDecodeError):
        return data.decode('iso-8859-1')

def word_bytes(cs, enc, et):
    if enc in 'Bb':
        s = et.encode('iso-8859-1', 'replace')
        if len(s) % 4:
            s += b'=' * (4 - len(s) % 4)
        return base64.b64decode(s)
    out = bytearray()
    i = 0
    while i < len(et):
        c = et[i]
        if c == '_':
            out.append(0x20); i += 1
        elif c == '=' and i + 2 < len(et) and et[i+1] in HEX and et[i+2] in HEX:
            out.append(int(et[i+1:i+3], 16)); i += 3
        else:
            out.append(ord(c) & 0xFF); i += 1
    return bytes(out)

def decode_rfc2047(text):
    tokens = []
    pos = 0
    for m in ENCWORD.finditer(text):
        if m.start() > pos:
            tokens.append(('t', text[pos:m.start()]))
        tokens.append(('w', m.group(1), m.group(2), m.group(3)))
        pos = m.end()
    if pos < len(text):
        tokens.append(('t', text[pos:]))
    items = []
    for i, t in enumerate(tokens):
        if t[0] == 't' and items and items[-1][0] == 'w' and \
           i + 1 < len(tokens) and tokens[i+1][0] == 'w' and t[1].strip(' \t') == '':
            continue
        items.append(t)
    out = []
    i = 0
    while i < len(items):
        if items[i][0] == 'w':
            cs_norm = items[i][1].split('*')[0].lower()
            buf = bytearray()
            j = i
            while j < len(items) and items[j][0] == 'w' and \
                  items[j][1].split('*')[0].lower() == cs_norm:
                buf += word_bytes(items[j][1], items[j][2], items[j][3])
                j += 1
            out.append(decode_charset(bytes(buf), cs_norm))
            i = j
        else:
            out.append(items[i][1])
            i += 1
    return ''.join(out)

def percent_decode(s):
    out = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s) and s[i+1] in HEX and s[i+2] in HEX:
            out.append(int(s[i+1:i+3], 16)); i += 3
        else:
            out.append(ord(s[i]) & 0xFF); i += 1
    return bytes(out)

def rfc2231(params, attr):
    segs = {}
    single = None
    found = False
    for name, val in params:
        if name == attr + '*':
            single = val
            found = True
        elif name.startswith(attr):
            m = re.fullmatch(r'\*(\d+)(\*)?', name[len(attr):])
            if m:
                segs[int(m.group(1))] = (bool(m.group(2)), val)
                found = True
    if not found:
        return None
    if segs:
        items = [segs[k] for k in sorted(segs)]
    else:
        items = [(True, single)]
    data = bytearray()
    charset = None
    first_ext = True
    for ext, val in items:
        if ext:
            if first_ext:
                parts = val.split("'", 2)
                if len(parts) == 3:
                    charset = parts[0]
                    val = parts[2]
                first_ext = False
            data += percent_decode(val)
        else:
            data += bytes(ord(c) & 0xFF for c in val)
    cs = charset or 'us-ascii'
    if not cs:
        cs = 'us-ascii'
    return decode_charset(bytes(data), cs)

def get_name(ct_params, cd_params):
    for params, attr in ((cd_params, 'filename'), (ct_params, 'name')):
        r = rfc2231(params, attr)
        if r is not None:
            return r
    for params, attr in ((cd_params, 'filename'), (ct_params, 'name')):
        v = get_param(params, attr)
        if v is not None:
            return decode_rfc2047(v)
    return None

def get_parts(ent, br, params):
    boundary = get_param(params, 'boundary')
    if boundary is None:
        return []
    B = boundary.encode('iso-8859-1')
    lines, ewb = split_lines(ent['body'], br)
    marks = []
    for i, line in enumerate(lines):
        s = line.rstrip(b' \t')
        if s == b'--' + B:
            marks.append((i, False))
        elif s == b'--' + B + b'--':
            marks.append((i, True))
    parts = []
    k = 0
    while k < len(marks):
        idx, close = marks[k]
        if close:
            break
        if k + 1 < len(marks):
            parts.append(br.join(lines[idx+1:marks[k+1][0]]))
        else:
            parts.append(br.join(lines[idx+1:]))
            break
        k += 1
    return parts

def q(s):
    r = []
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            r.append('\\\\')
        elif ch == '"':
            r.append('\\"')
        elif ch == '\n':
            r.append('\\n')
        elif ch == '\t':
            r.append('\\t')
        elif o < 0x20 or 0x7F <= o <= 0x9F:
            r.append('\\u%04x' % o)
        else:
            r.append(ch)
    return '"' + ''.join(r) + '"'

def emit(ent, br, depth, out):
    t, st, params, cte, disp, cd_params = analyze(ent)
    ind = '  ' * depth
    if t == 'multipart':
        parts = get_parts(ent, br, params)
        out.append('%smultipart/%s parts=%d' % (ind, st, len(parts)))
        for p in parts:
            emit(parse_entity(p, br), br, depth + 1, out)
    elif t == 'text' and disp != 'attachment':
        charset = (get_param(params, 'charset') or 'us-ascii').lower()
        data = transfer_decode(ent['body'], cte, br)
        text = decode_charset(data, charset)
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        out.append('%stext/%s charset=%s cte=%s chars=%d' % (ind, st, charset, cte, len(text)))
        out.append('  ' * (depth + 1) + q(text))
    else:
        data = transfer_decode(ent['body'], cte, br)
        name = get_name(params, cd_params)
        crc = zlib.crc32(data) & 0xFFFFFFFF
        out.append('%s%s/%s cte=%s disposition=%s name=%s size=%d crc32=%08x' % (
            ind, t, st, cte, disp if disp else '-',
            q(name) if name is not None else '-', len(data), crc))

def main():
    sys.stdout.reconfigure(encoding='utf-8')
    d = sys.argv[1]
    names = sorted((f for f in os.listdir(d) if f.endswith('.eml')),
                   key=lambda s: s.encode('utf-8'))
    blocks = []
    for name in names:
        with open(os.path.join(d, name), 'rb') as f:
            data = f.read()
        br = b'\r\n' if b'\r\n' in data else b'\n'
        ent = parse_entity(data, br)
        h = ent['headers']
        out = ['== ' + name]
        frm = h.get('from')
        subj = h.get('subject')
        out.append('From: ' + (q(decode_rfc2047(frm)) if frm is not None else '-'))
        out.append('Subject: ' + (q(decode_rfc2047(subj)) if subj is not None else '-'))
        emit(ent, br, 0, out)
        blocks.append('\n'.join(out))
    if blocks:
        sys.stdout.write('\n\n'.join(blocks) + '\n')

if __name__ == '__main__':
    main()

import * as fs from 'fs';
import * as path from 'path';

const KEYWORDS = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);
const MIN = -(1n << 63n), MAX = (1n << 63n) - 1n;

class TernError { constructor(public msg: string, public line: number) {} }
function err(msg: string, line: number): never { throw new TernError(msg, line); }

// ---------- Values ----------
type Value = bigint | boolean | string | Value[] | Closure | Builtin | null;

class Closure { constructor(public params: string[], public body: Stmt[], public env: Env) {} }
class Builtin { constructor(public name: string, public arity: number | null, public fn: (args: Value[], line: number) => Value) {} }

function typeName(v: Value): string {
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'string') return 'string';
  if (Array.isArray(v)) return 'list';
  if (v === null) return 'nil';
  return 'function';
}

function truthy(v: Value): boolean {
  if (v === null || v === false) return false;
  if (v === 0n || v === '') return false;
  if (Array.isArray(v) && v.length === 0) return false;
  return true;
}

function eq(a: Value, b: Value): boolean {
  if (typeof a === 'bigint' || typeof b === 'bigint')
    return typeof a === 'bigint' && typeof b === 'bigint' && a === b;
  if (typeof a === 'boolean' || typeof b === 'boolean')
    return typeof a === 'boolean' && typeof b === 'boolean' && a === b;
  if (typeof a === 'string' || typeof b === 'string')
    return typeof a === 'string' && typeof b === 'string' && a === b;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!eq(a[i], b[i])) return false;
    return true;
  }
  if (a === null || b === null) return a === null && b === null;
  return a === b;
}

function quoteStr(s: string): string {
  let out = '"';
  for (const c of s) {
    if (c === '\\') out += '\\\\';
    else if (c === '"') out += '\\"';
    else if (c === '\n') out += '\\n';
    else if (c === '\t') out += '\\t';
    else out += c;
  }
  return out + '"';
}

function display(v: Value, quote: boolean, seen: Set<Value>): string {
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (v === null) return 'nil';
  if (typeof v === 'string') return quote ? quoteStr(v) : v;
  if (v instanceof Closure || v instanceof Builtin) return '<fn>';
  if (seen.has(v)) return '[...]';
  seen.add(v);
  const s = '[' + v.map(e => display(e, true, seen)).join(', ') + ']';
  seen.delete(v);
  return s;
}

// ---------- Tokenizer ----------
interface Tok { t: string; v: any; line: number; }

function tokenize(src: string): Tok[] {
  const toks: Tok[] = [];
  let i = 0, line = 1;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === '\n') { line++; i++; continue; }
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '#') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      let j = i;
      while (j < n && src[j] >= '0' && src[j] <= '9') j++;
      toks.push({ t: 'int', v: BigInt(src.slice(i, j)), line });
      i = j; continue;
    }
    if (/[A-Za-z_]/.test(c)) {
      let j = i;
      while (j < n && /[A-Za-z0-9_]/.test(src[j])) j++;
      const w = src.slice(i, j);
      toks.push({ t: KEYWORDS.has(w) ? 'kw' : 'ident', v: w, line });
      i = j; continue;
    }
    if (c === '"') {
      let j = i + 1, s = '';
      while (j < n && src[j] !== '"') {
        if (src[j] === '\\') {
          const e = src[j + 1];
          s += e === 'n' ? '\n' : e === 't' ? '\t' : e === '"' ? '"' : e === '\\' ? '\\' : e;
          j += 2;
        } else { s += src[j]; j++; }
      }
      toks.push({ t: 'str', v: s, line });
      i = j + 1; continue;
    }
    const two = src.slice(i, i + 2);
    if (two === '==' || two === '!=' || two === '<=' || two === '>=') {
      toks.push({ t: 'op', v: two, line }); i += 2; continue;
    }
    if ('+-*/%<>=()[]{},;'.includes(c)) { toks.push({ t: 'op', v: c, line }); i++; continue; }
    i++;
  }
  toks.push({ t: 'eof', v: '', line });
  return toks;
}

// ---------- AST ----------
type Expr = any;
type Stmt = any;

class Parser {
  pos = 0;
  constructor(public toks: Tok[]) {}
  peek() { return this.toks[this.pos]; }
  next() { return this.toks[this.pos++]; }
  isOp(v: string) { const t = this.peek(); return t.t === 'op' && t.v === v; }
  isKw(v: string) { const t = this.peek(); return t.t === 'kw' && t.v === v; }
  expectOp(v: string) { if (!this.isOp(v)) throw new Error('parse'); this.next(); }
  expectKw(v: string) { if (!this.isKw(v)) throw new Error('parse'); this.next(); }
  expectIdent() { const t = this.next(); if (t.t !== 'ident') throw new Error('parse'); return t.v; }

  parseProgram(): Stmt[] {
    const s: Stmt[] = [];
    while (this.peek().t !== 'eof') s.push(this.stmt());
    return s;
  }

  stmt(): Stmt {
    const t = this.peek();
    if (t.t === 'kw') {
      switch (t.v) {
        case 'let': {
          this.next(); const name = this.expectIdent(); this.expectOp('=');
          const e = this.expr(); this.expectOp(';');
          return { k: 'let', name, expr: e, line: t.line };
        }
        case 'fn': {
          this.next(); const name = this.expectIdent();
          const params = this.params(); const body = this.block();
          return { k: 'fn', name, params, body, line: t.line };
        }
        case 'if': return this.ifStmt();
        case 'while': {
          this.next(); const c = this.expr(); const b = this.block();
          return { k: 'while', cond: c, body: b, line: t.line };
        }
        case 'for': {
          this.next(); const name = this.expectIdent(); this.expectKw('in');
          const it = this.expr(); const b = this.block();
          return { k: 'for', name, iter: it, body: b, line: t.line };
        }
        case 'return': {
          this.next(); let e = null;
          if (!this.isOp(';')) e = this.expr();
          this.expectOp(';');
          return { k: 'return', expr: e, line: t.line };
        }
        case 'break': { this.next(); this.expectOp(';'); return { k: 'break', line: t.line }; }
        case 'continue': { this.next(); this.expectOp(';'); return { k: 'continue', line: t.line }; }
      }
    }
    const e = this.expr();
    if (this.isOp('=')) {
      this.next();
      const v = this.expr();
      this.expectOp(';');
      if (e.k === 'var') return { k: 'assign', name: e.name, expr: v, line: e.line };
      if (e.k === 'index') return { k: 'idxassign', obj: e.obj, idx: e.idx, expr: v, line: e.line };
      throw new Error('parse');
    }
    this.expectOp(';');
    return { k: 'expr', expr: e };
  }

  ifStmt(): Stmt {
    const t = this.next();
    const c = this.expr();
    const b = this.block();
    let els: Stmt[] | null = null;
    if (this.isKw('else')) {
      this.next();
      els = this.isKw('if') ? [this.ifStmt()] : this.block();
    }
    return { k: 'if', cond: c, then: b, els, line: t.line };
  }

  block(): Stmt[] {
    this.expectOp('{');
    const s: Stmt[] = [];
    while (!this.isOp('}')) s.push(this.stmt());
    this.next();
    return s;
  }

  params(): string[] {
    const p: string[] = [];
    this.expectOp('(');
    if (!this.isOp(')')) {
      p.push(this.expectIdent());
      while (this.isOp(',')) { this.next(); p.push(this.expectIdent()); }
    }
    this.expectOp(')');
    return p;
  }

  expr(): Expr { return this.or(); }
  or(): Expr { let l = this.and(); while (this.isKw('or')) { this.next(); l = { k: 'or', l, r: this.and() }; } return l; }
  and(): Expr { let l = this.not(); while (this.isKw('and')) { this.next(); l = { k: 'and', l, r: this.not() }; } return l; }
  not(): Expr { if (this.isKw('not')) { this.next(); return { k: 'not', e: this.not() }; } return this.cmp(); }
  cmp(): Expr {
    let l = this.add();
    while (this.peek().t === 'op' && ['==','!=','<','<=','>','>='].includes(this.peek().v)) {
      const t = this.next(); l = { k: 'bin', op: t.v, l, r: this.add(), line: t.line };
    }
    return l;
  }
  add(): Expr {
    let l = this.mul();
    while (this.peek().t === 'op' && (this.peek().v === '+' || this.peek().v === '-')) {
      const t = this.next(); l = { k: 'bin', op: t.v, l, r: this.mul(), line: t.line };
    }
    return l;
  }
  mul(): Expr {
    let l = this.unary();
    while (this.peek().t === 'op' && ['*','/','%'].includes(this.peek().v)) {
      const t = this.next(); l = { k: 'bin', op: t.v, l, r: this.unary(), line: t.line };
    }
    return l;
  }
  unary(): Expr {
    if (this.isOp('-')) { const t = this.next(); return { k: 'neg', e: this.unary(), line: t.line }; }
    return this.postfix();
  }
  postfix(): Expr {
    let e = this.primary();
    for (;;) {
      if (this.isOp('(')) {
        const t = this.next();
        const args: Expr[] = [];
        if (!this.isOp(')')) {
          args.push(this.expr());
          while (this.isOp(',')) { this.next(); args.push(this.expr()); }
        }
        this.expectOp(')');
        e = { k: 'call', callee: e, args, line: t.line };
      } else if (this.isOp('[')) {
        const t = this.next();
        const idx = this.expr();
        this.expectOp(']');
        e = { k: 'index', obj: e, idx, line: t.line };
      } else return e;
    }
  }
  primary(): Expr {
    const t = this.next();
    if (t.t === 'int') return { k: 'int', v: t.v };
    if (t.t === 'str') return { k: 'str', v: t.v };
    if (t.t === 'ident') return { k: 'var', name: t.v, line: t.line };
    if (t.t === 'kw') {
      if (t.v === 'true') return { k: 'bool', v: true };
      if (t.v === 'false') return { k: 'bool', v: false };
      if (t.v === 'nil') return { k: 'nil' };
      if (t.v === 'fn') { const p = this.params(); const b = this.block(); return { k: 'fnexpr', params: p, body: b }; }
    }
    if (t.t === 'op') {
      if (t.v === '(') { const e = this.expr(); this.expectOp(')'); return e; }
      if (t.v === '[') {
        const items: Expr[] = [];
        if (!this.isOp(']')) {
          items.push(this.expr());
          while (this.isOp(',')) { this.next(); items.push(this.expr()); }
        }
        this.expectOp(']');
        return { k: 'list', items };
      }
    }
    throw new Error('parse');
  }
}

// ---------- Interpreter ----------
class BreakSig {}
class ContinueSig {}
class ReturnSig { constructor(public value: Value) {} }

class Env {
  vars = new Map<string, Value>();
  constructor(public parent: Env | null) {}
  get(name: string, line: number): Value {
    let e: Env | null = this;
    while (e) { if (e.vars.has(name)) return e.vars.get(name)!; e = e.parent; }
    return err(`undefined variable ${name}`, line);
  }
  set(name: string, v: Value, line: number): void {
    let e: Env | null = this;
    while (e) { if (e.vars.has(name)) { e.vars.set(name, v); return; } e = e.parent; }
    err(`undefined variable ${name}`, line);
  }
  declare(name: string, v: Value): void { this.vars.set(name, v); }
}

function chk(v: bigint, line: number): bigint {
  if (v < MIN || v > MAX) err('integer overflow', line);
  return v;
}

function binop(op: string, l: Value, r: Value, line: number): Value {
  if (op === '==') return eq(l, r);
  if (op === '!=') return !eq(l, r);
  if (op === '+') {
    if (typeof l === 'bigint' && typeof r === 'bigint') return chk(l + r, line);
    if (typeof l === 'string' && typeof r === 'string') return l + r;
    if (Array.isArray(l) && Array.isArray(r)) return [...l, ...r];
    err(`cannot apply + to ${typeName(l)} and ${typeName(r)}`, line);
  }
  if (op === '-' || op === '*' || op === '/' || op === '%') {
    if (typeof l !== 'bigint' || typeof r !== 'bigint')
      err(`cannot apply ${op} to ${typeName(l)} and ${typeName(r)}`, line);
    switch (op) {
      case '-': return chk(l - r, line);
      case '*': return chk(l * r, line);
      case '/':
        if (r === 0n) err('division by zero', line);
        return chk(l / r, line);
      case '%':
        if (r === 0n) err('division by zero', line);
        return chk(l % r, line);
    }
  }
  const ok = (typeof l === 'bigint' && typeof r === 'bigint') || (typeof l === 'string' && typeof r === 'string');
  if (!ok) err(`cannot apply ${op} to ${typeName(l)} and ${typeName(r)}`, line);
  switch (op) {
    case '<': return l < r;
    case '<=': return l <= r;
    case '>': return l > r;
    case '>=': return l >= r;
  }
  throw new Error('unreachable');
}

function bad(name: string, line: number): never {
  return err(`bad argument to ${name}`, line);
}

function makeBuiltins(): Env {
  const env = new Env(null);
  const def = (name: string, arity: number | null, fn: (args: Value[], line: number) => Value) =>
    env.declare(name, new Builtin(name, arity, fn));

  def('print', null, (args) => {
    process.stdout.write(args.map(a => display(a, false, new Set())).join(' ') + '\n');
    return null;
  });
  def('str', 1, (args, line) => display(args[0], false, new Set()));
  def('type', 1, (args) => typeName(args[0]));
  def('len', 1, (args, line) => {
    const x = args[0];
    if (typeof x === 'string') return BigInt(x.length);
    if (Array.isArray(x)) return BigInt(x.length);
    bad('len', line);
  });
  def('push', 2, (args, line) => {
    if (!Array.isArray(args[0])) bad('push', line);
    args[0].push(args[1]);
    return null;
  });
  def('pop', 1, (args, line) => {
    if (!Array.isArray(args[0]) || args[0].length === 0) bad('pop', line);
    return args[0].pop()!;
  });
  def('range', 2, (args, line) => {
    if (typeof args[0] !== 'bigint' || typeof args[1] !== 'bigint') bad('range', line);
    const out: Value[] = [];
    for (let x = args[0]; x < args[1]; x++) out.push(x);
    return out;
  });
  def('slice', 3, (args, line) => {
    const [x, a, b] = args;
    if (typeof a !== 'bigint' || typeof b !== 'bigint') bad('slice', line);
    if (typeof x === 'string') {
      if (a < 0n || b > BigInt(x.length) || a > b) bad('slice', line);
      return x.slice(Number(a), Number(b));
    }
    if (Array.isArray(x)) {
      if (a < 0n || b > BigInt(x.length) || a > b) bad('slice', line);
      return x.slice(Number(a), Number(b));
    }
    bad('slice', line);
  });
  return env;
}

function evalExpr(n: Expr, env: Env): Value {
  switch (n.k) {
    case 'int': return n.v;
    case 'str': return n.v;
    case 'bool': return n.v;
    case 'nil': return null;
    case 'var': return env.get(n.name, n.line);
    case 'list': return n.items.map((e: Expr) => evalExpr(e, env));
    case 'fnexpr': return new Closure(n.params, n.body, env);
    case 'and': { const l = evalExpr(n.l, env); return truthy(l) ? evalExpr(n.r, env) : l; }
    case 'or': { const l = evalExpr(n.l, env); return truthy(l) ? l : evalExpr(n.r, env); }
    case 'not': return !truthy(evalExpr(n.e, env));
    case 'neg': {
      const v = evalExpr(n.e, env);
      if (typeof v !== 'bigint') err(`cannot apply - to ${typeName(v)}`, n.line);
      return chk(-v, n.line);
    }
    case 'bin': {
      const l = evalExpr(n.l, env);
      const r = evalExpr(n.r, env);
      return binop(n.op, l, r, n.line);
    }
    case 'index': {
      const obj = evalExpr(n.obj, env);
      const idx = evalExpr(n.idx, env);
      if (Array.isArray(obj) || typeof obj === 'string') {
        if (typeof idx !== 'bigint') err(`cannot index ${typeName(obj)} with ${typeName(idx)}`, n.line);
        if (idx < 0n || idx >= BigInt(obj.length))
          err(`index ${idx} out of range for length ${obj.length}`, n.line);
        return obj[Number(idx)];
      }
      err(`cannot index ${typeName(obj)} with ${typeName(idx)}`, n.line);
    }
    case 'call': {
      const callee = evalExpr(n.callee, env);
      const args = n.args.map((a: Expr) => evalExpr(a, env));
      if (callee instanceof Builtin) {
        if (callee.arity !== null && args.length !== callee.arity)
          err(`expected ${callee.arity} arguments, got ${args.length}`, n.line);
        return callee.fn(args, n.line);
      }
      if (callee instanceof Closure) {
        if (args.length !== callee.params.length)
          err(`expected ${callee.params.length} arguments, got ${args.length}`, n.line);
        const e = new Env(callee.env);
        for (let i = 0; i < args.length; i++) e.declare(callee.params[i], args[i]);
        try { execStmts(callee.body, e); }
        catch (sig) {
          if (sig instanceof ReturnSig) return sig.value;
          throw sig;
        }
        return null;
      }
      err(`cannot call ${typeName(callee)}`, n.line);
    }
  }
  throw new Error('unreachable');
}

function execStmts(stmts: Stmt[], env: Env): void {
  for (const s of stmts) execStmt(s, env);
}

function execStmt(s: Stmt, env: Env): void {
  switch (s.k) {
    case 'let': env.declare(s.name, evalExpr(s.expr, env)); break;
    case 'fn': env.declare(s.name, new Closure(s.params, s.body, env)); break;
    case 'if':
      if (truthy(evalExpr(s.cond, env))) execStmts(s.then, new Env(env));
      else if (s.els) execStmts(s.els, new Env(env));
      break;
    case 'while':
      while (truthy(evalExpr(s.cond, env))) {
        try { execStmts(s.body, new Env(env)); }
        catch (sig) {
          if (sig instanceof BreakSig) break;
          if (!(sig instanceof ContinueSig)) throw sig;
        }
      }
      break;
    case 'for': {
      const list = evalExpr(s.iter, env);
      if (!Array.isArray(list)) err(`cannot iterate ${typeName(list)}`, s.line);
      let i = 0;
      while (i < list.length) {
        const e2 = new Env(env);
        e2.declare(s.name, list[i]);
        try { execStmts(s.body, e2); }
        catch (sig) {
          if (sig instanceof BreakSig) break;
          if (!(sig instanceof ContinueSig)) throw sig;
        }
        i++;
      }
      break;
    }
    case 'return': throw new ReturnSig(s.expr ? evalExpr(s.expr, env) : null);
    case 'break': throw new BreakSig();
    case 'continue': throw new ContinueSig();
    case 'assign': env.set(s.name, evalExpr(s.expr, env), s.line); break;
    case 'idxassign': {
      const obj = evalExpr(s.obj, env);
      const idx = evalExpr(s.idx, env);
      const v = evalExpr(s.expr, env);
      if (!Array.isArray(obj)) err(`cannot assign into ${typeName(obj)}`, s.line);
      if (typeof idx !== 'bigint') err(`cannot index list with ${typeName(idx)}`, s.line);
      if (idx < 0n || idx >= BigInt(obj.length))
        err(`index ${idx} out of range for length ${obj.length}`, s.line);
      obj[Number(idx)] = v;
      break;
    }
    case 'expr': evalExpr(s.expr, env); break;
  }
}

