const dir = process.argv[2];
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf8');
try {
  const toks = tokenize(src);
  const prog = new Parser(toks).parseProgram();
  const genv = new Env(makeBuiltins());
  execStmts(prog, genv);
} catch (e) {
  if (e instanceof TernError) {
    process.stdout.write(`error at line ${e.line}: ${e.msg}\n`);
  } else {
    throw e;
  }
}

import sys, os, re, zlib

def split_lines(data):
    if not data:
        return []
    parts = data.split(b'\n')
    if data.endswith(b'\n'):
        return [p + b'\n' for p in parts[:-1]]
    return [p + b'\n' for p in parts[:-1]] + [parts[-1]]

def off_str(k):
    if k > 0:
        return ('+%d' % k).encode()
    if k < 0:
        return ('-%d' % -k).encode()
    return b'0'

def main():
    base = sys.argv[1]
    with open(os.path.join(base, 'changes.diff'), 'rb') as f:
        raw = f.read()

    if raw.endswith(b'\n'):
        items = [(l, True) for l in raw.split(b'\n')[:-1]]
    else:
        ls = raw.split(b'\n')
        items = [(l, i < len(ls) - 1) for i, l in enumerate(ls)]

    sections = []
    cur = None
    for line, nl in items:
        if line.startswith(b'diff --git a/'):
            rest = line[len(b'diff --git a/'):]
            i = rest.find(b' b/')
            path = rest[:i] if i != -1 else rest
            cur = (path, [])
            sections.append(cur)
        elif cur is not None:
            cur[1].append((line, nl))

    sections.sort(key=lambda s: s[0])
    out = []

    for path, slines in sections:
        kind = b'modify'
        for line, _ in slines:
            if line.startswith(b'new file mode '):
                kind = b'create'
                break
            if line.startswith(b'deleted file mode '):
                kind = b'delete'
                break

        # parse hunks
        hunks = []
        i = 0
        while i < len(slines):
            line, _ = slines[i]
            if line.startswith(b'@@ '):
                m = re.match(rb'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
                i += 1
                body = []
                while i < len(slines):
                    l2, _ = slines[i]
                    if l2.startswith(b'@@ ') or l2.startswith(b'diff --git '):
                        break
                    body.append(slines[i])
                    i += 1
                if m is None:
                    hunks.append((0, 0, 0, 0, [], [], True))
                else:
                    a = int(m.group(1)); b = int(m.group(2) or 1)
                    c = int(m.group(3)); d = int(m.group(4) or 1)
                    old = []; new = []
                    for bl, bnl in body:
                        mk = bl[:1]
                        if mk == b'\\':
                            if old and old[-1].endswith(b'\n'):
                                old[-1] = old[-1][:-1]
                            if new and new[-1].endswith(b'\n'):
                                new[-1] = new[-1][:-1]
                        else:
                            content = bl[1:] + (b'\n' if bnl else b'')
                            if mk == b' ':
                                old.append(content); new.append(content)
                            elif mk == b'-':
                                old.append(content)
                            elif mk == b'+':
                                new.append(content)
                    hunks.append((a, b, c, d, old, new, False))
            else:
                i += 1

        fpath = os.path.join(base.encode(), b'tree', path)
        exists = os.path.exists(fpath)

        if kind == b'create' and exists:
            out.append(path + b': ' + kind)
            out.append(b'  error: already exists')
            continue
        if kind in (b'modify', b'delete') and not exists:
            out.append(path + b': ' + kind)
            out.append(b'  error: not found')
            continue

        if kind == b'create':
            lines = []
        else:
            with open(fpath, 'rb') as f:
                lines = split_lines(f.read())

        results = []
        delta = 0
        all_applied = True
        for idx, (a, b, c, d, old, new, mal) in enumerate(hunks, 1):
            if mal or len(old) != b or len(new) != d:
                results.append(b'  hunk %d: malformed' % idx)
                all_applied = False
                continue
            P = a + delta
            n = len(lines)
            if b == 0:
                if 0 <= P <= n:
                    lines[P:P] = new
                    results.append(b'  hunk %d: applied at %d (offset %s)' % (idx, P, off_str(0)))
                    delta += d
                else:
                    results.append(b'  hunk %d: rejected' % idx)
                    all_applied = False
            else:
                applied = False
                k = 0
                while True:
                    cands = [P] if k == 0 else [P - k, P + k]
                    for p in cands:
                        if 1 <= p and p + b - 1 <= n and lines[p - 1:p - 1 + b] == old:
                            lines[p - 1:p - 1 + b] = new
                            results.append(b'  hunk %d: applied at %d (offset %s)' % (idx, p, off_str(p - P)))
                            delta += d - b
                            applied = True
                            break
                    if applied:
                        break
                    if P - k < 1 and P + k + b - 1 > n:
                        break
                    k += 1
                if not applied:
                    results.append(b'  hunk %d: rejected' % idx)
                    all_applied = False

        deleted = (kind == b'delete') and all_applied and len(lines) == 0

        out.append(path + b': ' + kind)
        out.extend(results)
        if deleted:
            out.append(b'  result: deleted')
        else:
            crc = zlib.crc32(b''.join(lines)) & 0xffffffff
            out.append(b'  result: %d lines, crc32 %08x' % (len(lines), crc))

    sys.stdout.buffer.write(b'\n'.join(out) + b'\n')

