import java.util.zip.CRC32;

public class Main {
    static final Pattern HDR = Pattern.compile("@@ -(\\d+)(?:,(\\d+))? \\+(\\d+)(?:,(\\d+))? @@.*");

    static class Line {
        byte[] b; boolean nl;
        Line(byte[] b, boolean nl){ this.b = b; this.nl = nl; }
    }

    static List<Line> parse(byte[] data) {
        List<Line> out = new ArrayList<>();
        int i = 0;
        while (i < data.length) {
            int j = i;
            while (j < data.length && data[j] != '\n') j++;
            out.add(new Line(Arrays.copyOfRange(data, i, j), j < data.length));
            i = j + 1;
        }
        return out;
    }

    static byte[] toBytes(List<Line> lines) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        for (int i = 0; i < lines.size(); i++) {
            Line l = lines.get(i);
            bos.write(l.b, 0, l.b.length);
            if (i < lines.size() - 1 || l.nl) bos.write('\n');
        }
        return bos.toByteArray();
    }

    static boolean startsWith(byte[] a, String s) {
        byte[] sb = s.getBytes();
        if (a.length < sb.length) return false;
        for (int i = 0; i < sb.length; i++) if (a[i] != sb[i]) return false;
        return true;
    }

    static boolean lineEq(Line x, Line y) {
        return x.nl == y.nl && Arrays.equals(x.b, y.b);
    }

    static class Hunk {
        int a, b, d;
        boolean malformed;
        List<Line> oldL = new ArrayList<>(), newL = new ArrayList<>();
    }

    static class Sec {
        byte[] path;
        String kind = "modify";
        List<Hunk> hunks = new ArrayList<>();
        List<Line> content;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        byte[] diff = Files.readAllBytes(Paths.get(dir, "changes.diff"));
        List<byte[]> dl = new ArrayList<>();
        {
            int i = 0;
            while (i < diff.length) {
                int j = i;
                while (j < diff.length && diff[j] != '\n') j++;
                dl.add(Arrays.copyOfRange(diff, i, j));
                i = j + 1;
            }
        }

        List<Sec> secs = new ArrayList<>();
        int i = 0;
        while (i < dl.size()) {
            byte[] L = dl.get(i);
            if (!startsWith(L, "diff --git a/")) { i++; continue; }
            Sec s = new Sec();
            int start = 13, end = L.length;
            for (int k = start; k + 2 < L.length; k++) {
                if (L[k] == ' ' && L[k+1] == 'b' && L[k+2] == '/') { end = k; break; }
            }
            s.path = Arrays.copyOfRange(L, start, end);
            i++;
            while (i < dl.size()) {
                byte[] h = dl.get(i);
                if (startsWith(h, "new file mode ")) { s.kind = "create"; i++; }
                else if (startsWith(h, "deleted file mode ")) { s.kind = "delete"; i++; }
                else if (startsWith(h, "index ")) i++;
                else break;
            }
            if (i < dl.size() && startsWith(dl.get(i), "--- ")) {
                i++;
                if (i < dl.size() && startsWith(dl.get(i), "+++ ")) i++;
            }
            while (i < dl.size() && startsWith(dl.get(i), "@@ ")) {
                Hunk h = new Hunk();
                Matcher m = HDR.matcher(new String(dl.get(i)));
                if (m.matches()) {
                    h.a = Integer.parseInt(m.group(1));
                    h.b = m.group(2) != null ? Integer.parseInt(m.group(2)) : 1;
                    h.d = m.group(4) != null ? Integer.parseInt(m.group(4)) : 1;
                } else h.malformed = true;
                i++;
                Line last = null;
                while (i < dl.size() && !startsWith(dl.get(i), "@@ ") && !startsWith(dl.get(i), "diff --git ")) {
                    byte[] bl = dl.get(i);
                    if (bl.length > 0) {
                        byte mk = bl[0];
                        if (mk == '\\') {
                            if (last != null) last.nl = false;
                        } else {
                            Line ln = new Line(Arrays.copyOfRange(bl, 1, bl.length), true);
                            if (mk == ' ') { h.oldL.add(ln); h.newL.add(ln); }
                            else if (mk == '-') h.oldL.add(ln);
                            else if (mk == '+') h.newL.add(ln);
                            last = ln;
                        }
                    }
                    i++;
                }
                if (!h.malformed && (h.oldL.size() != h.b || h.newL.size() != h.d)) h.malformed = true;
                s.hunks.add(h);
            }
            secs.add(s);
        }

        secs.sort((x, y) -> Arrays.compareUnsigned(x.path, y.path));

        StringBuilder sb = new StringBuilder();
        for (Sec s : secs) {
            String path = new String(s.path);
            sb.append(path).append(": ").append(s.kind).append('\n');
            File f = Paths.get(dir, "tree", path).toFile();
            if (s.kind.equals("create")) {
                if (f.exists()) { sb.append("  error: already exists\n"); continue; }
                s.content = new ArrayList<>();
            } else {
                if (!f.exists()) { sb.append("  error: not found\n"); continue; }
                s.content = parse(Files.readAllBytes(f.toPath()));
            }
            int delta = 0, applied = 0, num = 1;
            for (Hunk h : s.hunks) {
                if (h.malformed) {
                    sb.append("  hunk ").append(num).append(": malformed\n");
                } else if (h.b == 0) {
                    int P = h.a + delta;
                    if (P >= 0 && P <= s.content.size()) {
                        s.content.addAll(P, h.newL);
                        sb.append("  hunk ").append(num).append(": applied at ").append(P).append(" (offset 0)\n");
                        delta += h.d; applied++;
                    } else sb.append("  hunk ").append(num).append(": rejected\n");
                } else {
                    int P = h.a + delta;
                    int n = s.content.size();
                    int found = -1;
                    int lim = Math.max(P, n) + h.b + 2;
                    for (int k = 0; k <= lim; k++) {
                        if (P - k < 1 && P + k > n - h.b + 1) break;
                        int[] cand = (k == 0) ? new int[]{P} : new int[]{P - k, P + k};
                        for (int p : cand) {
                            if (p < 1 || p + h.b - 1 > n) continue;
                            boolean ok = true;
                            for (int j = 0; j < h.b; j++) {
                                if (!lineEq(s.content.get(p - 1 + j), h.oldL.get(j))) { ok = false; break; }
                            }
                            if (ok) { found = p; break; }
                        }
                        if (found > 0) break;
                    }
                    if (found > 0) {
                        s.content.subList(found - 1, found - 1 + h.b).clear();
                        s.content.addAll(found - 1, h.newL);
                        int off = found - P;
                        String offs = off > 0 ? "+" + off : String.valueOf(off);
                        sb.append("  hunk ").append(num).append(": applied at ").append(found)
                          .append(" (offset ").append(offs).append(")\n");
                        delta += h.d - h.b; applied++;
                    } else sb.append("  hunk ").append(num).append(": rejected\n");
                }
                num++;
            }
            if (s.kind.equals("delete") && applied == s.hunks.size() && s.content.isEmpty()) {
                sb.append("  result: deleted\n");
            } else {
                byte[] out = toBytes(s.content);
                CRC32 crc = new CRC32();
                crc.update(out);
                sb.append("  result: ").append(s.content.size()).append(" lines, crc32 ")
                  .append(String.format("%08x", crc.getValue())).append('\n');
            }
        }
        System.out.print(sb);
    }
}

import Foundation

// ---------- Errors & control flow ----------

final class TernError: Error {
    let line: Int
    let msg: String
    init(_ line: Int, _ msg: String) { self.line = line; self.msg = msg }
}

enum Flow: Error { case ret(Value), brk, cont }

// ---------- Values ----------

final class Lst {
    var items: [Value]
    init(_ items: [Value]) { self.items = items }
}

final class FuncVal {
    enum Kind {
        case builtin(String, Int, ([Value], Int) throws -> Value)
        case user([String], [Stmt], Env)
    }
    let kind: Kind
    init(_ kind: Kind) { self.kind = kind }
}

enum Value {
    case int(Int64), boolean(Bool), string(String), list(Lst), function(FuncVal), nil_

    var typeName: String {
        switch self {
        case .int: return "int"
        case .boolean: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .function: return "function"
        case .nil_: return "nil"
        }
    }

    var isTruthy: Bool {
        switch self {
        case .boolean(let b): return b
        case .nil_: return false
        case .int(let i): return i != 0
        case .string(let s): return !s.isEmpty
        case .list(let l): return !l.items.isEmpty
        case .function: return true
        }
    }
}

func ternEq(_ a: Value, _ b: Value) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.boolean(let x), .boolean(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.items.count != y.items.count { return false }
        for i in 0..<x.items.count where !ternEq(x.items[i], y.items[i]) { return false }
        return true
    case (.function(let x), .function(let y)): return x === y
    default: return false
    }
}

func display(_ v: Value, _ active: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .boolean(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .string(let s): return s
    case .function: return "<fn>"
    case .list(let l):
        let id = ObjectIdentifier(l)
        if active.contains(id) { return "[...]" }
        active.insert(id)
        defer { active.remove(id) }
        return "[" + l.items.map { displayElem($0, &active) }.joined(separator: ", ") + "]"
    }
}

func displayElem(_ v: Value, _ active: inout Set<ObjectIdentifier>) -> String {
    if case .string(let s) = v {
        var r = "\""
        for c in s.utf8 {
            switch c {
            case 0x5C: r += "\\\\"
            case 0x22: r += "\\\""
            case 0x0A: r += "\\n"
            case 0x09: r += "\\t"
            default: r.unicodeScalars.append(UnicodeScalar(c))
            }
        }
        return r + "\""
    }
    return display(v, &active)
}

func displayTop(_ v: Value) -> String {
    var active = Set<ObjectIdentifier>()
    return display(v, &active)
}

// ---------- Environments ----------

final class Env {
    var vars: [String: Value] = [:]
    let parent: Env?
    init(_ parent: Env?) { self.parent = parent }
    func define(_ name: String, _ v: Value) { vars[name] = v }
    func get(_ name: String, _ line: Int) throws -> Value {
        var e: Env? = self
        while let cur = e {
            if let v = cur.vars[name] { return v }
            e = cur.parent
        }
        throw TernError(line, "undefined variable \(name)")
    }
    func assign(_ name: String, _ v: Value, _ line: Int) throws {
        var e: Env? = self
        while let cur = e {
            if cur.vars[name] != nil { cur.vars[name] = v; return }
            e = cur.parent
        }
        throw TernError(line, "undefined variable \(name)")
    }
}

// ---------- AST ----------

indirect enum Expr {
    case int(Int64), str(String), bool(Bool), nil_
    case list([Expr])
    case fnLit([String], [Stmt])
    case ident(String, Int)
    case unary(String, Expr, Int)
    case binary(String, Expr, Expr, Int)
    case call(Expr, [Expr], Int)
    case index(Expr, Expr, Int)
}

enum Stmt {
    case let_(String, Expr)
    case fnDecl(String, [String], [Stmt])
    case if_(Expr, [Stmt], Stmt?)
    case while_(Expr, [Stmt])
    case for_(String, Expr, [Stmt], Int)
    case return_(Expr?)
    case break_, continue_
    case assign(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int)
    case block([Stmt])
    case exprStmt(Expr)
}

// ---------- Lexer ----------

enum Kind: Equatable {
    case int(Int64), string(String), ident(String)
    case let_, fn_, if_, else_, while_, for_, in_, return_, break_, continue_
    case and_, or_, not_, true_, false_, nil_
    case eq, ne, le, ge, lt, gt, assign, plus, minus, star, slash, percent
    case lparen, rparen, lbrack, rbrack, lbrace, rbrace, comma, semi, eof
}

struct Token { let kind: Kind; let line: Int }

func lex(_ src: String) throws -> [Token] {
    let b = Array(src.utf8)
    var toks: [Token] = []
    var i = 0
    var line = 1
    let n = b.count
    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

    while i < n {
        let c = b[i]
        if c == 10 { line += 1; i += 1; continue }
        if c == 32 || c == 9 || c == 13 { i += 1; continue }
        if c == 35 { while i < n && b[i] != 10 { i += 1 }; continue }
        if isDigit(c) {
            let s = i
            while i < n && isDigit(b[i]) { i += 1 }
            guard let v = Int64(String(decoding: b[s..<i], as: UTF8.self)) else {
                throw TernError(line, "invalid integer literal")
            }
            toks.append(Token(kind: .int(v), line: line))
            continue
        }
        if isAlpha(c) {
            let s = i
            while i < n && (isAlpha(b[i]) || isDigit(b[i])) { i += 1 }
            let w = String(decoding: b[s..<i], as: UTF8.self)
            let k: Kind
            switch w {
            case "let": k = .let_
            case "fn": k = .fn_
            case "if": k = .if_
            case "else": k = .else_
            case "while": k = .while_
            case "for": k = .for_
            case "in": k = .in_
            case "return": k = .return_
            case "break": k = .break_
            case "continue": k = .continue_
            case "and": k = .and_
            case "or": k = .or_
            case "not": k = .not_
            case "true": k = .true_
            case "false": k = .false_
            case "nil": k = .nil_
            default: k = .ident(w)
            }
            toks.append(Token(kind: k, line: line))
            continue
        }
        if c == 34 {
            i += 1
            var s: [UInt8] = []
            while i < n && b[i] != 34 {
                if b[i] == 92 {
                    i += 1
                    switch b[i] {
                    case 110: s.append(10)
                    case 116: s.append(9)
                    case 34: s.append(34)
                    case 92: s.append(92)
                    default: throw TernError(line, "invalid escape")
                    }
                } else { s.append(b[i]) }
                i += 1
            }
            i += 1
            toks.append(Token(kind: .string(String(decoding: s, as: UTF8.self)), line: line))
            continue
        }
        if i + 1 < n {
            switch (c, b[i + 1]) {
            case (61, 61): toks.append(Token(kind: .eq, line: line)); i += 2; continue
            case (33, 61): toks.append(Token(kind: .ne, line: line)); i += 2; continue
            case (60, 61): toks.append(Token(kind: .le, line: line)); i += 2; continue
            case (62, 61): toks.append(Token(kind: .ge, line: line)); i += 2; continue
            default: break
            }
        }
        let k: Kind
        switch c {
        case 60: k = .lt
        case 62: k = .gt
        case 61: k = .assign
        case 43: k = .plus
        case 45: k = .minus
        case 42: k = .star
        case 47: k = .slash
        case 37: k = .percent
        case 40: k = .lparen
        case 41: k = .rparen
        case 91: k = .lbrack
        case 93: k = .rbrack
        case 123: k = .lbrace
        case 125: k = .rbrace
        case 44: k = .comma
        case 59: k = .semi
        default: throw TernError(line, "unexpected character")
        }
        toks.append(Token(kind: k, line: line))
        i += 1
    }
    toks.append(Token(kind: .eof, line: line))
    return toks
}

// ---------- Parser ----------

final class Parser {
    var toks: [Token]
    var pos = 0
    init(_ toks: [Token]) { self.toks = toks }

    func peek(_ off: Int = 0) -> Token { toks[min(pos + off, toks.count - 1)] }
    @discardableResult
    func advance() -> Token { let t = toks[pos]; if pos < toks.count - 1 { pos += 1 }; return t }
    func check(_ k: Kind) -> Bool { peek().kind == k }
    @discardableResult
    func accept(_ k: Kind) -> Bool { if check(k) { advance(); return true }; return false }
    @discardableResult
    func expect(_ k: Kind) throws -> Token {
        if check(k) { return advance() }
        throw TernError(peek().line, "syntax error")
    }
    func expectIdent() throws -> String {
        if case .ident(let nm) = peek().kind { advance(); return nm }
        throw TernError(peek().line, "syntax error")
    }

    func parseProgram() throws -> [Stmt] {
        var stmts: [Stmt] = []
        while !check(.eof) { stmts.append(try parseStmt()) }
        return stmts
    }

    func parseExprStmt() throws -> Stmt {
        let e = try parseExpr()
        if accept(.assign) {
            let v = try parseExpr()
            try expect(.semi)
            switch e {
            case .ident(let nm, let l): return .assign(nm, v, l)
            case .index(let o, let ix, let bl): return .indexAssign(o, ix, v, bl)
            default: throw TernError(peek().line, "invalid assignment")
            }
        }
        try expect(.semi)
        return .exprStmt(e)
    }

    func parseStmt() throws -> Stmt {
        switch peek().kind {
        case .let_:
            advance()
            let name = try expectIdent()
            try expect(.assign)
            let e = try parseExpr()
            try expect(.semi)
            return .let_(name, e)
        case .fn_:
            if case .ident = peek(1).kind {
                advance()
                let name = try expectIdent()
                let params = try parseParams()
                let body = try parseBlock()
                return .fnDecl(name, params, body)
            }
            return try parseExprStmt()
        case .if_:
            return try parseIf()
        case .while_:
            advance()
            let c = try parseExpr()
            let body = try parseBlock()
            return .while_(c, body)
        case .for_:
            let line = peek().line
            advance()
            let name = try expectIdent()
            try expect(.in_)
            let e = try parseExpr()
            let body = try parseBlock()
            return .for_(name, e, body, line)
        case .return_:
            advance()
            if accept(.semi) { return .return_(nil) }
            let e = try parseExpr()
            try expect(.semi)
            return .return_(e)
        case .break_:
            advance(); try expect(.semi); return .break_
        case .continue_:
            advance(); try expect(.semi); return .continue_
        default:
            return try parseExprStmt()
        }
    }

    func parseIf() throws -> Stmt {
        try expect(.if_)
        let c = try parseExpr()
        let thenB = try parseBlock()
        var elseS: Stmt? = nil
        if accept(.else_) {
            if check(.if_) { elseS = try parseIf() }
            else { elseS = .block(try parseBlock()) }
        }
        return .if_(c, thenB, elseS)
    }

    func parseBlock() throws -> [Stmt] {
        try expect(.lbrace)
        var stmts: [Stmt] = []
        while !check(.rbrace) { stmts.append(try parseStmt()) }
        advance()
        return stmts
    }

    func parseParams() throws -> [String] {
        try expect(.lparen)
        var ps: [String] = []
        if !check(.rparen) {
            ps.append(try expectIdent())
            while accept(.comma) { ps.append(try expectIdent()) }
        }
        try expect(.rparen)
        return ps
    }

    func parseExpr() throws -> Expr { try parseOr() }

    func parseOr() throws -> Expr {
        var l = try parseAnd()
        while check(.or_) {
            let line = peek().line; advance()
            l = .binary("or", l, try parseAnd(), line)
        }
        return l
    }

    func parseAnd() throws -> Expr {
        var l = try parseNot()
        while check(.and_) {
            let line = peek().line; advance()
            l = .binary("and", l, try parseNot(), line)
        }
        return l
    }

    func parseNot() throws -> Expr {
        if check(.not_) {
            let line = peek().line; advance()
            return .unary("not", try parseNot(), line)
        }
        return try parseCompare()
    }

    func parseCompare() throws -> Expr {
        var l = try parseAdd()
        while true {
            let k = peek().kind
            var op: String? = nil
            if k == .eq { op = "==" }
            else if k == .ne { op = "!=" }
            else if k == .lt { op = "<" }
            else if k == .le { op = "<=" }
            else if k == .gt { op = ">" }
            else if k == .ge { op = ">=" }
            guard let o = op else { break }
            let line = peek().line; advance()
            l = .binary(o, l, try parseAdd(), line)
        }
        return l
    }

    func parseAdd() throws -> Expr {
        var l = try parseMul()
        while true {
            if check(.plus) { let line = peek().line; advance(); l = .binary("+", l, try parseMul(), line) }
            else if check(.minus) { let line = peek().line; advance(); l = .binary("-", l, try parseMul(), line) }
            else { break }
        }
        return l
    }

    func parseMul() throws -> Expr {
        var l = try parseUnary()
        while true {
            if check(.star) { let line = peek().line; advance(); l = .binary("*", l, try parseUnary(), line) }
            else if check(.slash) { let line = peek().line; advance(); l = .binary("/", l, try parseUnary(), line) }
            else if check(.percent) { let line = peek().line; advance(); l = .binary("%", l, try parseUnary(), line) }
            else { break }
        }
        return l
    }

    func parseUnary() throws -> Expr {
        if check(.minus) {
            let line = peek().line; advance()
            return .unary("-", try parseUnary(), line)
        }
        return try parsePostfix()
    }

    func parsePostfix() throws -> Expr {
        var e = try parsePrimary()
        while true {
            if check(.lparen) {
                let line = peek().line; advance()
                var args: [Expr] = []
                if !check(.rparen) {
                    args.append(try parseExpr())
                    while accept(.comma) { args.append(try parseExpr()) }
                }
                try expect(.rparen)
                e = .call(e, args, line)
            } else if check(.lbrack) {
                let line = peek().line; advance()
                let ix = try parseExpr()
                try expect(.rbrack)
                e = .index(e, ix, line)
            } else { break }
        }
        return e
    }

    func parsePrimary() throws -> Expr {
        let t = advance()
        switch t.kind {
        case .int(let v): return .int(v)
        case .string(let s): return .str(s)
        case .true_: return .bool(true)
        case .false_: return .bool(false)
        case .nil_: return .nil_
        case .ident(let nm): return .ident(nm, t.line)
        case .lparen:
            let e = try parseExpr()
            try expect(.rparen)
            return e
        case .lbrack:
            var els: [Expr] = []
            if !check(.rbrack) {
                els.append(try parseExpr())
                while accept(.comma) { els.append(try parseExpr()) }
            }
            try expect(.rbrack)
            return .list(els)
        case .fn_:
            let ps = try parseParams()
            let body = try parseBlock()
            return .fnLit(ps, body)
        default: throw TernError(t.line, "syntax error")
        }
    }
}

// ---------- Interpreter ----------

final class Interp {
    func run(_ stmts: [Stmt], _ env: Env) throws {
        for s in stmts { try exec(s, env) }
    }

    func execBlock(_ stmts: [Stmt], _ env: Env) throws {
        let child = Env(env)
        for s in stmts { try exec(s, child) }
    }

    func exec(_ s: Stmt, _ env: Env) throws {
        switch s {
        case .let_(let name, let e):
            env.define(name, try eval(e, env))
        case .fnDecl(let name, let params, let body):
            env.define(name, .function(FuncVal(.user(params, body, env))))
        case .if_(let cond, let thenB, let elseS):
            if try eval(cond, env).isTruthy {
                try execBlock(thenB, env)
            } else if let e = elseS {
                try exec(e, env)
            }
        case .while_(let cond, let body):
            while try eval(cond, env).isTruthy {
                do { try execBlock(body, env) }
                catch Flow.brk { break }
                catch Flow.cont { }
            }
        case .for_(let name, let e, let body, let line):
            let v = try eval(e, env)
            guard case .list(let l) = v else {
                throw TernError(line, "cannot iterate \(v.typeName)")
            }
            var i = 0
            while i < l.items.count {
                let child = Env(env)
                child.define(name, l.items[i])
                do { for st in body { try exec(st, child) } }
                catch Flow.brk { break }
                catch Flow.cont { }
                i += 1
            }
        case .return_(let e):
            throw Flow.ret(e != nil ? try eval(e!, env) : .nil_)
        case .break_:
            throw Flow.brk
        case .continue_:
            throw Flow.cont
        case .assign(let name, let e, let line):
            let v = try eval(e, env)
            try env.assign(name, v, line)
        case .indexAssign(let obj, let ix, let val, let line):
            let ov = try eval(obj, env)
            let iv = try eval(ix, env)
            let vv = try eval(val, env)
            guard case .list(let l) = ov else {
                throw TernError(line, "cannot assign into \(ov.typeName)")
            }
            guard case .int(let idx) = iv else {
                throw TernError(line, "cannot index list with \(iv.typeName)")
            }
            guard idx >= 0 && idx < Int64(l.items.count) else {
                throw TernError(line, "index \(idx) out of range for length \(l.items.count)")
            }
            l.items[Int(idx)] = vv
        case .block(let stmts):
            try execBlock(stmts, env)
        case .exprStmt(let e):
            _ = try eval(e, env)
        }
    }

    func eval(_ e: Expr, _ env: Env) throws -> Value {
        switch e {
        case .int(let v): return .int(v)
        case .str(let s): return .string(s)
        case .bool(let b): return .boolean(b)
        case .nil_: return .nil_
        case .list(let els):
            var items: [Value] = []
            items.reserveCapacity(els.count)
            for x in els { items.append(try eval(x, env)) }
            return .list(Lst(items))
        case .fnLit(let params, let body):
            return .function(FuncVal(.user(params, body, env)))
        case .ident(let name, let line):
            return try env.get(name, line)
        case .unary(let op, let x, let line):
            if op == "not" { return .boolean(!try eval(x, env).isTruthy) }
            let v = try eval(x, env)
            guard case .int(let i) = v else {
                throw TernError(line, "cannot apply - to \(v.typeName)")
            }
            let (r, of) = i.multipliedReportingOverflow(by: -1)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case .binary(let op, let a, let b, let line):
            if op == "and" {
                let va = try eval(a, env)
                return va.isTruthy ? try eval(b, env) : va
            }
            if op == "or" {
                let va = try eval(a, env)
                return va.isTruthy ? va : try eval(b, env)
            }
            let va = try eval(a, env)
            let vb = try eval(b, env)
            return try binop(op, va, vb, line)
        case .call(let callee, let args, let line):
            let f = try eval(callee, env)
            var av: [Value] = []
            av.reserveCapacity(args.count)
            for x in args { av.append(try eval(x, env)) }
            guard case .function(let fv) = f else {
                throw TernError(line, "cannot call \(f.typeName)")
            }
            switch fv.kind {
            case .builtin(_, let arity, let fn):
                if arity >= 0 && av.count != arity {
                    throw TernError(line, "expected \(arity) arguments, got \(av.count)")
                }
                return try fn(av, line)
            case .user(let params, let body, let fenv):
                if params.count != av.count {
                    throw TernError(line, "expected \(params.count) arguments, got \(av.count)")
                }
                let callEnv = Env(fenv)
                for i in 0..<params.count { callEnv.define(params[i], av[i]) }
                do {
                    for st in body { try exec(st, callEnv) }
                } catch Flow.ret(let v) {
                    return v
                }
                return .nil_
            }
        case .index(let obj, let ix, let line):
            let ov = try eval(obj, env)
            let iv = try eval(ix, env)
            switch ov {
            case .list(let l):
                guard case .int(let idx) = iv else {
                    throw TernError(line, "cannot index list with \(iv.typeName)")
                }
                guard idx >= 0 && idx < Int64(l.items.count) else {
                    throw TernError(line, "index \(idx) out of range for length \(l.items.count)")
                }
                return l.items[Int(idx)]
            case .string(let s):
                guard case .int(let idx) = iv else {
                    throw TernError(line, "cannot index string with \(iv.typeName)")
                }
                let u = s.utf8
                guard idx >= 0 && idx < Int64(u.count) else {
                    throw TernError(line, "index \(idx) out of range for length \(u.count)")
                }
                let j = u.index(u.startIndex, offsetBy: Int(idx))
                return .string(String(UnicodeScalar(u[j])))
            default:
                throw TernError(line, "cannot index \(ov.typeName) with \(iv.typeName)")
            }
        }
    }

    func binop(_ op: String, _ a: Value, _ b: Value, _ line: Int) throws -> Value {
        switch op {
        case "+":
            if case .int(let x) = a, case .int(let y) = b {
                let (r, of) = x.addingReportingOverflow(y)
                if of { throw TernError(line, "integer overflow") }
                return .int(r)
            }
            if case .string(let x) = a, case .string(let y) = b { return .string(x + y) }
            if case .list(let x) = a, case .list(let y) = b { return .list(Lst(x.items + y.items)) }
            throw TernError(line, "cannot apply + to \(a.typeName) and \(b.typeName)")
        case "-":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply - to \(a.typeName) and \(b.typeName)")
            }
            let (r, of) = x.subtractingReportingOverflow(y)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case "*":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply * to \(a.typeName) and \(b.typeName)")
            }
            let (r, of) = x.multipliedReportingOverflow(y)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case "/":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply / to \(a.typeName) and \(b.typeName)")
            }
            if y == 0 { throw TernError(line, "division by zero") }
            if x == Int64.min && y == -1 { throw TernError(line, "integer overflow") }
            return .int(x / y)
        case "%":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply % to \(a.typeName) and \(b.typeName)")
            }
            if y == 0 { throw TernError(line, "division by zero") }
            if y == -1 { return .int(0) }
            return .int(x % y)
        case "==": return .boolean(ternEq(a, b))
        case "!=": return .boolean(!ternEq(a, b))
        case "<", "<=", ">", ">=":
            if case .int(let x) = a, case .int(let y) = b {
                switch op {
                case "<": return .boolean(x < y)
                case "<=": return .boolean(x <= y)
                case ">": return .boolean(x > y)
                default: return .boolean(x >= y)
                }
            }
            if case .string(let x) = a, case .string(let y) = b {
                switch op {
                case "<": return .boolean(x < y)
                case "<=": return .boolean(x <= y)
                case ">": return .boolean(x > y)
                default: return .boolean(x >= y)
                }
            }
            throw TernError(line, "cannot apply \(op) to \(a.typeName) and \(b.typeName)")
        default: fatalError()
        }
    }
}

// ---------- Builtins ----------

func makeGlobals() -> Env {
    let env = Env(nil)
    func add(_ name: String, _ arity: Int, _ fn: @escaping ([Value], Int) throws -> Value) {
        env.define(name, .function(FuncVal(.builtin(name, arity, fn))))
    }
    add("print", -1) { args, _ in
        print(args.map { displayTop($0) }.joined(separator: " "))
        return .nil_
    }
    add("str", 1) { args, _ in .string(displayTop(args[0])) }
    add("type", 1) { args, _ in .string(args[0].typeName) }
    add("len", 1) { args, line in
        switch args[0] {
        case .string(let s): return .int(Int64(s.count))
        case .list(let l): return .int(Int64(l.items.count))
        default: throw TernError(line, "bad argument to len")
        }
    }
    add("push", 2) { args, line in
        guard case .list(let l) = args[0] else { throw TernError(line, "bad argument to push") }
        l.items.append(args[1])
        return .nil_
    }
    add("pop", 1) { args, line in
        guard case .list(let l) = args[0], !l.items.isEmpty else {
            throw TernError(line, "bad argument to pop")
        }
        return l.items.removeLast()
    }
    add("range", 2) { args, line in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line, "bad argument to range")
        }
        var items: [Value] = []
        if b > a {
            let count = Int(b - a)
            items.reserveCapacity(count)
            var x = a
            for _ in 0..<count { items.append(.int(x)); x += 1 }
        }
        return .list(Lst(items))
    }
    add("slice", 3) { args, line in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line, "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let n = s.count
            guard a >= 0 && a <= b && b <= Int64(n) else {
                throw TernError(line, "bad argument to slice")
            }
            let arr = Array(s)
            return .string(String(arr[Int(a)..<Int(b)]))
        case .list(let l):
            let n = l.items.count
            guard a >= 0 && a <= b && b <= Int64(n) else {
                throw TernError(line, "bad argument to slice")
            }
            return .list(Lst(Array(l.items[Int(a)..<Int(b)])))
        default:
            throw TernError(line, "bad argument to slice")
        }
    }
    return env
}

// ---------- Main ----------

func main() {
    guard CommandLine.arguments.count > 1 else { return }
    let path = CommandLine.arguments[1] + "/program.tern"
    guard let src = try? String(contentsOfFile: path, encoding: .utf8) else { return }
    do {
        let toks = try lex(src)
        let prog = try Parser(toks).parseProgram()
        let builtins = makeGlobals()
        let globals = Env(builtins)
        try Interp().run(prog, globals)
    } catch let e as TernError {
        print("error at line \(e.line): \(e.msg)")
    } catch {
        // control-flow signals escaping top level (cannot happen in valid programs)
    }
}

main()

import Foundation

// ---------- Errors & control flow ----------

final class TernError: Error {
    let line: Int
    let msg: String
    init(_ line: Int, _ msg: String) { self.line = line; self.msg = msg }
}

enum Flow: Error { case ret(Value), brk, cont }

// ---------- Values ----------

final class Lst {
    var items: [Value]
    init(_ items: [Value]) { self.items = items }
}

final class FuncVal {
    enum Kind {
        case builtin(String, Int, ([Value], Int) throws -> Value)
        case user([String], [Stmt], Env)
    }
    let kind: Kind
    init(_ kind: Kind) { self.kind = kind }
}

enum Value {
    case int(Int64), boolean(Bool), string(String), list(Lst), function(FuncVal), nil_

    var typeName: String {
        switch self {
        case .int: return "int"
        case .boolean: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .function: return "function"
        case .nil_: return "nil"
        }
    }

    var isTruthy: Bool {
        switch self {
        case .boolean(let b): return b
        case .nil_: return false
        case .int(let i): return i != 0
        case .string(let s): return !s.isEmpty
        case .list(let l): return !l.items.isEmpty
        case .function: return true
        }
    }
}

func ternEq(_ a: Value, _ b: Value) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.boolean(let x), .boolean(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.items.count != y.items.count { return false }
        for i in 0..<x.items.count where !ternEq(x.items[i], y.items[i]) { return false }
        return true
    case (.function(let x), .function(let y)): return x === y
    default: return false
    }
}

func display(_ v: Value, _ active: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .boolean(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .string(let s): return s
    case .function: return "<fn>"
    case .list(let l):
        let id = ObjectIdentifier(l)
        if active.contains(id) { return "[...]" }
        active.insert(id)
        defer { active.remove(id) }
        return "[" + l.items.map { displayElem($0, &active) }.joined(separator: ", ") + "]"
    }
}

func displayElem(_ v: Value, _ active: inout Set<ObjectIdentifier>) -> String {
    if case .string(let s) = v {
        var r = "\""
        for c in s.utf8 {
            switch c {
            case 0x5C: r += "\\\\"
            case 0x22: r += "\\\""
            case 0x0A: r += "\\n"
            case 0x09: r += "\\t"
            default: r.unicodeScalars.append(UnicodeScalar(c))
            }
        }
        return r + "\""
    }
    return display(v, &active)
}

func displayTop(_ v: Value) -> String {
    var active = Set<ObjectIdentifier>()
    return display(v, &active)
}

// ---------- Environments ----------

final class Env {
    var vars: [String: Value] = [:]
    let parent: Env?
    init(_ parent: Env?) { self.parent = parent }
    func define(_ name: String, _ v: Value) { vars[name] = v }
    func get(_ name: String, _ line: Int) throws -> Value {
        var e: Env? = self
        while let cur = e {
            if let v = cur.vars[name] { return v }
            e = cur.parent
        }
        throw TernError(line, "undefined variable \(name)")
    }
    func assign(_ name: String, _ v: Value, _ line: Int) throws {
        var e: Env? = self
        while let cur = e {
            if cur.vars[name] != nil { cur.vars[name] = v; return }
            e = cur.parent
        }
        throw TernError(line, "undefined variable \(name)")
    }
}

// ---------- AST ----------

indirect enum Expr {
    case int(Int64), str(String), bool(Bool), nil_
    case list([Expr])
    case fnLit([String], [Stmt])
    case ident(String, Int)
    case unary(String, Expr, Int)
    case binary(String, Expr, Expr, Int)
    case call(Expr, [Expr], Int)
    case index(Expr, Expr, Int)
}

indirect enum Stmt {
    case let_(String, Expr)
    case fnDecl(String, [String], [Stmt])
    case if_(Expr, [Stmt], Stmt?)
    case while_(Expr, [Stmt])
    case for_(String, Expr, [Stmt], Int)
    case return_(Expr?)
    case break_, continue_
    case assign(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int)
    case block([Stmt])
    case exprStmt(Expr)
}

// ---------- Lexer ----------

enum Kind: Equatable {
    case int(Int64), string(String), ident(String)
    case let_, fn_, if_, else_, while_, for_, in_, return_, break_, continue_
    case and_, or_, not_, true_, false_, nil_
    case eq, ne, le, ge, lt, gt, assign, plus, minus, star, slash, percent
    case lparen, rparen, lbrack, rbrack, lbrace, rbrace, comma, semi, eof
}

struct Token { let kind: Kind; let line: Int }

func lex(_ src: String) throws -> [Token] {
    let b = Array(src.utf8)
    var toks: [Token] = []
    var i = 0
    var line = 1
    let n = b.count
    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

    while i < n {
        let c = b[i]
        if c == 10 { line += 1; i += 1; continue }
        if c == 32 || c == 9 || c == 13 { i += 1; continue }
        if c == 35 { while i < n && b[i] != 10 { i += 1 }; continue }
        if isDigit(c) {
            let s = i
            while i < n && isDigit(b[i]) { i += 1 }
            guard let v = Int64(String(decoding: b[s..<i], as: UTF8.self)) else {
                throw TernError(line, "invalid integer literal")
            }
            toks.append(Token(kind: .int(v), line: line))
            continue
        }
        if isAlpha(c) {
            let s = i
            while i < n && (isAlpha(b[i]) || isDigit(b[i])) { i += 1 }
            let w = String(decoding: b[s..<i], as: UTF8.self)
            let k: Kind
            switch w {
            case "let": k = .let_
            case "fn": k = .fn_
            case "if": k = .if_
            case "else": k = .else_
            case "while": k = .while_
            case "for": k = .for_
            case "in": k = .in_
            case "return": k = .return_
            case "break": k = .break_
            case "continue": k = .continue_
            case "and": k = .and_
            case "or": k = .or_
            case "not": k = .not_
            case "true": k = .true_
            case "false": k = .false_
            case "nil": k = .nil_
            default: k = .ident(w)
            }
            toks.append(Token(kind: k, line: line))
            continue
        }
        if c == 34 {
            i += 1
            var s: [UInt8] = []
            while i < n && b[i] != 34 {
                if b[i] == 92 {
                    i += 1
                    switch b[i] {
                    case 110: s.append(10)
                    case 116: s.append(9)
                    case 34: s.append(34)
                    case 92: s.append(92)
                    default: throw TernError(line, "invalid escape")
                    }
                } else { s.append(b[i]) }
                i += 1
            }
            i += 1
            toks.append(Token(kind: .string(String(decoding: s, as: UTF8.self)), line: line))
            continue
        }
        if i + 1 < n {
            switch (c, b[i + 1]) {
            case (61, 61): toks.append(Token(kind: .eq, line: line)); i += 2; continue
            case (33, 61): toks.append(Token(kind: .ne, line: line)); i += 2; continue
            case (60, 61): toks.append(Token(kind: .le, line: line)); i += 2; continue
            case (62, 61): toks.append(Token(kind: .ge, line: line)); i += 2; continue
            default: break
            }
        }
        let k: Kind
        switch c {
        case 60: k = .lt
        case 62: k = .gt
        case 61: k = .assign
        case 43: k = .plus
        case 45: k = .minus
        case 42: k = .star
        case 47: k = .slash
        case 37: k = .percent
        case 40: k = .lparen
        case 41: k = .rparen
        case 91: k = .lbrack
        case 93: k = .rbrack
        case 123: k = .lbrace
        case 125: k = .rbrace
        case 44: k = .comma
        case 59: k = .semi
        default: throw TernError(line, "unexpected character")
        }
        toks.append(Token(kind: k, line: line))
        i += 1
    }
    toks.append(Token(kind: .eof, line: line))
    return toks
}

// ---------- Parser ----------

final class Parser {
    var toks: [Token]
    var pos = 0
    init(_ toks: [Token]) { self.toks = toks }

    func peek(_ off: Int = 0) -> Token { toks[min(pos + off, toks.count - 1)] }
    @discardableResult
    func advance() -> Token { let t = toks[pos]; if pos < toks.count - 1 { pos += 1 }; return t }
    func check(_ k: Kind) -> Bool { peek().kind == k }
    @discardableResult
    func accept(_ k: Kind) -> Bool { if check(k) { advance(); return true }; return false }
    @discardableResult
    func expect(_ k: Kind) throws -> Token {
        if check(k) { return advance() }
        throw TernError(peek().line, "syntax error")
    }
    func expectIdent() throws -> String {
        if case .ident(let nm) = peek().kind { advance(); return nm }
        throw TernError(peek().line, "syntax error")
    }

    func parseProgram() throws -> [Stmt] {
        var stmts: [Stmt] = []
        while !check(.eof) { stmts.append(try parseStmt()) }
        return stmts
    }

    func parseExprStmt() throws -> Stmt {
        let e = try parseExpr()
        if accept(.assign) {
            let v = try parseExpr()
            try expect(.semi)
            switch e {
            case .ident(let nm, let l): return .assign(nm, v, l)
            case .index(let o, let ix, let bl): return .indexAssign(o, ix, v, bl)
            default: throw TernError(peek().line, "invalid assignment")
            }
        }
        try expect(.semi)
        return .exprStmt(e)
    }

    func parseStmt() throws -> Stmt {
        switch peek().kind {
        case .let_:
            advance()
            let name = try expectIdent()
            try expect(.assign)
            let e = try parseExpr()
            try expect(.semi)
            return .let_(name, e)
        case .fn_:
            if case .ident = peek(1).kind {
                advance()
                let name = try expectIdent()
                let params = try parseParams()
                let body = try parseBlock()
                return .fnDecl(name, params, body)
            }
            return try parseExprStmt()
        case .if_:
            return try parseIf()
        case .while_:
            advance()
            let c = try parseExpr()
            let body = try parseBlock()
            return .while_(c, body)
        case .for_:
            let line = peek().line
            advance()
            let name = try expectIdent()
            try expect(.in_)
            let e = try parseExpr()
            let body = try parseBlock()
            return .for_(name, e, body, line)
        case .return_:
            advance()
            if accept(.semi) { return .return_(nil) }
            let e = try parseExpr()
            try expect(.semi)
            return .return_(e)
        case .break_:
            advance(); try expect(.semi); return .break_
        case .continue_:
            advance(); try expect(.semi); return .continue_
        default:
            return try parseExprStmt()
        }
    }

    func parseIf() throws -> Stmt {
        try expect(.if_)
        let c = try parseExpr()
        let thenB = try parseBlock()
        var elseS: Stmt? = nil
        if accept(.else_) {
            if check(.if_) { elseS = try parseIf() }
            else { elseS = .block(try parseBlock()) }
        }
        return .if_(c, thenB, elseS)
    }

    func parseBlock() throws -> [Stmt] {
        try expect(.lbrace)
        var stmts: [Stmt] = []
        while !check(.rbrace) { stmts.append(try parseStmt()) }
        advance()
        return stmts
    }

    func parseParams() throws -> [String] {
        try expect(.lparen)
        var ps: [String] = []
        if !check(.rparen) {
            ps.append(try expectIdent())
            while accept(.comma) { ps.append(try expectIdent()) }
        }
        try expect(.rparen)
        return ps
    }

    func parseExpr() throws -> Expr { try parseOr() }

    func parseOr() throws -> Expr {
        var l = try parseAnd()
        while check(.or_) {
            let line = peek().line; advance()
            l = .binary("or", l, try parseAnd(), line)
        }
        return l
    }

    func parseAnd() throws -> Expr {
        var l = try parseNot()
        while check(.and_) {
            let line = peek().line; advance()
            l = .binary("and", l, try parseNot(), line)
        }
        return l
    }

    func parseNot() throws -> Expr {
        if check(.not_) {
            let line = peek().line; advance()
            return .unary("not", try parseNot(), line)
        }
        return try parseCompare()
    }

    func parseCompare() throws -> Expr {
        var l = try parseAdd()
        while true {
            let k = peek().kind
            var op: String? = nil
            if k == .eq { op = "==" }
            else if k == .ne { op = "!=" }
            else if k == .lt { op = "<" }
            else if k == .le { op = "<=" }
            else if k == .gt { op = ">" }
            else if k == .ge { op = ">=" }
            guard let o = op else { break }
            let line = peek().line; advance()
            l = .binary(o, l, try parseAdd(), line)
        }
        return l
    }

    func parseAdd() throws -> Expr {
        var l = try parseMul()
        while true {
            if check(.plus) { let line = peek().line; advance(); l = .binary("+", l, try parseMul(), line) }
            else if check(.minus) { let line = peek().line; advance(); l = .binary("-", l, try parseMul(), line) }
            else { break }
        }
        return l
    }

    func parseMul() throws -> Expr {
        var l = try parseUnary()
        while true {
            if check(.star) { let line = peek().line; advance(); l = .binary("*", l, try parseUnary(), line) }
            else if check(.slash) { let line = peek().line; advance(); l = .binary("/", l, try parseUnary(), line) }
            else if check(.percent) { let line = peek().line; advance(); l = .binary("%", l, try parseUnary(), line) }
            else { break }
        }
        return l
    }

    func parseUnary() throws -> Expr {
        if check(.minus) {
            let line = peek().line; advance()
            return .unary("-", try parseUnary(), line)
        }
        return try parsePostfix()
    }

    func parsePostfix() throws -> Expr {
        var e = try parsePrimary()
        while true {
            if check(.lparen) {
                let line = peek().line; advance()
                var args: [Expr] = []
                if !check(.rparen) {
                    args.append(try parseExpr())
                    while accept(.comma) { args.append(try parseExpr()) }
                }
                try expect(.rparen)
                e = .call(e, args, line)
            } else if check(.lbrack) {
                let line = peek().line; advance()
                let ix = try parseExpr()
                try expect(.rbrack)
                e = .index(e, ix, line)
            } else { break }
        }
        return e
    }

    func parsePrimary() throws -> Expr {
        let t = advance()
        switch t.kind {
        case .int(let v): return .int(v)
        case .string(let s): return .str(s)
        case .true_: return .bool(true)
        case .false_: return .bool(false)
        case .nil_: return .nil_
        case .ident(let nm): return .ident(nm, t.line)
        case .lparen:
            let e = try parseExpr()
            try expect(.rparen)
            return e
        case .lbrack:
            var els: [Expr] = []
            if !check(.rbrack) {
                els.append(try parseExpr())
                while accept(.comma) { els.append(try parseExpr()) }
            }
            try expect(.rbrack)
            return .list(els)
        case .fn_:
            let ps = try parseParams()
            let body = try parseBlock()
            return .fnLit(ps, body)
        default: throw TernError(t.line, "syntax error")
        }
    }
}

// ---------- Interpreter ----------

final class Interp {
    func run(_ stmts: [Stmt], _ env: Env) throws {
        for s in stmts { try exec(s, env) }
    }

    func execBlock(_ stmts: [Stmt], _ env: Env) throws {
        let child = Env(env)
        for s in stmts { try exec(s, child) }
    }

    func exec(_ s: Stmt, _ env: Env) throws {
        switch s {
        case .let_(let name, let e):
            env.define(name, try eval(e, env))
        case .fnDecl(let name, let params, let body):
            env.define(name, .function(FuncVal(.user(params, body, env))))
        case .if_(let cond, let thenB, let elseS):
            if try eval(cond, env).isTruthy {
                try execBlock(thenB, env)
            } else if let e = elseS {
                try exec(e, env)
            }
        case .while_(let cond, let body):
            while try eval(cond, env).isTruthy {
                do { try execBlock(body, env) }
                catch Flow.brk { break }
                catch Flow.cont { }
            }
        case .for_(let name, let e, let body, let line):
            let v = try eval(e, env)
            guard case .list(let l) = v else {
                throw TernError(line, "cannot iterate \(v.typeName)")
            }
            var i = 0
            while i < l.items.count {
                let child = Env(env)
                child.define(name, l.items[i])
                do { for st in body { try exec(st, child) } }
                catch Flow.brk { break }
                catch Flow.cont { }
                i += 1
            }
        case .return_(let e):
            throw Flow.ret(e != nil ? try eval(e!, env) : .nil_)
        case .break_:
            throw Flow.brk
        case .continue_:
            throw Flow.cont
        case .assign(let name, let e, let line):
            let v = try eval(e, env)
            try env.assign(name, v, line)
        case .indexAssign(let obj, let ix, let val, let line):
            let ov = try eval(obj, env)
            let iv = try eval(ix, env)
            let vv = try eval(val, env)
            guard case .list(let l) = ov else {
                throw TernError(line, "cannot assign into \(ov.typeName)")
            }
            guard case .int(let idx) = iv else {
                throw TernError(line, "cannot index list with \(iv.typeName)")
            }
            guard idx >= 0 && idx < Int64(l.items.count) else {
                throw TernError(line, "index \(idx) out of range for length \(l.items.count)")
            }
            l.items[Int(idx)] = vv
        case .block(let stmts):
            try execBlock(stmts, env)
        case .exprStmt(let e):
            _ = try eval(e, env)
        }
    }

    func eval(_ e: Expr, _ env: Env) throws -> Value {
        switch e {
        case .int(let v): return .int(v)
        case .str(let s): return .string(s)
        case .bool(let b): return .boolean(b)
        case .nil_: return .nil_
        case .list(let els):
            var items: [Value] = []
            items.reserveCapacity(els.count)
            for x in els { items.append(try eval(x, env)) }
            return .list(Lst(items))
        case .fnLit(let params, let body):
            return .function(FuncVal(.user(params, body, env)))
        case .ident(let name, let line):
            return try env.get(name, line)
        case .unary(let op, let x, let line):
            if op == "not" {
                let v = try eval(x, env)
                return .boolean(!v.isTruthy)
            }
            let v = try eval(x, env)
            guard case .int(let i) = v else {
                throw TernError(line, "cannot apply - to \(v.typeName)")
            }
            let (r, of) = i.multipliedReportingOverflow(by: -1)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case .binary(let op, let a, let b, let line):
            if op == "and" {
                let va = try eval(a, env)
                return va.isTruthy ? try eval(b, env) : va
            }
            if op == "or" {
                let va = try eval(a, env)
                return va.isTruthy ? va : try eval(b, env)
            }
            let va = try eval(a, env)
            let vb = try eval(b, env)
            return try binop(op, va, vb, line)
        case .call(let callee, let args, let line):
            let f = try eval(callee, env)
            var av: [Value] = []
            av.reserveCapacity(args.count)
            for x in args { av.append(try eval(x, env)) }
            guard case .function(let fv) = f else {
                throw TernError(line, "cannot call \(f.typeName)")
            }
            switch fv.kind {
            case .builtin(_, let arity, let fn):
                if arity >= 0 && av.count != arity {
                    throw TernError(line, "expected \(arity) arguments, got \(av.count)")
                }
                return try fn(av, line)
            case .user(let params, let body, let fenv):
                if params.count != av.count {
                    throw TernError(line, "expected \(params.count) arguments, got \(av.count)")
                }
                let callEnv = Env(fenv)
                for i in 0..<params.count { callEnv.define(params[i], av[i]) }
                do {
                    for st in body { try exec(st, callEnv) }
                } catch Flow.ret(let v) {
                    return v
                }
                return .nil_
            }
        case .index(let obj, let ix, let line):
            let ov = try eval(obj, env)
            let iv = try eval(ix, env)
            switch ov {
            case .list(let l):
                guard case .int(let idx) = iv else {
                    throw TernError(line, "cannot index list with \(iv.typeName)")
                }
                guard idx >= 0 && idx < Int64(l.items.count) else {
                    throw TernError(line, "index \(idx) out of range for length \(l.items.count)")
                }
                return l.items[Int(idx)]
            case .string(let s):
                guard case .int(let idx) = iv else {
                    throw TernError(line, "cannot index string with \(iv.typeName)")
                }
                let u = s.utf8
                guard idx >= 0 && idx < Int64(u.count) else {
                    throw TernError(line, "index \(idx) out of range for length \(u.count)")
                }
                let j = u.index(u.startIndex, offsetBy: Int(idx))
                return .string(String(UnicodeScalar(u[j])))
            default:
                throw TernError(line, "cannot index \(ov.typeName) with \(iv.typeName)")
            }
        }
    }

    func binop(_ op: String, _ a: Value, _ b: Value, _ line: Int) throws -> Value {
        switch op {
        case "+":
            if case .int(let x) = a, case .int(let y) = b {
                let (r, of) = x.addingReportingOverflow(y)
                if of { throw TernError(line, "integer overflow") }
                return .int(r)
            }
            if case .string(let x) = a, case .string(let y) = b { return .string(x + y) }
            if case .list(let x) = a, case .list(let y) = b { return .list(Lst(x.items + y.items)) }
            throw TernError(line, "cannot apply + to \(a.typeName) and \(b.typeName)")
        case "-":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply - to \(a.typeName) and \(b.typeName)")
            }
            let (r, of) = x.subtractingReportingOverflow(y)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case "*":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply * to \(a.typeName) and \(b.typeName)")
            }
            let (r, of) = x.multipliedReportingOverflow(by: y)
            if of { throw TernError(line, "integer overflow") }
            return .int(r)
        case "/":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply / to \(a.typeName) and \(b.typeName)")
            }
            if y == 0 { throw TernError(line, "division by zero") }
            if x == Int64.min && y == -1 { throw TernError(line, "integer overflow") }
            return .int(x / y)
        case "%":
            guard case .int(let x) = a, case .int(let y) = b else {
                throw TernError(line, "cannot apply % to \(a.typeName) and \(b.typeName)")
            }
            if y == 0 { throw TernError(line, "division by zero") }
            if y == -1 { return .int(0) }
            return .int(x % y)
        case "==": return .boolean(ternEq(a, b))
        case "!=": return .boolean(!ternEq(a, b))
        case "<", "<=", ">", ">=":
            if case .int(let x) = a, case .int(let y) = b {
                switch op {
                case "<": return .boolean(x < y)
                case "<=": return .boolean(x <= y)
                case ">": return .boolean(x > y)
                default: return .boolean(x >= y)
                }
            }
            if case .string(let x) = a, case .string(let y) = b {
                switch op {
                case "<": return .boolean(x < y)
                case "<=": return .boolean(x <= y)
                case ">": return .boolean(x > y)
                default: return .boolean(x >= y)
                }
            }
            throw TernError(line, "cannot apply \(op) to \(a.typeName) and \(b.typeName)")
        default: fatalError()
        }
    }
}

// ---------- Builtins ----------

func makeGlobals() -> Env {
    let env = Env(nil)
    func add(_ name: String, _ arity: Int, _ fn: @escaping ([Value], Int) throws -> Value) {
        env.define(name, .function(FuncVal(.builtin(name, arity, fn))))
    }
    add("print", -1) { args, _ in
        print(args.map { displayTop($0) }.joined(separator: " "))
        return .nil_
    }
    add("str", 1) { args, _ in .string(displayTop(args[0])) }
    add("type", 1) { args, _ in .string(args[0].typeName) }
    add("len", 1) { args, line in
        switch args[0] {
        case .string(let s): return .int(Int64(s.count))
        case .list(let l): return .int(Int64(l.items.count))
        default: throw TernError(line, "bad argument to len")
        }
    }
    add("push", 2) { args, line in
        guard case .list(let l) = args[0] else { throw TernError(line, "bad argument to push") }
        l.items.append(args[1])
        return .nil_
    }
    add("pop", 1) { args, line in
        guard case .list(let l) = args[0], !l.items.isEmpty else {
            throw TernError(line, "bad argument to pop")
        }
        return l.items.removeLast()
    }
    add("range", 2) { args, line in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line, "bad argument to range")
        }
        var items: [Value] = []
        if b > a {
            let count = Int(b - a)
            items.reserveCapacity(count)
            var x = a
            for _ in 0..<count { items.append(.int(x)); x += 1 }
        }
        return .list(Lst(items))
    }
    add("slice", 3) { args, line in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line, "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let n = s.count
            guard a >= 0 && a <= b && b <= Int64(n) else {
                throw TernError(line, "bad argument to slice")
            }
            let arr = Array(s)
            return .string(String(arr[Int(a)..<Int(b)]))
        case .list(let l):
            let n = l.items.count
            guard a >= 0 && a <= b && b <= Int64(n) else {
                throw TernError(line, "bad argument to slice")
            }
            return .list(Lst(Array(l.items[Int(a)..<Int(b)])))
        default:
            throw TernError(line, "bad argument to slice")
        }
    }
    return env
}

// ---------- Main ----------

func main() {
    guard CommandLine.arguments.count > 1 else { return }
    let path = CommandLine.arguments[1] + "/program.tern"
    guard let src = try? String(contentsOfFile: path, encoding: .utf8) else { return }
    do {
        let toks = try lex(src)
        let prog = try Parser(toks).parseProgram()
        let builtins = makeGlobals()
        let globals = Env(builtins)
        try Interp().run(prog, globals)
    } catch let e as TernError {
        print("error at line \(e.line): \(e.msg)")
    } catch {
        // control-flow signals escaping top level (cannot happen in valid programs)
    }
}

main()

import * as fs from 'fs';
import * as path from 'path';

type Line = { data: Buffer; nl: boolean };

function splitLines(buf: Buffer): Line[] {
  const lines: Line[] = [];
  let start = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 0x0a) {
      lines.push({ data: buf.subarray(start, i), nl: true });
      start = i + 1;
    }
  }
  if (start < buf.length) lines.push({ data: buf.subarray(start), nl: false });
  return lines;
}

function joinLines(lines: Line[]): Buffer {
  const parts: Buffer[] = [];
  for (const l of lines) {
    parts.push(l.data);
    if (l.nl) parts.push(Buffer.from([0x0a]));
  }
  return Buffer.concat(parts);
}

function eq(a: Line, b: Line): boolean {
  return a.nl === b.nl && a.data.equals(b.data);
}

const crcTable = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf: Buffer): string {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = crcTable[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return ((c ^ 0xffffffff) >>> 0).toString(16).padStart(8, '0');
}

function startsWith(b: Buffer, s: string): boolean {
  const p = Buffer.from(s, 'latin1');
  if (b.length < p.length) return false;
  return b.subarray(0, p.length).equals(p);
}

interface Hunk {
  m: RegExpExecArray | null;
  body: Buffer[];
}
interface Section {
  file: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
}

function parseDiff(buf: Buffer): Section[] {
  const raw = splitLines(buf).map((l) => l.data);
  const sections: Section[] = [];
  let i = 0;
  while (i < raw.length) {
    if (!startsWith(raw[i], 'diff --git a/')) {
      i++;
      continue;
    }
    const s = raw[i].toString('latin1');
    const rest = s.slice('diff --git a/'.length);
    const idx = rest.indexOf(' b/');
    const file = idx >= 0 ? rest.slice(0, idx) : rest;
    i++;
    let kind: 'create' | 'delete' | 'modify' = 'modify';
    while (i < raw.length) {
      if (startsWith(raw[i], 'new file mode ')) {
        kind = 'create';
        i++;
      } else if (startsWith(raw[i], 'deleted file mode ')) {
        kind = 'delete';
        i++;
      } else if (startsWith(raw[i], 'index ')) {
        i++;
      } else break;
    }
    const hunks: Hunk[] = [];
    while (i < raw.length && !startsWith(raw[i], 'diff --git ')) {
      if (startsWith(raw[i], '@@ ')) {
        const header = raw[i].toString('latin1');
        const m = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(header);
        i++;
        const body: Buffer[] = [];
        while (
          i < raw.length &&
          !startsWith(raw[i], '@@ ') &&
          !startsWith(raw[i], 'diff --git ')
        ) {
          body.push(raw[i]);
          i++;
        }
        hunks.push({ m, body });
      } else {
        i++;
      }
    }
    sections.push({ file, kind, hunks });
  }
  return sections;
}

function buildSides(body: Buffer[]): { oldL: Line[]; newL: Line[] } {
  const oldL: Line[] = [];
  const newL: Line[] = [];
  for (let j = 0; j < body.length; j++) {
    const marker = String.fromCharCode(body[j][0]);
    if (marker === '\\') continue;
    const content = body[j].subarray(1);
    let nl = true;
    if (j + 1 < body.length && body[j + 1][0] === 0x5c) nl = false;
    if (marker === ' ') {
      oldL.push({ data: content, nl });
      newL.push({ data: content, nl });
    } else if (marker === '-') {
      oldL.push({ data: content, nl });
    } else if (marker === '+') {
      newL.push({ data: content, nl });
    }
  }
  return { oldL, newL };
}

function main() {
  const dir = process.argv[2];
  const diffBuf = fs.readFileSync(path.join(dir, 'changes.diff'));
  const treeDir = path.join(dir, 'tree');
  const sections = parseDiff(diffBuf);

  const results: { file: string; out: string[] }[] = [];

  for (const sec of sections) {
    const out: string[] = [];
    const filePath = path.join(treeDir, sec.file);
    const exists = fs.existsSync(filePath);
    let error: string | null = null;
    if (sec.kind === 'create' && exists) error = 'already exists';
    if (sec.kind !== 'create' && !exists) error = 'not found';

    if (error) {
      out.push(`${sec.file}: ${sec.kind}`);
      out.push(`  error: ${error}`);
      results.push({ file: sec.file, out });
      continue;
    }

    let lines: Line[] = sec.kind === 'create' ? [] : splitLines(fs.readFileSync(filePath));
    let delta = 0;
    let allApplied = true;

    sec.hunks.forEach((h, idx) => {
      const n = idx + 1;
      if (!h.m) {
        out.push(`  hunk ${n}: malformed`);
        allApplied = false;
        return;
      }
      const a = parseInt(h.m[1], 10);
      const b = h.m[2] !== undefined ? parseInt(h.m[2], 10) : 1;
      const d = h.m[4] !== undefined ? parseInt(h.m[4], 10) : 1;
      const { oldL, newL } = buildSides(h.body);
      if (oldL.length !== b || newL.length !== d) {
        out.push(`  hunk ${n}: malformed`);
        allApplied = false;
        return;
      }
      const P = a + delta;
      if (b === 0) {
        if (P >= 0 && P <= lines.length) {
          lines.splice(P, 0, ...newL);
          out.push(`  hunk ${n}: applied at ${P} (offset 0)`);
          delta += d - b;
        } else {
          out.push(`  hunk ${n}: rejected`);
          allApplied = false;
        }
        return;
      }
      let found = -1;
      for (let k = 0; ; k++) {
        const lo = P - k;
        const hi = P + k;
        const loValid = lo >= 1;
        const hiValid = hi + b - 1 <= lines.length;
        if (!loValid && !hiValid) break;
        let done = false;
        for (const p of k === 0 ? [lo] : [lo, hi]) {
          if (p >= 1 && p + b - 1 <= lines.length) {
            let match = true;
            for (let j = 0; j < b; j++) {
              if (!eq(lines[p - 1 + j], oldL[j])) {
                match = false;
                break;
              }
            }
            if (match) {
              found = p;
              done = true;
              break;
            }
          }
        }
        if (done) break;
      }
      if (found > 0) {
        lines.splice(found - 1, b, ...newL);
        const off = found - P;
        const offStr = off > 0 ? `+${off}` : `${off}`;
        out.push(`  hunk ${n}: applied at ${found} (offset ${offStr})`);
        delta += d - b;
      } else {
        out.push(`  hunk ${n}: rejected`);
        allApplied = false;
      }
    });

    out.push(`${sec.file}: ${sec.kind}`);
    // re-insert header at front (we pushed hunk lines first)
    const hunkLines = out.slice(1);
    out.length = 1;

    const deleted = sec.kind === 'delete' && allApplied && lines.length === 0;
    if (deleted) {
      out.push('  result: deleted');
    } else {
      const content = joinLines(lines);
      out.push(`  result: ${lines.length} lines, crc32 ${crc32(content)}`);
    }
    out.push(...hunkLines);
    results.push({ file: sec.file, out });
  }

  results.sort((x, y) => Buffer.compare(Buffer.from(x.file, 'utf8'), Buffer.from(y.file, 'utf8')));
  let text = '';
  for (const r of results) text += r.out.join('\n') + '\n';
  process.stdout.write(text);
}

main();

import * as fs from 'fs';
import * as path from 'path';

type Line = { data: Buffer; nl: boolean };

function splitLines(buf: Buffer): Line[] {
  const lines: Line[] = [];
  let start = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 0x0a) {
      lines.push({ data: buf.subarray(start, i), nl: true });
      start = i + 1;
    }
  }
  if (start < buf.length) lines.push({ data: buf.subarray(start), nl: false });
  return lines;
}

function joinLines(lines: Line[]): Buffer {
  const parts: Buffer[] = [];
  for (const l of lines) {
    parts.push(l.data);
    if (l.nl) parts.push(Buffer.from([0x0a]));
  }
  return Buffer.concat(parts);
}

function eq(a: Line, b: Line): boolean {
  return a.nl === b.nl && a.data.equals(b.data);
}

const crcTable = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf: Buffer): string {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = crcTable[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return ((c ^ 0xffffffff) >>> 0).toString(16).padStart(8, '0');
}

function startsWith(b: Buffer, s: string): boolean {
  const p = Buffer.from(s, 'latin1');
  if (b.length < p.length) return false;
  return b.subarray(0, p.length).equals(p);
}

interface Hunk {
  m: RegExpExecArray | null;
  body: Buffer[];
}
interface Section {
  file: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
}

function parseDiff(buf: Buffer): Section[] {
  const raw = splitLines(buf).map((l) => l.data);
  const sections: Section[] = [];
  let i = 0;
  while (i < raw.length) {
    if (!startsWith(raw[i], 'diff --git a/')) {
      i++;
      continue;
    }
    const s = raw[i].toString('latin1');
    const rest = s.slice('diff --git a/'.length);
    const idx = rest.indexOf(' b/');
    const file = idx >= 0 ? rest.slice(0, idx) : rest;
    i++;
    let kind: 'create' | 'delete' | 'modify' = 'modify';
    while (i < raw.length) {
      if (startsWith(raw[i], 'new file mode ')) {
        kind = 'create';
        i++;
      } else if (startsWith(raw[i], 'deleted file mode ')) {
        kind = 'delete';
        i++;
      } else if (startsWith(raw[i], 'index ')) {
        i++;
      } else break;
    }
    const hunks: Hunk[] = [];
    while (i < raw.length && !startsWith(raw[i], 'diff --git ')) {
      if (startsWith(raw[i], '@@ ')) {
        const header = raw[i].toString('latin1');
        const m = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(header);
        i++;
        const body: Buffer[] = [];
        while (
          i < raw.length &&
          !startsWith(raw[i], '@@ ') &&
          !startsWith(raw[i], 'diff --git ')
        ) {
          body.push(raw[i]);
          i++;
        }
        hunks.push({ m, body });
      } else {
        i++;
      }
    }
    sections.push({ file, kind, hunks });
  }
  return sections;
}

function buildSides(body: Buffer[]): { oldL: Line[]; newL: Line[] } {
  const oldL: Line[] = [];
  const newL: Line[] = [];
  for (let j = 0; j < body.length; j++) {
    const marker = String.fromCharCode(body[j][0]);
    if (marker === '\\') continue;
    const content = body[j].subarray(1);
    let nl = true;
    if (j + 1 < body.length && body[j + 1][0] === 0x5c) nl = false;
    if (marker === ' ') {
      oldL.push({ data: content, nl });
      newL.push({ data: content, nl });
    } else if (marker === '-') {
      oldL.push({ data: content, nl });
    } else if (marker === '+') {
      newL.push({ data: content, nl });
    }
  }
  return { oldL, newL };
}

function main() {
  const dir = process.argv[2];
  const diffBuf = fs.readFileSync(path.join(dir, 'changes.diff'));
  const treeDir = path.join(dir, 'tree');
  const sections = parseDiff(diffBuf);

  const results: { file: string; out: string[] }[] = [];

  for (const sec of sections) {
    const header = `${sec.file}: ${sec.kind}`;
    const hunkLines: string[] = [];
    const filePath = path.join(treeDir, sec.file);
    const exists = fs.existsSync(filePath);
    let error: string | null = null;
    if (sec.kind === 'create' && exists) error = 'already exists';
    if (sec.kind !== 'create' && !exists) error = 'not found';

    if (error) {
      results.push({ file: sec.file, out: [header, `  error: ${error}`] });
      continue;
    }

    let lines: Line[] = sec.kind === 'create' ? [] : splitLines(fs.readFileSync(filePath));
    let delta = 0;
    let allApplied = true;

    sec.hunks.forEach((h, idx) => {
      const n = idx + 1;
      if (!h.m) {
        hunkLines.push(`  hunk ${n}: malformed`);
        allApplied = false;
        return;
      }
      const a = parseInt(h.m[1], 10);
      const b = h.m[2] !== undefined ? parseInt(h.m[2], 10) : 1;
      const d = h.m[4] !== undefined ? parseInt(h.m[4], 10) : 1;
      const { oldL, newL } = buildSides(h.body);
      if (oldL.length !== b || newL.length !== d) {
        hunkLines.push(`  hunk ${n}: malformed`);
        allApplied = false;
        return;
      }
      const P = a + delta;
      if (b === 0) {
        if (P >= 0 && P <= lines.length) {
          lines.splice(P, 0, ...newL);
          hunkLines.push(`  hunk ${n}: applied at ${P} (offset 0)`);
          delta += d - b;
        } else {
          hunkLines.push(`  hunk ${n}: rejected`);
          allApplied = false;
        }
        return;
      }
      let found = -1;
      for (let k = 0; ; k++) {
        const lo = P - k;
        const hi = P + k;
        const loValid = lo >= 1;
        const hiValid = hi + b - 1 <= lines.length;
        if (!loValid && !hiValid) break;
        let done = false;
        for (const p of k === 0 ? [lo] : [lo, hi]) {
          if (p >= 1 && p + b - 1 <= lines.length) {
            let match = true;
            for (let j = 0; j < b; j++) {
              if (!eq(lines[p - 1 + j], oldL[j])) {
                match = false;
                break;
              }
            }
            if (match) {
              found = p;
              done = true;
              break;
            }
          }
        }
        if (done) break;
      }
      if (found > 0) {
        lines.splice(found - 1, b, ...newL);
        const off = found - P;
        const offStr = off > 0 ? `+${off}` : `${off}`;
        hunkLines.push(`  hunk ${n}: applied at ${found} (offset ${offStr})`);
        delta += d - b;
      } else {
        hunkLines.push(`  hunk ${n}: rejected`);
        allApplied = false;
      }
    });

    const deleted = sec.kind === 'delete' && allApplied && lines.length === 0;
    let resultLine: string;
    if (deleted) {
      resultLine = '  result: deleted';
    } else {
      const content = joinLines(lines);
      resultLine = `  result: ${lines.length} lines, crc32 ${crc32(content)}`;
    }
    results.push({ file: sec.file, out: [header, ...hunkLines, resultLine] });
  }

  results.sort((x, y) => Buffer.compare(Buffer.from(x.file, 'utf8'), Buffer.from(y.file, 'utf8')));
  let text = '';
  for (const r of results) text += r.out.join('\n') + '\n';
  process.stdout.write(text);
}

main();

import sys, os
sys.setrecursionlimit(200000)

INT_MIN = -(2**63); INT_MAX = 2**63 - 1
KEYWORDS = {'let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil'}

class TernError(Exception):
    def __init__(self, line, msg): self.line = line; self.msg = msg
class BadArg(Exception): pass
class BreakEx(Exception): pass
class ContEx(Exception): pass
class RetEx(Exception):
    def __init__(self, v): self.v = v
class Nil:
    __slots__ = ()
NIL = Nil()

def tokenize(src):
    toks = []; i = 0; line = 1; n = len(src)
    while i < n:
        c = src[i]
        if c == '\n': line += 1; i += 1; continue
        if c in ' \t\r': i += 1; continue
        if c == '#':
            while i < n and src[i] != '\n': i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and src[j].isdigit(): j += 1
            toks.append(('int', int(src[i:j]), line)); i = j; continue
        if c == '"':
            j = i + 1; buf = []
            while src[j] != '"':
                if src[j] == '\\':
                    e = src[j+1]
                    buf.append({'n':'\n','t':'\t','"':'"','\\':'\\'}[e]); j += 2
                else:
                    buf.append(src[j]); j += 1
            toks.append(('str', ''.join(buf), line)); i = j + 1; continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'): j += 1
            w = src[i:j]
            toks.append(('kw' if w in KEYWORDS else 'ident', w, line)); i = j; continue
        two = src[i:i+2]
        if two in ('==','!=','<=','>='):
            toks.append(('punc', two, line)); i += 2; continue
        toks.append(('punc', c, line)); i += 1
    toks.append(('eof', None, line))
    return toks

class P:
    def __init__(self, toks): self.t = toks; self.i = 0
    def peek(self, k=0): return self.t[self.i+k]
    def next(self): tok = self.t[self.i]; self.i += 1; return tok
    def expect(self, val):
        tok = self.next()
        if tok[1] != val: raise Exception('parse error')
    def program(self):
        stmts = []
        while self.peek()[0] != 'eof': stmts.append(self.stmt())
        return stmts
    def block(self):
        self.expect('{'); stmts = []
        while self.peek()[1] != '}': stmts.append(self.stmt())
        self.expect('}'); return stmts
    def params(self):
        self.expect('('); ps = []
        if self.peek()[1] != ')':
            ps.append(self.next()[1])
            while self.peek()[1] == ',': self.next(); ps.append(self.next()[1])
        self.expect(')'); return ps
    def stmt(self):
        k, v, l = self.peek()
        if v == 'let':
            self.next(); name = self.next()[1]; self.expect('=')
            e = self.expr(); self.expect(';'); return ('let', name, e)
        if v == 'fn' and self.peek(1)[0] == 'ident':
            self.next(); name = self.next()[1]; params = self.params(); body = self.block()
            return ('fnstmt', name, params, body)
        if v == 'if': return self.ifstmt()
        if v == 'while':
            self.next(); c = self.expr(); b = self.block(); return ('while', c, b)
        if v == 'for':
            self.next(); name = self.next()[1]; self.expect('in')
            e = self.expr(); b = self.block(); return ('for', name, e, b, l)
        if v == 'return':
            self.next()
            if self.peek()[1] == ';': self.next(); return ('return', None)
            e = self.expr(); self.expect(';'); return ('return', e)
        if v == 'break': self.next(); self.expect(';'); return ('break',)
        if v == 'continue': self.next(); self.expect(';'); return ('continue',)
        if k == 'ident' and self.peek(1)[1] == '=':
            name = self.next()[1]; self.next(); e = self.expr(); self.expect(';')
            return ('assign', name, e, l)
        e = self.expr()
        if self.peek()[1] == '=':
            self.next(); val = self.expr(); self.expect(';')
            return ('idxassign', e[1], e[2], val, e[3])
        self.expect(';'); return ('expr', e)
    def ifstmt(self):
        self.next(); c = self.expr(); b = self.block()
        els = None
        if self.peek()[1] == 'else':
            self.next()
            if self.peek()[1] == 'if': els = self.ifstmt()
            else: els = ('block', self.block())
        return ('if', c, b, els)
    def expr(self): return self.or_()
    def or_(self):
        e = self.and_()
        while self.peek()[1] == 'or': self.next(); e = ('or', e, self.and_())
        return e
    def and_(self):
        e = self.not_()
        while self.peek()[1] == 'and': self.next(); e = ('and', e, self.not_())
        return e
    def not_(self):
        if self.peek()[1] == 'not': self.next(); return ('not', self.not_())
        return self.cmp_()
    def cmp_(self):
        e = self.add_()
        while self.peek()[1] in ('==','!=','<','<=','>','>='):
            op = self.next(); e = ('binop', op[1], e, self.add_(), op[2])
        return e
    def add_(self):
        e = self.mul_()
        while self.peek()[1] in ('+','-'):
            op = self.next(); e = ('binop', op[1], e, self.mul_(), op[2])
        return e
    def mul_(self):
        e = self.unary_()
        while self.peek()[1] in ('*','/','%'):
            op = self.next(); e = ('binop', op[1], e, self.unary_(), op[2])
        return e
    def unary_(self):
        if self.peek()[1] == '-':
            op = self.next(); return ('neg', self.unary_(), op[2])
        return self.postfix_()
    def postfix_(self):
        e = self.primary_()
        while True:
            v = self.peek()[1]
            if v == '(':
                ln = self.next()[2]; args = []
                if self.peek()[1] != ')':
                    args.append(self.expr())
                    while self.peek()[1] == ',': self.next(); args.append(self.expr())
                self.expect(')'); e = ('call', e, args, ln)
            elif v == '[':
                ln = self.next()[2]; idx = self.expr(); self.expect(']')
                e = ('index', e, idx, ln)
            else: return e
    def primary_(self):
        k, v, l = self.next()
        if k == 'int': return ('int', v)
        if k == 'str': return ('str', v)
        if k == 'ident': return ('var', v, l)
        if v == 'true': return ('bool', True)
        if v == 'false': return ('bool', False)
        if v == 'nil': return ('nil',)
        if v == 'fn':
            params = self.params(); body = self.block(); return ('fn', params, body)
        if v == '(':
            e = self.expr(); self.expect(')'); return e
        if v == '[':
            elems = []
            if self.peek()[1] != ']':
                elems.append(self.expr())
                while self.peek()[1] == ',': self.next(); elems.append(self.expr())
            self.expect(']'); return ('list', elems)
        raise Exception('parse error')

class Env:
    __slots__ = ('v','p')
    def __init__(self, p): self.v = {}; self.p = p
    def get(self, name, line):
        e = self
        while e is not None:
            if name in e.v: return e.v[name]
            e = e.p
        raise TernError(line, "undefined variable " + name)
    def set(self, name, val, line):
        e = self
        while e is not None:
            if name in e.v: e.v[name] = val; return
            e = e.p
        raise TernError(line, "undefined variable " + name)

class Closure:
    __slots__ = ('params','body','env')
    def __init__(self, params, body, env): self.params = params; self.body = body; self.env = env
class Builtin:
    __slots__ = ('name','arity','fn')
    def __init__(self, name, arity, fn): self.name = name; self.arity = arity; self.fn = fn

def tname(v):
    if v is NIL: return 'nil'
    t = type(v)
    if t is bool: return 'bool'
    if t is int: return 'int'
    if t is str: return 'string'
    if t is list: return 'list'
    return 'function'

def truthy(v):
    if v is NIL or v is False: return False
    t = type(v)
    if t is int: return v != 0
    if t is str: return v != ''
    if t is list: return len(v) > 0
    return True

def chk(v, line):
    if v < INT_MIN or v > INT_MAX: raise TernError(line, "integer overflow")
    return v

def tern_eq(a, b):
    ta, tb = tname(a), tname(b)
    if ta != tb: return False
    if ta == 'nil': return True
    if ta in ('int','bool','string'): return a == b
    if ta == 'list':
        if len(a) != len(b): return False
        for x, y in zip(a, b):
            if not tern_eq(x, y): return False
        return True
    return a is b

def apply(op, a, b, line):
    if op == '+':
        ta, tb = tname(a), tname(b)
        if ta == 'int' and tb == 'int': return chk(a + b, line)
        if ta == 'string' and tb == 'string': return a + b
        if ta == 'list' and tb == 'list': return a + b
        raise TernError(line, "cannot apply + to %s and %s" % (ta, tb))
    if op in ('-','*','/','%'):
        ta, tb = tname(a), tname(b)
        if ta != 'int' or tb != 'int':
            raise TernError(line, "cannot apply %s to %s and %s" % (op, ta, tb))
        if op == '-': return chk(a - b, line)
        if op == '*': return chk(a * b, line)
        if b == 0: raise TernError(line, "division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0): q = -q
        if op == '/': return chk(q, line)
        if b == -1: return 0
        return a - q * b
    if op == '==': return tern_eq(a, b)
    if op == '!=': return not tern_eq(a, b)
    ta, tb = tname(a), tname(b)
    if not ((ta == 'int' and tb == 'int') or (ta == 'string' and tb == 'string')):
        raise TernError(line, "cannot apply %s to %s and %s" % (op, ta, tb))
    if op == '<': return a < b
    if op == '<=': return a <= b
    if op == '>': return a > b
    return a >= b

def quote(s):
    return '"' + s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t') + '"'

def display(v, active=None):
    if active is None: active = set()
    t = type(v)
    if t is bool: return 'true' if v else 'false'
    if t is int: return str(v)
    if v is NIL: return 'nil'
    if t is str: return v
    if t is list:
        if id(v) in active: return '[...]'
        active.add(id(v))
        try:
            parts = []
            for e in v:
                parts.append(quote(e) if type(e) is str else display(e, active))
            return '[' + ', '.join(parts) + ']'
        finally:
            active.discard(id(v))
    return '<fn>'

def ev(e, env):
    t = e[0]
    if t == 'int' or t == 'str' or t == 'bool': return e[1]
    if t == 'nil': return NIL
    if t == 'var': return env.get(e[1], e[2])
    if t == 'binop':
        l = ev(e[2], env); r = ev(e[3], env)
        return apply(e[1], l, r, e[4])
    if t == 'call':
        f = ev(e[1], env); args = [ev(a, env) for a in e[2]]; line = e[3]
        return call(f, args, line)
    if t == 'index':
        x = ev(e[1], env); i = ev(e[2], env)
        tx = tname(x); ti = tname(i)
        if (tx != 'list' and tx != 'string') or ti != 'int':
            raise TernError(e[3], "cannot index %s with %s" % (tx, ti))
        if i < 0 or i >= len(x):
            raise TernError(e[3], "index %d out of range for length %d" % (i, len(x)))
        return x[i]
    if t == 'list': return [ev(x, env) for x in e[1]]
    if t == 'fn': return Closure(e[1], e[2], env)
    if t == 'and':
        l = ev(e[1], env)
        return l if not truthy(l) else ev(e[2], env)
    if t == 'or':
        l = ev(e[1], env)
        return l if truthy(l) else ev(e[2], env)
    if t == 'not': return not truthy(ev(e[1], env))
    if t == 'neg':
        v = ev(e[1], env)
        if tname(v) != 'int': raise TernError(e[2], "cannot apply - to " + tname(v))
        if v == INT_MIN: raise TernError(e[2], "integer overflow")
        return -v
    raise Exception('bad node')

def call(f, args, line):
    tf = tname(f)
    if tf != 'function': raise TernError(line, "cannot call " + tf)
    if isinstance(f, Builtin):
        if f.arity is not None and len(args) != f.arity:
            raise TernError(line, "expected %d arguments, got %d" % (f.arity, len(args)))
        try:
            return f.fn(args)
        except BadArg:
            raise TernError(line, "bad argument to " + f.name)
    if len(args) != len(f.params):
        raise TernError(line, "expected %d arguments, got %d" % (len(f.params), len(args)))
    env = Env(f.env)
    for p, a in zip(f.params, args): env.v[p] = a
    try:
        ex_stmts(f.body, env)
    except RetEx as r:
        return r.v
    return NIL

def ex_stmts(stmts, env):
    for s in stmts: ex(s, env)

def ex(s, env):
    t = s[0]
    if t == 'expr': ev(s[1], env); return
    if t == 'let': env.v[s[1]] = ev(s[2], env); return
    if t == 'fnstmt': env.v[s[1]] = Closure(s[2], s[3], env); return
    if t == 'assign': env.set(s[1], ev(s[2], env), s[3]); return
    if t == 'if':
        if truthy(ev(s[1], env)):
            ex_stmts(s[2], Env(env))
        elif s[3] is not None:
            els = s[3]
            if els[0] == 'block': ex_stmts(els[1], Env(env))
            else: ex(els, env)
        return
    if t == 'while':
        while truthy(ev(s[1], env)):
            try: ex_stmts(s[2], Env(env))
            except BreakEx: break
            except ContEx: pass
        return
    if t == 'for':
        lst = ev(s[2], env)
        if tname(lst) != 'list': raise TernError(s[4], "cannot iterate " + tname(lst))
        i = 0
        while i < len(lst):
            e2 = Env(env); e2.v[s[1]] = lst[i]
            try: ex_stmts(s[3], e2)
            except BreakEx: break
            except ContEx: pass
            i += 1
        return
    if t == 'idxassign':
        x = ev(s[1], env); i = ev(s[2], env); v = ev(s[3], env); line = s[4]
        if tname(x) != 'list': raise TernError(line, "cannot assign into " + tname(x))
        if tname(i) != 'int': raise TernError(line, "cannot index list with " + tname(i))
        if i < 0 or i >= len(x):
            raise TernError(line, "index %d out of range for length %d" % (i, len(x)))
        x[i] = v; return
    if t == 'return': raise RetEx(NIL if s[1] is None else ev(s[1], env))
    if t == 'break': raise BreakEx()
    if t == 'continue': raise ContEx()

def bi_print(args):
    sys.stdout.write(" ".join(display(a) for a in args) + "\n"); return NIL
def bi_str(args): return display(args[0])
def bi_type(args): return tname(args[0])
def bi_len(args):
    x = args[0]
    if type(x) is str or type(x) is list: return len(x)
    raise BadArg()
def bi_push(args):
    if type(args[0]) is not list: raise BadArg()
    args[0].append(args[1]); return NIL
def bi_pop(args):
    if type(args[0]) is not list or not args[0]: raise BadArg()
    return args[0].pop()
def bi_range(args):
    a, b = args
    if type(a) is not int or type(b) is not int: raise BadArg()
    return list(range(a, b))
def bi_slice(args):
    x, a, b = args
    if type(x) is not str and type(x) is not list: raise BadArg()
    if type(a) is not int or type(b) is not int: raise BadArg()
    if not (0 <= a <= b <= len(x)): raise BadArg()
    return x[a:b]

BUILTINS = Env(None)
for name, ar, fn in [('print',None,bi_print),('str',1,bi_str),('type',1,bi_type),
                     ('len',1,bi_len),('push',2,bi_push),('pop',1,bi_pop),
                     ('range',2,bi_range),('slice',3,bi_slice)]:
    BUILTINS.v[name] = Builtin(name, ar, fn)

def main():
    with open(os.path.join(sys.argv[1], 'program.tern')) as f:
        src = f.read()
    try:
        prog = P(tokenize(src)).program()
        ex_stmts(prog, Env(BUILTINS))
    except TernError as e:
        sys.stdout.write("error at line %d: %s\n" % (e.line, e.msg))
    return 0

if __name__ == '__main__':
    sys.exit(main())

import Foundation

let args = CommandLine.arguments
let dir = args.count > 1 ? args[1] : "."

func readBytes(_ path: String) -> [UInt8]? {
    let fm = FileManager.default
    guard fm.fileExists(atPath: path) else { return nil }
    guard let d = fm.contents(atPath: path) else { return nil }
    return [UInt8](d)
}

func splitNoNL(_ data: [UInt8]) -> [[UInt8]] {
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    for b in data {
        if b == 10 { lines.append(cur); cur = [] } else { cur.append(b) }
    }
    if !cur.isEmpty { lines.append(cur) }
    return lines
}

func splitWithNL(_ data: [UInt8]) -> [[UInt8]] {
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    for b in data {
        cur.append(b)
        if b == 10 { lines.append(cur); cur = [] }
    }
    if !cur.isEmpty { lines.append(cur) }
    return lines
}

func hasPrefix(_ line: [UInt8], _ s: String) -> Bool {
    let p = Array(s.utf8)
    if line.count < p.count { return false }
    for j in 0..<p.count where line[j] != p[j] { return false }
    return true
}

var crcTable: [UInt32] = {
    var t = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            c = (c & 1) != 0 ? (0xEDB88320 ^ (c >> 1)) : (c >> 1)
        }
        t[i] = c
    }
    return t
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data { c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8) }
    return c ^ 0xFFFFFFFF
}

struct Hunk {
    var a = 0, b = 0, c = 0, d = 0
    var body: [[UInt8]] = []
    var oldLines: [[UInt8]] = []
    var newLines: [[UInt8]] = []
    var malformed = false
}

func parseHeader(_ line: [UInt8]) -> (Int, Int, Int, Int)? {
    let pfx = Array("@@ -".utf8)
    guard line.count >= pfx.count else { return nil }
    for j in 0..<pfx.count where line[j] != pfx[j] { return nil }
    var i = pfx.count
    func num() -> Int? {
        guard i < line.count, line[i] >= 48, line[i] <= 57 else { return nil }
        var v = 0
        while i < line.count, line[i] >= 48, line[i] <= 57 {
            v = v * 10 + Int(line[i] - 48); i += 1
        }
        return v
    }
    guard let a = num() else { return nil }
    var b = 1
    if i < line.count && line[i] == UInt8(ascii: ",") {
        i += 1
        guard let x = num() else { return nil }
        b = x
    }
    guard i + 1 < line.count, line[i] == UInt8(ascii: " "), line[i + 1] == UInt8(ascii: "+") else { return nil }
    i += 2
    guard let c = num() else { return nil }
    var d = 1
    if i < line.count && line[i] == UInt8(ascii: ",") {
        i += 1
        guard let x = num() else { return nil }
        d = x
    }
    guard i + 2 < line.count,
          line[i] == UInt8(ascii: " "), line[i + 1] == UInt8(ascii: "@"), line[i + 2] == UInt8(ascii: "@") else { return nil }
    return (a, b, c, d)
}

func finalize(_ h: inout Hunk) {
    let bs = h.body
    var i = 0
    while i < bs.count {
        let l = bs[i]
        guard !l.isEmpty else { i += 1; continue }
        let marker = l[0]
        if marker == UInt8(ascii: "\\") { i += 1; continue }
        let sp = UInt8(ascii: " "), mi = UInt8(ascii: "-"), pl = UInt8(ascii: "+")
        if marker != sp && marker != mi && marker != pl { i += 1; continue }
        var content = Array(l[1...])
        if i + 1 < bs.count, !bs[i + 1].isEmpty, bs[i + 1][0] == UInt8(ascii: "\\") {
            // no trailing newline
        } else {
            content.append(10)
        }
        if marker == sp {
            h.oldLines.append(content); h.newLines.append(content)
        } else if marker == mi {
            h.oldLines.append(content)
        } else {
            h.newLines.append(content)
        }
        i += 1
    }
    if h.oldLines.count != h.b || h.newLines.count != h.d { h.malformed = true }
}

enum Kind { case create, delete, modify }

struct Section {
    var path: [UInt8]
    var kind: Kind = .modify
    var hunks: [Hunk] = []
}

var sections: [Section] = []
let diffBytes = readBytes(dir + "/changes.diff") ?? []
let diffLines = splitNoNL(diffBytes)
var i = 0
while i < diffLines.count {
    let line = diffLines[i]
    if hasPrefix(line, "diff --git a/") {
        let rest = Array(line[13...])
        let path: [UInt8]
        if let s = rest.firstIndex(of: 32) {
            path = Array(rest[0..<s])
        } else {
            path = rest
        }
        var sec = Section(path: path)
        i += 1
        var cur: Hunk? = nil
        while i < diffLines.count && !hasPrefix(diffLines[i], "diff --git ") {
            let l = diffLines[i]
            if hasPrefix(l, "@@ ") {
                if var h = cur { finalize(&h); sec.hunks.append(h) }
                var h = Hunk()
                if let (a, b, c, d) = parseHeader(l) {
                    h.a = a; h.b = b; h.c = c; h.d = d
                } else {
                    h.malformed = true
                }
                cur = h
            } else if cur != nil {
                cur!.body.append(l)
            } else {
                if hasPrefix(l, "new file mode ") { sec.kind = .create }
                else if hasPrefix(l, "deleted file mode ") { sec.kind = .delete }
            }
            i += 1
        }
        if var h = cur { finalize(&h); sec.hunks.append(h) }
        sections.append(sec)
    } else {
        i += 1
    }
}

func lex(_ a: [UInt8], _ b: [UInt8]) -> Bool {
    for j in 0..<min(a.count, b.count) {
        if a[j] != b[j] { return a[j] < b[j] }
    }
    return a.count < b.count
}

sections.sort { lex($0.path, $1.path) }

func pathStr(_ p: [UInt8]) -> String { String(bytes: p, encoding: .utf8) ?? "" }

var out: [String] = []
let fm = FileManager.default

for sec in sections {
    let ps = pathStr(sec.path)
    let kindStr: String
    switch sec.kind {
    case .create: kindStr = "create"
    case .delete: kindStr = "delete"
    case .modify: kindStr = "modify"
    }
    out.append("\(ps): \(kindStr)")
    let fp = dir + "/tree/" + ps
    var content: [[UInt8]] = []
    var ok = true
    var errMsg = ""
    if sec.kind == .create {
        if fm.fileExists(atPath: fp) { ok = false; errMsg = "already exists" }
    } else {
        if let data = readBytes(fp) {
            content = splitWithNL(data)
        } else {
            ok = false; errMsg = "not found"
        }
    }
    if !ok {
        out.append("  error: \(errMsg)")
        continue
    }
    var delta = 0
    var allApplied = true
    for (idx, h) in sec.hunks.enumerated() {
        let n = idx + 1
        if h.malformed {
            out.append("  hunk \(n): malformed")
            allApplied = false
            continue
        }
        let P = h.a + delta
        if h.b == 0 {
            if P >= 0 && P <= content.count {
                content.insert(contentsOf: h.newLines, at: P)
                out.append("  hunk \(n): applied at \(P) (offset 0)")
                delta += h.d - h.b
            } else {
                out.append("  hunk \(n): rejected")
                allApplied = false
            }
        } else {
            let limit = content.count - h.b + 1
            var found: Int? = nil
            if limit >= 1 {
                var k = 0
                while true {
                    if P - k < 1 && P + k > limit { break }
                    let cands: [Int] = k == 0 ? [P] : [P - k, P + k]
                    for p in cands {
                        if p < 1 || p > limit { continue }
                        var match = true
                        for j in 0..<h.b {
                            if content[p - 1 + j] != h.oldLines[j] { match = false; break }
                        }
                        if match { found = p; break }
                    }
                    if found != nil { break }
                    k += 1
                }
            }
            if let p = found {
                content.replaceSubrange((p - 1)..<(p - 1 + h.b), with: h.newLines)
                let off = p - P
                let offStr = off > 0 ? "+\(off)" : (off < 0 ? "-\(-off)" : "0")
                out.append("  hunk \(n): applied at \(p) (offset \(offStr))")
                delta += h.d - h.b
            } else {
                out.append("  hunk \(n): rejected")
                allApplied = false
            }
        }
    }
    if sec.kind == .delete && allApplied && content.isEmpty {
        out.append("  result: deleted")
    } else {
        let bytes = content.flatMap { $0 }
        let crc = crc32(bytes)
        out.append("  result: \(content.count) lines, crc32 \(String(format: "%08x", crc))")
    }
}

if !out.isEmpty {
    print(out.joined(separator: "\n"))
}
exit(0)

use std::fs;
use std::io::Write;

#[derive(Clone, PartialEq)]
struct Line {
    bytes: Vec<u8>,
    nl: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Create,
    Delete,
    Modify,
}

struct Hunk {
    a: usize,
    b: usize,
    d: usize,
    old: Vec<Line>,
    new: Vec<Line>,
    malformed: bool,
}

struct Section {
    path: Vec<u8>,
    kind: Kind,
    hunks: Vec<Hunk>,
}

fn split_lines_raw(data: &[u8]) -> Vec<(Vec<u8>, bool)> {
    let mut out = Vec::new();
    let mut start = 0usize;
    for i in 0..data.len() {
        if data[i] == b'\n' {
            out.push((data[start..i].to_vec(), true));
            start = i + 1;
        }
    }
    if start < data.len() {
        out.push((data[start..].to_vec(), false));
    }
    out
}

fn to_content(data: &[u8]) -> Vec<Line> {
    split_lines_raw(data)
        .into_iter()
        .map(|(b, nl)| Line { bytes: b, nl })
        .collect()
}

fn serialize(c: &[Line]) -> Vec<u8> {
    let mut v = Vec::new();
    for l in c {
        v.extend_from_slice(&l.bytes);
        if l.nl {
            v.push(b'\n');
        }
    }
    v
}

fn parse_num(s: &[u8], i: &mut usize) -> Option<usize> {
    let start = *i;
    while *i < s.len() && s[*i].is_ascii_digit() {
        *i += 1;
    }
    if start == *i {
        return None;
    }
    std::str::from_utf8(&s[start..*i]).ok()?.parse().ok()
}

fn parse_hunk_header(s: &[u8]) -> Option<(usize, usize, usize, usize)> {
    if !s.starts_with(b"@@ -") {
        return None;
    }
    let mut i = 4;
    let a = parse_num(s, &mut i)?;
    let b = if i < s.len() && s[i] == b',' {
        i += 1;
        parse_num(s, &mut i)?
    } else {
        1
    };
    if i >= s.len() || s[i] != b' ' {
        return None;
    }
    i += 1;
    if i >= s.len() || s[i] != b'+' {
        return None;
    }
    i += 1;
    let c = parse_num(s, &mut i)?;
    let d = if i < s.len() && s[i] == b',' {
        i += 1;
        parse_num(s, &mut i)?
    } else {
        1
    };
    if !s[i..].starts_with(b" @@") {
        return None;
    }
    Some((a, b, c, d))
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

fn find_sub(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > hay.len() {
        return None;
    }
    (0..=hay.len() - needle.len()).find(|&i| &hay[i..i + needle.len()] == needle)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = args[1].clone();

    let diff = fs::read(format!("{}/changes.diff", dir)).unwrap();
    let lines = split_lines_raw(&diff);

    let mut sections: Vec<Section> = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        let (l, _) = (&lines[i].0, lines[i].1);
        if !l.starts_with(b"diff --git ") {
            i += 1;
            continue;
        }
        let rest = &l[11..];
        let sep = find_sub(rest, b" b/").unwrap();
        let path = rest[2..sep].to_vec();
        i += 1;
        let mut kind = Kind::Modify;
        while i < lines.len() {
            let l2 = &lines[i].0;
            if l2.starts_with(b"new file mode ") {
                kind = Kind::Create;
                i += 1;
            } else if l2.starts_with(b"deleted file mode ") {
                kind = Kind::Delete;
                i += 1;
            } else if l2.starts_with(b"index ") {
                i += 1;
            } else {
                break;
            }
        }
        if i < lines.len() && lines[i].0.starts_with(b"--- ") {
            i += 1;
        }
        if i < lines.len() && lines[i].0.starts_with(b"+++ ") {
            i += 1;
        }
        let mut hunks: Vec<Hunk> = Vec::new();
        while i < lines.len() && lines[i].0.starts_with(b"@@ ") {
            let hdr = lines[i].0.clone();
            let (a, b, _c, d) = match parse_hunk_header(&hdr) {
                Some(x) => x,
                None => {
                    i += 1;
                    while i < lines.len()
                        && !lines[i].0.starts_with(b"@@ ")
                        && !lines[i].0.starts_with(b"diff --git ")
                    {
                        i += 1;
                    }
                    hunks.push(Hunk {
                        a: 0,
                        b: 0,
                        d: 0,
                        old: vec![],
                        new: vec![],
                        malformed: true,
                    });
                    continue;
                }
            };
            i += 1;
            let mut body: Vec<(u8, Vec<u8>, bool)> = Vec::new();
            while i < lines.len() {
                let bl = lines[i].0.clone();
                let bnl = lines[i].1;
                if bl.starts_with(b"@@ ") || bl.starts_with(b"diff --git ") {
                    break;
                }
                let marker = bl[0];
                body.push((marker, bl[1..].to_vec(), bnl));
                i += 1;
            }
            let mut old: Vec<Line> = Vec::new();
            let mut new: Vec<Line> = Vec::new();
            let mut prev_marker = 0u8;
            for &(m, ref c, nl) in &body {
                if m == b'\\' {
                    match prev_marker {
                        b' ' => {
                            if let Some(l) = old.last_mut() {
                                l.nl = false;
                            }
                            if let Some(l) = new.last_mut() {
                                l.nl = false;
                            }
                        }
                        b'-' => {
                            if let Some(l) = old.last_mut() {
                                l.nl = false;
                            }
                        }
                        b'+' => {
                            if let Some(l) = new.last_mut() {
                                l.nl = false;
                            }
                        }
                        _ => {}
                    }
                    continue;
                }
                let line = Line {
                    bytes: c.clone(),
                    nl,
                };
                match m {
                    b' ' => {
                        old.push(line.clone());
                        new.push(line);
                    }
                    b'-' => old.push(line),
                    b'+' => new.push(line),
                    _ => {}
                }
                prev_marker = m;
            }
            let malformed = old.len() != b || new.len() != d;
            hunks.push(Hunk {
                a,
                b,
                d,
                old,
                new,
                malformed,
            });
        }
        sections.push(Section { path, kind, hunks });
    }

    sections.sort_by(|x, y| x.path.cmp(&y.path));

    let mut out: Vec<u8> = Vec::new();
    for s in &sections {
        out.extend_from_slice(&s.path);
        out.extend_from_slice(b": ");
        out.extend_from_slice(match s.kind {
            Kind::Create => b"create",
            Kind::Delete => b"delete",
            Kind::Modify => b"modify",
        });
        out.push(b'\n');

        let fpath = format!(
            "{}/tree/{}",
            dir,
            String::from_utf8_lossy(&s.path)
        );
        let path = std::path::Path::new(&fpath);
        let exists = path.exists();

        let error: Option<&str> = match s.kind {
            Kind::Create if exists => Some("already exists"),
            Kind::Create => None,
            _ if !exists => Some("not found"),
            _ => None,
        };
        if let Some(e) = error {
            out.extend_from_slice(format!("  error: {}\n", e).as_bytes());
            continue;
        }

        let mut content: Vec<Line> = match s.kind {
            Kind::Create => Vec::new(),
            _ => to_content(&fs::read(path).unwrap()),
        };

        let mut delta: i64 = 0;
        let mut all_applied = true;

        for (n, h) in s.hunks.iter().enumerate() {
            let num = n + 1;
            if h.malformed {
                out.extend_from_slice(format!("  hunk {}: malformed\n", num).as_bytes());
                all_applied = false;
                continue;
            }
            if h.b == 0 {
                let p = h.a as i64 + delta;
                if p >= 0 && p <= content.len() as i64 {
                    let at = p as usize;
                    for (j, l) in h.new.iter().enumerate() {
                        content.insert(at + j, l.clone());
                    }
                    delta += h.d as i64;
                    out.extend_from_slice(
                        format!("  hunk {}: applied at {} (offset 0)\n", num, p).as_bytes(),
                    );
                } else {
                    out.extend_from_slice(format!("  hunk {}: rejected\n", num).as_bytes());
                    all_applied = false;
                }
            } else {
                let p0 = h.a as i64 + delta;
                let limit = content.len() as i64 - h.b as i64 + 1;
                let mut found: Option<(usize, i64)> = None;
                let mut k: i64 = 0;
                loop {
                    let lo = p0 - k;
                    let hi = p0 + k;
                    if lo < 1 && hi > limit {
                        break;
                    }
                    let mut cands: Vec<i64> = Vec::new();
                    if k == 0 {
                        if lo >= 1 && lo <= limit {
                            cands.push(lo);
                        }
                    } else {
                        if lo >= 1 && lo <= limit {
                            cands.push(lo);
                        }
                        if hi >= 1 && hi <= limit && hi != lo {
                            cands.push(hi);
                        }
                    }
                    let mut hit = None;
                    for p in cands {
                        let p = p as usize;
                        if content[p - 1..p - 1 + h.b] == h.old[..] {
                            hit = Some(p);
                            break;
                        }
                    }
                    if let Some(p) = hit {
                        found = Some((p, p as i64 - p0));
                        break;
                    }
                    k += 1;
                }
                if let Some((p, off)) = found {
                    for _ in 0..h.b {
                        content.remove(p - 1);
                    }
                    for (j, l) in h.new.iter().enumerate() {
                        content.insert(p - 1 + j, l.clone());
                    }
                    delta += h.d as i64 - h.b as i64;
                    let off_s = if off == 0 {
                        "0".to_string()
                    } else {
                        format!("{:+}", off)
                    };
                    out.extend_from_slice(
                        format!("  hunk {}: applied at {} (offset {})\n", num, p, off_s)
                            .as_bytes(),
                    );
                } else {
                    out.extend_from_slice(format!("  hunk {}: rejected\n", num).as_bytes());
                    all_applied = false;
                }
            }
        }

        if s.kind == Kind::Delete && all_applied && content.is_empty() {
            out.extend_from_slice(b"  result: deleted\n");
        } else {
            let bytes = serialize(&content);
            let c = crc32(&bytes);
            out.extend_from_slice(
                format!(
                    "  result: {} lines, crc32 {:08x}\n",
                    content.len(),
                    c
                )
                .as_bytes(),
            );
        }
    }

    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(&out).unwrap();
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static uint32_t crc_table[256];
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){
        uint32_t c=i;
        for(int k=0;k<8;k++) c=(c&1)?(0xEDB88320u^(c>>1)):(c>>1);
        crc_table[i]=c;
    }
}
static uint32_t crc32_of(const unsigned char*buf,size_t len){
    uint32_t c=0xFFFFFFFFu;
    for(size_t i=0;i<len;i++) c=crc_table[(c^buf[i])&0xFFu]^(c>>8);
    return c^0xFFFFFFFFu;
}

typedef struct { unsigned char *bytes; size_t len; int nl; } Line;
typedef struct { Line *v; size_t n, cap; } Lines;

static void lines_push(Lines *L, const unsigned char *b, size_t len, int nl){
    if(L->n==L->cap){ L->cap = L->cap? L->cap*2 : 8; L->v = realloc(L->v, L->cap*sizeof(Line)); }
    L->v[L->n].bytes = malloc(len?len:1);
    if(len) memcpy(L->v[L->n].bytes, b, len);
    L->v[L->n].len=len; L->v[L->n].nl=nl; L->n++;
}

static void split_lines(const unsigned char*buf,size_t len,Lines*out){
    size_t i=0;
    while(i<len){
        const unsigned char *nl = memchr(buf+i,'\n',len-i);
        if(nl){ lines_push(out,buf+i,(size_t)(nl-(buf+i)),1); i=(size_t)(nl-buf)+1; }
        else { lines_push(out,buf+i,len-i,0); i=len; }
    }
}

static int line_eq(const Line*a,const Line*b){
    return a->len==b->len && a->nl==b->nl && (a->len==0 || memcmp(a->bytes,b->bytes,a->len)==0);
}

static unsigned char* read_file(const char*path,size_t*len){
    FILE*f=fopen(path,"rb");
    if(!f) return NULL;
    fseek(f,0,SEEK_END); long sz=ftell(f);
    if(sz<0){fclose(f);return NULL;}
    fseek(f,0,SEEK_SET);
    unsigned char*buf=malloc((size_t)sz?(size_t)sz:1);
    size_t rd=fread(buf,1,(size_t)sz,f);
    fclose(f);
    *len=rd;
    return buf;
}

typedef struct { long a,b,c,d; Lines oldl,newl; int malformed; } Hunk;
typedef struct {
    char *path; size_t pathlen;
    int kind; /* 0 modify, 1 create, 2 delete */
    Hunk *h; size_t nh,hcap;
    int *stat_,*hpos,*hoff;
    int error; /* 0 none, 1 already exists, 2 not found */
    int deleted; unsigned long nlines; uint32_t crc;
} Section;

int main(int argc,char**argv){
    crc_init();
    const char*dir = argc>1? argv[1] : ".";
    size_t dlen=strlen(dir);
    char *diffpath=malloc(dlen+20);
    sprintf(diffpath,"%s/changes.diff",dir);
    size_t dl; unsigned char*dbuf=read_file(diffpath,&dl);
    if(!dbuf) return 0;

    char **raw=malloc(16*sizeof(char*)); size_t nraw=0,rcap=16;
    {
        size_t i=0;
        while(i<dl){
            unsigned char*nl=memchr(dbuf+i,'\n',dl-i);
            size_t e = nl? (size_t)(nl-dbuf) : dl;
            char*s=malloc(e-i+1);
            if(e>i) memcpy(s,dbuf+i,e-i);
            s[e-i]=0;
            if(nraw==rcap){rcap*=2;raw=realloc(raw,rcap*sizeof(char*));}
            raw[nraw++]=s;
            i = nl? e+1 : dl;
        }
    }

    Section *secs=NULL; size_t nsec=0,scap=0;
    size_t i=0;
    while(i<nraw){
        if(strncmp(raw[i],"diff --git a/",13)==0){
            char*rest=raw[i]+13;
            char*sep=strstr(rest," b/");
            if(nsec==scap){scap=scap?scap*2:8;secs=realloc(secs,scap*sizeof(Section));}
            Section*s=&secs[nsec++]; memset(s,0,sizeof *s);
            if(sep){
                s->pathlen=(size_t)(sep-rest);
                s->path=malloc(s->pathlen+1);
                memcpy(s->path,rest,s->pathlen); s->path[s->pathlen]=0;
            } else { s->path=malloc(1); s->path[0]=0; s->pathlen=0; }
            i++; continue;
        }
        if(nsec>0){
            Section*s=&secs[nsec-1];
            if(strncmp(raw[i],"@@ ",3)==0){
                Hunk h; memset(&h,0,sizeof h);
                char*p=raw[i]+3;
                int ok=0;
                do {
                    if(*p!='-') break;
                    p++;
                    char*e; long a=strtol(p,&e,10); if(e==p)break; p=e;
                    long b=1;
                    if(*p==','){p++; long bb=strtol(p,&e,10); if(e==p)break; b=bb; p=e;}
                    if(strncmp(p," +",2)!=0)break; p+=2;
                    long c=strtol(p,&e,10); if(e==p)break; p=e;
                    long d=1;
                    if(*p==','){p++; long dd=strtol(p,&e,10); if(e==p)break; d=dd; p=e;}
                    if(strncmp(p," @@",3)!=0)break;
                    h.a=a;h.b=b;h.c=c;h.d=d; ok=1;
                } while(0);
                if(ok){
                    size_t j=i+1;
                    long po=-1,pn=-1;
                    while(j<nraw && strncmp(raw[j],"@@ ",3)!=0 && strncmp(raw[j],"diff --git ",11)!=0){
                        char*bl=raw[j]; size_t blen=strlen(bl);
                        char m=blen?bl[0]:0;
                        if(m=='\\'){
                            if(po>=0) h.oldl.v[po].nl=0;
                            if(pn>=0) h.newl.v[pn].nl=0;
                            po=pn=-1;
                        } else if(m==' '){
                            lines_push(&h.oldl,(unsigned char*)bl+1,blen-1,1);
                            lines_push(&h.newl,(unsigned char*)bl+1,blen-1,1);
                            po=(long)h.oldl.n-1; pn=(long)h.newl.n-1;
                        } else if(m=='-'){
                            lines_push(&h.oldl,(unsigned char*)bl+1,blen-1,1);
                            po=(long)h.oldl.n-1; pn=-1;
                        } else if(m=='+'){
                            lines_push(&h.newl,(unsigned char*)bl+1,blen-1,1);
                            pn=(long)h.newl.n-1; po=-1;
                        } else {
                            po=pn=-1;
                        }
                        j++;
                    }
                    if(h.oldl.n!=(size_t)h.b || h.newl.n!=(size_t)h.d) h.malformed=1;
                    if(s->nh==s->hcap){s->hcap=s->hcap?s->hcap*2:4;s->h=realloc(s->h,s->hcap*sizeof(Hunk));}
                    s->h[s->nh++]=h;
                    i=j; continue;
                }
                i++; continue;
            }
            if(strncmp(raw[i],"new file mode ",14)==0){ s->kind=1; i++; continue; }
            if(strncmp(raw[i],"deleted file mode ",18)==0){ s->kind=2; i++; continue; }
            i++; continue;
        }
        i++;
    }

    for(size_t si=0;si<nsec;si++){
        Section*s=&secs[si];
        char*full=malloc(dlen+7+s->pathlen+2);
        sprintf(full,"%s/tree/%s",dir,s->path);
        Lines cur; memset(&cur,0,sizeof cur);
        if(s->kind==1){
            FILE*f=fopen(full,"rb");
            if(f){ fclose(f); s->error=1; }
        } else {
            size_t fl; unsigned char*fb=read_file(full,&fl);
            if(!fb) s->error=2;
            else split_lines(fb,fl,&cur);
        }
        s->stat_=malloc((s->nh?s->nh:1)*sizeof(int));
        s->hpos=malloc((s->nh?s->nh:1)*sizeof(long));
        s->hoff=malloc((s->nh?s->nh:1)*sizeof(long));
        int all=1;
        long delta=0;
        for(size_t k=0;k<s->nh;k++){
            Hunk*h=&s->h[k];
            if(h->malformed){ s->stat_[k]=2; all=0; continue; }
            long P=h->a+delta;
            if(h->b==0){
                if(P<0 || P>(long)cur.n){ s->stat_[k]=1; all=0; }
                else {
                    size_t nn=cur.n+h->newl.n;
                    Line*nv=malloc((nn?nn:1)*sizeof(Line));
                    if(P>0) memcpy(nv,cur.v,P*sizeof(Line));
                    if(h->newl.n) memcpy(nv+P,h->newl.v,h->newl.n*sizeof(Line));
                    if(cur.n-(size_t)P>0) memcpy(nv+P+h->newl.n,cur.v+P,(cur.n-(size_t)P)*sizeof(Line));
                    free(cur.v); cur.v=nv; cur.n=nn;
                    s->stat_[k]=0; s->hpos[k]=P; s->hoff[k]=0;
                    delta += h->d - h->b;
                }
            } else {
                long b=h->b;
                long hi=(long)cur.n - b + 1;
                long found=-1;
                if(hi>=1){
                    long kmax=(P-1>hi-P)?P-1:hi-P;
                    for(long kk=0; kk<=kmax && found<0; kk++){
                        long cand[2]={P-kk,P+kk};
                        for(int t=0;t<2;t++){
                            if(kk==0&&t==1) break;
                            long p=cand[t];
                            if(p<1||p>hi) continue;
                            int m=1;
                            for(long q=0;q<b;q++){
                                if(!line_eq(&cur.v[p-1+q],&h->oldl.v[q])){m=0;break;}
                            }
                            if(m){found=p;break;}
                        }
                    }
                }
                if(found<0){ s->stat_[k]=1; all=0; }
                else {
                    size_t nn=cur.n-(size_t)b+h->newl.n;
                    Line*nv=malloc((nn?nn:1)*sizeof(Line));
                    if(found-1>0) memcpy(nv,cur.v,(size_t)(found-1)*sizeof(Line));
                    if(h->newl.n) memcpy(nv+(found-1),h->newl.v,h->newl.n*sizeof(Line));
                    if(cur.n-(size_t)(found-1)-(size_t)b>0)
                        memcpy(nv+(found-1)+h->newl.n,cur.v+(found-1)+b,(cur.n-(size_t)(found-1)-(size_t)b)*sizeof(Line));
                    free(cur.v); cur.v=nv; cur.n=nn;
                    s->stat_[k]=0; s->hpos[k]=found; s->hoff[k]=found-P;
                    delta += h->d - h->b;
                }
            }
        }
        if(s->kind==2 && all && cur.n==0) s->deleted=1;
        if(!s->error && !s->deleted){
            size_t total=0;
            for(size_t q=0;q<cur.n;q++) total+=cur.v[q].len+(cur.v[q].nl?1:0);
            unsigned char*buf=malloc(total?total:1); size_t o=0;
            for(size_t q=0;q<cur.n;q++){
                if(cur.v[q].len){memcpy(buf+o,cur.v[q].bytes,cur.v[q].len); o+=cur.v[q].len;}
                if(cur.v[q].nl) buf[o++]='\n';
            }
            s->nlines=(unsigned long)cur.n;
            s->crc=crc32_of(buf,total);
        }
    }

    for(size_t x=0;x+1<nsec;x++)for(size_t y=x+1;y<nsec;y++){
        Section*A=&secs[x],*B=&secs[y];
        size_t m=A->pathlen<B->pathlen?A->pathlen:B->pathlen;
        int r=m?memcmp(A->path,B->path,m):0;
        if(r==0) r=A->pathlen<B->pathlen?-1:(A->pathlen>B->pathlen?1:0);
        if(r>0){ Section tmp=*A; *A=*B; *B=tmp; }
    }

    static const char*kindstr[]={"modify","create","delete"};
    for(size_t si=0;si<nsec;si++){
        Section*s=&secs[si];
        printf("%.*s: %s\n",(int)s->pathlen,s->path,kindstr[s->kind]);
        if(s->error){
            printf("  error: %s\n", s->error==1?"already exists":"not found");
        } else {
            for(size_t k=0;k<s->nh;k++){
                if(s->stat_[k]==0) printf("  hunk %zu: applied at %ld (offset %+ld)\n",k+1,s->hpos[k],s->hoff[k]);
                else if(s->stat_[k]==1) printf("  hunk %zu: rejected\n",k+1);
                else printf("  hunk %zu: malformed\n",k+1);
            }
            if(s->deleted) printf("  result: deleted\n");
            else printf("  result: %lu lines, crc32 %08x\n",s->nlines,(unsigned)s->crc);
        }
    }
    return 0;
}

