        }
        if(s->kind==2 && all && cur.n==0) s->deleted=1;
        if(!s->error && !s->deleted){
            size_t total=0;
            for(size_t q=0;q<cur.n;q++) total+=cur.v[q].len+(cur.v[q].nl?1:0);
            unsigned char*buf=malloc(total?total:1); size_t o=0;
            for(size_t q=0;q<cur.n;q++){
                if(cur.v[q].len){memcpy(buf+o,cur.v[q].bytes,cur.v[q].len); o+=cur.v[q].len;}
                if(cur.v[q].nl) buf[o++]='\n';
            }
            s->nlines=(unsigned long)cur.n;
            s->crc=crc32_of(buf,total);
        }
    }

    for(size_t x=0;x+1<nsec;x++)for(size_t y=x+1;y<nsec;y++){
        Section*A=&secs[x],*B=&secs[y];
        size_t m=A->pathlen<B->pathlen?A->pathlen:B->pathlen;
        int r=m?memcmp(A->path,B->path,m):0;
        if(r==0) r=A->pathlen<B->pathlen?-1:(A->pathlen>B->pathlen?1:0);
        if(r>0){ Section tmp=*A; *A=*B; *B=tmp; }
    }

    static const char*kindstr[]={"modify","create","delete"};
    for(size_t si=0;si<nsec;si++){
        Section*s=&secs[si];
        printf("%.*s: %s\n",(int)s->pathlen,s->path,kindstr[s->kind]);
        if(s->error){
            printf("  error: %s\n", s->error==1?"already exists":"not found");
        } else {
            for(size_t k=0;k<s->nh;k++){
                if(s->stat_[k]==0){
                    long off=s->hoff[k];
                    if(off==0)
                        printf("  hunk %zu: applied at %ld (offset 0)\n",k+1,s->hpos[k]);
                    else if(off>0)
                        printf("  hunk %zu: applied at %ld (offset +%ld)\n",k+1,s->hpos[k],off);
                    else
                        printf("  hunk %zu: applied at %ld (offset %ld)\n",k+1,s->hpos[k],off);
                }
                else if(s->stat_[k]==1) printf("  hunk %zu: rejected\n",k+1);
                else printf("  hunk %zu: malformed\n",k+1);
            }
            if(s->deleted) printf("  result: deleted\n");
            else printf("  result: %lu lines, crc32 %08x\n",s->nlines,(unsigned)s->crc);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <setjmp.h>
#include <stdarg.h>
#include <ctype.h>

/* ---------------- errors ---------------- */
static jmp_buf err_jmp;
static char err_msg[256];
static int err_line;
static void rt(int line, const char *fmt, ...) __attribute__((noreturn));
static void rt(int line, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    vsnprintf(err_msg, sizeof err_msg, fmt, ap);
    va_end(ap);
    err_line = line;
    longjmp(err_jmp, 1);
}

/* ---------------- string buffer ---------------- */
typedef struct { char *s; size_t len, cap; } SB;
static void sb_add(SB *sb, const char *p, size_t n) {
    if (sb->len + n + 1 > sb->cap) {
        sb->cap = (sb->len + n + 1) * 2;
        sb->s = realloc(sb->s, sb->cap);
    }
    memcpy(sb->s + sb->len, p, n);
    sb->len += n;
    sb->s[sb->len] = 0;
}

/* ---------------- tokens ---------------- */
enum {
    TK_EOF = 0, TK_INT, TK_STR, TK_IDENT,
    TK_EQ = 256, TK_NE, TK_LE, TK_GE,
    KW_AND = 300, KW_OR, KW_NOT, KW_IF, KW_ELSE, KW_WHILE, KW_FOR, KW_IN,
    KW_RETURN, KW_BREAK, KW_CONTINUE, KW_LET, KW_FN, KW_TRUE, KW_FALSE, KW_NIL
};
typedef struct { int kind, line; int64_t iv; char *s; int slen; } Token;
static Token *toks; static int ntoks, tcap, tpos;
static void addtok(int kind, int line, int64_t iv, char *s, int slen) {
    if (ntoks == tcap) { tcap = tcap ? tcap * 2 : 256; toks = realloc(toks, tcap * sizeof(Token)); }
    Token *t = &toks[ntoks++];
    t->kind = kind; t->line = line; t->iv = iv; t->s = s; t->slen = slen;
}
static void lex(const char *src) {
    size_t i = 0, n = strlen(src);
    int line = 1;
    static const char *kwn[] = {"and","or","not","if","else","while","for","in","return","break","continue","let","fn","true","false","nil"};
    static const int kvt[] = {KW_AND,KW_OR,KW_NOT,KW_IF,KW_ELSE,KW_WHILE,KW_FOR,KW_IN,KW_RETURN,KW_BREAK,KW_CONTINUE,KW_LET,KW_FN,KW_TRUE,KW_FALSE,KW_NIL};
    while (i < n) {
        char c = src[i];
        if (c == '\n') { line++; i++; continue; }
        if (c == ' ' || c == '\t' || c == '\r') { i++; continue; }
        if (c == '#') { while (i < n && src[i] != '\n') i++; continue; }
        if (c >= '0' && c <= '9') {
            int64_t v = 0;
            while (i < n && src[i] >= '0' && src[i] <= '9') { v = v * 10 + (src[i] - '0'); i++; }
            addtok(TK_INT, line, v, NULL, 0);
            continue;
        }
        if (c == '"') {
            int ln = line; i++;
            int cap = 16, len = 0; char *b = malloc(cap);
            while (i < n && src[i] != '"') {
                char ch = src[i];
                if (ch == '\\') {
                    i++;
                    char e = src[i];
                    if (e == 'n') ch = '\n'; else if (e == 't') ch = '\t';
                    else if (e == '"') ch = '"'; else if (e == '\\') ch = '\\';
                    i++;
                } else i++;
                if (len + 1 >= cap) { cap *= 2; b = realloc(b, cap); }
                b[len++] = ch;
            }
            i++;
            addtok(TK_STR, ln, 0, b, len);
            continue;
        }
        if (isalpha((unsigned char)c) || c == '_') {
            size_t st = i;
            while (i < n && (isalnum((unsigned char)src[i]) || src[i] == '_')) i++;
            int len = (int)(i - st);
            char *name = malloc(len + 1);
            memcpy(name, src + st, len); name[len] = 0;
            int k = TK_IDENT;
            for (int j = 0; j < 16; j++) if (!strcmp(name, kwn[j])) { k = kvt[j]; break; }
            addtok(k, line, 0, name, len);
            continue;
        }
        int ln = line;
        if (i + 1 < n) {
            if (src[i] == '=' && src[i+1] == '=') { addtok(TK_EQ, ln, 0, NULL, 0); i += 2; continue; }
            if (src[i] == '!' && src[i+1] == '=') { addtok(TK_NE, ln, 0, NULL, 0); i += 2; continue; }
            if (src[i] == '<' && src[i+1] == '=') { addtok(TK_LE, ln, 0, NULL, 0); i += 2; continue; }
            if (src[i] == '>' && src[i+1] == '=') { addtok(TK_GE, ln, 0, NULL, 0); i += 2; continue; }
        }
        addtok((unsigned char)c, ln, 0, NULL, 0);
        i++;
    }
    addtok(TK_EOF, line, 0, NULL, 0);
}

/* ---------------- AST ---------------- */
typedef struct Node Node;
typedef enum { N_INT, N_STR, N_BOOL, N_NIL, N_IDENT, N_LIST, N_FNEXP,
    N_BIN, N_NOT, N_NEG, N_CALL, N_INDEX,
    N_LET, N_FN, N_IF, N_WHILE, N_FOR, N_RETURN, N_BREAK, N_CONTINUE,
    N_ASSIGN, N_SETIDX, N_EXPRSTMT, N_BLOCK } NKind;
struct Node {
    NKind k; int line; int op;
    int64_t iv; char *s; int slen; char *name;
    Node *a, *b, *c;
    Node **items; int n;
    char **params; int np;
};
static Node *newnode(NKind k, int line) { Node *n = calloc(1, sizeof(Node)); n->k = k; n->line = line; return n; }
static void pushnode(Node ***arr, int *n, Node *nd) {
    *arr = realloc(*arr, (*n + 1) * sizeof(Node*));
    (*arr)[(*n)++] = nd;
}

/* ---------------- parser ---------------- */
static Node *parse_expr(void);
static Node *parse_block(void);
static Node *parse_if(void);
static Node *parse_stmt(void);

static Token *pk(void) { return &toks[tpos]; }
static int at(int k) { return pk()->kind == k; }
static int atkw(const char *w) { return pk()->kind == TK_IDENT && !strcmp(pk()->s, w); }
static void adv(void) { tpos++; }
static int eat(int k) { if (at(k)) { adv(); return 1; } return 0; }
static int eatkw(const char *w) { if (atkw(w)) { adv(); return 1; } return 0; }
static void perr(void) { fprintf(stderr, "parse error\n"); exit(1); }
static void expect(int k) { if (!eat(k)) perr(); }
static char *expect_ident(void) { if (!at(TK_IDENT)) perr(); char *n = pk()->s; adv(); return n; }

static char **parse_params(int *np) {
    char **ps = NULL; int n = 0;
    if (!at(')')) {
        do { char *nm = expect_ident(); ps = realloc(ps, (n + 1) * sizeof(char*)); ps[n++] = nm; } while (eat(','));
    }
    *np = n; return ps;
}

static Node *parse_primary(void) {
    Token *t = pk();
    if (at(TK_INT)) { adv(); Node *n = newnode(N_INT, t->line); n->iv = t->iv; return n; }
    if (at(TK_STR)) { adv(); Node *n = newnode(N_STR, t->line); n->s = t->s; n->slen = t->slen; return n; }
    if (at(KW_TRUE)) { adv(); Node *n = newnode(N_BOOL, t->line); n->iv = 1; return n; }
    if (at(KW_FALSE)) { adv(); Node *n = newnode(N_BOOL, t->line); n->iv = 0; return n; }
    if (at(KW_NIL)) { adv(); return newnode(N_NIL, t->line); }
    if (at(TK_IDENT)) { adv(); Node *n = newnode(N_IDENT, t->line); n->name = t->s; return n; }
    if (eat('(')) { Node *e = parse_expr(); expect(')'); return e; }
    if (at('[')) {
        int ln = t->line; adv();
        Node *n = newnode(N_LIST, ln);
        if (!at(']')) { do { Node *el = parse_expr(); pushnode(&n->items, &n->n, el); } while (eat(',')); }
        expect(']');
        return n;
    }
    if (at(KW_FN)) {
        int ln = t->line; adv();
        expect('(');
        Node *n = newnode(N_FNEXP, ln);
        n->params = parse_params(&n->np);
        expect(')');
        n->a = parse_block();
        return n;
    }
    perr(); return NULL;
}
static Node *parse_postfix(void) {
    Node *e = parse_primary();
    for (;;) {
        if (at('(')) {
            int ln = pk()->line; adv();
            Node *n = newnode(N_CALL, ln); n->a = e;
            if (!at(')')) { do { Node *arg = parse_expr(); pushnode(&n->items, &n->n, arg); } while (eat(',')); }
            expect(')');
            e = n;
        } else if (at('[')) {
            int ln = pk()->line; adv();
            Node *n = newnode(N_INDEX, ln); n->a = e; n->b = parse_expr();
            expect(']');
            e = n;
        } else break;
    }
    return e;
}
static Node *parse_unary(void) {
    if (at('-')) { int ln = pk()->line; adv(); Node *n = newnode(N_NEG, ln); n->a = parse_unary(); return n; }
    return parse_postfix();
}
static Node *parse_mul(void) {
    Node *l = parse_unary();
    while (at('*') || at('/') || at('%')) {
        int op = pk()->kind, ln = pk()->line; adv();
        Node *r = parse_unary();
        Node *n = newnode(N_BIN, ln); n->op = op; n->a = l; n->b = r; l = n;
    }
    return l;
}
static Node *parse_add(void) {
    Node *l = parse_mul();
    while (at('+') || at('-')) {
        int op = pk()->kind, ln = pk()->line; adv();
        Node *r = parse_mul();
        Node *n = newnode(N_BIN, ln); n->op = op; n->a = l; n->b = r; l = n;
    }
    return l;
}
static Node *parse_cmp(void) {
    Node *l = parse_add();
    while (at(TK_EQ) || at(TK_NE) || at('<') || at('>') || at(TK_LE) || at(TK_GE)) {
        int op = pk()->kind, ln = pk()->line; adv();
        Node *r = parse_add();
        Node *n = newnode(N_BIN, ln); n->op = op; n->a = l; n->b = r; l = n;
    }
    return l;
}
static Node *parse_not(void) {
    if (at(KW_NOT)) { int ln = pk()->line; adv(); Node *n = newnode(N_NOT, ln); n->a = parse_not(); return n; }
    return parse_cmp();
}
static Node *parse_and(void) {
    Node *l = parse_not();
    while (at(KW_AND)) {
        int ln = pk()->line; adv();
        Node *r = parse_not();
        Node *n = newnode(N_BIN, ln); n->op = KW_AND; n->a = l; n->b = r; l = n;
    }
    return l;
}
static Node *parse_or(void) {
    Node *l = parse_and();
    while (at(KW_OR)) {
        int ln = pk()->line; adv();
        Node *r = parse_and();
        Node *n = newnode(N_BIN, ln); n->op = KW_OR; n->a = l; n->b = r; l = n;
    }
    return l;
}
static Node *parse_expr(void) { return parse_or(); }

static Node *parse_block(void) {
    int ln = pk()->line;
    expect('{');
    Node *n = newnode(N_BLOCK, ln);
    while (!at('}')) { Node *s = parse_stmt(); pushnode(&n->items, &n->n, s); }
    expect('}');
    return n;
}
static Node *parse_if(void) {
    int ln = pk()->line;
    expect(KW_IF);
    Node *n = newnode(N_IF, ln);
    n->a = parse_expr();
    n->b = parse_block();
    if (eatkw("else")) {
        if (at(KW_IF)) n->c = parse_if();
        else n->c = parse_block();
    }
    return n;
}
static Node *parse_stmt(void) {
    Token *t = pk();
    if (eatkw("let")) {
        int ln = t->line;
        char *name = expect_ident();
        expect('=');
        Node *e = parse_expr();
        expect(';');
        Node *n = newnode(N_LET, ln); n->name = name; n->a = e; return n;
    }
    if (at(KW_FN) && toks[tpos + 1].kind == TK_IDENT) {
        adv();
        char *name = expect_ident();
        expect('(');
        Node *n = newnode(N_FN, t->line); n->name = name;
        n->params = parse_params(&n->np);
        expect(')');
        n->a = parse_block();
        return n;
    }
    if (at(KW_IF)) return parse_if();
    if (at(KW_WHILE)) {
        adv();
        Node *n = newnode(N_WHILE, t->line);
        n->a = parse_expr();
        n->b = parse_block();
        return n;
    }
    if (at(KW_FOR)) {
        adv();
        Node *n = newnode(N_FOR, t->line);
        n->name = expect_ident();
        if (!eatkw("in")) perr();
        n->a = parse_expr();
        n->b = parse_block();
        return n;
    }
    if (at(KW_RETURN)) {
        adv();
        Node *n = newnode(N_RETURN, t->line);
        if (!eat(';')) { n->a = parse_expr(); expect(';'); }
        return n;
    }
    if (at(KW_BREAK)) { adv(); expect(';'); return newnode(N_BREAK, t->line); }
    if (at(KW_CONTINUE)) { adv(); expect(';'); return newnode(N_CONTINUE, t->line); }
    Node *e = parse_expr();
    if (eat('=')) {
        Node *r = parse_expr();
        expect(';');
        if (e->k == N_IDENT) { Node *n = newnode(N_ASSIGN, e->line); n->name = e->name; n->a = r; return n; }
        if (e->k == N_INDEX) { Node *n = newnode(N_SETIDX, e->line); n->a = e->a; n->b = e->b; n->c = r; return n; }
        perr();
    }
    expect(';');
    Node *n = newnode(N_EXPRSTMT, e->line); n->a = e; return n;
}
static Node *parse_program(void) {
    Node *prog = newnode(N_BLOCK, 0);
    while (!at(TK_EOF)) { Node *s = parse_stmt(); pushnode(&prog->items, &prog->n, s); }
    return prog;
}

/* ---------------- values ---------------- */
typedef struct List { int len, cap; struct Value *items; } List;
typedef struct Func { Node **body; int nbody; char **params; int np; struct Scope *env; } Func;
typedef struct Scope { struct Scope *parent; struct SV { char *name; struct Value v; } *vars; int n, cap; } Scope;
enum { T_INT, T_BOOL, T_STR, T_LIST, T_FN, T_NIL, T_BUILTIN };
typedef struct Value {
    uint8_t t;
    union { int64_t i; int b; struct { char *s; int len; } s; List *l; Func *f; int bi; } u;
} Value;

static Value VINT(int64_t x) { Value v; v.t = T_INT; v.u.i = x; return v; }
static Value VBOOL(int b) { Value v; v.t = T_BOOL; v.u.b = b; return v; }
static Value VNIL(void) { Value v; memset(&v, 0, sizeof v); v.t = T_NIL; return v; }
static Value VSTR(char *s, int len) { Value v; v.t = T_STR; v.u.s.s = s; v.u.s.len = len; return v; }
static Value VL(List *l) { Value v; v.t = T_LIST; v.u.l = l; return v; }
static Value VF(Func *f) { Value v; v.t = T_FN; v.u.f = f; return v; }
static Value VBUILTIN(int i) { Value v; memset(&v, 0, sizeof v); v.t = T_BUILTIN; v.u.bi = i; return v; }

static const char *tn(Value v) {
    static const char *names[] = {"int","bool","string","list","function","nil","function"};
    return names[v.t];
}
static void list_push(List *l, Value v) {
    if (l->len == l->cap) { l->cap = l->cap ? l->cap * 2 : 4; l->items = realloc(l->items, l->cap * sizeof(Value)); }
    l->items[l->len++] = v;
}
static Scope *newscope(Scope *p) { Scope *s = calloc(1, sizeof(Scope)); s->parent = p; return s; }
static void scope_def(Scope *s, char *name, Value v) {
    if (s->n == s->cap) { s->cap = s->cap ? s->cap * 2 : 4; s->vars = realloc(s->vars, s->cap * sizeof(struct SV)); }
    s->vars[s->n].name = name; s->vars[s->n].v = v; s->n++;
}
static Value *scope_get(Scope *s, char *name) {
    for (; s; s = s->parent)
        for (int i = 0; i < s->n; i++)
            if (!strcmp(s->vars[i].name, name)) return &s->vars[i].v;
    return NULL;
}
static int truthy(Value v) {
    switch (v.t) {
    case T_INT: return v.u.i != 0;
    case T_BOOL: return v.u.b;
    case T_STR: return v.u.s.len > 0;
    case T_LIST: return v.u.l->len > 0;
    default: return 0;
    }
}
static int val_eq(Value a, Value b) {
    if (a.t != b.t) return 0;
    switch (a.t) {
    case T_INT: return a.u.i == b.u.i;
    case T_BOOL: return a.u.b == b.u.b;
    case T_NIL: return 1;
    case T_STR: return a.u.s.len == b.u.s.len && (a.u.s.len == 0 || !memcmp(a.u.s.s, b.u.s.s, a.u.s.len));
    case T_LIST: {
        List *x = a.u.l, *y = b.u.l;
        if (x->len != y->len) return 0;
        for (int i = 0; i < x->len; i++) if (!val_eq(x->items[i], y->items[i])) return 0;
        return 1;
    }
    case T_FN: return a.u.f == b.u.f;
    case T_BUILTIN: return a.u.bi == b.u.bi;
    }
    return 0;
}
static int str_cmp(Value a, Value b) {
    int m = a.u.s.len < b.u.s.len ? a.u.s.len : b.u.s.len;
    int c = m ? memcmp(a.u.s.s, b.u.s.s, m) : 0;
    if (c) return c < 0 ? -1 : 1;
    return a.u.s.len < b.u.s.len ? -1 : a.u.s.len > b.u.s.len ? 1 : 0;
}
static const char *opname(int op) {
    switch (op) {
    case '+': return "+"; case '-': return "-"; case '*': return "*";
    case '/': return "/"; case '%': return "%"; case '<': return "<"; case '>': return ">";
    case TK_LE: return "<="; case TK_GE: return ">="; case TK_EQ: return "=="; case TK_NE: return "!=";
    }
    return "?";
}

/* ---------------- display ---------------- */
static List **dstack; static int dn, dcap;
static void disp(Value v, SB *sb, int inlist) {
    char buf[32];
    switch (v.t) {
    case T_INT: sprintf(buf, "%lld", (long long)v.u.i); sb_add(sb, buf, strlen(buf)); return;
    case T_BOOL: sb_add(sb, v.u.b ? "true" : "false", v.u.b ? 4 : 5); return;
    case T_NIL: sb_add(sb, "nil", 3); return;
    case T_FN: case T_BUILTIN: sb_add(sb, "<fn>", 4); return;
    case T_STR:
        if (!inlist) { if (v.u.s.len) sb_add(sb, v.u.s.s, v.u.s.len); return; }
        sb_add(sb, "\"", 1);
        for (int i = 0; i < v.u.s.len; i++) {
            char c = v.u.s.s[i];
            if (c == '\\') sb_add(sb, "\\\\", 2);
            else if (c == '"') sb_add(sb, "\\\"", 2);
            else if (c == '\n') sb_add(sb, "\\n", 2);
            else if (c == '\t') sb_add(sb, "\\t", 2);
            else sb_add(sb, &c, 1);
        }
        sb_add(sb, "\"", 1);
        return;
    case T_LIST: {
        List *l = v.u.l;
        for (int i = 0; i < dn; i++) if (dstack[i] == l) { sb_add(sb, "[...]", 5); return; }
        if (dn == dcap) { dcap = dcap ? dcap * 2 : 8; dstack = realloc(dstack, dcap * sizeof(List*)); }
        dstack[dn++] = l;
        sb_add(sb, "[", 1);
        for (int i = 0; i < l->len; i++) { if (i) sb_add(sb, ", ", 2); disp(l->items[i], sb, 1); }
        sb_add(sb, "]", 1);
        dn--;
        return;
    }
    }
}

/* ---------------- builtins ---------------- */
typedef struct { const char *name; int nargs; Value (*fn)(Value*, int, int); } Builtin;
static Value bi_print(Value *a, int n, int line) {
    (void)line;
    SB sb = {0};
    for (int i = 0; i < n; i++) { if (i) sb_add(&sb, " ", 1); disp(a[i], &sb, 0); }
    sb_add(&sb, "\n", 1);
    fwrite(sb.s ? sb.s : "", 1, sb.len, stdout);
    return VNIL();
}
static Value bi_str(Value *a, int n, int line) {
    (void)n; (void)line;
    SB sb = {0};
    disp(a[0], &sb, 0);
    if (!sb.s) { char *e = malloc(1); e[0] = 0; return VSTR(e, 0); }
    return VSTR(sb.s, (int)sb.len);
}
static Value bi_type(Value *a, int n, int line) {
    (void)n; (void)line;
    const char *t = tn(a[0]);
    return VSTR(strdup(t), (int)strlen(t));
}
static Value bi_len(Value *a, int n, int line) {
    (void)n;
    if (a[0].t == T_STR) return VINT(a[0].u.s.len);
    if (a[0].t == T_LIST) return VINT(a[0].u.l->len);
    rt(line, "bad argument to len");
}
static Value bi_push(Value *a, int n, int line) {
    (void)n;
    if (a[0].t != T_LIST) rt(line, "bad argument to push");
    list_push(a[0].u.l, a[1]);
    return VNIL();
}
static Value bi_pop(Value *a, int n, int line) {
    (void)n;
    if (a[0].t != T_LIST || a[0].u.l->len == 0) rt(line, "bad argument to pop");
    return a[0].u.l->items[--a[0].u.l->len];
}
static Value bi_range(Value *a, int n, int line) {
    (void)n;
    if (a[0].t != T_INT || a[1].t != T_INT) rt(line, "bad argument to range");
    List *l = calloc(1, sizeof(List));
    for (int64_t i = a[0].u.i; i < a[1].u.i; i++) list_push(l, VINT(i));
    return VL(l);
}
static Value bi_slice(Value *a, int n, int line) {
    (void)n;
    if (a[1].t != T_INT || a[2].t != T_INT) rt(line, "bad argument to slice");
    int64_t s = a[1].u.i, e = a[2].u.i;
    if (a[0].t == T_STR) {
        if (s < 0 || e < s || e > a[0].u.s.len) rt(line, "bad argument to slice");
        int len = (int)(e - s);
        char *b = malloc(len ? len : 1);
        memcpy(b, a[0].u.s.s + s, len);
        return VSTR(b, len);
    }
    if (a[0].t == T_LIST) {
        List *x = a[0].u.l;
        if (s < 0 || e < s || e > x->len) rt(line, "bad argument to slice");
        List *l = calloc(1, sizeof(List));
        for (int64_t i = s; i < e; i++) list_push(l, x->items[i]);
        return VL(l);
    }
    rt(line, "bad argument to slice");
}
static Builtin builtins[] = {
    {"print", -1, bi_print}, {"str", 1, bi_str}, {"type", 1, bi_type}, {"len", 1, bi_len},
    {"push", 2, bi_push}, {"pop", 1, bi_pop}, {"range", 2, bi_range}, {"slice", 3, bi_slice},
};
#define NBUILTIN ((int)(sizeof builtins / sizeof builtins[0]))

/* ---------------- interpreter ---------------- */
typedef struct { int k; Value ret; } Res;
enum { R_NORMAL, R_BREAK, R_CONT, R_RET };
static Res mkres(int k, Value v) { Res r; r.k = k; r.ret = v; return r; }
static Value eval(Node *n, Scope *sc);
static Res exec_stmts(Scope *sc, Node **st, int cnt);

static Value binop(int op, Value l, Value r, int line) {
    switch (op) {
    case '+':
        if (l.t == T_INT && r.t == T_INT) {
            int64_t res;
            if (__builtin_add_overflow(l.u.i, r.u.i, &res)) rt(line, "integer overflow");
            return VINT(res);
        }
        if (l.t == T_STR && r.t == T_STR) {
            int len = l.u.s.len + r.u.s.len;
            char *b = malloc(len ? len : 1);
            memcpy(b, l.u.s.s, l.u.s.len);
            memcpy(b + l.u.s.len, r.u.s.s, r.u.s.len);
            return VSTR(b, len);
        }
        if (l.t == T_LIST && r.t == T_LIST) {
            List *nl = calloc(1, sizeof(List));
            for (int i = 0; i < l.u.l->len; i++) list_push(nl, l.u.l->items[i]);
            for (int i = 0; i < r.u.l->len; i++) list_push(nl, r.u.l->items[i]);
            return VL(nl);
        }
        rt(line, "cannot apply + to %s and %s", tn(l), tn(r));
    case '-': case '*': case '/': case '%': {
        if (l.t != T_INT || r.t != T_INT)
            rt(line, "cannot apply %s to %s and %s", opname(op), tn(l), tn(r));
        int64_t a = l.u.i, b = r.u.i;
        if (op == '-') { int64_t res; if (__builtin_sub_overflow(a, b, &res)) rt(line, "integer overflow"); return VINT(res); }
        if (op == '*') { int64_t res; if (__builtin_mul_overflow(a, b, &res)) rt(line, "integer overflow"); return VINT(res); }
        if (op == '/') {
            if (b == 0) rt(line, "division by zero");
            if (a == INT64_MIN && b == -1) rt(line, "integer overflow");
            return VINT(a / b);
        }
        if (b == 0) rt(line, "division by zero");
        if (b == -1) return VINT(0);
        return VINT(a % b);
    }
    case '<': case '>': case TK_LE: case TK_GE: {
        if (l.t == T_INT && r.t == T_INT) {
            switch (op) {
            case '<': return VBOOL(l.u.i < r.u.i);
            case '>': return VBOOL(l.u.i > r.u.i);
            case TK_LE: return VBOOL(l.u.i <= r.u.i);
            default: return VBOOL(l.u.i >= r.u.i);
            }
        }
        if (l.t == T_STR && r.t == T_STR) {
            int c = str_cmp(l, r);
            switch (op) {
            case '<': return VBOOL(c < 0);
            case '>': return VBOOL(c > 0);
            case TK_LE: return VBOOL(c <= 0);
            default: return VBOOL(c >= 0);
            }
        }
        rt(line, "cannot apply %s to %s and %s", opname(op), tn(l), tn(r));
    }
    case TK_EQ: return VBOOL(val_eq(l, r));
    case TK_NE: return VBOOL(!val_eq(l, r));
    }
    return VNIL();
}

static Value call_value(Value c, Value *args, int na, int line) {
    if (c.t == T_BUILTIN) {
        Builtin *b = &builtins[c.u.bi];
        if (b->nargs >= 0 && na != b->nargs) rt(line, "expected %d arguments, got %d", b->nargs, na);
        return b->fn(args, na, line);
    }
    if (c.t == T_FN) {
        Func *f = c.u.f;
        if (na != f->np) rt(line, "expected %d arguments, got %d", f->np, na);
        Scope *s = newscope(f->env);
        for (int i = 0; i < f->np; i++) scope_def(s, f->params[i], args[i]);
        Res r = exec_stmts(s, f->body, f->nbody);
        return r.k == R_RET ? r.ret : VNIL();
    }
    rt(line, "cannot call %s", tn(c));
}

static Value eval(Node *n, Scope *sc) {
    switch (n->k) {
    case N_INT: return VINT(n->iv);
    case N_STR: return VSTR(n->s, n->slen);
    case N_BOOL: return VBOOL((int)n->iv);
    case N_NIL: return VNIL();
    case N_IDENT: {
        Value *v = scope_get(sc, n->name);
        if (!v) rt(n->line, "undefined variable %s", n->name);
        return *v;
    }
    case N_LIST: {
        List *l = calloc(1, sizeof(List));
        for (int i = 0; i < n->n; i++) list_push(l, eval(n->items[i], sc));
        return VL(l);
    }
    case N_FNEXP: {
        Func *f = malloc(sizeof(Func));
        f->params = n->params; f->np = n->np;
        f->body = n->a->items; f->nbody = n->a->n;
        f->env = sc;
        return VF(f);
    }
    case N_NEG: {
        Value v = eval(n->a, sc);
        if (v.t != T_INT) rt(n->line, "cannot apply - to %s", tn(v));
        if (v.u.i == INT64_MIN) rt(n->line, "integer overflow");
        return VINT(-v.u.i);
    }
    case N_NOT: return VBOOL(!truthy(eval(n->a, sc)));
    case N_BIN: {
        if (n->op == KW_AND) { Value l = eval(n->a, sc); if (!truthy(l)) return l; return eval(n->b, sc); }
        if (n->op == KW_OR) { Value l = eval(n->a, sc); if (truthy(l)) return l; return eval(n->b, sc); }
        Value l = eval(n->a, sc), r = eval(n->b, sc);
        return binop(n->op, l, r, n->line);
    }
    case N_CALL: {
        Value c = eval(n->a, sc);
        Value *args = n->n ? malloc(n->n * sizeof(Value)) : NULL;
        for (int i = 0; i < n->n; i++) args[i] = eval(n->items[i], sc);
        return call_value(c, args, n->n, n->line);
    }
    case N_INDEX: {
        Value o = eval(n->a, sc), i = eval(n->b, sc);
        if (o.t == T_LIST) {
            if (i.t != T_INT) rt(n->line, "cannot index list with %s", tn(i));
            if (i.u.i < 0 || i.u.i >= o.u.l->len)
                rt(n->line, "index %lld out of range for length %d", (long long)i.u.i, o.u.l->len);
            return o.u.l->items[i.u.i];
        }
        if (o.t == T_STR) {
            if (i.t != T_INT) rt(n->line, "cannot index string with %s", tn(i));
            if (i.u.i < 0 || i.u.i >= o.u.s.len)
                rt(n->line, "index %lld out of range for length %d", (long long)i.u.i, o.u.s.len);
            char *b = malloc(1); b[0] = o.u.s.s[i.u.i];
            return VSTR(b, 1);
        }
        rt(n->line, "cannot index %s with %s", tn(o), tn(i));
    }
    }
    return VNIL();
}

static Res exec_stmt(Scope *sc, Node *n) {
    switch (n->k) {
    case N_LET: scope_def(sc, n->name, eval(n->a, sc)); break;
    case N_FN: {
        Func *f = malloc(sizeof(Func));
        f->params = n->params; f->np = n->np;
        f->body = n->a->items; f->nbody = n->a->n;
        f->env = sc;
        scope_def(sc, n->name, VF(f));
        break;
    }
    case N_ASSIGN: {
        Value v = eval(n->a, sc);
        Value *slot = scope_get(sc, n->name);
        if (!slot) rt(n->line, "undefined variable %s", n->name);
        *slot = v;
        break;
    }
    case N_SETIDX: {
        Value o = eval(n->a, sc), i = eval(n->b, sc), v = eval(n->c, sc);
        if (o.t != T_LIST) rt(n->line, "cannot assign into %s", tn(o));
        if (i.t != T_INT) rt(n->line, "cannot index list with %s", tn(i));
        if (i.u.i < 0 || i.u.i >= o.u.l->len)
            rt(n->line, "index %lld out of range for length %d", (long long)i.u.i, o.u.l->len);
        o.u.l->items[i.u.i] = v;
        break;
    }
    case N_EXPRSTMT: eval(n->a, sc); break;
    case N_BLOCK: { Scope *s2 = newscope(sc); return exec_stmts(s2, n->items, n->n); }
    case N_IF: {
        Value c = eval(n->a, sc);
        if (truthy(c)) return exec_stmt(sc, n->b);
        if (n->c) return exec_stmt(sc, n->c);
        break;
    }
    case N_WHILE: {
        for (;;) {
            Value c = eval(n->a, sc);
            if (!truthy(c)) break;
            Res r = exec_stmt(sc, n->b);
            if (r.k == R_BREAK) break;
        }
        break;
    }
    case N_FOR: {
        Value l = eval(n->a, sc);
        if (l.t != T_LIST) rt(n->line, "cannot iterate %s", tn(l));
        List *L = l.u.l;
        int64_t i = 0;
        while (i < L->len) {
            Scope *xs = newscope(sc);
            scope_def(xs, n->name, L->items[i]);
            Res r = exec_stmt(xs, n->b);
            if (r.k == R_BREAK) break;
            i++;
        }
        break;
    }
    case N_RETURN: return mkres(R_RET, n->a ? eval(n->a, sc) : VNIL());
    case N_BREAK: return mkres(R_BREAK, VNIL());
    case N_CONTINUE: return mkres(R_CONT, VNIL());
    default: break;
    }
    return mkres(R_NORMAL, VNIL());
}
static Res exec_stmts(Scope *sc, Node **st, int cnt) {
    for (int i = 0; i < cnt; i++) {
        Res r = exec_stmt(sc, st[i]);
        if (r.k != R_NORMAL) return r;
    }
    return mkres(R_NORMAL, VNIL());
}

/* ---------------- main ---------------- */
int main(int argc, char **argv) {
    if (argc < 2) return 1;
    char path[4096];
    snprintf(path, sizeof path, "%s/program.tern", argv[1]);
    FILE *fp = fopen(path, "rb");
    if (!fp) return 1;
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *src = malloc(sz + 1);
    if (fread(src, 1, sz, fp) != (size_t)sz) return 1;
    src[sz] = 0;
    fclose(fp);

    lex(src);
    tpos = 0;
    Node *prog = parse_program();

    Scope *bscope = newscope(NULL);
    for (int i = 0; i < NBUILTIN; i++) scope_def(bscope, (char*)builtins[i].name, VBUILTIN(i));
    Scope *globals = newscope(bscope);

    if (setjmp(err_jmp)) {
        printf("error at line %d: %s\n", err_line, err_msg);
        return 0;
    }
    exec_stmts(globals, prog->items, prog->n);
    return 0;
}

import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.*;
import java.util.*;
import javax.imageio.ImageIO;

public class Main {
    // ---------- minimal JSON parser ----------
    static String s;
    static int pos;

    static void skip() { while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++; }

    static String parseString() {
        skip();
        StringBuilder sb = new StringBuilder();
        pos++; // opening quote
        while (s.charAt(pos) != '"') {
            char c = s.charAt(pos);
            if (c == '\\') {
                pos++;
                char e = s.charAt(pos);
                switch (e) {
                    case 'n': sb.append('\n'); break;
                    case 't': sb.append('\t'); break;
                    case 'r': sb.append('\r'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'u':
                        sb.append((char) Integer.parseInt(s.substring(pos + 1, pos + 5), 16));
                        pos += 4;
                        break;
                    default: sb.append(e);
                }
                pos++;
            } else { sb.append(c); pos++; }
        }
        pos++; // closing quote
        return sb.toString();
    }

    static Object parseValue() {
        skip();
        char c = s.charAt(pos);
        if (c == '{') {
            pos++;
            Map<String, Object> m = new LinkedHashMap<>();
            skip();
            if (s.charAt(pos) == '}') { pos++; return m; }
            while (true) {
                skip();
                String k = parseString();
                skip();
                pos++; // ':'
                m.put(k, parseValue());
                skip();
                char d = s.charAt(pos);
                pos++;
                if (d == '}') return m;
            }
        }
        if (c == '[') {
            pos++;
            List<Object> l = new ArrayList<>();
            skip();
            if (s.charAt(pos) == ']') { pos++; return l; }
            while (true) {
                l.add(parseValue());
                skip();
                char d = s.charAt(pos);
                pos++;
                if (d == ']') return l;
            }
        }
        if (c == '"') return parseString();
        if (s.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
        if (s.startsWith("false", pos)) { pos += 5; return Boolean.FALSE; }
        if (s.startsWith("null", pos)) { pos += 4; return null; }
        int start = pos;
        while (pos < s.length() && "+-0123456789.eE".indexOf(s.charAt(pos)) >= 0) pos++;
        String num = s.substring(start, pos);
        if (num.indexOf('.') < 0 && num.indexOf('e') < 0 && num.indexOf('E') < 0)
            return Long.parseLong(num);
        return Double.parseDouble(num);
    }

    static long getLong(Map<String, Object> m, String k) { return ((Number) m.get(k)).longValue(); }

    static int[] getColor(Object o) {
        List<?> l = (List<?>) o;
        int[] c = new int[l.size()];
        for (int i = 0; i < l.size(); i++) c[i] = (int) ((Number) l.get(i)).longValue();
        return c;
    }

    // ---------- coverage tests ----------
    static boolean covers(Map<String, Object> sh, long x, long y) {
        String type = (String) sh.get("type");
        switch (type) {
            case "rect": {
                long rx = getLong(sh, "x"), ry = getLong(sh, "y");
                long w = getLong(sh, "w"), h = getLong(sh, "h");
                return x >= rx && x < rx + w && y >= ry && y < ry + h;
            }
            case "circle": {
                long cx = getLong(sh, "cx"), cy = getLong(sh, "cy"), r = getLong(sh, "r");
                long dx = x - cx, dy = y - cy;
                return dx * dx + dy * dy <= r * r;
            }
            case "triangle": {
                List<?> pts = (List<?>) sh.get("points");
                long[] px = new long[3], py = new long[3];
                for (int i = 0; i < 3; i++) {
                    List<?> p = (List<?>) pts.get(i);
                    px[i] = ((Number) p.get(0)).longValue();
                    py[i] = ((Number) p.get(1)).longValue();
                }
                long e0 = 0, e1 = 0, e2 = 0;
                for (int i = 0; i < 3; i++) {
                    int j = (i + 1) % 3;
                    long e = (px[j] - px[i]) * (y - py[i]) - (py[j] - py[i]) * (x - px[i]);
                    if (i == 0) e0 = e; else if (i == 1) e1 = e; else e2 = e;
                }
                return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
            }
            case "line": {
                long x1 = getLong(sh, "x1"), y1 = getLong(sh, "y1");
                long x2 = getLong(sh, "x2"), y2 = getLong(sh, "y2");
                long r = getLong(sh, "r");
                long dx = x2 - x1, dy = y2 - y1;
                long L = dx * dx + dy * dy;
                long t = (x - x1) * dx + (y - y1) * dy;
                if (t <= 0) {
                    long ax = x - x1, ay = y - y1;
                    return ax * ax + ay * ay <= r * r;
                } else if (t >= L) {
                    long bx = x - x2, by = y - y2;
                    return bx * bx + by * by <= r * r;
                } else {
                    long c = (x - x1) * dy - (y - y1) * dx;
                    return c * c <= r * r * L;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        String json = new String(Files.readAllBytes(Paths.get(args[0], "scene.json")));
        s = json;
        pos = 0;
        @SuppressWarnings("unchecked")
        Map<String, Object> scene = (Map<String, Object>) parseValue();

        int width = (int) getLong(scene, "width");
        int height = (int) getLong(scene, "height");
        int[] bg = getColor(scene.get("background"));

        int[] canvas = new int[width * height];
        int bgRGB = (bg[0] << 16) | (bg[1] << 8) | bg[2];
        Arrays.fill(canvas, bgRGB);

        List<?> shapes = (List<?>) scene.get("shapes");
        StringBuilder out = new StringBuilder();
        int idx = 1;
        for (Object o : shapes) {
            @SuppressWarnings("unchecked")
            Map<String, Object> sh = (Map<String, Object>) o;
            int[] col = getColor(sh.get("color"));
            int sr = col[0], sg = col[1], sb = col[2];
            int A = col.length > 3 ? col[3] : 255;
            long count = 0;
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    if (covers(sh, x, y)) {
                        count++;
                        int d = canvas[y * width + x];
                        int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
                        int nr = (sr * A + dr * (255 - A) + 127) / 255;
                        int ng = (sg * A + dg * (255 - A) + 127) / 255;
                        int nb = (sb * A + db * (255 - A) + 127) / 255;
                        canvas[y * width + x] = (nr << 16) | (ng << 8) | nb;
                    }
                }
            }
            out.append(idx).append(' ').append((String) sh.get("type")).append(' ').append(count).append('\n');
            idx++;
        }

        Set<Integer> distinct = new HashSet<>();
        for (int c : canvas) distinct.add(c & 0xFFFFFF);
        out.append("colors ").append(distinct.size());

        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        img.setRGB(0, 0, width, height, canvas, 0, width);
        ImageIO.write(img, "png", new File("out.png"));

        System.out.print(out);
    }
}

import * as fs from 'fs';
import * as path from 'path';

interface Shape {
  type: string;
  x?: number; y?: number; w?: number; h?: number;
  cx?: number; cy?: number; r?: number;
  points?: number[][];
  x1?: number; y1?: number; x2?: number; y2?: number;
  color: number[];
}

interface Scene {
  width: number;
  height: number;
  background: number[];
  shapes: Shape[];
}

const scenePath = path.join(process.argv[2], 'scene.json');
const scene: Scene = JSON.parse(fs.readFileSync(scenePath, 'utf8'));
const W = scene.width, H = scene.height;

// canvas as Uint8Array RGB
const canvas = new Uint8Array(W * H * 3);
for (let i = 0; i < W * H; i++) {
  canvas[i * 3] = scene.background[0];
  canvas[i * 3 + 1] = scene.background[1];
  canvas[i * 3 + 2] = scene.background[2];
}

function covers(s: Shape, x: number, y: number): boolean {
  if (s.type === 'rect') {
    return x >= s.x! && x < s.x! + s.w! && y >= s.y! && y < s.y! + s.h!;
  } else if (s.type === 'circle') {
    const dx = x - s.cx!, dy = y - s.cy!;
    return dx * dx + dy * dy <= s.r! * s.r!;
  } else if (s.type === 'triangle') {
    const p = s.points!;
    let allPos = true, allNeg = true;
    for (let i = 0; i < 3; i++) {
      const j = (i + 1) % 3;
      const xi = p[i][0], yi = p[i][1];
      const xj = p[j][0], yj = p[j][1];
      const e = (xj - xi) * (y - yi) - (yj - yi) * (x - xi);
      if (e < 0) allPos = false;
      if (e > 0) allNeg = false;
    }
    return allPos || allNeg;
  } else { // line
    const x1 = s.x1!, y1 = s.y1!, x2 = s.x2!, y2 = s.y2!, r = s.r!;
    const dx = x2 - x1, dy = y2 - y1;
    const L = dx * dx + dy * dy;
    const t = (x - x1) * dx + (y - y1) * dy;
    if (t <= 0) {
      const ddx = x - x1, ddy = y - y1;
      return ddx * ddx + ddy * ddy <= r * r;
    } else if (t >= L) {
      const ddx = x - x2, ddy = y - y2;
      return ddx * ddx + ddy * ddy <= r * r;
    } else {
      const c = (x - x1) * dy - (y - y1) * dx;
      return c * c <= r * r * L;
    }
  }
}

