}

// zlib with stored deflate blocks
function zlibStored(data: Buffer): Buffer {
  const out: Buffer[] = [Buffer.from([0x78, 0x01])];
  let off = 0;
  while (off < data.length) {
    const n = Math.min(65535, data.length - off);
    const last = off + n >= data.length ? 1 : 0;
    const header = Buffer.alloc(5);
    header[0] = last;
    header.writeUInt16LE(n, 1);
    header.writeUInt16LE(~n & 0xffff, 3);
    out.push(header, data.subarray(off, off + n));
    off += n;
  }
  // adler32
  let a = 1, b = 0;
  for (let i = 0; i < data.length; i++) {
    a = (a + data[i]) % 65521;
    b = (b + a) % 65521;
  }
  const adler = Buffer.alloc(4);
  adler.writeUInt32BE(((b << 16) | a) >>> 0, 0);
  out.push(adler);
  return Buffer.concat(out);
}

