                    let tg = Int(t[2]) << 8 | Int(t[3])
                    let tb = Int(t[4]) << 8 | Int(t[5])
                    if tr == r0 && tg == g0 && tb == b0 { a8 = 0 }
                }
            case 3:
                let pi = sample(row, x, 0)
                if let p = plte, (pi + 1) * 3 <= p.count {
                    r8 = Int(p[3 * pi]); g8 = Int(p[3 * pi + 1]); b8 = Int(p[3 * pi + 2])
                }
                a8 = pi < (trns?.count ?? 0) ? Int(trns![pi]) : 255
            case 4:
                let g = to8(sample(row, x, 0))
                let a = to8(sample(row, x, 1))
                r8 = g; g8 = g; b8 = g; a8 = a
            case 6:
                r8 = to8(sample(row, x, 0))
                g8 = to8(sample(row, x, 1))
                b8 = to8(sample(row, x, 2))
                a8 = to8(sample(row, x, 3))
            default:
                break
            }
            rgba[idx] = UInt8(r8); rgba[idx + 1] = UInt8(g8)
            rgba[idx + 2] = UInt8(b8); rgba[idx + 3] = UInt8(a8)
            idx += 4
        }
    }

    var sr = 0, sg = 0, sb = 0, sa = 0
    var q = 0
    while q + 3 < rgba.count {
        sr += Int(rgba[q]); sg += Int(rgba[q + 1])
        sb += Int(rgba[q + 2]); sa += Int(rgba[q + 3])
        q += 4
    }
    let rcrc = crc32(rgba)
    result += String(format: "rgba sum=%d,%d,%d,%d crc32=%08x", sr, sg, sb, sa, rcrc) + "\n"
    return result
}

