import Foundation

// ---------- CRC-32 ----------
let crcTable: [UInt32] = {
    var t = [UInt32](repeating: 0, count: 256)
    for n in 0..<256 {
        var c = UInt32(n)
        for _ in 0..<8 {
            c = (c & 1) != 0 ? 0xEDB88320 ^ (c >> 1) : c >> 1
        }
        t[n] = c
    }
    return t
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data {
        c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8)
    }
    return c ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

// ---------- PNG writing ----------
func chunk(_ type: String, _ data: [UInt8]) -> [UInt8] {
    var out: [UInt8] = []
    let len = UInt32(data.count).bigEndian
    withUnsafeBytes(of: len) { out.append(contentsOf: $0) }
    let typeBytes = Array(type.utf8)
    out.append(contentsOf: typeBytes)
    out.append(contentsOf: data)
    var crcInput = typeBytes
    crcInput.append(contentsOf: data)
    let crc = crc32(crcInput).bigEndian
    withUnsafeBytes(of: crc) { out.append(contentsOf: $0) }
    return out
}

func writePNG(width: Int, height: Int, pixels: [UInt8], path: String) {
    var ihdr: [UInt8] = []
    withUnsafeBytes(of: UInt32(width).bigEndian) { ihdr.append(contentsOf: $0) }
    withUnsafeBytes(of: UInt32(height).bigEndian) { ihdr.append(contentsOf: $0) }
    ihdr.append(contentsOf: [8, 2, 0, 0, 0])

    // raw scanlines with filter byte 0
    var raw: [UInt8] = []
    raw.reserveCapacity(height * (1 + width * 3))
    for y in 0..<height {
        raw.append(0)
        let rowStart = y * width * 3
        raw.append(contentsOf: pixels[rowStart..<(rowStart + width * 3)])
    }

    // zlib stream with stored deflate blocks
    var idat: [UInt8] = [0x78, 0x01]
    var offset = 0
    while offset < raw.count {
        let n = min(65535, raw.count - offset)
        let isLast = (offset + n) >= raw.count
        idat.append(isLast ? 1 : 0)
        let len = UInt16(n)
        idat.append(UInt8(len & 0xFF))
        idat.append(UInt8((len >> 8) & 0xFF))
        idat.append(UInt8(~len & 0xFF))
        idat.append(UInt8((~len >> 8) & 0xFF))
        idat.append(contentsOf: raw[offset..<(offset + n)])
        offset += n
    }
    let ad = adler32(raw).bigEndian
    withUnsafeBytes(of: ad) { idat.append(contentsOf: $0) }

    var png: [UInt8] = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]
    png.append(contentsOf: chunk("IHDR", ihdr))
    png.append(contentsOf: chunk("IDAT", idat))
    png.append(contentsOf: chunk("IEND", []))

    let data = Data(png)
    try? data.write(to: URL(fileURLWithPath: path))
}

