let width = (scene["width"] as! NSNumber).intValue
let height = (scene["height"] as! NSNumber).intValue
let bg = getColor(scene, "background", 3)
let shapes = scene["shapes"] as! [[String: Any]]

var canvas = [UInt8](repeating: 0, count: width * height * 3)
for y in 0..<height {
    for x in 0..<width {
        let i = (y * width + x) * 3
        canvas[i] = UInt8(bg[0]); canvas[i+1] = UInt8(bg[1]); canvas[i+2] = UInt8(bg[2])
    }
}

var output = ""

for (idx, shape) in shapes.enumerated() {
    let type = shape["type"] as! String
    let color = getColor(shape, "color", 4)
    let (sR, sG, sB, A) = (color[0], color[1], color[2], color[3])

    var covered = 0

    func blendAt(_ x: Int, _ y: Int) {
        covered += 1
        if A == 0 { return }
        let i = (y * width + x) * 3
        let dR = Int(canvas[i]), dG = Int(canvas[i+1]), dB = Int(canvas[i+2])
        canvas[i]   = UInt8((sR * A + dR * (255 - A) + 127) / 255)
        canvas[i+1] = UInt8((sG * A + dG * (255 - A) + 127) / 255)
        canvas[i+2] = UInt8((sB * A + dB * (255 - A) + 127) / 255)
    }

    switch type {
    case "rect":
        let rx = getInt(shape, "x"), ry = getInt(shape, "y")
        let w = getInt(shape, "w"), h = getInt(shape, "h")
        let x0 = max(rx, 0), x1 = min(rx + w, width)
        let y0 = max(ry, 0), y1 = min(ry + h, height)
        for y in y0..<y1 { for x in x0..<x1 { blendAt(x, y) } }

    case "circle":
        let cx = getInt(shape, "cx"), cy = getInt(shape, "cy")
        let r = getInt(shape, "r")
        let r2 = Int64(r) * Int64(r)
        let x0 = max(cx - r, 0), x1 = min(cx + r, width - 1)
        let y0 = max(cy - r, 0), y1 = min(cy + r, height - 1)
        for y in y0...max(y0, y1) {
            for x in x0...max(x0, x1) {
                let dx = Int64(x - cx), dy = Int64(y - cy)
                if dx*dx + dy*dy <= r2 { blendAt(x, y) }
            }
        }

    case "triangle":
        let pts = shape["points"] as! [[NSNumber]]
        let p = (0..<3).map { (pts[$0][0].intValue, pts[$0][1].intValue) }
        // bounding box
        let minX = min(p[0].0, p[1].0, p[2].0)
        let maxX = max(p[0].0, p[1].0, p[2].0)
        let minY = min(p[0].1, p[1].1, p[2].1)
        let maxY = max(p[0].1, p[1].1, p[2].1)
        let x0 = max(minX, 0), x1 = min(maxX, width - 1)
        let y0 = max(minY, 0), y1 = min(maxY, height - 1)
        guard x0 <= x1 && y0 <= y1 else { break }
        for y in y0...y1 {
            for x in x0...x1 {
                var allPos = true, allNeg = true
                for i in 0..<3 {
                    let j = (i + 1) % 3
                    let xi = p[i].0, yi = p[i].1
                    let xj = p[j].0, yj = p[j].1
                    let e = Int64(xj - xi) * Int64(y - yi) - Int64(yj - yi) * Int64(x - xi)
                    if e < 0 { allPos = false }
                    if e > 0 { allNeg = false }
                }
                if allPos || allNeg { blendAt(x, y) }
            }
        }

    case "line":
        let x1 = getInt(shape, "x1"), y1 = getInt(shape, "y1")
        let x2 = getInt(shape, "x2"), y2 = getInt(shape, "y2")
        let r = getInt(shape, "r")
        let dx = Int64(x2 - x1), dy = Int64(y2 - y1)
        let L = dx*dx + dy*dy
        let r2 = Int64(r) * Int64(r)
        // bounding box: segment endpoints expanded by r
        let bx0 = max(min(x1, x2) - r, 0), bx1 = min(max(x1, x2) + r, width - 1)
        let by0 = max(min(y1, y2) - r, 0), by1 = min(max(y1, y2) + r, height - 1)
        guard bx0 <= bx1 && by0 <= by1 else { break }
        for y in by0...by1 {
            for x in bx0...bx1 {
                let px = Int64(x), py = Int64(y)
                let t = (px - Int64(x1)) * dx + (py - Int64(y1)) * dy
                var inside = false
                if t <= 0 {
                    let ex = px - Int64(x1), ey = py - Int64(y1)
                    inside = ex*ex + ey*ey <= r2
                } else if t >= L {
                    let ex = px - Int64(x2), ey = py - Int64(y2)
                    inside = ex*ex + ey*ey <= r2
                } else {
                    let c = (px - Int64(x1)) * dy - (py - Int64(y1)) * dx
                    inside = c*c <= r2 * L
                }
                if inside { blendAt(x, y) }
            }
        }

    default: break
    }

    output += "\(idx + 1) \(type) \(covered)\n"
}

// distinct colors
var colorSet = Set<UInt32>()
for i in stride(from: 0, to: canvas.count, by: 3) {
    let c = (UInt32(canvas[i]) << 16) | (UInt32(canvas[i+1]) << 8) | UInt32(canvas[i+2])
    colorSet.insert(c)
}
output += "colors \(colorSet.count)\n"

print(output.trimmingCharacters(in: CharacterSet(charactersIn: "\n")))

writePNG(width: width, height: height, pixels: canvas, path: "out.png")

