    // ---------- bit reader over the zlib stream ----------
    static byte[] zin;
    static int zpos, zbitbuf, zbitcnt;

    static int getBits(int n) {
        while (zbitcnt < n) {
            zbitbuf |= (zin[zpos++] & 0xff) << zbitcnt;
            zbitcnt += 8;
        }
        int v = zbitbuf & ((1 << n) - 1);
        zbitbuf >>>= n;
        zbitcnt -= n;
        return v;
    }

    // ---------- Huffman ----------
    static int[] construct(int[] lengths, int[] counts) {
        Arrays.fill(counts, 0);
        for (int l : lengths) counts[l]++;
        counts[0] = 0;
        int[] offs = new int[16];
        for (int i = 1; i < 15; i++) offs[i + 1] = offs[i] + counts[i];
        int[] syms = new int[lengths.length];
        for (int s = 0; s < lengths.length; s++)
            if (lengths[s] != 0) syms[offs[lengths[s]]++] = s;
        return syms;
    }

    static int decode(int[] counts, int[] syms) {
        int code = 0, first = 0, index = 0;
        for (int len = 1; len < 16; len++) {
            code |= getBits(1);
            int count = counts[len];
            if (code - first < count) return syms[index + code - first];
            index += count;
            first = (first + count) << 1;
            code <<= 1;
        }
        throw new RuntimeException("bad huffman code");
    }

