        for (int i = 144; i < 256; i++) l[i] = 9;
        for (int i = 256; i < 280; i++) l[i] = 7;
        for (int i = 280; i < 288; i++) l[i] = 8;
        fixedLitSyms = construct(l, fixedLitCounts);
        int[] d = new int[30];
