        fixedDistSyms = construct(d, fixedDistCounts);
    }

    static byte[] obuf;
    static int olen;
    static int[] blockCounts = new int[3];

    static void emit(byte b) {
        if (olen == obuf.length) obuf = Arrays.copyOf(obuf, obuf.length * 2);
