                } else {
                    int hlit = getBits(5) + 257;
                    int hdist = getBits(5) + 1;
                    int hclen = getBits(4) + 4;
                    int[] ORDER = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
                    int[] clLens = new int[19];
                    for (int i = 0; i < hclen; i++) clLens[ORDER[i]] = getBits(3);
                    int[] clCounts = new int[16];
                    int[] clSyms = construct(clLens, clCounts);
                    int[] lens = new int[hlit + hdist];
                    int i = 0;
                    while (i < lens.length) {
                        int sym = decode(clCounts, clSyms);
                        if (sym < 16) lens[i++] = sym;
                        else if (sym == 16) {
                            int p = lens[i - 1];
                            int r = 3 + getBits(2);
                            while (r-- > 0 && i < lens.length) lens[i++] = p;
                        } else if (sym == 17) {
                            int r = 3 + getBits(3);
                            while (r-- > 0 && i < lens.length) lens[i++] = 0;
                        } else {
                            int r = 11 + getBits(7);
                            while (r-- > 0 && i < lens.length) lens[i++] = 0;
                        }
                    }
                    litC = new int[16];
                    litS = construct(Arrays.copyOf(lens, hlit), litC);
                    distC = new int[16];
                    distS = construct(Arrays.copyOfRange(lens, hlit, lens.length), distC);
                }
                while (true) {
                    int sym = decode(litC, litS);
                    if (sym < 256) emit((byte) sym);
                    else if (sym == 256) break;
                    else {
                        int len = LBASE[sym - 257] + getBits(LEXT[sym - 257]);
                        int dsym = decode(distC, distS);
                        int dist = DBASE[dsym] + getBits(DEXT[dsym]);
                        for (int k = 0; k < len; k++) emit(obuf[olen - dist]);
                    }
                }
            }
            if (bfinal == 1) break;
        }
