    }

    static int convGray(int v, int depth) {
        if (depth == 16) return v >> 8;
        if (depth == 8) return v;
        return v * 255 / ((1 << depth) - 1);
    }

    static int conv8(int v, int depth) {
        return depth == 16 ? v >> 8 : v;
    }

    // ---------- per-file processing ----------
