        int channels = colorType == 2 ? 3 : colorType == 6 ? 4 : colorType == 4 ? 2 : 1;
        int bpp = Math.max(1, (channels * depth + 7) / 8);
        int rowBytes = (width * channels * depth + 7) / 8;
