                            let j = (i + 1) % 3;
                            let xi = tpx[i];
                            let yi = tpy[i];
                            let xj = tpx[j];
                            let yj = tpy[j];
                            es[i] = (xj - xi) * (y - yi) - (yj - yi) * (x - xi);
                        }
                        (es[0] >= 0 && es[1] >= 0 && es[2] >= 0)
                            || (es[0] <= 0 && es[1] <= 0 && es[2] <= 0)
                    }
                    "line" => {
                        let dx = bx - ax;
                        let dy = by - ay;
                        let l = dx * dx + dy * dy;
                        let t = (x - ax) * dx + (y - ay) * dy;
                        if t <= 0 {
                            let ddx = x - ax;
                            let ddy = y - ay;
                            ddx * ddx + ddy * ddy <= lr * lr
                        } else if t >= l {
                            let ddx = x - bx;
                            let ddy = y - by;
                            ddx * ddx + ddy * ddy <= lr * lr
                        } else {
                            let c = (x - ax) * dy - (y - ay) * dx;
                            c * c <= lr * lr * l
                        }
                    }
                    _ => false,
                };
                if covered {
                    count += 1;
                    let px = &mut canvas[y as usize * width + x as usize];
                    for c in 0..3 {
                        let s = [sr, sg, sb][c];
                        let d = px[c] as i64;
                        px[c] = ((s * sa + d * (255 - sa) + 127) / 255) as u8;
                    }
                }
            }
        }
        out_lines.push(format!("{} {} {}", idx + 1, typ, count));
    }

    let mut colors: HashSet<u32> = HashSet::new();
    for px in &canvas {
        colors.insert(((px[0] as u32) << 16) | ((px[1] as u32) << 8) | px[2] as u32);
    }
    out_lines.push(format!("colors {}", colors.len()));

    // Build PNG
    let mut png: Vec<u8> = Vec::new();
    png.extend_from_slice(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]);
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&(width as u32).to_be_bytes());
    ihdr.extend_from_slice(&(height as u32).to_be_bytes());
    ihdr.push(8); // bit depth
    ihdr.push(2); // RGB
    ihdr.push(0); // compression
    ihdr.push(0); // filter
    ihdr.push(0); // interlace
    chunk(&mut png, b"IHDR", &ihdr);

    // raw scanlines with filter 0
    let mut raw = Vec::with_capacity(height * (width * 3 + 1));
    for y in 0..height {
        raw.push(0u8);
        for x in 0..width {
            let px = &canvas[y * width + x];
            raw.extend_from_slice(px);
        }
    }

    // zlib with stored deflate blocks
    let mut idat = Vec::new();
    idat.push(0x78);
    idat.push(0x01);
    let mut off = 0usize;
    while off < raw.len() {
        let n = (raw.len() - off).min(65535);
        let last = off + n >= raw.len();
        idat.push(if last { 1 } else { 0 });
        idat.extend_from_slice(&(n as u16).to_le_bytes());
        idat.extend_from_slice(&(!(n as u16)).to_le_bytes());
        idat.extend_from_slice(&raw[off..off + n]);
        off += n;
    }
    idat.extend_from_slice(&adler32(&raw).to_be_bytes());
    chunk(&mut png, b"IDAT", &idat);
    chunk(&mut png, b"IEND", &[]);

    fs::write("out.png", &png).unwrap();

    let mut stdout = std::io::stdout();
    let mut buf = String::new();
    for l in &out_lines {
        buf.push_str(l);
        buf.push('\n');
    }
    stdout.write_all(buf.as_bytes()).unwrap();
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
  enum K {I32,I64,U32,U64,S32,S64,BOOL,STR,BYTES,F32,SF32,F64,SF64,MSG,ENUM,MAP}

  static class FieldDef {
    int num; String name; String json; K kind; String typeName;
    boolean repeated, optional; int oneof = -1;
    MessageType msgType; EnumType enumType;
    K keyKind; FieldDef keyDef, valDef; String valTypeName;
  }

  static class MessageType {
    String name;
    TreeMap<Integer,FieldDef> byNum = new TreeMap<>();
    List<List<Integer>> oneofs = new ArrayList<>();
    MessageType(String n){name=n;}
  }

  static class EnumType { Map<Long,String> names = new HashMap<>(); }

  static class Node {
    MessageType t; TreeMap<Integer,Object> data = new TreeMap<>();
    Node(MessageType t){this.t=t;}
  }

  static class Cur { byte[] b; int p; Cur(byte[] b,int p){this.b=b;this.p=p;} }

  static Map<String,MessageType> messages = new HashMap<>();
  static Map<String,EnumType> enums = new HashMap<>();
  static MessageType root;

  static K kindOf(String s){
    switch(s){
      case "int32": return K.I32; case "int64": return K.I64;
      case "uint32": return K.U32; case "uint64": return K.U64;
      case "sint32": return K.S32; case "sint64": return K.S64;
      case "bool": return K.BOOL; case "string": return K.STR;
      case "bytes": return K.BYTES; case "fixed32": return K.F32;
      case "fixed64": return K.F64; case "sfixed32": return K.SF32;
      case "sfixed64": return K.SF64;
    }
    return null;
  }

  static boolean packable(K k){
    return k!=K.STR && k!=K.BYTES && k!=K.MSG && k!=K.MAP;
  }

  static boolean is64(K k){ return k==K.I64||k==K.U64||k==K.S64||k==K.F64||k==K.SF64; }

  // ---------- lexer ----------
  static List<String> lex(String s){
    List<String> out = new ArrayList<>();
    int i=0, n=s.length();
    while(i<n){
      char c=s.charAt(i);
      if(c=='\uFEFF'){ i++; }
      else if(c=='/'&&i+1<n&&s.charAt(i+1)=='/'){ while(i<n&&s.charAt(i)!='\n')i++; }
      else if(c=='/'&&i+1<n&&s.charAt(i+1)=='*'){ i+=2; while(i+1<n&&!(s.charAt(i)=='*'&&s.charAt(i+1)=='/'))i++; i+=2; }
      else if(Character.isWhitespace(c)) i++;
      else if(c=='"'){ int j=i+1; while(j<n&&s.charAt(j)!='"')j++; out.add(s.substring(i,j+1)); i=j+1; }
      else if(c=='-'&&i+1<n&&Character.isDigit(s.charAt(i+1))){ int j=i+1; while(j<n&&Character.isDigit(s.charAt(j)))j++; out.add(s.substring(i,j)); i=j; }
      else if(Character.isLetterOrDigit(c)||c=='_'){ int j=i; while(j<n&&(Character.isLetterOrDigit(s.charAt(j))||s.charAt(j)=='_'))j++; out.add(s.substring(i,j)); i=j; }
      else { out.add(String.valueOf(c)); i++; }
    }
    return out;
  }

  static int ti; static List<String> toks;
  static String pk(){ return toks.get(ti); }
  static String nx(){ return toks.get(ti++); }
  static void expect(String x){ if(!nx().equals(x)) throw new RuntimeException("parse error: expected "+x); }
  static void skipTo(String x){ while(!nx().equals(x)){} }
  static void skipToSemi(){ while(!nx().equals(";")){} }

  static String jsonName(String s){
    StringBuilder sb=new StringBuilder();
    for(int i=0;i<s.length();i++){
      char c=s.charAt(i);
      if(c=='_'){
        if(i+1<s.length()){ char d=s.charAt(i+1); if(d>='a'&&d<='z'){ sb.append((char)(d-32)); i++; } }
      } else sb.append(c);
    }
    return sb.toString();
  }

  static FieldDef parseField(MessageType m, boolean inOneof){
    FieldDef f=new FieldDef();
    if(!inOneof){
      if(pk().equals("repeated")){ f.repeated=true; nx(); }
      else if(pk().equals("optional")){ f.optional=true; nx(); }
    }
    String ty=nx();
    if(ty.equals("map")&&pk().equals("<")){
      nx(); f.kind=K.MAP; f.typeName=nx(); f.keyKind=kindOf(f.typeName);
      expect(","); f.valTypeName=nx(); expect(">");
    } else f.typeName=ty;
    f.name=nx(); expect("="); f.num=Integer.parseInt(nx());
    if(pk().equals("[")) skipTo("]");
    expect(";");
    f.json=jsonName(f.name);
    m.byNum.put(f.num,f);
    return f;
  }

  static MessageType parseMsg(){
    String name=nx(); MessageType m=new MessageType(name); messages.put(name,m);
    expect("{");
    while(!pk().equals("}")){
      String t=pk();
      if(t.equals("message")){ nx(); parseMsg(); }
      else if(t.equals("enum")){ nx(); parseEnum(); }
      else if(t.equals("option")||t.equals("reserved")){ skipToSemi(); }
      else if(t.equals("oneof")){
        nx(); nx(); expect("{");
        int oi=m.oneofs.size(); List<Integer> l=new ArrayList<>(); m.oneofs.add(l);
        while(!pk().equals("}")){ FieldDef f=parseField(m,true); f.oneof=oi; l.add(f.num); }
        nx();
      }
      else parseField(m,false);
    }
    nx();
    return m;
  }

  static void parseEnum(){
    String name=nx(); EnumType e=new EnumType(); enums.put(name,e);
    expect("{");
    while(!pk().equals("}")){
      if(pk().equals("option")||pk().equals("reserved")){ skipToSemi(); continue; }
      String vn=nx(); expect("="); long v=Long.parseLong(nx());
      if(pk().equals("[")) skipTo("]");
      expect(";");
      e.names.put(v,vn);
    }
    nx();
  }

  static void resolve(){
    for(MessageType m : messages.values()){
      for(FieldDef f : m.byNum.values()){
        if(f.kind==K.MAP){
          f.keyDef=new FieldDef(); f.keyDef.kind=f.keyKind; f.keyDef.json="";
          f.valDef=new FieldDef();
          K vk=kindOf(f.valTypeName);
          if(vk!=null) f.valDef.kind=vk;
          else if(messages.containsKey(f.valTypeName)){ f.valDef.kind=K.MSG; f.valDef.msgType=messages.get(f.valTypeName); }
          else { f.valDef.kind=K.ENUM; f.valDef.enumType=enums.get(f.valTypeName); }
        } else {
          f.kind=kindOf(f.typeName);
          if(f.kind==null){
            if(messages.containsKey(f.typeName)){ f.kind=K.MSG; f.msgType=messages.get(f.typeName); }
            else { f.kind=K.ENUM; f.enumType=enums.get(f.typeName); }
          }
        }
      }
    }
  }

  // ---------- wire decoding ----------
  static long varint(Cur c){
    long r=0; int sh=0;
    while(true){
      int b=c.b[c.p++]&0xff;
      r|=(long)(b&0x7f)<<sh;
      if((b&0x80)==0) return r;
      sh+=7;
    }
  }

  static long read4(Cur c){ long v=0; for(int i=0;i<4;i++) v|=(c.b[c.p++]&0xffL)<<(8*i); return v; }
  static long read8(Cur c){ long v=0; for(int i=0;i<8;i++) v|=(c.b[c.p++]&0xffL)<<(8*i); return v; }

  static Object readScalar(FieldDef f, Cur c){
    switch(f.kind){
      case I32: return (long)(int)varint(c);
      case I64: return varint(c);
      case U32: return varint(c)&0xffffffffL;
      case U64: return varint(c);
      case S32: { int v=(int)varint(c); return (long)((v>>>1)^-(v&1)); }
      case S64: { long v=varint(c); return (v>>>1)^-(v&1); }
      case BOOL: return varint(c)!=0;
      case F32: return read4(c)&0xffffffffL;
      case SF32: return (long)(int)read4(c);
      case F64: case SF64: return read8(c);
      case STR: { int len=(int)varint(c); String s=new String(c.b,c.p,len,StandardCharsets.UTF_8); c.p+=len; return s; }
      case BYTES: { int len=(int)varint(c); byte[] b=Arrays.copyOfRange(c.b,c.p,c.p+len); c.p+=len; return b; }
      case ENUM: return (long)(int)varint(c);
    }
    throw new RuntimeException();
  }

  static void skipField(Cur c,int wt,int fn){
    switch(wt){
      case 0: varint(c); break;
      case 1: c.p+=8; break;
      case 5: c.p+=4; break;
      case 2: { int len=(int)varint(c); c.p+=len; break; }
      case 3: { while(true){ long k=varint(c); int f2=(int)(k>>>3), w2=(int)(k&7); if(w2==4) break; skipField(c,w2,f2);} break; }
      default: break;
    }
  }

  @SuppressWarnings("unchecked")
  static List<Object> getList(Node n, FieldDef f){
    return (List<Object>) n.data.computeIfAbsent(f.num, k->new ArrayList<>());
  }

  static void clearOthers(Node node, FieldDef f){
    for(int g : node.t.oneofs.get(f.oneof)) if(g!=f.num) node.data.remove(g);
  }

  static Object defaultVal(FieldDef v){
    switch(v.kind){
      case MSG: return new Node(v.msgType);
      case ENUM: return 0L;
      case BOOL: return Boolean.FALSE;
      case STR: return "";
      case BYTES: return new byte[0];
      default: return 0L;
    }
  }

  static void decodeMapEntry(Node node, FieldDef f, byte[] b, int s, int e){
    Cur c=new Cur(b,s);
    Object key = f.keyKind==K.STR ? "" : 0L;
    Object val = defaultVal(f.valDef);
    while(c.p<e){
      long k=varint(c); int fn=(int)(k>>>3), wt=(int)(k&7);
      if(fn==1){ key=readScalar(f.keyDef,c); }
      else if(fn==2){
        if(f.valDef.kind==K.MSG){
          int len=(int)varint(c); int st=c.p; c.p+=len;
          Node n=new Node(f.valDef.msgType); decode(n,b,st,c.p); val=n;
        } else val=readScalar(f.valDef,c);
      } else skipField(c,wt,fn);
    }
    @SuppressWarnings("unchecked")
    Map<Object,Object> m=(Map<Object,Object>) node.data.computeIfAbsent(f.num, x->new LinkedHashMap<>());
    m.put(key,val);
  }

  static void decode(Node node, byte[] b, int start, int end){
    Cur c=new Cur(b,start);
    while(c.p<end){
      long key=varint(c); int fn=(int)(key>>>3), wt=(int)(key&7);
      FieldDef f=node.t.byNum.get(fn);
      if(f==null){ skipField(c,wt,fn); continue; }
      switch(f.kind){
        case MAP: {
          int len=(int)varint(c); int s=c.p; c.p+=len;
          decodeMapEntry(node,f,b,s,c.p);
          break;
        }
        case MSG: {
          int len=(int)varint(c); int s=c.p; c.p+=len;
          if(f.repeated){
            Node n=new Node(f.msgType); decode(n,b,s,c.p);
            getList(node,f).add(n);
          } else {
            if(f.oneof>=0) clearOthers(node,f);
            Object ex=node.data.get(f.num);
            Node n;
            if(ex instanceof Node) n=(Node)ex;
            else { n=new Node(f.msgType); node.data.put(f.num,n); }
            decode(n,b,s,c.p);
          }
          break;
        }
        default: {
          if(f.repeated && wt==2 && packable(f.kind)){
            int len=(int)varint(c); int e2=c.p+len;
            List<Object> l=getList(node,f);
            while(c.p<e2) l.add(readScalar(f,c));
          } else if(f.repeated){
            getList(node,f).add(readScalar(f,c));
          } else {
            if(f.oneof>=0) clearOthers(node,f);
            node.data.put(f.num, readScalar(f,c));
          }
        }
      }
    }
  }

  static void merge(Node dst, Node src){
    for(Map.Entry<Integer,Object> e : src.data.entrySet()){
      FieldDef f=src.t.byNum.get(e.getKey());
      Object v=e.getValue();
      if(f.kind==K.MSG && !f.repeated){
        Object ex=dst.data.get(e.getKey());
        if(ex instanceof Node) merge((Node)ex,(Node)v);
        else dst.data.put(e.getKey(),v);
      } else if(f.repeated){
        @SuppressWarnings("unchecked")
        List<Object> l=(List<Object>) dst.data.computeIfAbsent(e.getKey(), k->new ArrayList<>());
        l.addAll((List<Object>)v);
      } else if(f.kind==K.MAP){
        @SuppressWarnings("unchecked")
        Map<Object,Object> m=(Map<Object,Object>) dst.data.computeIfAbsent(e.getKey(), k->new LinkedHashMap<>());
        m.putAll((Map<Object,Object>)v);
      } else dst.data.put(e.getKey(),v);
    }
  }

  // ---------- JSON output ----------
  static boolean isDefault(FieldDef f, Object v){
    switch(f.kind){
      case BOOL: return !((Boolean)v);
      case STR: return ((String)v).isEmpty();
      case BYTES: return ((byte[])v).length==0;
      default: return (Long)v==0L;
    }
  }

  static void writeStr(StringBuilder sb, String s){
    sb.append('"');
    for(int i=0;i<s.length();i++){
      char ch=s.charAt(i);
      switch(ch){
        case '"': sb.append("\\\""); break;
        case '\\': sb.append("\\\\"); break;
        case '\b': sb.append("\\b"); break;
        case '\t': sb.append("\\t"); break;
        case '\n': sb.append("\\n"); break;
        case '\f': sb.append("\\f"); break;
        case '\r': sb.append("\\r"); break;
        default:
          if(ch<0x20) sb.append(String.format("\\u%04x",(int)ch));
          else sb.append(ch);
      }
    }
    sb.append('"');
  }

  static void writeValue(StringBuilder sb, FieldDef f, Object v){
    switch(f.kind){
      case MSG: writeNode(sb,(Node)v); break;
      case MAP: writeMap(sb,f,v); break;
      case STR: writeStr(sb,(String)v); break;
      case BYTES: sb.append('"').append(Base64.getEncoder().encodeToString((byte[])v)).append('"'); break;
      case BOOL: sb.append(v); break;
      case ENUM: {
        long n=(Long)v; String nm=f.enumType.names.get(n);
        if(nm!=null) writeStr(sb,nm); else sb.append(n);
        break;
      }
      default: {
        long n=(Long)v;
        if(f.kind==K.I64||f.kind==K.SF64){ sb.append('"').append(n).append('"'); }
        else if(f.kind==K.U64||f.kind==K.F64){ sb.append('"').append(Long.toUnsignedString(n)).append('"'); }
        else sb.append(n);
      }
    }
  }

  @SuppressWarnings("unchecked")
  static void writeMap(StringBuilder sb, FieldDef f, Object mv){
    LinkedHashMap<Object,Object> m=(LinkedHashMap<Object,Object>)mv;
    sb.append('{');
    List<Object> keys=new ArrayList<>(m.keySet());
    if(f.keyKind==K.STR){
      keys.sort((a,b)->Arrays.compareUnsigned(
        ((String)a).getBytes(StandardCharsets.UTF_8),
        ((String)b).getBytes(StandardCharsets.UTF_8)));
    } else {
      keys.sort((a,b)->Long.compare((Long)a,(Long)b));
    }
    boolean first=true;
    for(Object k : keys){
      if(!first) sb.append(',');
      first=false;
      String ks = (f.keyKind==K.STR) ? (String)k : String.valueOf((Long)k);
      writeStr(sb,ks);
      sb.append(':');
      writeValue(sb,f.valDef,m.get(k));
    }
    sb.append('}');
  }

  static void writeNode(StringBuilder sb, Node n){
    sb.append('{');
    boolean first=true;
    for(Map.Entry<Integer,Object> en : n.data.entrySet()){
      FieldDef f=n.t.byNum.get(en.getKey());
      Object v=en.getValue();
      if(f.kind==K.MSG && !f.repeated){ }
      else if(f.kind==K.MAP){ if(((Map<?,?>)v).isEmpty()) continue; }
      else if(f.repeated){ if(((List<?>)v).isEmpty()) continue; }
      else { if(!(f.optional || f.oneof>=0 || !isDefault(f,v))) continue; }
      if(!first) sb.append(',');
      first=false;
      writeStr(sb,f.json);
      sb.append(':');
      writeValue(sb,f,v);
    }
    sb.append('}');
  }

  // ---------- main ----------
  public static void main(String[] args) throws Exception {
    String dir=args[0];
    String proto=new String(Files.readAllBytes(Paths.get(dir,"schema.proto")),StandardCharsets.UTF_8);
    toks=lex(proto); ti=0;
    while(ti<toks.size()){
      String t=pk();
      if(t.equals("message")){ nx(); MessageType m=parseMsg(); if(root==null) root=m; }
      else if(t.equals("enum")){ nx(); parseEnum(); }
      else if(t.equals("option")||t.equals("syntax")||t.equals("package")||t.equals("import")||t.equals("reserved")) skipToSemi();
      else nx();
    }
    resolve();
    byte[] bin=Files.readAllBytes(Paths.get(dir,"messages.bin"));
    Cur c=new Cur(bin,0);
    PrintStream out=new PrintStream(new BufferedOutputStream(new FileOutputStream(FileDescriptor.out)),false,"UTF-8");
    while(c.p<bin.length){
      int len=(int)varint(c);
      int end=Math.min(c.p+len,bin.length);
      Node n=new Node(root);
      decode(n,bin,c.p,end);
      c.p+=len;
      StringBuilder sb=new StringBuilder();
      writeNode(sb,n);
      out.println(sb);
    }
    out.flush();
  }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
  enum K {I32,I64,U32,U64,S32,S64,BOOL,STR,BYTES,F32,SF32,F64,SF64,MSG,ENUM,MAP}

  static class FieldDef {
    int num; String name; String json; K kind; String typeName;
    boolean repeated, optional; int oneof = -1;
    MessageType msgType; EnumType enumType;
    K keyKind; FieldDef keyDef, valDef; String valTypeName;
  }

  static class MessageType {
    String name;
    TreeMap<Integer,FieldDef> byNum = new TreeMap<>();
    List<List<Integer>> oneofs = new ArrayList<>();
    MessageType(String n){name=n;}
  }

  static class EnumType { Map<Long,String> names = new HashMap<>(); }

  static class Node {
    MessageType t; TreeMap<Integer,Object> data = new TreeMap<>();
    Node(MessageType t){this.t=t;}
  }

  static class Cur { byte[] b; int p; Cur(byte[] b,int p){this.b=b;this.p=p;} }

  static Map<String,MessageType> messages = new HashMap<>();
  static Map<String,EnumType> enums = new HashMap<>();
  static MessageType root;

  static K kindOf(String s){
    switch(s){
      case "int32": return K.I32; case "int64": return K.I64;
      case "uint32": return K.U32; case "uint64": return K.U64;
      case "sint32": return K.S32; case "sint64": return K.S64;
      case "bool": return K.BOOL; case "string": return K.STR;
      case "bytes": return K.BYTES; case "fixed32": return K.F32;
      case "fixed64": return K.F64; case "sfixed32": return K.SF32;
      case "sfixed64": return K.SF64;
    }
    return null;
  }

  static boolean packable(K k){
    return k!=K.STR && k!=K.BYTES && k!=K.MSG && k!=K.MAP;
  }

  // ---------- lexer ----------
  static List<String> lex(String s){
    List<String> out = new ArrayList<>();
