def form_encode(s: str) -> bytes:
    out = bytearray()
    for b in str(s).encode('utf-8'):
        c = chr(b)
        if (65 <= b <= 90) or (97 <= b <= 122) or (48 <= b <= 57) or c in '-._*':
            out.append(b)
        elif c == ' ':
            out.append(ord('+'))
        else:
            out += ('%%%02X' % b).encode('ascii')
    return bytes(out)

def request(base, method, path, headers=None, body=None):
    conn = http.client.HTTPConnection(base.hostname, base.port)
    try:
        conn.request(method, path, body=body, headers=headers or {})
        resp = conn.getresponse()
        data = resp.read()
        return resp.status, dict(resp.getheaders()), data
    finally:
        conn.close()

