        if label in ('repeated', 'optional'): p.next()
        ft = p.next(); fname = p.next(); p.expect('='); num = int(p.next())
        if p.peek() == '[': skip_options(p)
        p.expect(';')
        md.fields[num] = FieldDef(fname, json_name(fname), label or 'singular', ft, oneof, label == 'optional')

def parse_oneof(p, md):
    p.expect('oneof'); oname = p.next(); p.expect('{')
    while True:
        t = p.peek()
        if t == '}': p.next(); break
        if t in ('option', 'reserved'):
            p.next(); p.skip_to(';')
        elif t == ';':
            p.next()
        else:
            parse_field(p, md, None, oneof=oname)

def parse_msg(p, top):
    p.expect('message'); name = p.next(); md = MsgDef(name)
    if top: top_level_messages.append(md)
    types[name] = ('msg', md)
    p.expect('{')
    while True:
        t = p.peek()
        if t is None: break
        if t == '}': p.next(); break
        if t == ';': p.next(); continue
        if t == 'message': parse_msg(p, False)
        elif t == 'enum': parse_enum(p)
        elif t in ('option', 'reserved'): p.next(); p.skip_to(';')
        elif t == 'oneof': parse_oneof(p, md)
        else: parse_field(p, md, t if t in ('repeated', 'optional') else None)

def parse_enum(p):
    p.expect('enum'); name = p.next(); ed = EnumDef(name)
    types[name] = ('enum', ed)
    p.expect('{')
    while True:
        t = p.peek()
        if t is None: break
        if t == '}': p.next(); break
        if t == ';': p.next(); continue
        if t in ('option', 'reserved'):
            p.next(); p.skip_to(';')
        else:
            vname = p.next(); p.expect('='); num = int(p.next())
            if p.peek() == '[': skip_options(p)
            p.expect(';')
            ed.values[num] = vname

def parse_file(text):
    toks = TOKEN_RE.findall(strip_comments(text))
    p = P(toks)
    while p.peek() is not None:
        t = p.peek()
        if t == 'syntax':
            p.next(); p.expect('='); p.next(); p.expect(';')
        elif t == 'package':
            p.next()
            while p.i < len(p.t) and p.next() != ';': pass
        elif t == 'option':
            p.next(); p.skip_to(';')
        elif t == 'message':
            parse_msg(p, True)
        elif t == 'enum':
            parse_enum(p)
        else:
            p.next()

def resolve(tname):
    r = types.get(tname)
    if r is None: return ('scalar', tname)
    return r

VARINT_KINDS = {'int32', 'int64', 'uint32', 'uint64', 'sint32', 'sint64', 'bool'}
INT64_OUT = {'int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'}

def is_packable(tname):
    k = resolve(tname)
    if k[0] == 'msg': return False
    if tname in ('string', 'bytes'): return False
    return True

def read_varint(data, pos):
    result = 0; shift = 0
    while True:
        b = data[pos]; pos += 1
        result |= (b & 0x7f) << shift
        if not (b & 0x80): break
        shift += 7
    return result, pos

def to_s32(v):
    v &= 0xFFFFFFFF
    return v - (1 << 32) if v >= (1 << 31) else v

def to_s64(v):
    v &= (1 << 64) - 1
    return v - (1 << 64) if v >= (1 << 63) else v

def zz(v):
    return (v >> 1) ^ -(v & 1)

def skip_field(data, pos, wt, fnum):
    if wt == 0:
        _, pos = read_varint(data, pos)
    elif wt == 1:
        pos += 8
    elif wt == 2:
        ln, pos = read_varint(data, pos); pos += ln
    elif wt == 5:
        pos += 4
    elif wt == 3:
        while pos < len(data):
            key, pos = read_varint(data, pos)
            f2 = key >> 3; w2 = key & 7
            if w2 == 4: break
            pos = skip_field(data, pos, w2, f2)
    return pos

def read_single(tname, data, pos, wt):
    k = resolve(tname)
    if k[0] == 'enum':
        v, pos = read_varint(data, pos)
        return to_s32(v), pos
    t = tname
    if wt == 2 and t in ('string', 'bytes'):
        ln, pos = read_varint(data, pos)
        b = data[pos:pos + ln]; pos += ln
        return (b.decode('utf-8') if t == 'string' else bytes(b)), pos
    if t in VARINT_KINDS:
        v, pos = read_varint(data, pos)
        if t == 'int32': return to_s32(v), pos
        if t == 'int64': return to_s64(v), pos
        if t == 'uint32': return v & 0xFFFFFFFF, pos
        if t == 'uint64': return v & 0xFFFFFFFFFFFFFFFF, pos
        if t == 'sint32': return zz(v & 0xFFFFFFFF), pos
        if t == 'sint64': return zz(v & 0xFFFFFFFFFFFFFFFF), pos
        return (v != 0), pos
    if t == 'fixed32': return struct.unpack_from('<I', data, pos)[0], pos + 4
    if t == 'sfixed32': return struct.unpack_from('<i', data, pos)[0], pos + 4
    if t == 'fixed64': return struct.unpack_from('<Q', data, pos)[0], pos + 8
    if t == 'sfixed64': return struct.unpack_from('<q', data, pos)[0], pos + 8
    if k[0] == 'msg':
        ln, pos = read_varint(data, pos)
        return decode_message(k[1], data, pos, pos + ln), pos + ln
    raise ValueError(t)

def default_value(tname):
    k = resolve(tname)
    if k[0] == 'msg': return Msg(k[1])
    if k[0] == 'enum': return 0
    if tname == 'string': return ''
    if tname == 'bytes': return b''
    if tname == 'bool': return False
    return 0

def set_singular(msg, fd, fnum, value):
    ismsg = resolve(fd.type)[0] == 'msg'
    if fd.oneof is not None:
        cur = msg.oneof.get(fd.oneof)
        if cur != fnum:
            if cur is not None:
                del msg.fields[cur]
            msg.oneof[fd.oneof] = fnum
            msg.fields[fnum] = value
        else:
            if ismsg and fnum in msg.fields:
                merge_msg(msg.fields[fnum], value)
            else:
                msg.fields[fnum] = value
    else:
        if ismsg:
            if fnum in msg.fields:
                merge_msg(msg.fields[fnum], value)
            else:
                msg.fields[fnum] = value
        else:
            msg.fields[fnum] = value

def merge_msg(dst, src):
    for num, v in src.fields.items():
        fd = dst.md.fields[num]
        if fd.label == 'repeated':
            dst.fields.setdefault(num, []).extend(v)
        elif fd.label == 'map':
            dst.fields.setdefault(num, {}).update(v)
        else:
            set_singular(dst, fd, num, v)

def decode_message(md, data, pos, end):
    msg = Msg(md)
    while pos < end:
        key, pos = read_varint(data, pos)
        fnum = key >> 3; wt = key & 7
        fd = md.fields.get(fnum)
        if fd is None or wt in (3, 4):
            npos = skip_field(data, pos, wt, fnum)
            if npos <= pos: break
            pos = npos
            continue
        if fd.label == 'map':
            ln, pos = read_varint(data, pos)
            eend = pos + ln
            k = '' if fd.key_type == 'string' else 0
            v = default_value(fd.type)
            while pos < eend:
                k2, pos = read_varint(data, pos)
                f2 = k2 >> 3; w2 = k2 & 7
                if f2 == 1:
                    k, pos = read_single(fd.key_type, data, pos, w2)
                elif f2 == 2:
                    v, pos = read_single(fd.type, data, pos, w2)
                else:
                    pos = skip_field(data, pos, w2, f2)
            pos = eend
            msg.fields.setdefault(fnum, {})[k] = v
        elif fd.label == 'repeated':
            if is_packable(fd.type) and wt == 2:
                ln, pos = read_varint(data, pos)
                eend = pos + ln
                lst = msg.fields.setdefault(fnum, [])
                while pos < eend:
                    v, pos = read_single(fd.type, data, pos, 0)
                    lst.append(v)
                pos = eend
            else:
                v, pos = read_single(fd.type, data, pos, wt)
                msg.fields.setdefault(fnum, []).append(v)
        else:
            v, pos = read_single(fd.type, data, pos, wt)
            set_singular(msg, fd, fnum, v)
    return msg

def jstr(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\b': out.append('\\b')
        elif ch == '\t': out.append('\\t')
        elif ch == '\n': out.append('\\n')
        elif ch == '\f': out.append('\\f')
        elif ch == '\r': out.append('\\r')
        elif o < 0x20: out.append('\\u%04x' % o)
        else: out.append(ch)
    out.append('"')
    return ''.join(out)

def value_json(tname, v):
    k = resolve(tname)
    if k[0] == 'msg':
        return msg_json(k[1], v)
    if k[0] == 'enum':
        n = k[1].values.get(v)
        return '"' + n + '"' if n is not None else str(v)
    t = tname
    if t in INT64_OUT: return '"%d"' % v
    if t == 'bool': return 'true' if v else 'false'
    if t == 'string': return jstr(v)
    if t == 'bytes': return '"' + base64.b64encode(v).decode('ascii') + '"'
    return str(v)

def is_default(tname, v):
    k = resolve(tname)
    if k[0] == 'enum': return v == 0
    if tname == 'bool': return not v
    if tname == 'string': return v == ''
    if tname == 'bytes': return v == b''
    return v == 0

def msg_json(md, msg):
    parts = []
    for num in sorted(msg.fields):
        fd = md.fields[num]
        v = msg.fields[num]
        if fd.label == 'repeated':
            val = '[' + ','.join(value_json(fd.type, x) for x in v) + ']'
        elif fd.label == 'map':
            if fd.key_type == 'string':
                items = sorted(v.items(), key=lambda kv: kv[0].encode('utf-8'))
                keys = [jstr(k) for k, _ in items]
            else:
                items = sorted(v.items())
                keys = ['"%d"' % k for k, _ in items]
            vals = [value_json(fd.type, x) for _, x in items]
            val = '{' + ','.join(a + ':' + b for a, b in zip(keys, vals)) + '}'
        else:
            if not fd.optional and fd.oneof is None and is_default(fd.type, v):
                continue
            val = value_json(fd.type, v)
        parts.append(jstr(fd.jname) + ':' + val)
    return '{' + ','.join(parts) + '}'

def main():
    d = sys.argv[1]
    with open(os.path.join(d, 'schema.proto'), 'r', encoding='utf-8') as f:
        parse_file(f.read())
    root = top_level_messages[0]
    with open(os.path.join(d, 'messages.bin'), 'rb') as f:
        data = f.read()
    pos = 0
    out = []
    while pos < len(data):
        n, pos = read_varint(data, pos)
        rec = data[pos:pos + n]; pos += n
        msg = decode_message(root, rec, 0, len(rec))
        out.append(msg_json(root, msg))
    sys.stdout.write(''.join(line + '\n' for line in out))

main()

import Foundation

// ---------- global counters ----------
var R = 0, A = 0, P = 0, N = 0

func fatal(_ status: Int, _ body: [UInt8]) -> Never {
    print("ERROR \(status) \(String(decoding: body, as: UTF8.self))")
    exit(0)
}

// ---------- encoding helpers ----------
func formEncode(_ s: String) -> String {
    var out = ""
    for b in Array(s.utf8) {
        let c = Character(UnicodeScalar(b))
        if (b >= 97 && b <= 122) || (b >= 65 && b <= 90) || (b >= 48 && b <= 57) || b == 45 || b == 46 || b == 95 || b == 42 {
            out.append(c)
        } else if b == 0x20 {
            out.append("+")
        } else {
            out += String(format: "%%%02X", b)
        }
    }
    return out
}

func urlEncode(_ s: String) -> String {
    var out = ""
    for b in Array(s.utf8) {
        let c = Character(UnicodeScalar(b))
        if (b >= 97 && b <= 122) || (b >= 65 && b <= 90) || (b >= 48 && b <= 57) || b == 45 || b == 46 || b == 95 || b == 126 {
            out.append(c)
        } else {
            out += String(format: "%%%02X", b)
        }
    }
    return out
}

// ---------- socket helpers ----------
func connectSocket(host: String, port: Int) -> Int32 {
    var hints = addrinfo()
    hints.ai_family = AF_UNSPEC
    hints.ai_socktype = SOCK_STREAM
    hints.ai_protocol = IPPROTO_TCP
    var res: UnsafeMutablePointer<addrinfo>? = nil
    guard getaddrinfo(host, String(port), &hints, &res) == 0, let first = res else {
        fatalError("resolve failed")
    }
    defer { freeaddrinfo(res) }
    var p: UnsafeMutablePointer<addrinfo>? = first
    while let cur = p {
        let fd = socket(cur.pointee.ai_family, cur.pointee.ai_socktype, cur.pointee.ai_protocol)
        if fd >= 0 {
            if connect(fd, cur.pointee.ai_addr, cur.pointee.ai_addrlen) == 0 {
                return fd
            }
            close(fd)
        }
        p = cur.pointee.ai_next
    }
    fatalError("connect failed")
}

func sendAll(_ fd: Int32, _ bytes: [UInt8]) {
    var offset = 0
    bytes.withUnsafeBufferPointer { bp in
        guard let base = bp.baseAddress else { return }
        while offset < bytes.count {
            let n = write(fd, base + offset, bytes.count - offset)
            if n <= 0 { break }
            offset += n
        }
    }
}

func readAll(_ fd: Int32) -> [UInt8] {
    var data = [UInt8]()
    let bufSize = 65536
    var buf = [UInt8](repeating: 0, count: bufSize)
    while true {
        let n = read(fd, &buf, bufSize)
        if n <= 0 { break }
        data.append(contentsOf: buf[0..<n])
    }
    close(fd)
    return data
}

// ---------- HTTP ----------
func decodeChunked(_ d: [UInt8]) -> [UInt8] {
    var i = 0
    var out = [UInt8]()
    func readLine() -> String {
        let start = i
        while i < d.count && d[i] != 13 { i += 1 }
        let s = String(decoding: d[start..<i], as: UTF8.self)
        i += 2 // skip CRLF
        return s
    }
    while true {
        let line = readLine()
        let sizePart = line.split(separator: ";").first.map(String.init) ?? "0"
        let n = Int(sizePart.trimmingCharacters(in: .whitespaces), radix: 16)!
        if n == 0 { break }
        out.append(contentsOf: d[i..<i + n])
        i += n
        i += 2 // trailing CRLF after chunk data
    }
    return out
}

struct Response {
    let status: Int
    let headers: [String: String]
    let body: [UInt8]
    var bodyString: String { String(decoding: body, as: UTF8.self) }
}

func httpRequest(host: String, port: Int, method: String, path: String, headers: [String: String], body: [UInt8]?) -> Response {
    let fd = connectSocket(host: host, port: port)
    var req = "\(method) \(path) HTTP/1.1\r\nHost: \(host):\(port)\r\nConnection: close\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    if let b = body {
        req += "Content-Length: \(b.count)\r\n"
    }
    req += "\r\n"
    var bytes = Array(req.utf8)
    if let b = body { bytes += b }
    sendAll(fd, bytes)
    let raw = readAll(fd)
    let sep = Array("\r\n\r\n".utf8)
    guard let range = raw.firstRange(of: sep) else {
        fatalError("bad response")
    }
    let head = String(decoding: raw[0..<range.lowerBound], as: UTF8.self)
    var bodyBytes = Array(raw[range.upperBound...])
    let lines = head.components(separatedBy: "\r\n")
    let statusLine = lines[0].split(separator: " ")
    let status = Int(statusLine[1])!
    var headersOut = [String: String]()
    for l in lines.dropFirst() {
        if let idx = l.firstIndex(of: ":") {
            let key = l[..<idx].trimmingCharacters(in: .whitespaces).lowercased()
            let val = l[l.index(after: idx)...].trimmingCharacters(in: .whitespaces)
            headersOut[key] = val
        }
    }
    if let te = headersOut["transfer-encoding"], te.lowercased().contains("chunked") {
        bodyBytes = decodeChunked(bodyBytes)
    } else if let cl = headersOut["content-length"].flatMap({ Int($0) }) {
        if bodyBytes.count > cl { bodyBytes = Array(bodyBytes[0..<cl]) }
    }
    return Response(status: status, headers: headersOut, body: bodyBytes)
}

// ---------- main ----------
let args = CommandLine.arguments
guard args.count >= 3 else { fatalError("usage") }
let dataDir = args[1]
let baseURL = args[2]

// parse base URL
let afterScheme = baseURL.split(separator: "://", maxSplits: 1, omittingEmptySubsequences: false)[1]
let hostPortStr: String
let basePath: String
if let slashIdx = afterScheme.firstIndex(of: "/") {
    hostPortStr = String(afterScheme[..<slashIdx])
    basePath = String(afterScheme[slashIdx...])
} else {
    hostPortStr = String(afterScheme)
    basePath = ""
}
let host: String
let port: Int
if let colon = hostPortStr.lastIndex(of: ":") {
    host = String(hostPortStr[..<colon])
    port = Int(hostPortStr[colon...].dropFirst())!
} else {
    host = hostPortStr
    port = 80
}

// load client.json
let clientData = try! Data(contentsOf: URL(fileURLWithPath: dataDir + "/client.json"))
let client = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientID = client["client_id"] as! String
let clientSecret = client["client_secret"] as! String
let scope = client["scope"] as! String
let pageSize = client["page_size"] as! Int

let tokenPath = basePath + "/oauth/token"
let ordersPath = basePath + "/orders"

func getToken() -> String {
    let cred = formEncode(clientID) + ":" + formEncode(clientSecret)
    let b64 = Data(cred.utf8).base64EncodedString()
    let bodyStr = "grant_type=client_credentials&scope=" + formEncode(scope)
    let resp = httpRequest(host: host, port: port, method: "POST", path: tokenPath,
                           headers: ["Content-Type": "application/x-www-form-urlencoded",
                                     "Authorization": "Basic " + b64],
                           body: Array(bodyStr.utf8))
    if resp.status != 200 { fatal(resp.status, resp.body) }
    let obj = try! JSONSerialization.jsonObject(with: Data(resp.body)) as! [String: Any]
    return obj["access_token"] as! String
}

func cents(_ s: String) -> Int {
    var neg = false
    var t = Substring(s)
    if t.first == "-" { neg = true; t = t.dropFirst() }
    let parts = t.split(separator: ".", omittingEmptySubsequences: false)
    let ip = Int(parts[0]) ?? 0
    var fp = 0
    if parts.count > 1 {
        let f = parts[1]
        fp = Int(f) ?? 0
        if f.count == 1 { fp *= 10 }
    }
    return (neg ? -1 : 1) * (ip * 100 + fp)
}

func fmtCents(_ c: Int) -> String {
    let neg = c < 0
    let a = abs(c)
    let frac = String(a % 100)
    let pad = frac.count == 1 ? "0" + frac : frac
    return (neg ? "-" : "") + String(a / 100) + "." + pad
}

var token = getToken()
var freshToken = true
var cursor: String? = nil
var totals = [[UInt8]: [String: Int]]()   // name bytes -> currency -> cents
var statusCounts = [String: Int]()

while true {
    var q = "?limit=\(pageSize)"
    if let c = cursor { q += "&cursor=" + urlEncode(c) }
    let resp = httpRequest(host: host, port: port, method: "GET", path: ordersPath + q,
                           headers: ["Authorization": "Bearer " + token], body: nil)
    if resp.status == 429 {
        R += 1
        let secs = Int(resp.headers["retry-after"] ?? "1") ?? 1
        Thread.sleep(forTimeInterval: Double(secs))
        continue
    }
    if resp.status == 503 {
        R += 1
        Thread.sleep(forTimeInterval: 0.2)
        continue
    }
    if resp.status == 401 {
        if freshToken { fatal(resp.status, resp.body) }
        A += 1
        token = getToken()
        freshToken = true
        continue
    }
    if resp.status != 200 { fatal(resp.status, resp.body) }
    P += 1
    freshToken = false
    let obj = try! JSONSerialization.jsonObject(with: Data(resp.body)) as! [String: Any]
    if let data = obj["data"] as? [[String: Any]] {
        for order in data {
            N += 1
            let status = order["status"] as! String
            statusCounts[status, default: 0] += 1
            if status == "cancelled" { continue }
            let customer = order["customer"] as! [String: Any]
            let nameBytes = Array((customer["name"] as! String).utf8)
            let currency = order["currency"] as! String
            let amount = cents(order["amount"] as! String)
            totals[nameBytes, default: [:]][currency, default: 0] += amount
        }
    }
    if let nc = obj["next_cursor"] as? String {
        cursor = nc
    } else {
        break
    }
}

// build totals lines
var lines: [(name: [UInt8], currency: [UInt8], text: String)] = []
for (nameBytes, curs) in totals {
    for (cur, sum) in curs {
        let text = "total \(cur) \(fmtCents(sum)) \(String(decoding: nameBytes, as: UTF8.self))"
        lines.append((nameBytes, Array(cur.utf8), text))
    }
}
lines.sort { a, b in
    if a.name != b.name { return a.name.lexicographicallyPrecedes(b.name) }
    return a.currency.lexicographicallyPrecedes(b.currency)
}
for l in lines { print(l.text) }

for st in statusCounts.keys.sorted() {
    print("status \(st) \(statusCounts[st]!)")
}
print("orders \(N) pages \(P) retries \(R) reauth \(A)")

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    static int retries = 0, reauth = 0;
    static PrintStream out;

    static class Resp {
        int status;
        Map<String, String> headers = new HashMap<>();
        String body;
    }

    static void fatal(Resp r) {
        out.println("ERROR " + r.status + " " + r.body);
        out.flush();
        System.exit(0);
    }

    static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    // ---------- minimal JSON ----------
    static class Pi {
        String s; int i;
        Pi(String s) { this.s = s; }
        void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        Object val() {
            ws();
            char c = s.charAt(i);
            if (c == '{') {
                i++; Map<String, Object> m = new LinkedHashMap<>();
                ws(); if (s.charAt(i) == '}') { i++; return m; }
                while (true) {
                    ws(); String k = str(); ws(); i++; // ':'
                    Object v = val(); m.put(k, v); ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; return m; // '}'
                }
            }
            if (c == '[') {
                i++; List<Object> l = new ArrayList<>();
                ws(); if (s.charAt(i) == ']') { i++; return l; }
                while (true) {
                    l.add(val()); ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; return l; // ']'
                }
            }
            if (c == '"') return str();
            int j = i;
            while (j < s.length() && ",]} \t\r\n".indexOf(s.charAt(j)) < 0) j++;
            String t = s.substring(i, j); i = j;
            if (t.equals("null")) return null;
            return t;
        }
        String str() {
