const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function formEncode(s: string): string {
  const bytes = Buffer.from(s, "utf8");
  let out = "";
  for (const b of bytes) {
    const c = String.fromCharCode(b);
    if (/[A-Za-z0-9\-._*]/.test(c)) out += c;
    else if (c === " ") out += "+";
    else out += "%" + b.toString(16).toUpperCase().padStart(2, "0");
  }
  return out;
}

function fatal(status: number, body: string): never {
  process.stdout.write(`ERROR ${status} ${body}\n`);
  process.exit(0);
}

async function getToken(): Promise<string> {
  const cred = formEncode(client.client_id) + ":" + formEncode(client.client_secret);
  const res = await fetch(`${baseUrl}/oauth/token`, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: "Basic " + Buffer.from(cred, "utf8").toString("base64"),
    },
    body: `grant_type=client_credentials&scope=${formEncode(client.scope)}`,
  });
  const text = await res.text();
  if (res.status !== 200) fatal(res.status, text);
  return JSON.parse(text).access_token;
}

function toCents(amount: string): bigint {
  const m = /^(-)?(\d+)(?:\.(\d{1,2}))?$/.exec(amount);
  if (!m) throw new Error("bad amount: " + amount);
  let cents = BigInt(m[2]) * 100n;
  if (m[3]) cents += BigInt(m[3].padEnd(2, "0"));
  if (m[1]) cents = -cents;
  return cents;
}

function fmt(cents: bigint): string {
  const neg = cents < 0n;
  const abs = neg ? -cents : cents;
  const int = abs / 100n;
  const frac = abs % 100n;
  return (neg ? "-" : "") + `${int}.${frac.toString().padStart(2, "0")}`;
}

async function main() {
  let token = await getToken();
  let firstWithToken = true;
  let cursor: string | null = null;
  let pages = 0;
  let retries = 0;
  let reauth = 0;
  const orders: any[] = [];

  while (true) {
    let url = `${baseUrl}/orders?limit=${client.page_size}`;
    if (cursor !== null) url += "&cursor=" + encodeURIComponent(cursor);
    const res = await fetch(url, { headers: { Authorization: "Bearer " + token } });

    if (res.status === 429) {
      retries++;
      const secs = parseInt(res.headers.get("Retry-After") ?? "0", 10);
      await sleep(secs * 1000);
      continue;
    }
    if (res.status === 503) {
      retries++;
      await sleep(500);
      continue;
    }
    if (res.status === 401) {
      const text = await res.text();
      if (firstWithToken) fatal(res.status, text);
      reauth++;
      token = await getToken();
      firstWithToken = true;
      continue;
    }
    const text = await res.text();
    if (res.status !== 200) fatal(res.status, text);
    firstWithToken = false;
    pages++;
    const body = JSON.parse(text);
    orders.push(...body.data);
    if (body.next_cursor === null) break;
    cursor = body.next_cursor;
  }

  const totals = new Map<string, Map<string, bigint>>();
  const statusCounts = new Map<string, number>();

  for (const o of orders) {
    statusCounts.set(o.status, (statusCounts.get(o.status) ?? 0) + 1);
    if (o.status === "cancelled") continue;
    let byCur = totals.get(o.customer.name);
    if (!byCur) {
      byCur = new Map();
      totals.set(o.customer.name, byCur);
    }
    byCur.set(o.currency, (byCur.get(o.currency) ?? 0n) + toCents(o.amount));
  }

  const lines: string[] = [];
  const names = [...totals.keys()].sort((a, b) =>
    Buffer.compare(Buffer.from(a, "utf8"), Buffer.from(b, "utf8"))
  );
  for (const name of names) {
    const byCur = totals.get(name)!;
    for (const cur of [...byCur.keys()].sort()) {
      lines.push(`total ${cur} ${fmt(byCur.get(cur)!)} ${name}`);
    }
  }
  for (const st of [...statusCounts.keys()].sort()) {
    lines.push(`status ${st} ${statusCounts.get(st)}`);
  }
  lines.push(`orders ${orders.length} pages ${pages} retries ${retries} reauth ${reauth}`);
  process.stdout.write(lines.join("\n") + "\n");
}

main();

