use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::thread;
use std::time::Duration;

// ---------- JSON ----------

#[derive(Clone)]
enum Val {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Val>),
    Obj(Vec<(String, Val)>),
}

impl Val {
    fn get(&self, k: &str) -> &Val {
        if let Val::Obj(m) = self {
            for (kk, v) in m {
                if kk == k {
                    return v;
                }
            }
        }
        panic!("missing key {}", k);
    }
    fn as_str(&self) -> &str {
        if let Val::Str(s) = self {
            s
        } else {
            panic!("not a string");
        }
    }
    fn as_num(&self) -> u64 {
        if let Val::Num(s) = self {
            s.parse().unwrap()
        } else {
            panic!("not a number");
        }
    }
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len()
            && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r')
        {
            self.i += 1;
        }
    }
    fn value(&mut self) -> Val {
        self.ws();
        match self.b[self.i] {
            b'{' => self.obj(),
            b'[' => self.arr(),
            b'"' => Val::Str(self.string()),
            b't' => {
                self.i += 4;
                Val::Bool(true)
            }
            b'f' => {
                self.i += 5;
                Val::Bool(false)
            }
            b'n' => {
                self.i += 4;
                Val::Null
            }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Val {
        self.i += 1;
        let mut m = Vec::new();
        self.ws();
        if self.b[self.i] == b'}' {
            self.i += 1;
            return Val::Obj(m);
        }
        loop {
            self.ws();
            let k = self.string();
            self.ws();
            assert_eq!(self.b[self.i], b':');
            self.i += 1;
            let v = self.value();
            m.push((k, v));
            self.ws();
            match self.b[self.i] {
                b',' => self.i += 1,
                b'}' => {
                    self.i += 1;
                    break;
                }
                _ => panic!("bad obj"),
            }
        }
        Val::Obj(m)
    }
    fn arr(&mut self) -> Val {
        self.i += 1;
        let mut a = Vec::new();
        self.ws();
        if self.b[self.i] == b']' {
            self.i += 1;
            return Val::Arr(a);
        }
        loop {
            let v = self.value();
            a.push(v);
            self.ws();
            match self.b[self.i] {
                b',' => self.i += 1,
                b']' => {
                    self.i += 1;
                    break;
                }
                _ => panic!("bad arr"),
            }
        }
        Val::Arr(a)
    }
    fn num(&mut self) -> Val {
        let s = self.i;
        while self.i < self.b.len()
            && matches!(self.b[self.i], b'0'..=b'9' | b'-' | b'+' | b'.' | b'e' | b'E')
        {
            self.i += 1;
        }
        Val::Num(String::from_utf8_lossy(&self.b[s..self.i]).into_owned())
    }
    fn hex4(&mut self) -> u32 {
        let s = &self.b[self.i..self.i + 4];
        self.i += 4;
        u32::from_str_radix(&String::from_utf8_lossy(s), 16).unwrap()
    }
    fn string(&mut self) -> String {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.b[self.i];
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let cp = self.hex4();
                            let ch = if (0xD800..0xDC00).contains(&cp) {
                                self.i += 2; // skip \u
                                let lo = self.hex4();
                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                            } else {
                                cp
                            };
                            push_utf8(&mut out, ch);
                        }
                        _ => panic!("bad escape"),
                    }
                }
                _ => out.push(c),
            }
        }
        String::from_utf8(out).unwrap()
    }
}

fn push_utf8(out: &mut Vec<u8>, cp: u32) {
    let c = char::from_u32(cp).unwrap();
    let mut buf = [0u8; 4];
    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
}

fn parse_json(s: &str) -> Val {
    let mut p = P { b: s.as_bytes(), i: 0 };
    p.value()
}

// ---------- encoding helpers ----------

fn form_encode(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'*' => {
                o.push(b as char)
            }
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn query_encode(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                o.push(b as char)
            }
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn b64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 {
            T[(n >> 6) as usize & 63] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            T[(n as usize) & 63] as char
        } else {
            '='
        });
    }
    out
}

// ---------- HTTP ----------

struct Resp {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

impl Resp {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|h| h.0 == name)
            .map(|h| h.1.as_str())
    }
}

fn http_req(
    authority: &str,
    method: &str,
    path: &str,
    headers: &[(String, String)],
    body: Option<&str>,
) -> std::io::Result<Resp> {
    let stream = TcpStream::connect(authority)?;
    let mut w = stream.try_clone()?;
    let mut req = format!(
        "{} {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n",
        method, path, authority
    );
    for (k, v) in headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n\r\n", b.len()));
        req.push_str(b);
    } else {
        req.push_str("\r\n");
    }
    w.write_all(req.as_bytes())?;

    let mut r = BufReader::new(stream);
    let mut line = String::new();
    r.read_line(&mut line)?;
    let status: u16 = line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut hdrs = Vec::new();
    loop {
        let mut l = String::new();
        r.read_line(&mut l)?;
        let l = l.trim_end();
        if l.is_empty() {
            break;
        }
        if let Some(c) = l.find(':') {
            hdrs.push((l[..c].to_lowercase(), l[c + 1..].trim().to_string()));
        }
    }
    let te = hdrs
        .iter()
        .find(|h| h.0 == "transfer-encoding")
        .map(|h| h.1.to_lowercase());
    let body = if te.map(|t| t.contains("chunked")).unwrap_or(false) {
        let mut body = Vec::new();
        loop {
            let mut l = String::new();
            r.read_line(&mut l)?;
            let szstr = l.trim().split(';').next().unwrap().trim();
            let n = usize::from_str_radix(szstr, 16).unwrap();
            if n == 0 {
                loop {
                    let mut t = String::new();
                    r.read_line(&mut t)?;
                    if t.trim_end().is_empty() {
                        break;
                    }
                }
                break;
            }
            let mut buf = vec![0u8; n];
            r.read_exact(&mut buf)?;
            body.extend_from_slice(&buf);
            let mut crlf = [0u8; 2];
            r.read_exact(&mut crlf)?;
        }
        String::from_utf8(body).unwrap()
    } else if let Some(cl) = hdrs.iter().find(|h| h.0 == "content-length") {
        let n: usize = cl.1.parse().unwrap();
        let mut buf = vec![0u8; n];
        r.read_exact(&mut buf)?;
        String::from_utf8(buf).unwrap()
    } else {
        let mut buf = Vec::new();
        r.read_to_end(&mut buf)?;
        String::from_utf8(buf).unwrap()
    };
    Ok(Resp { status, headers: hdrs, body })
}

// ---------- money ----------

fn cents(s: &str) -> i64 {
    let (neg, body) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else {
        (false, s)
    };
    let (int, frac) = match body.split_once('.') {
        Some((a, b)) => (a, b),
        None => (body, ""),
    };
    let iv: i64 = int.parse().unwrap();
    let mut fv: i64 = 0;
    for c in frac.bytes() {
        fv = fv * 10 + (c - b'0') as i64;
    }
    let c = iv * 100 + fv;
    if neg {
        -c
    } else {
        c
    }
}

fn fmt_amount(c: i64) -> String {
    let neg = c < 0;
    let a = c.unsigned_abs();
    format!("{}{}.{:02}", if neg { "-" } else { "" }, a / 100, a % 100)
}

// ---------- main logic ----------

fn get_token(
    authority: &str,
    token_path: &str,
    client_id: &str,
    client_secret: &str,
    scope: &str,
) -> Result<String, (u16, String)> {
    let creds = format!("{}:{}", form_encode(client_id), form_encode(client_secret));
    let auth = format!("Basic {}", b64(creds.as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", form_encode(scope));
    let resp = http_req(
        authority,
        "POST",
        token_path,
        &[
            ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
            ("Authorization".to_string(), auth),
        ],
        Some(&body),
    )
    .map_err(|e| (0, e.to_string()))?;
    if resp.status != 200 {
        return Err((resp.status, resp.body));
    }
    let v = parse_json(&resp.body);
    Ok(v.get("access_token").as_str().to_string())
}

fn run() -> Result<(), (u16, String)> {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cfg_raw = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cfg = parse_json(&cfg_raw);
    let client_id = cfg.get("client_id").as_str().to_string();
    let client_secret = cfg.get("client_secret").as_str().to_string();
    let scope = cfg.get("scope").as_str().to_string();
    let page_size = cfg.get("page_size").as_num();

    let rest = base_url.strip_prefix("http://").unwrap_or(base_url);
    let (authority, base_path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, ""),
    };
    let token_path = format!("{}/oauth/token", base_path);
    let orders_path = format!("{}/orders", base_path);

    let mut token = get_token(&authority, &token_path, &client_id, &client_secret, &scope)?;
    let mut fresh = true;

    let mut cursor: Option<String> = None;
    let mut n_orders: u64 = 0;
    let mut pages: u64 = 0;
    let mut retries: u64 = 0;
    let mut reauth: u64 = 0;

    let mut totals: HashMap<(String, String), i64> = HashMap::new();
    let mut status_count: HashMap<String, i64> = HashMap::new();

    loop {
        let path = match &cursor {
            None => format!("{}?limit={}", orders_path, page_size),
            Some(c) => format!("{}?limit={}&cursor={}", orders_path, page_size, query_encode(c)),
        };
        let resp = http_req(
            &authority,
            "GET",
            &path,
            &[("Authorization".to_string(), format!("Bearer {}", token))],
            None,
        )
        .map_err(|e| (0, e.to_string()))?;

        match resp.status {
            200 => {
                pages += 1;
                fresh = false;
                let v = parse_json(&resp.body);
                if let Val::Arr(arr) = v.get("data") {
                    for o in arr {
                        n_orders += 1;
                        let status = o.get("status").as_str().to_string();
                        *status_count.entry(status.clone()).or_insert(0) += 1;
                        if status != "cancelled" {
                            let name = o.get("customer").get("name").as_str().to_string();
                            let currency = o.get("currency").as_str().to_string();
                            let c = cents(o.get("amount").as_str());
                            *totals.entry((name, currency)).or_insert(0) += c;
                        }
                    }
                }
                cursor = match v.get("next_cursor") {
                    Val::Str(s) => Some(s.clone()),
                    _ => None,
                };
                if cursor.is_none() {
                    break;
                }
            }
            429 => {
                retries += 1;
                let ra: u64 = resp.header("retry-after").unwrap().trim().parse().unwrap();
                thread::sleep(Duration::from_secs(ra));
            }
            503 => {
                retries += 1;
                thread::sleep(Duration::from_millis(100));
            }
            401 => {
                if fresh {
                    return Err((401, resp.body));
                }
                reauth += 1;
                token = get_token(&authority, &token_path, &client_id, &client_secret, &scope)?;
                fresh = true;
            }
            s => return Err((s, resp.body)),
        }
    }

    let mut tv: Vec<(&String, &String, i64)> =
        totals.iter().map(|((n, c), v)| (n, c, *v)).collect();
    tv.sort_by(|a, b| a.0.cmp(b.0).then(a.1.cmp(b.1)));
    for (name, cur, c) in tv {
        println!("total {} {} {}", cur, fmt_amount(c), name);
    }
    let mut sv: Vec<(&String, i64)> = status_count.iter().map(|(s, c)| (s, *c)).collect();
    sv.sort_by(|a, b| a.0.cmp(b.0));
    for (s, c) in sv {
        println!("status {} {}", s, c);
    }
    println!(
        "orders {} pages {} retries {} reauth {}",
        n_orders, pages, retries, reauth
    );
    Ok(())
}

fn main() {
    if let Err((status, body)) = run() {
        println!("ERROR {} {}", status, body);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::thread;
use std::time::Duration;

// ---------- JSON ----------

#[derive(Clone)]
enum Val {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Val>),
    Obj(Vec<(String, Val)>),
}

impl Val {
    fn get(&self, k: &str) -> &Val {
        if let Val::Obj(m) = self {
            for (kk, v) in m {
                if kk == k {
                    return v;
                }
            }
        }
        panic!("missing key {}", k);
    }
    fn as_str(&self) -> &str {
        if let Val::Str(s) = self {
            s
        } else {
            panic!("not a string");
        }
    }
    fn as_num(&self) -> u64 {
        if let Val::Num(s) = self {
            s.parse().unwrap()
        } else {
            panic!("not a number");
        }
    }
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len()
            && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r')
        {
            self.i += 1;
        }
    }
    fn value(&mut self) -> Val {
        self.ws();
        match self.b[self.i] {
            b'{' => self.obj(),
            b'[' => self.arr(),
            b'"' => Val::Str(self.string()),
            b't' => {
                self.i += 4;
                Val::Bool(true)
            }
            b'f' => {
                self.i += 5;
                Val::Bool(false)
            }
            b'n' => {
                self.i += 4;
                Val::Null
            }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Val {
        self.i += 1;
        let mut m = Vec::new();
        self.ws();
        if self.b[self.i] == b'}' {
            self.i += 1;
            return Val::Obj(m);
        }
        loop {
            self.ws();
            let k = self.string();
            self.ws();
            assert_eq!(self.b[self.i], b':');
            self.i += 1;
            let v = self.value();
            m.push((k, v));
            self.ws();
            match self.b[self.i] {
                b',' => self.i += 1,
                b'}' => {
                    self.i += 1;
                    break;
                }
                _ => panic!("bad obj"),
            }
        }
        Val::Obj(m)
    }
    fn arr(&mut self) -> Val {
        self.i += 1;
        let mut a = Vec::new();
        self.ws();
        if self.b[self.i] == b']' {
            self.i += 1;
            return Val::Arr(a);
        }
        loop {
            let v = self.value();
            a.push(v);
            self.ws();
            match self.b[self.i] {
                b',' => self.i += 1,
                b']' => {
                    self.i += 1;
                    break;
                }
                _ => panic!("bad arr"),
            }
        }
        Val::Arr(a)
    }
    fn num(&mut self) -> Val {
        let s = self.i;
        while self.i < self.b.len()
            && matches!(self.b[self.i], b'0'..=b'9' | b'-' | b'+' | b'.' | b'e' | b'E')
        {
            self.i += 1;
        }
        Val::Num(String::from_utf8_lossy(&self.b[s..self.i]).into_owned())
    }
    fn hex4(&mut self) -> u32 {
        let s = &self.b[self.i..self.i + 4];
        self.i += 4;
        u32::from_str_radix(&String::from_utf8_lossy(s), 16).unwrap()
    }
    fn string(&mut self) -> String {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.b[self.i];
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let cp = self.hex4();
                            let ch = if (0xD800..0xDC00).contains(&cp) {
                                self.i += 2; // skip \u
                                let lo = self.hex4();
                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                            } else {
                                cp
                            };
                            push_utf8(&mut out, ch);
                        }
                        _ => panic!("bad escape"),
                    }
                }
                _ => out.push(c),
            }
        }
        String::from_utf8(out).unwrap()
    }
}

fn push_utf8(out: &mut Vec<u8>, cp: u32) {
    let c = char::from_u32(cp).unwrap();
    let mut buf = [0u8; 4];
    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
}

fn parse_json(s: &str) -> Val {
    let mut p = P { b: s.as_bytes(), i: 0 };
    p.value()
}

// ---------- encoding helpers ----------

fn form_encode(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'*' => {
                o.push(b as char)
            }
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn query_encode(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                o.push(b as char)
            }
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn b64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 {
            T[(n >> 6) as usize & 63] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            T[(n as usize) & 63] as char
        } else {
            '='
        });
    }
    out
}

// ---------- HTTP ----------

struct Resp {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

impl Resp {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|h| h.0 == name)
            .map(|h| h.1.as_str())
    }
}

fn http_req(
    authority: &str,
    method: &str,
    path: &str,
    headers: &[(String, String)],
    body: Option<&str>,
) -> std::io::Result<Resp> {
    let stream = TcpStream::connect(authority)?;
    let mut w = stream.try_clone()?;
    let mut req = format!(
        "{} {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n",
        method, path, authority
    );
    for (k, v) in headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n\r\n", b.len()));
        req.push_str(b);
    } else {
        req.push_str("\r\n");
    }
    w.write_all(req.as_bytes())?;

    let mut r = BufReader::new(stream);
    let mut line = String::new();
    r.read_line(&mut line)?;
    let status: u16 = line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut hdrs = Vec::new();
    loop {
        let mut l = String::new();
        r.read_line(&mut l)?;
        let l = l.trim_end();
        if l.is_empty() {
            break;
        }
        if let Some(c) = l.find(':') {
            hdrs.push((l[..c].to_lowercase(), l[c + 1..].trim().to_string()));
        }
    }
    let te = hdrs
        .iter()
        .find(|h| h.0 == "transfer-encoding")
        .map(|h| h.1.to_lowercase());
    let body = if te.map(|t| t.contains("chunked")).unwrap_or(false) {
        let mut body = Vec::new();
        loop {
            let mut l = String::new();
            r.read_line(&mut l)?;
            let szstr = l.trim().split(';').next().unwrap().trim();
            let n = usize::from_str_radix(szstr, 16).unwrap();
            if n == 0 {
                loop {
                    let mut t = String::new();
                    r.read_line(&mut t)?;
                    if t.trim_end().is_empty() {
                        break;
                    }
                }
                break;
            }
            let mut buf = vec![0u8; n];
            r.read_exact(&mut buf)?;
            body.extend_from_slice(&buf);
            let mut crlf = [0u8; 2];
            r.read_exact(&mut crlf)?;
        }
        String::from_utf8(body).unwrap()
    } else if let Some(cl) = hdrs.iter().find(|h| h.0 == "content-length") {
        let n: usize = cl.1.parse().unwrap();
        let mut buf = vec![0u8; n];
        r.read_exact(&mut buf)?;
        String::from_utf8(buf).unwrap()
    } else {
        let mut buf = Vec::new();
        r.read_to_end(&mut buf)?;
        String::from_utf8(buf).unwrap()
    };
    Ok(Resp { status, headers: hdrs, body })
}

// ---------- money ----------

fn cents(s: &str) -> i64 {
    let (neg, body) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else {
        (false, s)
    };
    let (int, frac) = match body.split_once('.') {
        Some((a, b)) => (a, b),
        None => (body, ""),
    };
    let iv: i64 = int.parse().unwrap();
    let mut fv: i64 = 0;
    for c in frac.bytes() {
        fv = fv * 10 + (c - b'0') as i64;
    }
    if frac.len() == 1 {
        fv *= 10;
    }
    let c = iv * 100 + fv;
    if neg {
        -c
    } else {
        c
    }
}

fn fmt_amount(c: i64) -> String {
    let neg = c < 0;
    let a = c.unsigned_abs();
    format!("{}{}.{:02}", if neg { "-" } else { "" }, a / 100, a % 100)
}

// ---------- main logic ----------

fn get_token(
    authority: &str,
    token_path: &str,
    client_id: &str,
    client_secret: &str,
    scope: &str,
) -> Result<String, (u16, String)> {
    let creds = format!("{}:{}", form_encode(client_id), form_encode(client_secret));
    let auth = format!("Basic {}", b64(creds.as_bytes()));
    let body = format!("grant_type=client_credentials&scope={}", form_encode(scope));
    let resp = http_req(
        authority,
        "POST",
        token_path,
        &[
            ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
            ("Authorization".to_string(), auth),
        ],
        Some(&body),
    )
    .map_err(|e| (0, e.to_string()))?;
    if resp.status != 200 {
        return Err((resp.status, resp.body));
    }
    let v = parse_json(&resp.body);
    Ok(v.get("access_token").as_str().to_string())
}

fn run() -> Result<(), (u16, String)> {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cfg_raw = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cfg = parse_json(&cfg_raw);
    let client_id = cfg.get("client_id").as_str().to_string();
    let client_secret = cfg.get("client_secret").as_str().to_string();
    let scope = cfg.get("scope").as_str().to_string();
    let page_size = cfg.get("page_size").as_num();

    let rest = base_url.strip_prefix("http://").unwrap_or(base_url);
    let (authority, base_path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, ""),
    };
    let token_path = format!("{}/oauth/token", base_path);
    let orders_path = format!("{}/orders", base_path);

    let mut token = get_token(&authority, &token_path, &client_id, &client_secret, &scope)?;
    let mut fresh = true;

    let mut cursor: Option<String> = None;
    let mut n_orders: u64 = 0;
    let mut pages: u64 = 0;
    let mut retries: u64 = 0;
    let mut reauth: u64 = 0;

    let mut totals: HashMap<(String, String), i64> = HashMap::new();
    let mut status_count: HashMap<String, i64> = HashMap::new();

    loop {
        let path = match &cursor {
            None => format!("{}?limit={}", orders_path, page_size),
            Some(c) => format!("{}?limit={}&cursor={}", orders_path, page_size, query_encode(c)),
        };
        let resp = http_req(
            &authority,
            "GET",
            &path,
            &[("Authorization".to_string(), format!("Bearer {}", token))],
            None,
        )
        .map_err(|e| (0, e.to_string()))?;

        match resp.status {
            200 => {
                pages += 1;
                fresh = false;
                let v = parse_json(&resp.body);
                if let Val::Arr(arr) = v.get("data") {
                    for o in arr {
                        n_orders += 1;
                        let status = o.get("status").as_str().to_string();
                        *status_count.entry(status.clone()).or_insert(0) += 1;
                        if status != "cancelled" {
                            let name = o.get("customer").get("name").as_str().to_string();
                            let currency = o.get("currency").as_str().to_string();
                            let c = cents(o.get("amount").as_str());
                            *totals.entry((name, currency)).or_insert(0) += c;
                        }
                    }
                }
                cursor = match v.get("next_cursor") {
                    Val::Str(s) => Some(s.clone()),
                    _ => None,
                };
                if cursor.is_none() {
                    break;
                }
            }
            429 => {
                retries += 1;
                let ra: u64 = resp.header("retry-after").unwrap().trim().parse().unwrap();
                thread::sleep(Duration::from_secs(ra));
            }
            503 => {
                retries += 1;
                thread::sleep(Duration::from_millis(100));
            }
            401 => {
                if fresh {
                    return Err((401, resp.body));
                }
                reauth += 1;
                token = get_token(&authority, &token_path, &client_id, &client_secret, &scope)?;
                fresh = true;
            }
            s => return Err((s, resp.body)),
        }
    }

    let mut tv: Vec<(&String, &String, i64)> =
        totals.iter().map(|((n, c), v)| (n, c, *v)).collect();
    tv.sort_by(|a, b| a.0.cmp(b.0).then(a.1.cmp(b.1)));
    for (name, cur, c) in tv {
        println!("total {} {} {}", cur, fmt_amount(c), name);
    }
    let mut sv: Vec<(&String, i64)> = status_count.iter().map(|(s, c)| (s, *c)).collect();
    sv.sort_by(|a, b| a.0.cmp(b.0));
    for (s, c) in sv {
        println!("status {} {}", s, c);
    }
    println!(
        "orders {} pages {} retries {} reauth {}",
        n_orders, pages, retries, reauth
    );
    Ok(())
}

fn main() {
    if let Err((status, body)) = run() {
        println!("ERROR {} {}", status, body);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>

/* ---------- globals ---------- */
static char *g_host, *g_port, *g_hostport, *g_prefix;

static void fatal(int code, const char *body) {
    printf("ERROR %d %s\n", code, body ? body : "");
    exit(0);
}

/* ---------- JSON parser ---------- */
typedef struct JV JV;
struct JV { int type; /*0 null,1 bool,2 num,3 str,4 arr,5 obj*/ char *s; JV **items; char **keys; int n; };
typedef struct { const char *p; } JP;

static JV *jnew(int t) { JV *v = calloc(1, sizeof(JV)); v->type = t; return v; }
static void jadd(JV *o, char *k, JV *v) {
    o->items = realloc(o->items, (o->n + 1) * sizeof(JV *));
    o->keys = realloc(o->keys, (o->n + 1) * sizeof(char *));
    o->keys[o->n] = k; o->items[o->n] = v; o->n++;
}
static void jskip(JP *j) { while (*j->p == ' ' || *j->p == '\t' || *j->p == '\n' || *j->p == '\r') j->p++; }

static char *jparse_string_raw(JP *j) {
    j->p++; /* opening quote */
    size_t cap = 16, len = 0; char *b = malloc(cap);
#define PB(c) do{ if(len+5>=cap){cap*=2;b=realloc(b,cap);} b[len++]=(char)(c);}while(0)
    while (*j->p != '"') {
        char c = *j->p++;
        if (c == '\\') {
            char e = *j->p++;
            switch (e) {
                case '"': PB('"'); break; case '\\': PB('\\'); break; case '/': PB('/'); break;
                case 'b': PB('\b'); break; case 'f': PB('\f'); break; case 'n': PB('\n'); break;
                case 'r': PB('\r'); break; case 't': PB('\t'); break;
                case 'u': {
                    unsigned cp; sscanf(j->p, "%4x", &cp); j->p += 4;
                    if (cp >= 0xD800 && cp <= 0xDBFF && j->p[0] == '\\' && j->p[1] == 'u') {
                        unsigned lo; sscanf(j->p + 2, "%4x", &lo);
                        if (lo >= 0xDC00 && lo <= 0xDFFF) { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00); j->p += 6; }
                    }
                    if (cp < 0x80) PB(cp);
                    else if (cp < 0x800) { PB(0xC0 | (cp >> 6)); PB(0x80 | (cp & 0x3F)); }
                    else if (cp < 0x10000) { PB(0xE0 | (cp >> 12)); PB(0x80 | ((cp >> 6) & 0x3F)); PB(0x80 | (cp & 0x3F)); }
                    else { PB(0xF0 | (cp >> 18)); PB(0x80 | ((cp >> 12) & 0x3F)); PB(0x80 | ((cp >> 6) & 0x3F)); PB(0x80 | (cp & 0x3F)); }
                } break;
                default: break;
            }
        } else PB(c);
    }
    j->p++;
#undef PB
    b[len] = 0; return b;
}

static JV *jparse(JP *j) {
    jskip(j);
    char c = *j->p;
    if (c == '{') {
        j->p++; JV *o = jnew(5); jskip(j);
        if (*j->p == '}') { j->p++; return o; }
        for (;;) {
            jskip(j); char *k = jparse_string_raw(j); jskip(j); j->p++; /* ':' */
            JV *v = jparse(j); jadd(o, k, v); jskip(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == '}') { j->p++; break; }
        }
        return o;
    }
    if (c == '[') {
        j->p++; JV *a = jnew(4); jskip(j);
        if (*j->p == ']') { j->p++; return a; }
        for (;;) {
            JV *v = jparse(j); jadd(a, NULL, v); jskip(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == ']') { j->p++; break; }
        }
        return a;
    }
    if (c == '"') { JV *v = jnew(3); v->s = jparse_string_raw(j); return v; }
    if (!strncmp(j->p, "true", 4)) { j->p += 4; JV *v = jnew(1); v->s = strdup("true"); return v; }
    if (!strncmp(j->p, "false", 5)) { j->p += 5; JV *v = jnew(1); v->s = strdup("false"); return v; }
    if (!strncmp(j->p, "null", 4)) { j->p += 4; return jnew(0); }
    const char *st = j->p;
    while (*j->p && strchr("0123456789+-.eE", *j->p)) j->p++;
    JV *v = jnew(2); size_t n = (size_t)(j->p - st);
    v->s = malloc(n + 1); memcpy(v->s, st, n); v->s[n] = 0; return v;
}

static JV *jget(JV *o, const char *k) {
    if (!o || o->type != 5) return NULL;
    for (int i = 0; i < o->n; i++) if (o->keys[i] && !strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}

/* ---------- encoding helpers ---------- */
static char *b64(const unsigned char *in, size_t n) {
    static const char *A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    char *o = malloc(((n + 2) / 3) * 4 + 1); size_t j = 0;
    for (size_t i = 0; i < n; i += 3) {
        unsigned v = (unsigned)in[i] << 16 | (i + 1 < n ? (unsigned)in[i + 1] << 8 : 0) | (i + 2 < n ? in[i + 2] : 0);
        o[j++] = A[(v >> 18) & 63]; o[j++] = A[(v >> 12) & 63];
        o[j++] = (i + 1 < n) ? A[(v >> 6) & 63] : '=';
        o[j++] = (i + 2 < n) ? A[v & 63] : '=';
    }
    o[j] = 0; return o;
}

static char *form_encode(const char *s) {
    size_t cap = strlen(s) * 3 + 4, len = 0; char *o = malloc(cap);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '*') o[len++] = (char)c;
        else if (c == ' ') o[len++] = '+';
        else len += (size_t)sprintf(o + len, "%%%02X", c);
    }
    o[len] = 0; return o;
}

static char *pct_encode(const char *s) {
    size_t cap = strlen(s) * 3 + 4, len = 0; char *o = malloc(cap);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '~') o[len++] = (char)c;
        else len += (size_t)sprintf(o + len, "%%%02X", c);
    }
    o[len] = 0; return o;
}

/* ---------- HTTP ---------- */
typedef struct { int code; char *hdrs; char *body; } Resp;

static char *header_get(const char *hdrs, const char *name) {
    size_t nl = strlen(name);
    const char *p = hdrs;
    while (p && *p) {
        const char *e = strstr(p, "\r\n");
        size_t ll = e ? (size_t)(e - p) : strlen(p);
        if (ll > nl && p[nl] == ':' && strncasecmp(p, name, nl) == 0) {
            const char *v = p + nl + 1; while (v < p + ll && *v == ' ') v++;
            size_t vl = (size_t)(p + ll - v);
            char *o = malloc(vl + 1); memcpy(o, v, vl); o[vl] = 0; return o;
        }
        p = e ? e + 2 : NULL;
    }
    return NULL;
}

static char *dechunk(const char *b, size_t *outlen) {
    size_t cap = 8192, len = 0; char *o = malloc(cap);
    const char *p = b;
    for (;;) {
        char *end; unsigned long long sz = strtoull(p, &end, 16);
        if (end == p) break;
        p = end;
        if (*p == ';') { while (*p && *p != '\r') p++; }
        if (p[0] == '\r' && p[1] == '\n') p += 2;
        if (sz == 0) break;
        if (len + sz + 1 > cap) { cap = len + sz + 1; o = realloc(o, cap); }
        memcpy(o + len, p, sz); len += sz; p += sz;
        if (p[0] == '\r' && p[1] == '\n') p += 2;
    }
    o[len] = 0; *outlen = len; return o;
}

static Resp *http_req(const char *method, const char *path, const char *hdrs, const char *body) {
    size_t bl = body ? strlen(body) : 0;
    char *req = malloc(strlen(method) + strlen(path) + strlen(g_hostport) + strlen(hdrs) + bl + 256);
    sprintf(req, "%s %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n%s", method, path, g_hostport, hdrs);
    if (body) sprintf(req + strlen(req), "Content-Length: %zu\r\n", bl);
    strcat(req, "\r\n");
    if (body) strcat(req, body);
    size_t rl = strlen(req);

    struct addrinfo hints; memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; hints.ai_socktype = SOCK_STREAM;
    struct addrinfo *res;
    if (getaddrinfo(g_host, g_port, &hints, &res) != 0) exit(1);
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) exit(1);
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) exit(1);
    freeaddrinfo(res);

    size_t off = 0;
    while (off < rl) {
        ssize_t w = send(fd, req + off, rl - off, 0);
        if (w <= 0) exit(1);
        off += (size_t)w;
    }

    size_t cap = 65536, len = 0; char *buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
        ssize_t r = recv(fd, buf + len, cap - len - 1, 0);
        if (r <= 0) break;
        len += (size_t)r;
    }
    buf[len] = 0; close(fd);

    Resp *rp = malloc(sizeof(Resp));
    rp->code = atoi(buf + 9);
    const char *hb = strstr(buf, "\r\n");
    hb = hb ? hb + 2 : buf;
    const char *bend = strstr(hb, "\r\n\r\n");
    const char *bodystart; size_t hlen;
    if (bend) { hlen = (size_t)(bend - hb); bodystart = bend + 4; }
    else { hlen = strlen(hb); bodystart = hb + hlen; }
    rp->hdrs = malloc(hlen + 1); memcpy(rp->hdrs, hb, hlen); rp->hdrs[hlen] = 0;
    size_t restlen = len - (size_t)(bodystart - buf);

    char *te = header_get(rp->hdrs, "Transfer-Encoding");
    char *cl = header_get(rp->hdrs, "Content-Length");
    int chunked = 0;
    if (te) {
        char *l = strdup(te); for (char *q = l; *q; q++) *q = (char)tolower((unsigned char)*q);
        chunked = strstr(l, "chunked") != NULL; free(l);
    }
    if (chunked) {
        rp->body = dechunk(bodystart, &restlen);
    } else if (cl) {
        size_t n = (size_t)strtoul(cl, NULL, 10);
        if (n > restlen) n = restlen;
        rp->body = malloc(n + 1); memcpy(rp->body, bodystart, n); rp->body[n] = 0;
    } else {
        rp->body = malloc(restlen + 1); memcpy(rp->body, bodystart, restlen); rp->body[restlen] = 0;
    }
    return rp;
}

/* ---------- aggregation ---------- */
typedef struct { char *name, *cur; long long cents; } Tot;
static Tot *tots = NULL; static int nt = 0, ctot = 0;
static void add_tot(const char *name, const char *cur, long long c) {
    for (int i = 0; i < nt; i++)
        if (!strcmp(tots[i].name, name) && !strcmp(tots[i].cur, cur)) { tots[i].cents += c; return; }
    if (nt == ctot) { ctot = ctot ? ctot * 2 : 16; tots = realloc(tots, (size_t)ctot * sizeof(Tot)); }
    tots[nt].name = strdup(name); tots[nt].cur = strdup(cur); tots[nt].cents = c; nt++;
}
typedef struct { char *st; long long cnt; } Stc;
static Stc *sts = NULL; static int ns = 0, cst = 0;
static void add_status(const char *st) {
    for (int i = 0; i < ns; i++)
        if (!strcmp(sts[i].st, st)) { sts[i].cnt++; return; }
    if (ns == cst) { cst = cst ? cst * 2 : 16; sts = realloc(sts, (size_t)cst * sizeof(Stc)); }
    sts[ns].st = strdup(st); sts[ns].cnt = 1; ns++;
}

static long long amount_cents(const char *s) {
    long long sign = 1;
    if (*s == '-') { sign = -1; s++; }
    long long ip = 0;
    while (isdigit((unsigned char)*s)) ip = ip * 10 + (*s++ - '0');
    long long c = ip * 100;
    if (*s == '.') {
        s++; int d = 0;
        while (isdigit((unsigned char)*s) && d < 2) { c = c * 10 + (*s++ - '0'); d++; }
        if (d == 1) c *= 10;
    }
    return sign * c;
}

static int cmp_tot(const void *a, const void *b) {
    const Tot *x = a, *y = b;
    int c = strcmp(x->name, y->name);
    if (c) return c;
    return strcmp(x->cur, y->cur);
}
static int cmp_st(const void *a, const void *b) {
    const Stc *x = a, *y = b;
    return strcmp(x->st, y->st);
}

/* ---------- misc ---------- */
static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) exit(1);
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if (fread(b, 1, (size_t)n, f) != (size_t)n) exit(1);
    b[n] = 0; fclose(f); return b;
}

static char *get_token(const char *cid, const char *csec, const char *scope) {
    char *es = form_encode(scope), *eid = form_encode(cid), *esc = form_encode(csec);
    char *cred = malloc(strlen(eid) + strlen(esc) + 2);
    sprintf(cred, "%s:%s", eid, esc);
    char *b = b64((const unsigned char *)cred, strlen(cred));
    char *ahdr = malloc(strlen(b) + 64);
    sprintf(ahdr, "Authorization: Basic %s\r\nContent-Type: application/x-www-form-urlencoded\r\n", b);
    char *body = malloc(strlen(es) + 64);
    sprintf(body, "grant_type=client_credentials&scope=%s", es);
    char *path = malloc(strlen(g_prefix) + 32);
    sprintf(path, "%s/oauth/token", g_prefix);
    Resp *r = http_req("POST", path, ahdr, body);
    if (r->code != 200) fatal(r->code, r->body);
    JP j = { r->body };
    JV *v = jparse(&j);
    JV *at = jget(v, "access_token");
    if (!at || at->type != 3) exit(1);
    return strdup(at->s);
}

int main(int argc, char **argv) {
    if (argc != 3) return 1;
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    if (strncmp(base_url, "http://", 7) != 0) return 1;
    const char *u = base_url + 7;
    const char *slash = strchr(u, '/');
    if (slash) { g_hostport = strndup(u, (size_t)(slash - u)); g_prefix = strdup(slash); }
    else { g_hostport = strdup(u); g_prefix = strdup(""); }
    char *colon = strrchr(g_hostport, ':');
    if (colon) { g_port = strdup(colon + 1); g_host = strndup(g_hostport, (size_t)(colon - g_hostport)); }
    else { g_host = strdup(g_hostport); g_port = strdup("80"); }

    char *cpath = malloc(strlen(data_dir) + 32);
    sprintf(cpath, "%s/client.json", data_dir);
    char *cfg = read_file(cpath);
    JP cj = { cfg };
    JV *cv = jparse(&cj);
    JV *jcid = jget(cv, "client_id"), *jcsec = jget(cv, "client_secret"),
       *jscope = jget(cv, "scope"), *jps = jget(cv, "page_size");
    if (!jcid || !jcsec || !jscope || !jps) return 1;
    const char *cid = jcid->s, *csec = jcsec->s, *scope = jscope->s;
    int page_size = atoi(jps->s);

    int N = 0, P = 0, R = 0, A = 0;
    char *cursor = NULL;
    int fresh = 1;
    char *token = get_token(cid, csec, scope);

    for (;;) {
        char *path = malloc(strlen(g_prefix) + 64 + (cursor ? strlen(cursor) * 3 + 16 : 0));
        if (cursor) {
            char *ec = pct_encode(cursor);
            sprintf(path, "%s/orders?limit=%d&cursor=%s", g_prefix, page_size, ec);
            free(ec);
        } else {
            sprintf(path, "%s/orders?limit=%d", g_prefix, page_size);
        }
        char *ah = malloc(strlen(token) + 32);
        sprintf(ah, "Authorization: Bearer %s\r\n", token);
        Resp *r = http_req("GET", path, ah, NULL);

        if (r->code == 429) {
            R++;
            char *ra = header_get(r->hdrs, "Retry-After");
            if (ra) sleep((unsigned)atoi(ra));
            continue;
        }
        if (r->code == 503) { R++; continue; }
        if (r->code == 401) {
            if (fresh) fatal(r->code, r->body);
            A++;
            token = get_token(cid, csec, scope);
            fresh = 1;
            continue;
        }
        if (r->code != 200) fatal(r->code, r->body);

        fresh = 0; P++;
        JP j = { r->body };
        JV *v = jparse(&j);
        JV *data = jget(v, "data");
        if (data && data->type == 4) {
            for (int i = 0; i < data->n; i++) {
                JV *o = data->items[i];
                N++;
                JV *st = jget(o, "status");
                if (st && st->type == 3) add_status(st->s);
                JV *cust = jget(o, "customer");
                JV *amt = jget(o, "amount"), *cur = jget(o, "currency");
                JV *nm = cust ? jget(cust, "name") : NULL;
                if (nm && amt && cur && st && st->type == 3 && strcmp(st->s, "cancelled"))
                    add_tot(nm->s, cur->s, amount_cents(amt->s));
            }
        }
        JV *nc = jget(v, "next_cursor");
        if (nc && nc->type == 3) cursor = strdup(nc->s);
        else break;
    }

    qsort(tots, (size_t)nt, sizeof(Tot), cmp_tot);
    for (int i = 0; i < nt; i++) {
        long long v = tots[i].cents;
        unsigned long long a = v < 0 ? (unsigned long long)(-v) : (unsigned long long)v;
        printf("total %s %s%llu.%02llu %s\n", tots[i].cur, v < 0 ? "-" : "", a / 100, a % 100, tots[i].name);
    }
    qsort(sts, (size_t)ns, sizeof(Stc), cmp_st);
    for (int i = 0; i < ns; i++)
        printf("status %s %lld\n", sts[i].st, sts[i].cnt);
    printf("orders %d pages %d retries %d reauth %d\n", N, P, R, A);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>

/* ---------- globals ---------- */
static char *g_host, *g_port, *g_hostport, *g_prefix;

static void fatal(int code, const char *body) {
    printf("ERROR %d %s\n", code, body ? body : "");
    exit(0);
}

/* ---------- JSON parser ---------- */
typedef struct JV JV;
struct JV { int type; /*0 null,1 bool,2 num,3 str,4 arr,5 obj*/ char *s; JV **items; char **keys; int n; };
typedef struct { const char *p; } JP;

static JV *jnew(int t) { JV *v = calloc(1, sizeof(JV)); v->type = t; return v; }
static void jadd(JV *o, char *k, JV *v) {
    o->items = realloc(o->items, (o->n + 1) * sizeof(JV *));
    o->keys = realloc(o->keys, (o->n + 1) * sizeof(char *));
    o->keys[o->n] = k; o->items[o->n] = v; o->n++;
}
static void jskip(JP *j) { while (*j->p == ' ' || *j->p == '\t' || *j->p == '\n' || *j->p == '\r') j->p++; }

static char *jparse_string_raw(JP *j) {
    j->p++; /* opening quote */
    size_t cap = 16, len = 0; char *b = malloc(cap);
#define PB(c) do{ if(len+5>=cap){cap*=2;b=realloc(b,cap);} b[len++]=(char)(c);}while(0)
    while (*j->p != '"') {
        char c = *j->p++;
        if (c == '\\') {
            char e = *j->p++;
            switch (e) {
                case '"': PB('"'); break; case '\\': PB('\\'); break; case '/': PB('/'); break;
                case 'b': PB('\b'); break; case 'f': PB('\f'); break; case 'n': PB('\n'); break;
                case 'r': PB('\r'); break; case 't': PB('\t'); break;
                case 'u': {
                    unsigned cp; sscanf(j->p, "%4x", &cp); j->p += 4;
                    if (cp >= 0xD800 && cp <= 0xDBFF && j->p[0] == '\\' && j->p[1] == 'u') {
                        unsigned lo; sscanf(j->p + 2, "%4x", &lo);
                        if (lo >= 0xDC00 && lo <= 0xDFFF) { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00); j->p += 6; }
                    }
                    if (cp < 0x80) PB(cp);
                    else if (cp < 0x800) { PB(0xC0 | (cp >> 6)); PB(0x80 | (cp & 0x3F)); }
                    else if (cp < 0x10000) { PB(0xE0 | (cp >> 12)); PB(0x80 | ((cp >> 6) & 0x3F)); PB(0x80 | (cp & 0x3F)); }
                    else { PB(0xF0 | (cp >> 18)); PB(0x80 | ((cp >> 12) & 0x3F)); PB(0x80 | ((cp >> 6) & 0x3F)); PB(0x80 | (cp & 0x3F)); }
                } break;
                default: break;
            }
        } else PB(c);
    }
    j->p++;
#undef PB
    b[len] = 0; return b;
}

static JV *jparse(JP *j) {
    jskip(j);
    char c = *j->p;
    if (c == '{') {
        j->p++; JV *o = jnew(5); jskip(j);
        if (*j->p == '}') { j->p++; return o; }
        for (;;) {
            jskip(j); char *k = jparse_string_raw(j); jskip(j); j->p++; /* ':' */
            JV *v = jparse(j); jadd(o, k, v); jskip(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == '}') { j->p++; break; }
        }
        return o;
    }
    if (c == '[') {
        j->p++; JV *a = jnew(4); jskip(j);
        if (*j->p == ']') { j->p++; return a; }
        for (;;) {
            JV *v = jparse(j); jadd(a, NULL, v); jskip(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == ']') { j->p++; break; }
        }
        return a;
    }
    if (c == '"') { JV *v = jnew(3); v->s = jparse_string_raw(j); return v; }
    if (!strncmp(j->p, "true", 4)) { j->p += 4; JV *v = jnew(1); v->s = strdup("true"); return v; }
    if (!strncmp(j->p, "false", 5)) { j->p += 5; JV *v = jnew(1); v->s = strdup("false"); return v; }
    if (!strncmp(j->p, "null", 4)) { j->p += 4; return jnew(0); }
    const char *st = j->p;
    while (*j->p && strchr("0123456789+-.eE", *j->p)) j->p++;
    JV *v = jnew(2); size_t n = (size_t)(j->p - st);
    v->s = malloc(n + 1); memcpy(v->s, st, n); v->s[n] = 0; return v;
}

static JV *jget(JV *o, const char *k) {
    if (!o || o->type != 5) return NULL;
    for (int i = 0; i < o->n; i++) if (o->keys[i] && !strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}

/* ---------- encoding helpers ---------- */
static char *b64(const unsigned char *in, size_t n) {
    static const char *A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    char *o = malloc(((n + 2) / 3) * 4 + 1); size_t j = 0;
    for (size_t i = 0; i < n; i += 3) {
        unsigned v = (unsigned)in[i] << 16 | (i + 1 < n ? (unsigned)in[i + 1] << 8 : 0) | (i + 2 < n ? in[i + 2] : 0);
        o[j++] = A[(v >> 18) & 63]; o[j++] = A[(v >> 12) & 63];
        o[j++] = (i + 1 < n) ? A[(v >> 6) & 63] : '=';
        o[j++] = (i + 2 < n) ? A[v & 63] : '=';
    }
    o[j] = 0; return o;
}

static char *form_encode(const char *s) {
    size_t cap = strlen(s) * 3 + 4, len = 0; char *o = malloc(cap);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '*') o[len++] = (char)c;
        else if (c == ' ') o[len++] = '+';
        else len += (size_t)sprintf(o + len, "%%%02X", c);
    }
    o[len] = 0; return o;
}

static char *pct_encode(const char *s) {
    size_t cap = strlen(s) * 3 + 4, len = 0; char *o = malloc(cap);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '~') o[len++] = (char)c;
        else len += (size_t)sprintf(o + len, "%%%02X", c);
    }
    o[len] = 0; return o;
}

/* ---------- HTTP ---------- */
typedef struct { int code; char *hdrs; char *body; } Resp;

static char *header_get(const char *hdrs, const char *name) {
    size_t nl = strlen(name);
    const char *p = hdrs;
    while (p && *p) {
        const char *e = strstr(p, "\r\n");
        size_t ll = e ? (size_t)(e - p) : strlen(p);
        if (ll > nl && p[nl] == ':' && strncasecmp(p, name, nl) == 0) {
            const char *v = p + nl + 1; while (v < p + ll && *v == ' ') v++;
            size_t vl = (size_t)(p + ll - v);
            char *o = malloc(vl + 1); memcpy(o, v, vl); o[vl] = 0; return o;
        }
        p = e ? e + 2 : NULL;
    }
    return NULL;
}

static char *dechunk(const char *b, size_t *outlen) {
    size_t cap = 8192, len = 0; char *o = malloc(cap);
    const char *p = b;
    for (;;) {
        char *end; unsigned long long sz = strtoull(p, &end, 16);
        if (end == p) break;
        p = end;
        if (*p == ';') { while (*p && *p != '\r') p++; }
        if (p[0] == '\r' && p[1] == '\n') p += 2;
        if (sz == 0) break;
        if (len + sz + 1 > cap) { cap = len + sz + 1; o = realloc(o, cap); }
        memcpy(o + len, p, sz); len += sz; p += sz;
        if (p[0] == '\r' && p[1] == '\n') p += 2;
    }
    o[len] = 0; *outlen = len; return o;
}

static Resp *http_req(const char *method, const char *path, const char *hdrs, const char *body) {
    size_t bl = body ? strlen(body) : 0;
    char *req = malloc(strlen(method) + strlen(path) + strlen(g_hostport) + strlen(hdrs) + bl + 256);
    sprintf(req, "%s %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n%s", method, path, g_hostport, hdrs);
    if (body) sprintf(req + strlen(req), "Content-Length: %zu\r\n", bl);
    strcat(req, "\r\n");
    if (body) strcat(req, body);
    size_t rl = strlen(req);

    struct addrinfo hints; memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; hints.ai_socktype = SOCK_STREAM;
    struct addrinfo *res;
    if (getaddrinfo(g_host, g_port, &hints, &res) != 0) exit(1);
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) exit(1);
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) exit(1);
    freeaddrinfo(res);

    size_t off = 0;
    while (off < rl) {
        ssize_t w = send(fd, req + off, rl - off, 0);
        if (w <= 0) exit(1);
        off += (size_t)w;
    }

    size_t cap = 65536, len = 0; char *buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
        ssize_t r = recv(fd, buf + len, cap - len - 1, 0);
        if (r <= 0) break;
        len += (size_t)r;
    }
    buf[len] = 0; close(fd);

    Resp *rp = malloc(sizeof(Resp));
    rp->code = atoi(buf + 9);
    const char *hb = strstr(buf, "\r\n");
    hb = hb ? hb + 2 : buf;
    const char *bend = strstr(hb, "\r\n\r\n");
    const char *bodystart; size_t hlen;
    if (bend) { hlen = (size_t)(bend - hb); bodystart = bend + 4; }
    else { hlen = strlen(hb); bodystart = hb + hlen; }
    rp->hdrs = malloc(hlen + 1); memcpy(rp->hdrs, hb, hlen); rp->hdrs[hlen] = 0;
    size_t restlen = len - (size_t)(bodystart - buf);

    char *te = header_get(rp->hdrs, "Transfer-Encoding");
    char *cl = header_get(rp->hdrs, "Content-Length");
    int chunked = 0;
    if (te) {
        char *l = strdup(te); for (char *q = l; *q; q++) *q = (char)tolower((unsigned char)*q);
        chunked = strstr(l, "chunked") != NULL; free(l);
    }
    if (chunked) {
        rp->body = dechunk(bodystart, &restlen);
    } else if (cl) {
        size_t n = (size_t)strtoul(cl, NULL, 10);
        if (n > restlen) n = restlen;
        rp->body = malloc(n + 1); memcpy(rp->body, bodystart, n); rp->body[n] = 0;
    } else {
        rp->body = malloc(restlen + 1); memcpy(rp->body, bodystart, restlen); rp->body[restlen] = 0;
    }
    return rp;
}

/* ---------- aggregation ---------- */
typedef struct { char *name, *cur; long long cents; } Tot;
static Tot *tots = NULL; static int nt = 0, ctot = 0;
static void add_tot(const char *name, const char *cur, long long c) {
    for (int i = 0; i < nt; i++)
        if (!strcmp(tots[i].name, name) && !strcmp(tots[i].cur, cur)) { tots[i].cents += c; return; }
    if (nt == ctot) { ctot = ctot ? ctot * 2 : 16; tots = realloc(tots, (size_t)ctot * sizeof(Tot)); }
    tots[nt].name = strdup(name); tots[nt].cur = strdup(cur); tots[nt].cents = c; nt++;
}
typedef struct { char *st; long long cnt; } Stc;
static Stc *sts = NULL; static int ns = 0, cst = 0;
static void add_status(const char *st) {
    for (int i = 0; i < ns; i++)
        if (!strcmp(sts[i].st, st)) { sts[i].cnt++; return; }
    if (ns == cst) { cst = cst ? cst * 2 : 16; sts = realloc(sts, (size_t)cst * sizeof(Stc)); }
    sts[ns].st = strdup(st); sts[ns].cnt = 1; ns++;
}

static long long amount_cents(const char *s) {
    long long sign = 1;
    if (*s == '-') { sign = -1; s++; }
    long long ip = 0;
    while (isdigit((unsigned char)*s)) ip = ip * 10 + (*s++ - '0');
    long long c = ip * 100;
    if (*s == '.') {
        s++; int d = 0; long long frac = 0;
        while (isdigit((unsigned char)*s) && d < 2) { frac = frac * 10 + (*s++ - '0'); d++; }
        if (d == 1) frac *= 10;
        c += frac;
    }
    return sign * c;
}

static int cmp_tot(const void *a, const void *b) {
    const Tot *x = a, *y = b;
    int c = strcmp(x->name, y->name);
    if (c) return c;
    return strcmp(x->cur, y->cur);
}
static int cmp_st(const void *a, const void *b) {
    const Stc *x = a, *y = b;
    return strcmp(x->st, y->st);
}

/* ---------- misc ---------- */
static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) exit(1);
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if (fread(b, 1, (size_t)n, f) != (size_t)n) exit(1);
    b[n] = 0; fclose(f); return b;
}

static char *get_token(const char *cid, const char *csec, const char *scope) {
    char *es = form_encode(scope), *eid = form_encode(cid), *esc = form_encode(csec);
    char *cred = malloc(strlen(eid) + strlen(esc) + 2);
    sprintf(cred, "%s:%s", eid, esc);
    char *b = b64((const unsigned char *)cred, strlen(cred));
    char *ahdr = malloc(strlen(b) + 64);
    sprintf(ahdr, "Authorization: Basic %s\r\nContent-Type: application/x-www-form-urlencoded\r\n", b);
    char *body = malloc(strlen(es) + 64);
    sprintf(body, "grant_type=client_credentials&scope=%s", es);
    char *path = malloc(strlen(g_prefix) + 32);
    sprintf(path, "%s/oauth/token", g_prefix);
    Resp *r = http_req("POST", path, ahdr, body);
    if (r->code != 200) fatal(r->code, r->body);
    JP j = { r->body };
    JV *v = jparse(&j);
    JV *at = jget(v, "access_token");
    if (!at || at->type != 3) exit(1);
    return strdup(at->s);
}

int main(int argc, char **argv) {
    if (argc != 3) return 1;
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    if (strncmp(base_url, "http://", 7) != 0) return 1;
    const char *u = base_url + 7;
    const char *slash = strchr(u, '/');
    if (slash) { g_hostport = strndup(u, (size_t)(slash - u)); g_prefix = strdup(slash); }
    else { g_hostport = strdup(u); g_prefix = strdup(""); }
    char *colon = strrchr(g_hostport, ':');
    if (colon) { g_port = strdup(colon + 1); g_host = strndup(g_hostport, (size_t)(colon - g_hostport)); }
    else { g_host = strdup(g_hostport); g_port = strdup("80"); }

    char *cpath = malloc(strlen(data_dir) + 32);
    sprintf(cpath, "%s/client.json", data_dir);
    char *cfg = read_file(cpath);
    JP cj = { cfg };
    JV *cv = jparse(&cj);
    JV *jcid = jget(cv, "client_id"), *jcsec = jget(cv, "client_secret"),
       *jscope = jget(cv, "scope"), *jps = jget(cv, "page_size");
    if (!jcid || !jcsec || !jscope || !jps) return 1;
    const char *cid = jcid->s, *csec = jcsec->s, *scope = jscope->s;
    int page_size = atoi(jps->s);

    int N = 0, P = 0, R = 0, A = 0;
    char *cursor = NULL;
    int fresh = 1;
    char *token = get_token(cid, csec, scope);

    for (;;) {
        char *path = malloc(strlen(g_prefix) + 64 + (cursor ? strlen(cursor) * 3 + 16 : 0));
        if (cursor) {
            char *ec = pct_encode(cursor);
            sprintf(path, "%s/orders?limit=%d&cursor=%s", g_prefix, page_size, ec);
            free(ec);
        } else {
            sprintf(path, "%s/orders?limit=%d", g_prefix, page_size);
        }
        char *ah = malloc(strlen(token) + 32);
        sprintf(ah, "Authorization: Bearer %s\r\n", token);
        Resp *r = http_req("GET", path, ah, NULL);

        if (r->code == 429) {
            R++;
            char *ra = header_get(r->hdrs, "Retry-After");
            if (ra) sleep((unsigned)atoi(ra));
            continue;
        }
        if (r->code == 503) { R++; continue; }
        if (r->code == 401) {
            if (fresh) fatal(r->code, r->body);
            A++;
            token = get_token(cid, csec, scope);
            fresh = 1;
            continue;
        }
        if (r->code != 200) fatal(r->code, r->body);

        fresh = 0; P++;
        JP j = { r->body };
        JV *v = jparse(&j);
        JV *data = jget(v, "data");
        if (data && data->type == 4) {
            for (int i = 0; i < data->n; i++) {
                JV *o = data->items[i];
                N++;
                JV *st = jget(o, "status");
                if (st && st->type == 3) add_status(st->s);
                JV *cust = jget(o, "customer");
                JV *amt = jget(o, "amount"), *cur = jget(o, "currency");
                JV *nm = cust ? jget(cust, "name") : NULL;
                if (nm && amt && cur && st && st->type == 3 && strcmp(st->s, "cancelled"))
                    add_tot(nm->s, cur->s, amount_cents(amt->s));
            }
        }
        JV *nc = jget(v, "next_cursor");
        if (nc && nc->type == 3) cursor = strdup(nc->s);
        else break;
    }

    qsort(tots, (size_t)nt, sizeof(Tot), cmp_tot);
    for (int i = 0; i < nt; i++) {
        long long v = tots[i].cents;
        unsigned long long a = v < 0 ? (unsigned long long)(-v) : (unsigned long long)v;
        printf("total %s %s%llu.%02llu %s\n", tots[i].cur, v < 0 ? "-" : "", a / 100, a % 100, tots[i].name);
    }
    qsort(sts, (size_t)ns, sizeof(Stc), cmp_st);
    for (int i = 0; i < ns; i++)
        printf("status %s %lld\n", sts[i].st, sts[i].cnt);
    printf("orders %d pages %d retries %d reauth %d\n", N, P, R, A);
    return 0;
}

import sys, os, re, struct, zlib
from decimal import Decimal


def read_varint(buf, off):
    result = 0
    for _ in range(8):
        b = buf[off]
        off += 1
        result = (result << 7) | (b & 0x7F)
        if not (b & 0x80):
            return result, off
    b = buf[off]
    off += 1
    result = (result << 8) | b
    return result, off


def to_signed64(v):
    if v >= 1 << 63:
        v -= 1 << 64
    return v


class DB:
    def __init__(self, path):
        self.data = open(path, 'rb').read()
        ps = struct.unpack('>H', self.data[16:18])[0]
        self.page_size = 65536 if ps == 1 else ps
        self.reserved = self.data[20]
        self.usable = self.page_size - self.reserved

    def page(self, n):
        return self.data[(n - 1) * self.page_size: n * self.page_size]

    def read_payload(self, pg, off, P):
        U = self.usable
        X = U - 35
        if P <= X:
            return bytes(pg[off:off + P])
        M = ((U - 12) * 32) // 255 - 23
        K = M + (P - M) % (U - 4)
        local = K if K <= X else M
        result = bytearray(pg[off:off + local])
        next_pg = struct.unpack('>I', pg[off + local:off + local + 4])[0]
        remaining = P - local
        while remaining > 0 and next_pg:
            opg = self.page(next_pg)
            next_pg = struct.unpack('>I', opg[:4])[0]
            take = min(remaining, U - 4)
            result += opg[4:4 + take]
            remaining -= take
        return bytes(result)

    def walk_table(self, root):
        rows = []
        stack = [root]
        while stack:
            p = stack.pop()
            pg = self.page(p)
            hdr = 100 if p == 1 else 0
            ptype = pg[hdr]
            ncells = struct.unpack('>H', pg[hdr + 3:hdr + 5])[0]
            cell_base = hdr + (12 if ptype == 5 else 8)
            if ptype == 5:
                stack.append(struct.unpack('>I', pg[hdr + 8:hdr + 12])[0])
                for i in range(ncells):
                    off = struct.unpack('>H', pg[cell_base + 2 * i:cell_base + 2 * i + 2])[0]
                    stack.append(struct.unpack('>I', pg[off:off + 4])[0])
            elif ptype == 13:
                for i in range(ncells):
                    off = struct.unpack('>H', pg[cell_base + 2 * i:cell_base + 2 * i + 2])[0]
                    P, o = read_varint(pg, off)
                    rowid, o = read_varint(pg, o)
                    rowid = to_signed64(rowid)
                    rows.append((rowid, self.read_payload(pg, o, P)))
        rows.sort()
        return rows


def decode_record(payload):
    hlen, o = read_varint(payload, 0)
    types = []
    while o < hlen:
        t, o = read_varint(payload, o)
        types.append(t)
    vals = []
    body = hlen
    for t in types:
        if t == 0:
            vals.append(None)
        elif 1 <= t <= 6:
            n = {1: 1, 2: 2, 3: 3, 4: 4, 5: 6, 6: 8}[t]
            vals.append(int.from_bytes(payload[body:body + n], 'big', signed=True))
            body += n
        elif t == 7:
            vals.append(struct.unpack('>d', payload[body:body + 8])[0])
            body += 8
        elif t == 8:
            vals.append(0)
        elif t == 9:
            vals.append(1)
        elif t >= 12 and t % 2 == 0:
            n = (t - 12) // 2
            vals.append(('blob', payload[body:body + n]))
            body += n
        else:
            n = (t - 13) // 2
            vals.append(('text', payload[body:body + n]))
            body += n
    return vals


def esc_text(data):
    s = data.decode('utf-8')
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '"':
            out.append('\\"')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20 or o == 0x7F:
            out.append('\\x%02X' % o)
        else:
            out.append(ch)
    return ''.join(out)


def fmt_real(x):
    s = format(Decimal(x), 'f')
    if '.' in s:
        s = s.rstrip('0')
        if s.endswith('.'):
            s += '0'
    else:
        s += '.0'
    return s


def fmt_value(v):
    if v is None:
        return 'NULL'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return fmt_real(v)
    kind, data = v
    if kind == 'text':
        if len(data) <= 100:
            return '"' + esc_text(data) + '"'
        return '<TEXT len=%d crc32=%08x>' % (len(data), zlib.crc32(data) & 0xFFFFFFFF)
    else:
        if len(data) <= 100:
            return "X'" + data.hex().upper() + "'"
        return '<BLOB len=%d crc32=%08x>' % (len(data), zlib.crc32(data) & 0xFFFFFFFF)


def parse_columns(sql):
    n = len(sql)
    j = re.search(r'\bTABLE\b', sql, re.I).end()
    while j < n and sql[j] in ' \t\r\n':
        j += 1
    if j < n and sql[j] == '"':
        j += 1
        while j < n and sql[j] != '"':
            j += 1
        j += 1
    else:
        while j < n and sql[j] not in ' \t\r\n(':
            j += 1
    while j < n and sql[j] != '(':
        j += 1
    depth = 0
    start = j + 1
    defs = []
    k = j
    while k < n:
        c = sql[k]
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth == 0:
                defs.append(sql[start:k])
                break
        elif c == ',' and depth == 1:
            defs.append(sql[start:k])
            start = k + 1
        k += 1
    cols = []
    aliases = []
    for d in defs:
        d = d.strip()
        if d.startswith('"'):
            e = d.index('"', 1)
            name = d[1:e]
            rest = d[e + 1:]
        else:
            m = re.match(r'[^\s(,]+', d)
            name = m.group(0)
            rest = d[m.end():]
        alias = (re.match(r'\s*INTEGER\b', rest, re.I) is not None
                 and re.match(r'\s*INTEGER\s*\(', rest, re.I) is None
                 and re.search(r'\bPRIMARY\s+KEY\b', rest, re.I) is not None)
        cols.append(name)
        aliases.append(alias)
    return cols, aliases


def as_str(v):
    return v[1].decode('utf-8') if isinstance(v, tuple) else v


def main():
    db = DB(os.path.join(sys.argv[1], 'db.sqlite'))
    schema_rows = db.walk_table(1)
    tables = []
    for rowid, payload in schema_rows:
        vals = decode_record(payload)
        vals += [None] * (5 - len(vals))
        typ, name, tbl_name, rootpage, sql = vals[:5]
        if as_str(typ) == 'table':
            name_s = as_str(name)
            if not name_s.startswith('sqlite_'):
                tables.append((name_s.encode('utf-8'), name_s, rootpage, as_str(sql)))
    tables.sort(key=lambda t: t[0])
    out = []
    for idx, (nb, name, rootpage, sql) in enumerate(tables):
        cols, aliases = parse_columns(sql)
        rows = db.walk_table(rootpage)
        if idx:
            out.append('')
        out.append('TABLE %s rows=%d' % (name, len(rows)))
        out.append('COLUMNS ' + ', '.join(cols))
        for rowid, payload in rows:
            vals = decode_record(payload)
            parts = []
            for ci in range(len(cols)):
                if aliases[ci]:
                    parts.append(str(rowid))
                else:
                    v = vals[ci] if ci < len(vals) else None
                    parts.append(fmt_value(v))
            out.append('%d: %s' % (rowid, ', '.join(parts)))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))
    sys.exit(0)


if __name__ == '__main__':
    main()

import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.zip.CRC32;

public class Main {
    static byte[] data;
    static int pageSize, usable;
    static OutputStream out;

    static final class Txt { final byte[] b; Txt(byte[] b){this.b=b;} }
    static final class Row { final long rowid; final Object[] v; Row(long r, Object[] v){this.rowid=r;this.v=v;} }
    static final class Col { final String name; final boolean alias; Col(String n, boolean a){name=n;alias=a;} }
    static final class Table {
        final String name; final byte[] nb; final long root; final List<Col> cols;
        Table(String name, byte[] nb, long root, List<Col> cols){this.name=name;this.nb=nb;this.root=root;this.cols=cols;}
    }

    public static void main(String[] args) throws Exception {
        data = Files.readAllBytes(Path.of(args[0]).resolve("db.sqlite"));
        int ps = ((data[16]&0xFF)<<8) | (data[17]&0xFF);
        pageSize = (ps==1) ? 65536 : ps;
        usable = pageSize - (data[20]&0xFF);
        out = new BufferedOutputStream(System.out);

        List<Row> schema = new ArrayList<>();
        walkTable(1, schema);
        List<Table> tables = new ArrayList<>();
        for (Row r : schema) {
            Object[] v = r.v;
            if (v.length < 5) continue;
            String type = txt(v[0]);
            if (!"table".equals(type)) continue;
            String name = txt(v[1]);
            if (name == null || name.startsWith("sqlite_")) continue;
            if (!(v[3] instanceof Long root)) continue;
            if (!(v[4] instanceof Txt sqlT)) continue;
            String sql = new String(sqlT.b, StandardCharsets.UTF_8);
            tables.add(new Table(name, name.getBytes(StandardCharsets.UTF_8), root, parseCols(sql)));
        }
        tables.sort((a,b)->Arrays.compare(a.nb, b.nb));
        boolean first = true;
        for (Table t : tables) {
            if (!first) wStr("\n");
            first = false;
            List<Row> rows = new ArrayList<>();
            walkTable((int)t.root, rows);
            rows.sort(Comparator.comparingLong(r -> r.rowid));
            wStr("TABLE " + t.name + " rows=" + rows.size() + "\n");
            StringBuilder sb = new StringBuilder("COLUMNS");
            for (int i=0;i<t.cols.size();i++) sb.append(i==0 ? " " : ", ").append(t.cols.get(i).name);
            wStr(sb + "\n");
            for (Row r : rows) {
                wStr(r.rowid + ":");
                for (int i=0;i<t.cols.size();i++) {
                    wStr(i==0 ? " " : ", ");
                    Object v = i < r.v.length ? r.v[i] : null;
                    writeValue(v, r.rowid, t.cols.get(i));
                }
                wStr("\n");
            }
        }
        out.flush();
    }

    static void walkTable(int page, List<Row> rows) {
        long off = (long)(page-1)*pageSize;
        int hdr = (page==1) ? 100 : 0;
        int type = data[(int)(off+hdr)] & 0xFF;
        int nCells = ((data[(int)(off+hdr+3)]&0xFF)<<8) | (data[(int)(off+hdr+4)]&0xFF);
        if (type == 5) {
            for (int i=0;i<nCells;i++) {
                int cp = cellPtr(off, hdr+12, i);
                walkTable(int4(off+cp), rows);
            }
            walkTable(int4(off+hdr+8), rows);
        } else if (type == 13) {
            for (int i=0;i<nCells;i++) {
                int cp = cellPtr(off, hdr+8, i);
                long p = off + cp;
                long[] vr = varintFile(p); long P = vr[0]; p = vr[1];
                vr = varintFile(p); long rowid = vr[0]; p = vr[1];
                rows.add(new Row(rowid, parseRecord(readPayload(p, P))));
            }
        }
    }

    static int cellPtr(long pageOff, int base, int i) {
        int o = (int)(pageOff + base + 2*i);
        return ((data[o]&0xFF)<<8) | (data[o+1]&0xFF);
    }

    static int int4(long off) {
        int o = (int)off;
        return ((data[o]&0xFF)<<24)|((data[o+1]&0xFF)<<16)|((data[o+2]&0xFF)<<8)|(data[o+3]&0xFF);
    }

    static long[] varintFile(long off) {
        long result = 0;
        for (int i=0;i<8;i++) {
            int b = data[(int)off++] & 0xFF;
            result = (result<<7) | (b & 0x7F);
            if ((b&0x80)==0) return new long[]{result, off};
        }
        result = (result<<8) | (data[(int)off++] & 0xFF);
        return new long[]{result, off};
    }

    static long[] varintArr(byte[] b, int off) {
        long result = 0;
        int i = off;
        for (int k=0;k<8;k++) {
            int by = b[i++] & 0xFF;
            result = (result<<7) | (by & 0x7F);
            if ((by&0x80)==0) return new long[]{result, i};
        }
        result = (result<<8) | (b[i++] & 0xFF);
        return new long[]{result, i};
    }

    static byte[] readPayload(long p, long P) {
        long X = usable - 35;
        int local;
        if (P <= X) local = (int)P;
        else {
            long M = ((usable-12)*32)/255 - 23;
            long K = M + ((P - M) % (usable - 4));
            local = (int)((K <= X) ? K : M);
        }
        byte[] payload = new byte[(int)P];
        System.arraycopy(data, (int)p, payload, 0, local);
        long remaining = P - local;
        long nextPtrLoc = p + local;
        int dst = local;
        while (remaining > 0) {
            int op = int4(nextPtrLoc);
            long ooff = (long)(op-1)*pageSize;
            int chunk = (int)Math.min(remaining, usable - 4);
            System.arraycopy(data, (int)(ooff+4), payload, dst, chunk);
            dst += chunk; remaining -= chunk;
            nextPtrLoc = ooff;
        }
        return payload;
    }

    static Object[] parseRecord(byte[] pl) {
        long[] r = varintArr(pl, 0);
        int hdrSize = (int)r[0];
        int pos = (int)r[1];
        List<Object> vals = new ArrayList<>();
        int body = hdrSize;
        while (pos < hdrSize) {
            r = varintArr(pl, pos); pos = (int)r[1];
            long st = r[0];
            Object v = null;
            if (st >= 1 && st <= 6) {
                int n = new int[]{1,2,3,4,6,8}[(int)(st-1)];
                v = signed(pl, body, n); body += n;
            } else if (st == 7) {
                long bits = 0;
                for (int k=0;k<8;k++) bits = (bits<<8) | (pl[body+k]&0xFFL);
                v = Double.longBitsToDouble(bits); body += 8;
            } else if (st == 8) v = 0L;
            else if (st == 9) v = 1L;
            else if (st >= 12) {
                int n = (int)((st - ((st%2==0)?12:13)) / 2);
                byte[] b = Arrays.copyOfRange(pl, body, body+n); body += n;
                v = (st%2==0) ? (Object)b : (Object)new Txt(b);
            }
            vals.add(v);
        }
        return vals.toArray();
    }

    static long signed(byte[] b, int off, int n) {
        long r = 0;
        for (int i=0;i<n;i++) r = (r<<8) | (b[off+i]&0xFFL);
        return r << (64-8*n) >> (64-8*n);
    }

    static String txt(Object v) { return v instanceof Txt t ? new String(t.b, StandardCharsets.UTF_8) : null; }

    static List<Col> parseCols(String sql) {
        int n = sql.length();
        int i = 0;
        i = skipWs(sql, i);
        i = expectWord(sql, i, "CREATE");
        i = skipWs(sql, i);
        i = expectWord(sql, i, "TABLE");
        i = skipWs(sql, i);
        if (i<n && sql.charAt(i)=='"') { i++; while (i<n && sql.charAt(i)!='"') i++; i++; }
        else while (i<n && isIdent(sql.charAt(i))) i++;
        i = skipWs(sql, i);
        if (i<n && sql.charAt(i)=='(') i++;
        List<String> defs = new ArrayList<>();
        int depth = 0, start = i;
        while (i < n) {
            char c = sql.charAt(i);
            if (c=='"') { i++; while (i<n && sql.charAt(i)!='"') i++; i++; continue; }
            if (c=='(') depth++;
            else if (c==')') { if (depth==0) break; depth--; }
            else if (c==',' && depth==0) { defs.add(sql.substring(start,i)); start=i+1; }
            i++;
        }
        if (start < i) defs.add(sql.substring(start,i));
        List<Col> cols = new ArrayList<>();
        for (String def : defs) {
            def = def.trim();
            if (def.isEmpty()) continue;
            String name;
            int j = 0;
            if (def.charAt(0)=='"') {
                j = 1;
                StringBuilder sb = new StringBuilder();
                while (j<def.length() && def.charAt(j)!='"') { sb.append(def.charAt(j)); j++; }
                j++;
                name = sb.toString();
            } else {
                while (j<def.length() && isIdent(def.charAt(j))) j++;
                name = def.substring(0,j);
            }
            String rest = def.substring(Math.min(j, def.length())).trim();
            cols.add(new Col(name, isRowidAlias(rest)));
        }
        return cols;
    }

    static boolean isRowidAlias(String rest) {
        int j = 0;
        while (j<rest.length() && Character.isLetter(rest.charAt(j))) j++;
        if (j==0 || !rest.substring(0,j).equalsIgnoreCase("INTEGER")) return false;
        if (j<rest.length() && rest.charAt(j)=='(') return false;
        return Pattern.compile("PRIMARY\\s+KEY", Pattern.CASE_INSENSITIVE).matcher(rest.substring(j)).find();
    }

    static int skipWs(String s, int i) {
        while (i<s.length()) {
            char c = s.charAt(i);
            if (c==' '||c=='\t'||c=='\r'||c=='\n'||c=='\f') i++; else break;
        }
        return i;
    }

    static int expectWord(String s, int i, String w) {
        if (!s.regionMatches(true, i, w, 0, w.length())) throw new RuntimeException("bad sql");
        return i + w.length();
    }

    static boolean isIdent(char c) {
        return Character.isLetterOrDigit(c) || c=='_' || c=='$' || c > 127;
    }

    static String fmtReal(double d) {
        String s = new BigDecimal(d).toPlainString();
        int dot = s.indexOf('.');
        if (dot < 0) return s + ".0";
        int end = s.length();
        while (end > dot+2 && s.charAt(end-1)=='0') end--;
        return s.substring(0, end);
    }

    static void writeValue(Object v, long rowid, Col col) throws IOException {
        if (col.alias) { wStr(Long.toString(rowid)); return; }
        if (v == null) { wStr("NULL"); return; }
        if (v instanceof Long l) { wStr(l.toString()); return; }
        if (v instanceof Double d) { wStr(fmtReal(d)); return; }
        byte[] b; boolean isText;
        if (v instanceof Txt t) { b = t.b; isText = true; }
        else { b = (byte[])v; isText = false; }
        if (b.length <= 100) {
            if (isText) {
                wByte('"');
                for (byte x : b) {
                    int c = x & 0xFF;
                    if (c=='\\') wStr("\\\\");
                    else if (c=='"') wStr("\\\"");
                    else if (c=='\n') wStr("\\n");
                    else if (c=='\r') wStr("\\r");
                    else if (c=='\t') wStr("\\t");
                    else if (c<0x20 || c==0x7F) wStr("\\x" + String.format("%02X", c));
                    else wByte(c);
                }
                wByte('"');
            } else {
                StringBuilder sb = new StringBuilder("X'");
                for (byte x : b) sb.append(String.format("%02X", x));
                sb.append('\'');
                wStr(sb.toString());
            }
        } else {
            CRC32 crc = new CRC32();
            crc.update(b);
            wStr("<" + (isText?"TEXT":"BLOB") + " len=" + b.length + " crc32=" + String.format("%08x", crc.getValue()) + ">");
        }
    }

    static void wStr(String s) throws IOException { out.write(s.getBytes(StandardCharsets.UTF_8)); }
    static void wByte(int b) throws IOException { out.write(b); }
}

import Foundation

var d: [UInt8] = []
var pageSize = 0
var usableSize = 0

func u16(_ i: Int) -> Int { Int(d[i]) << 8 | Int(d[i + 1]) }
func u32(_ i: Int) -> UInt32 {
    (UInt32(d[i]) << 24) | (UInt32(d[i+1]) << 16) | (UInt32(d[i+2]) << 8) | UInt32(d[i+3])
}

func readVarint(_ a: [UInt8], _ i: Int) -> (UInt64, Int) {
    var result: UInt64 = 0
    var k = i
    for _ in 0..<8 {
        let b = a[k]; k += 1
        result = (result << 7) | UInt64(b & 0x7F)
        if b & 0x80 == 0 { return (result, k) }
    }
    result = (result << 8) | UInt64(a[k]); k += 1
    return (result, k)
}

func signedInt(_ a: [UInt8], _ off: Int, _ n: Int) -> Int64 {
    var v: UInt64 = 0
    for k in 0..<n { v = (v << 8) | UInt64(a[off + k]) }
    let sh = 64 - 8 * n
    return Int64(bitPattern: v << UInt64(sh)) >> sh
}

enum Value { case null, int(Int64), real(Double), text([UInt8]), blob([UInt8]) }

func decodeRecord(_ payload: [UInt8]) -> [Value] {
    var vals: [Value] = []
    guard !payload.isEmpty else { return vals }
    let (hdrLen, p0) = readVarint(payload, 0)
    var hp = p0
    var body = Int(hdrLen)
    while hp < Int(hdrLen) {
        let (st, nhp) = readVarint(payload, hp)
        hp = nhp
        let t = Int(st)
        switch t {
        case 0: vals.append(.null)
        case 1: vals.append(.int(signedInt(payload, body, 1))); body += 1
        case 2: vals.append(.int(signedInt(payload, body, 2))); body += 2
        case 3: vals.append(.int(signedInt(payload, body, 3))); body += 3
        case 4: vals.append(.int(signedInt(payload, body, 4))); body += 4
        case 5: vals.append(.int(signedInt(payload, body, 6))); body += 6
        case 6: vals.append(.int(signedInt(payload, body, 8))); body += 8
        case 7:
            var bits: UInt64 = 0
            for k in 0..<8 { bits = (bits << 8) | UInt64(payload[body + k]) }
            vals.append(.real(Double(bitPattern: bits))); body += 8
        case 8: vals.append(.int(0))
        case 9: vals.append(.int(1))
        default:
            let len = (t - 12) / 2
            let bytes = Array(payload[body..<body+len])
            body += len
            vals.append(t % 2 == 0 ? .blob(bytes) : .text(bytes))
        }
    }
    return vals
}

func walkTable(root: UInt32) -> [(Int64, [UInt8])] {
    var rows: [(Int64, [UInt8])] = []
    func walk(_ pageNo: UInt32) {
        let base = (Int(pageNo) - 1) * pageSize
        let h = base + (pageNo == 1 ? 100 : 0)
        let type = d[h]
        let nCells = u16(h + 3)
        if type == 5 {
            for c in 0..<nCells {
                let off = u16(h + 12 + 2 * c)
                walk(u32(base + off))
            }
            walk(u32(h + 8))
        } else if type == 13 {
            let X = usableSize - 35
            let M = ((usableSize - 12) * 32 / 255) - 23
            for c in 0..<nCells {
                let off = u16(h + 8 + 2 * c)
                var p = base + off
                let (plen, p1) = readVarint(d, p); p = p1
                let (rid, p2) = readVarint(d, p); p = p2
                let P = Int(plen)
                var payload: [UInt8]
                if P <= X {
                    payload = Array(d[p..<p+P])
                } else {
                    let K = M + (P - M) % (usableSize - 4)
                    let L = K <= X ? K : M
                    payload = Array(d[p..<p+L])
                    var next = u32(p + L)
                    while payload.count < P && next != 0 {
                        let pb = (Int(next) - 1) * pageSize
                        next = u32(pb)
                        let avail = min(usableSize - 4, P - payload.count)
                        payload.append(contentsOf: d[(pb+4)..<(pb+4+avail)])
                    }
                }
                rows.append((Int64(bitPattern: rid), payload))
            }
        }
    }
    walk(root)
    return rows
}

let crcTable: [UInt32] = {
    (0..<256).map { i -> UInt32 in
        var c = UInt32(i)
        for _ in 0..<8 { c = (c & 1) != 0 ? 0xEDB88320 ^ (c >> 1) : c >> 1 }
        return c
    }
}()

func crc32(_ b: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for x in b { c = crcTable[Int((c ^ UInt32(x)) & 0xFF)] ^ (c >> 8) }
    return c ^ 0xFFFFFFFF
}

func escText(_ b: [UInt8]) -> String {
    var out: [UInt8] = [0x22]
    for byte in b {
        switch byte {
        case 0x5C: out.append(contentsOf: [0x5C, 0x5C])
        case 0x22: out.append(contentsOf: [0x5C, 0x22])
        case 0x0A: out.append(contentsOf: [0x5C, 0x6E])
        case 0x0D: out.append(contentsOf: [0x5C, 0x72])
        case 0x09: out.append(contentsOf: [0x5C, 0x74])
        default:
            if byte < 0x20 || byte == 0x7F {
                out.append(contentsOf: Array(String(format: "\\x%02X", byte).utf8))
            } else {
                out.append(byte)
            }
        }
    }
    out.append(0x22)
    return String(decoding: out, as: UTF8.self)
}

func fmtReal(_ v: Double) -> String {
    var s = String(format: "%.8f", locale: Locale(identifier: "en_US_POSIX"), v)
    while s.hasSuffix("0") && s[s.index(s.endIndex, offsetBy: -2)] != "." {
        s.removeLast()
    }
    return s
}

func format(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .int(let n): return String(n)
    case .real(let x): return fmtReal(x)
    case .text(let b):
        if b.count <= 100 { return escText(b) }
        return "<TEXT len=\(b.count) crc32=\(String(format: "%08x", crc32(b)))>"
    case .blob(let b):
        if b.count <= 100 { return "X'" + b.map { String(format: "%02X", $0) }.joined() + "'" }
        return "<BLOB len=\(b.count) crc32=\(String(format: "%08x", crc32(b)))>"
    }
}

func topTokens(_ s: String) -> [String] {
    var toks: [String] = []
    let c = Array(s)
    var i = 0
    while i < c.count {
        if c[i].isWhitespace { i += 1; continue }
        if c[i] == "(" {
            var depth = 1; i += 1
            while i < c.count && depth > 0 {
                if c[i] == "(" { depth += 1 }
                if c[i] == ")" { depth -= 1 }
                i += 1
            }
            continue
        }
        if c[i] == "\"" {
            i += 1
            while i < c.count && c[i] != "\"" { i += 1 }
            i += 1
            toks.append("Q")
            continue
        }
        if c[i].isLetter || c[i].isNumber || c[i] == "_" {
            var w = ""
            while i < c.count && (c[i].isLetter || c[i].isNumber || c[i] == "_") { w.append(c[i]); i += 1 }
            toks.append(w)
            continue
        }
        i += 1
    }
    return toks
}

func isRowidAlias(_ rest: String) -> Bool {
    let arr = Array(rest)
    var i = 0
    while i < arr.count && arr[i].isWhitespace { i += 1 }
    var w = ""
    while i < arr.count && (arr[i].isLetter || arr[i].isNumber || arr[i] == "_") { w.append(arr[i]); i += 1 }
    guard w.lowercased() == "integer" else { return false }
    while i < arr.count && arr[i].isWhitespace { i += 1 }
    if i < arr.count && arr[i] == "(" { return false }
    let toks = topTokens(rest)
    let kw: Set<String> = ["primary", "not", "null", "unique", "check", "default",
                           "collate", "references", "generated", "as", "constraint"]
    if toks.count > 1 && !kw.contains(toks[1].lowercased()) { return false }
    for k in 0..<(toks.count - 1) where toks[k].lowercased() == "primary" && toks[k+1].lowercased() == "key" {
        return true
    }
    return false
}

func parseCreate(_ sql: String) -> ([String], Int?) {
    let chars = Array(sql)
    var i = 0
    func skipWs() { while i < chars.count && chars[i].isWhitespace { i += 1 } }
    func readWord() -> String {
        skipWs()
        var s = ""
        while i < chars.count && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_") {
            s.append(chars[i]); i += 1
        }
        return s
    }
    _ = readWord() // CREATE
    _ = readWord() // TABLE
    skipWs()
    if i < chars.count && chars[i] == "\"" {
        i += 1
        while i < chars.count && chars[i] != "\"" { i += 1 }
        if i < chars.count { i += 1 }
    } else {
        while i < chars.count && !chars[i].isWhitespace && chars[i] != "(" { i += 1 }
    }
    skipWs()
    if i < chars.count && chars[i] == "(" { i += 1 }
    var defs: [String] = []
    var depth = 1
    var cur = ""
    while i < chars.count {
        let c = chars[i]
        if c == "\"" {
            cur.append(c); i += 1
            while i < chars.count && chars[i] != "\"" { cur.append(chars[i]); i += 1 }
            if i < chars.count { cur.append("\""); i += 1 }
            continue
        }
        if c == "(" { depth += 1 }
        if c == ")" {
            depth -= 1
            if depth == 0 { break }
        }
        if c == "," && depth == 1 {
            defs.append(cur); cur = ""; i += 1; continue
        }
        cur.append(c)
        i += 1
    }
    if !cur.trimmingCharacters(in: .whitespaces).isEmpty { defs.append(cur) }

    var names: [String] = []
    var alias: Int? = nil
    for def in defs {
        let dd = Array(def)
        var j = 0
        while j < dd.count && dd[j].isWhitespace { j += 1 }
        var name = ""
        if j < dd.count && dd[j] == "\"" {
            j += 1
            while j < dd.count && dd[j] != "\"" { name.append(dd[j]); j += 1 }
            j += 1
        } else {
            while j < dd.count && !dd[j].isWhitespace && dd[j] != "(" && dd[j] != ")" && dd[j] != "," {
                name.append(dd[j]); j += 1
            }
        }
        names.append(name)
        let rest = String(dd[j...])
        if isRowidAlias(rest) { alias = names.count - 1 }
    }
    return (names, alias)
}

// ---- main ----
let args = CommandLine.arguments
let dir = args.count > 1 ? args[1] : "."
let rawData = try! Data(contentsOf: URL(fileURLWithPath: dir).appendingPathComponent("db.sqlite"))
d = Array(rawData)
pageSize = Int(d[16]) << 8 | Int(d[17])
if pageSize == 1 { pageSize = 65536 }
usableSize = pageSize - Int(d[20])

struct Tbl { var name: String; var root: UInt32; var cols: [String]; var alias: Int? }
var tables: [Tbl] = []

for (_, payload) in walkTable(root: 1) {
    let vals = decodeRecord(payload)
    guard vals.count >= 5 else { continue }
    guard case .text(let t) = vals[0], String(decoding: t, as: UTF8.self) == "table" else { continue }
    guard case .text(let n) = vals[1] else { continue }
    let name = String(decoding: n, as: UTF8.self)
    guard !name.hasPrefix("sqlite_") else { continue }
    guard case .int(let root) = vals[3] else { continue }
    var sql = ""
    if case .text(let s) = vals[4] { sql = String(decoding: s, as: UTF8.self) }
    let (cols, alias) = parseCreate(sql)
    tables.append(Tbl(name: name, root: UInt32(root), cols: cols, alias: alias))
}

tables.sort {
    let a = Array($0.name.utf8), b = Array($1.name.utf8)
    return a.lexicographicallyPrecedes(b)
}

var out = ""
for (idx, t) in tables.enumerated() {
    let rows = walkTable(root: t.root)
    out += "TABLE \(t.name) rows=\(rows.count)\n"
    out += "COLUMNS " + t.cols.joined(separator: ", ") + "\n"
    for (rid, vals) in rows {
        var parts: [String] = []
        for ci in 0..<t.cols.count {
            if let a = t.alias, ci == a {
                parts.append(String(rid))
            } else if ci < vals.count {
                parts.append(format(vals[ci]))
            } else {
                parts.append("NULL")
            }
        }
        out += "\(rid): " + parts.joined(separator: ", ") + "\n"
    }
    if idx < tables.count - 1 { out += "\n" }
}
print(out, terminator: "")

