func escText(_ b: [UInt8]) -> String {
    var out: [UInt8] = [0x22]
    for byte in b {
        switch byte {
        case 0x5C: out.append(contentsOf: [0x5C, 0x5C])
        case 0x22: out.append(contentsOf: [0x5C, 0x22])
        case 0x0A: out.append(contentsOf: [0x5C, 0x6E])
        case 0x0D: out.append(contentsOf: [0x5C, 0x72])
        case 0x09: out.append(contentsOf: [0x5C, 0x74])
        default:
            if byte < 0x20 || byte == 0x7F {
                out.append(contentsOf: Array(String(format: "\\x%02X", byte).utf8))
            } else {
                out.append(byte)
            }
        }
    }
    out.append(0x22)
    return String(decoding: out, as: UTF8.self)
}

func fmtReal(_ v: Double) -> String {
    var s = String(format: "%.8f", locale: Locale(identifier: "en_US_POSIX"), v)
    while s.hasSuffix("0") && s[s.index(s.endIndex, offsetBy: -2)] != "." {
        s.removeLast()
    }
    return s
}

func format(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .int(let n): return String(n)
    case .real(let x): return fmtReal(x)
    case .text(let b):
        if b.count <= 100 { return escText(b) }
        return "<TEXT len=\(b.count) crc32=\(String(format: "%08x", crc32(b)))>"
    case .blob(let b):
        if b.count <= 100 { return "X'" + b.map { String(format: "%02X", $0) }.joined() + "'" }
        return "<BLOB len=\(b.count) crc32=\(String(format: "%08x", crc32(b)))>"
    }
}

func topTokens(_ s: String) -> [String] {
    var toks: [String] = []
    let c = Array(s)
    var i = 0
    while i < c.count {
        if c[i].isWhitespace { i += 1; continue }
        if c[i] == "(" {
            var depth = 1; i += 1
            while i < c.count && depth > 0 {
                if c[i] == "(" { depth += 1 }
                if c[i] == ")" { depth -= 1 }
                i += 1
            }
            continue
        }
        if c[i] == "\"" {
            i += 1
            while i < c.count && c[i] != "\"" { i += 1 }
            i += 1
            toks.append("Q")
            continue
        }
        if c[i].isLetter || c[i].isNumber || c[i] == "_" {
            var w = ""
            while i < c.count && (c[i].isLetter || c[i].isNumber || c[i] == "_") { w.append(c[i]); i += 1 }
            toks.append(w)
            continue
        }
        i += 1
    }
    return toks
}

func isRowidAlias(_ rest: String) -> Bool {
    let arr = Array(rest)
    var i = 0
    while i < arr.count && arr[i].isWhitespace { i += 1 }
    var w = ""
    while i < arr.count && (arr[i].isLetter || arr[i].isNumber || arr[i] == "_") { w.append(arr[i]); i += 1 }
    guard w.lowercased() == "integer" else { return false }
    while i < arr.count && arr[i].isWhitespace { i += 1 }
    if i < arr.count && arr[i] == "(" { return false }
    let toks = topTokens(rest)
    let kw: Set<String> = ["primary", "not", "null", "unique", "check", "default",
                           "collate", "references", "generated", "as", "constraint"]
    if toks.count > 1 && !kw.contains(toks[1].lowercased()) { return false }
    for k in 0..<(toks.count - 1) where toks[k].lowercased() == "primary" && toks[k+1].lowercased() == "key" {
        return true
    }
    return false
}

func parseCreate(_ sql: String) -> ([String], Int?) {
    let chars = Array(sql)
    var i = 0
    func skipWs() { while i < chars.count && chars[i].isWhitespace { i += 1 } }
    func readWord() -> String {
        skipWs()
        var s = ""
        while i < chars.count && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_") {
            s.append(chars[i]); i += 1
        }
        return s
    }
    _ = readWord() // CREATE
    _ = readWord() // TABLE
    skipWs()
    if i < chars.count && chars[i] == "\"" {
        i += 1
        while i < chars.count && chars[i] != "\"" { i += 1 }
        if i < chars.count { i += 1 }
    } else {
        while i < chars.count && !chars[i].isWhitespace && chars[i] != "(" { i += 1 }
    }
    skipWs()
    if i < chars.count && chars[i] == "(" { i += 1 }
    var defs: [String] = []
    var depth = 1
    var cur = ""
    while i < chars.count {
        let c = chars[i]
        if c == "\"" {
            cur.append(c); i += 1
            while i < chars.count && chars[i] != "\"" { cur.append(chars[i]); i += 1 }
            if i < chars.count { cur.append("\""); i += 1 }
            continue
        }
        if c == "(" { depth += 1 }
        if c == ")" {
            depth -= 1
            if depth == 0 { break }
        }
        if c == "," && depth == 1 {
            defs.append(cur); cur = ""; i += 1; continue
        }
        cur.append(c)
        i += 1
    }
    if !cur.trimmingCharacters(in: .whitespaces).isEmpty { defs.append(cur) }

    var names: [String] = []
    var alias: Int? = nil
    for def in defs {
        let dd = Array(def)
        var j = 0
        while j < dd.count && dd[j].isWhitespace { j += 1 }
        var name = ""
        if j < dd.count && dd[j] == "\"" {
            j += 1
            while j < dd.count && dd[j] != "\"" { name.append(dd[j]); j += 1 }
            j += 1
        } else {
            while j < dd.count && !dd[j].isWhitespace && dd[j] != "(" && dd[j] != ")" && dd[j] != "," {
                name.append(dd[j]); j += 1
            }
        }
        names.append(name)
        let rest = String(dd[j...])
        if isRowidAlias(rest) { alias = names.count - 1 }
    }
    return (names, alias)
}

