import * as fs from "fs";
import * as path from "path";

const data = fs.readFileSync(path.join(process.argv[2], "db.sqlite"));

const pageSize = (() => {
  const v = data.readUInt16BE(16);
  return v === 1 ? 65536 : v;
})();
const reserved = data.readUInt8(20);
const usable = pageSize - reserved;

function pageOffset(p: number): number {
  return (p - 1) * pageSize;
}

function readVarintBuf(buf: Buffer, off: number): [bigint, number] {
  let result = 0n;
  for (let i = 0; i < 9; i++) {
    const b = buf[off + i];
    if (i === 8) {
      result = (result << 8n) | BigInt(b);
      return [result, off + 9];
    }
    result = (result << 7n) | BigInt(b & 0x7f);
    if ((b & 0x80) === 0) return [result, off + i + 1];
  }
  return [result, off + 9];
}

function toSigned64(v: bigint): bigint {
  if (v >= 1n << 63n) return v - (1n << 64n);
  return v;
}

type Value =
  | { t: "null" }
  | { t: "int"; v: bigint }
  | { t: "real"; v: number }
  | { t: "text"; v: Buffer }
  | { t: "blob"; v: Buffer };

function readPayload(cellOff: number, payloadLen: number): Buffer {
  const X = usable - 35;
  let local: number;
  if (payloadLen <= X) {
    local = payloadLen;
  } else {
    const M = Math.floor(((usable - 12) * 32) / 255) - 23;
    const K = M + ((payloadLen - M) % (usable - 4));
    local = K <= X ? K : M;
  }
  const parts: Buffer[] = [data.subarray(cellOff, cellOff + local)];
  let remaining = payloadLen - local;
  let next = local < payloadLen ? data.readUInt32BE(cellOff + local) : 0;
  while (remaining > 0) {
    const po = pageOffset(next);
    const np = data.readUInt32BE(po);
    const take = Math.min(usable - 4, remaining);
    parts.push(data.subarray(po + 4, po + 4 + take));
    remaining -= take;
    next = np;
  }
  return Buffer.concat(parts);
}

function parseLeafCell(off: number): { rowid: bigint; record: Buffer } {
  const [P, o] = readVarintBuf(data, off);
  const [rowid, o2] = readVarintBuf(data, o);
  const payload = readPayload(o2, Number(P));
  return { rowid: toSigned64(rowid), record: payload };
}

function readValue(buf: Buffer, off: number, st: number): [Value, number] {
  if (st === 0) return [{ t: "null" }, off];
  if (st >= 1 && st <= 6) {
    const n = [0, 1, 2, 3, 4, 6, 8][st];
    let v = 0n;
    for (let i = 0; i < n; i++) v = (v << 8n) | BigInt(buf[off + i]);
    if (buf[off] & 0x80) v -= 1n << BigInt(8 * n);
    return [{ t: "int", v }, off + n];
  }
  if (st === 7) return [{ t: "real", v: buf.readDoubleBE(off) }, off + 8];
  if (st === 8) return [{ t: "int", v: 0n }, off];
  if (st === 9) return [{ t: "int", v: 1n }, off];
  const n = Math.floor((st - 12) / 2);
  const b = buf.subarray(off, off + n);
  return [st % 2 === 0 ? { t: "blob", v: b } : { t: "text", v: b }, off + n];
}

function parseRecord(buf: Buffer): Value[] {
  const [hdrSize, h0] = readVarintBuf(buf, 0);
  const types: number[] = [];
  let off = h0;
  while (off < hdrSize) {
    const [t, no] = readVarintBuf(buf, off);
    types.push(Number(t));
    off = no;
  }
  let body = hdrSize;
  const vals: Value[] = [];
  for (const t of types) {
    const [v, nb] = readValue(buf, body, t);
    vals.push(v);
    body = nb;
  }
  return vals;
}

function walkTable(root: number): { rowid: bigint; vals: Value[] }[] {
  const rows: { rowid: bigint; vals: Value[] }[] = [];
  function visit(p: number): void {
    const base = pageOffset(p);
    const hdr = base + (p === 1 ? 100 : 0);
    const type = data[hdr];
    const ncells = data.readUInt16BE(hdr + 3);
    const ptrBase = hdr + (type === 5 ? 12 : 8);
    if (type === 5) {
      for (let i = 0; i < ncells; i++) {
        const co = base + data.readUInt16BE(ptrBase + 2 * i);
        visit(data.readUInt32BE(co));
      }
      visit(data.readUInt32BE(hdr + 8));
    } else if (type === 13) {
      for (let i = 0; i < ncells; i++) {
        const co = base + data.readUInt16BE(ptrBase + 2 * i);
        const { rowid, record } = parseLeafCell(co);
        rows.push({ rowid, vals: parseRecord(record) });
      }
    }
  }
  visit(root);
  return rows;
}

function parseCreate(sql: string): { names: string[]; alias: boolean[] } {
  let i = 0;
  let inQ = false;
  let start = -1;
  for (; i < sql.length; i++) {
    const c = sql[i];
    if (inQ) {
      if (c === '"') inQ = false;
    } else if (c === '"') inQ = true;
    else if (c === "(") {
      start = i + 1;
      break;
    }
  }
  let depth = 1;
  let end = sql.length;
  inQ = false;
  for (let j = start; j < sql.length; j++) {
    const c = sql[j];
    if (inQ) {
      if (c === '"') inQ = false;
    } else if (c === '"') inQ = true;
    else if (c === "(") depth++;
    else if (c === ")") {
      depth--;
      if (depth === 0) {
        end = j;
        break;
      }
    }
  }
  const inner = sql.slice(start, end);
  const defs: string[] = [];
  depth = 0;
  inQ = false;
  let cur = "";
  for (const c of inner) {
    if (inQ) {
      cur += c;
      if (c === '"') inQ = false;
    } else if (c === '"') {
      inQ = true;
      cur += c;
    } else if (c === "(") {
      depth++;
      cur += c;
    } else if (c === ")") {
      depth--;
      cur += c;
    } else if (c === "," && depth === 0) {
      defs.push(cur);
      cur = "";
    } else cur += c;
  }
  defs.push(cur);
  const names: string[] = [];
  const alias: boolean[] = [];
  for (let d of defs) {
    d = d.trim();
    let name: string;
    let rest: string;
    if (d[0] === '"') {
      const e = d.indexOf('"', 1);
      name = d.slice(1, e);
      rest = d.slice(e + 1).trim();
    } else {
      const m = d.match(/^[^\s,(]+/)!;
      name = m[0];
      rest = d.slice(name.length).trim();
    }
    names.push(name);
    alias.push(/^integer\b/i.test(rest) && /primary\s+key/i.test(rest));
  }
  return { names, alias };
}

const crcTable = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32hex(buf: Buffer): string {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  c = (c ^ 0xffffffff) >>> 0;
  return c.toString(16).padStart(8, "0");
}

function formatText(b: Buffer): string {
  let out = "";
  let seg: number[] = [];
  const flush = () => {
    if (seg.length) {
      out += Buffer.from(seg).toString("utf8");
      seg = [];
    }
  };
  for (const byte of b) {
    if (byte === 0x5c) {
      flush();
      out += "\\\\";
    } else if (byte === 0x22) {
      flush();
      out += '\\"';
    } else if (byte === 0x0a) {
      flush();
      out += "\\n";
    } else if (byte === 0x0d) {
      flush();
      out += "\\r";
    } else if (byte === 0x09) {
      flush();
      out += "\\t";
    } else if (byte < 0x20 || byte === 0x7f) {
      flush();
      out += "\\x" + byte.toString(16).toUpperCase().padStart(2, "0");
    } else seg.push(byte);
  }
  flush();
  return '"' + out + '"';
}

function formatReal(d: number): string {
  const buf = Buffer.alloc(8);
  buf.writeDoubleBE(d);
  const bits = buf.readBigUInt64BE();
  const sign = (bits >> 63n) & 1n;
  const exp = Number((bits >> 52n) & 0x7ffn);
  const mant = bits & ((1n << 52n) - 1n);
  if (mant === 0n && exp === 0) return sign ? "-0.0" : "0.0";
  let m: bigint;
  let e: number;
  if (exp === 0) {
    m = mant;
    e = -1074;
  } else {
    m = mant | (1n << 52n);
    e = exp - 1075;
  }
  let num: bigint;
  let den: bigint;
  if (e >= 0) {
    num = m << BigInt(e);
    den = 1n;
  } else {
    num = m;
    den = 1n << BigInt(-e);
  }
  const intPart = num / den;
  let frac = num % den;
  let digits = "";
  while (frac !== 0n) {
    frac *= 10n;
    digits += (frac / den).toString();
    frac %= den;
  }
  digits = digits.replace(/0+$/, "");
  if (!digits) digits = "0";
  return (sign ? "-" : "") + intPart.toString() + "." + digits;
}

function formatValue(v: Value): string {
  switch (v.t) {
    case "null":
      return "NULL";
    case "int":
      return v.v.toString();
    case "real":
      return formatReal(v.v);
    case "text":
      if (v.v.length <= 100) return formatText(v.v);
      return `<TEXT len=${v.v.length} crc32=${crc32hex(v.v)}>`;
    case "blob":
      if (v.v.length <= 100) return "X'" + v.v.toString("hex").toUpperCase() + "'";
      return `<BLOB len=${v.v.length} crc32=${crc32hex(v.v)}>`;
  }
}

// main
const schemaRows = walkTable(1);
type Table = { name: string; root: number; sql: string };
const tables: Table[] = [];
for (const r of schemaRows) {
  const type = r.vals[0];
  const name = r.vals[1];
  const root = r.vals[3];
  const sql = r.vals[4];
  if (
    type &&
    type.t === "text" &&
    type.v.toString("utf8") === "table" &&
    name &&
    name.t === "text" &&
    !name.v.toString("utf8").startsWith("sqlite_") &&
    root &&
    root.t === "int"
  ) {
    tables.push({
      name: name.v.toString("utf8"),
      root: Number(root.v),
      sql: sql && sql.t === "text" ? sql.v.toString("utf8") : "",
    });
  }
}
tables.sort((a, b) =>
  Buffer.compare(Buffer.from(a.name, "utf8"), Buffer.from(b.name, "utf8"))
);

const blocks: string[] = [];
for (const t of tables) {
  const { names, alias } = parseCreate(t.sql);
  const rows = walkTable(t.root);
  rows.sort((a, b) => (a.rowid < b.rowid ? -1 : a.rowid > b.rowid ? 1 : 0));
  const lines: string[] = [];
  lines.push(`TABLE ${t.name} rows=${rows.length}`);
  lines.push(`COLUMNS ${names.join(", ")}`);
  for (const r of rows) {
    const parts: string[] = [];
    for (let c = 0; c < names.length; c++) {
      if (alias[c]) {
        parts.push(r.rowid.toString());
      } else {
        const v = r.vals[c] ?? { t: "null" };
        parts.push(formatValue(v));
      }
    }
    lines.push(`${r.rowid.toString()}: ${parts.join(", ")}`);
  }
  blocks.push(lines.join("\n"));
}
process.stdout.write(blocks.join("\n\n") + (blocks.length ? "\n" : ""));

