  const hdrSize = Number(hdrSizeBig);
  const types: number[] = [];
  let off = h0;
  while (off < hdrSize) {
    const [t, no] = readVarintBuf(buf, off);
    types.push(Number(t));
    off = no;
  }
  let body = hdrSize;
  const vals: Value[] = [];
  for (const t of types) {
    const [v, nb] = readValue(buf, body, t);
    vals.push(v);
    body = nb;
  }
  return vals;
}

function walkTable(root: number): { rowid: bigint; vals: Value[] }[] {
  const rows: { rowid: bigint; vals: Value[] }[] = [];
  function visit(p: number): void {
    const base = pageOffset(p);
    const hdr = base + (p === 1 ? 100 : 0);
    const type = data[hdr];
    const ncells = data.readUInt16BE(hdr + 3);
    const ptrBase = hdr + (type === 5 ? 12 : 8);
    if (type === 5) {
      for (let i = 0; i < ncells; i++) {
        const co = base + data.readUInt16BE(ptrBase + 2 * i);
        visit(data.readUInt32BE(co));
      }
      visit(data.readUInt32BE(hdr + 8));
    } else if (type === 13) {
      for (let i = 0; i < ncells; i++) {
        const co = base + data.readUInt16BE(ptrBase + 2 * i);
        const { rowid, record } = parseLeafCell(co);
        rows.push({ rowid, vals: parseRecord(record) });
      }
    }
  }
  visit(root);
  return rows;
}

function parseCreate(sql: string): { names: string[]; alias: boolean[] } {
  let i = 0;
  let inQ = false;
  let start = -1;
  for (; i < sql.length; i++) {
    const c = sql[i];
    if (inQ) {
      if (c === '"') inQ = false;
    } else if (c === '"') inQ = true;
    else if (c === "(") {
      start = i + 1;
      break;
    }
  }
  let depth = 1;
  let end = sql.length;
  inQ = false;
  for (let j = start; j < sql.length; j++) {
    const c = sql[j];
    if (inQ) {
      if (c === '"') inQ = false;
    } else if (c === '"') inQ = true;
    else if (c === "(") depth++;
    else if (c === ")") {
      depth--;
      if (depth === 0) {
        end = j;
        break;
      }
    }
  }
  const inner = sql.slice(start, end);
  const defs: string[] = [];
  depth = 0;
  inQ = false;
  let cur = "";
  for (const c of inner) {
    if (inQ) {
      cur += c;
      if (c === '"') inQ = false;
    } else if (c === '"') {
      inQ = true;
      cur += c;
    } else if (c === "(") {
      depth++;
      cur += c;
    } else if (c === ")") {
      depth--;
      cur += c;
    } else if (c === "," && depth === 0) {
      defs.push(cur);
      cur = "";
    } else cur += c;
  }
  defs.push(cur);
  const names: string[] = [];
  const alias: boolean[] = [];
  for (let d of defs) {
    d = d.trim();
    let name: string;
    let rest: string;
    if (d[0] === '"') {
      const e = d.indexOf('"', 1);
      name = d.slice(1, e);
      rest = d.slice(e + 1).trim();
    } else {
      const m = d.match(/^[^\s,(]+/)!;
      name = m[0];
      rest = d.slice(name.length).trim();
    }
    names.push(name);
    alias.push(/^integer\b/i.test(rest) && /primary\s+key/i.test(rest));
  }
  return { names, alias };
}

const crcTable = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32hex(buf: Buffer): string {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  c = (c ^ 0xffffffff) >>> 0;
  return c.toString(16).padStart(8, "0");
}

function formatText(b: Buffer): string {
  let out = "";
  let seg: number[] = [];
  const flush = () => {
    if (seg.length) {
      out += Buffer.from(seg).toString("utf8");
      seg = [];
    }
  };
  for (const byte of b) {
    if (byte === 0x5c) {
      flush();
      out += "\\\\";
    } else if (byte === 0x22) {
      flush();
      out += '\\"';
    } else if (byte === 0x0a) {
      flush();
      out += "\\n";
    } else if (byte === 0x0d) {
      flush();
      out += "\\r";
    } else if (byte === 0x09) {
      flush();
      out += "\\t";
    } else if (byte < 0x20 || byte === 0x7f) {
      flush();
      out += "\\x" + byte.toString(16).toUpperCase().padStart(2, "0");
    } else seg.push(byte);
  }
  flush();
  return '"' + out + '"';
}

function formatReal(d: number): string {
  const buf = Buffer.alloc(8);
  buf.writeDoubleBE(d);
  const bits = buf.readBigUInt64BE();
  const sign = (bits >> 63n) & 1n;
  const exp = Number((bits >> 52n) & 0x7ffn);
  const mant = bits & ((1n << 52n) - 1n);
  if (mant === 0n && exp === 0) return sign ? "-0.0" : "0.0";
  let m: bigint;
  let e: number;
  if (exp === 0) {
    m = mant;
    e = -1074;
  } else {
    m = mant | (1n << 52n);
    e = exp - 1075;
  }
  let num: bigint;
  let den: bigint;
  if (e >= 0) {
    num = m << BigInt(e);
    den = 1n;
  } else {
    num = m;
    den = 1n << BigInt(-e);
  }
  const intPart = num / den;
  let frac = num % den;
  let digits = "";
  while (frac !== 0n) {
    frac *= 10n;
    digits += (frac / den).toString();
    frac %= den;
  }
  digits = digits.replace(/0+$/, "");
  if (!digits) digits = "0";
  return (sign ? "-" : "") + intPart.toString() + "." + digits;
}

function formatValue(v: Value): string {
  switch (v.t) {
    case "null":
      return "NULL";
    case "int":
      return v.v.toString();
    case "real":
      return formatReal(v.v);
    case "text":
      if (v.v.length <= 100) return formatText(v.v);
      return `<TEXT len=${v.v.length} crc32=${crc32hex(v.v)}>`;
    case "blob":
      if (v.v.length <= 100) return "X'" + v.v.toString("hex").toUpperCase() + "'";
      return `<BLOB len=${v.v.length} crc32=${crc32hex(v.v)}>`;
  }
}

// main
const schemaRows = walkTable(1);
type Table = { name: string; root: number; sql: string };
const tables: Table[] = [];
for (const r of schemaRows) {
  const type = r.vals[0];
  const name = r.vals[1];
  const root = r.vals[3];
  const sql = r.vals[4];
  if (
    type &&
    type.t === "text" &&
    type.v.toString("utf8") === "table" &&
    name &&
    name.t === "text" &&
    !name.v.toString("utf8").startsWith("sqlite_") &&
    root &&
    root.t === "int"
  ) {
    tables.push({
      name: name.v.toString("utf8"),
      root: Number(root.v),
      sql: sql && sql.t === "text" ? sql.v.toString("utf8") : "",
    });
  }
}
tables.sort((a, b) =>
  Buffer.compare(Buffer.from(a.name, "utf8"), Buffer.from(b.name, "utf8"))
);

const blocks: string[] = [];
for (const t of tables) {
  const { names, alias } = parseCreate(t.sql);
  const rows = walkTable(t.root);
  rows.sort((a, b) => (a.rowid < b.rowid ? -1 : a.rowid > b.rowid ? 1 : 0));
  const lines: string[] = [];
  lines.push(`TABLE ${t.name} rows=${rows.length}`);
  lines.push(`COLUMNS ${names.join(", ")}`);
  for (const r of rows) {
    const parts: string[] = [];
    for (let c = 0; c < names.length; c++) {
      if (alias[c]) {
        parts.push(r.rowid.toString());
      } else {
        const v = r.vals[c] ?? { t: "null" };
        parts.push(formatValue(v));
      }
    }
    lines.push(`${r.rowid.toString()}: ${parts.join(", ")}`);
  }
  blocks.push(lines.join("\n"));
}
process.stdout.write(blocks.join("\n\n") + (blocks.length ? "\n" : ""));

import sys, json, socket
from urllib.parse import urlparse


def esc(s):
    return s.replace('\\', '\\\\').replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t')


def dechunk(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        j = data.find(b'\n', i)
        if j == -1:
            break
        line = data[i:j].rstrip(b'\r')
        i = j + 1
        try:
            size = int(line, 16)
        except ValueError:
            break
        if size == 0:
            break
        out += data[i:i + size]
        i += size
        if data[i:i + 2] == b'\r\n':
            i += 2
        elif data[i:i + 1] == b'\n':
            i += 1
    return bytes(out)


def http_post(host, port, path, headers, body):
    sock = socket.create_connection((host, port))
    req = "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Length: %d\r\n" % (path, host, len(body))
    for k, v in headers:
        req += "%s: %s\r\n" % (k, v)
    req += "\r\n"
    sock.sendall(req.encode('utf-8') + body)
    buf = bytearray()
    while b"\r\n\r\n" not in buf and b"\n\n" not in buf:
        d = sock.recv(65536)
        if not d:
            break
        buf += d
    idx = buf.find(b"\r\n\r\n")
    seplen = 4
    idx2 = buf.find(b"\n\n")
    if idx == -1 or (idx2 != -1 and idx2 < idx):
        idx, seplen = idx2, 2
    if idx == -1:
        sock.close()
        return ('error', 0, 'invalid_response', 'no header terminator')
    header_bytes = bytes(buf[:idx])
    rest = bytes(buf[idx + seplen:])
    lines = header_bytes.decode('latin-1').split('\n')
    status = int(lines[0].split()[1])
    hdrs = {}
    for l in lines[1:]:
        l = l.rstrip('\r')
        if ':' in l:
            k, v = l.split(':', 1)
            hdrs[k.strip().lower()] = v.strip()
    if status != 200:
        cl = int(hdrs.get('content-length', '0'))
        body_bytes = rest
        while len(body_bytes) < cl:
            d = sock.recv(65536)
            if not d:
                break
            body_bytes += d
        sock.close()
        err = json.loads(body_bytes)
        return ('error', status, err['error']['type'], err['error']['message'])
    while True:
        d = sock.recv(65536)
        if not d:
            break
        rest += d
    sock.close()
    return ('ok', dechunk(rest))


def parse_sse(text):
    events = []
    name = None
    data_lines = []
    for raw in text.split('\n'):
        line = raw[:-1] if raw.endswith('\r') else raw
        if line == '':
            if data_lines:
                events.append((name, '\n'.join(data_lines)))
            name = None
            data_lines = []
            continue
        if line.startswith(':'):
            continue
        if ':' in line:
            field, _, value = line.partition(':')
            if value.startswith(' '):
                value = value[1:]
        else:
            field, value = line, ''
        if field == 'event':
            name = value
        elif field == 'data':
            data_lines.append(value)
    return events


def process_stream(body_bytes):
    text = body_bytes.decode('utf-8')
    blocks = {}
    order = []
    stop_reason = None
    usage = {'input': 0, 'output': 0, 'cache_read': 0}
    for name, data in parse_sse(text):
        obj = json.loads(data)
        if name == 'message_start':
            u = obj['message']['usage']
            usage['input'] += u.get('input_tokens', 0)
            usage['cache_read'] += u.get('cache_read_input_tokens', 0)
        elif name == 'content_block_start':
            idx = obj['index']
            cb = obj['content_block']
            b = {'type': cb['type']}
            if b['type'] == 'thinking':
                b['thinking'] = ''
                b['signature'] = ''
            elif b['type'] == 'text':
                b['text'] = ''
            else:
                b['id'] = cb['id']
                b['name'] = cb['name']
                b['raw'] = ''
            blocks[idx] = b
            order.append(idx)
        elif name == 'content_block_delta':
            idx = obj['index']
            d = obj['delta']
            b = blocks[idx]
            dt = d['type']
            if dt == 'thinking_delta':
                b['thinking'] += d['thinking']
            elif dt == 'signature_delta':
                b['signature'] += d['signature']
            elif dt == 'text_delta':
                b['text'] += d['text']
            elif dt == 'input_json_delta':
                b['raw'] += d['partial_json']
        elif name == 'message_delta':
            stop_reason = obj['delta']['stop_reason']
            usage['output'] += obj['usage']['output_tokens']
    return [blocks[i] for i in order], stop_reason, usage


def print_blocks(blocks):
    for b in blocks:
        if b['type'] == 'thinking':
            print('thinking ' + esc(b['thinking']))
            print('signature ' + esc(b['signature']))
        elif b['type'] == 'text':
            print('text ' + esc(b['text']))
        else:
            print('tool_use %s %s %s' % (b['id'], b['name'], esc(b['raw'])))


def run_tool(name, args):
    if name == 'measure':
        text = args['text']
        unit = args['unit']
        if unit == 'code_points':
            return str(len(text)), False
        if unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        if unit == 'utf16_units':
            return str(sum(2 if ord(c) > 0xFFFF else 1 for c in text)), False
        return 'unsupported unit: ' + unit, True
    if name == 'reverse':
        return args['text'][::-1], False
    return 'unknown tool: ' + name, True


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]
    with open(data_dir + '/request.json', 'r', encoding='utf-8') as f:
        cfg = json.load(f)
    u = urlparse(base_url)
    host = u.hostname
    port = u.port or 80
    path = u.path.rstrip('/') + '/v1/messages'
    headers = [('x-api-key', cfg['api_key']),
               ('anthropic-version', '2023-06-01'),
               ('content-type', 'application/json')]

    def make_body(messages):
        obj = {
            "model": cfg["model"],
            "max_tokens": cfg["max_tokens"],
            "stream": True,
            "thinking": {"type": "enabled", "budget_tokens": cfg["thinking_budget"]},
            "system": cfg["system"],
            "tools": cfg["tools"],
            "messages": messages,
        }
        return json.dumps(obj).encode('utf-8')

    user_msg = {"role": "user", "content": cfg["prompt"]}

    res = http_post(host, port, path, headers, make_body([user_msg]))
    if res[0] == 'error':
        print('ERROR %d %s: %s' % (res[1], res[2], esc(res[3])))
        return
    blocks1, stop1, usage1 = process_stream(res[1])
    print('request 1')
    print_blocks(blocks1)
    print('stop_reason ' + stop1)

    assistant_content = []
    tool_result_content = []
    for b in blocks1:
        if b['type'] == 'thinking':
            assistant_content.append({"type": "thinking", "thinking": b["thinking"], "signature": b["signature"]})
        elif b['type'] == 'text':
            assistant_content.append({"type": "text", "text": b["text"]})
        else:
            inp = json.loads(b['raw'])
            assistant_content.append({"type": "tool_use", "id": b["id"], "name": b["name"], "input": inp})
            result, is_err = run_tool(b['name'], inp)
            if is_err:
                print('error %s %s' % (b['id'], esc(result)))
            else:
                print('result %s %s' % (b['id'], esc(result)))
            tr = {"type": "tool_result", "tool_use_id": b["id"], "content": result}
            if is_err:
                tr["is_error"] = True
            tool_result_content.append(tr)

    res = http_post(host, port, path, headers, make_body([
        user_msg,
        {"role": "assistant", "content": assistant_content},
        {"role": "user", "content": tool_result_content},
    ]))
    if res[0] == 'error':
        print('ERROR %d %s: %s' % (res[1], res[2], esc(res[3])))
        return
    blocks2, stop2, usage2 = process_stream(res[1])
    print('request 2')
    print_blocks(blocks2)
    print('stop_reason ' + stop2)
    print('usage input=%d output=%d cache_read=%d' % (
        usage1['input'] + usage2['input'],
        usage1['output'] + usage2['output'],
        usage1['cache_read'] + usage2['cache_read']))


main()

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

function esc(s: string): string {
  return s.replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t');
}

interface Block {
  type: string;
  thinking: string;
  signature: string;
  text: string;
  raw: string;
  id: string;
  name: string;
}

interface ReplyState {
  blocks: Map<number, Block>;
  stopReason: string;
  inputTokens: number;
  outputTokens: number;
  cacheRead: number;
}

function newReply(): ReplyState {
  return { blocks: new Map(), stopReason: '', inputTokens: 0, outputTokens: 0, cacheRead: 0 };
}

function printBlock(b: Block): void {
  if (b.type === 'thinking') {
    console.log('thinking ' + esc(b.thinking));
    console.log('signature ' + esc(b.signature));
  } else if (b.type === 'text') {
    console.log('text ' + esc(b.text));
  } else if (b.type === 'tool_use') {
    console.log('tool_use ' + b.id + ' ' + b.name + ' ' + esc(b.raw));
  }
}

function handleEvent(st: ReplyState, ev: any): void {
  switch (ev.type) {
    case 'message_start': {
      const u = ev.message && ev.message.usage ? ev.message.usage : {};
      st.inputTokens += u.input_tokens || 0;
      st.cacheRead += u.cache_read_input_tokens || 0;
      break;
    }
    case 'content_block_start': {
      const cb = ev.content_block || {};
      st.blocks.set(ev.index, {
        type: cb.type, thinking: '', signature: '', text: '', raw: '',
        id: cb.id || '', name: cb.name || ''
      });
      break;
    }
    case 'content_block_delta': {
      const b = st.blocks.get(ev.index);
      if (!b) break;
      const d = ev.delta || {};
      if (d.type === 'thinking_delta') b.thinking += d.thinking;
      else if (d.type === 'signature_delta') b.signature += d.signature;
      else if (d.type === 'text_delta') b.text += d.text;
      else if (d.type === 'input_json_delta') b.raw += d.partial_json;
      break;
    }
    case 'content_block_stop': {
      const b = st.blocks.get(ev.index);
      if (b) printBlock(b);
      break;
    }
    case 'message_delta': {
      if (ev.delta && ev.delta.stop_reason !== undefined) st.stopReason = ev.delta.stop_reason;
      if (ev.usage && ev.usage.output_tokens) st.outputTokens += ev.usage.output_tokens;
      break;
    }
    default:
      break;
  }
}

async function readSSE(res: http.IncomingMessage, st: ReplyState): Promise<void> {
  res.setEncoding('utf8');
  let buf = '';
  let eventName = '';
  let dataLines: string[] = [];
  const dispatch = () => {
    if (eventName !== '' || dataLines.length > 0) {
      const data = dataLines.join('\n');
      eventName = '';
      dataLines = [];
      handleEvent(st, JSON.parse(data));
    }
  };
  res.on('data', (chunk: string) => {
    buf += chunk;
    let idx: number;
    while ((idx = buf.indexOf('\n')) >= 0) {
      let line = buf.slice(0, idx);
      buf = buf.slice(idx + 1);
      if (line.endsWith('\r')) line = line.slice(0, -1);
      if (line === '') { dispatch(); continue; }
      if (line.startsWith(':')) continue;
      const ci = line.indexOf(':');
      let field = line;
      let value = '';
      if (ci >= 0) {
        field = line.slice(0, ci);
        value = line.slice(ci + 1);
        if (value.startsWith(' ')) value = value.slice(1);
      }
      if (field === 'event') eventName = value;
      else if (field === 'data') dataLines.push(value);
    }
  });
  await new Promise<void>((resolve) => {
    res.on('end', () => { dispatch(); resolve(); });
    res.on('close', () => { dispatch(); resolve(); });
  });
}

function post(url: URL, apiKey: string, body: string): Promise<http.IncomingMessage> {
  return new Promise((resolve, reject) => {
    const req = http.request({
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Length': Buffer.byteLength(body).toString(),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    }, resolve);
    req.on('error', reject);
    req.end(body);
  });
}

async function errorExit(res: http.IncomingMessage): Promise<never> {
  res.setEncoding('utf8');
  let body = '';
  for await (const chunk of res) body += chunk;
  let msg = '';
  try {
    const j = JSON.parse(body);
    msg = j.error.type + ': ' + j.error.message;
  } catch { /* ignore */ }
  console.log('ERROR ' + res.statusCode + ' ' + msg);
  process.exit(0);
}

function runTool(name: string, input: any): { ok: boolean; result: string } {
  if (name === 'measure') {
    const unit = input.unit;
    if (unit === 'code_points') return { ok: true, result: String([...input.text].length) };
    if (unit === 'utf8_bytes') return { ok: true, result: String(Buffer.from(input.text, 'utf8').length) };
    if (unit === 'utf16_units') {
      let n = 0;
      for (const ch of input.text) n += (ch.codePointAt(0) as number) > 0xFFFF ? 2 : 1;
      return { ok: true, result: String(n) };
    }
    return { ok: false, result: 'unsupported unit: ' + unit };
  }
  if (name === 'reverse') {
    return { ok: true, result: [...input.text].reverse().join('') };
  }
  return { ok: false, result: 'unknown tool: ' + name };
}

async function main(): Promise<void> {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];
  const url = new URL(baseUrl + '/v1/messages');
  const cfg = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf8'));

  const userMsg = { role: 'user', content: cfg.prompt };
  const body1 = JSON.stringify({
    model: cfg.model,
    max_tokens: cfg.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: cfg.thinking_budget },
    system: cfg.system,
    tools: cfg.tools,
    messages: [userMsg]
  });

  console.log('request 1');
  const res1 = await post(url, cfg.api_key, body1);
  if (res1.statusCode !== 200) return errorExit(res1);
  const st1 = newReply();
  await readSSE(res1, st1);
  console.log('stop_reason ' + st1.stopReason);

  const assistantContent: any[] = [];
  const toolResults: any[] = [];
