            while (i < s.length()) {
                char c = s.charAt(i);
                if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E') i++; else break;
            }
            String t = s.substring(st, i);
            if (t.indexOf('.') < 0 && t.indexOf('e') < 0 && t.indexOf('E') < 0) return Long.parseLong(t);
            return Double.valueOf(t);
        }
    }

    static String jsonWrite(Object v) {
        StringBuilder b = new StringBuilder();
        writeVal(b, v);
        return b.toString();
    }

    @SuppressWarnings("unchecked")
    static void writeVal(StringBuilder b, Object v) {
        if (v == null) { b.append("null"); return; }
        if (v instanceof String) { writeStr(b, (String) v); return; }
        if (v instanceof Boolean || v instanceof Integer || v instanceof Long || v instanceof Double) { b.append(v.toString()); return; }
        if (v instanceof Map) {
            b.append('{'); boolean first = true;
            for (Map.Entry<Object,Object> e : ((Map<Object,Object>) v).entrySet()) {
                if (!first) b.append(',');
                first = false;
                writeStr(b, (String) e.getKey()); b.append(':');
                writeVal(b, e.getValue());
            }
            b.append('}'); return;
        }
        if (v instanceof List) {
            b.append('['); boolean first = true;
            for (Object o : (List<Object>) v) {
                if (!first) b.append(',');
                first = false;
                writeVal(b, o);
            }
            b.append(']'); return;
        }
    }

    static void writeStr(StringBuilder b, String s) {
        b.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': b.append("\\\""); break;
                case '\\': b.append("\\\\"); break;
                case '\b': b.append("\\b"); break;
                case '\f': b.append("\\f"); break;
                case '\n': b.append("\\n"); break;
                case '\r': b.append("\\r"); break;
                case '\t': b.append("\\t"); break;
                default:
                    if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
                    else b.append(c);
            }
        }
        b.append('"');
    }

    static long num(Object o) { return ((Number) o).longValue(); }

    // ---------- HTTP ----------
    static class Response implements Closeable {
        final Socket sock;
        final int status;
        final Map<String, String> headers = new HashMap<>();
        final InputStream in;

        Response(Socket sock) throws IOException {
            this.sock = sock;
            InputStream raw = new BufferedInputStream(sock.getInputStream());
            String statusLine = readLine(raw);
            String[] t = statusLine.split(" ");
            this.status = Integer.parseInt(t[1]);
            String line;
            while ((line = readLine(raw)) != null) {
                if (line.isEmpty()) break;
                int ci = line.indexOf(':');
                if (ci > 0) headers.put(line.substring(0, ci).trim().toLowerCase(), line.substring(ci + 1).trim());
            }
            this.in = raw;
        }

        static String readLine(InputStream in) throws IOException {
            ByteArrayOutputStream b = new ByteArrayOutputStream();
            int c;
            while ((c = in.read()) != -1) { if (c == '\n') break; b.write(c); }
            if (c == -1 && b.size() == 0) return null;
            byte[] d = b.toByteArray(); int n = d.length;
            if (n > 0 && d[n - 1] == '\r') n--;
            return new String(d, 0, n, StandardCharsets.UTF_8);
        }

        public void close() throws IOException { sock.close(); }
    }

    static Response send(String host, int port, String path, String apiKey, String body) throws IOException {
        Socket sock = new Socket(host, port);
        OutputStream os = sock.getOutputStream();
        byte[] b = body.getBytes(StandardCharsets.UTF_8);
        String req = "POST " + path + " HTTP/1.1\r\n"
                + "Host: " + host + ":" + port + "\r\n"
                + "Content-Length: " + b.length + "\r\n"
                + "x-api-key: " + apiKey + "\r\n"
                + "anthropic-version: 2023-06-01\r\n"
                + "content-type: application/json\r\n"
                + "\r\n";
        os.write(req.getBytes(StandardCharsets.UTF_8));
        os.write(b);
        os.flush();
        return new Response(sock);
    }

    static class ChunkedReader {
        final InputStream in;
        long remaining = -1;
        boolean done = false;
        ChunkedReader(InputStream in) { this.in = in; }

        int read() throws IOException {
            if (done) return -1;
            if (remaining == 0) { in.read(); in.read(); remaining = -1; } // trailing CRLF
            if (remaining == -1) {
                String line = readRawLine();
                if (line == null) { done = true; return -1; }
                int semi = line.indexOf(';');
                String t = semi >= 0 ? line.substring(0, semi) : line;
                t = t.trim();
                long size = Long.parseLong(t, 16);
                if (size == 0) {
                    String l;
                    while ((l = readRawLine()) != null && !l.isEmpty()) {}
                    done = true;
                    return -1;
                }
                remaining = size;
            }
            int c = in.read();
            if (c == -1) { done = true; return -1; }
            remaining--;
            return c;
        }

        String readRawLine() throws IOException {
            ByteArrayOutputStream b = new ByteArrayOutputStream();
            int c;
            while ((c = in.read()) != -1) { if (c == '\n') break; b.write(c); }
            if (c == -1 && b.size() == 0) return null;
            byte[] d = b.toByteArray(); int n = d.length;
            if (n > 0 && d[n - 1] == '\r') n--;
            return new String(d, 0, n, StandardCharsets.ISO_8859_1);
        }

        String readLine() throws IOException {
            ByteArrayOutputStream b = new ByteArrayOutputStream();
            int c;
            while ((c = read()) != -1) { if (c == '\n') break; b.write(c); }
            if (c == -1 && b.size() == 0) return null;
            byte[] d = b.toByteArray(); int n = d.length;
            if (n > 0 && d[n - 1] == '\r') n--;
            return new String(d, 0, n, StandardCharsets.UTF_8);
        }
    }

    // ---------- reply state ----------
    static class Block {
        String type;
        String thinking = "", signature = "", text = "", id = "", name = "", raw = "";
    }

    static long usageInput = 0, usageOutput = 0, usageCacheRead = 0;
    static Map<Integer, Block> blockMap = new HashMap<>();
    static List<Integer> blockOrder = new ArrayList<>();
    static String stopReason = "";

    static void dispatch(String name, String data) throws IOException {
        if (data == null) return;
        Object j = jsonParse(data);
        Map m = (Map) j;
        switch (name) {
            case "message_start": {
                Map msg = (Map) m.get("message");
                Map u = (Map) msg.get("usage");
                usageInput += num(u.get("input_tokens"));
                Object cr = u.get("cache_read_input_tokens");
                if (cr != null) usageCacheRead += num(cr);
                break;
            }
            case "content_block_start": {
                int idx = (int) num(m.get("index"));
                Map cb = (Map) m.get("content_block");
                Block b = new Block();
                b.type = (String) cb.get("type");
                if (b.type.equals("tool_use")) {
                    b.id = (String) cb.get("id");
                    b.name = (String) cb.get("name");
                }
                blockMap.put(idx, b);
                blockOrder.add(idx);
                break;
            }
            case "content_block_delta": {
                int idx = (int) num(m.get("index"));
                Block b = blockMap.get(idx);
                Map d = (Map) m.get("delta");
                String t = (String) d.get("type");
                if (t.equals("thinking_delta")) b.thinking += (String) d.get("thinking");
                else if (t.equals("signature_delta")) b.signature += (String) d.get("signature");
                else if (t.equals("text_delta")) b.text += (String) d.get("text");
                else if (t.equals("input_json_delta")) b.raw += (String) d.get("partial_json");
                break;
            }
            case "message_delta": {
                Map d = (Map) m.get("delta");
                stopReason = (String) d.get("stop_reason");
                Map u = (Map) m.get("usage");
                if (u != null && u.get("output_tokens") != null) usageOutput += num(u.get("output_tokens"));
                break;
            }
            default:
                break;
        }
    }

    static void readReply(Response r) throws IOException {
        blockMap = new HashMap<>();
        blockOrder = new ArrayList<>();
        stopReason = "";
        ChunkedReader cr = new ChunkedReader(r.in);
        String evName = null;
        List<String> datas = new ArrayList<>();
        String line;
        while ((line = cr.readLine()) != null) {
            if (line.isEmpty()) {
                if (evName != null || !datas.isEmpty()) dispatch(evName, datas.isEmpty() ? null : String.join("\n", datas));
                evName = null;
                datas.clear();
                continue;
            }
            if (line.startsWith(":")) continue;
            int ci = line.indexOf(':');
            String f, v;
            if (ci < 0) { f = line; v = ""; }
            else { f = line.substring(0, ci); v = line.substring(ci + 1); if (v.startsWith(" ")) v = v.substring(1); }
            if (f.equals("event")) evName = v;
            else if (f.equals("data")) datas.add(v);
        }
        if (evName != null || !datas.isEmpty()) dispatch(evName, datas.isEmpty() ? null : String.join("\n", datas));
    }

    static void printBlocks() {
        for (int idx : blockOrder) {
            Block b = blockMap.get(idx);
            if (b.type.equals("thinking")) {
                out.println("thinking " + esc(b.thinking));
                out.println("signature " + esc(b.signature));
            } else if (b.type.equals("text")) {
                out.println("text " + esc(b.text));
            } else if (b.type.equals("tool_use")) {
                out.println("tool_use " + b.id + " " + b.name + " " + esc(b.raw));
            }
        }
        out.println("stop_reason " + esc(stopReason));
    }

    static List<Block> toolUseBlocks() {
        List<Block> l = new ArrayList<>();
        for (int idx : blockOrder) {
            Block b = blockMap.get(idx);
            if (b.type.equals("tool_use")) l.add(b);
        }
        return l;
    }

    static String[] runTool(Block b) { // returns {result, ok}
        Map in = (Map) jsonParse(b.raw);
        String text = (String) in.get("text");
        if (b.name.equals("measure")) {
            String unit = (String) in.get("unit");
            switch (unit) {
                case "code_points": return new String[]{String.valueOf(text.codePointCount(0, text.length())), "true"};
                case "utf8_bytes": return new String[]{String.valueOf(text.getBytes(StandardCharsets.UTF_8).length), "true"};
                case "utf16_units": return new String[]{String.valueOf(text.length()), "true"};
                default: return new String[]{"unsupported unit: " + unit, "false"};
            }
        } else if (b.name.equals("reverse")) {
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return new String[]{sb.toString(), "true"};
        } else {
            return new String[]{"unknown tool: " + b.name, "false"};
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        out = new PrintStream(new FileOutputStream(FileDescriptor.out), true, StandardCharsets.UTF_8);

        String dataDir = args[0];
        String baseUrl = args[1];
        String bu = baseUrl.substring("http://".length());
        int si = bu.indexOf('/');
        String hostport, bpath;
        if (si < 0) { hostport = bu; bpath = ""; } else { hostport = bu.substring(0, si); bpath = bu.substring(si); }
        int ci = hostport.indexOf(':');
        String host = ci < 0 ? hostport : hostport.substring(0, ci);
        int port = ci < 0 ? 80 : Integer.parseInt(hostport.substring(ci + 1));
        String path = bpath + "/v1/messages";

        String reqJson = new String(Files.readAllBytes(Paths.get(dataDir, "request.json")), StandardCharsets.UTF_8);
        Map cfg = (Map) jsonParse(reqJson);
        String apiKey = (String) cfg.get("api_key");
        Object model = cfg.get("model");
        Object maxTokens = cfg.get("max_tokens");
        Object budget = cfg.get("thinking_budget");
        Object system = cfg.get("system");
        Object prompt = cfg.get("prompt");
        Object tools = cfg.get("tools");

        // request 1
        out.println("request 1");
        List<Object> messages1 = new ArrayList<>();
        LinkedHashMap<Object,Object> um = new LinkedHashMap<>();
        um.put("role", "user");
        um.put("content", prompt);
        messages1.add(um);
        String body1 = buildBody(model, maxTokens, budget, system, tools, messages1);

        Response r1 = send(host, port, path, apiKey, body1);
        if (r1.status != 200) { handleError(r1); }
        readReply(r1);
        r1.close();
        printBlocks();

        // run tools
        List<Block> toolUses = toolUseBlocks();
        List<String[]> results = new ArrayList<>(); // {id, result, ok}
        for (Block b : toolUses) {
            String[] res = runTool(b);
            results.add(new String[]{b.id, res[0], res[1]});
            out.println((res[1].equals("true") ? "result " : "error ") + b.id + " " + esc(res[0]));
        }

        // request 2
        out.println("request 2");
        List<Object> assistantContent = new ArrayList<>();
        for (int idx : blockOrder) {
            Block b = blockMap.get(idx);
            LinkedHashMap<Object,Object> cb = new LinkedHashMap<>();
            if (b.type.equals("thinking")) {
                cb.put("type", "thinking");
                cb.put("thinking", b.thinking);
                cb.put("signature", b.signature);
            } else if (b.type.equals("text")) {
                cb.put("type", "text");
                cb.put("text", b.text);
            } else {
                cb.put("type", "tool_use");
                cb.put("id", b.id);
                cb.put("name", b.name);
                cb.put("input", jsonParse(b.raw));
            }
            assistantContent.add(cb);
        }
        List<Object> toolResults = new ArrayList<>();
        for (String[] res : results) {
            LinkedHashMap<Object,Object> tr = new LinkedHashMap<>();
            tr.put("type", "tool_result");
            tr.put("tool_use_id", res[0]);
            tr.put("content", res[1]);
            if (res[2].equals("false")) tr.put("is_error", Boolean.TRUE);
            toolResults.add(tr);
        }
        List<Object> messages2 = new ArrayList<>();
        messages2.add(um);
        LinkedHashMap<Object,Object> am = new LinkedHashMap<>();
        am.put("role", "assistant");
        am.put("content", assistantContent);
        messages2.add(am);
        LinkedHashMap<Object,Object> tm = new LinkedHashMap<>();
        tm.put("role", "user");
        tm.put("content", toolResults);
        messages2.add(tm);
        String body2 = buildBody(model, maxTokens, budget, system, tools, messages2);

        Response r2 = send(host, port, path, apiKey, body2);
        if (r2.status != 200) { handleError(r2); }
        readReply(r2);
        r2.close();
        printBlocks();

        out.println("usage input=" + usageInput + " output=" + usageOutput + " cache_read=" + usageCacheRead);
        out.flush();
    }

    static String buildBody(Object model, Object maxTokens, Object budget, Object system, Object tools, List<Object> messages) {
        LinkedHashMap<Object,Object> m = new LinkedHashMap<>();
        m.put("model", model);
        m.put("max_tokens", maxTokens);
        m.put("stream", Boolean.TRUE);
        LinkedHashMap<Object,Object> th = new LinkedHashMap<>();
        th.put("type", "enabled");
        th.put("budget_tokens", budget);
        m.put("thinking", th);
        m.put("system", system);
        m.put("tools", tools);
        m.put("messages", messages);
        return jsonWrite(m);
    }

    static void handleError(Response r) throws IOException {
        int len = Integer.parseInt(r.headers.get("content-length"));
        byte[] body = r.in.readNBytes(len);
        Map j = (Map) jsonParse(new String(body, StandardCharsets.UTF_8));
        Map err = (Map) j.get("error");
        String type = (String) err.get("type");
        String message = (String) err.get("message");
        out.println("ERROR " + r.status + " " + type + ": " + message);
        out.flush();
        System.exit(0);
    }
}

import sys, json, csv, http.client
from urllib.parse import urlparse

def main():
    data_dir, base_url = sys.argv[1], sys.argv[2]
    with open(data_dir + "/task.json", encoding="utf-8") as f:
        task = json.load(f)
    rows = {}
    with open(data_dir + "/inventory.csv", encoding="utf-8-sig", newline="") as f:
        r = csv.reader(f)
        header = next(r)
        for row in r:
            rows[row[0]] = row
    with open(data_dir + "/rates.json", encoding="utf-8") as f:
        rates = json.load(f)

    u = urlparse(base_url)
    conn = http.client.HTTPConnection(u.hostname, u.port)

    def compact(obj):
        return json.dumps(obj, separators=(",", ":"), ensure_ascii=False)

    def do_tool(name, args):
        if name == "inventory_lookup":
            sku = args["sku"]
            row = rows.get(sku)
            if row is None:
                return compact({"error": "unknown sku: " + sku})
            return compact({"sku": row[0], "name": row[1], "price_cents": int(row[2]),
                            "currency": row[3], "stock": int(row[4])})
        if name == "convert_currency":
            amount = args["amount_cents"]
            fr, to = args["from"], args["to"]
            rf, rt = rates["rates"][fr], rates["rates"][to]
            converted = (2 * amount * rt + rf) // (2 * rf)
            return compact({"amount_cents": converted, "currency": to})
        return compact({"error": "unknown tool: " + name})

    messages = [
        {"role": "system", "content": task["system"]},
        {"role": "user", "content": task["user"]},
    ]

    prompt_tokens = completion_tokens = total_tokens = 0
    n_requests = 0

    while True:
        body = json.dumps({
            "model": task["model"],
            "messages": messages,
            "tools": task["tools"],
            "tool_choice": "auto",
        }).encode("utf-8")
        headers = {
            "Authorization": "Bearer " + task["api_key"],
            "Content-Type": "application/json",
            "Content-Length": str(len(body)),
            "Host": u.netloc,
        }
        conn.request("POST", u.path + "/chat/completions", body=body, headers=headers)
        resp = conn.getresponse()
        data = resp.read()
        n_requests += 1
        if resp.status != 200:
            try:
                err = json.loads(data.decode("utf-8"))
                msg = err["error"]["message"]
            except Exception:
                msg = data.decode("utf-8", "replace")
            print("ERROR %d %s" % (resp.status, msg))
            return
        obj = json.loads(data.decode("utf-8"))
        usage = obj.get("usage") or {}
        prompt_tokens += usage.get("prompt_tokens", 0)
        completion_tokens += usage.get("completion_tokens", 0)
        total_tokens += usage.get("total_tokens", 0)
        choice = obj["choices"][0]
        msg = choice["message"]
        fr = choice["finish_reason"]
        if fr == "stop":
            print("FINAL %s" % msg["content"])
            break
        # tool_calls
        if isinstance(msg.get("content"), str):
            print("SAY %s" % msg["content"])
        assistant = {"role": "assistant", "content": msg.get("content"),
                     "tool_calls": msg["tool_calls"]}
        messages.append(assistant)
        results = []
        for tc in msg["tool_calls"]:
            print("CALL %s %s" % (tc["id"], tc["function"]["name"]))
            args = json.loads(tc["function"]["arguments"])
            result = do_tool(tc["function"]["name"], args)
            results.append((tc["id"], result))
        for tid, result in results:
            print("RESULT %s %s" % (tid, result))
            messages.append({"role": "tool", "tool_call_id": tid, "content": result})

    print("USAGE prompt=%d completion=%d total=%d requests=%d" %
          (prompt_tokens, completion_tokens, total_tokens, n_requests))

main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

static uint8_t *db;
static uint32_t page_size, usable;

static uint16_t be16(const uint8_t *p){ return (uint16_t)((p[0]<<8)|p[1]); }
static uint32_t be32(const uint8_t *p){ return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]; }

static uint64_t get_varint(const uint8_t *p, int *n){
    uint64_t r=0;
    for(int i=0;i<8;i++){
        r=(r<<7)|(p[i]&0x7f);
        if(!(p[i]&0x80)){ *n=i+1; return r; }
    }
    r=(r<<8)|p[8]; *n=9; return r;
}

static int64_t read_int(const uint8_t *p, int nb){
    int64_t v = (p[0]&0x80)? -1 : 0;
    for(int i=0;i<nb;i++) v=(v<<8)|p[i];
    return v;
}

static char *my_strndup(const char *s, size_t n){
    char *r=malloc(n+1); memcpy(r,s,n); r[n]=0; return r;
}

/* ---------- rows ---------- */
typedef struct { int64_t rowid; uint8_t *payload; uint64_t len; } Row;
static Row *rows; static size_t nrows, caprows;

static void add_row(int64_t rowid, uint8_t *payload, uint64_t len){
    if(nrows==caprows){ caprows=caprows?caprows*2:64; rows=realloc(rows,caprows*sizeof(Row)); }
    rows[nrows].rowid=rowid; rows[nrows].payload=payload; rows[nrows].len=len; nrows++;
}

static uint8_t *assemble(const uint8_t *pg, uint64_t poff, uint64_t paylen, uint64_t local){
    uint8_t *buf=malloc(paylen?paylen:1);
    uint64_t t = local<paylen?local:paylen;
    memcpy(buf, pg+poff, t);
    uint64_t pos=t;
    uint32_t ovf = be32(pg+poff+local);
    while(pos<paylen){
        const uint8_t *op = db + (uint64_t)(ovf-1)*page_size;
        uint64_t chunk = usable-4;
        if(chunk > paylen-pos) chunk = paylen-pos;
        memcpy(buf+pos, op+4, chunk);
        pos += chunk;
        ovf = be32(op);
    }
    return buf;
}

static void walk(uint32_t pgno){
    const uint8_t *pg = db + (uint64_t)(pgno-1)*page_size;
    uint64_t h = (pgno==1)?100:0;
    uint8_t type = pg[h];
    uint16_t ncell = be16(pg+h+3);
    if(type==5){
        for(uint16_t i=0;i<ncell;i++){
            uint64_t off = be16(pg+h+12+2*i);
            walk(be32(pg+off));
        }
        walk(be32(pg+h+8));
    } else if(type==13){
        for(uint16_t i=0;i<ncell;i++){
            uint64_t off = be16(pg+h+8+2*i);
            int l1,l2;
            uint64_t paylen = get_varint(pg+off,&l1);
            uint64_t rid = get_varint(pg+off+l1,&l2);
            uint64_t U=usable, X=U-35, local;
            if(paylen<=X) local=paylen;
            else{
                uint64_t M=((U-12)*32)/255-23;
                uint64_t K=M+((paylen-M)%(U-4));
                local = (K<=X)?K:M;
            }
            add_row((int64_t)rid, assemble(pg, off+l1+l2, paylen, local), paylen);
        }
    }
}

static int cmp_row(const void *a, const void *b){
    int64_t x=((const Row*)a)->rowid, y=((const Row*)b)->rowid;
    return (x>y)-(x<y);
}

/* ---------- records ---------- */
typedef struct { int st; int64_t i; double d; const uint8_t *p; uint64_t n; } Val;

static Val *parse_record(const uint8_t *payload, uint64_t len, int *count){
    (void)len;
    int l; uint64_t hsize = get_varint(payload,&l);
    uint64_t p=l;
    int nv=0, cap=64;
    uint64_t *sts=malloc(cap*sizeof(uint64_t));
    while(p<hsize){
        if(nv==cap){ cap*=2; sts=realloc(sts,cap*sizeof(uint64_t)); }
        sts[nv++]=get_varint(payload+p,&l); p+=l;
    }
    Val *v=calloc(nv?nv:1,sizeof(Val));
    uint64_t body=hsize;
    for(int i=0;i<nv;i++){
        uint64_t s=sts[i];
        if(s<=6){
            static const int nb[7]={0,1,2,3,4,6,8};
            v[i].st=1; v[i].i=read_int(payload+body,nb[s]); body+=nb[s];
        } else if(s==7){
            uint64_t b=0; for(int j=0;j<8;j++) b=(b<<8)|payload[body+j];
            memcpy(&v[i].d,&b,8); v[i].st=7; body+=8;
        } else if(s==8){ v[i].st=1; v[i].i=0; }
        else if(s==9){ v[i].st=1; v[i].i=1; }
        else if(s>=12){
            uint64_t sz=(s-12-(s&1))/2;
            v[i].st=(s&1)?13:12; v[i].p=payload+body; v[i].n=sz; body+=sz;
        } else { v[i].st=0; }
    }
    free(sts);
    *count=nv; return v;
}

/* ---------- crc32 ---------- */
static uint32_t ct[256];
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){
        uint32_t c=i;
        for(int j=0;j<8;j++) c = (c&1)?(0xEDB88320^(c>>1)):(c>>1);
        ct[i]=c;
    }
}
static uint32_t crc32b(const uint8_t *p, uint64_t n){
    uint32_t c=0xFFFFFFFF;
    for(uint64_t i=0;i<n;i++) c=ct[(c^p[i])&0xFF]^(c>>8);
    return c^0xFFFFFFFF;
}

/* ---------- value printing ---------- */
static void escape_text(const uint8_t *p, uint64_t n){
    for(uint64_t i=0;i<n;i++){
        uint8_t b=p[i];
        switch(b){
            case '\\': fputs("\\\\",stdout); break;
            case '"': fputs("\\\"",stdout); break;
            case '\n': fputs("\\n",stdout); break;
            case '\r': fputs("\\r",stdout); break;
            case '\t': fputs("\\t",stdout); break;
            default:
                if(b<0x20||b==0x7F) printf("\\x%02X",b);
                else putchar(b);
        }
    }
}

static void print_real(double d){
    uint64_t bits; memcpy(&bits,&d,8);
    int neg=(int)(bits>>63);
    int expf=(int)((bits>>52)&0x7FF);
    uint64_t mant=bits & 0xFFFFFFFFFFFFFULL;
    if(expf==0){
        if(mant==0){ printf("%s0.0", neg?"-":""); return; }
    } else mant |= 1ULL<<52;
    int e = expf ? expf-1075 : -1074;
    if(e>=0){
        uint32_t limbs[160]; int n=0;
        limbs[n++]=(uint32_t)(mant%1000000000);
        uint64_t hi=mant/1000000000;
        if(hi) limbs[n++]=(uint32_t)hi;
        for(int i=0;i<e;i++){
            uint64_t carry=0;
            for(int j=0;j<n;j++){
                uint64_t v=(uint64_t)limbs[j]*2+carry;
                limbs[j]=(uint32_t)(v%1000000000); carry=v/1000000000;
            }
            if(carry) limbs[n++]=(uint32_t)carry;
        }
        printf("%s%u", neg?"-":"", limbs[n-1]);
        for(int j=n-2;j>=0;j--) printf("%09u", limbs[j]);
        printf(".0");
        return;
    }
    int k=-e;
    uint64_t ip, frac;
    if(k>=64){ ip=0; frac=mant; }
    else { ip=mant>>k; frac=mant&((1ULL<<k)-1); }
    printf("%s%llu", neg?"-":"", (unsigned long long)ip);
    if(k<120){
        unsigned __int128 rem=frac, mask=(((unsigned __int128)1)<<k)-1;
        char digits[512]; int n=0;
        while(rem && n<500){
            rem*=10;
            digits[n++]=(char)('0'+(int)(rem>>k));
            rem&=mask;
        }
        putchar('.');
        if(n==0) putchar('0'); else fwrite(digits,1,n,stdout);
    } else {
        printf(".0");
    }
}

static void print_val(const Val *v){
    switch(v->st){
        case 0: fputs("NULL",stdout); break;
        case 1: printf("%lld",(long long)v->i); break;
        case 7: print_real(v->d); break;
        case 13:
            if(v->n<=100){ putchar('"'); escape_text(v->p,v->n); putchar('"'); }
            else printf("<TEXT len=%llu crc32=%08x>",(unsigned long long)v->n,crc32b(v->p,v->n));
            break;
        case 12:
            if(v->n<=100){
                fputs("X'",stdout);
                for(uint64_t i=0;i<v->n;i++) printf("%02X",v->p[i]);
                putchar('\'');
            } else printf("<BLOB len=%llu crc32=%08x>",(unsigned long long)v->n,crc32b(v->p,v->n));
            break;
        default: fputs("NULL",stdout); break;
    }
}

/* ---------- schema / columns ---------- */
typedef struct { char *name; uint32_t root; char *sql; } Table;

static char **cols; static int *alias; static int ncols;

static void add_def(const char *s, const char *e, char ***colsp, int **aliasp, int *np, int *capp){
    while(s<e && isspace((unsigned char)*s)) s++;
    char *name;
    if(s<e && *s=='"'){
        s++; const char *st=s;
        while(s<e && *s!='"') s++;
        name=my_strndup(st,s-st);
        s++;
    } else {
        const char *st=s;
        while(s<e && (isalnum((unsigned char)*s)||*s=='_')) s++;
        name=my_strndup(st,s-st);
    }
    const char *w=s;
    char words[64][32]; int nw=0;
    while(w<e && nw<64){
        while(w<e && isspace((unsigned char)*w)) w++;
        if(w>=e || !(isalnum((unsigned char)*w)||*w=='_')) break;
        const char *ws=w;
        while(w<e && (isalnum((unsigned char)*w)||*w=='_')) w++;
        int ln=w-ws; if(ln>31) ln=31;
        memcpy(words[nw],ws,ln); words[nw][ln]=0;
        for(char *c=words[nw];*c;c++) *c=(char)toupper((unsigned char)*c);
        nw++;
    }
    static const char *ck[]={"PRIMARY","NOT","NULL","UNIQUE","CHECK","DEFAULT","COLLATE","REFERENCES","GENERATED","CONSTRAINT"};
    int typew=0;
    for(int i=0;i<nw;i++){
        int isc=0;
        for(unsigned j=0;j<sizeof(ck)/sizeof(ck[0]);j++) if(!strcmp(words[i],ck[j])) isc=1;
        if(isc) break;
        typew++;
    }
    int haspk=0;
    for(int i=0;i+1<nw;i++)
        if(!strcmp(words[i],"PRIMARY")&&!strcmp(words[i+1],"KEY")) haspk=1;
    int isalias = (typew==1 && !strcmp(words[0],"INTEGER") && haspk);
    if(*np==*capp){
        *capp=*capp?*capp*2:8;
        *colsp=realloc(*colsp,*capp*sizeof(char*));
        *aliasp=realloc(*aliasp,*capp*sizeof(int));
    }
    (*colsp)[*np]=name; (*aliasp)[*np]=isalias; (*np)++;
}

static void parse_columns(const char *sql){
    cols=NULL; alias=NULL; ncols=0; int cap=0;
    const char *p=sql;
    while(*p && isspace((unsigned char)*p)) p++;
    while(*p && !isspace((unsigned char)*p)) p++;           /* CREATE */
    while(*p && isspace((unsigned char)*p)) p++;
    while(*p && !isspace((unsigned char)*p)) p++;           /* TABLE  */
    while(*p && isspace((unsigned char)*p)) p++;
    if(*p=='"'){ p++; while(*p && *p!='"') p++; if(*p) p++; }
    else while(*p && !isspace((unsigned char)*p) && *p!='(') p++;
    while(*p && isspace((unsigned char)*p)) p++;
    if(*p=='(') p++;
    const char *ds=p, *q=p;
    int depth=0, inq=0;
    while(*q){
        char c=*q;
        if(inq){ if(c=='"') inq=0; }
        else if(c=='"') inq=1;
        else if(c=='(') depth++;
        else if(c==')'){ if(depth==0) break; depth--; }
        else if(c==',' && depth==0){ add_def(ds,q,&cols,&alias,&ncols,&cap); ds=q+1; }
        q++;
    }
    add_def(ds,q,&cols,&alias,&ncols,&cap);
}

static int cmp_table(const void *a, const void *b){
    return strcmp(((const Table*)a)->name, ((const Table*)b)->name);
}

/* ---------- main ---------- */
int main(int argc, char **argv){
    if(argc<2) return 0;
    crc_init();
    char path[4096];
    snprintf(path,sizeof path,"%s/db.sqlite",argv[1]);
    FILE *f=fopen(path,"rb");
    if(!f) return 0;
    fseek(f,0,SEEK_END);
    long sz=ftell(f);
    fseek(f,0,SEEK_SET);
    db=malloc(sz?sz:1);
    if(sz>0 && fread(db,1,sz,f)!=(size_t)sz){ fclose(f); return 0; }
    fclose(f);

    page_size = be16(db+16);
    if(page_size==1) page_size=65536;
    usable = page_size - db[20];

    nrows=0; caprows=0; rows=NULL;

    /* schema */
    walk(1);
    Table *tables=NULL; int ntables=0, capt=0;
    for(size_t i=0;i<nrows;i++){
        int nv; Val *v=parse_record(rows[i].payload,rows[i].len,&nv);
        if(nv>=5 && v[0].st==13 && v[0].n==5 && !memcmp(v[0].p,"table",5)
           && v[1].st==13 && !(v[1].n>=7 && !memcmp(v[1].p,"sqlite_",7))
           && v[3].st==1 && v[4].st==13){
            if(ntables==capt){ capt=capt?capt*2:8; tables=realloc(tables,capt*sizeof(Table)); }
            tables[ntables].name=my_strndup((const char*)v[1].p,v[1].n);
            tables[ntables].root=(uint32_t)v[3].i;
            tables[ntables].sql=my_strndup((const char*)v[4].p,v[4].n);
            ntables++;
        }
        free(v); free(rows[i].payload);
    }
    nrows=0;

    qsort(tables,ntables,sizeof(Table),cmp_table);

    for(int ti=0; ti<ntables; ti++){
        if(ti) putchar('\n');
        parse_columns(tables[ti].sql);
        nrows=0;
        walk(tables[ti].root);
        qsort(rows,nrows,sizeof(Row),cmp_row);
        printf("TABLE %s rows=%zu\n", tables[ti].name, nrows);
        fputs("COLUMNS ",stdout);
        for(int j=0;j<ncols;j++){ if(j) fputs(", ",stdout); fputs(cols[j],stdout); }
        putchar('\n');
        for(size_t i=0;i<nrows;i++){
            int nv; Val *v=parse_record(rows[i].payload,rows[i].len,&nv);
            printf("%lld:",(long long)rows[i].rowid);
            for(int j=0;j<ncols;j++){
                fputs(j?", ":" ",stdout);
                if(alias[j]) printf("%lld",(long long)rows[i].rowid);
                else if(j>=nv) fputs("NULL",stdout);
                else print_val(&v[j]);
            }
            putchar('\n');
            free(v); free(rows[i].payload);
        }
        nrows=0;
        for(int j=0;j<ncols;j++) free(cols[j]);
        free(cols); free(alias);
        free(tables[ti].name); free(tables[ti].sql);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

static uint8_t *db;
static uint32_t page_size, usable;

static uint16_t be16(const uint8_t *p){ return (uint16_t)((p[0]<<8)|p[1]); }
static uint32_t be32(const uint8_t *p){ return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]; }

static uint64_t get_varint(const uint8_t *p, int *n){
    uint64_t r=0;
    for(int i=0;i<8;i++){
        r=(r<<7)|(p[i]&0x7f);
        if(!(p[i]&0x80)){ *n=i+1; return r; }
    }
    r=(r<<8)|p[8]; *n=9; return r;
}

static int64_t read_int(const uint8_t *p, int nb){
    int64_t v = (p[0]&0x80)? -1 : 0;
    for(int i=0;i<nb;i++) v=(v<<8)|p[i];
    return v;
}

static char *my_strndup(const char *s, size_t n){
    char *r=malloc(n+1); memcpy(r,s,n); r[n]=0; return r;
}

/* ---------- rows ---------- */
typedef struct { int64_t rowid; uint8_t *payload; uint64_t len; } Row;
static Row *rows; static size_t nrows, caprows;

static void add_row(int64_t rowid, uint8_t *payload, uint64_t len){
    if(nrows==caprows){ caprows=caprows?caprows*2:64; rows=realloc(rows,caprows*sizeof(Row)); }
    rows[nrows].rowid=rowid; rows[nrows].payload=payload; rows[nrows].len=len; nrows++;
}

static uint8_t *assemble(const uint8_t *pg, uint64_t poff, uint64_t paylen, uint64_t local){
    uint8_t *buf=malloc(paylen?paylen:1);
    uint64_t t = local<paylen?local:paylen;
    memcpy(buf, pg+poff, t);
    uint64_t pos=t;
    uint32_t ovf = be32(pg+poff+local);
    while(pos<paylen){
        const uint8_t *op = db + (uint64_t)(ovf-1)*page_size;
        uint64_t chunk = usable-4;
        if(chunk > paylen-pos) chunk = paylen-pos;
        memcpy(buf+pos, op+4, chunk);
        pos += chunk;
        ovf = be32(op);
    }
    return buf;
}

static void walk(uint32_t pgno){
    const uint8_t *pg = db + (uint64_t)(pgno-1)*page_size;
    uint64_t h = (pgno==1)?100:0;
    uint8_t type = pg[h];
    uint16_t ncell = be16(pg+h+3);
    if(type==5){
        for(uint16_t i=0;i<ncell;i++){
            uint64_t off = be16(pg+h+12+2*i);
            walk(be32(pg+off));
        }
        walk(be32(pg+h+8));
    } else if(type==13){
        for(uint16_t i=0;i<ncell;i++){
            uint64_t off = be16(pg+h+8+2*i);
            int l1,l2;
            uint64_t paylen = get_varint(pg+off,&l1);
            uint64_t rid = get_varint(pg+off+l1,&l2);
            uint64_t U=usable, X=U-35, local;
            if(paylen<=X) local=paylen;
            else{
                uint64_t M=((U-12)*32)/255-23;
                uint64_t K=M+((paylen-M)%(U-4));
                local = (K<=X)?K:M;
            }
            add_row((int64_t)rid, assemble(pg, off+l1+l2, paylen, local), paylen);
        }
    }
}

static int cmp_row(const void *a, const void *b){
    int64_t x=((const Row*)a)->rowid, y=((const Row*)b)->rowid;
    return (x>y)-(x<y);
}

/* ---------- records ---------- */
typedef struct { int st; int64_t i; double d; const uint8_t *p; uint64_t n; } Val;

static Val *parse_record(const uint8_t *payload, uint64_t len, int *count){
    (void)len;
    int l; uint64_t hsize = get_varint(payload,&l);
    uint64_t p=l;
    int nv=0, cap=64;
    uint64_t *sts=malloc(cap*sizeof(uint64_t));
    while(p<hsize){
        if(nv==cap){ cap*=2; sts=realloc(sts,cap*sizeof(uint64_t)); }
        sts[nv++]=get_varint(payload+p,&l); p+=l;
    }
    Val *v=calloc(nv?nv:1,sizeof(Val));
    uint64_t body=hsize;
    for(int i=0;i<nv;i++){
        uint64_t s=sts[i];
        if(s==0 || s==10 || s==11){
            v[i].st=0;
        } else if(s<=6){
            static const int nb[7]={0,1,2,3,4,6,8};
            v[i].st=1; v[i].i=read_int(payload+body,nb[s]); body+=nb[s];
        } else if(s==7){
            uint64_t b=0; for(int j=0;j<8;j++) b=(b<<8)|payload[body+j];
            memcpy(&v[i].d,&b,8); v[i].st=7; body+=8;
        } else if(s==8){ v[i].st=1; v[i].i=0; }
        else if(s==9){ v[i].st=1; v[i].i=1; }
        else if(s>=12){
            uint64_t sz=(s-12-(s&1))/2;
            v[i].st=(s&1)?13:12; v[i].p=payload+body; v[i].n=sz; body+=sz;
        } else { v[i].st=0; }
    }
    free(sts);
    *count=nv; return v;
}

