    const char *p=sql;
    while(*p && isspace((unsigned char)*p)) p++;
    while(*p && !isspace((unsigned char)*p)) p++;           /* CREATE */
    while(*p && isspace((unsigned char)*p)) p++;
    while(*p && !isspace((unsigned char)*p)) p++;           /* TABLE  */
    while(*p && isspace((unsigned char)*p)) p++;
    if(*p=='"'){ p++; while(*p && *p!='"') p++; if(*p) p++; }
    else while(*p && !isspace((unsigned char)*p) && *p!='(') p++;
    while(*p && isspace((unsigned char)*p)) p++;
    if(*p=='(') p++;
    const char *ds=p, *q=p;
    int depth=0, inq=0;
    while(*q){
        char c=*q;
        if(inq){ if(c=='"') inq=0; }
        else if(c=='"') inq=1;
        else if(c=='(') depth++;
        else if(c==')'){ if(depth==0) break; depth--; }
        else if(c==',' && depth==0){ add_def(ds,q,&cols,&alias,&ncols,&cap); ds=q+1; }
        q++;
    }
    add_def(ds,q,&cols,&alias,&ncols,&cap);
}

static int cmp_table(const void *a, const void *b){
    return strcmp(((const Table*)a)->name, ((const Table*)b)->name);
}

