// --- JSON compact serializer with required escaping ---
function escStr(s: string): string {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '"') out += '\\"';
    else if (ch === "\\") out += "\\\\";
    else if (cp === 8) out += "\\b";
    else if (cp === 12) out += "\\f";
    else if (cp === 10) out += "\\n";
    else if (cp === 13) out += "\\r";
    else if (cp === 9) out += "\\t";
    else if (cp < 0x20) out += "\\u" + cp.toString(16).padStart(4, "0");
    else out += ch;
  }
  return out + '"';
}

function compact(v: any): string {
  if (typeof v === "string") return escStr(v);
  if (typeof v === "number" || typeof v === "boolean" || v === null) return String(v);
  if (Array.isArray(v)) return "[" + v.map(compact).join(",") + "]";
  return "{" + Object.keys(v).map((k) => escStr(k) + ":" + compact(v[k])).join(",") + "}";
}

// --- Tools ---
function runTool(name: string, argsJson: string): string {
  let args: any;
  try { args = JSON.parse(argsJson); } catch { return '{"error":"bad arguments"}'; }
  if (name === "inventory_lookup") {
    const sku: string = args.sku;
    const row = inventory.get(sku);
    if (!row) return compact({ error: `unknown sku: ${sku}` });
    return compact({ sku: row.sku, name: row.name, price_cents: row.price_cents, currency: row.currency, stock: row.stock });
  }
  if (name === "convert_currency") {
    const amount: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rf = rates.rates[from], rt = rates.rates[to];
    const converted = Math.floor((2 * amount * rt + rf) / (2 * rf));
    return compact({ amount_cents: converted, currency: to });
  }
  return compact({ error: `unknown tool: ${name}` });
}

// --- Main loop ---
async function main() {
  const messages: any[] = [
    { role: "system", content: task.system },
    { role: "user", content: task.user },
  ];
  let promptTokens = 0, completionTokens = 0, totalTokens = 0, requests = 0;

  for (;;) {
    const body = {
      model: task.model,
      messages,
      tools: task.tools,
      tool_choice: "auto",
    };
    const res = await fetch(baseUrl + "/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${task.api_key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
    requests++;
    const text = await res.text();
    if (res.status !== 200) {
      let msg = "";
      try { msg = JSON.parse(text).error.message; } catch {}
      console.log(`ERROR ${res.status} ${msg}`);
      process.exit(0);
    }
    const data = JSON.parse(text);
    const u = data.usage || {};
    promptTokens += u.prompt_tokens || 0;
    completionTokens += u.completion_tokens || 0;
    totalTokens += u.total_tokens || 0;

    const choice = data.choices[0];
    const message = choice.message;
    const finish = choice.finish_reason;

    if (finish === "tool_calls") {
      if (typeof message.content === "string") console.log(`SAY ${message.content}`);
      const kept: any = { role: message.role, content: message.content };
      if (message.tool_calls !== undefined) {
        kept.tool_calls = message.tool_calls.map((tc: any) => ({
          id: tc.id,
          type: tc.type,
          function: { name: tc.function.name, arguments: tc.function.arguments },
        }));
      }
      messages.push(kept);
      for (const tc of message.tool_calls) {
        console.log(`CALL ${tc.id} ${tc.function.name}`);
      }
      for (const tc of message.tool_calls) {
        const result = runTool(tc.function.name, tc.function.arguments);
        console.log(`RESULT ${tc.id} ${result}`);
        messages.push({ role: "tool", tool_call_id: tc.id, content: result });
      }
    } else {
      console.log(`FINAL ${message.content}`);
      break;
    }
  }
  console.log(`USAGE prompt=${promptTokens} completion=${completionTokens} total=${totalTokens} requests=${requests}`);
}

