import Foundation

// ---------- JSON string escaping ----------
func esc(_ s: String) -> String {
    var out = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\"": out += "\\\""
        case "\\": out += "\\\\"
        case "\u{08}": out += "\\b"
        case "\u{0C}": out += "\\f"
        case "\n": out += "\\n"
        case "\r": out += "\\r"
        case "\t": out += "\\t"
        default:
            if c.value < 0x20 {
                out += String(format: "\\u%04x", c.value)
            } else {
                out.unicodeScalars.append(c)
            }
        }
    }
    return out + "\""
}

// ---------- CSV parsing ----------
struct Item {
    let sku: String
    let name: String
    let priceCents: Int
    let currency: String
    let stock: Int
}

func parseCSV(_ text0: String) -> [[String]] {
    var text = text0
    if text.hasPrefix("\u{FEFF}") { text.removeFirst() }
    var rows: [[String]] = []
    var row: [String] = []
    var field = ""
    var inQuotes = false
    let chars = Array(text)
    var i = 0
    while i < chars.count {
        let c = chars[i]
        if inQuotes {
            if c == "\"" {
                if i + 1 < chars.count && chars[i+1] == "\"" {
                    field.append("\"")
                    i += 2
                } else {
                    inQuotes = false
                    i += 1
                }
            } else {
                field.append(c)
                i += 1
            }
        } else {
            if c == "\"" {
                inQuotes = true
                i += 1
            } else if c == "," {
                row.append(field)
                field = ""
                i += 1
            } else if c == "\r" {
                row.append(field)
                rows.append(row)
                row = []
                field = ""
                if i + 1 < chars.count && chars[i+1] == "\n" { i += 2 } else { i += 1 }
            } else if c == "\n" {
                row.append(field)
                rows.append(row)
                row = []
                field = ""
                i += 1
            } else {
                field.append(c)
                i += 1
            }
        }
    }
    if !field.isEmpty || !row.isEmpty {
        row.append(field)
        rows.append(row)
    }
    return rows
}

// ---------- HTTP ----------
func postSync(url: URL, apiKey: String, body: Data) -> (Int, Data) {
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    req.setValue("application/json", forHTTPHeaderField: "Content-Type")
    req.httpBody = body
    let sem = DispatchSemaphore(value: 0)
    var outData: Data? = nil
    var outResp: URLResponse? = nil
    var outErr: Error? = nil
    let task = URLSession.shared.dataTask(with: req) { d, r, e in
        outData = d; outResp = r; outErr = e
        sem.signal()
    }
    task.resume()
    sem.wait()
    if let e = outErr {
        FileHandle.standardOutput.write(Data("ERROR 0 \(e.localizedDescription)\n".utf8))
        exit(0)
    }
    let http = outResp as! HTTPURLResponse
    return (http.statusCode, outData ?? Data())
}

