    if let e = outErr {
        FileHandle.standardOutput.write(Data("ERROR 0 \(e.localizedDescription)\n".utf8))
        exit(0)
    }
    let http = outResp as! HTTPURLResponse
    return (http.statusCode, outData ?? Data())
}

