func runTool(name: String, arguments: String) -> String {
    let argsObj = (try? JSONSerialization.jsonObject(with: Data(arguments.utf8))) as? [String: Any] ?? [:]
    switch name {
    case "inventory_lookup":
        let sku = argsObj["sku"] as? String ?? ""
        if let it = inventory[sku] {
            return "{\"sku\":\(esc(it.sku)),\"name\":\(esc(it.name)),\"price_cents\":\(it.priceCents),\"currency\":\(esc(it.currency)),\"stock\":\(it.stock)}"
        } else {
            return "{\"error\":\(esc("unknown sku: \(sku)"))}"
        }
    case "convert_currency":
        let amount = (argsObj["amount_cents"] as? NSNumber)?.intValue ?? 0
        let from = argsObj["from"] as? String ?? ""
        let to = argsObj["to"] as? String ?? ""
        let rf = rates[from] ?? 1
        let rt = rates[to] ?? 1
        let converted = (2 * amount * rt + rf) / (2 * rf)
        return "{\"amount_cents\":\(converted),\"currency\":\(esc(to))}"
    default:
        return "{\"error\":\(esc("unknown tool: \(name)"))}"
    }
}

