import Foundation

func die(_ msg: String) -> Never {
    FileHandle.standardError.write((msg + "\n").data(using: .utf8)!)
    exit(1)
}

// ---------- Networking ----------

func tcpConnect(host: String, port: String) -> Int32 {
    var hints = addrinfo()
    hints.ai_family = AF_UNSPEC
    hints.ai_socktype = SOCK_STREAM
    var res: UnsafeMutablePointer<addrinfo>? = nil
    let rc = getaddrinfo(host, port, &hints, &res)
    guard rc == 0, res != nil else { die("getaddrinfo failed") }
    defer { freeaddrinfo(res) }
    var cur: UnsafeMutablePointer<addrinfo>? = res
    while let p = cur {
        let fd = socket(p.pointee.ai_family, p.pointee.ai_socktype, p.pointee.ai_protocol)
        if fd >= 0 {
            if connect(fd, p.pointee.ai_addr, p.pointee.ai_addrlen) == 0 { return fd }
            close(fd)
        }
        cur = p.pointee.ai_next
    }
    die("connect failed")
}

func sendAll(_ fd: Int32, _ data: Data) {
    let bytes = [UInt8](data)
    var sent = 0
    while sent < bytes.count {
        let n = bytes.withUnsafeBufferPointer { buf -> Int in
            send(fd, UnsafeRawPointer(buf.baseAddress! + sent), bytes.count - sent, 0)
        }
        if n <= 0 { die("send failed") }
        sent += n
    }
}

func findCRLFCRLF(_ b: [UInt8]) -> Int? {
    guard b.count >= 4 else { return nil }
    for i in 0...(b.count - 4) {
        if b[i] == 13, b[i + 1] == 10, b[i + 2] == 13, b[i + 3] == 10 { return i }
    }
    return nil
}

func recvResponse(_ fd: Int32) -> (status: Int, headers: [String: String], body: Data) {
    var buf: [UInt8] = []
    var chunk = [UInt8](repeating: 0, count: 65536)
    var headerEnd = -1
    while true {
        if let idx = findCRLFCRLF(buf) { headerEnd = idx; break }
        let n = chunk.withUnsafeBufferPointer { b -> Int in
            recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
        }
        if n <= 0 { die("no response headers") }
        buf += chunk[0..<n]
    }
    let headerData = Data(buf[0..<headerEnd])
    guard let headerStr = String(data: headerData, encoding: .utf8) else { die("bad headers") }
    var hlines = headerStr.components(separatedBy: "\r\n")
    let statusLine = hlines.removeFirst()
    let parts = statusLine.split(separator: " ")
    guard parts.count >= 2, let status = Int(parts[1]) else { die("bad status line") }
    var headers: [String: String] = [:]
    for line in hlines {
        guard let ci = line.firstIndex(of: ":") else { continue }
        let k = String(line[..<ci]).lowercased()
        var v = String(line[line.index(after: ci)...])
        if v.hasPrefix(" ") { v.removeFirst() }
        headers[k] = v
    }
    var body = Array(buf[(headerEnd + 4)...])
    if status == 200 {
        while true {
            let n = chunk.withUnsafeBufferPointer { b -> Int in
                recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
            }
            if n < 0 { die("recv failed") }
            if n == 0 { break }
            body += chunk[0..<n]
        }
    } else {
        let cl = Int(headers["content-length"] ?? "0") ?? 0
        while body.count < cl {
            let n = chunk.withUnsafeBufferPointer { b -> Int in
                recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
            }
            if n <= 0 { die("recv failed") }
            body += chunk[0..<n]
        }
        body = Array(body[0..<cl])
    }
    close(fd)
    return (status, headers, Data(body))
}

func dechunk(_ data: Data) -> Data {
    let b = [UInt8](data)
    var i = 0
    var out: [UInt8] = []
    while i < b.count {
        let start = i
        while i < b.count && b[i] != 13 && b[i] != 10 { i += 1 }
        var sizeStr = String(bytes: b[start..<i], encoding: .utf8) ?? ""
        if i < b.count && b[i] == 13 { i += 1 }
        if i < b.count && b[i] == 10 { i += 1 }
        if let semi = sizeStr.firstIndex(of: ";") { sizeStr = String(sizeStr[..<semi]) }
        guard let size = Int(sizeStr.trimmingCharacters(in: .whitespaces), radix: 16) else { die("bad chunk size") }
        if size == 0 { break }
        guard i + size <= b.count else { die("truncated chunk") }
        out += b[i..<(i + size)]
        i += size
        if i < b.count && b[i] == 13 { i += 1 }
        if i < b.count && b[i] == 10 { i += 1 }
    }
    return Data(out)
}

func parseSSE(_ data: Data) -> [(String, String)] {
    guard let s = String(data: data, encoding: .utf8) else { die("bad sse encoding") }
    var events: [(String, String)] = []
    var event = ""
    var datas: [String] = []
    func flush() {
        if !datas.isEmpty { events.append((event, datas.joined(separator: "\n"))) }
        event = ""
        datas = []
    }
    for rawLine in s.split(separator: "\n", omittingEmptySubsequences: false) {
        var line = String(rawLine)
        if line.hasSuffix("\r") { line.removeLast() }
        if line.isEmpty { flush(); continue }
        if line.hasPrefix(":") { continue }
        guard let ci = line.firstIndex(of: ":") else { continue }
        let field = String(line[..<ci])
        var value = String(line[line.index(after: ci)...])
        if value.hasPrefix(" ") { value.removeFirst() }
        if field == "event" { event = value }
        else if field == "data" { datas.append(value) }
    }
    flush()
    return events
}

// ---------- Output helpers ----------

func esc(_ s: String) -> String {
    var r = ""
    for c in s {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.append(c)
        }
    }
    return r
}

// ---------- Model of a reply ----------

struct Block {
    var type = ""
    var thinking = ""
    var signature = ""
    var text = ""
    var id = ""
    var name = ""
    var json = ""
}

struct Reply {
    var blocks: [Block]
    var stopReason: String
    var input: Int
    var output: Int
    var cacheRead: Int
}

enum ReplyOrError {
    case reply(Reply)
    case error(Int, String, String)
}

