func recvResponse(_ fd: Int32) -> (status: Int, headers: [String: String], body: Data) {
    var buf: [UInt8] = []
    let chunk = [UInt8](repeating: 0, count: 65536)
    var headerEnd = -1
    while true {
        if let idx = findCRLFCRLF(buf) { headerEnd = idx; break }
        let n = chunk.withUnsafeBufferPointer { b -> Int in
            recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
        }
        if n <= 0 { die("no response headers") }
        buf += chunk[0..<n]
    }
    let headerData = Data(buf[0..<headerEnd])
    guard let headerStr = String(data: headerData, encoding: .utf8) else { die("bad headers") }
    var hlines = headerStr.components(separatedBy: "\r\n")
    let statusLine = hlines.removeFirst()
    let parts = statusLine.split(separator: " ")
    guard parts.count >= 2, let status = Int(parts[1]) else { die("bad status line") }
    var headers: [String: String] = [:]
    for line in hlines {
        guard let ci = line.firstIndex(of: ":") else { continue }
        let k = String(line[..<ci]).lowercased()
        var v = String(line[line.index(after: ci)...])
        if v.hasPrefix(" ") { v.removeFirst() }
        headers[k] = v
    }
    var body = Array(buf[(headerEnd + 4)...])
    if status == 200 {
        while true {
            let n = chunk.withUnsafeBufferPointer { b -> Int in
                recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
            }
            if n < 0 { die("recv failed") }
            if n == 0 { break }
            body += chunk[0..<n]
        }
    } else {
        let cl = Int(headers["content-length"] ?? "0") ?? 0
        while body.count < cl {
            let n = chunk.withUnsafeBufferPointer { b -> Int in
                recv(fd, UnsafeMutableRawPointer(mutating: UnsafeRawPointer(b.baseAddress!)), chunk.count, 0)
            }
            if n <= 0 { die("recv failed") }
            body += chunk[0..<n]
        }
        body = Array(body[0..<cl])
    }
    close(fd)
    return (status, headers, Data(body))
}

func dechunk(_ data: Data) -> Data {
    let b = [UInt8](data)
    var i = 0
    var out: [UInt8] = []
    while i < b.count {
        let start = i
        while i < b.count && b[i] != 13 && b[i] != 10 { i += 1 }
        var sizeStr = String(bytes: b[start..<i], encoding: .utf8) ?? ""
        if i < b.count && b[i] == 13 { i += 1 }
        if i < b.count && b[i] == 10 { i += 1 }
        if let semi = sizeStr.firstIndex(of: ";") { sizeStr = String(sizeStr[..<semi]) }
        guard let size = Int(sizeStr.trimmingCharacters(in: .whitespaces), radix: 16) else { die("bad chunk size") }
        if size == 0 { break }
        guard i + size <= b.count else { die("truncated chunk") }
        out += b[i..<(i + size)]
        i += size
        if i < b.count && b[i] == 13 { i += 1 }
        if i < b.count && b[i] == 10 { i += 1 }
    }
    return Data(out)
}

func parseSSE(_ data: Data) -> [(String, String)] {
    guard let s = String(data: data, encoding: .utf8) else { die("bad sse encoding") }
    var events: [(String, String)] = []
    var event = ""
    var datas: [String] = []
    func flush() {
        if !datas.isEmpty { events.append((event, datas.joined(separator: "\n"))) }
        event = ""
        datas = []
    }
    for rawLine in s.split(separator: "\n", omittingEmptySubsequences: false) {
        var line = String(rawLine)
        if line.hasSuffix("\r") { line.removeLast() }
        if line.isEmpty { flush(); continue }
        if line.hasPrefix(":") { continue }
        guard let ci = line.firstIndex(of: ":") else { continue }
        let field = String(line[..<ci])
        var value = String(line[line.index(after: ci)...])
        if value.hasPrefix(" ") { value.removeFirst() }
        if field == "event" { event = value }
        else if field == "data" { datas.append(value) }
    }
    flush()
    return events
}

// ---------- Output helpers ----------

func esc(_ s: String) -> String {
    var r = ""
    for c in s {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.append(c)
        }
    }
    return r
}

// ---------- Model of a reply ----------

struct Block {
    var type = ""
    var thinking = ""
    var signature = ""
    var text = ""
    var id = ""
    var name = ""
    var json = ""
}

struct Reply {
    var blocks: [Block]
    var stopReason: String
    var input: Int
    var output: Int
    var cacheRead: Int
}

enum ReplyOrError {
    case reply(Reply)
    case error(Int, String, String)
}

// ---------- Main ----------

let args = CommandLine.arguments
guard args.count >= 3 else { die("usage: main <data_dir> <base_url>") }
let dataDir = args[1]
let base = args[2]

var baseRest = base
if baseRest.hasPrefix("http://") { baseRest.removeFirst(7) }
var hostPort = baseRest
var basePath = ""
if let si = baseRest.firstIndex(of: "/") {
    hostPort = String(baseRest[..<si])
    basePath = String(baseRest[si...])
}
if basePath.hasSuffix("/") { basePath.removeLast() }
let endpointPath = basePath + "/v1/messages"
let hostHeader = hostPort
let host: String
let port: String
if let colonIdx = hostPort.firstIndex(of: ":") {
    host = String(hostPort[..<colonIdx])
    port = String(hostPort[hostPort.index(after: colonIdx)...])
} else {
    host = hostPort
    port = "80"
}

let reqJSONData = try! Data(contentsOf: URL(fileURLWithPath: dataDir + "/request.json"))
let reqJSON = (try! JSONSerialization.jsonObject(with: reqJSONData)) as! [String: Any]
let apiKey = reqJSON["api_key"] as! String
let model = reqJSON["model"] as! String
let maxTokens = reqJSON["max_tokens"] as! Int
let thinkingBudget = reqJSON["thinking_budget"] as! Int
let system = reqJSON["system"] as! String
let prompt = reqJSON["prompt"] as! String
let tools = reqJSON["tools"] as! [[String: Any]]

func makeBody(messages: [[String: Any]]) -> [String: Any] {
    return [
        "model": model,
        "max_tokens": maxTokens,
        "stream": true,
        "thinking": ["type": "enabled", "budget_tokens": thinkingBudget],
        "system": system,
        "tools": tools,
        "messages": messages,
    ]
}

func post(_ bodyDict: [String: Any]) -> ReplyOrError {
    let bodyData = try! JSONSerialization.data(withJSONObject: bodyDict)
    let fd = tcpConnect(host: host, port: port)
    let reqHead = "POST \(endpointPath) HTTP/1.1\r\n" +
        "Host: \(hostHeader)\r\n" +
        "Content-Length: \(bodyData.count)\r\n" +
        "x-api-key: \(apiKey)\r\n" +
        "anthropic-version: 2023-06-01\r\n" +
        "content-type: application/json\r\n\r\n"
    sendAll(fd, Data(reqHead.utf8) + bodyData)
    let resp = recvResponse(fd)
    if resp.status != 200 {
        let obj = (try? JSONSerialization.jsonObject(with: resp.body)) as? [String: Any] ?? [:]
        let err = obj["error"] as? [String: Any] ?? [:]
        return .error(resp.status, err["type"] as? String ?? "", err["message"] as? String ?? "")
    }
    let events = parseSSE(dechunk(resp.body))
    var blocksDict: [Int: Block] = [:]
    var stop = ""
    var inTok = 0, outTok = 0, cacheTok = 0
    for (name, dataStr) in events {
        guard let d = dataStr.data(using: .utf8),
              let obj = (try? JSONSerialization.jsonObject(with: d)) as? [String: Any] else { continue }
        switch name {
        case "message_start":
            if let msg = obj["message"] as? [String: Any], let usage = msg["usage"] as? [String: Any] {
                inTok += usage["input_tokens"] as? Int ?? 0
                cacheTok += usage["cache_read_input_tokens"] as? Int ?? 0
            }
        case "content_block_start":
            guard let idx = obj["index"] as? Int, let cb = obj["content_block"] as? [String: Any] else { break }
            var b = Block()
            b.type = cb["type"] as? String ?? ""
            if b.type == "tool_use" {
                b.id = cb["id"] as? String ?? ""
                b.name = cb["name"] as? String ?? ""
            }
            blocksDict[idx] = b
        case "content_block_delta":
            guard let idx = obj["index"] as? Int, let delta = obj["delta"] as? [String: Any] else { break }
            switch delta["type"] as? String {
            case "thinking_delta": blocksDict[idx]?.thinking += delta["thinking"] as? String ?? ""
            case "signature_delta": blocksDict[idx]?.signature += delta["signature"] as? String ?? ""
            case "text_delta": blocksDict[idx]?.text += delta["text"] as? String ?? ""
            case "input_json_delta": blocksDict[idx]?.json += delta["partial_json"] as? String ?? ""
            default: break
            }
        case "message_delta":
            if let d2 = obj["delta"] as? [String: Any], let sr = d2["stop_reason"] as? String { stop = sr }
            if let usage = obj["usage"] as? [String: Any] { outTok += usage["output_tokens"] as? Int ?? 0 }
        default:
            break
        }
    }
    let blocks = blocksDict.sorted { $0.key < $1.key }.map { $0.value }
    return .reply(Reply(blocks: blocks, stopReason: stop, input: inTok, output: outTok, cacheRead: cacheTok))
}

func runTool(name: String, json: String) -> (String, Bool) {
    guard let obj = (try? JSONSerialization.jsonObject(with: Data(json.utf8))) as? [String: Any] else {
        return ("unknown tool: \(name)", true)
    }
    func str(_ k: String) -> String { obj[k] as? String ?? "" }
    switch name {
    case "measure":
        let text = str("text")
        let unit = str("unit")
        switch unit {
        case "code_points": return (String(text.unicodeScalars.count), false)
        case "utf8_bytes": return (String(text.utf8.count), false)
        case "utf16_units": return (String(text.utf16.count), false)
        default: return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = str("text")
        var out = ""
        out.unicodeScalars.append(contentsOf: text.unicodeScalars.reversed())
        return (out, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

var lines: [String] = []

func fail(status: Int, type: String, message: String) -> Never {
    for l in lines { print(l) }
    print("ERROR \(status) \(type): \(message)")
    exit(0)
}

func appendBlockLines(_ reply: Reply) {
    for b in reply.blocks {
        switch b.type {
        case "thinking":
            lines.append("thinking " + esc(b.thinking))
            lines.append("signature " + esc(b.signature))
        case "text":
            lines.append("text " + esc(b.text))
        case "tool_use":
            lines.append("tool_use \(b.id) \(b.name) " + esc(b.json))
        default:
            break
        }
    }
    lines.append("stop_reason " + reply.stopReason)
}

// ----- Request 1 -----

let userMsg: [String: Any] = ["role": "user", "content": prompt]
let r1: ReplyOrError
r1 = post(makeBody(messages: [userMsg]))
guard case .reply(let reply1) = r1 else {
    if case .error(let s, let t, let m) = r1 { fail(status: s, type: t, message: m) }
    die("unreachable")
}

lines.append("request 1")
appendBlockLines(reply1)

var assistantContent: [[String: Any]] = []
var toolResults: [[String: Any]] = []

for b in reply1.blocks {
    switch b.type {
    case "thinking":
        assistantContent.append(["type": "thinking", "thinking": b.thinking, "signature": b.signature])
    case "text":
        assistantContent.append(["type": "text", "text": b.text])
    case "tool_use":
        let inputObj = (try? JSONSerialization.jsonObject(with: Data(b.json.utf8))) ?? [String: Any]()
        assistantContent.append(["type": "tool_use", "id": b.id, "name": b.name, "input": inputObj])
        let (result, isError) = runTool(name: b.name, json: b.json)
        var r: [String: Any] = ["type": "tool_result", "tool_use_id": b.id, "content": result]
        if isError { r["is_error"] = true }
        toolResults.append(r)
        lines.append((isError ? "error " : "result ") + b.id + " " + esc(result))
    default:
        break
    }
}

// ----- Request 2 -----

let messages2: [[String: Any]] = [
    userMsg,
    ["role": "assistant", "content": assistantContent],
    ["role": "user", "content": toolResults],
]

let r2 = post(makeBody(messages: messages2))
guard case .reply(let reply2) = r2 else {
    if case .error(let s, let t, let m) = r2 { fail(status: s, type: t, message: m) }
    die("unreachable")
}

lines.append("request 2")
appendBlockLines(reply2)

let totalIn = reply1.input + reply2.input
let totalOut = reply1.output + reply2.output
let totalCache = reply1.cacheRead + reply2.cacheRead
lines.append("usage input=\(totalIn) output=\(totalOut) cache_read=\(totalCache)")

for l in lines { print(l) }
exit(0)

use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone)]
enum Val {
    Null,
    Int(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(b: &[u8], p: &mut usize) -> u64 {
    let mut r: u64 = 0;
    for i in 0..9 {
        let byte = b[*p];
        *p += 1;
        if i == 8 {
            r = (r << 8) | byte as u64;
            break;
        }
        r = (r << 7) | (byte as u64 & 0x7f);
        if byte & 0x80 == 0 {
            break;
        }
    }
    r
}

fn read_signed(buf: &[u8]) -> i64 {
    let mut v: i64 = (buf[0] as i8) as i64;
    for &b in &buf[1..] {
        v = (v << 8) | (b as i64 & 0xFF);
    }
    v
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut c: u32 = 0xFFFFFFFF;
    for &b in data {
        c = table[((c ^ b as u32) & 0xFF) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFFFFFF
}

struct Db {
    data: Vec<u8>,
    page_size: usize,
    reserved: usize,
}

impl Db {
    fn usable(&self) -> usize {
        self.page_size - self.reserved
    }
    fn page(&self, n: usize) -> &[u8] {
        let s = (n - 1) * self.page_size;
        &self.data[s..s + self.page_size]
    }
    fn walk(&self, page_no: usize, out: &mut Vec<(i64, Vec<u8>)>) {
        let pg = self.page(page_no);
        let hdr = if page_no == 1 { 100 } else { 0 };
        let ptype = pg[hdr];
        let ncell = u16::from_be_bytes([pg[hdr + 3], pg[hdr + 4]]) as usize;
        let cp = hdr + if ptype == 5 { 12 } else { 8 };
        if ptype == 5 {
            for i in 0..ncell {
                let off = u16::from_be_bytes([pg[cp + 2 * i], pg[cp + 2 * i + 1]]) as usize;
                let child =
                    u32::from_be_bytes([pg[off], pg[off + 1], pg[off + 2], pg[off + 3]]) as usize;
                self.walk(child, out);
            }
            let right =
                u32::from_be_bytes([pg[hdr + 8], pg[hdr + 9], pg[hdr + 10], pg[hdr + 11]])
                    as usize;
            self.walk(right, out);
        } else if ptype == 13 {
            for i in 0..ncell {
                let off = u16::from_be_bytes([pg[cp + 2 * i], pg[cp + 2 * i + 1]]) as usize;
                let mut p = off;
                let plen = read_varint(pg, &mut p) as usize;
                let rowid = read_varint(pg, &mut p) as i64;
                let payload = self.read_payload(pg, p, plen);
                out.push((rowid, payload));
            }
        }
    }
    fn read_payload(&self, pg: &[u8], p: usize, plen: usize) -> Vec<u8> {
        let u = self.usable();
        let x = u - 35;
        if plen <= x {
            return pg[p..p + plen].to_vec();
        }
        let m = ((u - 12) * 32) / 255 - 23;
        let k = m + ((plen - m) % (u - 4));
        let local = if k <= x { k } else { m };
        let mut buf = pg[p..p + local].to_vec();
        let mut next =
            u32::from_be_bytes([pg[p + local], pg[p + local + 1], pg[p + local + 2], pg[p + local + 3]])
                as usize;
        let mut remaining = plen - local;
        while next != 0 && remaining > 0 {
            let op = self.page(next);
            let n = remaining.min(u - 4);
            buf.extend_from_slice(&op[4..4 + n]);
            remaining -= n;
            next = u32::from_be_bytes([op[0], op[1], op[2], op[3]]) as usize;
        }
        buf
    }
}

fn parse_record(payload: &[u8]) -> Vec<Val> {
    let mut p = 0usize;
    let hdr_len = read_varint(payload, &mut p) as usize;
    let mut types = Vec::new();
    while p < hdr_len {
        types.push(read_varint(payload, &mut p));
    }
    let mut vals = Vec::new();
    let mut off = hdr_len;
    for t in types {
        match t {
            0 => vals.push(Val::Null),
            1..=6 => {
                let size = [0usize, 1, 2, 3, 4, 6, 8][(t - 1) as usize];
                vals.push(Val::Int(read_signed(&payload[off..off + size])));
                off += size;
            }
            7 => {
                let mut a = [0u8; 8];
                a.copy_from_slice(&payload[off..off + 8]);
                vals.push(Val::Real(f64::from_be_bytes(a)));
                off += 8;
            }
            8 => vals.push(Val::Int(0)),
            9 => vals.push(Val::Int(1)),
            n if n % 2 == 0 => {
                let l = ((n - 12) / 2) as usize;
                vals.push(Val::Blob(payload[off..off + l].to_vec()));
                off += l;
            }
            n => {
                let l = ((n - 13) / 2) as usize;
                vals.push(Val::Text(payload[off..off + l].to_vec()));
                off += l;
            }
        }
    }
    vals
}

fn shl1(v: &mut Vec<u32>) {
    let mut carry = 0u32;
    for x in v.iter_mut() {
        let n = (*x << 1) | carry;
        carry = *x >> 31;
        *x = n;
    }
    if carry != 0 {
        v.push(1);
    }
}

fn bignum_to_dec(v: &Vec<u32>) -> String {
    let mut d = v.clone();
    let mut parts: Vec<u32> = Vec::new();
    while !d.is_empty() {
        let mut rem: u64 = 0;
        for x in d.iter_mut().rev() {
            let cur = (rem << 32) | (*x as u64);
            *x = (cur / 1_000_000_000) as u32;
            rem = cur % 1_000_000_000;
        }
        while d.last() == Some(&0) {
            d.pop();
        }
        parts.push(rem as u32);
    }
    if parts.is_empty() {
        return "0".to_string();
    }
    let mut s = String::new();
    for i in (0..parts.len()).rev() {
        if i == parts.len() - 1 {
            s.push_str(&parts[i].to_string());
        } else {
            s.push_str(&format!("{:09}", parts[i]));
        }
    }
    s
}

fn pow2_to_dec(m: u64, shift: usize) -> String {
    let mut v: Vec<u32> = vec![m as u32, (m >> 32) as u32];
    for _ in 0..shift {
        shl1(&mut v);
    }
    bignum_to_dec(&v)
}

fn fmt_real(v: f64) -> String {
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let bits = v.to_bits();
    let neg = bits >> 63 == 1;
    let exp = ((bits >> 52) & 0x7ff) as i64;
    let frac = bits & ((1u64 << 52) - 1);
    let (m, e) = if exp == 0 { (frac, -1074i64) } else { (frac | (1u64 << 52), exp - 1075) };
    let mut s = String::new();
    if neg {
        s.push('-');
    }
    if e >= 0 {
        s.push_str(&pow2_to_dec(m, e as usize));
        s.push_str(".0");
    } else {
        let k = (-e) as u32;
        let ip = if k >= 53 { 0u64 } else { m >> k };
        s.push_str(&ip.to_string());
        s.push('.');
        let mut rem: u128 = if k >= 53 { m as u128 } else { (m & ((1u64 << k) - 1)) as u128 };
        let mut digits = String::new();
        for _ in 0..8 {
            if rem == 0 {
                break;
            }
            let t = rem * 10;
            let d = if k >= 128 { 0u32 } else { (t >> k) as u32 };
            rem = if k >= 128 { t } else { t & ((1u128 << k) - 1) };
            digits.push((b'0' + d as u8) as char);
        }
        while digits.ends_with('0') {
            digits.pop();
        }
        if digits.is_empty() {
            digits.push('0');
        }
        s.push_str(&digits);
    }
    s
}

fn quote(t: &[u8]) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(t.len() + 2);
    out.push(b'"');
    for &b in t {
        match b {
            b'\\' => out.extend_from_slice(b"\\\\"),
            b'"' => out.extend_from_slice(b"\\\""),
            b'\n' => out.extend_from_slice(b"\\n"),
            b'\r' => out.extend_from_slice(b"\\r"),
            b'\t' => out.extend_from_slice(b"\\t"),
            0x00..=0x1F | 0x7F => {
                out.extend_from_slice(format!("\\x{:02X}", b).as_bytes());
            }
            _ => out.push(b),
        }
    }
    out.push(b'"');
    String::from_utf8_lossy(&out).into_owned()
}

fn fmt_value(v: &Val, alias: bool, rowid: i64) -> String {
    match v {
        Val::Null => {
            if alias {
                rowid.to_string()
            } else {
                "NULL".to_string()
            }
        }
        Val::Int(i) => i.to_string(),
        Val::Real(r) => fmt_real(*r),
        Val::Text(t) => {
            if t.len() <= 100 {
                quote(t)
            } else {
                format!("<TEXT len={} crc32={:08x}>", t.len(), crc32(t))
            }
        }
        Val::Blob(b) => {
            if b.len() <= 100 {
                let mut s = String::from("X'");
                for &byte in b {
                    s.push_str(&format!("{:02X}", byte));
                }
                s.push('\'');
                s
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn parse_name(t: &str) -> (String, &str) {
    let b = t.as_bytes();
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_whitespace() {
        i += 1;
    }
    if i < b.len() && b[i] == b'"' {
        let mut j = i + 1;
        while j < b.len() && b[j] != b'"' {
            j += 1;
        }
        (t[i + 1..j].to_string(), &t[j + 1..])
    } else {
        let mut j = i;
        while j < b.len()
            && !matches!(b[j], b' ' | b'\t' | b'\r' | b'\n' | b',' | b'(' | b')')
        {
            j += 1;
        }
        (t[i..j].to_string(), &t[j..])
    }
}

const CONSTRAINT_KW: &[&str] = &[
    "constraint", "primary", "not", "null", "unique", "check", "default",
    "collate", "references", "generated", "as",
];

fn parse_def(def: &str) -> (String, bool) {
    let (name, rest) = parse_name(def);
    // collect words, skipping parenthesized groups
    let mut words: Vec<String> = Vec::new();
    let mut chars = rest.chars().peekable();
    while let Some(&c) = chars.peek() {
        if c.is_ascii_whitespace() {
            chars.next();
        } else if c == '(' {
            let mut depth = 0;
            for ch in chars.by_ref() {
                if ch == '(' {
                    depth += 1;
                } else if ch == ')' {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
            }
        } else if c.is_ascii_alphanumeric() || c == '_' {
            let mut w = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_ascii_alphanumeric() || ch == '_' {
                    w.push(ch);
                    chars.next();
                } else {
                    break;
                }
            }
            words.push(w.to_ascii_lowercase());
        } else {
            chars.next();
        }
    }
    let mut type_tokens: Vec<&String> = Vec::new();
    for w in &words {
        if CONSTRAINT_KW.contains(&w.as_str()) {
            break;
        }
        type_tokens.push(w);
    }
    let has_pk = words.windows(2).any(|w| w[0] == "primary" && w[1] == "key");
    let alias = type_tokens.len() == 1 && type_tokens[0] == "integer" && has_pk;
    (name, alias)
}

fn parse_columns(sql: &[u8]) -> (Vec<String>, Vec<bool>) {
    let s = String::from_utf8_lossy(sql);
    let bytes = s.as_bytes();
    let start = bytes.iter().position(|&b| b == b'(').unwrap();
    let mut defs: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut depth = 1usize;
    for c in s[start + 1..].chars() {
        match c {
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
                cur.push(c);
            }
            ',' if depth == 1 => {
                defs.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        defs.push(cur);
    }
    let mut names = Vec::new();
    let mut alias = Vec::new();
    for d in &defs {
        let (n, a) = parse_def(d);
        names.push(n);
        alias.push(a);
    }
    (names, alias)
}

