use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone)]
enum Val {
    Null,
    Int(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(b: &[u8], p: &mut usize) -> u64 {
    let mut r: u64 = 0;
    for i in 0..9 {
        let byte = b[*p];
        *p += 1;
        if i == 8 {
            r = (r << 8) | byte as u64;
            break;
        }
        r = (r << 7) | (byte as u64 & 0x7f);
        if byte & 0x80 == 0 {
            break;
        }
    }
    r
}

fn read_signed(buf: &[u8]) -> i64 {
    let mut v: i64 = (buf[0] as i8) as i64;
    for &b in &buf[1..] {
        v = (v << 8) | (b as i64 & 0xFF);
    }
    v
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut c: u32 = 0xFFFFFFFF;
    for &b in data {
        c = table[((c ^ b as u32) & 0xFF) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFFFFFF
}

struct Db {
    data: Vec<u8>,
    page_size: usize,
    reserved: usize,
}

impl Db {
    fn usable(&self) -> usize {
        self.page_size - self.reserved
    }
    fn page(&self, n: usize) -> &[u8] {
        let s = (n - 1) * self.page_size;
        &self.data[s..s + self.page_size]
    }
    fn walk(&self, page_no: usize, out: &mut Vec<(i64, Vec<u8>)>) {
        let pg = self.page(page_no);
        let hdr = if page_no == 1 { 100 } else { 0 };
        let ptype = pg[hdr];
        let ncell = u16::from_be_bytes([pg[hdr + 3], pg[hdr + 4]]) as usize;
        let cp = hdr + if ptype == 5 { 12 } else { 8 };
        if ptype == 5 {
            for i in 0..ncell {
                let off = u16::from_be_bytes([pg[cp + 2 * i], pg[cp + 2 * i + 1]]) as usize;
                let child =
                    u32::from_be_bytes([pg[off], pg[off + 1], pg[off + 2], pg[off + 3]]) as usize;
                self.walk(child, out);
            }
            let right =
                u32::from_be_bytes([pg[hdr + 8], pg[hdr + 9], pg[hdr + 10], pg[hdr + 11]])
                    as usize;
            self.walk(right, out);
        } else if ptype == 13 {
            for i in 0..ncell {
                let off = u16::from_be_bytes([pg[cp + 2 * i], pg[cp + 2 * i + 1]]) as usize;
                let mut p = off;
                let plen = read_varint(pg, &mut p) as usize;
                let rowid = read_varint(pg, &mut p) as i64;
                let payload = self.read_payload(pg, p, plen);
                out.push((rowid, payload));
            }
        }
    }
    fn read_payload(&self, pg: &[u8], p: usize, plen: usize) -> Vec<u8> {
        let u = self.usable();
        let x = u - 35;
        if plen <= x {
            return pg[p..p + plen].to_vec();
        }
        let m = ((u - 12) * 32) / 255 - 23;
        let k = m + ((plen - m) % (u - 4));
        let local = if k <= x { k } else { m };
        let mut buf = pg[p..p + local].to_vec();
        let mut next =
            u32::from_be_bytes([pg[p + local], pg[p + local + 1], pg[p + local + 2], pg[p + local + 3]])
                as usize;
        let mut remaining = plen - local;
        while next != 0 && remaining > 0 {
            let op = self.page(next);
            let n = remaining.min(u - 4);
            buf.extend_from_slice(&op[4..4 + n]);
            remaining -= n;
            next = u32::from_be_bytes([op[0], op[1], op[2], op[3]]) as usize;
        }
        buf
    }
}

fn parse_record(payload: &[u8]) -> Vec<Val> {
    let mut p = 0usize;
    let hdr_len = read_varint(payload, &mut p) as usize;
    let mut types = Vec::new();
    while p < hdr_len {
        types.push(read_varint(payload, &mut p));
    }
    let mut vals = Vec::new();
    let mut off = hdr_len;
    for t in types {
        match t {
            0 => vals.push(Val::Null),
            1..=6 => {
                let size = [1usize, 2, 3, 4, 6, 8][(t - 1) as usize];
                vals.push(Val::Int(read_signed(&payload[off..off + size])));
                off += size;
            }
            7 => {
                let mut a = [0u8; 8];
                a.copy_from_slice(&payload[off..off + 8]);
                vals.push(Val::Real(f64::from_be_bytes(a)));
                off += 8;
            }
            8 => vals.push(Val::Int(0)),
            9 => vals.push(Val::Int(1)),
            n if n % 2 == 0 => {
                let l = ((n - 12) / 2) as usize;
                vals.push(Val::Blob(payload[off..off + l].to_vec()));
                off += l;
            }
            n => {
                let l = ((n - 13) / 2) as usize;
                vals.push(Val::Text(payload[off..off + l].to_vec()));
                off += l;
            }
        }
    }
    vals
}

fn shl1(v: &mut Vec<u32>) {
    let mut carry = 0u32;
    for x in v.iter_mut() {
        let n = (*x << 1) | carry;
        carry = *x >> 31;
        *x = n;
    }
    if carry != 0 {
        v.push(1);
    }
}

fn bignum_to_dec(v: &Vec<u32>) -> String {
    let mut d = v.clone();
    let mut parts: Vec<u32> = Vec::new();
    while !d.is_empty() {
        let mut rem: u64 = 0;
        for x in d.iter_mut().rev() {
            let cur = (rem << 32) | (*x as u64);
            *x = (cur / 1_000_000_000) as u32;
            rem = cur % 1_000_000_000;
        }
        while d.last() == Some(&0) {
            d.pop();
        }
        parts.push(rem as u32);
    }
    if parts.is_empty() {
        return "0".to_string();
    }
    let mut s = String::new();
    for i in (0..parts.len()).rev() {
        if i == parts.len() - 1 {
            s.push_str(&parts[i].to_string());
        } else {
            s.push_str(&format!("{:09}", parts[i]));
        }
    }
    s
}

fn pow2_to_dec(m: u64, shift: usize) -> String {
    let mut v: Vec<u32> = vec![m as u32, (m >> 32) as u32];
    for _ in 0..shift {
        shl1(&mut v);
    }
    bignum_to_dec(&v)
}

fn fmt_real(v: f64) -> String {
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let bits = v.to_bits();
    let neg = bits >> 63 == 1;
    let exp = ((bits >> 52) & 0x7ff) as i64;
    let frac = bits & ((1u64 << 52) - 1);
    let (m, e) = if exp == 0 { (frac, -1074i64) } else { (frac | (1u64 << 52), exp - 1075) };
    let mut s = String::new();
    if neg {
        s.push('-');
    }
    if e >= 0 {
        s.push_str(&pow2_to_dec(m, e as usize));
        s.push_str(".0");
    } else {
        let k = (-e) as u32;
        let ip = if k >= 53 { 0u64 } else { m >> k };
        s.push_str(&ip.to_string());
        s.push('.');
        let mut rem: u128 = if k >= 53 { m as u128 } else { (m & ((1u64 << k) - 1)) as u128 };
        let mut digits = String::new();
        for _ in 0..8 {
            if rem == 0 {
                break;
            }
            let t = rem * 10;
            let d = if k >= 128 { 0u32 } else { (t >> k) as u32 };
            rem = if k >= 128 { t } else { t & ((1u128 << k) - 1) };
            digits.push((b'0' + d as u8) as char);
        }
        while digits.ends_with('0') {
            digits.pop();
        }
        if digits.is_empty() {
            digits.push('0');
        }
        s.push_str(&digits);
    }
    s
}

fn quote(t: &[u8]) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(t.len() + 2);
    out.push(b'"');
    for &b in t {
        match b {
            b'\\' => out.extend_from_slice(b"\\\\"),
            b'"' => out.extend_from_slice(b"\\\""),
            b'\n' => out.extend_from_slice(b"\\n"),
            b'\r' => out.extend_from_slice(b"\\r"),
            b'\t' => out.extend_from_slice(b"\\t"),
            0x00..=0x1F | 0x7F => {
                out.extend_from_slice(format!("\\x{:02X}", b).as_bytes());
            }
            _ => out.push(b),
        }
    }
    out.push(b'"');
    String::from_utf8_lossy(&out).into_owned()
}

fn fmt_value(v: &Val, alias: bool, rowid: i64) -> String {
    match v {
        Val::Null => {
            if alias {
                rowid.to_string()
            } else {
                "NULL".to_string()
            }
        }
        Val::Int(i) => i.to_string(),
        Val::Real(r) => fmt_real(*r),
        Val::Text(t) => {
            if t.len() <= 100 {
                quote(t)
            } else {
                format!("<TEXT len={} crc32={:08x}>", t.len(), crc32(t))
            }
        }
        Val::Blob(b) => {
            if b.len() <= 100 {
                let mut s = String::from("X'");
                for &byte in b {
                    s.push_str(&format!("{:02X}", byte));
                }
                s.push('\'');
                s
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn parse_name(t: &str) -> (String, &str) {
    let b = t.as_bytes();
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_whitespace() {
        i += 1;
    }
    if i < b.len() && b[i] == b'"' {
        let mut j = i + 1;
        while j < b.len() && b[j] != b'"' {
            j += 1;
        }
        (t[i + 1..j].to_string(), &t[j + 1..])
    } else {
        let mut j = i;
        while j < b.len()
            && !matches!(b[j], b' ' | b'\t' | b'\r' | b'\n' | b',' | b'(' | b')' | b'"')
        {
            j += 1;
        }
        (t[i..j].to_string(), &t[j..])
    }
}

fn read_token(s: &str, i: usize) -> (String, usize) {
    let b = s.as_bytes();
    if b[i] == b'"' {
        let mut j = i + 1;
        while j < b.len() && b[j] != b'"' {
            j += 1;
        }
        (s[i + 1..j].to_string(), j + 1)
    } else {
        let mut j = i;
        while j < b.len()
            && !b[j].is_ascii_whitespace()
            && !matches!(b[j], b'(' | b')' | b',' | b'"')
        {
            j += 1;
        }
        (s[i..j].to_string(), j)
    }
}

const CONSTRAINT_KW: &[&str] = &[
    "constraint", "primary", "not", "null", "unique", "check", "default",
    "collate", "references", "generated", "as",
];

fn parse_def(def: &str) -> (String, bool) {
    let (name, rest) = parse_name(def);
    // collect words, skipping quoted strings and parenthesized groups
    let mut words: Vec<String> = Vec::new();
    let mut chars = rest.chars().peekable();
    let mut inq = false;
    while let Some(&c) = chars.peek() {
        if inq {
            if c == '"' {
                inq = false;
            }
            chars.next();
        } else if c == '"' {
            inq = true;
            chars.next();
        } else if c.is_ascii_whitespace() {
            chars.next();
        } else if c == '(' {
            let mut depth = 0;
            for ch in chars.by_ref() {
                if ch == '(' {
                    depth += 1;
                } else if ch == ')' {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
            }
        } else if c.is_ascii_alphanumeric() || c == '_' {
            let mut w = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_ascii_alphanumeric() || ch == '_' {
                    w.push(ch);
                    chars.next();
                } else {
                    break;
                }
            }
            words.push(w.to_ascii_lowercase());
        } else {
            chars.next();
        }
    }
    let mut type_tokens: Vec<&String> = Vec::new();
    for w in &words {
        if CONSTRAINT_KW.contains(&w.as_str()) {
            break;
        }
        type_tokens.push(w);
    }
    let has_pk = words.windows(2).any(|w| w[0] == "primary" && w[1] == "key");
    let alias = type_tokens.len() == 1 && type_tokens[0] == "integer" && has_pk;
    (name, alias)
}

fn parse_columns(sql: &[u8]) -> (Vec<String>, Vec<bool>) {
    let s = String::from_utf8_lossy(sql);
    let bytes = s.as_bytes();
    // skip "CREATE [TEMP|TEMPORARY] TABLE <name>" to the opening '('
    let mut i = 0usize;
    let mut name = String::new();
    loop {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || bytes[i] == b'(' {
            break;
        }
        let (tok, ni) = read_token(&s, i);
        let lower = tok.to_ascii_lowercase();
        if lower != "create" && lower != "temp" && lower != "temporary" && lower != "table" {
            name = tok;
        }
        i = ni;
    }
    let _ = name;
    let mut defs: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut depth = 1usize;
    let mut inq = false;
    for c in s[i + 1..].chars() {
        if inq {
            cur.push(c);
            if c == '"' {
                inq = false;
            }
            continue;
        }
        match c {
            '"' => {
                inq = true;
                cur.push(c);
            }
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
                cur.push(c);
            }
            ',' if depth == 1 => {
                defs.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        defs.push(cur);
    }
    let mut names = Vec::new();
    let mut alias = Vec::new();
    for d in &defs {
        let (n, a) = parse_def(d);
        names.push(n);
        alias.push(a);
    }
    (names, alias)
}

