            } else {
                res.put("sku", row[0]);
                res.put("name", row[1]);
                res.put("price_cents", Long.parseLong(row[2]));
                res.put("currency", row[3]);
                res.put("stock", Long.parseLong(row[4]));
            }
        } else if ("convert_currency".equals(name)) {
            long amount = num(args.get("amount_cents"));
            String from = sval(args.get("from"));
            String to = sval(args.get("to"));
            long rf = rates.get(from);
            long rt = rates.get(to);
            long conv = (2 * amount * rt + rf) / (2 * rf);
            res.put("amount_cents", conv);
            res.put("currency", to);
        } else {
            res.put("error", "unknown tool: " + name);
        }
        return ser(res);
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String baseUrl = args[1];

        // task.json
        String taskJson = Files.readString(Path.of(dir, "task.json"), UTF8);
        if (taskJson.startsWith("\uFEFF")) taskJson = taskJson.substring(1);
        @SuppressWarnings("unchecked")
        Map<String, Object> task = (Map<String, Object>) parse(taskJson);
        String apiKey = sval(task.get("api_key"));
        Object model = task.get("model");
        Object system = task.get("system");
        Object user = task.get("user");
        String toolsRaw = extractArray(taskJson, "tools");

        // inventory.csv
        List<String[]> records = parseCsv(Files.readString(Path.of(dir, "inventory.csv"), UTF8));
        Map<String, String[]> inv = new LinkedHashMap<>();
        for (int r = 1; r < records.size(); r++) {
            String[] row = records.get(r);
            if (row.length >= 5) inv.put(row[0], row);
        }

        // rates.json
        String ratesJson = Files.readString(Path.of(dir, "rates.json"), UTF8);
        if (ratesJson.startsWith("\uFEFF")) ratesJson = ratesJson.substring(1);
        @SuppressWarnings("unchecked")
        Map<String, Object> ratesRoot = (Map<String, Object>) parse(ratesJson);
        @SuppressWarnings("unchecked")
        Map<String, Object> ratesObj = (Map<String, Object>) ratesRoot.get("rates");
        Map<String, Long> rates = new LinkedHashMap<>();
        for (Map.Entry<String, Object> e : ratesObj.entrySet()) rates.put(e.getKey(), num(e.getValue()));

        // conversation
        List<Object> messages = new ArrayList<>();
        LinkedHashMap<String, Object> sys = new LinkedHashMap<>();
        sys.put("role", new JsonStr("system", "\"system\""));
        sys.put("content", system);
        messages.add(sys);
        LinkedHashMap<String, Object> usr = new LinkedHashMap<>();
        usr.put("role", new JsonStr("user", "\"user\""));
        usr.put("content", user);
        messages.add(usr);

        HttpClient client = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_1_1)
                .build();

        long promptTokens = 0, completionTokens = 0, totalTokens = 0;
        int requests = 0;

        while (true) {
            String body = "{\"model\":" + ser(model)
                    + ",\"messages\":" + ser((Object) messages)
                    + ",\"tools\":" + toolsRaw
                    + ",\"tool_choice\":\"auto\"}";

            HttpRequest req = HttpRequest.newBuilder(URI.create(baseUrl + "/chat/completions"))
                    .header("Authorization", "Bearer " + apiKey)
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(body, UTF8))
                    .build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString(UTF8));
            requests++;

            if (resp.statusCode() != 200) {
                String eb = resp.body();
                String msg = eb;
                try {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> err = (Map<String, Object>) ((Map<String, Object>) parse(eb)).get("error");
                    if (err != null && err.get("message") != null) msg = sval(err.get("message"));
                } catch (Exception ignored) {}
                System.out.println("ERROR " + resp.statusCode() + " " + msg);
                return;
            }

            @SuppressWarnings("unchecked")
            Map<String, Object> root = (Map<String, Object>) parse(resp.body());

            Object usageO = root.get("usage");
            if (usageO instanceof Map<?, ?>) {
                @SuppressWarnings("unchecked")
                Map<String, Object> usage = (Map<String, Object>) usageO;
                if (usage.get("prompt_tokens") != null) promptTokens += num(usage.get("prompt_tokens"));
                if (usage.get("completion_tokens") != null) completionTokens += num(usage.get("completion_tokens"));
                if (usage.get("total_tokens") != null) totalTokens += num(usage.get("total_tokens"));
            }

            @SuppressWarnings("unchecked")
            List<Object> choices = (List<Object>) root.get("choices");
            @SuppressWarnings("unchecked")
            Map<String, Object> choice0 = (Map<String, Object>) choices.get(0);
            String finish = sval(choice0.get("finish_reason"));
            @SuppressWarnings("unchecked")
            Map<String, Object> message = (Map<String, Object>) choice0.get("message");

            if ("tool_calls".equals(finish)) {
                Object content = message.get("content");
                if (content instanceof JsonStr j) System.out.println("SAY " + j.v());
                else if (content instanceof String cs) System.out.println("SAY " + cs);

                @SuppressWarnings("unchecked")
                List<Object> calls = (List<Object>) message.get("tool_calls");
                List<String> callLines = new ArrayList<>();
                List<String> resultLines = new ArrayList<>();
                List<Object> toolMessages = new ArrayList<>();

                for (Object co : calls) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> cm = (Map<String, Object>) co;
                    String id = sval(cm.get("id"));
                    @SuppressWarnings("unchecked")
                    Map<String, Object> fn = (Map<String, Object>) cm.get("function");
                    String name = sval(fn.get("name"));
                    String argsStr = sval(fn.get("arguments"));
                    @SuppressWarnings("unchecked")
                    Map<String, Object> parsedArgs = (Map<String, Object>) parse(argsStr);
                    String result = execTool(name, parsedArgs, inv, rates);

                    callLines.add("CALL " + id + " " + name);
                    resultLines.add("RESULT " + id + " " + result);

                    LinkedHashMap<String, Object> tm = new LinkedHashMap<>();
                    tm.put("role", new JsonStr("tool", "\"tool\""));
                    tm.put("tool_call_id", cm.get("id"));
                    tm.put("content", result);
                    toolMessages.add(tm);
                }

                for (String l : callLines) System.out.println(l);
                for (String l : resultLines) System.out.println(l);

                messages.add(message);
                messages.addAll(toolMessages);
            } else {
                System.out.println("FINAL " + sval(message.get("content")));
                break;
            }
        }

        System.out.println("USAGE prompt=" + promptTokens + " completion=" + completionTokens
                + " total=" + totalTokens + " requests=" + requests);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;

struct SS {
    s: String,
    raw: String,
}

enum J {
    Null,
    Bool(bool),
    Num(String),
    Str(SS),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn new(s: &'a str) -> Self {
        P { b: s.as_bytes(), i: 0 }
    }
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn hex4(&mut self) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..4 {
            v = v * 16 + (self.b[self.i] as char).to_digit(16).unwrap();
            self.i += 1;
        }
        v
    }
    fn string(&mut self) -> SS {
        let start = self.i;
        self.i += 1;
        let mut s = String::new();
        loop {
            let c = self.b[self.i];
            if c == b'"' {
                self.i += 1;
                break;
            }
            if c == b'\\' {
                self.i += 1;
                let e = self.b[self.i];
                match e {
                    b'"' => { s.push('"'); self.i += 1; }
                    b'\\' => { s.push('\\'); self.i += 1; }
                    b'/' => { s.push('/'); self.i += 1; }
                    b'b' => { s.push('\u{0008}'); self.i += 1; }
                    b'f' => { s.push('\u{000C}'); self.i += 1; }
                    b'n' => { s.push('\n'); self.i += 1; }
                    b'r' => { s.push('\r'); self.i += 1; }
                    b't' => { s.push('\t'); self.i += 1; }
                    b'u' => {
                        self.i += 1;
                        let c1 = self.hex4();
                        if (0xD800..0xDC00).contains(&c1)
                            && self.i + 1 < self.b.len()
                            && self.b[self.i] == b'\\'
                            && self.b[self.i + 1] == b'u'
                        {
                            let save = self.i;
                            self.i += 2;
                            let c2 = self.hex4();
                            if (0xDC00..0xE000).contains(&c2) {
                                let cp = 0x10000u32 + ((c1 - 0xD800) << 10) + (c2 - 0xDC00);
                                s.push(char::from_u32(cp).unwrap());
                            } else {
                                self.i = save;
                                s.push(char::from_u32(c1).unwrap());
                            }
                        } else {
                            s.push(char::from_u32(c1).unwrap());
                        }
                    }
                    _ => { self.i += 1; }
                }
            } else {
                let st = self.i;
                while self.b[self.i] != b'"' && self.b[self.i] != b'\\' {
                    self.i += 1;
                }
                s.push_str(std::str::from_utf8(&self.b[st..self.i]).unwrap());
            }
        }
        SS { s, raw: String::from_utf8_lossy(&self.b[start..self.i]).into_owned() }
    }
    fn val(&mut self) -> J {
        self.ws();
        match self.b[self.i] {
            b'{' => {
                self.i += 1;
                let mut m: Vec<(String, J)> = Vec::new();
                self.ws();
                if self.b[self.i] == b'}' {
                    self.i += 1;
                    return J::Obj(m);
                }
                loop {
                    self.ws();
                    let k = self.string();
                    self.ws();
                    self.i += 1; // ':'
                    let v = self.val();
                    m.push((k.s, v));
                    self.ws();
                    if self.b[self.i] == b',' {
                        self.i += 1;
                    } else {
                        self.i += 1;
                        break;
                    }
                }
                J::Obj(m)
            }
            b'[' => {
                self.i += 1;
                let mut m: Vec<J> = Vec::new();
                self.ws();
                if self.b[self.i] == b']' {
                    self.i += 1;
                    return J::Arr(m);
                }
                loop {
                    m.push(self.val());
                    self.ws();
                    if self.b[self.i] == b',' {
                        self.i += 1;
                    } else {
                        self.i += 1;
                        break;
                    }
                }
                J::Arr(m)
            }
            b'"' => J::Str(self.string()),
            b't' => { self.i += 4; J::Bool(true) }
            b'f' => { self.i += 5; J::Bool(false) }
            b'n' => { self.i += 4; J::Null }
            _ => {
                let st = self.i;
                while self.i < self.b.len() && !matches!(self.b[self.i], b',' | b']' | b'}' | b' ' | b'\t' | b'\n' | b'\r') {
                    self.i += 1;
                }
                J::Num(String::from_utf8_lossy(&self.b[st..self.i]).into_owned())
            }
        }
    }
}

fn pj(s: &str) -> J {
    let mut p = P::new(s);
    p.val()
}

fn jget<'a>(o: &'a J, k: &str) -> Option<&'a J> {
    match o {
        J::Obj(m) => m.iter().find(|(kk, _)| kk == k).map(|(_, v)| v),
        _ => None,
    }
}
fn jstr(j: &J) -> &str {
    match j {
        J::Str(ss) => &ss.s,
        _ => "",
    }
}
fn jraw(j: &J) -> &str {
    match j {
        J::Str(ss) => &ss.raw,
        _ => "null",
    }
}
fn jnum_u(j: &J) -> u64 {
    match j {
        J::Num(s) => s.parse().unwrap_or(0),
        _ => 0,
    }
}
fn jnum_i(j: &J) -> i128 {
    match j {
        J::Num(s) => s.parse().unwrap_or(0),
        _ => 0,
    }
}

fn esc(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\u{0008}' => o.push_str("\\b"),
            '\u{000C}' => o.push_str("\\f"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o
}

fn q(s: &str) -> String {
    format!("\"{}\"", esc(s))
}

fn raw_array(text: &str, key: &str) -> String {
    let pat = format!("\"{}\"", key);
    let pos = text.find(&pat).unwrap();
    let rel = text[pos..].find('[').unwrap();
    let start = pos + rel;
    let b = text.as_bytes();
    let mut i = start;
    let mut depth = 0;
    let mut in_str = false;
    let mut escp = false;
    while i < b.len() {
        let c = b[i];
        if in_str {
            if escp {
                escp = false;
            } else if c == b'\\' {
                escp = true;
            } else if c == b'"' {
                in_str = false;
            }
        } else {
            match c {
                b'"' => in_str = true,
                b'[' => depth += 1,
                b']' => {
                    depth -= 1;
                    if depth == 0 {
                        return text[start..=i].to_string();
                    }
                }
                _ => {}
            }
        }
        i += 1;
    }
    unreachable!()
}

fn parse_csv(data: &str) -> Vec<Vec<String>> {
    let b: Vec<char> = data.chars().collect();
    let n = b.len();
    let mut i = 0usize;
    let mut recs: Vec<Vec<String>> = Vec::new();
    let mut fields: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut have = false;
    while i < n {
        let c = b[i];
        if c == '"' {
            i += 1;
            loop {
                if i >= n {
                    break;
                }
                if b[i] == '"' {
                    if i + 1 < n && b[i + 1] == '"' {
                        cur.push('"');
                        i += 2;
                    } else {
                        i += 1;
                        break;
                    }
                } else {
                    cur.push(b[i]);
                    i += 1;
                }
            }
            have = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
            have = false;
            i += 1;
        } else if c == '\r' {
            if i + 1 < n && b[i + 1] == '\n' {
                i += 2;
            } else {
                i += 1;
            }
            fields.push(std::mem::take(&mut cur));
            recs.push(std::mem::take(&mut fields));
            have = false;
        } else if c == '\n' {
            i += 1;
            fields.push(std::mem::take(&mut cur));
            recs.push(std::mem::take(&mut fields));
            have = false;
        } else {
            cur.push(c);
            have = true;
            i += 1;
        }
    }
    if !fields.is_empty() || have || !cur.is_empty() {
        fields.push(cur);
        recs.push(fields);
    }
    recs
}

fn post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> (u16, String) {
    let mut s = TcpStream::connect((host, port)).expect("connect failed");
    let req = format!(
        "POST {}/chat/completions HTTP/1.1\r\nHost: {}:{}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        path, host, port, api_key, body.len(), body
    );
    s.write_all(req.as_bytes()).unwrap();
    let mut buf = Vec::new();
    s.read_to_end(&mut buf).unwrap();
    let text = String::from_utf8_lossy(&buf).into_owned();
    let line_end = text.find("\r\n").unwrap_or(text.len());
    let status_line = &text[..line_end];
    let status: u16 = status_line
        .split_whitespace()
        .nth(1)
        .unwrap_or("500")
        .parse()
        .unwrap_or(500);
    let body_start = text.find("\r\n\r\n").map(|p| p + 4).unwrap_or(line_end + 2);
    (status, text[body_start.min(text.len())..].to_string())
}

fn exec_tool(
    name: &str,
    args: &J,
    inv: &HashMap<String, (String, u64, String, u64)>,
    rates: &HashMap<String, u64>,
) -> String {
    match name {
        "inventory_lookup" => {
            let sku = jstr(jget(args, "sku").unwrap());
            if let Some(row) = inv.get(sku) {
                format!(
                    "{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                    q(sku), q(&row.0), row.1, q(&row.2), row.3
                )
            } else {
                format!("{{\"error\":\"unknown sku: {}\"}}", esc(sku))
            }
        }
        "convert_currency" => {
            let amount = jnum_i(jget(args, "amount_cents").unwrap());
            let from = jstr(jget(args, "from").unwrap());
            let to = jstr(jget(args, "to").unwrap());
            let rf = *rates.get(from).unwrap_or(&1);
            let rt = *rates.get(to).unwrap_or(&1);
            let conv = (2 * amount * rt as i128 + rf as i128) / (2 * rf as i128);
            format!("{{\"amount_cents\":{},\"currency\":{}}}", conv, q(to))
        }
        _ => format!("{{\"error\":\"unknown tool: {}\"}}", esc(name)),
    }
}

fn main() {
    let a: Vec<String> = env::args().collect();
    let dir = &a[1];
    let base = &a[2];

    let task = fs::read_to_string(format!("{}/task.json", dir)).unwrap();
    let tj = pj(&task);
    let api_key = jstr(jget(&tj, "api_key").unwrap()).to_string();
    let model_raw = jraw(jget(&tj, "model").unwrap()).to_string();
    let sys_raw = jraw(jget(&tj, "system").unwrap()).to_string();
    let user_raw = jraw(jget(&tj, "user").unwrap()).to_string();
    let tools_raw = raw_array(&task, "tools");

    let rates_s = fs::read_to_string(format!("{}/rates.json", dir)).unwrap();
    let rj = pj(&rates_s);
    let mut rates: HashMap<String, u64> = HashMap::new();
    if let Some(J::Obj(m)) = jget(&rj, "rates") {
        for (k, v) in m {
            rates.insert(k.clone(), jnum_u(v));
        }
    }

    let mut inv_s = fs::read_to_string(format!("{}/inventory.csv", dir)).unwrap();
    if inv_s.starts_with('\u{feff}') {
        inv_s.remove(0);
    }
    let recs = parse_csv(&inv_s);
    let mut inv: HashMap<String, (String, u64, String, u64)> = HashMap::new();
    for r in recs.iter().skip(1) {
        if r.len() >= 5 {
            inv.insert(
                r[0].clone(),
                (
                    r[1].clone(),
                    r[2].parse::<u64>().unwrap_or(0),
                    r[3].clone(),
                    r[4].parse::<u64>().unwrap_or(0),
                ),
            );
        }
    }

    let rest = &base["http://".len()..];
    let (hostport, path) = match rest.find('/') {
        Some(p) => (&rest[..p], &rest[p..]),
        None => (rest, "/"),
    };
    let (host, port) = match hostport.rfind(':') {
        Some(p) => (
            &hostport[..p],
            hostport[p + 1..].parse::<u16>().unwrap_or(80),
        ),
        None => (hostport, 80),
    };

    let mut messages: Vec<String> = vec![
        format!("{{\"role\":\"system\",\"content\":{}}}", sys_raw),
        format!("{{\"role\":\"user\",\"content\":{}}}", user_raw),
    ];
    let mut pt: u64 = 0;
    let mut ct: u64 = 0;
    let mut tt: u64 = 0;
    let mut reqs: u64 = 0;

    loop {
        let body = format!(
            "{{\"model\":{},\"messages\":[{}],\"tools\":{},\"tool_choice\":\"auto\"}}",
            model_raw,
            messages.join(","),
            tools_raw
        );
        let (status, rbody) = post(host, port, path, &api_key, &body);
        reqs += 1;
        let rj = pj(&rbody);
        if status != 200 {
            let msg = jget(&rj, "error")
                .and_then(|e| jget(e, "message"))
                .map(jstr)
                .unwrap_or("");
            println!("ERROR {} {}", status, msg);
            return;
        }
        if let Some(u) = jget(&rj, "usage") {
            pt += jnum_u(jget(u, "prompt_tokens").unwrap_or(&J::Null));
            ct += jnum_u(jget(u, "completion_tokens").unwrap_or(&J::Null));
            tt += jnum_u(jget(u, "total_tokens").unwrap_or(&J::Null));
        }
        let choice = match jget(&rj, "choices").unwrap() {
            J::Arr(v) => &v[0],
            _ => unreachable!(),
        };
        let msg = jget(choice, "message").unwrap();
        let fr = jstr(jget(choice, "finish_reason").unwrap_or(&J::Null));
        if fr == "tool_calls" {
            if let Some(J::Str(ss)) = jget(msg, "content") {
                println!("SAY {}", ss.s);
            }
            let content_raw = match jget(msg, "content") {
                Some(J::Str(ss)) => ss.raw.clone(),
                _ => "null".to_string(),
            };
            let calls = match jget(msg, "tool_calls").unwrap() {
                J::Arr(v) => v,
                _ => unreachable!(),
            };
            let mut assistant = format!(
                "{{\"role\":\"assistant\",\"content\":{},\"tool_calls\":[",
                content_raw
            );
            let mut results: Vec<(String, String, String)> = Vec::new();
            for (idx, call) in calls.iter().enumerate() {
                let id_raw = jraw(jget(call, "id").unwrap()).to_string();
                let id = jstr(jget(call, "id").unwrap()).to_string();
                let type_raw = jraw(jget(call, "type").unwrap()).to_string();
                let func = jget(call, "function").unwrap();
                let name_raw = jraw(jget(func, "name").unwrap()).to_string();
                let name = jstr(jget(func, "name").unwrap()).to_string();
                let args_raw = jraw(jget(func, "arguments").unwrap()).to_string();
                let args_s = jstr(jget(func, "arguments").unwrap()).to_string();
                let args_j = pj(&args_s);
                let result = exec_tool(&name, &args_j, &inv, &rates);
                if idx > 0 {
                    assistant.push(',');
                }
                assistant.push_str(&format!(
                    "{{\"id\":{},\"type\":{},\"function\":{{\"name\":{},\"arguments\":{}}}}}",
                    id_raw, type_raw, name_raw, args_raw
                ));
                results.push((id, name, result));
            }
            assistant.push_str("]}");
            messages.push(assistant);
            for (id, name, _) in &results {
                println!("CALL {} {}", id, name);
            }
            for (id, _, res) in &results {
                println!("RESULT {} {}", id, res);
            }
            for (id, _, res) in &results {
                messages.push(format!(
                    "{{\"role\":\"tool\",\"tool_call_id\":{},\"content\":{}}}",
                    q(id),
                    q(res)
                ));
            }
        } else {
            let content = jstr(jget(msg, "content").unwrap_or(&J::Null));
            println!("FINAL {}", content);
            break;
        }
    }
    println!(
        "USAGE prompt={} completion={} total={} requests={}",
        pt, ct, tt, reqs
    );
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::exit;

// ---------------- JSON ----------------

#[derive(Clone)]
enum J {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

fn s(x: &str) -> J {
    J::Str(x.to_string())
}

impl J {
    fn get(&self, k: &str) -> Option<&J> {
        match self {
            J::Obj(m) => m.iter().find(|(kk, _)| kk == k).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> &str {
        match self {
            J::Str(x) => x,
            _ => "",
        }
    }
    fn num(&self) -> i64 {
        match self {
            J::Num(n) => n.parse().unwrap_or(0),
            _ => 0,
        }
    }
    fn idx(&self) -> usize {
        match self {
            J::Num(n) => n.parse().unwrap_or(0),
            _ => 0,
        }
    }
    fn ser(&self) -> String {
        match self {
            J::Null => "null".into(),
            J::Bool(b) => b.to_string(),
            J::Num(n) => n.clone(),
            J::Str(x) => jesc(x),
            J::Arr(a) => format!(
                "[{}]",
                a.iter().map(|x| x.ser()).collect::<Vec<_>>().join(",")
            ),
            J::Obj(m) => format!(
                "{{{}}}",
                m.iter()
                    .map(|(k, v)| format!("{}:{}", jesc(k), v.ser()))
                    .collect::<Vec<_>>()
                    .join(",")
            ),
        }
    }
}

fn jesc(x: &str) -> String {
    let mut o = String::from("\"");
    for c in x.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

fn out_esc(x: &str) -> String {
    let mut o = String::new();
    for c in x.chars() {
        match c {
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c => o.push(c),
        }
    }
    o
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn value(&mut self) -> Result<J, String> {
        self.ws();
        if self.i >= self.b.len() {
            return Err("eof".into());
        }
        match self.b[self.i] {
            b'{' => {
                self.i += 1;
                let mut m = Vec::new();
                self.ws();
                if self.i < self.b.len() && self.b[self.i] == b'}' {
                    self.i += 1;
                    return Ok(J::Obj(m));
                }
                loop {
                    self.ws();
                    let k = self.string()?;
                    self.ws();
                    if self.i >= self.b.len() || self.b[self.i] != b':' {
                        return Err("expected :".into());
                    }
                    self.i += 1;
                    let v = self.value()?;
                    m.push((k, v));
                    self.ws();
                    if self.i >= self.b.len() {
                        return Err("eof in object".into());
                    }
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err("expected , or }".into()),
                    }
                }
                Ok(J::Obj(m))
            }
            b'[' => {
                self.i += 1;
                let mut a = Vec::new();
                self.ws();
                if self.i < self.b.len() && self.b[self.i] == b']' {
                    self.i += 1;
                    return Ok(J::Arr(a));
                }
                loop {
                    a.push(self.value()?);
                    self.ws();
                    if self.i >= self.b.len() {
                        return Err("eof in array".into());
                    }
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err("expected , or ]".into()),
                    }
                }
                Ok(J::Arr(a))
            }
            b'"' => Ok(J::Str(self.string()?)),
            b't' => {
                self.i += 4;
                Ok(J::Bool(true))
            }
            b'f' => {
                self.i += 5;
                Ok(J::Bool(false))
            }
            b'n' => {
                self.i += 4;
                Ok(J::Null)
            }
            _ => {
                let st = self.i;
                while self.i < self.b.len()
                    && matches!(
                        self.b[self.i],
                        b'-' | b'+' | b'.' | b'0'..=b'9' | b'e' | b'E'
                    )
                {
                    self.i += 1;
                }
                if st == self.i {
                    return Err("bad value".into());
                }
                Ok(J::Num(
                    String::from_utf8_lossy(&self.b[st..self.i]).into_owned(),
                ))
            }
        }
    }
    fn string(&mut self) -> Result<String, String> {
        if self.i >= self.b.len() || self.b[self.i] != b'"' {
            return Err("expected string".into());
        }
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            if self.i >= self.b.len() {
                return Err("eof in string".into());
            }
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    if self.i >= self.b.len() {
                        return Err("eof in escape".into());
                    }
                    let e = self.b[self.i];
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let cp = self.hex4()?;
                            let ch = if (0xD800..0xDC00).contains(&cp) {
                                if self.i + 1 < self.b.len()
                                    && self.b[self.i] == b'\\'
                                    && self.b[self.i + 1] == b'u'
                                {
                                    self.i += 2;
                                    let lo = self.hex4()?;
                                    let c = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                    char::from_u32(c).unwrap_or('\u{fffd}')
                                } else {
                                    '\u{fffd}'
                                }
                            } else {
                                char::from_u32(cp).unwrap_or('\u{fffd}')
                            };
                            let mut buf = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return Err("bad escape".into()),
                    }
                }
                _ => out.push(c),
            }
        }
        Ok(String::from_utf8_lossy(&out).into_owned())
    }
    fn hex4(&mut self) -> Result<u32, String> {
        if self.i + 4 > self.b.len() {
            return Err("eof in \\u".into());
        }
        let h = std::str::from_utf8(&self.b[self.i..self.i + 4]).map_err(|_| "bad hex".to_string())?;
        let v = u32::from_str_radix(h, 16).map_err(|_| "bad hex".to_string())?;
        self.i += 4;
        Ok(v)
    }
}

fn parse(s: &str) -> Result<J, String> {
    let mut p = P { b: s.as_bytes(), i: 0 };
    p.ws();
    p.value()
}

// ---------------- HTTP ----------------

struct R {
    sock: TcpStream,
    data: Vec<u8>,
    pos: usize,
    eof: bool,
}

impl R {
    fn need(&mut self, n: usize) -> std::io::Result<bool> {
        while self.data.len() - self.pos < n {
            if self.eof {
                return Ok(false);
            }
            let mut tmp = [0u8; 16384];
            let k = self.sock.read(&mut tmp)?;
            if k == 0 {
                self.eof = true;
                return Ok(false);
            }
            self.data.extend_from_slice(&tmp[..k]);
        }
        Ok(true)
    }
    fn ensure1(&mut self) -> std::io::Result<bool> {
        if self.pos < self.data.len() {
            return Ok(true);
        }
        self.need(1)
    }
    fn line(&mut self) -> std::io::Result<String> {
        let mut line = Vec::new();
        loop {
            if !self.ensure1()? {
                break;
            }
            let b = self.data[self.pos];
            self.pos += 1;
            if b == b'\n' {
                break;
            }
            line.push(b);
        }
        if line.last() == Some(&b'\r') {
            line.pop();
        }
        Ok(String::from_utf8_lossy(&line).into_owned())
    }
    fn exact(&mut self, n: usize) -> std::io::Result<Vec<u8>> {
        let _ = self.need(n)?;
        let avail = (self.data.len() - self.pos).min(n);
        let v = self.data[self.pos..self.pos + avail].to_vec();
        self.pos += avail;
        Ok(v)
    }
    fn to_end(&mut self) -> std::io::Result<Vec<u8>> {
        loop {
            if !self.ensure1()? {
                break;
            }
        }
        let v = self.data[self.pos..].to_vec();
        self.pos = self.data.len();
        Ok(v)
    }
}

struct Response {
    status: u16,
    body: Vec<u8>,
}

fn read_chunked(r: &mut R) -> std::io::Result<Vec<u8>> {
    let mut out = Vec::new();
    loop {
        let l = r.line()?;
        let szs = l.split(';').next().unwrap_or("").trim();
        let n = usize::from_str_radix(szs, 16)
            .map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "bad chunk size"))?;
        if n == 0 {
            loop {
                let t = r.line()?;
                if t.is_empty() {
                    break;
                }
            }
            break;
        }
        let c = r.exact(n)?;
        out.extend_from_slice(&c);
        let _ = r.line()?; // CRLF after chunk
    }
    Ok(out)
}

fn read_response(r: &mut R) -> std::io::Result<Response> {
    let status_line = r.line()?;
    let status: u16 = status_line
        .split_whitespace()
        .nth(1)
        .unwrap_or("0")
        .parse()
        .unwrap_or(0);
    let mut headers = Vec::new();
    loop {
        let l = r.line()?;
        if l.is_empty() {
            break;
        }
        if let Some(c) = l.find(':') {
            headers.push((l[..c].to_lowercase(), l[c + 1..].trim().to_string()));
        }
    }
    let te = headers
        .iter()
        .find(|(k, _)| k == "transfer-encoding")
        .map(|(_, v)| v.to_lowercase())
        .unwrap_or_default();
    let cl = headers
        .iter()
        .find(|(k, _)| k == "content-length")
        .and_then(|(_, v)| v.parse::<usize>().ok());
    let body = if te.contains("chunked") {
        read_chunked(r)?
    } else if let Some(n) = cl {
        r.exact(n)?
    } else {
        r.to_end()?
    };
    Ok(Response { status, body })
}

fn split_url(url: &str) -> (String, String, String) {
    let rest = url.strip_prefix("http://").unwrap_or(url);
    let (auth, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match auth.rfind(':') {
        Some(i) => (auth[..i].to_string(), auth[i + 1..].to_string()),
        None => (auth.to_string(), "80".to_string()),
    };
    (host, port, path.to_string())
}

fn send(base: &str, key: &str, body: &str) -> Response {
    let (host, port, path) = split_url(base);
    let sock = TcpStream::connect((host.as_str(), port.parse::<u16>().unwrap_or(80)))
        .expect("connect failed");
    let req = format!(
        "POST {}/v1/messages HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nConnection: close\r\n\r\n{}",
        path.trim_end_matches('/'),
        host,
        port,
        body.len(),
        key,
        body
    );
    let mut sock = sock;
    sock.write_all(req.as_bytes()).expect("write failed");
    let mut r = R { sock, data: Vec::new(), pos: 0, eof: false };
    read_response(&mut r).expect("read failed")
}

// ---------------- SSE ----------------

fn parse_sse(body: &[u8]) -> Vec<(String, String)> {
    let text = String::from_utf8_lossy(body);
    let mut events = Vec::new();
    let mut evname = String::new();
    let mut datas: Vec<String> = Vec::new();
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.is_empty() {
            if !datas.is_empty() || !evname.is_empty() {
                events.push((evname.clone(), datas.join("\n")));
            }
            evname.clear();
            datas.clear();
        } else if line.starts_with(':') {
            // comment
        } else if let Some(v) = line.strip_prefix("event:") {
            evname = v.strip_prefix(' ').unwrap_or(v).to_string();
        } else if let Some(v) = line.strip_prefix("data:") {
            datas.push(v.strip_prefix(' ').unwrap_or(v).to_string());
        }
    }
    if !datas.is_empty() || !evname.is_empty() {
        events.push((evname, datas.join("\n")));
    }
    events
}

// ---------------- Blocks / events ----------------

struct Blk {
    kind: String,
    thinking: String,
    signature: String,
    text: String,
    id: String,
    name: String,
    raw: String,
}

impl Blk {
    fn to_json(&self) -> J {
        match self.kind.as_str() {
            "thinking" => J::Obj(vec![
                ("type".into(), s("thinking")),
                ("thinking".into(), s(&self.thinking)),
                ("signature".into(), s(&self.signature)),
            ]),
            "text" => J::Obj(vec![("type".into(), s("text")), ("text".into(), s(&self.text))]),
            "tool_use" => J::Obj(vec![
                ("type".into(), s("tool_use")),
                ("id".into(), s(&self.id)),
                ("name".into(), s(&self.name)),
                (
                    "input".into(),
                    parse(&self.raw).unwrap_or(J::Obj(Vec::new())),
                ),
            ]),
            _ => J::Null,
        }
    }
}

fn handle_event(
    name: &str,
    data: &str,
    blocks: &mut Vec<Option<Blk>>,
    usage: &mut (i64, i64, i64),
    stop: &mut Option<String>,
) {
    let v = match parse(data) {
        Ok(v) => v,
        Err(_) => return,
    };
    match name {
        "message_start" => {
            if let Some(u) = v.get("message").and_then(|m| m.get("usage")) {
                if let Some(x) = u.get("input_tokens") {
                    usage.0 += x.num();
                }
                if let Some(x) = u.get("cache_read_input_tokens") {
                    usage.2 += x.num();
                }
            }
        }
        "content_block_start" => {
            let idx = v.get("index").map(|x| x.idx()).unwrap_or(0);
            while blocks.len() <= idx {
                blocks.push(None);
            }
            let cb = v.get("content_block").cloned().unwrap_or(J::Obj(Vec::new()));
            let kind = cb.get("type").map(|x| x.as_str().to_string()).unwrap_or_default();
            let id = cb.get("id").map(|x| x.as_str().to_string()).unwrap_or_default();
            let nm = cb.get("name").map(|x| x.as_str().to_string()).unwrap_or_default();
            blocks[idx] = Some(Blk {
                kind,
                thinking: String::new(),
                signature: String::new(),
                text: String::new(),
                id,
                name: nm,
                raw: String::new(),
            });
        }
        "content_block_delta" => {
            let idx = v.get("index").map(|x| x.idx()).unwrap_or(0);
            if let Some(d) = v.get("delta") {
                let t = d.get("type").map(|x| x.as_str().to_string()).unwrap_or_default();
                if let Some(b) = blocks.get_mut(idx).and_then(|x| x.as_mut()) {
                    match t.as_str() {
                        "thinking_delta" => {
                            if let Some(J::Str(x)) = d.get("thinking") {
                                b.thinking += x;
                            }
                        }
                        "signature_delta" => {
                            if let Some(J::Str(x)) = d.get("signature") {
                                b.signature += x;
                            }
                        }
                        "text_delta" => {
                            if let Some(J::Str(x)) = d.get("text") {
                                b.text += x;
                            }
                        }
                        "input_json_delta" => {
                            if let Some(J::Str(x)) = d.get("partial_json") {
                                b.raw += x;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
        "message_delta" => {
            if let Some(d) = v.get("delta") {
                if let Some(sr) = d.get("stop_reason") {
                    *stop = Some(sr.as_str().to_string());
                }
            }
            if let Some(u) = v.get("usage") {
                if let Some(x) = u.get("output_tokens") {
                    usage.1 += x.num();
                }
            }
        }
        _ => {}
    }
}

fn print_blocks(blocks: &Vec<Option<Blk>>) {
    for b in blocks.iter().flatten() {
        match b.kind.as_str() {
            "thinking" => {
                println!("thinking {}", out_esc(&b.thinking));
                println!("signature {}", out_esc(&b.signature));
            }
            "text" => println!("text {}", out_esc(&b.text)),
            "tool_use" => println!("tool_use {} {} {}", b.id, b.name, out_esc(&b.raw)),
            _ => {}
        }
    }
}

// ---------------- Tools ----------------

fn run_tool(name: &str, input_json: &str) -> (String, bool) {
    let parsed = match parse(input_json) {
        Ok(p) => p,
        Err(_) => return ("invalid tool input".to_string(), true),
    };
    let m = match parsed {
        J::Obj(m) => m,
        _ => return ("invalid tool input".to_string(), true),
    };
    let get = |k: &str| -> String {
        m.iter()
            .find(|(kk, _)| kk == k)
            .map(|(_, v)| v.as_str().to_string())
            .unwrap_or_default()
    };
    match name {
        "measure" => {
            let text = get("text");
            let unit = get("unit");
            match unit.as_str() {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.len().to_string(), false),
                "utf16_units" => (
                    text.chars().map(|c| c.len_utf16()).sum::<usize>().to_string(),
                    false,
                ),
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => (get("text").chars().rev().collect::<String>(), false),
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ---------------- Main ----------------

fn die(r: Response) -> ! {
    let txt = String::from_utf8_lossy(&r.body).into_owned();
    let (t, m) = match parse(&txt) {
        Ok(v) => (
            v.get("error")
                .and_then(|e| e.get("type"))
                .map(|x| x.as_str().to_string())
                .unwrap_or_default(),
            v.get("error")
                .and_then(|e| e.get("message"))
                .map(|x| x.as_str().to_string())
                .unwrap_or_default(),
        ),
        Err(_) => (String::new(), txt),
    };
    println!("ERROR {} {}: {}", r.status, out_esc(&t), out_esc(&m));
    exit(0);
}

fn build_body(model: &str, max_tokens: &J, budget: &J, system: &str, tools: &J, messages: J) -> String {
    J::Obj(vec![
        ("model".into(), s(model)),
        ("max_tokens".into(), max_tokens.clone()),
        ("stream".into(), J::Bool(true)),
        (
            "thinking".into(),
            J::Obj(vec![
                ("type".into(), s("enabled")),
                ("budget_tokens".into(), budget.clone()),
            ]),
        ),
        ("system".into(), s(system)),
        ("tools".into(), tools.clone()),
        ("messages".into(), messages),
    ])
    .ser()
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        exit(1);
    }
    let data_dir = &args[1];
    let base = &args[2];
    let raw = fs::read_to_string(format!("{}/request.json", data_dir)).expect("read request.json");
    let cfg = parse(&raw).expect("parse request.json");
    let api_key = cfg.get("api_key").unwrap().as_str().to_string();
    let model = cfg.get("model").unwrap().as_str().to_string();
    let max_tokens = cfg.get("max_tokens").unwrap().clone();
    let budget = cfg.get("thinking_budget").unwrap().clone();
    let system = cfg.get("system").unwrap().as_str().to_string();
    let prompt = cfg.get("prompt").unwrap().as_str().to_string();
    let tools = cfg.get("tools").unwrap().clone();

    let mut usage: (i64, i64, i64) = (0, 0, 0);
    let user_msg = J::Obj(vec![("role".into(), s("user")), ("content".into(), s(&prompt))]);

    println!("request 1");
    let b1 = build_body(&model, &max_tokens, &budget, &system, &tools, J::Arr(vec![user_msg.clone()]));
    let r1 = send(base, &api_key, &b1);
    if r1.status != 200 {
        die(r1);
    }
    let mut blocks: Vec<Option<Blk>> = Vec::new();
    let mut stop: Option<String> = None;
    for (n, d) in parse_sse(&r1.body) {
        handle_event(&n, &d, &mut blocks, &mut usage, &mut stop);
    }
    print_blocks(&blocks);
    println!("stop_reason {}", stop.unwrap_or_default());

    let mut results: Vec<(String, String, bool)> = Vec::new();
    for b in blocks.iter().flatten() {
        if b.kind == "tool_use" {
            let (res, err) = run_tool(&b.name, &b.raw);
            println!(
                "{} {} {}",
                if err { "error" } else { "result" },
                b.id,
                out_esc(&res)
            );
            results.push((b.id.clone(), res, err));
        }
    }

    println!("request 2");
    let asst: Vec<J> = blocks.iter().flatten().map(|b| b.to_json()).collect();
    let tr: Vec<J> = results
        .iter()
        .map(|(id, res, err)| {
            let mut v = vec![
                ("type".into(), s("tool_result")),
                ("tool_use_id".into(), s(id)),
                ("content".into(), s(res)),
            ];
            if *err {
                v.push(("is_error".into(), J::Bool(true)));
            }
            J::Obj(v)
        })
        .collect();
    let msgs = J::Arr(vec![
        user_msg,
        J::Obj(vec![("role".into(), s("assistant")), ("content".into(), J::Arr(asst))]),
        J::Obj(vec![("role".into(), s("user")), ("content".into(), J::Arr(tr))]),
    ]);
    let b2 = build_body(&model, &max_tokens, &budget, &system, &tools, msgs);
    let r2 = send(base, &api_key, &b2);
    if r2.status != 200 {
        die(r2);
    }
    let mut blocks2: Vec<Option<Blk>> = Vec::new();
    let mut stop2: Option<String> = None;
    for (n, d) in parse_sse(&r2.body) {
        handle_event(&n, &d, &mut blocks2, &mut usage, &mut stop2);
    }
    print_blocks(&blocks2);
    println!("stop_reason {}", stop2.unwrap_or_default());
    println!("usage input={} output={} cache_read={}", usage.0, usage.1, usage.2);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdarg.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>

/* ---------- string builder ---------- */
typedef struct { char *d; size_t n, cap; } SB;
static void sbneed(SB *b, size_t k) {
    if (b->n + k + 1 > b->cap) {
        size_t c = b->cap ? b->cap * 2 : 256;
        while (c < b->n + k + 1) c *= 2;
        b->d = realloc(b->d, c);
        b->cap = c;
    }
}
static void sbputn(SB *b, const char *s, size_t k) { sbneed(b, k); memcpy(b->d + b->n, s, k); b->n += k; b->d[b->n] = 0; }
static void sbputs(SB *b, const char *s) { sbputn(b, s, strlen(s)); }
static void sbputc(SB *b, char c) { sbneed(b, 1); b->d[b->n++] = c; b->d[b->n] = 0; }
static void sbprintf(SB *b, const char *fmt, ...) {
    char tmp[256];
    va_list ap; va_start(ap, fmt);
    int k = vsnprintf(tmp, sizeof tmp, fmt, ap);
    va_end(ap);
    if (k <= 0) return;
    if ((size_t)k < sizeof tmp) { sbputn(b, tmp, (size_t)k); }
    else {
        char *big = malloc((size_t)k + 1);
        va_start(ap, fmt); vsnprintf(big, (size_t)k + 1, fmt, ap); va_end(ap);
        sbputn(b, big, (size_t)k); free(big);
    }
}

/* ---------- JSON ---------- */
enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ };
typedef struct JVal JVal;
struct JVal {
    int t; int b;
    long long num; char *raw;
    char *str;
    JVal **items; char **keys; int n;
};
static JVal *jnew(int t) { JVal *v = calloc(1, sizeof(JVal)); v->t = t; return v; }

typedef struct { const char *s; size_t i, n; } P;
static void pws(P *p) {
    while (p->i < p->n) {
        char c = p->s[p->i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->i++; else break;
    }
}
static void utf8enc(SB *b, unsigned u) {
    if (u < 0x80) sbputc(b, (char)u);
    else if (u < 0x800) { sbputc(b, (char)(0xC0 | (u >> 6))); sbputc(b, (char)(0x80 | (u & 63))); }
    else if (u < 0x10000) { sbputc(b, (char)(0xE0 | (u >> 12))); sbputc(b, (char)(0x80 | ((u >> 6) & 63))); sbputc(b, (char)(0x80 | (u & 63))); }
    else { sbputc(b, (char)(0xF0 | (u >> 18))); sbputc(b, (char)(0x80 | ((u >> 12) & 63))); sbputc(b, (char)(0x80 | ((u >> 6) & 63))); sbputc(b, (char)(0x80 | (u & 63))); }
}
static int hexval(char h) {
    if (h >= '0' && h <= '9') return h - '0';
    if (h >= 'a' && h <= 'f') return h - 'a' + 10;
    if (h >= 'A' && h <= 'F') return h - 'A' + 10;
    return 0;
}
static char *pstr(P *p) {
    SB b = {0};
    p->i++; /* opening quote */
    while (p->i < p->n) {
        unsigned char c = (unsigned char)p->s[p->i];
        if (c == '"') { p->i++; break; }
        if (c == '\\') {
            p->i++;
            if (p->i >= p->n) break;
            char e = p->s[p->i++];
            switch (e) {
                case '"': sbputc(&b, '"'); break;
                case '\\': sbputc(&b, '\\'); break;
                case '/': sbputc(&b, '/'); break;
                case 'b': sbputc(&b, '\b'); break;
                case 'f': sbputc(&b, '\f'); break;
                case 'n': sbputc(&b, '\n'); break;
                case 'r': sbputc(&b, '\r'); break;
                case 't': sbputc(&b, '\t'); break;
                case 'u': {
                    unsigned u = 0;
                    for (int k = 0; k < 4 && p->i < p->n; k++) u = u * 16 + (unsigned)hexval(p->s[p->i++]);
                    if (u >= 0xD800 && u <= 0xDBFF && p->i + 1 < p->n && p->s[p->i] == '\\' && p->s[p->i + 1] == 'u') {
                        p->i += 2;
                        unsigned v = 0;
                        for (int k = 0; k < 4 && p->i < p->n; k++) v = v * 16 + (unsigned)hexval(p->s[p->i++]);
                        u = 0x10000 + ((u - 0xD800) << 10) + (v - 0xDC00);
                    }
                    utf8enc(&b, u);
                    break;
                }
                default: sbputc(&b, e);
            }
        } else { sbputc(&b, (char)c); p->i++; }
    }
    if (!b.d) return strdup("");
    return b.d;
}
static JVal *jparse(P *p) {
    pws(p);
    if (p->i >= p->n) return jnew(JNULL);
    char c = p->s[p->i];
    if (c == '{') {
        p->i++; JVal *o = jnew(JOBJ);
        pws(p);
        if (p->i < p->n && p->s[p->i] == '}') { p->i++; return o; }
        while (p->i < p->n) {
            pws(p);
            char *k = pstr(p);
            pws(p); p->i++; /* ':' */
            JVal *v = jparse(p);
            o->keys = realloc(o->keys, (size_t)(o->n + 1) * sizeof(char *));
            o->items = realloc(o->items, (size_t)(o->n + 1) * sizeof(JVal *));
            o->keys[o->n] = k; o->items[o->n] = v; o->n++;
            pws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == '}') { p->i++; }
            break;
        }
        return o;
    }
    if (c == '[') {
        p->i++; JVal *a = jnew(JARR);
        pws(p);
        if (p->i < p->n && p->s[p->i] == ']') { p->i++; return a; }
        while (p->i < p->n) {
            JVal *v = jparse(p);
            a->items = realloc(a->items, (size_t)(a->n + 1) * sizeof(JVal *));
            a->items[a->n++] = v;
            pws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == ']') { p->i++; }
            break;
        }
        return a;
    }
    if (c == '"') { JVal *v = jnew(JSTR); v->str = pstr(p); return v; }
    if (!strncmp(p->s + p->i, "true", 4)) { p->i += 4; JVal *v = jnew(JBOOL); v->b = 1; return v; }
    if (!strncmp(p->s + p->i, "false", 5)) { p->i += 5; return jnew(JBOOL); }
    if (!strncmp(p->s + p->i, "null", 4)) { p->i += 4; return jnew(JNULL); }
    size_t st = p->i;
    while (p->i < p->n && strchr("-+0123456789.eE", p->s[p->i])) p->i++;
    JVal *v = jnew(JNUM);
    size_t l = p->i - st;
    v->raw = malloc(l + 1);
    memcpy(v->raw, p->s + st, l); v->raw[l] = 0;
    v->num = strtoll(v->raw, 0, 10);
    return v;
}
static JVal *jget(JVal *o, const char *k) {
    if (!o || o->t != JOBJ) return NULL;
    for (int i = 0; i < o->n; i++)
        if (!strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}
static void jesc(SB *b, const char *s) {
    sbputc(b, '"');
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        switch (c) {
            case '"': sbputs(b, "\\\""); break;
            case '\\': sbputs(b, "\\\\"); break;
            case '\b': sbputs(b, "\\b"); break;
            case '\f': sbputs(b, "\\f"); break;
            case '\n': sbputs(b, "\\n"); break;
            case '\r': sbputs(b, "\\r"); break;
            case '\t': sbputs(b, "\\t"); break;
            default:
                if (c < 0x20) sbprintf(b, "\\u%04x", c);
                else sbputc(b, (char)c);
        }
    }
    sbputc(b, '"');
}
static void jser(SB *b, JVal *v) {
    switch (v->t) {
        case JNULL: sbputs(b, "null"); break;
        case JBOOL: sbputs(b, v->b ? "true" : "false"); break;
        case JNUM: sbputs(b, v->raw); break;
        case JSTR: jesc(b, v->str); break;
        case JARR:
            sbputc(b, '[');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jser(b, v->items[i]); }
            sbputc(b, ']');
            break;
        case JOBJ:
            sbputc(b, '{');
            for (int i = 0; i < v->n; i++) {
                if (i) sbputc(b, ',');
                jesc(b, v->keys[i]); sbputc(b, ':'); jser(b, v->items[i]);
            }
            sbputc(b, '}');
            break;
    }
}

/* ---------- file reading ---------- */
static char *readfile(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *d = malloc((size_t)n + 1);
    if (n > 0 && fread(d, 1, (size_t)n, f) != (size_t)n) { /* ignore */ }
    d[n] = 0;
    fclose(f);
    return d;
}

/* ---------- CSV ---------- */
typedef struct { char **f; int n; } Row;
static Row *rows = NULL;
static int nrows = 0;
static void parse_csv(const char *path) {
    char *s = readfile(path);
    size_t i = 0;
    if ((unsigned char)s[0] == 0xEF && (unsigned char)s[1] == 0xBB && (unsigned char)s[2] == 0xBF) i = 3;
    while (s[i]) {
        Row r = {0};
        while (1) {
            SB f = {0};
            if (s[i] == '"') {
                i++;
                while (s[i]) {
                    if (s[i] == '"') {
                        if (s[i + 1] == '"') { sbputc(&f, '"'); i += 2; }
                        else { i++; break; }
                    } else { sbputc(&f, s[i]); i++; }
                }
            } else {
                while (s[i] && s[i] != ',' && !(s[i] == '\r' && s[i + 1] == '\n')) { sbputc(&f, s[i]); i++; }
            }
            r.f = realloc(r.f, (size_t)(r.n + 1) * sizeof(char *));
            r.f[r.n++] = f.d ? f.d : strdup("");
            if (s[i] == ',') { i++; continue; }
            if (s[i] == '\r' && s[i + 1] == '\n') i += 2;
            break;
        }
        rows = realloc(rows, (size_t)(nrows + 1) * sizeof(Row));
        rows[nrows++] = r;
    }
}

/* ---------- rates ---------- */
typedef struct { char *code; long long r; } Rate;
static Rate *ratev = NULL;
static int nratev = 0;
static long long rateof(const char *c) {
    for (int i = 0; i < nratev; i++)
        if (!strcmp(ratev[i].code, c)) return ratev[i].r;
    return 0;
}

/* ---------- HTTP ---------- */
static int tcp_connect(const char *host, const char *port) {
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, port, &hints, &res) != 0) return -1;
    int fd = -1;
    for (struct addrinfo *a = res; a; a = a->ai_next) {
        fd = socket(a->ai_family, a->ai_socktype, 0);
        if (fd < 0) continue;
        if (connect(fd, a->ai_addr, a->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    return fd;
}
static char *http_post(const char *url, const char *key, const char *body, int *status) {
    const char *p = url;
    if (!strncmp(p, "http://", 7)) p += 7;
    const char *slash = strchr(p, '/');
    size_t hl = slash ? (size_t)(slash - p) : strlen(p);
    const char *path = slash ? slash : "/";
    char *hostfull = malloc(hl + 1);
    memcpy(hostfull, p, hl); hostfull[hl] = 0;
    char hostonly[256];
    snprintf(hostonly, sizeof hostonly, "%s", hostfull);
    char port[16] = "80";
    char *colon = strchr(hostonly, ':');
    if (colon) { *colon = 0; snprintf(port, sizeof port, "%s", colon + 1); }

    SB req = {0};
    sbprintf(&req, "POST %s/chat/completions HTTP/1.1\r\nHost: %s\r\nAuthorization: Bearer %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",
             path, hostfull, key, strlen(body));
    sbputs(&req, body);

    int fd = tcp_connect(hostonly, port);
    if (fd < 0) { *status = -1; return strdup("{\"error\":{\"message\":\"connection failed\"}}"); }
    size_t off = 0;
    while (off < req.n) {
        ssize_t k = send(fd, req.d + off, req.n - off, 0);
        if (k <= 0) break;
        off += (size_t)k;
    }
    SB resp = {0};
    char buf[65536];
    ssize_t k;
    while ((k = recv(fd, buf, sizeof buf, 0)) > 0) sbputn(&resp, buf, (size_t)k);
    close(fd);

    int code = 0;
    if (resp.n >= 12 && !strncmp(resp.d, "HTTP/", 5)) code = atoi(resp.d + 9);
    char *sep = strstr(resp.d, "\r\n\r\n");
    char *b = sep ? sep + 4 : resp.d;
    *status = code;
    return strdup(b);
}

/* ---------- tools ---------- */
static void tool_result(SB *res, const char *name, JVal *args) {
    if (!strcmp(name, "inventory_lookup")) {
        const char *sku = jget(args, "sku")->str;
        Row *found = NULL;
        for (int i = 0; i < nrows; i++)
            if (!strcmp(rows[i].f[0], sku)) { found = &rows[i]; break; }
        if (found) {
            sbputs(res, "{\"sku\":"); jesc(res, found->f[0]);
            sbputs(res, ",\"name\":"); jesc(res, found->f[1]);
            sbprintf(res, ",\"price_cents\":%lld,\"currency\":", strtoll(found->f[2], 0, 10));
            jesc(res, found->f[3]);
            sbprintf(res, ",\"stock\":%lld}", strtoll(found->f[4], 0, 10));
        } else {
            SB e = {0};
            sbprintf(&e, "unknown sku: %s", sku);
            sbputs(res, "{\"error\":"); jesc(res, e.d); sbputc(res, '}');
        }
    } else if (!strcmp(name, "convert_currency")) {
        long long amount = jget(args, "amount_cents")->num;
        const char *from = jget(args, "from")->str;
        const char *to = jget(args, "to")->str;
        long long rf = rateof(from), rt = rateof(to);
        long long conv = (long long)((2 * (__int128)amount * rt + rf) / (2 * (__int128)rf));
        sbprintf(res, "{\"amount_cents\":%lld,\"currency\":", conv);
        jesc(res, to);
        sbputc(res, '}');
    } else {
        SB e = {0};
        sbprintf(&e, "unknown tool: %s", name);
        sbputs(res, "{\"error\":"); jesc(res, e.d); sbputc(res, '}');
    }
}

/* ---------- main ---------- */
int main(int argc, char **argv) {
    if (argc < 3) return 1;
    const char *dir = argv[1], *base = argv[2];
    char path[1024];

    snprintf(path, sizeof path, "%s/task.json", dir);
    char *tj = readfile(path);
    P tp = {tj, strlen(tj)};
    JVal *task = jparse(&tp);
    const char *api_key = jget(task, "api_key")->str;
    const char *model = jget(task, "model")->str;
    JVal *system = jget(task, "system");
    JVal *user = jget(task, "user");
    JVal *tools = jget(task, "tools");

    snprintf(path, sizeof path, "%s/rates.json", dir);
    char *rj = readfile(path);
    P rp0 = {rj, strlen(rj)};
    JVal *ratesj = jparse(&rp0);
    JVal *rs = jget(ratesj, "rates");
    ratev = malloc((size_t)rs->n * sizeof(Rate));
    for (int i = 0; i < rs->n; i++) {
        ratev[i].code = rs->keys[i];
        ratev[i].r = rs->items[i]->num;
        nratev++;
    }

    snprintf(path, sizeof path, "%s/inventory.csv", dir);
    parse_csv(path);

    char **msgs = NULL;
    int nmsgs = 0, cap = 0;
#define ADDMSG(s) do { if (nmsgs == cap) { cap = cap ? cap * 2 : 8; msgs = realloc(msgs, (size_t)cap * sizeof(char *)); } msgs[nmsgs++] = (s); } while (0)

    { SB m = {0}; sbputs(&m, "{\"role\":\"system\",\"content\":"); jesc(&m, system->str); sbputs(&m, "}"); ADDMSG(m.d); }
    { SB m = {0}; sbputs(&m, "{\"role\":\"user\",\"content\":"); jesc(&m, user->str); sbputs(&m, "}"); ADDMSG(m.d); }

    long long pt = 0, ct = 0, tt = 0;
    int nreq = 0;

    while (1) {
        SB body = {0};
        sbputs(&body, "{\"model\":");
        jesc(&body, model);
        sbputs(&body, ",\"messages\":[");
        for (int i = 0; i < nmsgs; i++) { if (i) sbputc(&body, ','); sbputs(&body, msgs[i]); }
        sbputs(&body, "],\"tools\":");
        jser(&body, tools);
        sbputs(&body, ",\"tool_choice\":\"auto\"}");

        nreq++;
        int st;
        char *resp = http_post(base, api_key, body.d, &st);
        if (st != 200) {
            P ep = {resp, strlen(resp)};
            JVal *ej = jparse(&ep);
            const char *msg = "";
            JVal *e = jget(ej, "error");
            if (e) { JVal *em = jget(e, "message"); if (em && em->str) msg = em->str; }
            printf("ERROR %d %s\n", st, msg);
            return 0;
        }

        P rp = {resp, strlen(resp)};
        JVal *r = jparse(&rp);

        JVal *u = jget(r, "usage");
        if (u) {
            JVal *x;
            if ((x = jget(u, "prompt_tokens"))) pt += x->num;
            if ((x = jget(u, "completion_tokens"))) ct += x->num;
            if ((x = jget(u, "total_tokens"))) tt += x->num;
        }

        JVal *ch = jget(jget(r, "choices"), NULL) ? jget(r, "choices") : NULL;
        ch = jget(r, "choices");
        JVal *choice = ch->items[0];
        JVal *msg = jget(choice, "message");
        const char *fr = jget(choice, "finish_reason")->str;

        if (!strcmp(fr, "tool_calls")) {
            JVal *content = jget(msg, "content");
            if (content && content->t == JSTR) printf("SAY %s\n", content->str);

            JVal *tcs = jget(msg, "tool_calls");
            int ntc = tcs ? tcs->n : 0;

            SB am = {0};
            sbputs(&am, "{\"role\":\"assistant\",\"content\":");
            if (content && content->t == JSTR) jesc(&am, content->str);
            else sbputs(&am, "null");
            sbputs(&am, ",\"tool_calls\":[");
            for (int i = 0; i < ntc; i++) {
                JVal *tc = tcs->items[i];
                JVal *fn = jget(tc, "function");
                if (i) sbputc(&am, ',');
                sbputs(&am, "{\"id\":");
                jesc(&am, jget(tc, "id")->str);
                sbputs(&am, ",\"type\":\"function\",\"function\":{\"name\":");
                jesc(&am, jget(fn, "name")->str);
                sbputs(&am, ",\"arguments\":");
                jesc(&am, jget(fn, "arguments")->str);
                sbputs(&am, "}}");
            }
            sbputs(&am, "]}");
            ADDMSG(am.d);

            for (int i = 0; i < ntc; i++)
                printf("CALL %s %s\n", jget(tcs->items[i], "id")->str, jget(jget(tcs->items[i], "function"), "name")->str);

            for (int i = 0; i < ntc; i++) {
                JVal *tc = tcs->items[i];
                const char *id = jget(tc, "id")->str;
                const char *name = jget(jget(tc, "function"), "name")->str;
                const char *argsstr = jget(jget(tc, "function"), "arguments")->str;
                P ap = {argsstr, strlen(argsstr)};
                JVal *args = jparse(&ap);
                SB res = {0};
                tool_result(&res, name, args);
                SB tm = {0};
                sbputs(&tm, "{\"role\":\"tool\",\"tool_call_id\":");
                jesc(&tm, id);
                sbputs(&tm, ",\"content\":");
                jesc(&tm, res.d);
                sbputs(&tm, "}");
                ADDMSG(tm.d);
                printf("RESULT %s %s\n", id, res.d);
            }
        } else {
            JVal *content = jget(msg, "content");
            printf("FINAL %s\n", content && content->t == JSTR ? content->str : "");
            break;
        }
    }

    printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n", pt, ct, tt, nreq);
    return 0;
}

#include <stdio.h>
