/* ---------- string builder ---------- */
typedef struct { char *d; size_t n, cap; } SB;
static void sbneed(SB *b, size_t k) {
    if (b->n + k + 1 > b->cap) {
        size_t c = b->cap ? b->cap * 2 : 256;
        while (c < b->n + k + 1) c *= 2;
        b->d = realloc(b->d, c);
        b->cap = c;
    }
}
static void sbputn(SB *b, const char *s, size_t k) { sbneed(b, k); memcpy(b->d + b->n, s, k); b->n += k; b->d[b->n] = 0; }
static void sbputs(SB *b, const char *s) { sbputn(b, s, strlen(s)); }
static void sbputc(SB *b, char c) { sbneed(b, 1); b->d[b->n++] = c; b->d[b->n] = 0; }
static void sbprintf(SB *b, const char *fmt, ...) {
    char tmp[256];
    va_list ap; va_start(ap, fmt);
    int k = vsnprintf(tmp, sizeof tmp, fmt, ap);
    va_end(ap);
    if (k <= 0) return;
    if ((size_t)k < sizeof tmp) { sbputn(b, tmp, (size_t)k); }
    else {
        char *big = malloc((size_t)k + 1);
        va_start(ap, fmt); vsnprintf(big, (size_t)k + 1, fmt, ap); va_end(ap);
        sbputn(b, big, (size_t)k); free(big);
    }
}

/* ---------- JSON ---------- */
enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ };
typedef struct JVal JVal;
struct JVal {
    int t; int b;
    long long num; char *raw;
    char *str;
    JVal **items; char **keys; int n;
};
static JVal *jnew(int t) { JVal *v = calloc(1, sizeof(JVal)); v->t = t; return v; }

typedef struct { const char *s; size_t i, n; } P;
static void pws(P *p) {
    while (p->i < p->n) {
        char c = p->s[p->i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->i++; else break;
    }
}
static void utf8enc(SB *b, unsigned u) {
    if (u < 0x80) sbputc(b, (char)u);
    else if (u < 0x800) { sbputc(b, (char)(0xC0 | (u >> 6))); sbputc(b, (char)(0x80 | (u & 63))); }
    else if (u < 0x10000) { sbputc(b, (char)(0xE0 | (u >> 12))); sbputc(b, (char)(0x80 | ((u >> 6) & 63))); sbputc(b, (char)(0x80 | (u & 63))); }
    else { sbputc(b, (char)(0xF0 | (u >> 18))); sbputc(b, (char)(0x80 | ((u >> 12) & 63))); sbputc(b, (char)(0x80 | ((u >> 6) & 63))); sbputc(b, (char)(0x80 | (u & 63))); }
}
static int hexval(char h) {
    if (h >= '0' && h <= '9') return h - '0';
    if (h >= 'a' && h <= 'f') return h - 'a' + 10;
    if (h >= 'A' && h <= 'F') return h - 'A' + 10;
    return 0;
}
static char *pstr(P *p) {
    SB b = {0};
    p->i++; /* opening quote */
    while (p->i < p->n) {
        unsigned char c = (unsigned char)p->s[p->i];
        if (c == '"') { p->i++; break; }
        if (c == '\\') {
            p->i++;
            if (p->i >= p->n) break;
            char e = p->s[p->i++];
            switch (e) {
                case '"': sbputc(&b, '"'); break;
                case '\\': sbputc(&b, '\\'); break;
                case '/': sbputc(&b, '/'); break;
                case 'b': sbputc(&b, '\b'); break;
                case 'f': sbputc(&b, '\f'); break;
                case 'n': sbputc(&b, '\n'); break;
                case 'r': sbputc(&b, '\r'); break;
                case 't': sbputc(&b, '\t'); break;
                case 'u': {
                    unsigned u = 0;
                    for (int k = 0; k < 4 && p->i < p->n; k++) u = u * 16 + (unsigned)hexval(p->s[p->i++]);
                    if (u >= 0xD800 && u <= 0xDBFF && p->i + 1 < p->n && p->s[p->i] == '\\' && p->s[p->i + 1] == 'u') {
                        p->i += 2;
                        unsigned v = 0;
                        for (int k = 0; k < 4 && p->i < p->n; k++) v = v * 16 + (unsigned)hexval(p->s[p->i++]);
                        u = 0x10000 + ((u - 0xD800) << 10) + (v - 0xDC00);
                    }
                    utf8enc(&b, u);
                    break;
                }
                default: sbputc(&b, e);
            }
        } else { sbputc(&b, (char)c); p->i++; }
    }
    if (!b.d) return strdup("");
    return b.d;
}
static JVal *jparse(P *p) {
    pws(p);
    if (p->i >= p->n) return jnew(JNULL);
    char c = p->s[p->i];
    if (c == '{') {
        p->i++; JVal *o = jnew(JOBJ);
        pws(p);
        if (p->i < p->n && p->s[p->i] == '}') { p->i++; return o; }
        while (p->i < p->n) {
            pws(p);
            char *k = pstr(p);
            pws(p); p->i++; /* ':' */
            JVal *v = jparse(p);
            o->keys = realloc(o->keys, (size_t)(o->n + 1) * sizeof(char *));
            o->items = realloc(o->items, (size_t)(o->n + 1) * sizeof(JVal *));
            o->keys[o->n] = k; o->items[o->n] = v; o->n++;
            pws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == '}') { p->i++; }
            break;
        }
        return o;
    }
    if (c == '[') {
        p->i++; JVal *a = jnew(JARR);
        pws(p);
        if (p->i < p->n && p->s[p->i] == ']') { p->i++; return a; }
        while (p->i < p->n) {
            JVal *v = jparse(p);
            a->items = realloc(a->items, (size_t)(a->n + 1) * sizeof(JVal *));
            a->items[a->n++] = v;
            pws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == ']') { p->i++; }
            break;
        }
        return a;
    }
    if (c == '"') { JVal *v = jnew(JSTR); v->str = pstr(p); return v; }
    if (!strncmp(p->s + p->i, "true", 4)) { p->i += 4; JVal *v = jnew(JBOOL); v->b = 1; return v; }
    if (!strncmp(p->s + p->i, "false", 5)) { p->i += 5; return jnew(JBOOL); }
    if (!strncmp(p->s + p->i, "null", 4)) { p->i += 4; return jnew(JNULL); }
    size_t st = p->i;
    while (p->i < p->n && strchr("-+0123456789.eE", p->s[p->i]) && p->s[p->i] != 0) p->i++;
    JVal *v = jnew(JNUM);
    size_t l = p->i - st;
    v->raw = malloc(l + 1);
    memcpy(v->raw, p->s + st, l); v->raw[l] = 0;
    v->num = strtoll(v->raw, 0, 10);
    return v;
}
static JVal *jget(JVal *o, const char *k) {
    if (!o || o->t != JOBJ || !k) return NULL;
    for (int i = 0; i < o->n; i++)
        if (!strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}
static void jesc(SB *b, const char *s) {
    sbputc(b, '"');
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        switch (c) {
            case '"': sbputs(b, "\\\""); break;
            case '\\': sbputs(b, "\\\\"); break;
            case '\b': sbputs(b, "\\b"); break;
            case '\f': sbputs(b, "\\f"); break;
            case '\n': sbputs(b, "\\n"); break;
            case '\r': sbputs(b, "\\r"); break;
            case '\t': sbputs(b, "\\t"); break;
            default:
                if (c < 0x20) sbprintf(b, "\\u%04x", c);
                else sbputc(b, (char)c);
        }
    }
    sbputc(b, '"');
}
static void jser(SB *b, JVal *v) {
    switch (v->t) {
        case JNULL: sbputs(b, "null"); break;
        case JBOOL: sbputs(b, v->b ? "true" : "false"); break;
        case JNUM: sbputs(b, v->raw); break;
        case JSTR: jesc(b, v->str); break;
        case JARR:
            sbputc(b, '[');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jser(b, v->items[i]); }
            sbputc(b, ']');
            break;
        case JOBJ:
            sbputc(b, '{');
            for (int i = 0; i < v->n; i++) {
                if (i) sbputc(b, ',');
                jesc(b, v->keys[i]); sbputc(b, ':'); jser(b, v->items[i]);
            }
            sbputc(b, '}');
            break;
    }
}

/* ---------- file reading ---------- */
static char *readfile(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *d = malloc((size_t)n + 1);
    if (n > 0) {
        size_t got = fread(d, 1, (size_t)n, f);
        d[got] = 0;
    } else d[0] = 0;
    fclose(f);
    return d;
}

/* ---------- CSV ---------- */
typedef struct { char **f; int n; } Row;
static Row *rows = NULL;
static int nrows = 0;
static void parse_csv(const char *path) {
    char *s = readfile(path);
    size_t i = 0;
    if ((unsigned char)s[0] == 0xEF && (unsigned char)s[1] == 0xBB && (unsigned char)s[2] == 0xBF) i = 3;
    while (s[i]) {
        Row r = {0};
        while (1) {
            SB f = {0};
            if (s[i] == '"') {
                i++;
                while (s[i]) {
                    if (s[i] == '"') {
                        if (s[i + 1] == '"') { sbputc(&f, '"'); i += 2; }
                        else { i++; break; }
                    } else { sbputc(&f, s[i]); i++; }
                }
            } else {
                while (s[i] && s[i] != ',' && !(s[i] == '\r' && s[i + 1] == '\n')) { sbputc(&f, s[i]); i++; }
            }
            r.f = realloc(r.f, (size_t)(r.n + 1) * sizeof(char *));
            r.f[r.n++] = f.d ? f.d : strdup("");
            if (s[i] == ',') { i++; continue; }
            if (s[i] == '\r' && s[i + 1] == '\n') i += 2;
            break;
        }
        rows = realloc(rows, (size_t)(nrows + 1) * sizeof(Row));
        rows[nrows++] = r;
    }
}

/* ---------- rates ---------- */
typedef struct { char *code; long long r; } Rate;
static Rate *ratev = NULL;
static int nratev = 0;
static long long rateof(const char *c) {
    for (int i = 0; i < nratev; i++)
        if (!strcmp(ratev[i].code, c)) return ratev[i].r;
    return 0;
}

/* ---------- HTTP ---------- */
static int tcp_connect(const char *host, const char *port) {
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, port, &hints, &res) != 0) return -1;
    int fd = -1;
    for (struct addrinfo *a = res; a; a = a->ai_next) {
        fd = socket(a->ai_family, a->ai_socktype, 0);
        if (fd < 0) continue;
        if (connect(fd, a->ai_addr, a->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    return fd;
}
static char *http_post(const char *url, const char *key, const char *body, int *status) {
    const char *p = url;
    if (!strncmp(p, "http://", 7)) p += 7;
    const char *slash = strchr(p, '/');
    size_t hl = slash ? (size_t)(slash - p) : strlen(p);
    const char *path = slash ? slash : "/";
    char *hostfull = malloc(hl + 1);
    memcpy(hostfull, p, hl); hostfull[hl] = 0;
    char hostonly[256];
    snprintf(hostonly, sizeof hostonly, "%s", hostfull);
    char port[16] = "80";
    char *colon = strchr(hostonly, ':');
    if (colon) { *colon = 0; snprintf(port, sizeof port, "%s", colon + 1); }

    SB req = {0};
    sbprintf(&req, "POST %s/chat/completions HTTP/1.1\r\nHost: %s\r\nAuthorization: Bearer %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",
             path, hostfull, key, strlen(body));
    sbputs(&req, body);

    *status = 0;
    int fd = tcp_connect(hostonly, port);
    if (fd < 0) { *status = -1; return strdup("{\"error\":{\"message\":\"connection failed\"}}"); }
    size_t off = 0;
    while (off < req.n) {
        ssize_t k = send(fd, req.d + off, req.n - off, 0);
        if (k <= 0) break;
        off += (size_t)k;
    }
    SB resp = {0};
    char buf[65536];
    ssize_t k;
    while ((k = recv(fd, buf, sizeof buf, 0)) > 0) sbputn(&resp, buf, (size_t)k);
    close(fd);

    if (resp.d == NULL) { *status = -1; return strdup("{\"error\":{\"message\":\"empty response\"}}"); }
    int code = 0;
    if (resp.n >= 12 && !strncmp(resp.d, "HTTP/", 5)) code = atoi(resp.d + 9);
    char *sep = strstr(resp.d, "\r\n\r\n");
    char *b = sep ? sep + 4 : resp.d;
    *status = code;
    return strdup(b);
}

/* ---------- tools ---------- */
static void tool_result(SB *res, const char *name, JVal *args) {
    if (!strcmp(name, "inventory_lookup")) {
        JVal *skuV = jget(args, "sku");
        const char *sku = (skuV && skuV->t == JSTR) ? skuV->str : "";
        Row *found = NULL;
        for (int i = 0; i < nrows; i++)
            if (rows[i].n > 0 && !strcmp(rows[i].f[0], sku)) { found = &rows[i]; break; }
        if (found && found->n >= 5) {
            sbputs(res, "{\"sku\":"); jesc(res, found->f[0]);
            sbputs(res, ",\"name\":"); jesc(res, found->f[1]);
            sbprintf(res, ",\"price_cents\":%lld,\"currency\":", strtoll(found->f[2], 0, 10));
            jesc(res, found->f[3]);
            sbprintf(res, ",\"stock\":%lld}", strtoll(found->f[4], 0, 10));
        } else {
            SB e = {0};
            sbprintf(&e, "unknown sku: %s", sku);
            sbputs(res, "{\"error\":"); jesc(res, e.d ? e.d : ""); sbputc(res, '}');
        }
    } else if (!strcmp(name, "convert_currency")) {
        JVal *aV = jget(args, "amount_cents");
        JVal *fV = jget(args, "from");
        JVal *tV = jget(args, "to");
        long long amount = aV ? aV->num : 0;
        const char *from = (fV && fV->t == JSTR) ? fV->str : "";
        const char *to = (tV && tV->t == JSTR) ? tV->str : "";
        long long rf = rateof(from), rt = rateof(to);
        __int128 num = 2 * (__int128)amount * rt + rf;
        __int128 den = 2 * (__int128)rf;
        long long conv = (long long)(num / den);
        sbprintf(res, "{\"amount_cents\":%lld,\"currency\":", conv);
        jesc(res, to);
        sbputc(res, '}');
    } else {
        SB e = {0};
        sbprintf(&e, "unknown tool: %s", name);
        sbputs(res, "{\"error\":"); jesc(res, e.d); sbputc(res, '}');
    }
}

/* ---------- main ---------- */
int main(int argc, char **argv) {
    if (argc < 3) return 1;
    const char *dir = argv[1], *base = argv[2];
    char path[1024];

    snprintf(path, sizeof path, "%s/task.json", dir);
    char *tj = readfile(path);
    P tp = {tj, strlen(tj)};
    JVal *task = jparse(&tp);
    const char *api_key = jget(task, "api_key")->str;
    const char *model = jget(task, "model")->str;
    JVal *system = jget(task, "system");
    JVal *user = jget(task, "user");
    JVal *tools = jget(task, "tools");

    snprintf(path, sizeof path, "%s/rates.json", dir);
    char *rj = readfile(path);
    P rp0 = {rj, strlen(rj)};
    JVal *ratesj = jparse(&rp0);
    JVal *rs = jget(ratesj, "rates");
    ratev = malloc((size_t)rs->n * sizeof(Rate));
    for (int i = 0; i < rs->n; i++) {
        ratev[i].code = rs->keys[i];
        ratev[i].r = rs->items[i]->num;
        nratev++;
    }

    snprintf(path, sizeof path, "%s/inventory.csv", dir);
    parse_csv(path);

    char **msgs = NULL;
    int nmsgs = 0, cap = 0;
#define ADDMSG(s) do { if (nmsgs == cap) { cap = cap ? cap * 2 : 8; msgs = realloc(msgs, (size_t)cap * sizeof(char *)); } msgs[nmsgs++] = (s); } while (0)

    { SB m = {0}; sbputs(&m, "{\"role\":\"system\",\"content\":"); jesc(&m, system->str); sbputs(&m, "}"); ADDMSG(m.d); }
    { SB m = {0}; sbputs(&m, "{\"role\":\"user\",\"content\":"); jesc(&m, user->str); sbputs(&m, "}"); ADDMSG(m.d); }

    long long pt = 0, ct = 0, tt = 0;
    int nreq = 0;

    while (1) {
        SB body = {0};
        sbputs(&body, "{\"model\":");
        jesc(&body, model);
        sbputs(&body, ",\"messages\":[");
        for (int i = 0; i < nmsgs; i++) { if (i) sbputc(&body, ','); sbputs(&body, msgs[i]); }
        sbputs(&body, "],\"tools\":");
        jser(&body, tools);
        sbputs(&body, ",\"tool_choice\":\"auto\"}");

        nreq++;
        int st;
        char *resp = http_post(base, api_key, body.d, &st);
        if (st != 200) {
            P ep = {resp, strlen(resp)};
            JVal *ej = jparse(&ep);
            const char *msg = "";
            JVal *e = jget(ej, "error");
            if (e) { JVal *em = jget(e, "message"); if (em && em->str) msg = em->str; }
            printf("ERROR %d %s\n", st, msg);
            return 0;
        }

        P rp = {resp, strlen(resp)};
        JVal *r = jparse(&rp);

        JVal *u = jget(r, "usage");
        if (u) {
            JVal *x;
            if ((x = jget(u, "prompt_tokens"))) pt += x->num;
            if ((x = jget(u, "completion_tokens"))) ct += x->num;
            if ((x = jget(u, "total_tokens"))) tt += x->num;
        }

        JVal *ch = jget(r, "choices");
        if (!ch || ch->t != JARR || ch->n < 1) { printf("ERROR 0 bad response\n"); return 0; }
        JVal *choice = ch->items[0];
        JVal *msg = jget(choice, "message");
        JVal *frV = jget(choice, "finish_reason");
        const char *fr = (frV && frV->t == JSTR) ? frV->str : "";

        if (!strcmp(fr, "tool_calls")) {
            JVal *content = jget(msg, "content");
            if (content && content->t == JSTR) printf("SAY %s\n", content->str);

            JVal *tcs = jget(msg, "tool_calls");
            int ntc = (tcs && tcs->t == JARR) ? tcs->n : 0;

            SB am = {0};
            sbputs(&am, "{\"role\":\"assistant\",\"content\":");
            if (content && content->t == JSTR) jesc(&am, content->str);
            else sbputs(&am, "null");
            sbputs(&am, ",\"tool_calls\":[");
            for (int i = 0; i < ntc; i++) {
                JVal *tc = tcs->items[i];
                JVal *fn = jget(tc, "function");
                if (i) sbputc(&am, ',');
                sbputs(&am, "{\"id\":");
                jesc(&am, jget(tc, "id")->str);
                sbputs(&am, ",\"type\":\"function\",\"function\":{\"name\":");
                jesc(&am, jget(fn, "name")->str);
                sbputs(&am, ",\"arguments\":");
                jesc(&am, jget(fn, "arguments")->str);
                sbputs(&am, "}}");
            }
            sbputs(&am, "]}");
            ADDMSG(am.d);

            for (int i = 0; i < ntc; i++)
                printf("CALL %s %s\n", jget(tcs->items[i], "id")->str, jget(jget(tcs->items[i], "function"), "name")->str);

            for (int i = 0; i < ntc; i++) {
                JVal *tc = tcs->items[i];
                const char *id = jget(tc, "id")->str;
                const char *name = jget(jget(tc, "function"), "name")->str;
                const char *argsstr = jget(jget(tc, "function"), "arguments")->str;
                P ap = {argsstr, strlen(argsstr)};
                JVal *args = jparse(&ap);
                SB res = {0};
                tool_result(&res, name, args);
                SB tm = {0};
                sbputs(&tm, "{\"role\":\"tool\",\"tool_call_id\":");
                jesc(&tm, id);
                sbputs(&tm, ",\"content\":");
                jesc(&tm, res.d);
                sbputs(&tm, "}");
                ADDMSG(tm.d);
                printf("RESULT %s %s\n", id, res.d);
            }
        } else {
            JVal *content = jget(msg, "content");
            printf("FINAL %s\n", content && content->t == JSTR ? content->str : "");
            break;
        }
    }

    printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n", pt, ct, tt, nreq);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>

/* ---------- string builder ---------- */
typedef struct { char *s; size_t len, cap; } SB;
static void sbneed(SB *b, size_t n) {
    if (b->len + n + 1 > b->cap) {
        size_t nc = b->cap ? b->cap : 64;
        while (b->len + n + 1 > nc) nc *= 2;
        b->s = realloc(b->s, nc);
        b->cap = nc;
    }
}
static void sbputc(SB *b, char c) { sbneed(b, 1); b->s[b->len++] = c; b->s[b->len] = 0; }
static void sbputs(SB *b, const char *s) { size_t n = strlen(s); sbneed(b, n); memcpy(b->s + b->len, s, n); b->len += n; b->s[b->len] = 0; }
static void sbappend(SB *b, const char *s, size_t n) { sbneed(b, n); memcpy(b->s + b->len, s, n); b->len += n; b->s[b->len] = 0; }
static const char *sbstr(SB *b) { return b->s ? b->s : ""; }

static void utf8_enc(SB *b, unsigned cp) {
    if (cp < 0x80) sbputc(b, (char)cp);
    else if (cp < 0x800) { sbputc(b, (char)(0xC0 | (cp >> 6))); sbputc(b, (char)(0x80 | (cp & 63))); }
    else if (cp < 0x10000) { sbputc(b, (char)(0xE0 | (cp >> 12))); sbputc(b, (char)(0x80 | ((cp >> 6) & 63))); sbputc(b, (char)(0x80 | (cp & 63))); }
    else { sbputc(b, (char)(0xF0 | (cp >> 18))); sbputc(b, (char)(0x80 | ((cp >> 12) & 63))); sbputc(b, (char)(0x80 | ((cp >> 6) & 63))); sbputc(b, (char)(0x80 | (cp & 63))); }
}

/* ---------- JSON ---------- */
typedef enum { JNUL, JBOOL, JNUM, JSTR, JARR, JOBJ } JT;
typedef struct JV JV;
struct JV { JT t; char *raw; char *str; JV **items; char **keys; int n; size_t rs, re; };
static JV *jnew(JT t) { JV *v = calloc(1, sizeof(JV)); v->t = t; return v; }
typedef struct { const char *s; size_t i, n; } JP;
static void jskipws(JP *p) { while (p->i < p->n && isspace((unsigned char)p->s[p->i])) p->i++; }

static char *jparsestr(JP *p) {
    SB b = {0};
    if (p->i >= p->n || p->s[p->i] != '"') return NULL;
    p->i++;
    while (p->i < p->n) {
        unsigned char c = (unsigned char)p->s[p->i];
        if (c == '"') { p->i++; if (!b.s) return strdup(""); return b.s; }
        if (c == '\\') {
            p->i++;
            if (p->i >= p->n) break;
            char e = p->s[p->i++];
            switch (e) {
                case '"': sbputc(&b, '"'); break;
                case '\\': sbputc(&b, '\\'); break;
                case '/': sbputc(&b, '/'); break;
                case 'b': sbputc(&b, '\b'); break;
                case 'f': sbputc(&b, '\f'); break;
                case 'n': sbputc(&b, '\n'); break;
                case 'r': sbputc(&b, '\r'); break;
                case 't': sbputc(&b, '\t'); break;
                case 'u': {
                    unsigned cp = 0;
                    for (int k = 0; k < 4 && p->i < p->n; k++) {
                        char h = p->s[p->i++];
                        int d = h <= '9' ? h - '0' : (h | 32) - 'a' + 10;
                        cp = cp * 16 + (unsigned)d;
                    }
                    if (cp >= 0xD800 && cp <= 0xDBFF && p->i + 1 < p->n && p->s[p->i] == '\\' && p->s[p->i + 1] == 'u') {
                        size_t save = p->i; p->i += 2;
                        unsigned lo = 0; int ok = 1;
                        for (int k = 0; k < 4; k++) {
                            if (p->i >= p->n) { ok = 0; break; }
                            char h = p->s[p->i++];
                            if (!isxdigit((unsigned char)h)) { ok = 0; break; }
                            int d = h <= '9' ? h - '0' : (h | 32) - 'a' + 10;
                            lo = lo * 16 + (unsigned)d;
                        }
                        if (ok && lo >= 0xDC00 && lo <= 0xDFFF) cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        else p->i = save;
                    }
                    utf8_enc(&b, cp);
                } break;
                default: break;
            }
        } else { sbputc(&b, (char)c); p->i++; }
    }
    return b.s ? b.s : strdup("");
}

static JV *jparsev(JP *p) {
    jskipws(p);
    size_t start = p->i;
    if (p->i >= p->n) return NULL;
    char c = p->s[p->i];
    JV *v = NULL;
    if (c == '{') {
        p->i++; v = jnew(JOBJ); int cap = 0;
        jskipws(p);
        if (p->i < p->n && p->s[p->i] == '}') p->i++;
        else while (p->i < p->n) {
            jskipws(p);
            char *k = jparsestr(p);
            jskipws(p); p->i++;
            JV *val = jparsev(p);
            if (v->n == cap) { cap = cap ? cap * 2 : 4; v->keys = realloc(v->keys, cap * sizeof(char *)); v->items = realloc(v->items, cap * sizeof(JV *)); }
            v->keys[v->n] = k; v->items[v->n] = val; v->n++;
            jskipws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == '}') { p->i++; break; }
        }
    } else if (c == '[') {
        p->i++; v = jnew(JARR); int cap = 0;
        jskipws(p);
        if (p->i < p->n && p->s[p->i] == ']') p->i++;
        else while (p->i < p->n) {
            JV *val = jparsev(p);
            if (v->n == cap) { cap = cap ? cap * 2 : 4; v->items = realloc(v->items, cap * sizeof(JV *)); }
            v->items[v->n++] = val;
            jskipws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == ']') { p->i++; break; }
        }
    } else if (c == '"') { v = jnew(JSTR); v->str = jparsestr(p); }
    else if (p->n - p->i >= 4 && !strncmp(p->s + p->i, "true", 4)) { p->i += 4; v = jnew(JBOOL); v->raw = "true"; }
    else if (p->n - p->i >= 5 && !strncmp(p->s + p->i, "false", 5)) { p->i += 5; v = jnew(JBOOL); v->raw = "false"; }
    else if (p->n - p->i >= 4 && !strncmp(p->s + p->i, "null", 4)) { p->i += 4; v = jnew(JNUL); }
    else {
        size_t st = p->i;
        if (p->i < p->n && p->s[p->i] == '-') p->i++;
        while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++;
        if (p->i < p->n && p->s[p->i] == '.') { p->i++; while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++; }
        if (p->i < p->n && (p->s[p->i] == 'e' || p->s[p->i] == 'E')) { p->i++; if (p->i < p->n && (p->s[p->i] == '+' || p->s[p->i] == '-')) p->i++; while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++; }
        v = jnew(JNUM); v->raw = strndup(p->s + st, p->i - st);
    }
    if (v) { v->rs = start; v->re = p->i; }
    return v;
}

static void jstr(SB *b, const char *s) {
    sbputc(b, '"');
    for (; s && *s; s++) {
        unsigned char c = (unsigned char)*s;
        switch (c) {
            case '"': sbputs(b, "\\\""); break;
            case '\\': sbputs(b, "\\\\"); break;
            case '\b': sbputs(b, "\\b"); break;
            case '\f': sbputs(b, "\\f"); break;
            case '\n': sbputs(b, "\\n"); break;
            case '\r': sbputs(b, "\\r"); break;
            case '\t': sbputs(b, "\\t"); break;
            default:
                if (c < 0x20) { char t[8]; snprintf(t, sizeof t, "\\u%04x", c); sbputs(b, t); }
                else sbputc(b, (char)c);
        }
    }
    sbputc(b, '"');
}
static void jdump(SB *b, JV *v) {
    if (!v) { sbputs(b, "null"); return; }
    switch (v->t) {
        case JNUL: sbputs(b, "null"); break;
        case JBOOL: sbputs(b, v->raw ? v->raw : "false"); break;
        case JNUM: sbputs(b, v->raw ? v->raw : "0"); break;
        case JSTR: jstr(b, v->str); break;
        case JARR:
            sbputc(b, '[');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jdump(b, v->items[i]); }
            sbputc(b, ']');
            break;
        case JOBJ:
            sbputc(b, '{');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jstr(b, v->keys[i]); sbputc(b, ':'); jdump(b, v->items[i]); }
            sbputc(b, '}');
            break;
    }
}
static JV *jget(JV *o, const char *k) {
    if (!o || o->t != JOBJ) return NULL;
    for (int i = 0; i < o->n; i++) if (!strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}
static const char *jstrget(JV *o, const char *k) { JV *v = jget(o, k); return v && v->t == JSTR ? v->str : NULL; }
static long long jnum(JV *v) { return v && v->t == JNUM ? strtoll(v->raw, NULL, 10) : 0; }

/* ---------- output escaping ---------- */
static void print_esc(const char *s) {
    if (!s) return;
    for (; *s; s++) {
        switch (*s) {
            case '\\': fputs("\\\\", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default: putchar(*s);
        }
    }
}

/* ---------- reply model ---------- */
typedef struct { char *type; SB thinking, signature, text, json; char *id, *name; } Block;
typedef struct { Block *blocks; int nb, cap; char *stop_reason; long long in, out, cache; } Reply;
static void reply_block(Reply *r, int idx) {
    if (idx >= r->cap) {
        int nc = idx + 8;
        r->blocks = realloc(r->blocks, nc * sizeof(Block));
        memset(r->blocks + r->cap, 0, (nc - r->cap) * sizeof(Block));
        r->cap = nc;
    }
    while (r->nb <= idx) { memset(&r->blocks[r->nb], 0, sizeof(Block)); r->nb++; }
}

/* ---------- HTTP ---------- */
static char *g_auth, *g_path, *g_host;
static int g_port;
static int g_fd = -1;
static unsigned char g_buf[8192];
static size_t g_pos, g_len;

static void parse_base(const char *url) {
    const char *p = strstr(url, "://");
    if (!p) exit(1);
    p += 3;
    const char *slash = strchr(p, '/');
    size_t alen = slash ? (size_t)(slash - p) : strlen(p);
    g_auth = strndup(p, alen);
    g_path = slash ? strdup(slash) : strdup("");
    const char *colon = memchr(p, ':', alen);
    if (colon) { g_host = strndup(p, (size_t)(colon - p)); g_port = atoi(colon + 1); }
    else { g_host = strndup(p, alen); g_port = 80; }
}
static int conn(void) {
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC; hints.ai_socktype = SOCK_STREAM;
    char ps[16]; snprintf(ps, sizeof ps, "%d", g_port);
    if (getaddrinfo(g_host, ps, &hints, &res) || !res) exit(1);
    int fd = -1;
    for (struct addrinfo *a = res; a; a = a->ai_next) {
        fd = socket(a->ai_family, a->ai_socktype, 0);
        if (fd < 0) continue;
        if (connect(fd, a->ai_addr, a->ai_addrlen) == 0) break;
        close(fd); fd = -1;
    }
    freeaddrinfo(res);
    if (fd < 0) exit(1);
    return fd;
}
static int rdbyte(void) {
    if (g_pos == g_len) {
        g_len = recv(g_fd, g_buf, sizeof g_buf, 0);
        g_pos = 0;
        if (g_len <= 0) return -1;
    }
    return g_buf[g_pos++];
}
static SB readline(void) {
    SB b = {0};
    int c = rdbyte();
    if (c < 0) return b;
    while (c >= 0 && c != '\n') { sbputc(&b, (char)c); c = rdbyte(); }
    if (b.len > 0 && b.s[b.len - 1] == '\r') { b.len--; b.s[b.len] = 0; }
    return b;
}
static SB readn(long long n) {
    SB b = {0};
    while (n-- > 0) { int c = rdbyte(); if (c < 0) break; sbputc(&b, (char)c); }
    return b;
}
static SB readchunked(void) {
    SB body = {0};
    for (;;) {
        SB l = readline();
        if (!l.s) break;
        long sz = strtol(l.s, NULL, 16);
        if (sz == 0) {
            for (;;) { SB t = readline(); if (!t.s || t.len == 0) break; }
            break;
        }
        SB ch = readn(sz);
        sbappend(&body, ch.s ? ch.s : "", ch.len);
        readn(2);
    }
    return body;
}
static SB http_post(SB body, int *status_out) {
    int fd = conn();
    g_fd = fd; g_pos = g_len = 0;
    SB req = {0};
    sbputs(&req, "POST "); sbputs(&req, g_path); sbputs(&req, "/v1/messages HTTP/1.1\r\nHost: ");
    sbputs(&req, g_auth);
    char cl[32]; snprintf(cl, sizeof cl, "%zu", body.len);
    sbputs(&req, "\r\nContent-Length: "); sbputs(&req, cl);
    sbputs(&req, "\r\nx-api-key: "); sbputs(&req, g_apikey_g);
    sbputs(&req, "\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n");
    size_t off = 0;
    while (off < req.len) {
        ssize_t w = send(fd, req.s + off, req.len - off, 0);
        if (w <= 0) break;
        off += (size_t)w;
    }
    SB l = readline();
    int status = 0;
    if (l.s) { char *q = strchr(l.s, ' '); if (q) status = atoi(q + 1); }
    long long clen = -1; int chunked = 0;
    for (;;) {
        SB h = readline();
        if (!h.s || h.len == 0) break;
        char *lo = strdup(h.s);
        for (char *x = lo; *x; x++) *x = (char)tolower((unsigned char)*x);
        if (!strncmp(lo, "content-length:", 15)) clen = atoll(lo + 15);
        if (!strncmp(lo, "transfer-encoding:", 18) && strstr(lo, "chunked")) chunked = 1;
        free(lo);
    }
    SB resp = {0};
    if (chunked) resp = readchunked();
    else if (clen >= 0) resp = readn(clen);
    else { int c; while ((c = rdbyte()) >= 0) sbputc(&resp, (char)c); }
    close(fd);
    *status_out = status;
    return resp;
}

/* ---------- SSE ---------- */
static void handle_event(const char *name, SB *data, Reply *r) {
    if (!data || data->len == 0) return;
    JP jp = { data->s, 0, data->len };
    JV *o = jparsev(&jp);
    if (!o) return;
    const char *ty = jstrget(o, "type");
    if (!ty) ty = "";
    const char *ev = (name && *name) ? name : ty;
    if (!strcmp(ev, "message_start")) {
        JV *msg = jget(o, "message");
        if (msg) {
            JV *u = jget(msg, "usage");
            if (u) { r->in += jnum(jget(u, "input_tokens")); r->cache += jnum(jget(u, "cache_read_input_tokens")); }
        }
    } else if (!strcmp(ev, "content_block_start")) {
        JV *ix = jget(o, "index"), *cb = jget(o, "content_block");
        if (ix && cb) {
            int idx = (int)jnum(ix);
            reply_block(r, idx);
            Block *b = &r->blocks[idx];
            const char *t = jstrget(cb, "type");
            b->type = strdup(t ? t : "");
            if (!strcmp(b->type, "tool_use")) {
                const char *id = jstrget(cb, "id"), *nm = jstrget(cb, "name");
                b->id = strdup(id ? id : "");
                b->name = strdup(nm ? nm : "");
            }
        }
    } else if (!strcmp(ev, "content_block_delta")) {
        int idx = (int)jnum(jget(o, "index"));
        if (idx < r->nb) {
            Block *b = &r->blocks[idx];
            JV *d = jget(o, "delta");
            if (d) {
                const char *dt = jstrget(d, "type"), *txt;
                if (dt && !strcmp(dt, "thinking_delta")) { txt = jstrget(d, "thinking"); sbputs(&b->thinking, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "signature_delta")) { txt = jstrget(d, "signature"); sbputs(&b->signature, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "text_delta")) { txt = jstrget(d, "text"); sbputs(&b->text, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "input_json_delta")) { txt = jstrget(d, "partial_json"); sbputs(&b->json, txt ? txt : ""); }
            }
        }
    } else if (!strcmp(ev, "message_delta")) {
        JV *d = jget(o, "delta");
        if (d) { const char *sr = jstrget(d, "stop_reason"); if (sr) { free(r->stop_reason); r->stop_reason = strdup(sr); } }
        JV *u = jget(o, "usage");
        if (u) r->out += jnum(jget(u, "output_tokens"));
    }
}
static void parse_sse(SB *body, Reply *r) {
    char *p = body->s;
    if (!p) return;
    size_t n = body->len, i = 0;
    SB evname = {0}, data = {0};
    while (i < n) {
        size_t j = i;
        while (j < n && p[j] != '\n') j++;
        const char *line = p + i;
        size_t ll = j - i;
        if (ll > 0 && line[ll - 1] == '\r') ll--;
        i = (j < n) ? j + 1 : n;
        if (ll == 0) {
            handle_event(evname.s, &data, r);
            free(evname.s); evname = (SB){0};
            free(data.s); data = (SB){0};
            continue;
        }
        if (line[0] == ':') continue;
        if (ll >= 6 && !strncmp(line, "event:", 6)) {
            const char *v = line + 6; if (*v == ' ') v++;
            free(evname.s); evname = (SB){0};
            sbappend(&evname, v, line + ll - v);
        } else if (ll >= 5 && !strncmp(line, "data:", 5)) {
            const char *v = line + 5; if (*v == ' ') v++;
            if (data.len) sbputc(&data, '\n');
            sbappend(&data, v, line + ll - v);
        }
    }
    handle_event(evname.s, &data, r);
}

static void print_blocks(Reply *r) {
    for (int i = 0; i < r->nb; i++) {
        Block *b = &r->blocks[i];
        const char *bt = b->type ? b->type : "";
        if (!strcmp(bt, "thinking")) {
            printf("thinking "); print_esc(sbstr(&b->thinking));
            printf("\nsignature "); print_esc(sbstr(&b->signature)); printf("\n");
        } else if (!strcmp(bt, "text")) {
            printf("text "); print_esc(sbstr(&b->text)); printf("\n");
        } else if (!strcmp(bt, "tool_use")) {
            printf("tool_use %s %s ", b->id ? b->id : "", b->name ? b->name : "");
            print_esc(sbstr(&b->json)); printf("\n");
        }
    }
    printf("stop_reason %s\n", r->stop_reason ? r->stop_reason : "");
}

/* ---------- tools ---------- */
static void utf8_next(const char *s, size_t n, size_t *i, unsigned *cp) {
    unsigned char c = (unsigned char)s[*i];
    if (c < 0x80) { *cp = c; (*i)++; return; }
    int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
    if (*i + (size_t)len > n) len = 1;
    if (len == 1) { *cp = c; (*i)++; return; }
    unsigned v = c & (unsigned)(0x7F >> len);
    for (int k = 1; k < len; k++) v = (v << 6) | ((unsigned char)s[*i + k] & 0x3F);
    *i += (size_t)len;
    *cp = v;
}
static char *tool_result(Block *b, int *iserr) {
    *iserr = 0;
    JP jp = { sbstr(&b->json), 0, b->json.len };
    JV *in = jparsev(&jp);
    if (!strcmp(b->name, "measure")) {
        const char *unit = jstrget(in, "unit");
        const char *text = jstrget(in, "text");
        if (!text) text = "";
        if (!unit) unit = "";
        if (!strcmp(unit, "code_points")) {
            size_t i = 0, c = 0, n = strlen(text); unsigned cp;
            while (i < n) { utf8_next(text, n, &i, &cp); c++; }
            char buf[32]; snprintf(buf, sizeof buf, "%zu", c);
            return strdup(buf);
        } else if (!strcmp(unit, "utf8_bytes")) {
            char buf[32]; snprintf(buf, sizeof buf, "%zu", strlen(text));
            return strdup(buf);
        } else if (!strcmp(unit, "utf16_units")) {
            size_t i = 0, n = strlen(text); unsigned long long c = 0; unsigned cp;
            while (i < n) { utf8_next(text, n, &i, &cp); c += cp > 0xFFFF ? 2 : 1; }
            char buf[32]; snprintf(buf, sizeof buf, "%llu", c);
            return strdup(buf);
        } else {
            *iserr = 1;
            char *r = malloc(strlen(unit) + 32);
            sprintf(r, "unsupported unit: %s", unit);
            return r;
        }
    } else if (!strcmp(b->name, "reverse")) {
        const char *text = jstrget(in, "text");
        if (!text) text = "";
        size_t n = strlen(text);
        unsigned *cps = malloc((n + 1) * sizeof(unsigned));
        size_t i = 0, c = 0; unsigned cp;
        while (i < n) { utf8_next(text, n, &i, &cp); cps[c++] = cp; }
        SB o = {0};
        for (size_t k = c; k > 0; k--) utf8_enc(&o, cps[k - 1]);
        return o.s ? o.s : strdup("");
    } else {
        *iserr = 1;
        char *r = malloc(strlen(b->name) + 32);
        sprintf(r, "unknown tool: %s", b->name);
        return r;
    }
}

/* ---------- globals for config ---------- */
static char *g_apikey_g, *g_model, *g_maxraw, *g_budgetraw;
static char *g_toolsraw; static size_t g_toolslen;
static JV *g_system, *g_prompt;

static SB build_body(SB messages) {
    SB b = {0};
    sbputs(&b, "{\"model\":"); jstr(&b, g_model);
    sbputs(&b, ",\"max_tokens\":"); sbputs(&b, g_maxraw);
    sbputs(&b, ",\"stream\":true");
    sbputs(&b, ",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":"); sbputs(&b, g_budgetraw); sbputs(&b, "}");
    sbputs(&b, ",\"system\":"); jdump(&b, g_system);
    sbputs(&b, ",\"tools\":"); sbappend(&b, g_toolsraw, g_toolslen);
    sbputs(&b, ",\"messages\":"); sbappend(&b, messages.s ? messages.s : "", messages.len);
    sbputs(&b, "}");
    return b;
}
static void print_error(SB body, int st) {
    JP jp = { body.s ? body.s : "", 0, body.len };
    JV *o = jparsev(&jp);
    const char *et = "", *em = "";
    if (o) {
        JV *e = jget(o, "error");
        if (e) {
            const char *t = jstrget(e, "type"), *m = jstrget(e, "message");
            if (t) et = t;
            if (m) em = m;
        }
    }
    printf("ERROR %d %s: %s\n", st, et, em);
}

int main(int argc, char **argv) {
    if (argc != 3) return 1;
    char *cfgpath = malloc(strlen(argv[1]) + 32);
    sprintf(cfgpath, "%s/request.json", argv[1]);
    FILE *f = fopen(cfgpath, "rb");
    if (!f) return 1;
    SB cfgf = {0};
    int ch;
    while ((ch = fgetc(f)) != EOF) sbputc(&cfgf, (char)ch);
    fclose(f);
    JP jp = { cfgf.s, 0, cfgf.len };
    JV *cfg = jparsev(&jp);
    if (!cfg) return 1;
    g_apikey_g = strdup(jstrget(cfg, "api_key") ? jstrget(cfg, "api_key") : "");
    g_model = strdup(jstrget(cfg, "model") ? jstrget(cfg, "model") : "");
    JV *mt = jget(cfg, "max_tokens");
    g_maxraw = strdup(mt && mt->raw ? mt->raw : "0");
    JV *tb = jget(cfg, "thinking_budget");
    g_budgetraw = strdup(tb && tb->raw ? tb->raw : "0");
    g_system = jget(cfg, "system");
    g_prompt = jget(cfg, "prompt");
    JV *tools = jget(cfg, "tools");
    if (tools) { g_toolsraw = cfgf.s + tools->rs; g_toolslen = tools->re - tools->rs; }
    else { g_toolsraw = "[]"; g_toolslen = 2; }
    parse_base(argv[2]);

    /* request 1 */
    printf("request 1\n");
    SB m1 = {0};
    sbputs(&m1, "[{\"role\":\"user\",\"content\":");
    jdump(&m1, g_prompt);
    sbputs(&m1, "}]");
    SB b1 = build_body(m1);
    int st;
    SB r1b = http_post(b1, &st);
    if (st != 200) { print_error(r1b, st); return 0; }
    Reply r1 = {0};
    parse_sse(&r1b, &r1);
    print_blocks(&r1);

    /* tools */
    typedef struct { char *id; char *result; int iserr; } ToolRes;
    ToolRes *trs = malloc((r1.nb + 1) * sizeof(ToolRes));
    int ntr = 0;
    for (int i = 0; i < r1.nb; i++) {
        Block *b = &r1.blocks[i];
        if (b->type && !strcmp(b->type, "tool_use")) {
            int iserr;
            char *res = tool_result(b, &iserr);
            trs[ntr].id = b->id ? b->id : (char *)"";
            trs[ntr].result = res;
            trs[ntr].iserr = iserr;
            ntr++;
            printf("%s %s ", iserr ? "error" : "result", b->id ? b->id : "");
            print_esc(res);
            printf("\n");
        }
    }

    /* request 2 */
    printf("request 2\n");
    SB m2 = {0};
    sbputs(&m2, "[{\"role\":\"user\",\"content\":");
    jdump(&m2, g_prompt);
    sbputs(&m2, "},{\"role\":\"assistant\",\"content\":[");
    for (int i = 0; i < r1.nb; i++) {
        Block *b = &r1.blocks[i];
        const char *bt = b->type ? b->type : "";
        if (i) sbputc(&m2, ',');
        if (!strcmp(bt, "thinking")) {
            sbputs(&m2, "{\"type\":\"thinking\",\"thinking\":");
            jstr(&m2, sbstr(&b->thinking));
            sbputs(&m2, ",\"signature\":");
            jstr(&m2, sbstr(&b->signature));
            sbputc(&m2, '}');
        } else if (!strcmp(bt, "text")) {
            sbputs(&m2, "{\"type\":\"text\",\"text\":");
            jstr(&m2, sbstr(&b->text));
            sbputc(&m2, '}');
        } else if (!strcmp(bt, "tool_use")) {
            JP p2 = { sbstr(&b->json), 0, b->json.len };
            JV *in = jparsev(&p2);
            sbputs(&m2, "{\"type\":\"tool_use\",\"id\":");
            jstr(&m2, b->id ? b->id : "");
            sbputs(&m2, ",\"name\":");
            jstr(&m2, b->name ? b->name : "");
            sbputs(&m2, ",\"input\":");
            jdump(&m2, in);
            sbputc(&m2, '}');
        }
    }
    sbputs(&m2, "]},{\"role\":\"user\",\"content\":[");
    for (int i = 0; i < ntr; i++) {
        if (i) sbputc(&m2, ',');
        sbputs(&m2, "{\"type\":\"tool_result\",\"tool_use_id\":");
        jstr(&m2, trs[i].id);
        sbputs(&m2, ",\"content\":");
        jstr(&m2, trs[i].result);
        if (trs[i].iserr) sbputs(&m2, ",\"is_error\":true");
        sbputc(&m2, '}');
    }
    sbputs(&m2, "]}]");
    SB b2 = build_body(m2);
    SB r2b = http_post(b2, &st);
    if (st != 200) { print_error(r2b, st); return 0; }
    Reply r2 = {0};
    parse_sse(&r2b, &r2);
    print_blocks(&r2);
    printf("usage input=%lld output=%lld cache_read=%lld\n",
           r1.in + r2.in, r1.out + r2.out, r1.cache + r2.cache);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>

/* ---------- string builder ---------- */
typedef struct { char *s; size_t len, cap; } SB;
static void sbneed(SB *b, size_t n) {
    if (b->len + n + 1 > b->cap) {
        size_t nc = b->cap ? b->cap : 64;
        while (b->len + n + 1 > nc) nc *= 2;
        b->s = realloc(b->s, nc);
        b->cap = nc;
    }
}
static void sbputc(SB *b, char c) { sbneed(b, 1); b->s[b->len++] = c; b->s[b->len] = 0; }
static void sbputs(SB *b, const char *s) { size_t n = strlen(s); sbneed(b, n); memcpy(b->s + b->len, s, n); b->len += n; b->s[b->len] = 0; }
static void sbappend(SB *b, const char *s, size_t n) { sbneed(b, n); memcpy(b->s + b->len, s, n); b->len += n; b->s[b->len] = 0; }
static const char *sbstr(SB *b) { return b->s ? b->s : ""; }

static void utf8_enc(SB *b, unsigned cp) {
    if (cp < 0x80) sbputc(b, (char)cp);
    else if (cp < 0x800) { sbputc(b, (char)(0xC0 | (cp >> 6))); sbputc(b, (char)(0x80 | (cp & 63))); }
    else if (cp < 0x10000) { sbputc(b, (char)(0xE0 | (cp >> 12))); sbputc(b, (char)(0x80 | ((cp >> 6) & 63))); sbputc(b, (char)(0x80 | (cp & 63))); }
    else { sbputc(b, (char)(0xF0 | (cp >> 18))); sbputc(b, (char)(0x80 | ((cp >> 12) & 63))); sbputc(b, (char)(0x80 | ((cp >> 6) & 63))); sbputc(b, (char)(0x80 | (cp & 63))); }
}

/* ---------- JSON ---------- */
typedef enum { JNUL, JBOOL, JNUM, JSTR, JARR, JOBJ } JT;
typedef struct JV JV;
struct JV { JT t; char *raw; char *str; JV **items; char **keys; int n; size_t rs, re; };
static JV *jnew(JT t) { JV *v = calloc(1, sizeof(JV)); v->t = t; return v; }
typedef struct { const char *s; size_t i, n; } JP;
static void jskipws(JP *p) { while (p->i < p->n && isspace((unsigned char)p->s[p->i])) p->i++; }

static char *jparsestr(JP *p) {
    SB b = {0};
    if (p->i >= p->n || p->s[p->i] != '"') return NULL;
    p->i++;
    while (p->i < p->n) {
        unsigned char c = (unsigned char)p->s[p->i];
        if (c == '"') { p->i++; if (!b.s) return strdup(""); return b.s; }
        if (c == '\\') {
            p->i++;
            if (p->i >= p->n) break;
            char e = p->s[p->i++];
            switch (e) {
                case '"': sbputc(&b, '"'); break;
                case '\\': sbputc(&b, '\\'); break;
                case '/': sbputc(&b, '/'); break;
                case 'b': sbputc(&b, '\b'); break;
                case 'f': sbputc(&b, '\f'); break;
                case 'n': sbputc(&b, '\n'); break;
                case 'r': sbputc(&b, '\r'); break;
                case 't': sbputc(&b, '\t'); break;
                case 'u': {
                    unsigned cp = 0;
                    for (int k = 0; k < 4 && p->i < p->n; k++) {
                        char h = p->s[p->i++];
                        int d = h <= '9' ? h - '0' : (h | 32) - 'a' + 10;
                        cp = cp * 16 + (unsigned)d;
                    }
                    if (cp >= 0xD800 && cp <= 0xDBFF && p->i + 1 < p->n && p->s[p->i] == '\\' && p->s[p->i + 1] == 'u') {
                        size_t save = p->i; p->i += 2;
                        unsigned lo = 0; int ok = 1;
                        for (int k = 0; k < 4; k++) {
                            if (p->i >= p->n) { ok = 0; break; }
                            char h = p->s[p->i++];
                            if (!isxdigit((unsigned char)h)) { ok = 0; break; }
                            int d = h <= '9' ? h - '0' : (h | 32) - 'a' + 10;
                            lo = lo * 16 + (unsigned)d;
                        }
                        if (ok && lo >= 0xDC00 && lo <= 0xDFFF) cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        else p->i = save;
                    }
                    utf8_enc(&b, cp);
                } break;
                default: break;
            }
        } else { sbputc(&b, (char)c); p->i++; }
    }
    return b.s ? b.s : strdup("");
}

static JV *jparsev(JP *p) {
    jskipws(p);
    size_t start = p->i;
    if (p->i >= p->n) return NULL;
    char c = p->s[p->i];
    JV *v = NULL;
    if (c == '{') {
        p->i++; v = jnew(JOBJ); int cap = 0;
        jskipws(p);
        if (p->i < p->n && p->s[p->i] == '}') p->i++;
        else while (p->i < p->n) {
            jskipws(p);
            char *k = jparsestr(p);
            jskipws(p); p->i++;
            JV *val = jparsev(p);
            if (v->n == cap) { cap = cap ? cap * 2 : 4; v->keys = realloc(v->keys, cap * sizeof(char *)); v->items = realloc(v->items, cap * sizeof(JV *)); }
            v->keys[v->n] = k; v->items[v->n] = val; v->n++;
            jskipws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == '}') { p->i++; break; }
        }
    } else if (c == '[') {
        p->i++; v = jnew(JARR); int cap = 0;
        jskipws(p);
        if (p->i < p->n && p->s[p->i] == ']') p->i++;
        else while (p->i < p->n) {
            JV *val = jparsev(p);
            if (v->n == cap) { cap = cap ? cap * 2 : 4; v->items = realloc(v->items, cap * sizeof(JV *)); }
            v->items[v->n++] = val;
            jskipws(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == ']') { p->i++; break; }
        }
    } else if (c == '"') { v = jnew(JSTR); v->str = jparsestr(p); }
    else if (p->n - p->i >= 4 && !strncmp(p->s + p->i, "true", 4)) { p->i += 4; v = jnew(JBOOL); v->raw = "true"; }
    else if (p->n - p->i >= 5 && !strncmp(p->s + p->i, "false", 5)) { p->i += 5; v = jnew(JBOOL); v->raw = "false"; }
    else if (p->n - p->i >= 4 && !strncmp(p->s + p->i, "null", 4)) { p->i += 4; v = jnew(JNUL); }
    else {
        size_t st = p->i;
        if (p->i < p->n && p->s[p->i] == '-') p->i++;
        while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++;
        if (p->i < p->n && p->s[p->i] == '.') { p->i++; while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++; }
        if (p->i < p->n && (p->s[p->i] == 'e' || p->s[p->i] == 'E')) { p->i++; if (p->i < p->n && (p->s[p->i] == '+' || p->s[p->i] == '-')) p->i++; while (p->i < p->n && isdigit((unsigned char)p->s[p->i])) p->i++; }
        v = jnew(JNUM); v->raw = strndup(p->s + st, p->i - st);
    }
    if (v) { v->rs = start; v->re = p->i; }
    return v;
}

static void jstr(SB *b, const char *s) {
    sbputc(b, '"');
    for (; s && *s; s++) {
        unsigned char c = (unsigned char)*s;
        switch (c) {
            case '"': sbputs(b, "\\\""); break;
            case '\\': sbputs(b, "\\\\"); break;
            case '\b': sbputs(b, "\\b"); break;
            case '\f': sbputs(b, "\\f"); break;
            case '\n': sbputs(b, "\\n"); break;
            case '\r': sbputs(b, "\\r"); break;
            case '\t': sbputs(b, "\\t"); break;
            default:
                if (c < 0x20) { char t[8]; snprintf(t, sizeof t, "\\u%04x", c); sbputs(b, t); }
                else sbputc(b, (char)c);
        }
    }
    sbputc(b, '"');
}
static void jdump(SB *b, JV *v) {
    if (!v) { sbputs(b, "null"); return; }
    switch (v->t) {
        case JNUL: sbputs(b, "null"); break;
        case JBOOL: sbputs(b, v->raw ? v->raw : "false"); break;
        case JNUM: sbputs(b, v->raw ? v->raw : "0"); break;
        case JSTR: jstr(b, v->str); break;
        case JARR:
            sbputc(b, '[');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jdump(b, v->items[i]); }
            sbputc(b, ']');
            break;
        case JOBJ:
            sbputc(b, '{');
            for (int i = 0; i < v->n; i++) { if (i) sbputc(b, ','); jstr(b, v->keys[i]); sbputc(b, ':'); jdump(b, v->items[i]); }
            sbputc(b, '}');
            break;
    }
}
static JV *jget(JV *o, const char *k) {
    if (!o || o->t != JOBJ) return NULL;
    for (int i = 0; i < o->n; i++) if (!strcmp(o->keys[i], k)) return o->items[i];
    return NULL;
}
static const char *jstrget(JV *o, const char *k) { JV *v = jget(o, k); return v && v->t == JSTR ? v->str : NULL; }
static long long jnum(JV *v) { return v && v->t == JNUM ? strtoll(v->raw, NULL, 10) : 0; }

/* ---------- output escaping ---------- */
static void print_esc(const char *s) {
    if (!s) return;
    for (; *s; s++) {
        switch (*s) {
            case '\\': fputs("\\\\", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default: putchar(*s);
        }
    }
}

/* ---------- reply model ---------- */
typedef struct { char *type; SB thinking, signature, text, json; char *id, *name; } Block;
typedef struct { Block *blocks; int nb, cap; char *stop_reason; long long in, out, cache; } Reply;
static void reply_block(Reply *r, int idx) {
    if (idx >= r->cap) {
        int nc = idx + 8;
        r->blocks = realloc(r->blocks, nc * sizeof(Block));
        memset(r->blocks + r->cap, 0, (nc - r->cap) * sizeof(Block));
        r->cap = nc;
    }
    while (r->nb <= idx) { memset(&r->blocks[r->nb], 0, sizeof(Block)); r->nb++; }
}

/* ---------- HTTP ---------- */
static char *g_apikey_g;
static char *g_auth, *g_path, *g_host;
static int g_port;
static int g_fd = -1;
static unsigned char g_buf[8192];
static size_t g_pos, g_len;

static void parse_base(const char *url) {
    const char *p = strstr(url, "://");
    if (!p) exit(1);
    p += 3;
    const char *slash = strchr(p, '/');
    size_t alen = slash ? (size_t)(slash - p) : strlen(p);
    g_auth = strndup(p, alen);
    g_path = slash ? strdup(slash) : strdup("");
    const char *colon = memchr(p, ':', alen);
    if (colon) { g_host = strndup(p, (size_t)(colon - p)); g_port = atoi(colon + 1); }
    else { g_host = strndup(p, alen); g_port = 80; }
}
static int conn(void) {
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC; hints.ai_socktype = SOCK_STREAM;
    char ps[16]; snprintf(ps, sizeof ps, "%d", g_port);
    if (getaddrinfo(g_host, ps, &hints, &res) || !res) exit(1);
    int fd = -1;
    for (struct addrinfo *a = res; a; a = a->ai_next) {
        fd = socket(a->ai_family, a->ai_socktype, 0);
        if (fd < 0) continue;
        if (connect(fd, a->ai_addr, a->ai_addrlen) == 0) break;
        close(fd); fd = -1;
    }
    freeaddrinfo(res);
    if (fd < 0) exit(1);
    return fd;
}
static int rdbyte(void) {
    if (g_pos == g_len) {
        g_len = recv(g_fd, g_buf, sizeof g_buf, 0);
        g_pos = 0;
        if (g_len <= 0) return -1;
    }
    return g_buf[g_pos++];
}
static SB readline(void) {
    SB b = {0};
    int c = rdbyte();
    if (c < 0) return b;
    while (c >= 0 && c != '\n') { sbputc(&b, (char)c); c = rdbyte(); }
    if (b.len > 0 && b.s[b.len - 1] == '\r') { b.len--; b.s[b.len] = 0; }
    return b;
}
static SB readn(long long n) {
    SB b = {0};
    while (n-- > 0) { int c = rdbyte(); if (c < 0) break; sbputc(&b, (char)c); }
    return b;
}
static SB readchunked(void) {
    SB body = {0};
    for (;;) {
        SB l = readline();
        if (!l.s) break;
        long sz = strtol(l.s, NULL, 16);
        if (sz == 0) {
            for (;;) { SB t = readline(); if (!t.s || t.len == 0) break; }
            break;
        }
        SB ch = readn(sz);
        sbappend(&body, ch.s ? ch.s : "", ch.len);
        readn(2);
    }
    return body;
}
static SB http_post(SB body, int *status_out) {
    int fd = conn();
    g_fd = fd; g_pos = g_len = 0;
    SB req = {0};
    sbputs(&req, "POST "); sbputs(&req, g_path); sbputs(&req, "/v1/messages HTTP/1.1\r\nHost: ");
    sbputs(&req, g_auth);
    char cl[32]; snprintf(cl, sizeof cl, "%zu", body.len);
    sbputs(&req, "\r\nContent-Length: "); sbputs(&req, cl);
    sbputs(&req, "\r\nx-api-key: "); sbputs(&req, g_apikey_g);
    sbputs(&req, "\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n");
    size_t off = 0;
    while (off < req.len) {
        ssize_t w = send(fd, req.s + off, req.len - off, 0);
        if (w <= 0) break;
        off += (size_t)w;
    }
    SB l = readline();
    int status = 0;
    if (l.s) { char *q = strchr(l.s, ' '); if (q) status = atoi(q + 1); }
    long long clen = -1; int chunked = 0;
    for (;;) {
        SB h = readline();
        if (!h.s || h.len == 0) break;
        char *lo = strdup(h.s);
        for (char *x = lo; *x; x++) *x = (char)tolower((unsigned char)*x);
        if (!strncmp(lo, "content-length:", 15)) clen = atoll(lo + 15);
        if (!strncmp(lo, "transfer-encoding:", 18) && strstr(lo, "chunked")) chunked = 1;
        free(lo);
    }
    SB resp = {0};
    if (chunked) resp = readchunked();
    else if (clen >= 0) resp = readn(clen);
    else { int c; while ((c = rdbyte()) >= 0) sbputc(&resp, (char)c); }
    close(fd);
    *status_out = status;
    return resp;
}

/* ---------- SSE ---------- */
static void handle_event(const char *name, SB *data, Reply *r) {
    if (!data || data->len == 0) return;
    JP jp = { data->s, 0, data->len };
    JV *o = jparsev(&jp);
    if (!o) return;
    const char *ty = jstrget(o, "type");
    if (!ty) ty = "";
    const char *ev = (name && *name) ? name : ty;
    if (!strcmp(ev, "message_start")) {
        JV *msg = jget(o, "message");
        if (msg) {
            JV *u = jget(msg, "usage");
            if (u) { r->in += jnum(jget(u, "input_tokens")); r->cache += jnum(jget(u, "cache_read_input_tokens")); }
        }
    } else if (!strcmp(ev, "content_block_start")) {
        JV *ix = jget(o, "index"), *cb = jget(o, "content_block");
        if (ix && cb) {
            int idx = (int)jnum(ix);
            reply_block(r, idx);
            Block *b = &r->blocks[idx];
            const char *t = jstrget(cb, "type");
            b->type = strdup(t ? t : "");
            if (!strcmp(b->type, "tool_use")) {
                const char *id = jstrget(cb, "id"), *nm = jstrget(cb, "name");
                b->id = strdup(id ? id : "");
                b->name = strdup(nm ? nm : "");
            }
        }
    } else if (!strcmp(ev, "content_block_delta")) {
        int idx = (int)jnum(jget(o, "index"));
        if (idx < r->nb) {
            Block *b = &r->blocks[idx];
            JV *d = jget(o, "delta");
            if (d) {
                const char *dt = jstrget(d, "type"), *txt;
                if (dt && !strcmp(dt, "thinking_delta")) { txt = jstrget(d, "thinking"); sbputs(&b->thinking, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "signature_delta")) { txt = jstrget(d, "signature"); sbputs(&b->signature, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "text_delta")) { txt = jstrget(d, "text"); sbputs(&b->text, txt ? txt : ""); }
                else if (dt && !strcmp(dt, "input_json_delta")) { txt = jstrget(d, "partial_json"); sbputs(&b->json, txt ? txt : ""); }
            }
        }
    } else if (!strcmp(ev, "message_delta")) {
        JV *d = jget(o, "delta");
        if (d) { const char *sr = jstrget(d, "stop_reason"); if (sr) { free(r->stop_reason); r->stop_reason = strdup(sr); } }
        JV *u = jget(o, "usage");
        if (u) r->out += jnum(jget(u, "output_tokens"));
    }
}
static void parse_sse(SB *body, Reply *r) {
    char *p = body->s;
    if (!p) return;
    size_t n = body->len, i = 0;
    SB evname = {0}, data = {0};
    while (i < n) {
        size_t j = i;
        while (j < n && p[j] != '\n') j++;
        const char *line = p + i;
        size_t ll = j - i;
        if (ll > 0 && line[ll - 1] == '\r') ll--;
        i = (j < n) ? j + 1 : n;
        if (ll == 0) {
            handle_event(evname.s, &data, r);
            free(evname.s); evname = (SB){0};
            free(data.s); data = (SB){0};
            continue;
        }
        if (line[0] == ':') continue;
        if (ll >= 6 && !strncmp(line, "event:", 6)) {
            const char *v = line + 6; if (*v == ' ') v++;
            free(evname.s); evname = (SB){0};
            sbappend(&evname, v, line + ll - v);
        } else if (ll >= 5 && !strncmp(line, "data:", 5)) {
            const char *v = line + 5; if (*v == ' ') v++;
            if (data.len) sbputc(&data, '\n');
            sbappend(&data, v, line + ll - v);
        }
    }
    handle_event(evname.s, &data, r);
}

static void print_blocks(Reply *r) {
    for (int i = 0; i < r->nb; i++) {
        Block *b = &r->blocks[i];
        const char *bt = b->type ? b->type : "";
        if (!strcmp(bt, "thinking")) {
