import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static int u16(byte[] b, int o) { return (b[o] & 0xFF) | ((b[o+1] & 0xFF) << 8); }
    static int u32(byte[] b, int o) { return (b[o] & 0xFF) | ((b[o+1] & 0xFF) << 8) | ((b[o+2] & 0xFF) << 16) | ((b[o+3] & 0xFF) << 24); }

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles();
        List<File> list = new ArrayList<>();
        for (File f : files) if (f.getName().endsWith(".wav")) list.add(f);
        list.sort(Comparator.comparing(f -> {
            try { return Arrays.toString(f.getName().getBytes("UTF-8")); }
            catch (Exception e) { return f.getName(); }
        }));
        boolean first = true;
        for (File f : list) {
            if (!first) System.out.println();
            first = false;
            try {
                process(f);
            } catch (UnsupportedException e) {
                System.out.println(f.getName() + ": unsupported");
            }
        }
    }

    static class UnsupportedException extends Exception {}

    static void process(File f) throws Exception {
        byte[] b = Files.readAllBytes(f.toPath());
        if (b.length < 12 || !new String(b, 0, 4, "US-ASCII").equals("RIFF")
                || !new String(b, 8, 4, "US-ASCII").equals("WAVE")) throw new UnsupportedException();
        byte[] fmt = null; byte[] data = null;
        int pos = 12;
        while (pos + 8 <= b.length) {
            String id = new String(b, pos, 4, "US-ASCII");
            int n = u32(b, pos + 4);
            if (pos + 8 + n > b.length) throw new UnsupportedException();
            if (id.equals("fmt ")) fmt = Arrays.copyOfRange(b, pos + 8, pos + 8 + n);
            else if (id.equals("data")) data = Arrays.copyOfRange(b, pos + 8, pos + 8 + n);
            pos += 8 + n + (n & 1);
        }
        if (fmt == null || data == null || fmt.length < 16) throw new UnsupportedException();
        int tag = u16(fmt, 0);
        int eff = tag == 0xFFFE && fmt.length >= 26 ? u16(fmt, 24) : tag;
        int channels = u16(fmt, 2);
        int rate = u32(fmt, 4);
        int bits = u16(fmt, 14);
        if (eff != 1 || bits != 16) throw new UnsupportedException();
        int frames = data.length / (2 * channels);
        int N = rate / 50;
        int blocks = frames / N;
        int[] x = new int[N];
        double[] low = {697, 770, 852, 941};
        double[] high = {1209, 1336, 1477, 1633};
        char[][] pad = {{'1','2','3','A'},{'4','5','6','B'},{'7','8','9','C'},{'*','0','#','D'}};
        char[] labels = new char[blocks];
        double[] cos = new double[8];
        for (int i = 0; i < 8; i++) {
            double fq = i < 4 ? low[i] : high[i - 4];
            cos[i] = 2 * Math.cos(2 * Math.PI * fq / rate);
        }
        for (int i = 0; i < blocks; i++) {
            long E = 0;
            for (int n = 0; n < N; n++) {
                int o = (i * N + n) * 2 * channels;
                int v = (short)(data[o] & 0xFF | (data[o+1] << 8));
                x[n] = v;
                E += (long) v * v;
            }
            char lab = 0;
            if (E >= 1000000L * N) {
                double[] r = new double[8];
                for (int k = 0; k < 8; k++) {
                    double c = cos[k], s1 = 0, s2 = 0;
                    for (int n = 0; n < N; n++) {
                        double s = x[n] + c * s1 - s2;
                        s2 = s1; s1 = s;
                    }
                    double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                    r[k] = 2.0 * P / ((double) N * E);
                }
                int bl = 0, bh = 4;
                for (int k = 1; k < 4; k++) { if (r[k] > r[bl]) bl = k; if (r[4+k] > r[bh]) bh = 4 + k; }
                if (r[bl] >= 0.1 && r[bh] >= 0.1 && r[bl] + r[bh] >= 0.6)
                    lab = pad[bl][bh - 4];
            }
            labels[i] = lab;
        }
        // bridging
        for (int i = 1; i < blocks - 1; i++) {
            if (labels[i] == 0 && labels[i-1] != 0 && labels[i-1] == labels[i+1])
                labels[i] = labels[i-1];
        }
        StringBuilder sb = new StringBuilder();
        System.out.println(f.getName() + ": " + rate + " Hz, " + channels + " ch, " + blocks + " blocks");
        int i = 0;
        while (i < blocks) {
            if (labels[i] != 0) {
                int j = i;
                while (j < blocks && labels[j] == labels[i]) j++;
                if (j - i >= 2) {
                    System.out.println(labels[i] + " " + (20 * i) + " " + (20 * j));
                    sb.append(labels[i]);
                }
                i = j;
            } else i++;
        }
        System.out.println("digits: " + sb);
    }
}

