import sys, os, struct, bisect, calendar
from datetime import datetime, date, timedelta

EPOCH = datetime(1970, 1, 1)

def parse_name(s, i):
    if s[i] == '<':
        j = s.index('>', i)
        return s[i+1:j], j+1
    j = i
    while j < len(s) and s[j].isalpha():
        j += 1
    return s[i:j], j

def parse_signed(s, i):
    sign = 1
    if i < len(s) and s[i] in '+-':
        sign = -1 if s[i] == '-' else 1
        i += 1
    j = i
    while j < len(s) and (s[j].isdigit() or s[j] == ':'):
        j += 1
    parts = [int(x) for x in s[i:j].split(':')]
    while len(parts) < 3:
        parts.append(0)
    return sign * (parts[0]*3600 + parts[1]*60 + parts[2]), j

def parse_rule(s, i):
    i += 1  # skip 'M'
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    m = int(s[i:j]); i = j + 1
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    w = int(s[i:j]); i = j + 1
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    d = int(s[i:j]); i = j
    tsec = 7200
    if i < len(s) and s[i] == '/':
        tsec, i = parse_signed(s, i+1)
    return (m, w, d, tsec), i

def parse_tz(s):
    i = 0
    std_name, i = parse_name(s, i)
    val, i = parse_signed(s, i)
    std_off = -val
    dst_name = None; dst_off = None; rules = None
    if i < len(s) and s[i] != ',':
        dst_name, i = parse_name(s, i)
        if i < len(s) and s[i] != ',':
            val, i = parse_signed(s, i)
            dst_off = -val
        else:
            dst_off = std_off - 3600
        if i < len(s) and s[i] == ',':
            r1, i = parse_rule(s, i+1)
            r2, i = parse_rule(s, i+1)
            rules = (r1, r2)
    return std_name, std_off, dst_name, dst_off, rules

def mwd_datetime(rule, y):
    m, w, d, tsec = rule
    last = calendar.monthrange(y, m)[1]
    target = (d - 1) % 7  # python weekday: Mon=0..Sun=6
    if w == 5:
        day = last
        day -= (date(y, m, day).weekday() - target) % 7
    else:
        day = 1 + (target - date(y, m, 1).weekday()) % 7 + 7 * (w - 1)
    return datetime(y, m, day) + timedelta(seconds=tsec)

class TZ:
    def __init__(self, path):
        data = open(path, 'rb').read()
        def block_size(pos, tsz):
            isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = struct.unpack('>6I', data[pos+20:pos+44])
            return pos + 44 + timecnt*tsz + timecnt + typecnt*6 + charcnt + leapcnt*(tsz+4) + isstdcnt + isutcnt
        pos = block_size(0, 4)
        assert data[pos:pos+4] == b'TZif'
        isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = struct.unpack('>6I', data[pos+20:pos+44])
        p = pos + 44
        self.trans = list(struct.unpack('>%dq' % timecnt, data[p:p+8*timecnt])); p += 8*timecnt
        self.tidx = list(data[p:p+timecnt]); p += timecnt
        raw = []
        for _ in range(typecnt):
            off, isd, ai = struct.unpack('>ibB', data[p:p+6]); p += 6
            raw.append((off, ai))
        chars = data[p:p+charcnt]; p += charcnt
        p += leapcnt*12 + isstdcnt + isutcnt
        self.types = [(off, chars[ai:chars.index(0, ai)].decode()) for off, ai in raw]
        nl = data.index(b'\n', p)
        tzstr = data[p+1:nl].decode()
        self.std_name, self.std_off, self.dst_name, self.dst_off, self.rules = parse_tz(tzstr)

    def footer_type(self, t):
        if self.dst_off is None or self.rules is None:
            return (self.std_off, self.std_name)
        y = (EPOCH + timedelta(seconds=t)).year
        so, do = self.std_off, self.dst_off
        for yy in (y-1, y, y+1):
            s = int((mwd_datetime(self.rules[0], yy) - EPOCH).total_seconds()) - so
            e = int((mwd_datetime(self.rules[1], yy) - EPOCH).total_seconds()) - do
            if s < e:
                in_dst = s <= t < e
            else:
                in_dst = t >= s or t < e
            if in_dst:
                return (do, self.dst_name)
        return (so, self.std_name)

    def get(self, t):
        if self.trans and t < self.trans[0]:
            return self.types[0]
        if self.trans and t <= self.trans[-1]:
            i = bisect.bisect_right(self.trans, t) - 1
            return self.types[self.tidx[i]]
        return self.footer_type(t)

def fmt_off(o):
    sign = '+' if o >= 0 else '-'
    a = abs(o)
    h, m, s = a // 3600, (a % 3600) // 60, a % 60
    if s:
        return "%s%02d:%02d:%02d" % (sign, h, m, s)
    return "%s%02d:%02d" % (sign, h, m)

def fmt_local_secs(secs):
    dt = EPOCH + timedelta(seconds=secs)
    return "%04d-%02d-%02dT%02d:%02d:%02d" % (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)

def main():
    d = sys.argv[1]
    cache = {}
    def gettz(fn):
        if fn not in cache:
            cache[fn] = TZ(os.path.join(d, fn))
        return cache[fn]
    out = []
    for line in open(os.path.join(d, 'queries.txt')).read().splitlines():
        if not line.strip():
            continue
        parts = line.split()
        tz = gettz(parts[1])
        if parts[0] == 'UTC':
            t = int(parts[2])
            off, abbr = tz.get(t)
            out.append("%s -> %s %s %s" % (line, fmt_local_secs(t + off), fmt_off(off), abbr))
        else:
            wall_dt = datetime.strptime(parts[2], "%Y-%m-%dT%H:%M:%S")
            wall = int((wall_dt - EPOCH).total_seconds())
            cands = set(off for off, _ in tz.types)
            cands.add(tz.std_off)
            if tz.dst_off is not None:
                cands.add(tz.dst_off)
            ts = sorted(set(t for t in (wall - o for o in cands)
                            if t + tz.get(t)[0] == wall))
            if len(ts) == 1:
                t = ts[0]
                off, abbr = tz.get(t)
                out.append("%s -> %d %s %s" % (line, t, fmt_off(off), abbr))
            elif len(ts) >= 2:
                segs = []
                for t in ts[:2]:
                    off, abbr = tz.get(t)
                    segs.append("%d %s %s" % (t, fmt_off(off), abbr))
                out.append("%s -> %s" % (line, " | ".join(segs)))
            else:
                trs = list(tz.trans)
                if tz.dst_off is not None and tz.rules is not None:
                    y = wall_dt.year
                    for yy in range(y-2, y+3):
                        trs.append(int((mwd_datetime(tz.rules[0], yy) - EPOCH).total_seconds()) - tz.std_off)
                        trs.append(int((mwd_datetime(tz.rules[1], yy) - EPOCH).total_seconds()) - tz.dst_off)
                for tr in sorted(set(trs)):
                    ob = tz.get(tr - 1)[0]
                    oa = tz.get(tr)[0]
                    if oa > ob and tr + ob <= wall < tr + oa:
                        t = wall - ob
                        off, abbr = tz.get(t)
                        out.append("%s -> GAP %d %s %s" % (line, t, fmt_local_secs(t + off), abbr))
                        break
    print('\n'.join(out))

if __name__ == '__main__':
    main()

import sys, os, struct, bisect, calendar
from datetime import datetime, date, timedelta

EPOCH = datetime(1970, 1, 1)

def parse_name(s, i):
    if s[i] == '<':
        j = s.index('>', i)
        return s[i+1:j], j+1
    j = i
    while j < len(s) and s[j].isalpha():
        j += 1
    return s[i:j], j

def parse_signed(s, i):
    sign = 1
    if i < len(s) and s[i] in '+-':
        sign = -1 if s[i] == '-' else 1
        i += 1
    j = i
    while j < len(s) and (s[j].isdigit() or s[j] == ':'):
        j += 1
    parts = [int(x) for x in s[i:j].split(':')]
    while len(parts) < 3:
        parts.append(0)
    return sign * (parts[0]*3600 + parts[1]*60 + parts[2]), j

def parse_rule(s, i):
    i += 1  # skip 'M'
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    m = int(s[i:j]); i = j + 1
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    w = int(s[i:j]); i = j + 1
    j = i
    while j < len(s) and s[j].isdigit(): j += 1
    d = int(s[i:j]); i = j
    tsec = 7200
    if i < len(s) and s[i] == '/':
        tsec, i = parse_signed(s, i+1)
    return (m, w, d, tsec), i

def parse_tz(s):
    i = 0
    std_name, i = parse_name(s, i)
    val, i = parse_signed(s, i)
    std_off = -val
    dst_name = None; dst_off = None; rules = None
    if i < len(s) and s[i] != ',':
        dst_name, i = parse_name(s, i)
        if i < len(s) and s[i] != ',':
            val, i = parse_signed(s, i)
            dst_off = -val
        else:
            dst_off = std_off + 3600
        if i < len(s) and s[i] == ',':
            r1, i = parse_rule(s, i+1)
            r2, i = parse_rule(s, i+1)
            rules = (r1, r2)
    return std_name, std_off, dst_name, dst_off, rules

def mwd_datetime(rule, y):
    m, w, d, tsec = rule
    last = calendar.monthrange(y, m)[1]
    target = (d - 1) % 7  # python weekday: Mon=0..Sun=6
    if w >= 5:
        day = last
        day -= (date(y, m, day).weekday() - target) % 7
    else:
        day = 1 + (target - date(y, m, 1).weekday()) % 7 + 7 * (w - 1)
    return datetime(y, m, day) + timedelta(seconds=tsec)

