import * as fs from "fs";
import * as path from "path";

const LOW = [697, 770, 852, 941];
const HIGH = [1209, 1336, 1477, 1633];
const KEYPAD: Record<number, Record<number, string>> = {
  697: { 1209: "1", 1336: "2", 1477: "3", 1633: "A" },
  770: { 1209: "4", 1336: "5", 1477: "6", 1633: "B" },
  852: { 1209: "7", 1336: "8", 1477: "9", 1633: "C" },
  941: { 1209: "*", 1336: "0", 1477: "#", 1633: "D" },
};

interface Wav {
  rate: number;
  channels: number;
  samples: Int16Array; // left channel
}

function parseWav(buf: Buffer): Wav | null {
  if (buf.length < 12) return null;
  if (buf.toString("ascii", 0, 4) !== "RIFF" || buf.toString("ascii", 8, 12) !== "WAVE") return null;
  let off = 12;
  let fmt: Buffer | null = null;
  let data: Buffer | null = null;
  while (off + 8 <= buf.length) {
    const id = buf.toString("ascii", off, off + 4);
    const size = buf.readUInt32LE(off + 4);
    const bodyStart = off + 8;
    if (bodyStart + size > buf.length) return null;
    const body = buf.subarray(bodyStart, bodyStart + size);
    if (id === "fmt ") fmt = Buffer.from(body);
    else if (id === "data") data = Buffer.from(body);
    off = bodyStart + size + (size % 2);
  }
  if (!fmt || fmt.length < 16 || !data) return null;
  let tag = fmt.readUInt16LE(0);
  const channels = fmt.readUInt16LE(2);
  const rate = fmt.readUInt32LE(4);
  const bits = fmt.readUInt16LE(14);
  if (tag === 0xfffe) {
    if (fmt.length < 26) return null;
    tag = fmt.readUInt16LE(24);
  }
  if (tag !== 1 || bits !== 16) return null;
  if (channels !== 1 && channels !== 2) return null;
  if (rate !== 8000 && rate !== 16000) return null;
  const frames = Math.floor(data.length / (2 * channels));
  const samples = new Int16Array(frames);
  for (let i = 0; i < frames; i++) samples[i] = data.readInt16LE(i * 2 * channels);
  return { rate, channels, samples };
}

function goertzel(x: Int16Array, f: number, rate: number): number {
  const N = x.length;
  const c = 2 * Math.cos((2 * Math.PI * f) / rate);
  let s1 = 0, s2 = 0;
  for (let n = 0; n < N; n++) {
    const s = x[n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  return s1 * s1 + s2 * s2 - c * s1 * s2;
}

function processFile(dir: string, name: string, out: string[]): void {
  let wav: Wav | null = null;
  try {
    wav = parseWav(fs.readFileSync(path.join(dir, name)));
  } catch {
    wav = null;
  }
  if (!wav) {
    out.push(`${name}: unsupported`);
    return;
  }
  const { rate, channels, samples } = wav;
  const N = rate / 50;
  const numBlocks = Math.floor(samples.length / N);
  const labels: (string | null)[] = [];
  for (let b = 0; b < numBlocks; b++) {
    const x = samples.subarray(b * N, (b + 1) * N);
    let E = 0;
    for (let n = 0; n < N; n++) E += x[n] * x[n];
    if (E < 1000000 * N) {
      labels.push(null);
      continue;
    }
    let fl = 0, flr = -1, fh = 0, fhr = -1;
    for (const f of LOW) {
      const r = (2 * goertzel(x, f, rate)) / (N * E);
      if (r > flr) { flr = r; fl = f; }
    }
    for (const f of HIGH) {
      const r = (2 * goertzel(x, f, rate)) / (N * E);
      if (r > fhr) { fhr = r; fh = f; }
    }
    if (flr >= 0.1 && fhr >= 0.1 && flr + fhr >= 0.6) labels.push(KEYPAD[fl][fh]);
    else labels.push(null);
  }
  // bridging
  const bridged = labels.slice();
  for (let i = 1; i < labels.length - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }
  out.push(`${name}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);
  let digits = "";
  let i = 0;
  while (i < bridged.length) {
    if (bridged[i] === null) { i++; continue; }
    let j = i;
    while (j + 1 < bridged.length && bridged[j + 1] === bridged[i]) j++;
    if (j - i + 1 >= 2) {
      out.push(`${bridged[i]} ${20 * i} ${20 * (j + 1)}`);
      digits += bridged[i];
    }
    i = j + 1;
  }
  out.push(`digits: ${digits}`);
}

function main(): void {
  const dir = process.argv[2];
  const names = fs
    .readdirSync(dir)
    .filter((n) => n.endsWith(".wav"))
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const out: string[] = [];
  for (const name of names) {
    if (out.length > 0) out.push("");
    processFile(dir, name, out);
  }
  if (out.length > 0) process.stdout.write(out.join("\n") + "\n");
  process.exit(0);
}

main();

import Foundation

func byteCompare(_ a: String, _ b: String) -> Bool {
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

func u16(_ data: Data, _ off: Int) -> Int {
    Int(data[off]) | (Int(data[off+1]) << 8)
}
func u32(_ data: Data, _ off: Int) -> Int {
    Int(data[off]) | (Int(data[off+1]) << 8) | (Int(data[off+2]) << 16) | (Int(data[off+3]) << 24)
}

let lowFreqs = [697.0, 770.0, 852.0, 941.0]
let highFreqs = [1209.0, 1336.0, 1477.0, 1633.0]
let keypad = [
    [697, 1209]: "1", [697, 1336]: "2", [697, 1477]: "3", [697, 1633]: "A",
    [770, 1209]: "4", [770, 1336]: "5", [770, 1477]: "6", [770, 1633]: "B",
    [852, 1209]: "7", [852, 1336]: "8", [852, 1477]: "9", [852, 1633]: "C",
    [941, 1209]: "*", [941, 1336]: "0", [941, 1477]: "#", [941, 1633]: "D"
]

func goertzel(_ x: [Double], rate: Double, f: Double) -> Double {
    let c = 2.0 * cos(2.0 * Double.pi * f / rate)
    var s1 = 0.0, s2 = 0.0
    for v in x {
        let s = v + c * s1 - s2
        s2 = s1
        s1 = s
    }
    return s1 * s1 + s2 * s2 - c * s1 * s2
}

func processFile(_ url: URL) -> String {
    let name = url.lastPathComponent
    guard let raw = try? Data(contentsOf: url) else { return "\(name): unsupported" }
    guard raw.count >= 12,
          String(data: raw.subdata(in: 0..<4), encoding: .ascii) == "RIFF",
          String(data: raw.subdata(in: 8..<12), encoding: .ascii) == "WAVE"
    else { return "\(name): unsupported" }

    var fmtBody: Data? = nil
    var dataBody: Data? = nil
    var pos = 12
    while pos + 8 <= raw.count {
        guard let idData = try? raw.subdata(in: pos..<pos+4),
              let id = String(data: idData, encoding: .ascii)
        else { break }
        let n = u32(raw, pos + 4)
        let bodyStart = pos + 8
        if bodyStart + n > raw.count { break }
        let body = raw.subdata(in: bodyStart..<bodyStart+n)
        if id == "fmt " { fmtBody = body }
        if id == "data" { dataBody = body }
        pos = bodyStart + n + (n % 2 == 1 ? 1 : 0)
    }

    guard let fmt = fmtBody, fmt.count >= 16, let data = dataBody else {
        return "\(name): unsupported"
    }
    var tag = u16(fmt, 0)
    if tag == 0xFFFE {
        guard fmt.count >= 26 else { return "\(name): unsupported" }
        tag = u16(fmt, 24)
    }
    let channels = u16(fmt, 2)
    let rate = u32(fmt, 4)
    let bits = u16(fmt, 14)
    guard tag == 1, bits == 16, channels == 1 || channels == 2, rate == 8000 || rate == 16000 else {
        return "\(name): unsupported"
    }

    let frameBytes = 2 * channels
    let frames = data.count / frameBytes
    var samples: [Double] = []
    samples.reserveCapacity(frames)
    for i in 0..<frames {
        let off = i * frameBytes
        var v = Int16(bitPattern: UInt16(data[off]) | (UInt16(data[off+1]) << 8))
        _ = v
        let s = Int16(bitPattern: UInt16(data[off]) | (UInt16(data[off+1]) << 8))
        samples.append(Double(s))
    }

    let N = rate / 50
    let blockCount = samples.count / N
    var labels = [String?](repeating: nil, count: blockCount)
    for b in 0..<blockCount {
        let block = Array(samples[b*N..<(b+1)*N])
        var E = 0.0
        for v in block { E += v * v }
        if E < 1_000_000.0 * Double(N) { continue }
        var bestL = 0.0, bestLf = 0.0, bestH = 0.0, bestHf = 0.0
        for f in lowFreqs {
            let r = 2.0 * goertzel(block, rate: Double(rate), f: f) / (Double(N) * E)
            if r > bestL { bestL = r; bestLf = f }
        }
        for f in highFreqs {
            let r = 2.0 * goertzel(block, rate: Double(rate), f: f) / (Double(N) * E)
            if r > bestH { bestH = r; bestHf = f }
        }
        if bestL >= 0.1, bestH >= 0.1, bestL + bestH >= 0.6 {
            labels[b] = keypad[[Int(bestLf), Int(bestHf)]]
        }
    }

    // bridging
    var bridged = labels
    for i in 1..<(blockCount > 0 ? blockCount : 1) {
        if i + 1 < blockCount, labels[i] == nil,
           let a = labels[i-1], let c = labels[i+1], a == c {
            bridged[i] = a
        }
    }

    var lines: [String] = []
    lines.append("\(name): \(rate) Hz, \(channels) ch, \(blockCount) blocks")
    var digits = ""
    var i = 0
    while i < blockCount {
        guard let d = bridged[i] else { i += 1; continue }
        var j = i
        while j + 1 < blockCount && bridged[j+1] == d { j += 1 }
        if j - i + 1 >= 2 {
            let start = 20 * i, end = 20 * (j + 1)
            lines.append("\(d) \(start) \(end)")
            digits += d
        }
        i = j + 1
    }
    lines.append("digits: \(digits)")
    return lines.joined(separator: "\n")
}

