#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <math.h>
#include <stdint.h>

static int cmpstr(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

static uint32_t rd32(const unsigned char *p) {
    return p[0] | (p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
}
static uint16_t rd16(const unsigned char *p) {
    return p[0] | (p[1]<<8);
}

int main(int argc, char **argv) {
    if (argc != 2) return 0;
    DIR *d = opendir(argv[1]);
    if (!d) return 0;
    char **names = NULL;
    size_t nn = 0, cap = 0;
    struct dirent *e;
    while ((e = readdir(d))) {
        size_t l = strlen(e->d_name);
        if (l > 4 && strcmp(e->d_name + l - 4, ".wav") == 0) {
            if (nn == cap) { cap = cap ? cap*2 : 16; names = realloc(names, cap*sizeof(char*)); }
            names[nn++] = strdup(e->d_name);
        }
    }
    closedir(d);
    qsort(names, nn, sizeof(char*), cmpstr);

    for (size_t fi = 0; fi < nn; fi++) {
        if (fi) printf("\n");
        char path[4096];
        snprintf(path, sizeof path, "%s/%s", argv[1], names[fi]);
        FILE *f = fopen(path, "rb");
        int supported = 0;
        uint32_t rate = 0; uint16_t ch = 0;
        long datasize = 0, dataoff = 0;
        long fmtsize = 0, fmtoff = 0;
        if (f) {
            unsigned char hdr[12];
            if (fread(hdr, 1, 12, f) == 12 && !memcmp(hdr, "RIFF", 4) && !memcmp(hdr+8, "WAVE", 4)) {
                int ok = 1;
                while (ok) {
                    unsigned char ch8[8];
                    size_t r = fread(ch8, 1, 8, f);
                    if (r < 8) break;
                    uint32_t sz = rd32(ch8+4);
                    if (!memcmp(ch8, "fmt ", 4)) { fmtoff = ftell(f); fmtsize = sz; }
                    else if (!memcmp(ch8, "data", 4)) { dataoff = ftell(f); datasize = sz; }
                    long skip = sz + (sz & 1);
                    if (fseek(f, skip, SEEK_CUR) != 0) ok = 0;
                }
                if (ok && fmtsize >= 16 && datasize > 0) {
                    unsigned char fb[64];
                    size_t want = fmtsize > 64 ? 64 : fmtsize;
                    if (fseek(f, fmtoff, SEEK_SET) == 0 && fread(fb, 1, want, f) == want) {
                        uint16_t tag = rd16(fb);
                        if (tag == 0xFFFE && fmtsize >= 26) tag = rd16(fb + 24);
                        ch = rd16(fb + 2);
                        rate = rd32(fb + 4);
                        uint16_t bits = rd16(fb + 14);
                        if (tag == 1 && bits == 16 && (ch == 1 || ch == 2) &&
                            (rate == 8000 || rate == 16000))
                            supported = 1;
                    }
                }
            }
        }
        if (!supported) {
            printf("%s: unsupported\n", names[fi]);
            if (f) fclose(f);
            continue;
        }
        uint32_t N = rate / 50;
        long frames = datasize / (2L * ch);
        long nblocks = frames / (long)N;
        /* read left channel samples */
        int16_t *x = malloc((size_t)frames * 2);
        if (!x) { fclose(f); continue; }
        if (ch == 1) {
            if (fseek(f, dataoff, SEEK_SET) == 0)
                fread(x, 2, frames, f);
        } else {
            int16_t *raw = malloc((size_t)frames * 4);
            if (raw && fseek(f, dataoff, SEEK_SET) == 0) {
                fread(raw, 4, frames, f);
                for (long i = 0; i < frames; i++) x[i] = raw[2*i];
            }
            free(raw);
        }
        fclose(f);

        static const double freqs[8] = {697, 770, 852, 941, 1209, 1336, 1477, 1633};
        static const char digits[4][4] = {{'1','2','3','A'},{'4','5','6','B'},{'7','8','9','C'},{'*','0','#','D'}};
        int *lab = malloc(sizeof(int) * (nblocks > 0 ? nblocks : 1));
        double cs[8];
        for (int k = 0; k < 8; k++) cs[k] = 2.0 * cos(2.0 * M_PI * freqs[k] / rate);

        for (long b = 0; b < nblocks; b++) {
            const int16_t *xb = x + b * (long)N;
            double E = 0;
            for (uint32_t n = 0; n < N; n++) E += (double)xb[n] * xb[n];
            lab[b] = -1;
            if (E < 1000000.0 * N) continue;
            double rl[4] = {0,0,0,0}, rh[4] = {0,0,0,0};
            for (int k = 0; k < 8; k++) {
                double c = cs[k], s1 = 0, s2 = 0;
                for (uint32_t n = 0; n < N; n++) {
                    double s = xb[n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                double P = s1*s1 + s2*s2 - c*s1*s2;
                double r = 2.0 * P / ((double)N * E);
                if (k < 4) rl[k] = r; else rh[k-4] = r;
            }
            int fl = 0, fh = 0;
            for (int k = 1; k < 4; k++) { if (rl[k] > rl[fl]) fl = k; if (rh[k] > rh[fh]) fh = k; }
            if (rl[fl] >= 0.1 && rh[fh] >= 0.1 && rl[fl] + rh[fh] >= 0.6)
                lab[b] = fl * 4 + fh;
        }
        /* bridging */
        for (long b = 1; b + 1 < nblocks; b++) {
            if (lab[b] == -1 && lab[b-1] != -1 && lab[b-1] == lab[b+1])
                lab[b] = lab[b-1];
        }
        printf("%s: %u Hz, %u ch, %ld blocks\n", names[fi], rate, ch, nblocks);
        char digitsout[4096]; int di = 0;
        long b = 0;
        while (b < nblocks) {
            if (lab[b] == -1) { b++; continue; }
            long e = b;
            while (e + 1 < nblocks && lab[e+1] == lab[b]) e++;
            if (e - b + 1 >= 2) {
                int li = lab[b] / 4, hi = lab[b] % 4;
                char dg = digits[li][hi];
                printf("%c %ld %ld\n", dg, b * 20, (e + 1) * 20);
                digitsout[di++] = dg;
            }
            b = e + 1;
        }
        digitsout[di] = 0;
        printf("digits: %s\n", digitsout);
        free(lab); free(x);
    }
    return 0;
}

use std::env;
use std::fs;
use std::io::Read;
