fn rd_u16(b: &[u8], off: usize) -> u16 { u16::from_le_bytes([b[off], b[off+1]]) }
fn rd_u32(b: &[u8], off: usize) -> u32 { u32::from_le_bytes([b[off], b[off+1], b[off+2], b[off+3]]) }

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 { process::exit(1); }
    let dir = &args[1];
    let mut names: Vec<String> = Vec::new();
    if let Ok(rd) = fs::read_dir(dir) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().into_owned();
            if name.ends_with(".wav") {
                names.push(name);
            }
        }
    }
    names.sort();

    let mut first = true;
    for name in &names {
        if !first { println!(); }
        first = false;
        let path = format!("{}/{}", dir, name);
        let data = match fs::read(&path) { Ok(d) => d, Err(_) => { println!("{}: unsupported", name); continue; } };
        match process_file(&data) {
            Some((rate, channels, samples)) => {
                let n = rate / 50;
                let blocks = samples.len() / n;
                let mut labels: Vec<Option<char>> = Vec::with_capacity(blocks);
                for i in 0..blocks {
                    labels.push(detect(&samples[i*n..(i+1)*n], rate));
                }
                // bridging
                let mut bridged = labels.clone();
                for i in 0..blocks {
                    if labels[i].is_none() && i > 0 && i + 1 < blocks {
                        if let (Some(a), Some(b)) = (labels[i-1], labels[i+1]) {
                            if a == b { bridged[i] = Some(a); }
                        }
                    }
                }
                println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, blocks);
                let mut digits = String::new();
                let mut i = 0;
                while i < blocks {
                    if let Some(d) = bridged[i] {
                        let mut j = i;
                        while j < blocks && bridged[j] == Some(d) { j += 1; }
                        if j - i >= 2 {
                            println!("{} {} {}", d, 20 * i, 20 * j);
                            digits.push(d);
                        }
                        i = j;
                    } else {
                        i += 1;
                    }
                }
                println!("digits: {}", digits);
            }
            None => { println!("{}: unsupported", name); }
        }
    }
}

fn process_file(data: &[u8]) -> Option<(u32, u16, Vec<i16>)> {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" { return None; }
    let mut pos = 12usize;
    let mut fmt: Option<&[u8]> = None;
    let mut dat: Option<&[u8]> = None;
    while pos + 8 <= data.len() {
        let id = &data[pos..pos+4];
        let size = rd_u32(data, pos + 4) as usize;
        let body_start = pos + 8;
        let body_end = body_start.checked_add(size)?;
        if body_end > data.len() { return None; }
        let body = &data[body_start..body_end];
        match id {
            b"fmt " => fmt = Some(body),
            b"data" => dat = Some(body),
            _ => {}
        }
        pos = body_end + (size & 1);
    }
    let fmt = fmt?;
    if fmt.len() < 16 { return None; }
    let tag = rd_u16(fmt, 0);
    let channels = rd_u16(fmt, 2);
    let rate = rd_u32(fmt, 4);
    let bits = rd_u16(fmt, 14);
    let eff = if tag == 0xFFFE {
        if fmt.len() < 26 { return None; }
        rd_u16(fmt, 24)
    } else { tag };
    if eff != 1 || bits != 16 { return None; }
    if channels != 1 && channels != 2 { return None; }
    if rate != 8000 && rate != 16000 { return None; }
    let dat = dat?;
    let bytes_per_frame = 2 * channels as usize;
    let frames = dat.len() / bytes_per_frame;
    let mut samples = Vec::with_capacity(frames);
    for f in 0..frames {
        let o = f * bytes_per_frame;
        samples.push(i16::from_le_bytes([dat[o], dat[o+1]]));
    }
    Some((rate, channels, samples))
}

const LOW: [u32; 4] = [697, 770, 852, 941];
const HIGH: [u32; 4] = [1209, 1336, 1477, 1633];
const KEYPAD: [[char; 4]; 4] = [['1','2','3','A'],['4','5','6','B'],['7','8','9','C'],['*','0','#','D']];

fn goertzel(x: &[i16], f: u32, rate: u32) -> f64 {
    let n = x.len() as f64;
    let c = 2.0 * (2.0 * std::f64::consts::PI * f as f64 / rate as f64).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &v in x {
        let s = v as f64 + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    s1 * s1 + s2 * s2 - c * s1 * s2
}

fn detect(x: &[i16], rate: u32) -> Option<char> {
    let n = x.len();
    let e: f64 = x.iter().map(|&v| (v as f64) * (v as f64)).sum();
    if e < 1000000.0 * n as f64 { return None; }
    let mut rl = [0.0f64; 4];
    let mut rh = [0.0f64; 4];
    for k in 0..4 {
        rl[k] = 2.0 * goertzel(x, LOW[k], rate) / (n as f64 * e);
        rh[k] = 2.0 * goertzel(x, HIGH[k], rate) / (n as f64 * e);
    }
    let (il, _) = rl.iter().enumerate().fold((0, rl[0]), |a, (i, &v)| if v > a.1 { (i, v) } else { a });
    let (ih, _) = rh.iter().enumerate().fold((0, rh[0]), |a, (i, &v)| if v > a.1 { (i, v) } else { a });
    if rl[il] >= 0.1 && rh[ih] >= 0.1 && rl[il] + rh[ih] >= 0.6 {
        Some(KEYPAD[il][ih])
    } else {
        None
    }
}

