import Foundation

func daysFromCivil(_ y: Int, _ m: Int, _ d: Int) -> Int {
    var yy = y
    if m <= 2 { yy -= 1 }
    let era = (yy >= 0 ? yy : yy - 399) / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    return era * 146097 + doe - 719468
}

func civilFromDays(_ z0: Int) -> (Int, Int, Int) {
    let z = z0 + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100)
    let mp = (5 * doy + 2) / 153
    let d = doy - (153 * mp + 2) / 5 + 1
    let m = mp < 10 ? mp + 3 : mp - 9
    return (m <= 2 ? y + 1 : y, m, d)
}

func fdiv(_ a: Int64, _ m: Int64) -> Int64 {
    var q = a / m
    if a % m != 0 && (a < 0) != (m < 0) { q -= 1 }
    return q
}

func nthWeekday(_ y: Int, _ m: Int, _ w: Int, _ d: Int) -> Int {
    if w == 5 {
        let (ny, nm) = m == 12 ? (y + 1, 1) : (y, m + 1)
        let last = daysFromCivil(ny, nm, 1) - 1
        let dowLast = (last + 4) % 7
        return last - (dowLast - d + 7) % 7
    }
    let first = daysFromCivil(y, m, 1)
    let dowFirst = (first + 4) % 7
    return first + (d - dowFirst + 7) % 7 + 7 * (w - 1)
}

struct TZ {
    var transitions: [Int64] = []
    var typeIdx: [Int] = []
    var offsets: [Int] = []
    var abbrs: [String] = []
    var stdAbbr = ""
    var stdOff = 0
    var dstAbbr: String? = nil
    var dstOff = 0
    var rule1: (Int, Int, Int, Int)? = nil
    var rule2: (Int, Int, Int, Int)? = nil

    func ruleInstants(_ y: Int) -> [(Int64, Bool)] {
        guard let r1 = rule1, let r2 = rule2 else { return [] }
        let s = Int64(nthWeekday(y, r1.0, r1.1, r1.2)) * 86400 + Int64(r1.3) - Int64(stdOff)
        let e = Int64(nthWeekday(y, r2.0, r2.1, r2.2)) * 86400 + Int64(r2.3) - Int64(dstOff)
        return [(s, true), (e, false)]
    }

    func footerAt(_ t: Int64) -> (Int, String) {
        guard let da = dstAbbr else { return (stdOff, stdAbbr) }
        guard rule1 != nil && rule2 != nil else { return (dstOff, da) }
        let y = civilFromDays(Int(fdiv(t, 86400))).0
        var events: [(Int64, Bool)] = []
        for yy in (y - 1)...(y + 1) { events.append(contentsOf: ruleInstants(yy)) }
        events.sort { $0.0 < $1.0 }
        var dst = false
        for e in events where e.0 <= t { dst = e.1 }
        return dst ? (dstOff, da) : (stdOff, stdAbbr)
    }

    func offsetAt(_ t: Int64) -> (Int, String) {
        if transitions.isEmpty || t < transitions[0] {
            return (offsets[0], abbrs[0])
        }
        if t <= transitions.last! {
            var lo = 0, hi = transitions.count - 1
            while lo < hi {
                let mid = (lo + hi + 1) / 2
                if transitions[mid] <= t { lo = mid } else { hi = mid - 1 }
            }
            let ti = typeIdx[lo]
            return (offsets[ti], abbrs[ti])
        }
        return footerAt(t)
    }
}

func parsePosixFooter(_ s: String) -> (String, Int, String?, Int, (Int, Int, Int, Int)?, (Int, Int, Int, Int)?) {
    let c = Array(s)
    var i = 0
    func name() -> String {
        if c[i] == "<" {
            var j = i + 1
            while c[j] != ">" { j += 1 }
