    precondition(Array(b[0..<4]) == magic)
    let v1size = u32(20) + u32(24) + u32(28) * 8 + u32(32) * 5 + u32(36) * 6 + u32(40)
    var p = 44 + v1size
    precondition(Array(b[p..<p + 4]) == magic)
    let isutcnt = u32(p + 20), isstdcnt = u32(p + 24), leapcnt = u32(p + 28)
    let timecnt = u32(p + 32), typecnt = u32(p + 36), charcnt = u32(p + 40)
    p += 44
    for _ in 0..<timecnt {
