    }
    let chars = Array(b[p..<p + charcnt]); p += charcnt
    p += leapcnt * 12
    p += isstdcnt + isutcnt
    for idx in abbrIdx {
        var j = idx
        while j < charcnt && chars[j] != 0 { j += 1 }
