                    if T <= x && x < T + Int64(after - before) { o1 = before; break }
                }
            }
            let t = Wn - Int64(o1 ?? 0)
            let (off, ab) = tz.offsetAt(t)
            out += "\(line) -> GAP \(t) \(localStr(t, off)) \(ab)\n"
