    static void runSession(String url) {
        try {
            URI uri = new URI(url);
            String host = uri.getHost();
            int port = uri.getPort();
            String path = uri.getRawPath();
            if (uri.getRawQuery() != null) path += "?" + uri.getRawQuery();

            Socket sock = new Socket(host, port);
            try {
                in = new BufferedInputStream(sock.getInputStream());
                out = new BufferedOutputStream(sock.getOutputStream());

                byte[] keyBytes = new byte[16];
                new SecureRandom().nextBytes(keyBytes);
                String key = Base64.getEncoder().encodeToString(keyBytes);

                String req = "GET " + path + " HTTP/1.1\r\n"
                        + "Host: " + host + ":" + port + "\r\n"
                        + "Upgrade: websocket\r\n"
                        + "Connection: Upgrade\r\n"
                        + "Sec-WebSocket-Version: 13\r\n"
                        + "Sec-WebSocket-Key: " + key + "\r\n"
                        + "\r\n";
                out.write(req.getBytes(StandardCharsets.ISO_8859_1));
                out.flush();

                // read header block
                ByteArrayOutputStream head = new ByteArrayOutputStream();
                int prev = -2, c;
                while ((c = in.read()) != -1) {
                    head.write(c);
                    if (prev == '\r' && c == '\n' && head.size() >= 4) {
                        byte[] b = head.toByteArray();
                        int len = b.length;
                        if (len >= 4 && b[len-4] == '\r' && b[len-3] == '\n' && b[len-2] == '\r' && b[len-1] == '\n') break;
                    }
                    prev = c;
                }
                String headers = head.toString(StandardCharsets.ISO_8859_1);
                String[] lines = headers.split("\r\n");
                String statusLine = lines[0];
                String[] parts = statusLine.split(" ", 3);
                int code = Integer.parseInt(parts[1]);
                String rest = parts.length > 2 ? parts[2] : "";
                if (code != 101) {
                    System.out.println("handshake failed: " + code + (rest.isEmpty() ? "" : " " + rest));
                    sock.close();
                    return;
                }
                String accept = null;
                for (int i = 1; i < lines.length; i++) {
                    int ci = lines[i].indexOf(':');
                    if (ci > 0 && lines[i].substring(0, ci).trim().equalsIgnoreCase("Sec-WebSocket-Accept")) {
                        accept = lines[i].substring(ci + 1).trim();
                    }
                }
                String expected;
                MessageDigest sha = MessageDigest.getInstance("SHA-1");
                byte[] digest = sha.digest((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
                expected = Base64.getEncoder().encodeToString(digest);
                if (accept == null || !accept.equals(expected)) {
                    System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                    sock.close();
                    return;
                }

                sessionLoop(sock);
            } finally {
                sock.close();
            }
        } catch (Exception e) {
            // network error: just end session
        }
    }

