import sys, socket, base64, hashlib, os, struct

def make_reader(sock):
    return {'sock': sock, 'buf': b''}

def read_until(r, sep):
    while sep not in r['buf']:
        data = r['sock'].recv(65536)
        if not data:
            raise EOFError
        r['buf'] += data
    i = r['buf'].index(sep) + len(sep)
    out, r['buf'] = r['buf'][:i], r['buf'][i:]
    return out

def read_exact(r, n):
    while len(r['buf']) < n:
        data = r['sock'].recv(65536)
        if not data:
            raise EOFError
        r['buf'] += data
    out, r['buf'] = r['buf'][:n], r['buf'][n:]
    return out

def send_frame(sock, opcode, payload):
    mask = os.urandom(4)
    while mask == b'\x00\x00\x00\x00':
        mask = os.urandom(4)
    b0 = 0x80 | opcode
    n = len(payload)
    if n <= 125:
        lenb = bytes([n])
    elif n <= 65535:
        lenb = bytes([126]) + struct.pack('>H', n)
    else:
        lenb = bytes([127]) + struct.pack('>Q', n)
    masked = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
    sock.sendall(bytes([b0, 0x80 | len(mask) if False else 0x80]) if False else bytes([b0]) + bytes([0x80]) + lenb)
    # rebuild properly
    header = bytes([b0, 0x80]) + lenb
    sock.sendall(header + mask + masked)

def recv_frame(r):
    h = read_exact(r, 2)
    fin = (h[0] >> 7) & 1
    opcode = h[0] & 0x0F
    masked = (h[1] >> 7) & 1
    ln = h[1] & 0x7F
    if ln == 126:
        ln = struct.unpack('>H', read_exact(r, 2))[0]
    elif ln == 127:
        ln = struct.unpack('>Q', read_exact(r, 8))[0]
    if masked:
        mk = read_exact(r, 4)
        payload = read_exact(r, ln)
        payload = bytes(b ^ mk[i % 4] for i, b in enumerate(payload))
    else:
        payload = read_exact(r, ln)
    return fin, opcode, payload

def handle_session(url, n):
    # parse URL
    rest = url[len('ws://'):]
    slash = rest.index('/')
    hostport, path = rest[:slash], rest[slash:]
    host, port = hostport.rsplit(':', 1)
    port = int(port)
    print(f"session {n}")
    key = base64.b64encode(os.urandom(16)).decode()
    req = (f"GET {path} HTTP/1.1\r\n"
           f"Host: {host}:{port}\r\n"
           f"Upgrade: websocket\r\n"
           f"Connection: Upgrade\r\n"
           f"Sec-WebSocket-Key: {key}\r\n"
           f"Sec-WebSocket-Version: 13\r\n\r\n")
    sock = socket.create_connection((host, port))
    try:
        sock.sendall(req.encode())
        r = make_reader(sock)
        head = read_until(r, b'\r\n\r\n')
        lines = head.split(b'\r\n')
        status = lines[0].decode('latin-1')
        parts = status.split(' ', 2)
        code = int(parts[1])
        reason = parts[2] if len(parts) > 2 else ''
        if code != 101:
            print(f"handshake failed: {code} {reason}".rstrip())
            return
        headers = {}
        for line in lines[1:]:
            if b':' in line:
                name, val = line.split(b':', 1)
                headers[name.strip().lower().decode()] = val.strip().decode()
        expected = base64.b64encode(hashlib.sha1((key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
        if headers.get('sec-websocket-accept') != expected:
            print("handshake failed: bad Sec-WebSocket-Accept")
            return

        sent_close = False
        fragments = []
        frag_opcode = None
        awaiting_binary = False

        def handle_data(opcode, payload):
            nonlocal fragments, frag_opcode, awaiting_binary, sent_close
            if opcode in (1, 2):
                frag_opcode = opcode
                fragments = [payload]
            else:
                fragments.append(payload)
            return None

        while True:
            fin, opcode, payload = recv_frame(r)
            if opcode == 9:
                send_frame(sock, 10, payload)
                continue
            if opcode == 10:
                continue
            if opcode == 8:
                if len(payload) >= 2:
                    ccode = struct.unpack('>H', payload[:2])[0]
                    creason = payload[2:].decode('utf-8', 'replace')
                else:
                    ccode, creason = 1005, ''
                if creason:
                    print(f"closed {ccode} {creason}")
                else:
                    print(f"closed {ccode}")
                if not sent_close:
                    send_frame(sock, 8, struct.pack('>H', ccode))
                    sent_close = True
                return
            if opcode in (0, 1, 2):
                if opcode in (1, 2):
                    if fin:
                        msg = payload
                        op = opcode
                    else:
                        frag_opcode = opcode
                        fragments = [payload]
                        continue
                else:
                    fragments.append(payload)
                    if not fin:
                        continue
                    msg = b''.join(fragments)
                    op = frag_opcode
                    fragments = []
                    frag_opcode = None
                if op == 2:
                    if awaiting_binary:
                        awaiting_binary = False
                        print(f"SHA1 {len(msg)} -> {hashlib.sha1(msg).hexdigest()}")
                    continue
                # text message
                text = msg.decode('utf-8')
                if awaiting_binary:
                    # unexpected; treat as command anyway
                    awaiting_binary = False
                if text == 'SHA1':
                    awaiting_binary = True
                elif text == 'BYE':
                    send_frame(sock, 8, struct.pack('>H', 1000))
                    sent_close = True
                elif text.startswith('ADD ') or text.split(' ')[0] == 'ADD':
                    p = text.split(' ')
                    s = int(p[1]) + int(p[2])
                    send_frame(sock, 1, str(s).encode())
                    print(f"{text} -> {s}")
                elif text.split(' ')[0] == 'REV':
                    body = text[len('REV '):] if len(text) > 4 else ''
                    rev = body[::-1]
                    send_frame(sock, 1, rev.encode())
                    print(f"REV {body} -> {rev}")
                else:
                    # unknown command; no defined behavior
                    pass
    finally:
        try:
            sock.close()
        except OSError:
            pass

def main():
    urls = sys.argv[1:]
    for i, url in enumerate(urls, 1):
        try:
            handle_session(url, i)
        except Exception:
            pass

if __name__ == '__main__':
    main()

