import * as net from 'net';
import * as crypto from 'crypto';

class Reader {
  buf: Buffer = Buffer.alloc(0);
  private waiter: { n: number; resolve: (b: Buffer) => void } | null = null;
  private eof = false;

  constructor(sock: net.Socket) {
    sock.on('data', (d: Buffer) => {
      this.buf = Buffer.concat([this.buf, d]);
      this.tryResolve();
    });
    const end = () => {
      this.eof = true;
      this.tryResolve();
    };
    sock.on('error', end);
    sock.on('close', end);
  }

  private tryResolve() {
    if (this.waiter && (this.eof || this.buf.length >= this.waiter.n)) {
      const w = this.waiter;
      this.waiter = null;
      if (this.eof && this.buf.length < w.n) {
        w.resolve(Buffer.alloc(0));
      } else {
        const b = Buffer.from(this.buf.subarray(0, w.n));
        this.buf = this.buf.subarray(w.n);
        w.resolve(b);
      }
    }
  }

  read(n: number): Promise<Buffer> {
    return new Promise((res) => {
      this.waiter = { n, resolve: res };
      this.tryResolve();
    });
  }
}

function makeMask(): Buffer {
  let m = crypto.randomBytes(4);
  while (m[0] === 0 && m[1] === 0 && m[2] === 0 && m[3] === 0) {
    m = crypto.randomBytes(4);
  }
  return m;
}

function sendFrame(sock: net.Socket, opcode: number, payload: Buffer) {
  const mask = makeMask();
  const len = payload.length;
  let header: Buffer;
  if (len < 126) {
    header = Buffer.from([0x80 | opcode, 0x80 | len]);
  } else if (len <= 0xffff) {
    header = Buffer.alloc(4);
    header[0] = 0x80 | opcode;
    header[1] = 0x80 | 126;
    header.writeUInt16BE(len, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = 0x80 | opcode;
    header[1] = 0x80 | 127;
    header.writeBigUInt64BE(BigInt(len), 2);
  }
  const masked = Buffer.from(payload);
  for (let i = 0; i < len; i++) masked[i] ^= mask[i & 3];
  sock.write(Buffer.concat([header, mask, masked]));
}

function closePayload(code: number): Buffer {
  const b = Buffer.alloc(2);
  b.writeUInt16BE(code, 0);
  return b;
}

async function session(urlStr: string): Promise<void> {
  const u = new URL(urlStr);
  const port = u.port ? Number(u.port) : 80;
  const target = u.pathname + u.search;
  const key = crypto.randomBytes(16).toString('base64');

  const req =
    `GET ${target} HTTP/1.1\r\n` +
    `Host: ${u.hostname}:${port}\r\n` +
    `Upgrade: websocket\r\n` +
    `Connection: Upgrade\r\n` +
    `Sec-WebSocket-Version: 13\r\n` +
    `Sec-WebSocket-Key: ${key}\r\n` +
    `\r\n`;

  const sock = net.connect(port, u.hostname);
  const reader = new Reader(sock);

  await new Promise<void>((res) => {
    const done = () => {
      sock.removeListener('connect', ok);
      sock.removeListener('error', fail);
      res();
    };
    const ok = () => done();
    const fail = () => done();
    sock.once('connect', ok);
    sock.once('error', fail);
  });
  if (!sock.readable && !sock.writable) {
    sock.destroy();
    return;
  }

  sock.write(req);

  // Read header block
  let head = Buffer.alloc(0);
  for (;;) {
    const b = await reader.read(1);
    if (b.length === 0) {
      sock.destroy();
      return;
    }
    head = Buffer.concat([head, b]);
    if (head.length >= 4 && head.toString('binary', head.length - 4).includes('\r\n\r\n')) break;
  }
  const s = head.toString('binary');
  const idx = s.indexOf('\r\n\r\n');
  const headerBlock = s.slice(0, idx);
  // any bytes past the header block remain in reader.buf

  const lines = headerBlock.split('\r\n');
  const statusLine = lines[0];
  const code = parseInt(statusLine.split(' ')[1], 10);
  if (code !== 101) {
    console.log('handshake failed: ' + statusLine.slice(statusLine.indexOf(' ') + 1));
    sock.destroy();
    return;
  }
  let acceptVal: string | null = null;
  for (const l of lines.slice(1)) {
    const ci = l.indexOf(':');
    if (ci > 0 && l.slice(0, ci).trim().toLowerCase() === 'sec-websocket-accept') {
      acceptVal = l.slice(ci + 1).trim();
    }
  }
  const expected = crypto
    .createHash('sha1')
    .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');
  if (acceptVal !== expected) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    sock.destroy();
    return;
  }

  let sentClose = false;
  let pending: { opcode: number; chunks: Buffer[] } | null = null;
  let awaitingBinary = false;

  const handleMessage = (opcode: number, full: Buffer) => {
    if (awaitingBinary) {
      awaitingBinary = false;
      const hex = crypto.createHash('sha1').update(full).digest('hex');
      console.log(`SHA1 ${full.length} -> ${hex}`);
      sendFrame(sock, 0x1, Buffer.from(hex, 'utf8'));
      return;
    }
    if (opcode !== 1) return;
    const text = full.toString('utf8');
    if (text === 'SHA1') {
      awaitingBinary = true;
    } else if (text === 'BYE') {
      sendFrame(sock, 0x8, closePayload(1000));
      sentClose = true;
    } else if (text.startsWith('ADD ')) {
