      console.log(`${text} -> ${sum}`);
    } else if (text.startsWith('REV ')) {
      const t = text.slice(4);
      const rev = [...t].reverse().join('');
      sendFrame(sock, 0x1, Buffer.from(rev, 'utf8'));
      console.log(`${text} -> ${rev}`);
    }
  };

  for (;;) {
    const h = await reader.read(2);
    if (h.length < 2) break;
    const fin = (h[0] & 0x80) !== 0;
    const opcode = h[0] & 0x0f;
    const masked = (h[1] & 0x80) !== 0;
