      if (b.length < 2) break;
      len = b.readUInt16BE(0);
    } else if (len === 127) {
      const b = await reader.read(8);
      if (b.length < 8) break;
      len = Number(b.readBigUInt64BE(0));
    }
    let maskBuf = Buffer.alloc(0);
    if (masked) {
      maskBuf = await reader.read(4);
      if (maskBuf.length < 4) break;
    }
    const payload = await reader.read(len);
    if (payload.length < len) break;
    if (masked) {
      for (let i = 0; i < payload.length; i++) payload[i] ^= maskBuf[i & 3];
    }

