import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

public class Main {
    static long[] trans;
    static int[] tidx, toff;
    static String[] tabbr;

    static boolean footer = false;
    static String stdAbbr, dstAbbr;
    static long stdWritten, dstWritten, stdUtc, dstUtc;
    static boolean hasDst = false;
    static int[] startR = new int[4], endR = new int[4];

    static class Res {
        int off; String abbr;
        Res(int o, String a) { off = o; abbr = a; }
    }

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        List<String> lines = Files.readAllLines(dir.resolve("queries.txt"));
        StringBuilder sb = new StringBuilder();
        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] f = line.split(" ");
            load(dir.resolve(f[1]));
            if (f[0].equals("UTC")) {
                long t = Long.parseLong(f[2]);
                Res r = localOf(t);
                sb.append(line).append(" -> ").append(fmtLocal(t, r.off))
                  .append(fmtOff(r.off)).append(' ').append(r.abbr).append('\n');
            } else {
                LocalDateTime W = LocalDateTime.parse(f[2]);
                long w = W.toEpochSecond(ZoneOffset.UTC);
                TreeSet<Long> cands = new TreeSet<>();
                for (int off : toff) cands.add(w - off);
                if (footer) {
                    cands.add(w - stdUtc);
                    if (hasDst) cands.add(w - dstUtc);
                }
                List<Long> valid = new ArrayList<>();
                for (long t : cands) {
                    Res r = localOf(t);
                    if (t + r.off == w) valid.add(t);
                }
                if (!valid.isEmpty()) {
                    sb.append(line).append(" -> ");
                    for (int i = 0; i < valid.size(); i++) {
                        long t = valid.get(i);
                        Res r = localOf(t);
                        if (i > 0) sb.append(" | ");
                        sb.append(t).append(' ').append(fmtOff(r.off)).append(' ').append(r.abbr);
                    }
                    sb.append('\n');
                } else {
                    long t = findGap(w);
                    Res r = localOf(t);
                    sb.append(line).append(" -> GAP ").append(t).append(' ')
                      .append(fmtLocal(t, r.off)).append(fmtOff(r.off)).append(' ').append(r.abbr).append('\n');
                }
            }
        }
        System.out.print(sb);
    }

    static void load(Path p) throws IOException {
        byte[] b = Files.readAllBytes(p);
        ByteBuffer buf = ByteBuffer.wrap(b);
        int pos = 20;
        int isut1 = buf.getInt(pos), isstd1 = buf.getInt(pos + 4), leap1 = buf.getInt(pos + 8);
        int tc1 = buf.getInt(pos + 12), ty1 = buf.getInt(pos + 16), ch1 = buf.getInt(pos + 20);
        pos = 44 + tc1 * 5 + ty1 * 6 + ch1 + leap1 * 8 + isstd1 + isut1;
        pos += 20;
        int isut = buf.getInt(pos), isstd = buf.getInt(pos + 4), leap = buf.getInt(pos + 8);
        int tc = buf.getInt(pos + 12), ty = buf.getInt(pos + 16), ch = buf.getInt(pos + 20);
        pos += 24;
        trans = new long[tc];
        for (int i = 0; i < tc; i++) trans[i] = buf.getLong(pos + 8L * i);
        pos += 8L * tc;
        tidx = new int[tc];
        for (int i = 0; i < tc; i++) tidx[i] = b[pos + i] & 0xff;
        pos += tc;
        int charsStart = pos + 6 * ty;
        toff = new int[ty];
        tabbr = new String[ty];
        for (int i = 0; i < ty; i++) {
            toff[i] = buf.getInt(pos);
            int ai = (b[pos + 5] & 0xff) + charsStart;
            int e = ai;
            while (b[e] != 0) e++;
            tabbr[i] = new String(b, ai, e - ai, StandardCharsets.US_ASCII);
            pos += 6;
        }
        pos += ch + leap * 12 + isstd + isut;
        int e2 = pos + 1;
        while (b[e2] != '\n') e2++;
        String tz = new String(b, pos + 1, e2 - pos - 1, StandardCharsets.US_ASCII);
        if (!tz.isEmpty()) {
            footer = true;
            parseFooter(tz);
        } else {
            footer = false;
        }
    }

    static void parseFooter(String s) {
        int[] p = {0};
        stdAbbr = parseName(s, p);
        stdWritten = parseOffset(s, p);
        stdUtc = -stdWritten;
        hasDst = false;
        if (p[0] < s.length() && s.charAt(p[0]) != ',') {
            dstAbbr = parseName(s, p);
            if (p[0] < s.length() && s.charAt(p[0]) != ',') {
                dstWritten = parseOffset(s, p);
            } else {
                dstWritten = stdWritten + 3600;
            }
            dstUtc = -dstWritten;
            if (p[0] < s.length() && s.charAt(p[0]) == ',') {
                hasDst = true;
                p[0]++;
                parseRule(s, p, startR);
                p[0]++;
                parseRule(s, p, endR);
            }
        }
    }

    static String parseName(String s, int[] p) {
        if (s.charAt(p[0]) == '<') {
            int e = s.indexOf('>', p[0]);
            String r = s.substring(p[0] + 1, e);
            p[0] = e + 1;
            return r;
        } else {
            int st = p[0];
            while (p[0] < s.length() && Character.isLetter(s.charAt(p[0]))) p[0]++;
            return s.substring(st, p[0]);
        }
    }

    static long parseOffset(String s, int[] p) {
        int sign = 1;
        if (s.charAt(p[0]) == '+') p[0]++;
        else if (s.charAt(p[0]) == '-') { sign = -1; p[0]++; }
        long h = num(s, p), m = 0, sec = 0;
        if (p[0] < s.length() && s.charAt(p[0]) == ':') {
            p[0]++;
            m = num(s, p);
            if (p[0] < s.length() && s.charAt(p[0]) == ':') {
                p[0]++;
                sec = num(s, p);
            }
        }
        return sign * (h * 3600 + m * 60 + sec);
    }

    static long num(String s, int[] p) {
        int st = p[0];
        while (p[0] < s.length() && Character.isDigit(s.charAt(p[0]))) p[0]++;
        return Long.parseLong(s.substring(st, p[0]));
    }

    static void parseRule(String s, int[] p, int[] r) {
        p[0]++;
        r[0] = (int) num(s, p);
        p[0]++;
        r[1] = (int) num(s, p);
        p[0]++;
        r[2] = (int) num(s, p);
        r[3] = 7200;
        if (p[0] < s.length() && s.charAt(p[0]) == '/') {
            p[0]++;
            r[3] = (int) parseOffset(s, p);
        }
    }

    static LocalDate ruleDate(int year, int m, int w, int d) {
        if (w == 5) {
            LocalDate first = LocalDate.of(year, m, 1);
            LocalDate last = first.withDayOfMonth(first.lengthOfMonth());
            int dow = last.getDayOfWeek().getValue() % 7;
            return last.minusDays((dow - d + 7) % 7);
        }
        LocalDate first = LocalDate.of(year, m, 1);
        int dow = first.getDayOfWeek().getValue() % 7;
        return first.plusDays(7L * (w - 1) + (d - dow + 7) % 7);
    }

    static long ruleUtc(int year, int[] r, long writtenOff) {
        LocalDate d = ruleDate(year, r[0], r[1], r[2]);
        LocalDateTime ldt = d.atStartOfDay().plusSeconds(r[3]);
        return ldt.toEpochSecond(ZoneOffset.UTC) - writtenOff;
    }

    static boolean dstActive(long t) {
        int Y = LocalDateTime.ofEpochSecond(t + stdUtc, 0, ZoneOffset.UTC).getYear();
        for (int y = Y - 1; y <= Y + 1; y++) {
            long s = ruleUtc(y, startR, stdWritten);
            long eSame = ruleUtc(y, endR, dstWritten);
            long e = (s <= eSame) ? eSame : ruleUtc(y + 1, endR, dstWritten);
            if (t >= s && t < e) return true;
        }
        return false;
    }

    static int floorIdx(long t) {
        int lo = 0, hi = trans.length - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (trans[mid] <= t) { ans = mid; lo = mid + 1; } else hi = mid - 1;
        }
        return ans;
    }

    static Res localOf(long t) {
        if (footer && (trans.length == 0 || t > trans[trans.length - 1])) {
            if (hasDst && dstActive(t)) return new Res((int) dstUtc, dstAbbr);
            return new Res((int) stdUtc, stdAbbr);
        }
        int ti = 0;
        if (trans.length > 0 && t >= trans[0]) ti = tidx[floorIdx(t)];
        return new Res(toff[ti], tabbr[ti]);
    }

    static long findGap(long w) {
        for (int j = 0; j < trans.length; j++) {
            long oBefore = (j == 0) ? toff[0] : toff[tidx[j - 1]];
            long oAfter = toff[tidx[j]];
            if (oAfter > oBefore && w >= trans[j] + oBefore && w < trans[j] + oAfter) {
                return w - oBefore;
            }
        }
        int Y = LocalDateTime.ofEpochSecond(w, 0, ZoneOffset.UTC).getYear();
        for (int y = Y - 2; y <= Y + 2; y++) {
            long s = ruleUtc(y, startR, stdWritten);
            if (dstUtc > stdUtc && w >= s + stdUtc && w < s + dstUtc) return w - stdUtc;
        }
        return w;
    }

    static DateTimeFormatter F = DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss");

    static String fmtLocal(long t, int off) {
        return LocalDateTime.ofEpochSecond(t + off, 0, ZoneOffset.UTC).format(F);
    }

    static String fmtOff(long off) {
        String sign = off < 0 ? "-" : "+";
        long a = Math.abs(off);
        long h = a / 3600, m = (a % 3600) / 60, s = a % 60;
        StringBuilder sb = new StringBuilder(sign);
        sb.append(String.format("%02d:%02d", h, m));
        if (s != 0) sb.append(String.format(":%02d", s));
        return sb.toString();
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

typedef int64_t i64;
typedef int32_t i32;

static i64 *trans = NULL;
static unsigned char *tidx = NULL;
static i32 *toff = NULL;
static unsigned char *tabbind = NULL;
static char *abbrs = NULL;
static int nt = 0, ntype = 0;

static char std_abbr[64] = "", dst_abbr[64] = "";
static i64 std_parsed = 0, dst_parsed = 0;
static int has_dst = 0, has_rules = 0;
static int r1m, r1w, r1d; static i64 r1t;
static int r2m, r2w, r2d; static i64 r2t;

static i64 fdiv_(i64 a, i64 b){ i64 q=a/b, r=a%b; if(r && ((r<0)!=(b<0))) q--; return q; }
static i64 fmod_(i64 a, i64 b){ i64 r=a%b; if(r && ((r<0)!=(b<0))) r+=b; return r; }

static i64 days_from_civil(int y, unsigned m, unsigned d){
    y -= m <= 2;
    i64 era = (y >= 0 ? y : y - 399) / 400;
    unsigned yoe = (unsigned)(y - era*400);
    unsigned doy = (153*(m + (m > 2 ? -3 : 9)) + 2)/5 + d - 1;
    unsigned doe = yoe*365 + yoe/4 - yoe/100 + doy;
    return era*146097 + doe - 719468;
}
static void civil_from_days(i64 z, int *y, unsigned *m, unsigned *d){
    z += 719468;
    i64 era = (z >= 0 ? z : z - 146096) / 146097;
    unsigned doe = (unsigned)(z - era*146097);
    unsigned yoe = (doe - doe/1460 + doe/36524 - doe/146096)/365;
    i64 yy = (i64)yoe + era*400;
    unsigned doy = doe - (365*yoe + yoe/4 - yoe/100);
    unsigned mp = (5*doy + 2)/153;
    unsigned dd = doy - (153*mp + 2)/5 + 1;
    unsigned mm = mp + (mp < 10 ? 3 : -9);
    *y = (int)(yy + (mm <= 2)); *m = mm; *d = dd;
}
static int dow_(i64 z){ return (int)(((z + 4) % 7 + 7) % 7); } /* 0=Sunday */

static i64 mwd_day(int y, int m, int w, int d){
    i64 first = days_from_civil(y, (unsigned)m, 1);
    if(w == 5){
        i64 last = (m == 12) ? days_from_civil(y+1,1,1)-1 : days_from_civil(y,(unsigned)m+1,1)-1;
        return last - (((dow_(last) - d) % 7 + 7) % 7);
    }
    int d1 = dow_(first);
    int day = 1 + (d - d1 + 7) % 7 + 7*(w-1);
    return first + day - 1;
}

static i64 parse_num(const char **pp){
    i64 v = 0;
    while(isdigit((unsigned char)**pp)){ v = v*10 + (**pp - '0'); (*pp)++; }
    return v;
}
static i64 parse_off(const char **pp){
    const char *s = *pp;
    int sign = 1;
    if(*s == '+' || *s == '-'){ if(*s=='-') sign = -1; s++; }
    i64 h = parse_num(&s);
    i64 m = 0, sec = 0;
    if(*s == ':'){
        s++;
        m = parse_num(&s);
        if(*s == ':'){ s++; sec = parse_num(&s); }
    }
    *pp = s;
    return sign*(h*3600 + m*60 + sec);
}
static void parse_rule(const char **pp, int *m, int *w, int *d, i64 *t){
    const char *s = *pp;
    if(*s == 'M') s++;
    *m = (int)parse_num(&s);
    if(*s == '.') s++;
    *w = (int)parse_num(&s);
    if(*s == '.') s++;
    *d = (int)parse_num(&s);
    *t = 7200;
    if(*s == '/'){ s++; *t = parse_off(&s); }
    *pp = s;
}
static void parse_tz(char *s){
    if(*s == '<'){
        s++; int i = 0;
        while(*s && *s != '>' && i < 63) std_abbr[i++] = *s++;
        std_abbr[i] = 0;
        if(*s == '>') s++;
    } else {
        int i = 0;
        while(isalpha((unsigned char)*s) && i < 63) std_abbr[i++] = *s++;
        std_abbr[i] = 0;
    }
    std_parsed = parse_off((const char**)&s);
    if(*s && *s != ','){
        if(*s == '<'){
            s++; int i = 0;
            while(*s && *s != '>' && i < 63) dst_abbr[i++] = *s++;
            dst_abbr[i] = 0;
            if(*s == '>') s++;
        } else {
            int i = 0;
            while(isalpha((unsigned char)*s) && i < 63) dst_abbr[i++] = *s++;
            dst_abbr[i] = 0;
        }
        has_dst = 1;
        if(*s && *s != ',') dst_parsed = parse_off((const char**)&s);
        else dst_parsed = std_parsed - 3600;
    }
    if(*s == ','){
        s++;
        has_rules = 1;
        parse_rule((const char**)&s, &r1m, &r1w, &r1d, &r1t);
        if(*s == ','){ s++; parse_rule((const char**)&s, &r2m, &r2w, &r2d, &r2t); }
    }
}

static i32 be32(const unsigned char *p){
    uint32_t u = ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|(uint32_t)p[3];
    return (i32)u;
}
static i64 be64(const unsigned char *p){
    uint64_t u = 0;
    for(int i = 0; i < 8; i++) u = (u<<8) | p[i];
    return (i64)u;
}

static unsigned char *readall(const char *path, long *len){
    FILE *f = fopen(path, "rb");
    if(!f){ fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *b = malloc((size_t)n + 1);
    if(fread(b, 1, (size_t)n, f) != (size_t)n){ fprintf(stderr, "read error\n"); exit(1); }
    fclose(f);
    *len = n;
    return b;
}

static void load_tz(const char *dir, const char *name){
    char path[4096];
    snprintf(path, sizeof path, "%s/%s", dir, name);
    long len;
    unsigned char *b = readall(path, &len);
    if(len < 44 || memcmp(b, "TZif", 4)){ fprintf(stderr, "bad file\n"); exit(1); }
    const unsigned char *h = b + 20;
    i64 c0 = be32(h), c1 = be32(h+4), c2 = be32(h+8), c3 = be32(h+12), c4 = be32(h+16), c5 = be32(h+20);
    long v1sz = (long)(c3*5 + c4*6 + c5 + c2*8 + c1 + c0);
    long pos = 44 + v1sz;
    if(pos + 44 > len || memcmp(b + pos, "TZif", 4)){ fprintf(stderr, "bad v2 header\n"); exit(1); }
    const unsigned char *h2 = b + pos + 20;
    i64 isut = be32(h2), isstd = be32(h2+4), leap = be32(h2+8);
    nt = (int)be32(h2+12);
    ntype = (int)be32(h2+16);
    long charcnt = be32(h2+20);
    pos += 44;

    free(trans); free(tidx); free(toff); free(tabbind); free(abbrs);
    trans = malloc(sizeof(i64) * (size_t)(nt > 0 ? nt : 1));
    tidx = malloc((size_t)(nt > 0 ? nt : 1));
    for(int i = 0; i < nt; i++) trans[i] = be64(b + pos + 8*i);
    pos += (long)nt * 8;
    memcpy(tidx, b + pos, (size_t)nt);
    pos += nt;

    toff = malloc(sizeof(i32) * (size_t)(ntype > 0 ? ntype : 1));
    tabbind = malloc((size_t)(ntype > 0 ? ntype : 1));
    for(int i = 0; i < ntype; i++){
        toff[i] = be32(b + pos + 6*i);
        tabbind[i] = b[pos + 6*i + 5];
    }
    pos += (long)ntype * 6;

    abbrs = malloc((size_t)charcnt + 1);
    memcpy(abbrs, b + pos, (size_t)charcnt);
    abbrs[charcnt] = 0;
    pos += charcnt;
    pos += leap * 12 + isstd + isut;

    if(pos < len && b[pos] == '\n') pos++;
    char foot[256];
    int i = 0;
    while(pos + i < len && b[pos+i] != '\n' && i < 255){ foot[i] = (char)b[pos+i]; i++; }
    foot[i] = 0;
    parse_tz(foot);
    free(b);
}

static i64 offset_of(int idx){
    if(idx >= 0) return toff[idx];
    return idx == -1 ? -std_parsed : -dst_parsed;
}
static const char *abbr_of(int idx){
    if(idx >= 0) return abbrs + tabbind[idx];
    return idx == -1 ? std_abbr : dst_abbr;
}

static int dst_active(i64 t){
    if(!has_dst || !has_rules) return 0;
    i64 d = fdiv_(t - std_parsed, 86400); /* t + std_utc */
    int y; unsigned m, dd;
    civil_from_days(d, &y, &m, &dd);
    for(int yy = y-1; yy <= y+1; yy++){
        i64 start = mwd_day(yy, r1m, r1w, r1d)*86400 + r1t + std_parsed;
        i64 end   = mwd_day(yy, r2m, r2w, r2d)*86400 + r2t + dst_parsed;
        if(start < end){ if(t >= start && t < end) return 1; }
        else if(start > end){ if(t >= start || t < end) return 1; }
    }
    return 0;
}

static int gettype(i64 t){
    if(nt == 0 || t < trans[0]) return 0;
    if(t <= trans[nt-1]){
        int lo = 0, hi = nt - 1;
        while(lo < hi){
            int mid = (lo + hi + 1) / 2;
            if(trans[mid] <= t) lo = mid; else hi = mid - 1;
        }
        return tidx[lo];
    }
    if(has_dst && has_rules && dst_active(t)) return -2;
    return -1;
}

static void fmt_off(i64 off, char *out){
    const char *sg = off < 0 ? "-" : "+";
    i64 a = off < 0 ? -off : off;
    int h = (int)(a/3600), m = (int)((a%3600)/60), s = (int)(a%60);
    if(s) sprintf(out, "%s%02d:%02d:%02d", sg, h, m, s);
    else sprintf(out, "%s%02d:%02d", sg, h, m);
}

static void fmt_local(i64 t, char *out){
    int idx = gettype(t);
    i64 off = offset_of(idx);
    i64 tot = t + off;
    i64 d = fdiv_(tot, 86400);
    i64 s = fmod_(tot, 86400);
    int y; unsigned mo, da;
    civil_from_days(d, &y, &mo, &da);
    int hh = (int)(s/3600), mi = (int)((s%3600)/60), ss = (int)(s%60);
    char os[32];
    fmt_off(off, os);
    sprintf(out, "%04d-%02u-%02uT%02d:%02d:%02d%s", y, mo, da, hh, mi, ss, os);
}

static int cmp_i64(const void *a, const void *b){
    i64 x = *(const i64*)a, y = *(const i64*)b;
    return x < y ? -1 : (x > y ? 1 : 0);
}

int main(int argc, char **argv){
    const char *dir = argc > 1 ? argv[1] : ".";
    char qpath[4096];
    snprintf(qpath, sizeof qpath, "%s/queries.txt", dir);
    FILE *f = fopen(qpath, "r");
    if(!f){ fprintf(stderr, "cannot open queries.txt\n"); return 1; }
    char line[8192];
    while(fgets(line, sizeof line, f)){
        line[strcspn(line, "\r\n")] = 0;
        char *p = line;
        while(isspace((unsigned char)*p)) p++;
        if(!*p) continue;
        char op[16], fname[4096], arg[128];
        if(sscanf(line, "%15s %4095s %127s", op, fname, arg) != 3) continue;
        load_tz(dir, fname);
        if(strcmp(op, "UTC") == 0){
            i64 t = strtoll(arg, NULL, 10);
            char loc[64];
            fmt_local(t, loc);
            printf("%s -> %s %s\n", line, loc, abbr_of(gettype(t)));
        } else {
            int Y, Mo, D, hh, mi, ss;
            sscanf(arg, "%d-%d-%dT%d:%d:%d", &Y, &Mo, &D, &hh, &mi, &ss);
            i64 W = days_from_civil(Y, (unsigned)Mo, (unsigned)D)*86400 + hh*3600 + mi*60 + ss;
            i64 offs[512];
            int no = 0;
            for(int i = 0; i < ntype; i++){
                i64 o = toff[i];
                int dup = 0;
                for(int j = 0; j < no; j++) if(offs[j] == o){ dup = 1; break; }
                if(!dup && no < 512) offs[no++] = o;
            }
            i64 so = -std_parsed;
            int dup = 0;
            for(int j = 0; j < no; j++) if(offs[j] == so){ dup = 1; break; }
            if(!dup && no < 512) offs[no++] = so;
            if(has_dst && has_rules){
                i64 dvo = -dst_parsed;
                dup = 0;
                for(int j = 0; j < no; j++) if(offs[j] == dvo){ dup = 1; break; }
                if(!dup && no < 512) offs[no++] = dvo;
            }
            i64 cands[16];
            int nc = 0;
            for(int j = 0; j < no; j++){
                i64 t = W - offs[j];
                int idx = gettype(t);
                if(t + offset_of(idx) == W){
                    int d2 = 0;
                    for(int k = 0; k < nc; k++) if(cands[k] == t){ d2 = 1; break; }
                    if(!d2 && nc < 16) cands[nc++] = t;
                }
            }
            if(nc >= 1){
                qsort(cands, (size_t)nc, sizeof(i64), cmp_i64);
                printf("%s ->", line);
                for(int k = 0; k < nc; k++){
                    i64 t = cands[k];
                    int idx = gettype(t);
                    char os[32];
                    fmt_off(offset_of(idx), os);
                    printf("%s %lld %s %s", k == 0 ? "" : " |", (long long)t, os, abbr_of(idx));
                }
                printf("\n");
            } else {
                i64 gt = 0;
                int found = 0;
                for(int i = 0; i < nt && !found; i++){
                    i64 T = trans[i];
                    i64 ob = (i == 0) ? toff[0] : toff[tidx[i-1]];
                    i64 oa = toff[tidx[i]];
                    if(oa > ob && T + ob <= W && W < T + oa){ gt = W - ob; found = 1; }
                }
                if(!found && has_dst && has_rules){
                    for(int yy = Y-1; yy <= Y+1 && !found; yy++){
                        i64 Ts = mwd_day(yy, r1m, r1w, r1d)*86400 + r1t + std_parsed;
                        i64 ob = -std_parsed, oa = -dst_parsed;
                        if(oa > ob && Ts + ob <= W && W < Ts + oa){ gt = W - ob; found = 1; break; }
                        i64 Te = mwd_day(yy, r2m, r2w, r2d)*86400 + r2t + dst_parsed;
                        i64 ob2 = -dst_parsed, oa2 = -std_parsed;
                        if(oa2 > ob2 && Te + ob2 <= W && W < Te + oa2){ gt = W - ob2; found = 1; break; }
                    }
                }
                if(found){
                    char loc[64];
                    fmt_local(gt, loc);
                    printf("%s -> GAP %lld %s %s\n", line, (long long)gt, loc, abbr_of(gettype(gt)));
                }
            }
        }
    }
    fclose(f);
    return 0;
}
